do
    local src = ReplicatedStorage:WaitForChild("src", 60)
    Core.Loader = require(src:WaitForChild("Loader"))
    Core.Util = require(src:WaitForChild("Util"))
    local now = Utils.now()
    while App.alive and Utils.now() - now < 90 do
        local ok, res = pcall(Core.Loader.load_client_service, nil, "GUIService")
        if ok and type(res) == "table" and res.session and res.session._initialized then
            break
        end
        task.wait(0.5)
    end
end

