Core.LU = Core.core("LevelUtil") or (function()
    local list = {
        1,
        1.524259,
        2.3760452,
        3.7038265,
        5.7735984,
        9.9,
        13.6269783,
        16.313749,
        21.4345692,
        21.4345692,
        56.325588,
        84.488382,
        84.488382,
        168.976764,
        253.465146,
        337.953528,
        375,
        400,
        450,
        500,
        550,
        650
    }
    local list2 = {
        1,
        1.0447,
        1.09139809,
        1.1401835846,
        1.1911497909,
        1.3366844723
    }
    local info = {
        hxhant = 0.5,
        magnolia = 0.6,
        jjk = 0.7
    }
    local list3 = {
    }
    function list3.calculate_level_diff_scale(arg1, arg2, arg3)
        if arg3 and (arg3._use_max or arg3._is_daily_challenge or arg3._is_event_challenge) then
            return list2 [6]
        end
        if arg2 == "story" or arg2 == "challenge" then
            return list2 [arg1 or 6] or list2 [6]
        end
        return list2 [6]
    end
    function list3.calculate_world_diff_scale(arg1, arg2, _arg3, arg4, arg5)
        local item = list [# list] * 1.5
        if arg5 and arg5._is_event_challenge then
            return 0.5 * item
        end
        if arg5 and (arg5._use_max or arg5._is_daily_challenge) then
            return item
        end
        local item = list [arg1 or # list] or list [# list]
        if arg2 == "story" or arg2 == "raid" then
            item = item * ((arg1 or # list) < 12 and 0.6 or 0.7)
        end
        return item * 1.5 * (info [arg4] or 1)
    end
    function list3.calculate_world_resource_scale(arg1, arg2)
        local num = 1.7411011266
        if arg1 and arg1 <= 5 and (arg2 == "story" or arg2 == "infinite" or arg2 == "challenge") then
            num = ({
                1,
                1.148698355,
                1.3195079108,
                1.5157165665,
                1.7411011266
            }) [arg1]
        end
        return num * 1.5
    end
    function list3.calculate_multiplayer_diff_scale(arg1, arg2, arg3)
        if arg3._event_contract then
            return 1
        end
        if arg3._override_multiplayer_diff_scale then
            return 1 + (arg2 - 1) * arg3._override_multiplayer_diff_scale
        end
        if arg3._is_daily_challenge then
            return 4
        end
        if arg3._is_event_challenge or arg3._no_multiplayer_scale then
            return 1
        end
        if arg1 == "story" or arg1 == "challenge" or arg1 == "infinite" or arg1 == "infinite_tower" then
            return 1 + (arg2 - 1) * (arg3.world == "bleach_legend" and 1 / 6 or (arg3.world == "jojo_legend" and 0.3 or 0.6))
        end
        if arg1 == "raid" then
            if arg3.id == "jojo_portal_pucci" then
                return 0.3
            end
            if arg3.portal_group or arg3._raid_multiplayer_scale then
                return 1 + (arg2 - 1) * 0.3
            end
            return arg3.id ~= "namek_anniversary" and 8 or 8 * (1 + (arg2 - 1) * 0.5)
        end
        return 1
    end
    local info = {
        opm_infinite = 0.8,
        jojo_infinite = 0.7,
        sao_infinite = 0.7,
        berserk_infinite = 0.7,
        overlord_infinite = 0.7,
        fate_infinite = 0.7
    }
    list3.Infinite = {
        infinite_max_unit_wave = 100,
        initial_wave_template = {
            wave_reward = 1500,
            wave_diff_scale = 1
        },
        infinite_diff_scale = function(arg1,
            arg2)
            local exp
            if arg1 <= 20 then
                exp = math.exp(0.165 * arg1) * 0.257116 + 0.187431
            elseif arg1 <= 50 then
                if arg2 == "april2_event" then
                    exp = math.pow(arg1 - 1,
                    2.9) / 500 + 2
                elseif arg2 == "halloween2_event" or arg2 == "christmas_event" then
                    exp = math.pow(arg1 - 1,
                    2.4) / 400 + 4.2
                else
                    exp = math.pow(arg1 - 1,
                    2.48) / 400 + 4.2
                end
            else
                exp = math.max(32,
                math.pow(arg1 - 1,
                2.8) / 400 - 92)
            end
            if info [arg2] then
                return exp * info [arg2]
            end
            if arg2 == "halloween2_event" or arg2 == "christmas_event" or arg2 == "april2_event" then
                exp = exp * 0.85
                if arg2 == "christmas_event" then
                    exp = exp * 0.75
                end
            end
            return exp
        end,
        infinite_amt_scale = function(arg1,
            arg2)
            local value
            if arg1 <= 1 then
                value = 3
            elseif arg1 < 9 then
                value = math.pow(arg1 - 1,
                2) / 5 + 5
            else
                value = math.pow(arg1 - 1,
                1.4) / 5 + 15
            end
            if arg2 and arg2._tournament and arg2._tournament.tournament_id == "3" then
                value = math.min(value / 3,
                5)
            end
            return math.min(value,
            60)
        end,
        infinite_get_normal_unit_chance = function(arg1,
            arg2)
            if arg1.min_inf_wave and arg2 < arg1.min_inf_wave then
                return 0
            end
            local spawnTierNormal = arg1.spawn_tier_normal
            if not spawnTierNormal then
                return 0
            end
            local ratio = math.min(arg2 - 1,
            100) / 100
            local value,
            value2
            if spawnTierNormal <= 2 then
                value,
                value2 = 5,
                5
            elseif spawnTierNormal == 3 then
                value,
                value2 = 3,
                6
            elseif spawnTierNormal == 4 then
                value,
                value2 = 1,
                6
            elseif spawnTierNormal <= 7 then
                value,
                value2 = 0,
                5
            else
                value,
                value2 = 0,
                2
            end
            return value + (value2 - value) * ratio
        end,
        infinite_get_boss_unit_chance = function(arg1,
            arg2)
            if arg1.min_inf_wave and arg2 < arg1.min_inf_wave then
                return 0
            end
            if arg2 <= 10 then
                return arg1.spawn_tier_boss == 1 and 1 or 0
            end
            return arg1.spawn_tier_boss and 1 or 0
        end
    }
    local core = Core.core("LevelUtilCore")
    list3.xp_items_order = core and core.xp_items_order
    return list3
end)()
