function Core.session()
    return Core.GUIS and Core.GUIS.session
end

function Core.prof()
    local session = Core.session()
    return session and session.profile_data
end

function Core.cur(arg1)
    local stats = LocalPlayer:FindFirstChild("_stats")
    local findFirstChild = stats and ((arg1 == "gems" and stats:FindFirstChild("gem_amount")) or (arg1 == "gold" and stats:FindFirstChild("gold_amount")) or stats:FindFirstChild("_resource" .. arg1))
    if findFirstChild then
        return tonumber(findFirstChild.Value) or 0
    end
    local prof = Core.prof()
    if arg1 == "gems" then
        return tonumber(prof and prof.gem_amount) or 0
    end
    if arg1 == "gold" then
        return tonumber(prof and prof.gold_amount) or 0
    end
    return tonumber(prof and prof.resources and prof.resources [arg1]) or 0
end
App.where = (workspace:FindFirstChild("_MAP_CONFIG") and workspace._MAP_CONFIG:FindFirstChild("IsLobby") and workspace._MAP_CONFIG.IsLobby.Value) and "lobby" or "match"
App.req = {
    back = {
    },
    fails = {
    },
    calls = {
    }
}
App.BUDGET = {
    upg = 30,
    place = 15
}

function App.request(arg1, arg2, ...)
    local req = App.req
    local now = Utils.now()
    if req.back [arg1] and now < req.back [arg1] then
        return false, "waiting"
    end
    local call = req.calls [arg1] or {
    }
    req.calls [arg1] = call
    while call [1] and now - call [1] > 10 do
        table.remove(call, 1)
    end
    if # call >= (App.BUDGET [arg1] or 8) then
        req.back [arg1] = now + 3
        return false, "slowing down"
    end
    table.insert(call, now)
    if not (ReplicatedStorage:FindFirstChild("endpoints") and ReplicatedStorage.endpoints.client_to_server:FindFirstChild(arg2)) then
        return false, "no remote " .. arg2
    end
    local pack = table.pack(...)
    local flag, flag2, value, value2 = false, false, nil, nil
    task.spawn(function()
        flag2, value, value2 = pcall(function()
            return Core.EP.invoke_server(arg2, table.unpack(pack, 1, pack.n))
        end)
        flag = true
    end)
    local now = Utils.now()
    while not flag and Utils.now() - now < 15 do
        task.wait(0.05)
    end
    if not flag then
        req.fails [arg1] = (req.fails [arg1] or 0) + 1
        req.back [arg1] = Utils.now() + 30
        App.log(1, "NET", arg2 .. " timeout (no answer in 15s)")
        return false, "timeout"
    end
    if not flag2 then
        req.fails [arg1] = (req.fails [arg1] or 0) + 1
        req.back [arg1] = Utils.now() + math.min(60, 2 ^ req.fails [arg1])
        App.log(1, "NET", arg2 .. " error: " .. tostring(value))
        return false, tostring(value)
    end
    req.fails [arg1] = 0
    return true, value, value2
end

function App.backoff(arg1, num)
    App.req.back [arg1] = Utils.now() + num
end

function App.listenGame()
    if App.heard then
        return
    end
    local serverToClient = ReplicatedStorage:FindFirstChild("endpoints") and ReplicatedStorage.endpoints:FindFirstChild("server_to_client")
    local showMessage = serverToClient and serverToClient:FindFirstChild("show_message")
    if not showMessage then
        return
    end
    App.heard = true
    table.insert(App.conns, showMessage.OnClientEvent:Connect(function(arg1, arg2)
        if tostring(arg2) == "Error" then
            App.gameError = {
                msg = tostring(arg1),
                at = Utils.now()
            }
        end
    end))
    for _, value in ipairs({
        "hatch_refresh_remaining_time_changed",
        "hatch_banner_changed"
    }) do
        local findFirstChild = serverToClient:FindFirstChild(value)
        if findFirstChild then
            table.insert(App.conns, findFirstChild.OnClientEvent:Connect(function(...)
                pcall(FarmHub.snipeHeard, value, ...)
            end))
        end
    end
end

function App.gameSaid(now)
    local gameError = App.gameError
    return gameError and gameError.at >= now and gameError.msg or nil
end

function Spending.add(name, arg2, name2, why)
    table.insert(Brain.spend, 1, {
        at = os.time(),
        what = name,
        cost = arg2,
        cur = name2,
        why = why
    })
    while # Brain.spend > 60 do
        table.remove(Brain.spend)
    end
    App.log(1, "SPEND", string.format("%s for %s %s — %s", name, Utils.fmt(arg2), name2, why))
    App.saveSoon()
end

function Spending.text()
    if # Brain.spend == 0 then
        return "nothing spent yet"
    end
    local list = {
    }
    for i = 1, math.min(15, # Brain.spend) do
        local value = Brain.spend [i]
        table.insert(list, string.format("%s  %s — %s %s (%s)", os.date("%b %d %H:%M", value.at), value.what, Utils.fmt(value.cost), value.cur, value.why or ""))
    end
    return table.concat(list, "\n")
end
