function Units.critMul(unitId)
    local unit = Core.Units [unitId]
    return 1 + (tonumber(type(unit) == "table" and unit.physical_crit_chance) or 0) * 0.5
end
Units._bleeds = {
}

function Units.bleeds(unitId)
    local bleed = Units._bleeds [unitId]
    if bleed ~= nil then
        return bleed or nil
    end
    local rows = Units.rows(unitId)
    local flag = false
    if rows then
        for i = 0, rows.max do
            local row = rows [i]
            if row and row.atk then
                local ok, res = pcall(Units.attackInfo, row.atk, row.range)
                if ok and res and res.bleed then
                    flag = i
                    break
                end
            end
        end
    end
    Units._bleeds [unitId] = flag
    return flag or nil
end

function Units.bestBleeder(arg1)
    local session = Core.session()
    if not session then
        return nil
    end
    local list = {
    }
    for _, unitData in ipairs(arg1 or {
    }) do
        list [unitData.unit_id] = true
    end
    local value, value2
    for ownedUnitKey, ownedUnit in pairs(session.profile_data.collection.owned_units) do
        local unit = Core.Units [ownedUnit.unit_id]
        if unit and not list [ownedUnit.unit_id] and Units.rows(ownedUnit.unit_id) and not Units.hidden(ownedUnit.unit_id) and Units.bleeds(ownedUnit.unit_id) then
            local ok, res = pcall(Core.USC.calculate_level, ownedUnit.unit_id, tonumber(ownedUnit.xp) or 0)
            if ok and (tonumber(res) or 0) >= 50 then
                local unitObj = session.collection:get_unit_by_uuid(ownedUnitKey) or ownedUnit
                local ok, res = pcall(Units.score, unitObj)
                if ok and (not value2 or res > value2) then
                    value, value2 = unitObj, res
                end
            end
        end
    end
    return value
end

function Units.allyBuff(arg1)
    local unit = Core.Units [arg1]
    if type(unit) ~= "table" or not unit.active_attack then
        return nil
    end
    local attackInfo = Units.attackInfo(unit.active_attack)
    if not attackInfo.ally then
        return nil
    end
    local attackCooldown = tonumber(unit.active_attack_stats and unit.active_attack_stats.attack_cooldown) or 60
    return {
        types = attackInfo.ally.types,
        time = attackInfo.ally.time,
        cd = attackCooldown,
        uptime = math.min(1,
        (attackInfo.ally.time or 0) / math.max(1,
        attackCooldown)),
        attack = unit.active_attack,
        chain = arg1 == "erwin" or arg1 == "wendy" or arg1 == "leafa_evolved" or arg1 == "leafa",
        follow = Units.BUFF_GAP [arg1] or Units.BUFF_FOLLOW,
        squad = Units.BUFF_SQUAD [arg1],
    }
end

-- ===== Auto Buff =====
-- Commander (erwin) raises physical damage; Windsong (wendy) and Leafy (leafa, leafa_evolved) raise magic.
-- A buffed buffer casts a stronger buff, so copies cast in turn climb in steps (with +25%: 25 → 56 → 95 → cap).
-- Checked against three guide videos (Nov 2026): Commander 25 → 56 → 95 → 100, Windsong 30 → 69 → 100, Leafy starts at 50.
-- The gap before the second cast is 4s for Commander and about 5s for Windsong and Leafy (Units.BUFF_GAP).
-- One rule drives the forecast and the match alike: keep at most two buffs up, and cast the next ready
-- copy once only one is left and the last cast is a few seconds old. With four copies that is the
-- known opening: #1, #2 four seconds later, #3 when #1's buff drops, #4 when #2's drops.
Units.BUFF_FOLLOW, Units.BUFF_LEAD, Units.BUFF_COPIES = 4, 4, 4
-- Even step (2.25): used when it leaves at least BUFF_STEP_MARGIN s of overlap; a copy also casts early when
-- the only buff up has BUFF_RESCUE s left.
Units.BUFF_STEP_MARGIN, Units.BUFF_RESCUE = 4, 2.5
Units.BUFF_RELAY_MAX, Units.BUFF_RELAY_MIN, Units.BUFF_RELAY_GUARD = 6, 0.99, 2
-- Copies the infinite buff needs, all within each other's range, before any of them casts.
Units.BUFF_SQUAD = {
    erwin = 4,
    wendy = 4,
    leafa = 4,
    leafa_evolved = 4,
}
Units.BUFF_GAP = {
    erwin = 4,
    wendy = 5,
    leafa = 5,
    leafa_evolved = 5,
}
Units._cycle = {
}

-- Is the rotation on (for this buffer, when an id is given)?
function Units.chainOn(id)
    if Config.autoBuff == false or not Config.actives then
        return false
    end
    if id then
        local buff = Units.allyBuff(id)
        return buff ~= nil and buff.chain == true
    end
    return true
end

-- Auto Buff set to Physical or Magic keeps buffers of the other kind off the field.
function Units.buffAllowed(id)
    local buff = Units.allyBuff(id)
    if not buff or Config.autoBuff == false then
        return true
    end
    local kind = Config.autoBuffKind
    if kind ~= "physical" and kind ~= "magic" then
        return true
    end
    return buff.types [kind] ~= nil
end

-- Estimate a buffer copy's active cooldown before or during a match:
-- 1) real cooldown measured in a match (Brain.buffCd[uuid]),
-- 2) curse / active cooldown multiplier in the unit profile if visible,
-- 3) base cooldown from unit data (honestly marked as curse not visible).
function Units.buffCooldown(id, u, uuid)
    local buff = Units.allyBuff(id)
    if not buff then
        return nil
    end
    local learned = Brain.stack and Brain.stack [buff.attack]
    local dur = (learned and tonumber(learned.dur)) or tonumber(buff.time) or 30
    if not uuid and type(u) == "table" and u.uuid then
        uuid = tostring(u.uuid)
    end
    if not u and not uuid and Core.session() then
        for _, eq in ipairs(Units.equipped()) do
            if eq.id == id then
                u, uuid = eq.u, eq.uuid
                break
            end
        end
    end
    local saved = uuid and Brain.buffCd and Brain.buffCd [tostring(uuid)]
    local savedCd = type(saved) == "table" and tonumber(saved.cd) or tonumber(saved)
    -- Also check if the profile carries a visible curse modifier
    local curseCd
    if type(u) == "table" then
        local curse = u.curse or u.curses or (type(u.further_modifiers) == "table" and (u.further_modifiers.curse or u.further_modifiers.curses))
        if type(curse) == "table" then
            local raw = tonumber(curse.active_attack_cooldown or curse.attack_cooldown or curse.cooldown or curse.spa or curse.cd)
            if raw and raw ~= 0 then
                if raw >= 10 then
                    curseCd = raw
                elseif raw > 0.5 and raw < 2.0 then
                    curseCd = buff.cd * raw
                elseif math.abs(raw) <= 0.5 then
                    curseCd = buff.cd * (1 + raw)
                end
            end
        end
        if not curseCd and Core.USC and Core.USC.calculate_static_stat_multiplier then
            local ok, mul = pcall(Core.USC.calculate_static_stat_multiplier, u, u.xp, "active_attack_cooldown", Core.session())
            if ok and tonumber(mul) and tonumber(mul) > 0 and math.abs(tonumber(mul) - 1) > 0.001 then
                curseCd = buff.cd * tonumber(mul)
            end
        end
    end
    if savedCd and savedCd > 0 then
        return savedCd, "match", dur, buff
    end
    if curseCd and curseCd > 0 then
        return curseCd, "curse", dur, buff
    end
    return buff.cd, "data", dur, buff
end

function Units.buffCheckText(id, u, uuid)
    local cd, src, dur = Units.buffCooldown(id, u, uuid)
    if not cd then
        return nil
    end
    local need = math.floor(2 * dur)
    local cdSec = math.ceil(cd - 1e-6)
    local fits = cd <= 2 * dur + 0.5
    local note = src == "match" and " (from last match)" or (src == "curse" and " (curse read from profile)" or " (curse not visible in profile)")
    local status = fits and "fits ✓" or "SPA curse needed"
    return string.format("%s: cooldown %ds, Lenio needs ≤ %ds → %s%s", Units.name(id), cdSec, need, status, note), fits, cd, dur, src
end

function Units.lobbyBuffCheck(equipped)
    if not Units.chainOn() then
        return nil
    end
    local list = equipped or Units.equipped()
    local lines = {
    }
    local seen = {
    }
    for _, member in ipairs(list) do
        local id = member.id or member.unit_id
        local uuid = member.uuid
        local u = member.u or member
        local buff = id and Units.allyBuff(id)
        if buff and buff.chain and Units.buffAllowed(id) and not seen [uuid or id] then
            seen [uuid or id] = true
            local line = Units.buffCheckText(id, u, uuid)
            if line then
                table.insert(lines, line)
            end
        end
    end
    return # lines > 0 and table.concat(lines, "\n") or nil
end

function Units.buffPlan(copies, cd, dur, base, cap, follow)
    cd, dur = math.max(1, tonumber(cd) or 60), math.max(1, tonumber(dur) or 30)
    local plan = {
        n = copies,
        cd = cd,
        dur = dur,
        base = base,
        cap = cap or 1,
        follow = tonumber(follow) or Units.BUFF_FOLLOW,
        lead = math.min(Units.BUFF_LEAD, dur / 2)
    }
    -- continuous: some order of casts keeps a buff up with no gap. pairs: two buffs can overlap all the time.
    if copies >= 2 then
        plan.continuous = copies * (dur - plan.lead) >= cd
        plan.pairs = copies * dur >= 2 * cd
    else
        plan.continuous, plan.pairs = dur >= cd, false
    end
    -- Even step (2.25): when Lenio's order can't run (cooldown over 2 × buff, no SPA curse: 64-65 s seen in real
    -- matches), copies cast one every cd/copies seconds, so each cast lands while the last buff is still up with
    -- dur - step to spare (14 s at 64/30) instead of the 4 s the old chain kept. Lenio's order stays as it was.
    if copies >= 2 and not plan.pairs then
        local step = math.max(plan.follow, cd / copies)
        if dur - step >= Units.BUFF_STEP_MARGIN then
            plan.step = step
        end
    end
    return plan
end

-- live: buffs still up, each { left = seconds, level = }. Returns: cast now?, why, seconds to wait (when known).
function Units.buffDecide(plan, live, sinceCast, danger)
    local count, soonest = 0, nil
    for _, buff in ipairs(live) do
        if (buff.left or 0) > 0 then
            count = count + 1
            soonest = math.min(soonest or buff.left, buff.left)
        end
    end
    if count == 0 then
        if plan.continuous or danger then
            return true, "starts the rotation"
        end
        return false, "held for a boss or pressure: too few copies to keep the buff up all the time"
    end
    if plan.step then
        local since, latest = sinceCast or 99, 0
        for _, buff in ipairs(live) do
            latest = math.max(latest, buff.left or 0)
        end
        if since >= math.max(plan.follow, plan.step - 0.25) then
            return true, string.format("next copy on the %.0fs step", plan.step)
        end
        if latest <= Units.BUFF_RESCUE and since >= plan.follow then
            return true, "keeps the chain before the last buff ends"
        end
        local waitFor = math.min(plan.step - since, math.max(0, latest - Units.BUFF_RESCUE))
        return false, string.format("next copy in %.0fs (one every %.0fs)", plan.step - since, plan.step), math.max(waitFor, plan.follow - since)
    end
    if (sinceCast or 99) < plan.follow then
        return false, string.format("%.0fs gap after the last cast", plan.follow - sinceCast), plan.follow - sinceCast
    end
    if count == 1 then
        if plan.pairs or not plan.continuous then
            return true, "second buff on top of the first"
        end
        if soonest <= plan.lead then
            return true, "keeps the chain before the buff ends"
        end
        return false, string.format("next cast %.0fs before the buff ends", plan.lead), soonest - plan.lead
    end
    return false, "two buffs are up: the next copy casts when the older one drops", soonest
end

-- Average buff a rotation of this many copies gives (0.5 = +50% on average), its peak and uptime.
function Units.buffCycle(base, copies, cd, dur, cap, follow)
    copies = math.floor(tonumber(copies) or 0)
    if copies <= 0 or (base or 0) <= 0 then
        return {
            avg = 0,
            peak = 0,
            uptime = 0,
            casts = {
            }
        }
    end
    local key = string.format("%.3f:%d:%.1f:%.1f:%.2f:%.1f", base, copies, tonumber(cd) or 60, tonumber(dur) or 30, cap or 1, tonumber(follow) or Units.BUFF_FOLLOW)
    if Units._cycle [key] then
        return Units._cycle [key]
    end
    local plan = Units.buffPlan(copies, cd, dur, base, cap, follow)
    local ready, live, casts = {
    }, {
    }, {
    }
    for index = 1, copies do
        ready [index] = 0
    end
    local horizon = math.max(240, math.ceil(plan.cd * 4))
    local sum, peak, up, last = 0, 0, 0, - 99
    for t = 0, horizon - 1 do
        local view, carried = {
        }, 0
        for index = # live, 1, - 1 do
            if live [index].till <= t then
                table.remove(live, index)
            end
        end
        for _, buff in ipairs(live) do
            table.insert(view, {
                left = buff.till - t,
                level = buff.level
            })
            carried = math.max(carried, buff.level)
        end
        local who
        for index = 1, copies do
            if ready [index] <= t and (not who or ready [index] < ready [who]) then
                who = index
            end
        end
        if who and Units.buffDecide(plan, view, t - last, true) then
            local level = math.min(plan.cap, (1 + base) * (1 + carried) - 1)
            table.insert(live, {
                till = t + plan.dur,
                level = level
            })
            ready [who], last = t + plan.cd, t
            if # casts < 10 then
                table.insert(casts, {
                    t = t,
                    copy = who,
                    level = level
                })
            end
            carried = math.max(carried, level)
        end
        sum, peak = sum + carried, math.max(peak, carried)
        if carried > 0 then
            up = up + 1
        end
    end
    local result = {
        avg = sum / horizon,
        peak = peak,
        uptime = up / horizon,
        casts = casts,
        plan = plan
    }
    Units._cycle [key] = result
    return result
end

function Units.buffAverage(buff, copies, base, chainAllowed)
    local capacity = copies * buff.uptime
    local regular = base * math.min(1, capacity)
    if not (buff.chain and chainAllowed) or copies < 1 then return regular end
    -- The rotation's real average: steps, overlap and the gaps left when copies are few.
    local seen = Brain.stack [buff.attack]
    local cap = seen and tonumber(seen.cap) or 1
    local dur = seen and tonumber(seen.dur) or buff.time
    local squad = buff.squad or Units.BUFF_COPIES
    if copies < squad then
        -- No copy casts before the squad is down: until then each copy counts as its share of the full rotation.
        return Units.buffCycle(base, squad, buff.cd, dur, cap, buff.follow).avg * copies / squad
    end
    return Units.buffCycle(base, squad, buff.cd, dur, cap, buff.follow).avg
end

function Units.buffCopies(allyBuff, running)
    local value = math.max(1, math.ceil((tonumber(allyBuff.cd) or 60) / math.max(1, tonumber(allyBuff.time) or 30) - 0.001))
    if allyBuff.chain and Units.chainOn() then
        local squad = allyBuff.squad or Units.BUFF_COPIES
        local isRunning = running
        if isRunning == nil then
            isRunning = App.where == "match" and Match.buffState ~= nil and Match.buffState [allyBuff.attack] ~= nil and Match.buffState [allyBuff.attack].squad ~= nil
        end
        return math.max(value, isRunning and Units.BUFF_RELAY_MAX or squad)
    end
    local value2 = Brain.stack [allyBuff.attack]
    if value2 and value2.stacks then
        local count = 0
        for _, value in pairs(allyBuff.types or {
        }) do
            count = math.max(count, tonumber(value) or 0)
        end
        if count > 0 and allyBuff.uptime > 0 then
            value = math.max(value, math.ceil((tonumber(value2.cap) or 1) / (count * allyBuff.uptime) - 0.001))
        end
    end
    return value
end

Units._effects = {
}

-- What a unit brings besides its own damage, read only from data the game really sends:
-- its attacks at every upgrade and its active ability. Used so a support is never
-- dropped for low personal DPS before the simulator has measured what it adds.
-- `useful` = at least one effect the simulator can play; `unmodeled` = seen in the data, not simulated.
function Units.effects(id)
    local cached = Units._effects [id]
    if cached then
        return cached
    end
    local unit = Core.Units [id]
    local rows = type(unit) == "table" and Units.rows(id) or nil
    local profile = {
        tags = {
        },
        unmodeled = {
        },
        score = 0,
        useful = false
    }
    if not rows then
        profile.missing = true
        return profile
    end
    local activeId, activeFrom, activeCd
    for level = 0, rows.max do
        local row = rows [level]
        if row then
            local ok, info = pcall(Units.attackInfo, row.atk, row.range)
            if ok and info then
                if (info.stun or 0) > 0 and (info.stun or 0) > (profile.stun or 0) then
                    profile.stun, profile.ccFrom = info.stun, profile.ccFrom or level
                    profile.ccCd = info.ccCd or 8
                end
                if (info.slowTime or 0) > 0 and (info.slowPct or 0) * info.slowTime > (profile.slow or 0) * (profile.slowTime or 0) then
                    profile.slow, profile.slowTime, profile.ccFrom = info.slowPct, info.slowTime, profile.ccFrom or level
                    profile.ccCd = profile.ccCd or info.ccCd or 3
                end
                if (info.amp or 0) > (profile.amp or 0) then
                    profile.amp = info.amp
                end
                if info.bleed then
                    profile.bleed = true
                end
            end
            if row.active and not activeId then
                activeId, activeFrom = row.active, level
            end
            if row.active then
                activeCd = tonumber(row.activeCd) or activeCd
            end
        end
    end
    if activeId then
        profile.active, profile.activeFrom, profile.activeCd = activeId, activeFrom, activeCd or 60
        if Core.Attacks [activeId] or Units.fillAttack(activeId) then
            local ok, info = pcall(Units.attackInfo, activeId)
            if ok and info then
                if info.ally then
                    profile.ally = info.ally
                end
                if info.allyCd then
                    profile.allyCd = info.allyCd
                end
                if info.allyRange then
                    profile.allyRange = info.allyRange
                    table.insert(profile.unmodeled, "its ability widens allies' range")
                end
                if info.selfDmg then
                    profile.selfDmg = info.selfDmg
                end
                if info.baseSafe then
                    profile.baseSafe = info.baseSafe
                end
                if (info.stun or 0) > 0 then
                    profile.activeStun, profile.activeWide = info.stun, info.wholeMap and true or false
                end
                if (info.amp or 0) > (profile.amp or 0) then
                    profile.amp = info.amp
                end
            end
        elseif not Units.FUSION or not Units.FUSION.attacks [id] then
            profile.activeUnknown = true
            table.insert(profile.unmodeled, "ability \"" .. tostring(activeId) .. "\" has no data here")
        end
    end
    local passiveCount = 0
    for _, passive in pairs(type(unit.passives) == "table" and unit.passives or {
    }) do
        if type(passive) == "table" and passive.name and not tostring(passive.name):find("^Pact of") then
            passiveCount = passiveCount + 1
        end
    end
    if passiveCount > 0 then
        profile.passives = passiveCount
        table.insert(profile.unmodeled, passiveCount .. (passiveCount == 1 and " passive" or " passives") .. " not simulated")
    end
    local score = 0
    if profile.stun then
        table.insert(profile.tags, string.format("stuns %.1fs", profile.stun))
        score = score + profile.stun / (profile.stun + (profile.ccCd or 8))
    end
    if profile.slow then
        table.insert(profile.tags, string.format("slows %d%% for %.0fs", math.floor(profile.slow * 100 + 0.5), profile.slowTime))
        score = score + profile.slow * profile.slowTime / (profile.slowTime + (profile.ccCd or 3))
    end
    if (profile.amp or 0) > 0 then
        table.insert(profile.tags, string.format("enemies take +%d%%", math.floor(profile.amp * 100 + 0.5)))
        score = score + profile.amp
    end
    if profile.ally then
        local kinds, best = {
        }, 0
        for kind, rate in pairs(profile.ally.types or {
        }) do
            table.insert(kinds, tostring(kind))
            best = math.max(best, tonumber(rate) or 0)
        end
        table.sort(kinds)
        profile.buffKinds = kinds
        table.insert(profile.tags, string.format("+%d%% %s damage to allies", math.floor(best * 100 + 0.5), table.concat(kinds, "/")))
        score = score + best
    end
    if profile.allyCd then
        table.insert(profile.tags, string.format("allies attack %d%% faster", math.floor((profile.allyCd.reduce or 0) * 100 + 0.5)))
        score = score + (profile.allyCd.reduce or 0)
    end
    if profile.activeStun then
        table.insert(profile.tags, string.format("ability stops %s for %.0fs", profile.activeWide and "every enemy" or "enemies in range", profile.activeStun))
        score = score + profile.activeStun / math.max(1, profile.activeCd or 60) * (profile.activeWide and 3 or 1)
    end
    if profile.baseSafe then
        table.insert(profile.tags, string.format("ability shields the base for %.0fs", profile.baseSafe))
        score = score + 0.2
    end
    profile.score = score
    profile.useful = score > 0
    profile.control = (profile.stun or profile.slow or profile.activeStun) and true or false
    Units._effects [id] = profile
    return profile
end

-- One short word for the planner view and its log.
function Units.roleName(id)
    if Units.isFarm(id) then
        return "farm"
    end
    local _, base = Units.types(id)
    local buff = Units.allyBuff(id)
    if buff then
        local kinds = {
        }
        for kind in pairs(buff.types or {
        }) do
            table.insert(kinds, tostring(kind))
        end
        table.sort(kinds)
        return table.concat(kinds, "/") .. " buffer"
    end
    if Units.FUSION and Units.FUSION.attacks [id] then
        return "fusion · " .. tostring(base)
    end
    local effects = Units.effects(id)
    if effects.control then
        return "control · " .. tostring(base)
    end
    if effects.useful and (effects.amp or effects.allyCd or effects.baseSafe) then
        return "support · " .. tostring(base)
    end
    return tostring(base) .. " attacker"
end

function Units.idol(id)
    local unit = Core.Units [id]
    if type(unit) ~= "table" or not (unit._NO_ATTACKS_UNIT and unit._show_as_buff_unit) then
