    }
}
Units._galeOf = {
}

function Units.galeOf(id)
    local value = Units.GALE [id]
    if not value then
        return nil
    end
    local toggle = Brain.toggles and Brain.toggles [id]
    if not (toggle and (toggle.nf or 0) >= 5 and (toggle.nd or 0) >= 5 and (toggle.fill or 0) > 0 and (toggle.drain or 0) > 0) then
        return value
    end
    local ratio = toggle.fill / (toggle.fill + toggle.drain)
    local value2 = Units._galeOf [id]
    if not (value2 and math.abs(value2.duty - ratio) < 0.01) then
        value2 = table.clone(value)
        value2.duty = ratio
        Units._galeOf [id] = value2
    end
    return value2
end

function Units.toggleOf(id)
    if Units.GALE [id] then
        return {
            from = Units.GALE [id].from,
            known = true
        }
    end
    local toggle = Brain.toggles and Brain.toggles [id]
    if toggle then
        return toggle
    end
    local ok, res = pcall(Reports.hiveToggle, id)
    return ok and res or nil
end

function Units.galeDps(unitId, upgradeValue)
    local galeOf = Units.galeOf(unitId)
    if not galeOf or (upgradeValue or 0) < galeOf.from then
        return 0
    end
    return galeOf.duty * galeOf.targets * (galeOf.tick + 1 / galeOf.freezeEvery)
end

function Units.dps(u, upgradeValue, mod, arg4)
    local rows = Units.rows(u.unit_id)
    local row = rows and rows [math.min(upgradeValue, rows.max)]
    if not row or (row.cd or 0) <= 0 then
        return 0
    end
    local damage = row.damage * Units.mult(u, "damage")
    local num = arg4 and 0 or damage * Units.galeDps(u.unit_id, upgradeValue)
    return (damage / (row.cd * math.max(0.1, Units.mult(u, "attack_cooldown"))) * Units.aoe(row.atk, row.range) * Units.critMul(u.unit_id) + num) * Units.elem(u.unit_id, mod) * Units.relic(u) * Units.nudge(u.unit_id)
end
Units._skinMul = {
}

function Units.skinMul(item, skinSet)
    local skinId = skinSet and item.skin and item.skin._skin_id
    local value = skinId and (Core.data("Skins") or {
    }) [skinId]
    if not (value and value._skin_set == skinSet) then
        return 1
    end
    local damageBoost = tonumber(value._damage_boost) or 0
    if damageBoost <= 0 then
        return 1
    end
    local text = tostring(item.uuid or skinId) .. ":" .. tostring(skinSet) .. ":" .. tostring(App.where)
    local value = Units._skinMul [text]
    if value and Utils.now() - value.t < 60 then
        return value.v
    end
    local value = 1 + damageBoost
    local ok, res = pcall(table.clone, item)
    if ok and type(res) == "table" then
        res.skin = nil
        local session = Core.session()
        local ok, res2 = pcall(Core.USC.calculate_static_stat_multiplier, item, item.xp, "damage", session)
        local ok2, res3 = pcall(Core.USC.calculate_static_stat_multiplier, res, item.xp, "damage", session)
        res2, res3 = ok and tonumber(res2), ok2 and tonumber(res3)
        if res2 and res3 and res3 > 0 and res2 / res3 > 1 + damageBoost * 0.5 then
            value = 1
        end
    end
    Units._skinMul [text] = {
        v = value,
        t = Utils.now()
    }
    return value
end

function Units.range(u, max)
    local rows = Units.rows(u.unit_id)
    local row = rows and rows [math.min(max, rows.max)]
    return (row and row.range or 10) * Units.mult(u, "range")
end

function Units.farm(u, arg2)
    local rows = Units.rows(u.unit_id)
    local row = rows and rows [math.min(arg2, rows.max)]
