function Units.score(u, mod)
    local rows = Units.rows(u.unit_id)
    if not rows then
        return 0
    end
    local max = rows.max
    return Units.dps(u, max, mod) * math.sqrt(math.max(1, Units.range(u, max)) / 20) * math.sqrt(Units.cap(u))
end

