function Modes.levelMod(level)
    if level == nil then
        return nil
    end
    if Modes._levelMod [level] ~= nil then
        return Modes._levelMod [level] or nil
    end
    Modes._levelMod [level] = false
    local level2 = Core.Levels [level]
    local wave = type(level2) == "table" and Core.Waves [level2.waves or level]
    local initialUnitConfigs = type(wave) == "table" and wave.initial_unit_configs
    if type(initialUnitConfigs) ~= "table" then
        return nil
    end
    local list, list2, count = {
    }, {
    }, 0
    for _, initialUnitConfig in pairs(initialUnitConfigs) do
        local value = type(initialUnitConfig) == "table" and type(initialUnitConfig.override_stats) == "table" and (initialUnitConfig.override_stats [1] or initialUnitConfig.override_stats ["1"]) or nil
        if type(value) == "table" then
            local health = tonumber(value.health) or 20
            count = count + health
            table.insert(list, {
                hp = health,
                st = value
            })
            for key in pairs(value) do
                local match = tostring(key):match("^_dmg_amp_(.+)$") or tostring(key):match("^_dmg_res_(.+)$")
                if match then
                    list2 [match] = true
                end
            end
        end
    end
    if not next(list2) or count <= 0 then
        return nil
    end
    local info = {
        weak = {
        },
        strong = {
        },
        res = {
        }
    }
    for itemKey in pairs(list2) do
        local count2 = 0
        for _, item in ipairs(list) do
            local ratio = (1 + (tonumber(item.st ["_dmg_amp_" .. itemKey]) or 0)) * 100 / (100 + math.max(0, tonumber(item.st ["_dmg_res_" .. itemKey]) or 0))
            count2 = count2 + item.hp / math.max(0.05, ratio)
        end
        local ratio = count / math.max(1, count2)
        if ratio > 1.02 then
            info.weak [itemKey] = ratio
        elseif ratio < 0.98 then
            info.res [itemKey] = ratio
        end
    end
    if not (next(info.weak) or next(info.res)) then
        return nil
    end
    Modes._levelMod [level] = info
    return info
end

function Modes.dailyMod(challengeUuid, dailyChallengeWeakAgainst, dailyChallengeStrongAgainst)
    challengeUuid = tonumber(challengeUuid)
    local value = challengeUuid and Random.new(challengeUuid) or nil
    local info = {
        weak = {
        },
        strong = {
        },
        res = {
        }
    }
    for _, value2 in pairs(dailyChallengeWeakAgainst or {
    }) do
        info.weak [value2] = value and 1 + value:NextNumber(0.5, 0.7) or 1.5
    end
    for _, value2 in pairs(dailyChallengeStrongAgainst or {
    }) do
        if value then
            info.res [value2] = 100 / (100 + value:NextNumber(100, 150))
        else
            info.strong [value2] = true
        end
    end
    return info
end

