function Modes.infReach(key)
    local rec = Modes.rec(key)
    if (tonumber(rec.waveN) or 0) > 0 then
        return rec.waveSum / rec.waveN, true
    end
    local sim = Modes.sim({ key = key, kind = "infinite" })
    if sim and tonumber(sim.wave) then
        return sim.wave, false
    end
    return 25, false
end

function Modes.infDaily(prof, infId, infReach)
    local dailyInfiniteRewardClaim = prof.daily_infinite_reward_claims and prof.daily_infinite_reward_claims [infId]
    local dailyInfiniteRewardPeriod = tonumber(Core.GS.DAILY_INFINITE_REWARD_PERIOD) or 82800
    local value = (type(dailyInfiniteRewardClaim) == "table" and os.time() - (tonumber(dailyInfiniteRewardClaim.highest_claim_time) or 0) < dailyInfiniteRewardPeriod) and (tonumber(dailyInfiniteRewardClaim.highest_claimed_wave) or 0) or 0
    local count, count2 = 0, 0
    for _, item in ipairs(Utils.list(Core.GS.DAILY_INFINITE_REWARDS)) do
        local wave = tonumber(item.wave) or 0
        if wave > value and wave <= (infReach or 0) then
            count, count2 = count + (tonumber(item.gem_reward) or 0), math.max(count2, wave)
        end
    end
    return count, count2, value
end

function Modes.infTier(wave)
    local count = 0
    for _, item in ipairs(Utils.list(Core.GS.DAILY_INFINITE_REWARDS)) do
        if (tonumber(item.wave) or 0) <= wave then
            count = math.max(count, tonumber(item.wave) or 0)
        end
    end
    return count
end

