function Modes.eventNow()
    if Modes._event ~= nil then
        return Modes._event or nil
    end
    Modes._event = false
    for activeEventChallengeKey in pairs(Core.GS.ACTIVE_EVENT_CHALLENGES or {
    }) do
        local level = Core.Levels [activeEventChallengeKey]
        local flag, value = activeEventChallengeKey == Hunt.ID, type(level) == "table" and level._randomequippedmode ~= nil
        Modes._event = {
            id = activeEventChallengeKey,
            name = type(level) == "table" and level.name or tostring(activeEventChallengeKey),
            hunt = flag,
            dealt = value,
            about = flag and "50 waves with cards and weather, for Summer Pearls. It never spends them" or value and "AprilCoins every wave, for the April banner" or string.format("The game's current event, for %s",
            Modes.coinName())
        }
        break
    end
    return Modes._event or nil
end

function Modes.onlyOn()
    return Config.onlyRaids or Config.onlyStory or Config.onlyChallenges or (Config.onlyCoins and Modes.eventNow() ~= nil) or Config.onlyDungeons or Config.onlyLegend or Config.onlyInfinite or Config.onlyPortals or Config.onlyArtifact
end

function Modes.allowed(mode)
    if Config.dailyLoop and mode.kind == "daily" then
        return true
    end
    if not Modes.onlyOn() then
        return true
    end
    if Brain.nextMode and Brain.nextMode == mode.key then
        return true
    end
    if mode.kind == "daily" and Config.team then
        return true
    end
    if mode.kind == "raid" then
        return Config.onlyRaids
    end
    if mode.legend then
        return Config.onlyLegend
    end
    if mode.kind == "story" then
        return Config.onlyStory and (mode.picked or (mode.first and mode.diff == "Normal"))
    end
    if mode.kind == "daily" or mode.kind == "challenge" then
        return Config.onlyChallenges
    end
    if mode.kind == "event" then
        return Config.onlyCoins
    end
    if mode.kind == "dungeon" then
        return Config.onlyDungeons
    end
    if mode.kind == "infinite" then
        return Config.onlyInfinite
    end
    if mode.kind == "artifact" then
        return Config.onlyArtifact
    end
    if mode.kind == "portal" then
        if mode.picked or Config.onlyPortals then
            return true
        end
        for _, portal in pairs(Modes.PORTALS) do
            if portal.level == mode.level then
                return Config.onlyInfinite and (Config.pickInfinite == "" or Config.pickInfinite == "inf:" .. portal.from)
            end
        end
    end
    return false
end

function Modes.onlyText()
    local list = {
    }
    local eventNow = Modes.eventNow()
    for _, value in ipairs({
        {
            "onlyRaids",
            "raids"
        },
        {
            "onlyStory",
            "story"
        },
        {
            "onlyLegend",
            "legend stages"
        },
        {
            "onlyInfinite",
            "Infinite"
        },
        {
            "onlyPortals",
            "portals"
        },
        {
            "onlyArtifact",
            "the Artifact Stage"
        },
        {
            "onlyChallenges",
            "challenges"
        },
        {
            "onlyCoins",
            eventNow and (eventNow.hunt and "the Summer Hunt" or eventNow.name)
        },
        {
            "onlyDungeons",
            "dungeons"
        }
    }) do
        if Config [value [1]] and value [2] then
            table.insert(list, value [2])
        end
    end
    return table.concat(list, ", ")
end
