function Modes.chOk(mode, equippedOnly)
    local challenge = mode.kind == "daily" and Brain.live.daily and Brain.live.daily.challenge or mode.challenge
    if challenge and table.find(Config.chSkip or {
    }, challenge) then
        return false, Modes.chName(challenge) .. " is on your skip list"
    end
    if Config.chSmart then
        local sim = Modes.sim(mode, equippedOnly)
        local chMinP = tonumber(Config.chMinP) or 0.5
        local canSearch = not equippedOnly and Config.sim and Modes.canSearch(mode) and not Modes.teamPlan(mode)
        local probability = sim and sim.p
        if probability and mode.kind == "daily" and FarmHub.matchOn(mode) then
            probability = math.max(probability, Modes.MATCHED_DAILY_P)
        end
        if probability and probability < chMinP and not (sim.trust and not sim.trust.ok) and not canSearch then
            return false, string.format("estimated win chance %d%%, under the %d%% you set", math.floor(probability * 100 + 0.5), math.floor(chMinP * 100 + 0.5))
        end
    end
    return true
end

