function Hunt.plain(arg1, arg2)
    arg2 = arg2 or 0
    if type(arg1) == "table" then
        if arg2 > 5 then
            return "..."
        end
        local list = {
        }
        for key, value in pairs(arg1) do
            list [tostring(key)] = Hunt.plain(value, arg2 + 1)
        end
        return list
    end
    if type(arg1) == "number" or type(arg1) == "string" or type(arg1) == "boolean" then
        return arg1
    end
    return tostring(arg1)
end

