function Hunt.charmApplies(mode)
    if not mode then
        return false
    end
    if mode.kind == "event" and Hunt.is(mode.level) then
        return true
    end
    return mode.kind == "portal" and tostring(mode.level):find("skypiea", 1, true) ~= nil
end

function Hunt.charms()
    local prof = Core.prof()
    local list = {
    }
    for uniqueItemKey, uniqueItem in pairs((prof and prof.inventory and prof.inventory.unique_items) or {
    }) do
        local item = type(uniqueItem) == "table" and Core.Items [uniqueItem.item_id]
        if type(item) == "table" and item.item_group == "Charms" then
            local info = {
                uuid = uniqueItem.uuid or uniqueItemKey,
                id = uniqueItem.item_id,
                tier = tonumber(item.tier) or 0,
                rolls = {
                }
            }
            local d = type(uniqueItem._unique_item_data) == "table" and type(uniqueItem._unique_item_data._unique_charm_data) == "table" and uniqueItem._unique_item_data._unique_charm_data._d
            for _, value in pairs(type(d) == "table" and d or {
            }) do
                if type(value) == "table" and value._t then
                    info.rolls [tostring(value._t)] = (info.rolls [tostring(value._t)] or 0) + (tonumber(value._d) or 0)
                end
            end
            table.insert(list, info)
        end
    end
    return list
end

function Hunt.charmOn()
    local prof = Core.prof()
    local equippedCharms = prof and prof.equipped_charms
    if type(equippedCharms) ~= "table" then
        return nil
    end
    for _, equippedCharm in pairs(equippedCharms) do
        return type(equippedCharm) == "table" and (equippedCharm.uuid or equippedCharm [1]) or equippedCharm
    end
    return nil
end

function Hunt.charmScore(charm, arg2)
    local p = (arg2 and tonumber(arg2.p)) or 0.5
    local unitDamage, rewardMul, count = charm.rolls.unit_damage or 0, charm.rolls.reward_mul or 0, 0
    for rollKey, roll in pairs(charm.rolls) do
        if rollKey ~= "unit_damage" and rollKey ~= "reward_mul" then
            count = count + roll
        end
    end
    if p >= 0.92 then
        return rewardMul * 3 + unitDamage + count * 0.5
    end
    return unitDamage * 3 + rewardMul + count * 0.5
end

function Hunt.charmWords(charmWant)
    local list = {
    }
    for rollKey, roll in pairs(charmWant.rolls) do
        table.insert(list, string.format("%s +%d%%", rollKey == "unit_damage" and "damage" or (rollKey == "reward_mul" and "rewards" or rollKey), math.floor(roll * 100 + 0.5)))
    end
    table.sort(list)
    return string.format("Tier %d: %s", charmWant.tier, # list > 0 and table.concat(list, ", ") or "no bonus read")
end

function Hunt.charmDmg(arg1)
    if type(arg1) ~= "table" or not (Hunt.is(arg1.id) or arg1.portal_group == "summer2" or tostring(arg1.id):find("skypiea_portal", 1, true)) then
        return 0
    end
    local charmOn, count = Hunt.charmOn(), 0
    for _, charm in ipairs(Hunt.charms()) do
        local unitDamage = charm.rolls.unit_damage or 0
        if charmOn and charm.uuid == charmOn then
            return unitDamage
        end
        if Config.smartCharm and unitDamage > count then
            count = unitDamage
        end
    end
    return charmOn and 0 or count
end

function Hunt.charmWant(arg1)
    if not Config.smartCharm or not Hunt.charmApplies(arg1) then
        return nil
    end
    Brain.charm = type(Brain.charm) == "table" and Brain.charm or {
    }
    if os.time() - (tonumber(Brain.charm.failAt) or 0) < 1800 then
        return nil
    end
    local item, value
    for _, charm in ipairs(Hunt.charms()) do
        local charmScore = Hunt.charmScore(charm, arg1)
        if not value or charmScore > value then
            item, value = charm, charmScore
        end
    end
    if not item then
        return nil
    end
    local charmOn = Hunt.charmOn() or (App.where == "match" and Brain.charm.uuid) or nil
    if charmOn == item.uuid then
        return nil
    end
    return item, charmOn
end

function Hunt.charmTick(arg1)
    local charmWant, charmWant2 = Hunt.charmWant(arg1)
    if not charmWant then
        return
    end
    charmWant2 = Hunt.charmOn()
    if charmWant2 then
        App.request("charm", "request_unequip_charm", charmWant2)
        task.wait(1)
    end
    App.request("charm", "use_unique_item", charmWant.uuid)
    local now = Utils.now()
    while Utils.now() - now < 4 and Hunt.charmOn() ~= charmWant.uuid do
        task.wait(0.5)
    end
    if Hunt.charmOn() == charmWant.uuid then
        Brain.charm.uuid, Brain.charm.at, Brain.charm.failAt = charmWant.uuid, os.time(), nil
        App.saveSoon()
        App.log(1, "CHARM", string.format("wearing the Summer Charm (%s) for %s (win %d%%: %s first)", Hunt.charmWords(charmWant), tostring(arg1.label), math.floor((tonumber(arg1.p) or 0) * 100 + 0.5), (tonumber(arg1.p) or 0) >= 0.92 and "rewards" or "damage"))
    else
        Brain.charm.failAt = os.time()
        App.saveSoon()
        App.log(1, "CHARM", string.format("the game didn't put on the Summer Charm (%s): trying again in 30 min", Hunt.charmWords(charmWant)))
    end
end

function Hunt.weatherStrength(weatherNow)
    local fx = Hunt.fx(weatherNow)
    local ratio = fx.dmg / fx.cd / fx.hp / fx.speed * (1 + (fx.range - 1) / 2)
    for kindKey, kind in pairs(fx.kinds) do
        ratio = ratio * (1 + Match.rogueShare(kindKey) * kind)
    end
    if fx.ice > 0 then
        local rogueShare = Match.rogueShare("fire")
        ratio = ratio * (rogueShare + (1 - rogueShare) / (1 - fx.ice + fx.ice / Simulator.modFactor("Ice@snow")))
    end
    if fx.fly > 0 then
        ratio = ratio * (1 - fx.fly * 0.5)
    end
    if fx.noCC then
        ratio = ratio * 0.95
    end
    if fx.shroud then
        ratio = ratio * 0.9
    end
    return ratio
end

function Hunt.cardGems(value, arg2)
    local count = 0
    local pearlsFrom = Hunt.pearlsFrom(arg2 + 1, 50)
    for _, effect in pairs(type(value.effects) == "table" and value.effects or {
    }) do
        if type(effect) == "table" then
            local amount = tonumber(effect.amount) or 0
            if effect.type == "candy_multiplier" then
                count = count + math.abs(amount) * pearlsFrom * Config.pearlValue
            elseif effect.type == "add_reward" then
                local ok, res = pcall(Modes.rewardValue, effect.reward)
                if ok then
                    count = count + (tonumber(res) or 0)
                end
            elseif effect.type == "golem_chance" then
                count = count + amount * Hunt.STARFALL_GEMS
            elseif effect.type == "secret_drop" then
                count = count + amount * 100
            end
        end
    end
    if value.option_type == "Bad" then
        count = count + Hunt.HARD_GEMS
    end
    if value.weather then
        local flag = value.weather ~= Hunt.weatherNow()
        if flag and value.weather == "meteor_shower" then
            count = count + Hunt.STARFALL_GEMS
        end
        local board = Hunt.board()
        if flag and board and value.weather ~= "clear" and not board.weathers [value.weather] then
            count = count + (1000 + 5000 * Config.pearlValue + 50 * (Core.ITEM_VALUE.star_remnant_limited or 25)) / Hunt.WEATHERS
        end
    end
    return count
end

function Hunt.text()
    local event = Brain.live.event
    if not (event and Hunt.is(event.level)) then
        return "The Summer Hunt isn't on the board right now."
    end
    local value, value2 = Core.data("Weather") or {
    }, Core.data("Maps") or {
    }
    local list = {
    }
    local function helper(arg1)
        return arg1 and value2 [arg1] and value2 [arg1].name or arg1 or "?"
    end
    table.insert(list, string.format("This hour: %s, %s.", helper(event.map), event.weather and value [event.weather] and value [event.weather].name or "weather unknown"))
    if type(event.forecast) == "table" then
        table.insert(list, string.format("Next hour: %s, %s.", event.forecast.map and helper(event.forecast.map) or (event.forecast.map_hint or "map hidden"), event.forecast.weather and value [event.forecast.weather] and value [event.forecast.weather].name or (event.forecast.weather_hint or "weather hidden")))
    end
    local rec = Modes.rec("ev:" .. tostring(event.level))
    if rec.runs > 0 then
        table.insert(list, string.format("%d runs so far, %d won, ≈%d Summer Pearls a run.", rec.runs, rec.wins, math.floor(rec.coins / rec.runs)))
    else
        table.insert(list, string.format("Not played yet. A full run should pay about %d Summer Pearls.", math.floor(Hunt.pearlsFrom(1, 50) * Hunt.MULT_GUESS)))
    end
    local board = Hunt.board()
    if board then
        table.insert(list, string.format("Bingo: %d of %d squares, %d of %d lines. Weathers won: %d of %d.", board.squares, # board.board, board.lines, board.total, board.weathersWon, Hunt.WEATHERS))
    end
    local huntCards = table.find(Hunt.CARD_PICKS, Config.huntCards) and Config.huntCards or "Smart"
    table.insert(list, "Cards: " .. (({
        ["Secret Luck"] = "the most secret luck, then the most pay. Secret luck only comes on the harder cards, so one is skipped when it would leave your team too weak to win.",
        ["Gems"] = "the one that pays the most in gems and pearls, skipping any that would leave your team too weak to win.",
        ["Easiest Win"] = "the one that makes your team strongest, whatever it pays.",
        ["Smart"] = "what each pays weighed against how much weaker it leaves your team."
    }) [huntCards]))
    table.insert(list, string.format("You hold %s Summer Pearls. The farm never trades gems for them, and spends them only on Sunny Stars, only with Open Sunny Stars on.", Utils.fmt(tonumber(Core.cur("SummerPearls")) or 0)))
    return table.concat(list, "\n")
end
