function Hunt.skinFits(unitId, skin)
    local unit = Core.Units [unitId]
    local from = unit and unit.evolved and unit.evolved.from or unitId
    return skin.for_unit == unitId or skin.for_unit == from or (skin.for_units ~= nil and (skin.for_units [unitId] or skin.for_units [from]) and true) or false
end

function Hunt.team()
    local value = Brain.simTeam and Brain.simTeam ["ev:" .. tostring(Hunt.ID)]
    local session = Core.session()
    local list = {
    }
    for _, uuid in ipairs(value and value.uuids or Brain.savedTeam or {
    }) do
        local unitObj = session.collection:get_unit_by_uuid(uuid)
        if unitObj then
            table.insert(list, unitObj)
        end
    end
    return list
end

function Hunt.skinPlan()
    local session, prof = Core.session(), Core.prof()
    local value = Core.data("Skins") or {
    }
    local uniqueItems = (prof.inventory and prof.inventory.unique_items) or prof.unique_items or {
    }
    local list, info = {
    }, {
        kinds = {
        },
        sell = {
        },
        wear = {
        },
        pearls = 0,
        missing = {
        }
    }
    for uniqueItemKey, uniqueItem in pairs(uniqueItems) do
        local item = type(uniqueItem) == "table" and Core.Items [uniqueItem.item_id]
        if item and item.item_group == "Skins" and item._skin_set == Hunt.SKIN_SET and item.usage and value [item.usage.skin_id] then
            local item2 = list [uniqueItem.item_id]
            if not item2 then
                item2 = {
                    id = uniqueItem.item_id,
                    name = item.name,
                    rarity = item.rarity,
                    skinId = item.usage.skin_id,
                    skin = value [item.usage.skin_id],
                    uuids = {
                    }
                }
                list [uniqueItem.item_id] = item2
                table.insert(info.kinds, item2)
            end
            table.insert(item2.uuids, uniqueItem.uuid or uniqueItemKey)
        end
    end
    table.sort(info.kinds, function(arg1, arg2)
        return arg1.name < arg2.name
    end)
    local team = Hunt.team()
    local ownedUnits = session.profile_data.collection.owned_units
    for _, kind in ipairs(info.kinds) do
        for _, ownedUnit in pairs(ownedUnits) do
            if Hunt.skinFits(ownedUnit.unit_id, kind.skin) then
                kind.fits = true
                break
            end
        end
        local value = kind.rarity == "Legendary" or kind.rarity == "Mythic"
        kind.keep = (kind.fits or value) and 1 or 0
        for i = kind.keep + 1, # kind.uuids do
            table.insert(info.sell, {
                uuid = kind.uuids [i],
                name = kind.name,
                pearls = Hunt.SKIN_PRICE [kind.rarity] or 0
            })
            info.pearls = info.pearls + (Hunt.SKIN_PRICE [kind.rarity] or 0)
        end
    end
    for _, member in ipairs(team) do
        local value2 = member.skin and member.skin._skin_id and value [member.skin._skin_id]
        if not (value2 and value2._skin_set == Hunt.SKIN_SET) then
            for key, value in pairs(value) do
                if type(value) == "table" and value._skin_set == Hunt.SKIN_SET and Hunt.skinFits(member.unit_id, value) then
                    local text = key .. "_skin"
                    if list [text] then
                        table.insert(info.wear, {
                            uuid = list [text].uuids [1],
                            unit = member.uuid,
                            unitName = Units.name(member.unit_id),
                            name = list [text].name
                        })
                    else
                        table.insert(info.missing, {
                            item = text,
                            unitName = Units.name(member.unit_id),
                            name = value.name,
                            boost = tonumber(value._damage_boost) or 0,
                            drop = Hunt.SKIN_DROP [value._skin_rarity] or 0
                        })
                    end
                end
            end
        end
    end
    return info
end

function Hunt.starPlan(skinPlan)
    skinPlan = skinPlan or Hunt.skinPlan()
    local item = Core.Items [Hunt.STAR] or {
    }
    local mythicUnitPity = tonumber(item._mythic_unit_pity) or 400
    local value = (Core.prof().capsule_pity_data or {
    }) [Hunt.STAR] or {
    }
    local opensSinceMythicUnit = tonumber(value.opens_since_mythic_unit) or 0
    local info = {
        opened = tonumber(value.total_opens) or 0,
        left = math.max(1,
        mythicUnitPity - opensSinceMythicUnit),
        units = {
        }
    }
    local cur = tonumber(Core.cur("SummerPearls")) or 0
    info.can = math.max(0, math.floor((cur - (tonumber(Config.pearlFloor) or 0)) / Hunt.STAR_COST))
    local list = {
    }
    for _, ownedUnit in pairs(Core.session().profile_data.collection.owned_units) do
        list [ownedUnit.unit_id] = true
        local unit = Core.Units [ownedUnit.unit_id]
        if unit and unit.evolved and unit.evolved.from then
            list [unit.evolved.from] = true
        end
    end
    for _, possibleReward in pairs(item.usage and item.usage.possible_rewards or {
    }) do
        local unit = possibleReward.unit or possibleReward.item
        if unit and Core.Units [unit] and Core.Units [unit].rarity == "Mythic" and not list [unit] then
            table.insert(info.units, Units.name(unit))
        end
    end
    table.sort(info.units)
    local list = {
    }
    if # skinPlan.missing > 0 then
        local value = skinPlan.missing [1]
        table.insert(list, string.format("%s to go on %s", value.name, value.unitName))
    end
    if # info.units > 0 then
        table.insert(list, string.format("a Mythic unit you don't have (%s)", table.concat(info.units, ", ")))
    end
    info.why = table.concat(list, " and ")
    info.open = # list > 0 and math.min(info.can, # info.units > 0 and info.left or 100) or 0
    return info
end

function Hunt.skinText()
    local ok, res = pcall(Hunt.skinPlan)
    if not ok then
        return "Reading your skins: " .. tostring(res)
    end
    local list = {
    }
    local list2 = {
    }
    for _, kind in ipairs(res.kinds) do
        table.insert(list2, string.format("%s%s (+%d%% damage%s)", kind.name, # kind.uuids > 1 and (" ×" .. # kind.uuids) or "", (tonumber(kind.skin._damage_boost) or 0) * 100, kind.fits and "" or ", no unit of yours fits"))
    end
    table.insert(list, "A skin counts only in the Hunt, on the unit wearing it. You hold: " .. (# list2 > 0 and table.concat(list2, ", ") or "none") .. ".")
    if # res.wear > 0 then
        local list2 = {
        }
        for _, value in ipairs(res.wear) do
            table.insert(list2, value.name .. " on " .. value.unitName)
        end
        table.insert(list, "Would wear: " .. table.concat(list2, ", ") .. ".")
    end
    for _, value in ipairs(res.missing) do
        table.insert(list, string.format("Your Hunt team could use %s on %s: +%d%% damage, +%d%% Secret Portal drop.", value.name, value.unitName, value.boost * 100, value.drop * 100))
    end
    if # res.sell > 0 then
        local list2 = {
        }
        for _, value in ipairs(res.sell) do
            list2 [value.name] = (list2 [value.name] or 0) + 1
        end
        local list3 = {
        }
        for itemKey, item in pairs(list2) do
            table.insert(list3, item .. "× " .. itemKey)
        end
        table.sort(list3)
        table.insert(list, string.format("Would sell %s for %s pearls. It can't be undone.", table.concat(list3, ", "), Utils.fmt(res.pearls)))
    else
        table.insert(list, "Nothing to sell.")
    end
    local ok, res2 = pcall(Hunt.starPlan, res)
    if ok then
        table.insert(list, string.format("Sunny Stars: %d opened. A sure Mythic unit in %d more (%s pearls).", res2.opened, res2.left, Utils.fmt(res2.left * Hunt.STAR_COST)))
        if res2.open > 0 then
            table.insert(list, string.format("Would open %d (%s pearls) for %s, keeping %s pearls.", res2.open, Utils.fmt(res2.open * Hunt.STAR_COST), res2.why, Utils.fmt(Config.pearlFloor)))
        elseif res2.why ~= "" then
            table.insert(list, string.format("Wants %s, but that would go under the %s pearls you keep.", res2.why, Utils.fmt(Config.pearlFloor)))
        else
            table.insert(list, "No need for more stars.")
        end
    end
    if FarmHub.pickNote.skins then
        table.insert(list, FarmHub.pickNote.skins)
    end
    return table.concat(list, "\n")
end

function Hunt.skinTick()
    if not (Config.skinSmart or Config.starOpen) or not (Brain.live.event and Hunt.is(Brain.live.event.level)) then
        return
    end
    if (App.req.back.skins or 0) > Utils.now() then
        return
    end
    local session = Core.session()
    local function helper(arg1, arg2, arg3)
        local gameSaid = App.gameSaid(arg2)
        FarmHub.pickNote.skins = string.format("%s: the game said no (%s). Trying again in 30 min.", arg1, tostring(gameSaid or arg3 or "no answer"))
        App.log(1, "LOBBY", FarmHub.pickNote.skins)
        App.backoff("skins", 1800)
    end
    local skinPlan = Hunt.skinPlan()
    if Config.skinSmart then
        local item = skinPlan.wear [1]
        if item and (App.req.back.skinWear or 0) <= Utils.now() then
            local slotOf = Strategy.slotOf(item.unit)
            if slotOf then
                Brain.str.reequip = {
                    uuid = item.unit,
                    slot = slotOf
                }
                App.saveNow()
                App.request("uneq", "unequip_unit", item.unit)
                local now = Utils.now()
                while Utils.now() - now < 4 and Strategy.slotOf(item.unit) do
                    task.wait(0.25)
                end
            end
            local now = Utils.now()
            local _, res = App.request("skinWear", "use_unique_item", item.uuid, {
                unit_uuid = item.unit
            })
            local function helper()
                local unitObj = session.collection:get_unit_by_uuid(item.unit)
                return unitObj and unitObj.skin ~= nil
            end
            while Utils.now() - now < 5 and not helper() do
                task.wait(0.25)
            end
            if slotOf then
                Strategy.reequip()
            end
            if helper() then
                App.log(1, "LOBBY", string.format("Summer skins: %s on %s", item.name, item.unitName))
                FarmHub.pickNote.skins = nil
                skinPlan = Hunt.skinPlan()
            else
                local gameSaid = App.gameSaid(now)
                FarmHub.pickNote.skins = string.format("Wearing %s: the game said no (%s). Trying again in 30 min.", item.name, tostring(gameSaid or res or "no answer"))
                App.log(1, "LOBBY", FarmHub.pickNote.skins)
                App.backoff("skinWear", 1800)
            end
        end
        if # skinPlan.sell > 0 then
            local list, count = {
            }, 0
            for i = 1, math.min(50, # skinPlan.sell) do
                table.insert(list, skinPlan.sell [i].uuid)
                count = count + skinPlan.sell [i].pearls
            end
            local cur = tonumber(Core.cur("SummerPearls")) or 0
            local now = Utils.now()
            local _, res = App.request("skinSell", "delete_unique_items", list)
            while Utils.now() - now < 5 and (tonumber(Core.cur("SummerPearls")) or 0) <= cur do
                task.wait(0.25)
            end
            local cur2 = (tonumber(Core.cur("SummerPearls")) or 0) - cur
            if cur2 <= 0 then
                return helper("Selling skins", now, res)
            end
            Spending.add(string.format("sold %d spare Summer skins", # list), # list, "skins", string.format("Smart Skins: +%s pearls", Utils.fmt(cur2)))
            FarmHub.pickNote.skins = nil
        end
    end
    if Config.starOpen then
        local inventory = session.inventory
        local function helper2()
            local ok, res = pcall(inventory.get_number_of_owned_item, inventory, Hunt.STAR)
            return ok and tonumber(res) or 0
        end
        local now = Utils.now()
        for i = 1, 8 do
            if Utils.now() - now > 15 or not App.alive or App.where ~= "lobby" then
                break
            end
            local value = helper2()
            local starPlan = Hunt.starPlan(Hunt.skinPlan())
            local now = Utils.now()
            if value > 0 then
                local _, res = App.request("starOpen", "use_item", Hunt.STAR, {
                    use10 = value >= 10,
                    use_all = false
                })
                while Utils.now() - now < 6 and helper2() >= value do
                    task.wait(0.25)
                end
                if helper2() >= value then
                    return helper("Opening a Sunny Star", now, res)
                end
                App.log(1, "LOBBY", string.format("Sunny Stars: opened %d · %d opened in all", value - helper2(), (tonumber(((Core.prof().capsule_pity_data or {
                }) [Hunt.STAR] or {
                }).total_opens) or 0)))
                FarmHub.pickNote.skins = nil
            elseif starPlan.open > 0 then
                local num = starPlan.open >= 10 and 10 or 1
                local cur = tonumber(Core.cur("SummerPearls")) or 0
                local _, res = App.request("starBuy", "buy_item_generic", Hunt.STAR, "event", "event_shop", tostring(num))
                while Utils.now() - now < 5 and helper2() <= 0 do
                    task.wait(0.25)
                end
                if helper2() <= 0 then
                    return helper("Buying a Sunny Star", now, res)
                end
                Spending.add(string.format("%d Sunny Stars", helper2()), cur - (tonumber(Core.cur("SummerPearls")) or 0), "Summer Pearls", "Open Sunny Stars: for " .. starPlan.why)
                FarmHub.pickNote.skins = nil
            else
                break
            end
        end
    end
end

function Modes.list()
    local prof = Core.prof()
    if not prof then
        return {
        }
    end
    local levelData = prof.level_data
    local list = {
    }
    local now = os.time()
    local function helper(mode)
        if Modes.hasOwnTeam(mode) then
            local team, why = Modes.ownTeam(mode)
            if not team then
                Modes.skipped[mode.key] = mode.label .. ": " .. tostring(why)
                return
            end
        end
        mode.rec = Modes.rec(mode.key)
        local rotation = Modes.rotation(mode)
        local flag = (mode.rec.restUntil or 0) > now and mode.kind ~= "portal"
            and (not rotation or mode.rec.restRotation == rotation)
        if flag and mode.kind == "daily" and Config.dailyLoop and (mode.rec.restWhy == "losses" or (mode.rec.restWhy == nil and math.abs(mode.rec.restUntil - (tonumber(mode.rec.last) or 0) - 6 * 3600) <= 5)) then
            flag = false
        end
        if flag or not Modes.allowed(mode) then
            return
        end
        if mode.kind == "daily" and not FarmHub.matchOn(mode) and not Config.dailyLoop then
            local ok, res = pcall(Modes.needsHelp, mode)
            if ok and res and not (Config.sim and Modes.canSearch(mode) and not Modes.teamPlan(mode)) then
                Modes.skipped [mode.key] = mode.label .. ": the simulator says your team can't win it alone, and Matchmake The Daily is off"
                return
            end
        end
        mode.mod = mode.mod or Modes.levelMod(mode.level)
        if (mode.kind == "daily" or mode.kind == "challenge") and not (mode.kind == "daily" and Config.dailyLoop) then
            local chOk, chOk2 = Modes.chOk(mode)
            Modes.skipped [mode.key] = not chOk and (mode.label .. ": " .. chOk2) or nil
            if not chOk then
                return
            end
        end
        table.insert(list, mode)
    end
    local live = Brain.live or {
    }
    if (Config.dailyChallenge or Config.onlyChallenges or Config.dailyLoop) and live.daily and live.daily.uuid and live.daily.uuid ~= prof.last_completed_daily_challenge_uuid and live.daily.uuid ~= live.daily.doneUuid and ((live.daily.lost or 0) < 2 or Config.dailyLoop) then
        helper({
            key = "dc",
            kind = "daily",
            level = "__DAILY_CHALLENGE",
            rotation = live.daily.uuid,
            diff = "Hard",
            value = live.daily.value or 300,
            label = "Daily Challenge",
            why = string.format("daily reward ≈%s gems of gems + items",
            Utils.fmt(live.daily.value or 0)),
            mod = live.daily.mod
        })
    end
    if (Config.challenge or Config.onlyChallenges) and live.normal and live.normal.uuid and live.normal.uuid ~= prof.last_completed_challenge_uuid and live.normal.uuid ~= live.normal.doneUuid and (live.normal.expires or 0) > now + 360 and (live.normal.lost or 0) < 2 then
        helper({
            key = "ch",
            kind = "challenge",
            level = live.normal.level,
            rotation = live.normal.uuid,
            diff = "Hard",
            value = live.normal.value or 100,
            label = "Challenge · " .. Modes.levelName(live.normal.level),
            why = "new challenge every 30 min",
            challenge = live.normal.challenge
        })
    end
    local list2 = Utils.list(Core.WLO.WORLD_ORDER)
    local pickStory = Config.pickStory or ""
    local function helper2(arg1, arg2, arg3, arg4)
        if not Modes.done(levelData, arg1, arg2) then
            return {
                key = "st:" .. arg1 .. ":" .. arg2,
                kind = "story",
                first = true,
                level = arg1,
                diff = arg2,
                rank = arg3,
                picked = arg4,
                value = (Core.GS.GEM_REWARD_STORY_FIRST or 60) + Config.unlockValue,
                p0 = arg3 >= 16 and Modes.PRIOR_WIN.new or (arg2 == "Hard" and Modes.PRIOR_WIN.hard or Modes.PRIOR_WIN.story),
                label = Modes.levelName(arg1) .. " (" .. arg2 .. ")",
                why = (arg4 and "your pick · " or "") .. "first clear: " .. (Core.GS.GEM_REWARD_STORY_FIRST or 60) .. " gems + unlocks the next act"
            }
        end
        return {
            key = "st:" .. arg1 .. ":" .. arg2,
            kind = "story",
            level = arg1,
            diff = arg2,
            rank = arg3,
            picked = arg4,
            value = (Core.GS.GEM_REWARD_STORY or 20),
            p0 = arg2 == "Hard" and Modes.PRIOR_WIN.hard or Modes.PRIOR_WIN.story,
            label = Modes.levelName(arg1) .. " (" .. (arg4 and arg2 or "farm") .. ")",
            why = (arg4 and "your pick · " or "") .. (Core.GS.GEM_REWARD_STORY or 20) .. " gems a clear"
        }
    end
    local function helper3(arg1)
        for i, item in ipairs(list2) do
            local world = Core.Worlds [item]
            if world and not world.legend_stage and not world.raid_world then
                for _, item in ipairs(Utils.list(world.levels)) do
                    if Modes.open(item.id) and arg1(item.id, i) then
                        return
                    end
                end
            end
        end
    end
    if not (Config.firstClears or Config.farm or Config.onlyStory) then
    elseif pickStory == "progress" then
        for _, value in ipairs({
            "Normal",
            "Hard"
        }) do
            local value2
            helper3(function(arg1, arg2)
                if Modes.diffOpen(arg1, value) and not Modes.done(levelData, arg1, value) then
                    value2 = helper2(arg1, value, arg2, true)
                    return true
                end
            end)
            if value2 then
                helper(value2)
                break
            end
        end
    elseif pickStory ~= "" then
        local match, match2 = pickStory:match("^st:(.+):(%a+)$")
        if match and Modes.open(match) and Modes.diffOpen(match, match2) then
            helper(helper2(match, match2, 1, true))
        end
    else
        helper3(function(arg1, arg2)
            for _, value in ipairs({
                "Normal",
                "Hard"
            }) do
                if Modes.diffOpen(arg1, value) and not Modes.done(levelData, arg1, value) and (Config.firstClears or Config.onlyStory) then
                    helper(helper2(arg1, value, arg2, false))
                    break
                end
            end
            if Config.farm and arg2 <= 3 and Modes.done(levelData, arg1, "Normal") then
                helper(helper2(arg1, "Normal", arg2, false))
            end
        end)
    end
    local pickRaid = Config.pickRaid or ""
    if Config.raids or Config.onlyRaids then
        for _, item in ipairs(Utils.list(Core.WLO.RAID_WORLD_ORDER)) do
            local world = Core.Worlds [item]
            for _, item in ipairs(Utils.list(world and world.levels)) do
                local level = Core.Levels [item.id]
                if level and Modes.open(item.id) and (pickRaid == "" or pickRaid == "rd:" .. item.id) then
                    local raidDailyTries = tonumber(level._raid_daily_tries)
                    local value = (prof.raid_tries and prof.raid_tries.levels and tonumber(prof.raid_tries.levels [item.id])) or 0
                    if not raidDailyTries or value < raidDailyTries then
                        local count, text = 0, nil
                        for _, levelItem in ipairs(Adventure.levelItems(level)) do
                            count = count + Modes.itemValue(levelItem.item, levelItem.per)
                            if Brain.goalItems [levelItem.item] then
                                text = string.format("≈%.0f %s a run toward your goal", levelItem.per, (Core.Items [levelItem.item] or {
                                }).name or levelItem.item)
                            end
                        end
                        local flag = not Modes.done(levelData, item.id)
                        local overrideGemReward = tonumber(level._override_gem_reward) or (Core.GS.GEM_REWARD_RAID or 75)
                        helper({
                            key = "rd:" .. item.id,
                            kind = "raid",
                            level = item.id,
                            diff = "Hard",
                            first = flag,
                            picked = pickRaid ~= "",
                            value = overrideGemReward + count + (flag and Config.unlockValue or 0),
                            p0 = Modes.PRIOR_WIN.raid,
                            label = Modes.levelName(item.id),
                            why = (pickRaid ~= "" and "your pick · " or "") .. (text and (text .. " · ") or "") .. string.format("raid: %d gems + items%s",
                            overrideGemReward,
                            raidDailyTries and string.format(" · %d/%d tries left",
                            raidDailyTries - value,
                            raidDailyTries) or "")
                        })
                    end
                end
            end
        end
    end
    if (Config.artifact or Config.onlyArtifact) and Brain.live.artifact then
        for _, item in ipairs(Brain.live.artifact.list or {
        }) do
            local level = Core.Levels [item.level]
            if level and Modes.open(item.level) then
                local artifactLeft, artifactLeft2, artifactLeft3 = Modes.artifactLeft(item.level)
                if artifactLeft < artifactLeft3 then
                    local count = 0
                    for _, levelItem in ipairs(Adventure.levelItems(level)) do
                        count = count + Modes.itemValue(levelItem.item, levelItem.per)
                    end
                    local overrideGemReward = tonumber(level._override_gem_reward) or 30
                    helper({
                        key = "ar:" .. item.level,
                        kind = "artifact",
                        level = item.level,
                        world = item.world,
                        diff = "Hard",
                        value = overrideGemReward + count + artifactLeft2 / math.max(1,
                        artifactLeft3 - artifactLeft),
                        label = (Core.Worlds [item.world] or {
                        }).name or Modes.levelName(item.level),
                        why = string.format("Artifact Stage, alone: %d/%d clears this rotation · %d gems a clear + %s gems of milestones to come",
                        artifactLeft,
                        artifactLeft3,
                        overrideGemReward,
                        Utils.fmt(artifactLeft2))
                    })
                end
            end
        end
    end
    local pickLegend = Config.pickLegend or ""
    local pickLegend2 = pickLegend ~= "progress" and pickLegend ~= "" and pickLegend or nil
    if pickLegend == "progress" then
        for _, item in ipairs(Utils.list(Core.WLO.LEGEND_WORLD_ORDER)) do
            local world = Core.Worlds [item]
            for _, item in ipairs(Utils.list(world and world.levels)) do
                if not pickLegend2 and Core.Levels [item.id] and Modes.open(item.id) and not Modes.done(levelData, item.id, "Hard") then
                    pickLegend2 = "st:" .. item.id .. ":Hard"
                end
            end
        end
    end
    if (Config.goals and next(Brain.goalItems)) or Config.onlyLegend or pickLegend ~= "" then
        for _, item in ipairs(Utils.list(Core.WLO.LEGEND_WORLD_ORDER)) do
            local world = Core.Worlds [item]
            for _, item in ipairs(Utils.list(world and world.levels)) do
                local level = Core.Levels [item.id]
                local text = "st:" .. item.id .. ":Hard"
                if level and Modes.open(item.id) and (pickLegend == "" or pickLegend == "progress" or pickLegend == text) then
                    local onlyLegend = Config.onlyLegend or (pickLegend ~= "" and pickLegend ~= "progress")
                    local count, text2, count2 = 0, nil, 0
                    for _, levelItem in ipairs(Adventure.levelItems(level)) do
                        if Brain.goalItems [levelItem.item] then
                            count = count + Modes.itemValue(levelItem.item, levelItem.per)
                            text2 = string.format("≈%.1f %s a run toward your goal", levelItem.per, (Core.Items [levelItem.item] or {
                            }).name or levelItem.item)
                        elseif onlyLegend then
                            count = count + Modes.itemValue(levelItem.item, levelItem.per)
                            count2 = count2 + 1
                        end
                    end
                    if count > 0 or pickLegend2 == text then
                        local flag = not Modes.done(levelData, item.id, "Hard")
                        helper({
                            key = text,
                            kind = "story",
                            legend = true,
                            picked = pickLegend2 == text,
                            level = item.id,
                            diff = "Hard",
                            first = flag,
                            value = count + (flag and ((Core.GS.GEM_REWARD_STORY_FIRST or 60) + Config.unlockValue) or 0),
                            p0 = Modes.PRIOR_WIN.hard,
                            label = Modes.levelName(item.id),
                            why = (pickLegend2 == text and (pickLegend == "progress" and "the next legend stage you haven't beaten · " or "your pick · ") or "") .. (text2 or string.format("legend stage: %d kinds of drops",
                            count2))
                        })
                    end
                end
            end
        end
    end
    local pickInfinite = Config.pickInfinite or ""
    if Config.infinite or Config.onlyInfinite then
        for _, infId in ipairs(Modes.infIds()) do
            if Modes.open(infId) and (pickInfinite == "" or pickInfinite == "inf:" .. infId) then
                local text = "inf:" .. infId
                local infReach, infReach2 = Modes.infReach(text)
                local infDaily, infDaily2, infDaily3 = Modes.infDaily(prof, infId, infReach)
                local ok, res, res2 = pcall(Modes.portalBonus, infId)
                local ok2, res3, res22 = pcall(Modes.missionValue, infId)
                res, res3 = ok and res or 0, ok2 and res3 or 0
                local text2 = (res > 0 and res2 and (" · " .. res2) or "") .. (res3 > 0 and res22 and (" · " .. res22) or "")
                helper({
                    key = text,
                    kind = "infinite",
                    level = infId,
                    diff = "Hard",
                    value = infDaily + res + res3,
                    p0 = 1,
                    reach = infReach,
                    picked = pickInfinite ~= "",
                    portalMap = res > 0 or nil,
                    extra = text2,
                    label = Modes.levelName(infId),
                    why = (pickInfinite ~= "" and "your pick · " or "") .. string.format("until the base falls (≈wave %d%s) · %s",
                    math.floor(infReach + 0.5),
                    infReach2 and "" or ", not played yet",
                    infDaily > 0 and string.format("daily gems: %d up to wave %d",
                    infDaily,
                    infDaily2) or (infDaily3 > 0 and "today's gems claimed" or "no daily gems in reach")) .. text2
                })
            end
        end
    end
    local ok, res = pcall(Modes.portalRows)
    for _, value in ipairs(ok and res or {
    }) do
        helper(value)
    end
    if Config.dungeon or Config.onlyDungeons then
        local value = Dungeon.data()
        if value and (value._started or Config.dungeonStart or Config.onlyDungeons) then
            local ok, res = pcall(Dungeon.pick, value)
            res = ok and res or nil
            local res2, res22, res3 = Dungeon.res(value)
            local ok, res4 = pcall(Dungeon.payValue)
            helper({
                key = "dg",
                kind = "dungeon",
                level = "dungeon",
                diff = "Hard",
                value = (ok and res4) or Config.dungeonValue,
                p0 = res and res.p or Modes.PRIOR_WIN.dungeon,
                started = value._started or nil,
                label = value._started and string.format("Dungeon room %d/%d",
                res and res.d or (Dungeon.depth(value) or 1),
                Dungeon.ROOMS) or "Dungeon (new run)",
                why = value._started and string.format("%s · %d lives · %d coins · chests %d + %d rare",
                res and Dungeon.roomName(res) or "between rooms",
                Dungeon.lives(value),
                res2,
                res22,
                res3) or "a new run: 20 rooms with chests, shops and shrines"
            })
        end
    end
    if (Config.event or Config.onlyCoins or Brain.nextMode) and live.event and Hunt.is(live.event.level) then
        helper(Hunt.row(Modes.rec("ev:" .. tostring(live.event.level))))
    elseif (Config.event or Config.onlyCoins) and live.event and live.event.level then
        local rec = Modes.rec("ev:" .. live.event.level)
        local ratio = rec.runs > 0 and (rec.coins / rec.runs) or 400
        local pullGoal = Adventure.pullGoal()
        local aprilValue = pullGoal and pullGoal.needCoins > 0 and math.max(Config.aprilValue, Config.goalCoinValue) or Config.aprilValue
        helper({
            key = "ev:" .. live.event.level,
            kind = "event",
            level = live.event.level,
            diff = "Hard",
            value = ratio * aprilValue,
            coins = ratio,
            p0 = Modes.PRIOR_WIN.event,
            label = live.event.name or "Event",
            why = string.format("≈%d %s a run (×%.2f gems each%s)",
            math.floor(ratio),
            Modes.coinName(),
            aprilValue,
            pullGoal and pullGoal.needCoins > 0 and (", for " .. Units.name(pullGoal.to)) or "")
        })
    end
    return list
end

-- 2.26: a fixed lineup is shared by maps of the same mode kind.
function Modes.teamKey(train)
    if type(train) == "string" then return train end
    if type(train) ~= "table" then return nil end
    return train.legend and "legend" or train.kind
end

function Modes.hasOwnTeam(train)
    local key = Modes.teamKey(train)
    return key ~= nil and key ~= "dungeon" and type(Config.modeTeams) == "table" and Config.modeTeams[key] ~= nil
end

function Modes.ownTeam(train)
    local key = Modes.teamKey(train)
    if key == "dungeon" then return nil, "dungeon: own team not supported yet" end
    if not Modes.hasOwnTeam(train) then return nil end
    local function fail(why)
        local message = tostring(key) .. ": " .. why .. "; run held"
        Modes._ownErrors = Modes._ownErrors or {}
        if Modes._ownErrors[key] ~= message then
            App.log(1, "TEAM", message)
            Modes._ownErrors[key] = message
        end
        return nil, message
    end
    local saved = Config.modeTeams[key]
    if type(saved) ~= "table" or #saved < 1 or #saved > 6 then return fail("save 1 to 6 units again") end
    local session = Core.session()
    if not (session and session.collection and session.profile_data and session.profile_data.collection) then
        return fail("unit collection unavailable")
    end
    local result, used, reserved = {}, {}, {}
    -- Reserve exact UUIDs first: a missing slot must not steal a later slot's copy.
    for _, slot in ipairs(saved) do
        if type(slot) ~= "table" or type(slot.id) ~= "string" or slot.id == "" or type(slot.uuid) ~= "string" then
            return fail("invalid saved slot")
        end
        local unit = session.collection:get_unit_by_uuid(slot.uuid)
        if unit and unit.unit_id == slot.id then reserved[slot.uuid] = true end
    end
    for _, slot in ipairs(saved) do
        local uuid, unit = slot.uuid, session.collection:get_unit_by_uuid(slot.uuid)
        if not unit or unit.unit_id ~= slot.id then
            uuid = nil
            local best
            local rows = Units.isFarm(slot.id) and Units.rows(slot.id)
            for _, owned in pairs(session.profile_data.collection.owned_units or {}) do
                local candidate = owned.uuid and session.collection:get_unit_by_uuid(owned.uuid)
                if candidate and candidate.unit_id == slot.id and not used[owned.uuid] and not reserved[owned.uuid] then
                    local ok, score
                    if Units.isFarm(slot.id) then
                        ok, score = pcall(Units.farm, candidate, rows and rows.max or 0)
                    else
                        ok, score = pcall(Units.score, candidate)
                    end
                    score = ok and tonumber(score) or 0
                    score = score or 0
                    if not uuid or score > best or (score == best and owned.uuid < uuid) then uuid, best = owned.uuid, score end
                end
            end
        end
        if not uuid or used[uuid] then return fail("missing or duplicate unit " .. slot.id) end
        if uuid ~= slot.uuid then
            Modes._ownSubs = Modes._ownSubs or {}
            local note = tostring(key) .. ":" .. tostring(slot.uuid)
            if not Modes._ownSubs[note] then
                Modes._ownSubs[note] = true
                App.log(1, "TEAM", string.format("%s: the saved %s is gone, your best other copy goes in", tostring(key), Units.name(slot.id)))
            end
        end
        used[uuid] = true
        table.insert(result, uuid)
    end
    if Modes._ownErrors then Modes._ownErrors[key] = nil end
    return result
end

function Modes.ownUnits(train)
    local uuids, why = Modes.ownTeam(train)
    if not uuids then return nil, why end
    local session, units = Core.session(), {}
    for _, uuid in ipairs(uuids) do table.insert(units, session.collection:get_unit_by_uuid(uuid)) end
    return units
end

function Modes.ownProfile(train)
    local uuids = Modes.ownTeam(train)
    return uuids and Modes.ownedProfile(uuids) or nil
end

function Modes.canSearch(train)
    return not Modes.hasOwnTeam(train) and Config.autoTeam and Config.simTeams
end

function Modes.setOwnTeam(key, slots)
    if key == "dungeon" and slots ~= nil then return false, "dungeon: own team not supported yet" end
    local teams = table.clone(type(Config.modeTeams) == "table" and Config.modeTeams or {})
    teams[key] = slots
    Farming.setBase("modeTeams", teams)
    Modes._teamRevision = (Modes._teamRevision or 0) + 1
    Modes._ownErrors, Modes._sigAt, Modes.lastScored = nil, nil, nil
    Brain.simRes, Brain.simTeam = {}, {}
    FarmHub.manualPlan = nil
    if FarmHub.last then FarmHub.last.pick, FarmHub.last.simTeam = nil, nil end
    App.saveSoon()
    return true, slots and (key .. ": equipped team saved") or (key .. ": auto: the farm picks")
end

function Modes.saveOwnTeam(key)
    if Brain.trial or (Brain.train and Brain.train.on) then
        return false, "A trial or training team is on: save once your own team is back"
    end
    local slots = {}
    for _, entry in ipairs(Units.equipped()) do
        if #slots >= 6 then return false, "Equip no more than 6 units" end
        table.insert(slots, { uuid = entry.uuid, id = entry.u.unit_id })
    end
    if #slots == 0 then return false, "Equip at least one unit first" end
    return Modes.setOwnTeam(key, slots)
end

function Modes.ownTeamText(key)
    if key == "dungeon" then return "dungeon: own team not supported yet" end
    if not Modes.hasOwnTeam(key) then return tostring(key) .. ": auto: the farm picks" end
    local names = {}
    for _, slot in ipairs(type(Config.modeTeams[key]) == "table" and Config.modeTeams[key] or {}) do
        table.insert(names, type(slot) == "table" and Units.name(slot.id or "?") or "?")
    end
    local _, why = Modes.ownTeam(key)
    return tostring(key) .. ": " .. table.concat(names, ", ") .. (why and (" · " .. why) or "")
end


function Modes.teamSig()
    if Modes._sigAt and Utils.now() - Modes._sigAt < 20 then
        return Modes._sig
    end
    local list = {
    }
    for _, value in ipairs(Units.equipped()) do
        table.insert(list, value.u)
    end
    Modes._sig, Modes._sigAt = Simulator.sig(list), Utils.now()
    return Modes._sig
end

function Modes.liveChallenge(key)
    if key == "dc" then
        return Brain.live.daily
    elseif key == "ch" then
        return Brain.live.normal
    end
end

function Modes.rotation(mode)
    local live = Modes.liveChallenge(mode.key)
    if mode.rotation ~= nil then
        return tostring(mode.rotation)
    end
    if live and live.uuid ~= nil and (mode.key == "dc" or (live.level == mode.level and live.challenge == mode.challenge)) then
        return tostring(live.uuid)
    end
end

function Modes.outcomes(mode)
    local record = mode.rec or Modes.rec(mode.key)
    if mode.key ~= "ch" and mode.key ~= "dc" then
        return record
    end
    local rotation = Modes.rotation(mode)
    if rotation and record.rotationStats and record.rotationStats.rotation == rotation then
        return record.rotationStats
    end
    return { runs = 0, wins = 0, sec = 0, timed = 0, streak = 0 }
end

function Modes.equippedProfile()
    local units = {}
    for _, entry in ipairs(Units.equipped()) do
        table.insert(units, entry.u)
    end
    return Simulator.profileSig(units)
end

function Modes.ownedProfile(uuids)
    local session = Core.session()
    if not session or type(uuids) ~= "table" or # uuids == 0 then
        return nil
    end
    local units = {}
    for _, uuid in ipairs(uuids) do
        local unit = session.collection:get_unit_by_uuid(uuid)
        if not unit then
            return nil
        end
        table.insert(units, unit)
    end
    return Simulator.profileSig(units)
end

function Modes.teamPlan(mode, base)
    if Modes.hasOwnTeam(mode) then return nil end
    local plan = Brain.simTeam[mode.key]
    if not Config.sim or not Config.simTeams or not plan or not plan.profile or plan.rotation ~= Modes.rotation(mode) or os.time() - (tonumber(plan.at) or 0) >= 600 then
        return nil
    end
    base = base or Modes.ownedProfile(Brain.savedTeam or (Brain.train.on and Brain.train.on.base)) or Modes.equippedProfile()
    if plan.profile == base and plan.targetProfile and plan.targetProfile == Modes.ownedProfile(plan.uuids) then
        return plan
    end
end

function Modes.provenWinner(mode, profile)
    local kind = mode.kind
    if kind ~= "daily" and kind ~= "challenge" and kind ~= "story" and kind ~= "raid" then
        return nil
    end
    local record = mode.rec or Modes.rec(mode.key)
    local rotation = Modes.rotation(mode)
    if record.winProfile and record.winProfile == profile
        and ((kind ~= "daily" and kind ~= "challenge") or (rotation and record.winRotation == rotation)) then
        return { p = 0.7, won = true, margin = "won here with this team" }
    end
end

function Modes.sim(mode, equippedOnly)
    if not Config.sim then
        return nil
    end
    local fixed = Modes.hasOwnTeam(mode)
    local ownProfile = fixed and Modes.ownProfile(mode)
    if fixed and not ownProfile then return nil end
    if not equippedOnly and Modes.canSearch(mode) then
        local plan = Modes.teamPlan(mode)
        if plan and plan.better and plan.prediction then
            return plan.prediction
        end
    end
    local prediction = Brain.simRes[mode.key]
    local profile = ownProfile or Modes.equippedProfile()
    if not equippedOnly and Modes.canSearch(mode) then
        profile = Modes.ownedProfile(Brain.savedTeam or (Brain.train.on and Brain.train.on.base)) or profile
    end
    local proven = Modes.provenWinner(mode, profile)
    if prediction and prediction.p and prediction.profile == profile and prediction.rotation == Modes.rotation(mode)
        and os.time() - (tonumber(prediction.at) or 0) < 6 * 3600 then
        if not proven or (prediction.p >= proven.p and not (prediction.trust and not prediction.trust.ok)) then
            return prediction
        end
    end
    return proven
end

function Modes.nextAct(level)
    Modes._next = Modes._next or {
    }
    local dt2 = Modes._next [level]
    if dt2 == nil then
        local ok, dt = pcall(Core.PSC.get_next_story_level, level)
        dt2 = ok and dt or false
        Modes._next [level] = dt2
    end
    return dt2 or nil
end

function Modes.needsHelp(mode, equippedOnly)
    local prediction = Modes.sim(mode, equippedOnly)
    if prediction and not (prediction.trust and not prediction.trust.ok) then
        return prediction.p < 0.5
    end
    local record = Modes.outcomes(mode)
    return (tonumber(record.soloStreak) or 0) >= 2
end
Modes.MATCHED_DAILY_P = 0.7

function Modes.winP(item)
    if item.kind == "daily" and FarmHub.matchOn(item) and not Config.dailyLoop then
        local ok, res = pcall(Modes.needsHelp, item)
        if ok and res then
            return Modes.MATCHED_DAILY_P
        end
    end
    local outcomes = Modes.outcomes(item)
    local p0 = item.p0 or Modes.PRIOR_WIN [item.kind] or 0.7
    local sim = Modes.sim(item)
    if sim and not (sim.trust and not sim.trust.ok) then
        local calibrated = sim.calibrated or outcomes.runs > 0
        local num = (sim.trust and sim.trust.ok) and 6 or (calibrated and 3 or 1.5)
        local num2 = (calibrated or sim.hopeless) and 0 or 2
        return (outcomes.wins + p0 * num2 + sim.p * num) / (outcomes.runs + num2 + num)
    end
    return (outcomes.wins + p0 * 2) / (outcomes.runs + 2)
end

function Modes.minutes(item, p)
    local outcomes = Modes.outcomes(item)
    local timed = tonumber(outcomes.timed) or 0
    local sim = Modes.sim(item)
    local estimate = sim and (sim.won or item.kind == "infinite") and not (sim.trust and not sim.trust.ok) and tonumber(sim.minutes)
    local value = (timed > 0 and outcomes.sec > 0) and (outcomes.sec / timed / 60) or (estimate and estimate > 0 and estimate) or Modes.PRIOR_MIN[item.kind] or 6
    -- With both outcomes timed, the expected run is p × a win's length + (1 − p) × a loss's, where p is
    -- today's chance to win (it can differ from the past mix of wins and losses).
    local winTimed, lossTimed = tonumber(outcomes.winTimed) or 0, tonumber(outcomes.lossTimed) or 0
    if winTimed > 0 and lossTimed > 0 and item.kind ~= "infinite" and p then
        value = p * (outcomes.winSec / winTimed / 60) + (1 - p) * (outcomes.lossSec / lossTimed / 60)
    end
    return value + Modes.OVERHEAD
end

-- What a loss pays on average (gems), once at least two losses are known.
function Modes.lossValue(item)
    local outcomes = Modes.outcomes(item)
    local losses = tonumber(outcomes.lossTimed) or 0
    if losses < 2 then
        return 0
    end
    return math.max(0, (tonumber(outcomes.lossGems) or 0) / losses)
end

-- New modes get a try: a bonus that fades as runs come in (full at 0 runs, half at 2, a quarter at 6,
-- none from 10), instead of the whole bonus for two runs and nothing after.
function Modes.exploreMul(runs)
    if runs >= 10 then
        return 1
    end
    return 1 + Config.exploreBonus * 2 / (runs + 2)
end

function Modes.score(item)
    local num = ((item.kind == "event" and item.rec.runs > 0) or item.kind == "infinite") and 1 or (item.kind == "dungeon" and item.p0) or Modes.winP(item)
    local minutes = Modes.minutes(item, num)
    -- Full cycle (2.21): p × win reward + (1 − p) × what a loss pays, over the expected run length.
    local lossPay = num < 1 and Modes.lossValue(item) or 0
    local ok, res, res2 = pcall(Strategy.modeBonus, item)
    if ok and (res or 0) > 0 then
        item.teamBonus = res
        if not tostring(item.why):find("for your team", 1, true) then
            item.why = (item.why or "") .. " · " .. res2
        end
    end
    local ratio = (num * (item.value + (item.teamBonus or 0)) + (1 - num) * lossPay) / minutes
    item.baseScore = ratio
    local ok, res, res2 = pcall(Training.valueFor, item)
    if ok and res > 0 then
        local ratio2 = (num * (item.value + res) + (1 - num) * lossPay) / (minutes * res2)
        if ratio2 > ratio then
            ratio, item.train = ratio2, res
        end
    end
    ratio = ratio * Modes.exploreMul(tonumber(Modes.outcomes(item).runs) or 0)
    return ratio
end

function Modes.trialRow()
    local trial = Brain.trial
    if type(trial) ~= "table" or type(trial.list) ~= "table" then
        return nil
    end
    local item = trial.list [tonumber(trial.i) or 1]
    if not item then
        return nil
    end
    return {
        key = trial.key,
        kind = trial.kind or "story",
        level = trial.level,
        diff = trial.diff,
        label = trial.label,
        rec = Modes.rec(trial.key),
        value = 0,
        p0 = 1,
        p = 1,
        score = 0,
        why = string.format("%s %d of %d: %s",
        trial.study and "study run" or "trial",
        tonumber(trial.i) or 1,
        # trial.list,
        Units.name(item))
    }
end

function Modes.trialTeam()
    local trial = Brain.trial
    local item = trial.list [tonumber(trial.i) or 1]
    if Brain.train.on then
        Training.home()
    end
    local session = Core.session()
    local item2, value
    for _, ownedUnit in pairs(session.profile_data.collection.owned_units) do
        if ownedUnit.unit_id == item then
            local unitObj = session.collection:get_unit_by_uuid(ownedUnit.uuid) or ownedUnit
            local ok, res = pcall(Units.score, unitObj)
            res = ok and res or 0
            if not value or res > value then
                item2, value = unitObj, res
            end
        end
    end
    local study = trial.study and Brain.study and Brain.study.id == item and Brain.study or nil
    if study and session.collection:get_unit_by_uuid(study.uuid) then
        item2 = session.collection:get_unit_by_uuid(study.uuid)
    end
    if not item2 then
        App.log(1, "TRIAL", Units.name(item) .. ": no copy of it any more, skipped")
        trial.i = (tonumber(trial.i) or 1) + 1
        return false
    end
    local savedTeam = table.clone(Brain.savedTeam or Training.team())
    local flag = table.find(savedTeam, item2.uuid) ~= nil
    if not flag then
        local value, value2
        for i, value3 in ipairs(savedTeam) do
            local unitObj = session.collection:get_unit_by_uuid(value3)
            if unitObj and not Units.isFarm(unitObj.unit_id) and not Units.allyBuff(unitObj.unit_id) then
                local ok, res = pcall(Units.score, unitObj)
                res = ok and res or 0
                if not value2 or res < value2 then
                    value, value2 = i, res
                end
            end
        end
        if value then
            savedTeam [value] = item2.uuid
        else
            table.insert(savedTeam, item2.uuid)
        end
    end
    for _, summoner in ipairs(study and study.summoners or {
    }) do
        if not table.find(savedTeam, summoner) and session.collection:get_unit_by_uuid(summoner) then
            local value, value2
            for i, value3 in ipairs(savedTeam) do
                local unitObj = session.collection:get_unit_by_uuid(value3)
                if unitObj and value3 ~= item2.uuid and not table.find(study.summoners, value3) and not Units.isFarm(unitObj.unit_id) and not Units.allyBuff(unitObj.unit_id) then
                    local ok, res = pcall(Units.score, unitObj)
                    res = ok and res or 0
                    if not value2 or res < value2 then
                        value, value2 = i, res
                    end
                end
            end
            if value then
                savedTeam [value] = summoner
            elseif # savedTeam < 6 then
                table.insert(savedTeam, summoner)
            end
        end
    end
    if not Training.same(Training.team(), savedTeam) then
        FarmHub.equipTeam(savedTeam, (study and "study run for " or "trial run for ") .. Units.name(item))
    end
    return true
end

function Match.trialDone(arg1, arg2)
    local trial = Brain.trial
    local trialId = Match.trialId
    if type(trial) ~= "table" or not trialId then
        return
    end
    local damageShares, damageShares2 = Match.damageShares()
    damageShares2 = damageShares2 or 0
    local value = damageShares and (damageShares [trialId] or 0) * damageShares2 or 0
    local rows = Units.rows(trialId)
    local count, count2, count3 = 0, 0, 0
    for _, value in pairs(Match.ownDealt or {
    }) do
        if value.id == trialId then
            count = count + 1
            count2 = math.max(count2, value.lvl or 0)
            count3 = count3 + (tonumber(rows and rows [0] and rows [0].cost) or 0)
            for i = 1, value.lvl or 0 do
                count3 = count3 + (tonumber(rows and rows [i] and rows [i].cost) or 0)
            end
        end
    end
    local list = {
    }
    for damageShareKey, damageShare in pairs(damageShares or {
    }) do
        if damageShareKey ~= trialId and damageShare >= 0.005 then
            table.insert(list, {
                n = damageShareKey == "helpers" and damageShareKey or Units.name(damageShareKey),
                v = damageShare
            })
        end
    end
    table.sort(list, function(arg1, arg2)
        return arg1.v > arg2.v
    end)
    local list2 = {
    }
    for _, item in ipairs(list) do
        table.insert(list2, string.format("%s %d%%", (item.n:gsub(" %(.+%)", "")), math.floor(item.v * 100 + 0.5)))
    end
    local trialSim = Match.trialSim
    local text = trialSim and string.format("the sim expected %s alone: %s at wave %d, %s damage, upgrade %s", (Units.name(trialId):gsub(" %(.+%)", "")), trialSim.won and "wins" or "falls", trialSim.wave, Utils.fmt(trialSim.dealt or 0), tostring(trialSim.lvl or "?")) or "no sim reading"
    local text2 = string.format("%s · %s at wave %d of %d in %.1f min · dealt %s, %d%% of %s · %d copies, top upgrade %d of %d, about ¥%s · ability cast %d times · stood by: %s · %s", Units.name(trialId), arg1 and "won" or "lost", Match.wave(), Match.total or 0, (arg2 or 0) / 60, Utils.fmt(value), math.floor((damageShares and damageShares [trialId] or 0) * 100 + 0.5), Utils.fmt(damageShares2), count, count2, rows and rows.max or 0, Utils.fmt(count3), Match.casts and Match.casts [trialId] or 0, # list2 > 0 and table.concat(list2, ", ") or "nobody", text)
    App.log(1, "TRIAL", text2)
    local str = "AA_SmartFarm/trials.txt"
    local ok, res = pcall(readfile, str)
    pcall(writefile, str, (ok and type(res) == "string" and res or "") .. os.date("%H:%M ") .. text2 .. "\n")
    do
        local calRun = Match.calRun or {
        }
        local list = {
        }
        if (calRun.potSum or 0) > 0 then
            table.insert(list, string.format("real/listed damage %.2f", (calRun.dealtSum or 0) / calRun.potSum))
        end
        local str = "AA_SmartFarm/trial_trace.txt"
        local ok, res = pcall(readfile, str)
        pcall(writefile, str, (ok and type(res) == "string" and res or "") .. os.date("%H:%M ") .. Units.name(trialId) .. " " .. table.concat(list, " ") .. "\n" .. table.concat(Match.trialTrace or {
        }, "\n") .. "\n\n")
    end
    trial.results = type(trial.results) == "table" and trial.results or {
    }
    table.insert(trial.results, {
        id = trialId,
        won = arg1 and true or false,
        wave = Match.wave(),
        sec = arg2,
        dealt = value,
        share = damageShares and damageShares [trialId] or 0,
        sum = damageShares2,
        copies = count,
        lvl = count2,
        yen = count3,
        casts = Match.casts and Match.casts [trialId] or 0,
        sim = trialSim
    })
    if trial.study and Brain.study and Brain.study.id == trialId then
        local ok, res = pcall(Reports.studyRecord, trialId, trial.results [# trial.results])
        if ok and res then
            Brain.study.records = type(Brain.study.records) == "table" and Brain.study.records or {
            }
            table.insert(Brain.study.records, res.run)
            local ok, res2 = pcall(Reports.studyFit, res)
            if ok and res2 then
                table.insert(Brain.studyQ, res2)
                while # Brain.studyQ > 10 do
                    table.remove(Brain.studyQ, 1)
                end
                task.spawn(function()
                    pcall(Reports.sendStudy, 3)
                end)
                local ok, res = pcall(readfile, Core.FOLDER .. "/studies.txt")
                pcall(writefile, Core.FOLDER .. "/studies.txt", (ok and type(res) == "string" and res or "") .. os.date("%m-%d %H:%M ") .. res2 .. "\n")
            end
            App.log(1, "STUDY", Reports.studyLine(res))
        else
            App.log(1, "ERROR", "study record: " .. tostring(res))
        end
        local value = type(Brain.studied [trialId]) == "table" and Brain.studied [trialId] or {
        }
        Brain.studied [trialId] = {
            runs = (tonumber(value.runs) or 0) + 1,
            trials = value.trials,
            at = os.time()
        }
    elseif trialId then
        local value = type(Brain.studied [trialId]) == "table" and Brain.studied [trialId] or {
        }
        Brain.studied [trialId] = {
            runs = value.runs,
            trials = (tonumber(value.trials) or 0) + 1,
            at = os.time()
        }
    end
    trial.i = (tonumber(trial.i) or 1) + 1
    if not trial.list [trial.i] then
        App.log(1, "TRIAL", "all trial runs done: your own team goes back in")
        Brain.trial = nil
        if trial.study and Brain.study then
            Brain.study.done = os.time()
            App.log(1, "STUDY", Units.name(Brain.study.id) .. ": study done, " .. # (Brain.study.records or {
            }) .. " runs")
            if Brain.study.smart then
                local ok, res, res2 = pcall(FarmHub.studyStart)
                if ok then
                    App.log(1, "STUDY", "Smart Study, next: " .. tostring(res2))
                else
                    App.log(1, "ERROR", "Smart Study: " .. tostring(res))
                end
            elseif Brain.study.holdAfter then
                Brain.holdLobby = {
                    why = "the study is done",
                    at = os.time()
                }
            end
        end
    end
    App.saveNow()
end
Reports.STUDY_WORDS = {
    "summon",
    "spawn",
    "minion",
    "takedown",
    "kill",
    "dead",
    "revive",
    "raise",
    "buff",
    "ally",
    "allies",
    "aura",
    "slow",
    "stun",
    "freeze",
    "burn",
    "bleed",
    "poison",
    "wither",
    "range",
    "cooldown",
    "spa",
    "crit",
    "yen",
    "money",
    "shield",
    "heal",
    "stack",
    "boss",
    "flying",
    "hill",
    "mark",
    "every",
    "chance"
}

function Reports.r3(arg1)
    arg1 = tonumber(arg1)
    return arg1 and math.floor(arg1 * 1000 + 0.5) / 1000 or nil
end

function Reports.atkBrief(res)
    if type(res) ~= "table" then
        return nil
    end
    local info = {
        n = Reports.r3(res.n),
        hits = res.hits
    }
    if (res.slow or 0) > 0 then
        info.slow = Reports.r3(res.slowPct)
        info.slowTime = Reports.r3(res.slowTime)
    end
    if (res.stun or 0) > 0 then
        info.stun = Reports.r3(res.stun)
    end
    if (res.dot or 0) > 0 then
        info.dot = Reports.r3(res.dot)
    end
    if res.bleed then
        info.bleed = true
    end
    if (res.amp or 0) > 0 then
        info.amp = Reports.r3(res.amp)
    end
    if res.full then
        info.full = true
    end
    if res.wholeMap then
        info.wholeMap = true
    end
    if res.breakShields then
        info.breakShields = true
    end
    if res.ally then
        info.allyBuff = res.ally.types
        info.allyTime = res.ally.time
    end
    if res.allyCd then
        info.allyCd = res.allyCd
    end
    if res.allyRange then
        info.allyRange = res.allyRange
    end
    if res.selfDmg then
        info.selfDmg = res.selfDmg
    end
    if res.baseSafe then
        info.baseSafe = res.baseSafe
    end
    return info
end

function Reports.readPassives(unitId)
    local field = Units.field(unitId, "passives")
    local list = {
    }
    for key, value in pairs(type(field) == "table" and field or {
    }) do
        if type(value) == "table" then
            local replaced = tostring(value.description or ""):gsub("<[^>]+>", ""):gsub("%s+", " ")
            local replaced2 = replaced:lower()
            local info = {
                name = tostring(value.name or key),
                text = replaced:sub(1,
                400)
            }
            local list2 = {
            }
            for key in replaced2:gmatch("([%d%.]+)%%") do
                if tonumber(key) then
                    table.insert(list2, tonumber(key))
                end
            end
            if # list2 > 0 then
                info.pct = list2
            end
            info.every = tonumber(replaced2:match("every (%d+) attacks?")) or tonumber(replaced2:match("every (%d+) hits?")) or tonumber(replaced2:match("every (%d+) takedowns?"))
            info.sec = tonumber(replaced2:match("([%d%.]+) ?sec"))
            info.upTo = tonumber(replaced2:match("up to (%d+)"))
            local list2 = {
            }
            for _, studyWord in ipairs(Reports.STUDY_WORDS) do
                if replaced2:find(studyWord, 1, true) then
                    table.insert(list2, studyWord)
                end
            end
            if # list2 > 0 then
                info.tags = list2
            end
            table.insert(list, info)
        end
    end
    table.sort(list, function(arg1, arg2)
        return arg1.name < arg2.name
    end)
    return list
end

function Reports.readAbility(unitId)
    local rows = Units.rows(unitId)
    local field, value = Units.field(unitId, "active_attack"), nil
    for i = 0, rows and rows.max or - 1 do
        if rows [i] and rows [i].active then
            field, value = field or rows [i].active, value or i
        end
    end
    if not field then
        return nil
    end
    local attack = Core.Attacks [field] or Units.fillAttack(field)
    local ok, res = pcall(Units.attackInfo, field)
    local replaced = type(attack) == "table" and type(attack.active_description) == "string" and attack.active_description:gsub("<[^>]+>", ""):sub(1, 300) or nil
    local field2 = Units.field(unitId, "active_attack_stats")
    return {
        id = field,
        name = type(attack) == "table" and type(attack.name) == "string" and attack.name or nil,
        text = replaced,
        from = value,
        cd = type(field2) == "table" and tonumber(field2.attack_cooldown) or (rows and value and rows [value] and rows [value].activeCd) or nil,
        does = ok and Reports.atkBrief(res) or nil
    }
end

function Reports.readAttacks(unitId)
    local rows = Units.rows(unitId)
    local list, atk = {
    }, nil
    for i = 0, rows and rows.max or - 1 do
        local row = rows [i]
        if row and row.atk and row.atk ~= atk then
            atk = row.atk
            local ok, res = pcall(Units.attackInfo, row.atk, row.range)
            table.insert(list, {
                from = i,
                id = row.atk,
                does = ok and Reports.atkBrief(res) or nil
            })
            if # list >= 6 then
                break
            end
        end
    end
    return list
end

function Reports.studyProfile(unitId)
    local unit = Core.Units [unitId] or {
    }
    local rows = Units.rows(unitId)
    local info = {
        id = unitId,
        name = Units.name(unitId),
        rarity = unit.rarity,
        cost = tonumber(unit.cost),
        type = unit._base_damage_type,
        cap = tonumber(Units.field(unitId,
        "spawn_cap")),
        crit = tonumber(unit.physical_crit_chance),
        farm = Units.isFarm(unitId) or nil,
        hill = unit.hill_unit or nil,
        hidden = Brain.hidden [unitId] or nil,
        known = rows ~= nil and (rows.max or 0) > 0,
        ups = rows and rows.max or 0
    }
    if info.known then
        local row, row2 = rows [0], rows [rows.max]
        local count = 0
        for i = 0, rows.max do
            count = count + (tonumber(rows [i].cost) or 0)
        end
        info.first = {
            dmg = row.damage,
            cd = Reports.r3(row.cd),
            range = row.range,
            cost = row.cost
        }
        info.last = {
            dmg = row2.damage,
            cd = Reports.r3(row2.cd),
            range = row2.range,
            farm = (tonumber(row2.farm) or 0) > 0 and row2.farm or nil
        }
        info.totalCost = count
    end
    info.passives = Reports.readPassives(unitId)
    info.ability = Reports.readAbility(unitId)
    info.attacks = Reports.readAttacks(unitId)
    return info
end

function FarmHub.studyRole(unitId, studyProfile)
    local info = {
        kinds = {
        }
    }
    local str = ""
    for _, passive in ipairs(studyProfile.passives or {
    }) do
        str = str .. " " .. tostring(passive.text):lower()
    end
    if studyProfile.ability and studyProfile.ability.text then
        str = str .. " " .. studyProfile.ability.text:lower()
    end
    local function helper(arg1)
        table.insert(info.kinds, arg1)
    end
    if Units.isFarm(unitId) then
        helper("farm")
    end
    if Units.BLESS.by [unitId] or (str:find("minion", 1, true) and str:find("summon", 1, true)) then
        helper("summon buffer")
        info.team, info.summoners = true, true
    elseif Units.SUMMONER [unitId] or (Units.DRONES and Units.DRONES [unitId]) or str:find("summon", 1, true) or str:find("spawn", 1, true) then
        helper("summoner")
    end
    if Units.allyBuff(unitId) or Units.idol(unitId) or (studyProfile.ability and studyProfile.ability.does and studyProfile.ability.does.allyBuff) then
        helper("buffer")
        info.team = true
    end
    if Units.ENTRY [unitId] or str:find("dead", 1, true) or str:find("raise", 1, true) or str:find("revive", 1, true) then
        helper("needs kills")
        info.entry = true
    end
    if not studyProfile.known then
        helper("not read yet")
        info.team, info.first = true, true
    end
    if # info.kinds == 0 then
        helper("attacker")
    end
    return info
end

function FarmHub.studySummoners(unitId)
    local session = Core.session()
    local list = {
    }
    for ownedUnitKey, ownedUnit in pairs(session.profile_data.collection.owned_units) do
        local unitId2 = ownedUnit.unit_id
        if unitId2 ~= unitId and (Units.SUMMONER [unitId2] or (Units.DRONES and Units.DRONES [unitId2]) or (Units.summonShare and Units.summonShare(unitId2) >= 0.3)) then
            local unitObj = session.collection:get_unit_by_uuid(ownedUnitKey) or ownedUnit
            local ok, res = pcall(Units.score, unitObj)
            res = ok and res or 0
            if not list [unitId2] or res > list [unitId2].sc then
                list [unitId2] = {
                    uuid = ownedUnitKey,
                    sc = res
                }
            end
        end
    end
    local list2 = {
    }
    for itemKey, item in pairs(list) do
        table.insert(list2, {
            id = itemKey,
            uuid = item.uuid,
            sc = item.sc
        })
    end
    table.sort(list2, function(arg1, arg2)
        return arg1.sc > arg2.sc
    end)
    local list = {
    }
    for i = 1, math.min(2, # list2) do
        table.insert(list, list2 [i].uuid)
    end
    return list
end

function FarmHub.studyMap()
    local value, wins
    for modeKey, mode in pairs(Brain.modes or {
    }) do
        local match = tostring(modeKey):match("^st:(.+):Normal$")
        if match and (tonumber(mode.wins) or 0) > 0 and (not wins or mode.wins > wins) then
            value, wins = match, mode.wins
        end
    end
    value = value or "namek_level_1"
    return "st:" .. value .. ":Normal", value, "Normal", Modes.levelName(value) .. " (Normal)"
end

function FarmHub.studyPlanText(unitId, studyProfile, studyRole)
    local list = {
    }
    local list2 = {
    }
    for _, passive in ipairs(studyProfile.passives or {
    }) do
        table.insert(list2, passive.name)
    end
    table.insert(list, string.format("%s: read as %s.", Units.name(unitId), table.concat(studyRole.kinds, ", ")))
    if studyRole.first then
        table.insert(list, "The game hides this unit's upgrades, ability and passives until it plays, and no match has sent them yet: the first run reads them, with your whole team fighting.")
    else
        table.insert(list, (# list2 > 0 and ("Passives: " .. table.concat(list2, ", ") .. ".") or (studyProfile.hidden and "Passives: the game sends them only in a match, so the first run reads them." or "Passives: none.")) .. " " .. (studyProfile.ability and string.format("Ability: %s%s.", tostring(studyProfile.ability.name or studyProfile.ability.id), studyProfile.ability.cd and string.format(", every %ds", math.floor(studyProfile.ability.cd + 0.5)) or "") or "No ability."))
    end
    local str = studyRole.team and "with your whole team fighting" or "alone with the yen, the rest of your team standing by"
    if studyRole.summoners then
        local list = {
        }
        local session = Core.session()
        for _, studySummoner in ipairs(FarmHub.studySummoners(unitId)) do
            local unitObj = session and session.collection:get_unit_by_uuid(studySummoner)
            if unitObj then
                table.insert(list, Units.name(unitObj.unit_id))
            end
        end
        str = str .. (# list > 0 and (", with your summoners " .. table.concat(list, " and ")) or ", but you have no summoner to buff")
    end
    if studyRole.entry then
        str = str .. ", at the road's entrance (it needs kills)"
    end
    local _, _, _, studyMap4 = FarmHub.studyMap()
    table.insert(list, string.format("Test: %s, on %s.", str, studyMap4))
    return table.concat(list, "\n")
end

function FarmHub.studySeed()
    if Brain.studiedSeeded then
        return
    end
    Brain.studiedSeeded = true
    local ok, res = pcall(readfile, Core.FOLDER .. "/trials.txt")
    if not (ok and type(res) == "string") then
        return
    end
    local list = {
    }
    for unitKey, unit in pairs(Core.Units) do
        if type(unit) == "table" then
            list [Units.name(unitKey)] = list [Units.name(unitKey)] or unitKey
        end
    end
    local count = 0
    for key in res:gmatch("[^\n]+") do
        local match = key:match("^%d%d:%d%d (.-) · ")
        local item = match and list [match]
        if item then
            local value = type(Brain.studied [item]) == "table" and Brain.studied [item] or {
            }
            Brain.studied [item] = {
                runs = value.runs,
                trials = (tonumber(value.trials) or 0) + 1,
                at = value.at or 0
            }
            count = count + 1
        end
    end
    if count > 0 then
        App.log(1, "STUDY", string.format("%d trial runs from before count as trained (trials.txt)", count))
    end
    App.saveSoon()
end

function FarmHub.studyNext()
    FarmHub.studySeed()
    local session = Core.session()
    local list = {
    }
    for ownedUnitKey, ownedUnit in pairs(session and session.profile_data.collection.owned_units or {
    }) do
        local unitId = ownedUnit.unit_id
        if Core.Units [unitId] and not Brain.studied [unitId] then
            local unitObj = session.collection:get_unit_by_uuid(ownedUnitKey) or ownedUnit
            local ok, res = pcall(Units.score, unitObj)
            res = ok and tonumber(res) or 0
            if not list [unitId] or res > list [unitId].sc then
                list [unitId] = {
                    u = unitObj,
                    sc = res
                }
            end
        end
    end
    local value
    for _, item in pairs(list) do
        if not value or item.sc > value.sc then
            value = item
        end
    end
    return value and value.u or nil
end

function FarmHub.studyStart()
    local session = Core.session()
    local flag = Config.studyUnit == "smart"
    local studyNext
    if flag then
        studyNext = FarmHub.studyNext()
    else
        studyNext = session and Config.studyUnit ~= "" and session.collection:get_unit_by_uuid(Config.studyUnit)
    end
    if not studyNext then
        if flag and Brain.study then
            Brain.study.smart = nil
        end
        return false, flag and "every unit you own has been studied" or "pick a unit to study first"
    end
    if Brain.trial and not Brain.trial.study then
        return false, "trial runs are going: start the study after them"
    end
    local unitId = studyNext.unit_id
    local studyProfile = Reports.studyProfile(unitId)
    local studyRole = FarmHub.studyRole(unitId, studyProfile)
    local studyMap, studyMap2, studyMap3, studyMap4 = FarmHub.studyMap()
    local studyRuns = math.clamp(math.floor(tonumber(Config.studyRuns) or 2), 1, 5)
    local list = {
    }
    for i = 1, studyRuns do
        list [i] = unitId
    end
    Brain.study = {
        uuid = studyNext.uuid,
        id = unitId,
        n = studyRuns,
        role = studyRole,
        summoners = studyRole.summoners and FarmHub.studySummoners(unitId) or nil,
        key = studyMap,
        label = studyMap4,
        at = os.time(),
        records = {
        },
        smart = flag or nil
    }
    Brain.trial = {
        key = studyMap,
        kind = "story",
        level = studyMap2,
        diff = studyMap3,
        label = studyMap4,
        list = list,
        i = 1,
        study = true
    }
    FarmHub.studyCache = nil
    App.log(1, "STUDY", string.format("%s: %d run%s · %s", Units.name(unitId), studyRuns, studyRuns == 1 and "" or "s", FarmHub.studyPlanText(unitId, studyProfile, studyRole):gsub("\n", " ")))
    App.saveNow()
    return true, string.format("%s: %d run%s on %s%s", Units.name(unitId), studyRuns, studyRuns == 1 and "" or "s", studyMap4, Config.master and (Brain.holdLobby and " once you press Start Farming Again" or "") or " once you press Start Auto Farming")
end

function FarmHub.studyStop()
    local study = (Brain.trial and Brain.trial.study) or (Brain.study and not Brain.study.done)
    if Brain.trial and Brain.trial.study then
        Brain.trial = nil
    end
    if Brain.study and not Brain.study.done then
        Brain.study.done, Brain.study.stopped = os.time(), true
        App.log(1, "STUDY", Units.name(Brain.study.id) .. ": study stopped (you pressed Stop Study)")
    end
    FarmHub.studyCache = nil
    App.saveNow()
    return study
end

function FarmHub.studyText()
    local study = Brain.study
    local study2 = study and not study.done and Brain.trial and Brain.trial.study
    if not study2 then
        local str = ""
        if study and study.done then
            local record = study.records and study.records [# study.records]
            str = string.format("Last study: %s, %d run%s%s.%s\n", Units.name(study.id), # (study.records or {
            }), # (study.records or {
            }) == 1 and "" or "s", study.stopped and " (stopped)" or "", record and string.format(" Last run: %s at wave %d, dealt %s (%d%%), ability cast %d times.", record.won and "won" or "lost", record.wave or 0, Utils.fmt(record.dealt or 0), math.floor((record.share or 0) * 100 + 0.5), record.casts or 0) or "")
        end
        local count = 0
        for _ in pairs(Brain.studied) do
            count = count + 1
        end
        if count > 0 then
            str = str .. string.format("%d kind%s of unit studied so far (✓ in the list).\n", count, count == 1 and "" or "s")
        end
        if Config.studyUnit == "" then
            return str .. "Pick a unit, or Smart. The farm reads its passives and ability, plays real matches with it, and saves what it learned locally."
        end
        local session = Core.session()
        local studyNext
        if Config.studyUnit == "smart" then
            studyNext = FarmHub.studyNext()
            if not studyNext then
                return str .. "Smart Study: every unit you own has been studied."
            end
            str = str .. "Smart Study goes down your units from the strongest not studied yet. Next up:\n"
        else
            studyNext = session and session.collection:get_unit_by_uuid(Config.studyUnit)
        end
        if not studyNext then
            return str .. "That unit is gone: pick another."
        end
        local studyCache = FarmHub.studyCache
        if not (studyCache and studyCache.uuid == studyNext.uuid and Utils.now() - studyCache.at < 30) then
            local ok, res = pcall(function()
                local studyProfile = Reports.studyProfile(studyNext.unit_id)
                return FarmHub.studyPlanText(studyNext.unit_id, studyProfile, FarmHub.studyRole(studyNext.unit_id, studyProfile))
            end)
            studyCache = {
                uuid = studyNext.uuid,
                at = Utils.now(),
                text = ok and res or ("Couldn't read it: " .. tostring(res))
            }
            FarmHub.studyCache = studyCache
        end
        return str .. studyCache.text .. "\nPress Start Study to begin."
    end
    local i = tonumber(Brain.trial.i) or 1
    return string.format("Studying %s: run %d of %d on %s, %s.%s%s", Units.name(study.id), math.min(i, study.n), study.n, tostring(study.label), study.role and study.role.team and "with your team fighting" or "alone with the yen", study.smart and " Smart Study: then the next strongest unit not studied yet." or "", Config.master and (Brain.holdLobby and " Waiting: press Start Farming Again." or "") or " Waiting: press Start Auto Farming on Home.")
end

function Reports.studyRecord(arg1, simResult)
    simResult = type(simResult) == "table" and simResult or {
    }
    local studyProfile = Reports.studyProfile(arg1)
    local ok, res = pcall(Match.summonSplit)
    local value = ok and type(res) == "table" and res [arg1]
    local count = 0
    for _, unit in ipairs(Match.mine or {
    }) do
        local stats = unit._stats
        local takedownCount = stats:FindFirstChild("takedown_count")
        if stats.id.Value == arg1 and takedownCount then
            count = count + (tonumber(takedownCount.Value) or 0)
        end
    end
    local toggle = Brain.toggles [arg1]
    local calRun = Match.calRun or {
    }
    local list = {
    }
    for _, member in ipairs(Match.team or {
    }) do
        if member.id ~= arg1 then
            table.insert(list, member.id)
        end
    end
    local ok, res = pcall(Match.damageShares)
    local list2 = {
    }
    if ok and type(res) == "table" then
        for key, value in pairs(res) do
            if (tonumber(value) or 0) >= 0.005 then
                list2 [key] = Reports.r3(value)
            end
        end
    end
    local count2 = 0
    for _ in pairs(Match.helperDealt or {
    }) do
        count2 = count2 + 1
    end
    local info = {
        map = Match.ld.map,
        level = Match.ld.id,
        mode = Match.key,
        how = (Brain.study and Brain.study.role and Brain.study.role.team) and "team" or "solo",
        won = simResult.won,
        wave = simResult.wave,
        total = Match.total,
        sec = math.floor(tonumber(simResult.sec) or 0),
        dealt = math.floor(tonumber(simResult.dealt) or 0),
        share = Reports.r3(simResult.share),
        copies = simResult.copies,
        top = simResult.lvl,
        yen = simResult.yen,
        casts = simResult.casts,
        summons = value and Reports.r3(value.share) or nil,
        takedowns = count,
        realVsListed = (calRun.potSum or 0) > 0 and Reports.r3((calRun.dealtSum or 0) / calRun.potSum) or nil,
        toggle = type(toggle) == "table" and {
            from = toggle.from,
            fill = Reports.r3(toggle.fill),
            drain = Reports.r3(toggle.drain)
        } or nil,
        sim = type(simResult.sim) == "table" and {
            won = simResult.sim.won,
            wave = simResult.sim.wave,
            dealt = math.floor(tonumber(simResult.sim.dealt) or 0)
        } or nil,
        mates = list,
        teamShares = next(list2) and list2 or nil,
        teamDealt = math.floor(tonumber(simResult.sum) or 0),
        helpers = count2
    }
    return {
        v = VERSION,
        id = Brain.anonId,
        at = os.time(),
        unit = studyProfile,
        role = Brain.study and Brain.study.role and Brain.study.role.kinds or nil,
        run = info
    }
end

function Reports.studyFit(arg1)
    local json = Utils.json(arg1)
    if # json <= 3900 then
        return json
    end
    for _, value in ipairs({
        200,
        100
    }) do
        for _, passive in ipairs(arg1.unit.passives or {
        }) do
            passive.text = tostring(passive.text):sub(1, value)
        end
        json = Utils.json(arg1)
        if # json <= 3900 then
            return json
        end
    end
    for _, attack in ipairs(arg1.unit.attacks or {
    }) do
        attack.does = nil
    end
    if arg1.unit.ability then
        arg1.unit.ability.text = arg1.unit.ability.text and arg1.unit.ability.text:sub(1, 120)
    end
    arg1.run.mates = nil
    json = Utils.json(arg1)
    if # json <= 3900 then
        return json
    end
    arg1.unit.attacks = nil
    return Utils.json(arg1):sub(1, 3900)
end

function Reports.sendStudy(arg1)
    if not (Config.shareStats and Core.WEBHOOK_URL ~= "") then
        return
    end
    for i = 1, math.max(1, tonumber(arg1) or 1) do
        if # Brain.studyQ == 0 then
            return
        end
        local now = Utils.now()
        while Reports.sending and Utils.now() - now < 8 do
            task.wait(0.25)
        end
        if Reports.sending then
            return
        end
        Reports.sending = true
        local ok, res = pcall(Reports.postEmbed, string.format("🎌 AA · study · %s · v%s", tostring(Brain.anonId), VERSION), "```json\n" .. Brain.studyQ [1] .. "\n```")
        Reports.sending = nil
        if not (ok and res) then
            return
        end
        table.remove(Brain.studyQ, 1)
        Brain.studySent = (tonumber(Brain.studySent) or 0) + 1
        pcall(App.saveNow)
        if # Brain.studyQ > 0 then
            task.wait(1.5)
        end
    end
end

function Reports.studyLine(res)
    local unit, run = res.unit or {
    }, res.run or {
    }
    local list = {
    }
    for _, passive in ipairs(unit.passives or {
    }) do
        table.insert(list, passive.name .. (passive.every and (" (every " .. passive.every .. ")") or "") .. (passive.pct and (" " .. table.concat(passive.pct, "/") .. "%") or ""))
    end
    local text = unit.ability and string.format("%s%s", tostring(unit.ability.name or unit.ability.id), unit.ability.cd and string.format(" every %ds", math.floor(unit.ability.cd + 0.5)) or "") or "none"
    return string.format("%s · %s at wave %s in %.1f min, %s · dealt %s (%d%%)%s · %d takedowns · ability %s, cast %d · passives: %s%s · read %d upgrades, %d attacks", tostring(unit.name), run.won and "won" or "lost", tostring(run.wave), (run.sec or 0) / 60, run.how == "team" and "team fighting" or "alone with the yen", Utils.fmt(run.dealt or 0), math.floor((run.share or 0) * 100 + 0.5), run.summons and string.format(", %d%% of it from summons", math.floor(run.summons * 100 + 0.5)) or "", run.takedowns or 0, text, run.casts or 0, # list > 0 and table.concat(list, ", ") or "none", run.toggle and string.format(" · switch ability from upgrade %s", tostring(run.toggle.from)) or "", unit.ups or 0, # (unit.attacks or {
    }))
end

function Modes.pick()
    local trialRow = Modes.trialRow()
    if trialRow then
        Modes.lastScored = {
            trialRow
        }
        return trialRow
    end
    local list = Modes.list()
    for _, item in ipairs(list) do
        item.score = Modes.score(item)
        item.p = Modes.winP(item)
        local sim = Modes.sim(item)
        if sim and not tostring(item.why):find("sim:") then
            local flag = sim.trust and not sim.trust.ok
            item.why = (item.why or "") .. " · sim: " .. (flag and string.format(sim.trust.ratio < 0.1 and "not trusted here (off ×%.2f vs real runs)" or "not trusted here (off ×%.1f vs real runs)", sim.trust.ratio) or tostring(sim.playing or sim.margin))
        end
        if item.train then
            item.why = (item.why or "") .. string.format(" · takedown training ≈%d gems of progress", math.floor(item.train + 0.5))
        end
    end
    table.sort(list, function(arg1, arg2)
        return arg1.score > arg2.score
    end)
    for i, item in ipairs(list) do
        if item.kind == "dungeon" and item.started then
            if i > 1 and list [1].kind ~= "daily" then
                table.remove(list, i)
                table.insert(list, 1, item)
                item.why = "finishing the run · " .. (item.why or "")
            end
            break
        end
    end
    if Config.autoEvolve and Config.evolveUnit ~= "" then
        local item = list [1] and list [1].kind == "daily" and list [1] or nil
        local list2, list3 = {
        }, {
        }
        for _, item2 in ipairs(list) do
            if item2 ~= item then
                if Modes.dropsGoal(item2) or item2.train then
                    item2.why = "for your focus unit · " .. (item2.why or "")
                    table.insert(list2, item2)
                else
                    table.insert(list3, item2)
                end
            end
        end
        if # list2 > 0 then
            list = {
            }
            if item then
                table.insert(list, item)
            end
            for _, item in ipairs(list2) do
                table.insert(list, item)
            end
            for _, item in ipairs(list3) do
                table.insert(list, item)
            end
        end
    end
    for i, item in ipairs(list) do
        local ok, res = pcall(Modes.sim, item)
        local portalsAny = Config.portalsAny or (ok and res and (tonumber(res.p) or 0) >= 0.25) or ((item.rec and tonumber(item.rec.wins)) or 0) > 0
        if item.kind == "portal" and portalsAny then
            local item2 = list [1]
            if i > 1 and item2.kind ~= "daily" and not (item2.kind == "dungeon" and item2.started) then
                table.remove(list, i)
                table.insert(list, 1, item)
                item.why = "your portal first · " .. (item.why or "")
            end
            break
        end
    end
    for i, item in ipairs(list) do
        if item.kind == "artifact" then
            local item2 = list [1]
            if i > 1 and (item.p or 0) >= 0.25 and item2.kind ~= "daily" and item2.kind ~= "portal" and not (item2.kind == "dungeon" and item2.started) and not tostring(item2.why):find("for your focus unit", 1, true) then
                table.remove(list, i)
                table.insert(list, 1, item)
                item.why = "this rotation's clears · " .. (item.why or "")
            end
            break
        end
    end
    local item = list [1]
    if item and item.kind == "story" and item.first then
        local item2, baseScore = item, (item.baseScore or item.score) * Modes.CHAIN_MIN
        for i = 1, 6 do
            local value
            for _, item in ipairs(list) do
                if item.kind == "story" and item.first and item.diff == item2.diff and (item.baseScore or item.score) >= baseScore and Modes.nextAct(item.level) == item2.level then
                    value = item
                    break
                end
            end
            if not value then
                break
            end
            item2 = value
        end
        if item2 ~= item then
            table.remove(list, table.find(list, item2))
            table.insert(list, 1, item2)
            item2.why = "the first of these acts in a row · " .. (item2.why or "")
        end
    end
    local testTeam = Brain.testTeam
    if testTeam and (testTeam.left or 0) > 0 then
        for i, item in ipairs(list) do
            if item.key == testTeam.key then
                if i > 1 and list [1].kind ~= "daily" and (testTeam.first or not (list [1].kind == "dungeon" and list [1].started)) then
                    table.remove(list, i)
                    table.insert(list, 1, item)
                end
                item.why = string.format("team test, run %d of %d: %s · ", (tonumber(testTeam.n) or 0) - testTeam.left + 1, tonumber(testTeam.n) or 0, tostring(testTeam.label)) .. (item.why or "")
                break
            end
        end
    end
    if Brain.nextMode then
        for i, item in ipairs(list) do
            if item.key == Brain.nextMode then
                table.remove(list, i)
                table.insert(list, 1, item)
                item.why = "asked for once · " .. (item.why or "")
                break
            end
        end
    end
    if Config.dailyLoop then
        for i, item in ipairs(list) do
            if item.kind == "daily" then
                table.remove(list, i)
                table.insert(list, 1, item)
                item.why = "you asked to keep playing it · " .. (item.why or "")
                break
            end
        end
    end
    Modes.lastScored = list
    return list [1]
end

function Modes.fromLevelData(ld)
    if not ld then
        return nil
    end
    local id = ld.id
    if id == "__DAILY_CHALLENGE" then
        return "dc", "daily"
    end
    if ld._dungeon then
        return "dg", "dungeon"
    end
    if ld._challenge then
        return "ch", "challenge"
    end
    local world = Core.Levels [id] and Core.Levels [id].world
    if world and Core.Worlds [world] and Core.Worlds [world]._artifact_stage then
        return "ar:" .. id, "artifact"
    end
    if Core.Levels [id] and Core.Levels [id]._portal_only_level then
        local portalDepth = tonumber(ld.portal_depth) or tonumber(ld._portal_depth)
        if portalDepth and portalDepth > 0 then
            return "pt:" .. id .. ":t" .. math.floor(portalDepth), "portal"
        end
        local key = Brain.pending and Brain.pending.kind == "portal" and type(Brain.pending.key) == "string" and Brain.pending.key or ""
        local text = "pt:" .. id .. ":t"
        if key:sub(1, # text) == text and os.time() - (tonumber(Brain.pending.at) or 0) < 1200 then
            return key, "portal"
        end
        return "pt:" .. id, "portal"
    end
    if ld._gamemode == "infinite" or ld.infinite then
        return "inf:" .. id, "infinite"
    end
    if ld._gamemode == "raid" and Brain.live.event and Brain.live.event.level == id then
        return "ev:" .. id, "event"
    end
    if ld._gamemode == "raid" or (Core.Levels [id] and Core.Levels [id].is_raid) then
        return "rd:" .. id, "raid"
    end
    if ld._gamemode == "story" then
        return "st:" .. id .. ":" .. tostring(ld._difficulty or "Normal"), "story"
    end
    return tostring(ld._gamemode) .. ":" .. tostring(id), tostring(ld._gamemode)
end

function Adventure.levelItems(level, levelKey)
    local list = {
    }
    if type(level) ~= "table" then
        return list
    end
    levelKey = levelKey or level.id
    local rewards = level.rewards
    if type(rewards) == "table" and rewards.item then
        rewards = {
            rewards
        }
    end
    local flag = false
    for _, reward in pairs(type(rewards) == "table" and rewards or {
    }) do
        if type(reward) == "table" then
            local list2 = Utils.list(reward.item)
            local num = 1
            if reward._item_multichoice and # list2 > 0 then
                num = math.min(1, (tonumber(reward._item_multichoice.min) or # list2) / # list2)
            end
            for _, item in ipairs(list2) do
                if type(item) == "table" and item.item_id then
                    local amount = tonumber(item.amount) or ((tonumber(item.min_amount) or 1) + (tonumber(item.max_amount) or tonumber(item.min_amount) or 1)) / 2
                    table.insert(list, {
                        item = item.item_id,
                        per = amount * (tonumber(item.chance) or 1) * num
                    })
                    flag = true
                end
            end
        end
    end
    if not flag then
        for _, showReward in pairs(type(level._show_rewards) == "table" and level._show_rewards or {
        }) do
            if type(showReward) == "table" and showReward.type == "item" and showReward.params and showReward.params.item_id then
                table.insert(list, {
                    item = showReward.params.item_id,
                    per = 1
                })
            end
        end
    end
    local ok, res = pcall(Reports.hiveDrops, levelKey)
    if ok and res then
        local list2 = {
        }
        for i, item in ipairs(list) do
            list2 [item.item] = i
        end
        for key, value in pairs(res) do
            if list2 [key] then
                list [list2 [key]].per = value
            else
                table.insert(list, {
                    item = key,
                    per = value
                })
            end
        end
    end
    return list
end

function Adventure.sources()
    if Adventure._src then
        return Adventure._src
    end
    local list = {
    }
    for levelKey, level in pairs(Core.Levels) do
        for _, levelItem in ipairs(Adventure.levelItems(level, levelKey)) do
            list [levelItem.item] = list [levelItem.item] or {
            }
            table.insert(list [levelItem.item], {
                level = levelKey,
                per = levelItem.per
            })
        end
    end
    for _, item in pairs(list) do
        table.sort(item, function(arg1, arg2)
            return arg1.per > arg2.per
        end)
    end
    Adventure._src = list
    return list
end

function Adventure.have(item)
    local session = Core.session()
    local count = 0
    pcall(function()
        count = session.inventory:get_number_of_owned_item(item)
    end)
    return count
end

function Adventure.killsShort(unitObj, shiny)
    if not shiny then
        return nil
    end
    local takedownRequirement = tonumber(shiny._takedown_requirement)
    if takedownRequirement and (tonumber(unitObj.total_takedowns) or 0) < takedownRequirement then
        return {
            what = "takedowns",
            have = tonumber(unitObj.total_takedowns) or 0,
            need = takedownRequirement
        }
    end
    local killRequirement = tonumber(shiny._kill_requirement)
    if killRequirement and (tonumber(unitObj.total_kills) or 0) < killRequirement then
        return {
            what = "kills",
            have = tonumber(unitObj.total_kills) or 0,
            need = killRequirement
        }
    end
    return nil
end
Adventure.TIER_RANK = {
    SS = 6,
    S = 5,
    A = 4,
    B = 3,
    C = 2,
    D = 1
}

function Adventure.tiers()
    if Adventure._tiers then
        return Adventure._tiers
    end
    local list = {
    }
    for unitKey, unit in pairs(Core.Units) do
        if type(unit) == "table" and type(unit.name) == "string" then
            local name = unit.name:lower()
            if not list [name] or (unit.rarity and not Core.Units [list [name]].rarity) then
                list [name] = unitKey
            end
        end
    end
    local list2 = {
    }
    local function helper(arg1, arg2)
        return not arg2 or (Adventure.TIER_RANK [arg1] or 0) > (Adventure.TIER_RANK [arg2] or 0)
    end
    local function helper2(arg1, arg2, arg3, arg4)
        list2 [arg1] = list2 [arg1] or {
            base = {
            }
        }
        if helper(arg3, list2 [arg1] [arg2]) then
            list2 [arg1] [arg2] = arg3
        end
        if arg4 and helper(arg3, list2 [arg1].base [arg2]) then
            list2 [arg1].base [arg2] = arg3
        end
    end
    for _, value in ipairs({
        {
            Core.TIERS,
            true
        },
        {
            Core.TIERS_USER,
            true
        },
        {
            Core.TIERS_EXTRA,
            false
        }
    }) do
        for key, value2 in pairs(value [1]) do
            for key2, value2 in pairs(value2) do
                for key3 in value2:gmatch("[^|]+") do
                    local tierAlia = Core.TIER_ALIAS [key3] or list [key3:lower()]
                    if tierAlia and Core.Units [tierAlia] then
                        helper2(tierAlia, key, key2, value [2])
                    end
                end
            end
        end
    end
    Adventure._tiers = list2
    return list2
end

function Adventure.tier(arg1, arg2)
    if not Config.community then
        return nil, nil, 0
    end
    local tier = Adventure.tiers() [arg1]
    if arg2 and tier then
        tier = tier.base
    end
    if not tier then
        return nil, nil, 0
    end
    local value, value2 = Adventure.TIER_RANK [tier.story or ""] or 0, Adventure.TIER_RANK [tier.overall or ""] or 0
    local story = value >= value2 and tier.story or tier.overall
    if not story then
        return nil, nil, 0
    end
    return story, tier, math.max(value, value2)
end

function Adventure.tierText(evolveUnit)
    local tier, tier2 = Adventure.tier(evolveUnit)
    if not tier then
        return nil
    end
    local list = {
    }
    if tier2.story then
        table.insert(list, "Story " .. tier2.story)
    end
    if tier2.overall then
        table.insert(list, "overall " .. tier2.overall)
    end
    if tier2.infinite then
        table.insert(list, "Infinite " .. tier2.infinite)
    end
    if tier2.castle then
        table.insert(list, "Infinity Castle " .. tier2.castle)
    end
    return "tier " .. table.concat(list, ", ")
end

function Adventure.tierBest(arg1, arg2)
    local unit = Core.Units [arg1]
    local evolveUnit = unit and unit.evolve and unit.evolve.evolve_unit
    local _, _, tier3 = Adventure.tier(arg1, arg2)
    local _, _, tier32 = Adventure.tier(evolveUnit, arg2)
    if evolveUnit and tier32 > tier3 then
        return evolveUnit, tier32
    end
    return arg1, tier3
end

function Adventure.role(arg1)
    if not Adventure._roles then
        Adventure._roles = {
        }
        for keepRoleKey, keepRole in pairs(Core.KEEP_ROLES) do
            for _, value in ipairs(keepRole) do
                Adventure._roles [value] = keepRoleKey
            end
        end
    end
    return Adventure._roles [arg1]
end

function Adventure.fodderOrder(unitId)
    local count, list, unitId2 = 0, {
    }, unitId
    while unitId2 and Core.Units [unitId2] and not list [unitId2] do
        list [unitId2] = true
        if Adventure.role(unitId2) then
            return nil
        end
        local _, _, tier3 = Adventure.tier(unitId2)
        count = math.max(count, tier3)
        local unit = Core.Units [unitId2]
        unitId2 = unit.evolve and unit.evolve.evolve_unit
    end
    if count >= Adventure.TIER_RANK.A then
        return nil
    end
    local _, tier2 = Adventure.tier(unitId)
    if (tier2 and tier2.overall == "D") or count == Adventure.TIER_RANK.D then
        return 1
    end
    return 2 + count
end

function Adventure.strongest(arg1)
    if Adventure._strong and Adventure._strongN == arg1 and Utils.now() - Adventure._strongAt < 60 then
        return Adventure._strong
    end
    local session = Core.session()
    local list = {
    }
    for ownedUnitKey, ownedUnit in pairs(session.profile_data.collection.owned_units) do
        local ok, res = pcall(Units.score, session.collection:get_unit_by_uuid(ownedUnitKey) or ownedUnit)
        if ok and tonumber(res) then
            table.insert(list, {
                uuid = ownedUnitKey,
                sc = res
            })
        end
    end
    table.sort(list, function(arg1, arg2)
        return arg1.sc > arg2.sc
    end)
    local list2 = {
    }
    for i = 1, math.min(arg1, # list) do
        list2 [list [i].uuid] = true
    end
    Adventure._strong, Adventure._strongN, Adventure._strongAt = list2, arg1, Utils.now()
    return list2
end

function Adventure.communityText()
    if not Config.community then
        return "Off (Settings → Community tips)."
    end
    local prof = Core.prof()
    if not prof then
        return "…"
    end
    local list = {
    }
    local function helper(arg1, arg2, arg3)
        local banner = Core.Banners [arg2]
        local list2 = {
        }
        for _, rateupUnit in pairs(banner and banner.rateup_units or {
        }) do
            if type(rateupUnit) == "table" and type(rateupUnit.possible_units_set) == "table" then
                for key in pairs(rateupUnit.possible_units_set) do
                    table.insert(list2, key)
                end
            end
        end
        local list3 = {
        }
        for _, item in ipairs(list2) do
            local tierBest, tierBest2 = Adventure.tierBest(item)
            table.insert(list3, {
                r = tierBest2,
                text = string.format("%s %s%s",
                Units.name(tierBest),
                (Adventure.tier(tierBest)) or "unrated",
                Units.owns(item) and " (you have it)" or "")
            })
        end
        table.sort(list3, function(arg1, arg2)
            return arg1.r > arg2.r
        end)
        local list2 = {
        }
        for _, item in ipairs(list3) do
            table.insert(list2, item.text)
        end
        if # list2 > 0 then
            table.insert(list, string.format("%s (%s): %s", arg1, arg3, table.concat(list2, " · ")))
        end
    end
    helper("April banner", "April2025", "150 AprilCoins a pull")
    helper("Sakamoto banner", "SakamotoEvent", "10 Assassin Tokens a pull")
    helper("Gem banner", "EventClover", "50 gems a pull")
    local list2 = {
    }
    for _, value in ipairs(Units.equipped()) do
        if not Units.isFarm(value.id) and not Units.allyBuff(value.id) then
            local _, types2 = Units.types(value.id)
            if types2 then
                list2 [types2] = true
            end
        end
    end
    local list3, list4 = {
    }, {
    }
    for _, ownedUnit in pairs(prof.collection.owned_units) do
        local tierBest, tierBest2 = Adventure.tierBest(ownedUnit.unit_id)
        if tierBest2 >= 4 and not list4 [tierBest] then
            list4 [tierBest] = true
            local str = ""
            local allyBuff = Units.allyBuff(tierBest)
            if allyBuff then
                local flag = false
                for typeKey in pairs(allyBuff.types or {
                }) do
                    if list2 [typeKey] then
                        flag = true
                    end
                end
                if not flag then
                    for typeKey in pairs(allyBuff.types or {
                    }) do
                        str = string.format(" (buffs %s units: your damage dealers aren't)", typeKey)
                    end
                end
            end
            if tierBest ~= ownedUnit.unit_id then
                str = str .. " (evolve " .. Units.name(ownedUnit.unit_id) .. ")"
            end
            table.insert(list3, {
                r = tierBest2,
                text = Units.name(tierBest) .. " " .. ((Adventure.tier(tierBest)) or "") .. str
            })
        end
    end
    table.sort(list3, function(arg1, arg2)
        return arg1.r > arg2.r
    end)
    local list2 = {
    }
    for i, item in ipairs(list3) do
        if i <= 8 then
            table.insert(list2, item.text)
        end
    end
    if # list2 > 0 then
        table.insert(list, "Yours rated A or better: " .. table.concat(list2, " · "))
    end
    table.insert(list, "The guides rank evolved, fully upgraded units and ignore traits (a strong trait can move a unit a whole tier). " .. "Their advice: save gems and commit to one banner.")
    return table.concat(list, "\n")
end

function Adventure.pullGoal()
    local pullGoal = Config.pullGoal
    if type(pullGoal) ~= "string" or pullGoal == "" or type(Core.Units [pullGoal]) ~= "table" then
        return nil
    end
    local prof = Core.prof()
    if not prof then
        return nil
    end
    local unit = Core.Units [pullGoal]
    local evolveUnit = unit.evolve and unit.evolve.evolve_unit or pullGoal
    local info = {
        id = pullGoal,
        to = evolveUnit,
        coins = Core.cur("AprilCoins"),
        itemCost = 0,
        needCoins = 0
    }
    for _, value in pairs(unit.evolve and unit.evolve.normal and unit.evolve.normal.item_requirement or {
    }) do
        local value2 = Core.SaleEvent [value.item_id]
        if value2 and type(value2.resource_cost) == "table" and value2.resource_cost.id == "AprilCoins" then
            info.item, info.itemCost = value.item_id, tonumber(value2.resource_cost.amount) or 0
        end
    end
    info.haveItem = info.item ~= nil and Adventure.have(info.item) > 0
    local flag, flag2 = FarmHub.hatched [pullGoal] or false, false
    for _, ownedUnit in pairs(prof.collection.owned_units) do
        if ownedUnit.unit_id == pullGoal then
            flag = true
        end
        if ownedUnit.unit_id == evolveUnit then
            flag2 = true
        end
    end
    if flag2 then
        info.step = "done"
    elseif not flag then
        info.step, info.needCoins = "pull", 1
    elseif info.item and not info.haveItem then
        info.step, info.needCoins = "item", math.max(0, info.itemCost - info.coins)
    else
        info.step = "evolve"
    end
    return info
end

function Adventure.goalText()
    local pullGoal = Adventure.pullGoal()
    if not pullGoal then
        return "No main goal set (Settings: pull goal)."
    end
    local prof = Core.prof()
    local text = string.format("%s%s · ", Units.name(pullGoal.to), (Adventure.tier(pullGoal.to)) and (" (tier " .. Adventure.tier(pullGoal.to) .. ")") or "")
    if pullGoal.step == "pull" then
        if not Core.Banners.April2025 then
            return text .. string.format("the April banner isn't in the game right now, so there's nothing to pull %s from. This waits until it comes back.", Units.name(pullGoal.id))
        end
        local aprilFloor = math.max(Config.aprilFloor, pullGoal.haveItem and 0 or pullGoal.itemCost)
        local april2025 = prof and prof.pity_data and prof.pity_data.April2025
        local opensSinceMythic = april2025 and tonumber(april2025.opens_since_mythic)
        return text .. string.format("step 1 of 3: pull %s from the April banner. You have %s AprilCoins: %d ten-pulls above the %s kept for its evolve item. " .. "Each Mythic from this banner is one of 3 limited units (1 in 3 is %s), and one is guaranteed every 200 pulls%s. " .. "The farm plays Fool's Hunt for AprilCoins (worth %.2f gems each to the ranking while this goal needs them)%s.", Units.name(pullGoal.id), Utils.fmt(pullGoal.coins), math.max(0, math.floor((pullGoal.coins - aprilFloor) / 1500)), Utils.fmt(aprilFloor), Units.name(pullGoal.id), opensSinceMythic and string.format(" (%d pulls since the last Mythic)", opensSinceMythic) or "", math.max(Config.aprilValue, Config.goalCoinValue), Config.summonApril and " and pulls 10 at a time" or "; April pulls are off (Units → Summon)")
    elseif pullGoal.step == "item" then
        return text .. string.format("step 2 of 3: you have %s! Its evolve item costs %s AprilCoins in the event shop; you have %s. The farm buys it when the coins are in.", Units.name(pullGoal.id), Utils.fmt(pullGoal.itemCost), Utils.fmt(pullGoal.coins))
    elseif pullGoal.step == "evolve" then
        return text .. "step 3 of 3: its takedowns come from training (it joins easy runs), then smart evolve evolves it."
    end
    return text .. "done, it's yours!"
end

function FarmHub.eventShop()
    local pullGoal = Adventure.pullGoal()
    if not (Config.summonApril and pullGoal and pullGoal.step == "item" and pullGoal.coins >= pullGoal.itemCost and pullGoal.itemCost > 0) then
        return
    end
    if App.req.back.eshop and Utils.now() < App.req.back.eshop then
        return
    end
    local ok, res = App.request("eshop", "buy_item_generic", pullGoal.item, "event", "event_shop", "1")
    local now = Utils.now()
    while Utils.now() - now < 4 and Adventure.have(pullGoal.item) < 1 do
        task.wait(0.25)
    end
    local name = (Core.Items [pullGoal.item] or {
    }).name or pullGoal.item
    if Adventure.have(pullGoal.item) > 0 then
        Spending.add(name, pullGoal.itemCost, "AprilCoins", "evolve item for " .. Units.name(pullGoal.to))
        if App.notify then
            App.notify("Main goal", "Bought " .. name .. " for " .. Units.name(pullGoal.id), "success")
        end
        pcall(Adventure.refresh)
    else
        App.log(1, "SHOP", "event shop refused " .. tostring(pullGoal.item) .. " (" .. tostring(ok and res or "no answer") .. ")")
        App.backoff("eshop", 900)
    end
end

function FarmHub.codes()
    if not Config.codes then
        return App.status("Codes", "off (Settings)")
    end
    local prof = Core.prof()
    if not prof then
        return
    end
    local redeemedCodes = prof.redeemed_codes or {
    }
    local list, list2 = {
    }, {
    }
    for _, code in ipairs(Core.CODES) do
        local code2 = tonumber(Brain.codes [code])
        if redeemedCodes [code] then
            if code2 and code2 > 0 then
                table.insert(list2, code)
                Brain.codes [code] = - 1
            end
        elseif os.time() - (code2 or 0) > 86400 and (code2 or 0) >= 0 then
            Brain.codes [code] = os.time()
            local ok = App.request("code", "redeem_code", code)
            if ok then
                table.insert(list, code)
            end
            task.wait(1)
        end
    end
    if # list2 > 0 then
        App.log(1, "CODES", "the game confirms " .. table.concat(list2, ", "))
    end
    if # list > 0 then
        App.log(1, "CODES", "sent " .. table.concat(list, ", ") .. " (the game confirms a code after the next teleport; one it refuses is tried again tomorrow)")
    end
    App.saveSoon()
    local count = 0
    for _, code in ipairs(Core.CODES) do
        if not redeemedCodes [code] then
            count = count + 1
        end
    end
    App.status("Codes", # list > 0 and ("sent " .. table.concat(list, ", ")) or (count == 0 and "every known code is redeemed ✓" or (count .. " codes not taken yet, trying again tomorrow")))
end

