function Adventure.bestSource(levels)
    if not (Modes.lastScored and Modes.lastScored [1]) then
        pcall(Modes.pick)
    end
    local list = {
    }
    for _, value in ipairs(Modes.lastScored or {
    }) do
        if value.level then
            list [value.level] = value
        end
    end
    local value, value2
    for _, level in ipairs(levels or {
    }) do
        local item = list [level.level]
        local ok, res = pcall(function()
            return item and Modes.minutes(item) or 10
        end)
        local ratio = level.per * (item and (item.p or 0.5) or 0.5) / math.max(1, ok and res or 10)
        if not value2 or ratio > value2 then
            value, value2 = level, ratio
        end
    end
    return value
end

function Adventure.planItem(itemId, amount)
    local have = Adventure.have(itemId)
    if have >= amount then
        return {
            item = itemId,
            done = true
        }
    end
    local source = Adventure.sources() [itemId]
    if source and source [1] then
        return {
            item = itemId,
            need = amount,
            have = have,
            farm = itemId,
            farmNeed = amount - have,
            levels = source
        }
    end
    local value = Core.SaleEvent [itemId]
    if value and type(value.resource_cost) == "table" then
        return {
            item = itemId,
            need = amount,
            have = have,
            eventShop = true,
            cost = tonumber(value.resource_cost.amount) or 0,
            currency = value.resource_cost.id,
            farmNeed = 0
        }
    end
    for key, value in pairs(Brain.raidShop) do
        if value.id == itemId and value.costItem and (value.stock == "inf" or (tonumber(value.stock) or 0) > 0) then
            local source = Adventure.sources() [value.costItem]
            local cost = value.cost * (amount - have)
            local have2 = Adventure.have(value.costItem)
            return {
                item = itemId,
                need = amount,
                have = have,
                shopKey = key,
                costItem = value.costItem,
                cost = value.cost,
                farm = value.costItem,
                farmNeed = math.max(0,
                cost - have2),
                levels = source or {
                }
            }
        end
    end
    for portalKey, portal in pairs(Modes.PORTALS) do
        if portal.item == itemId then
            return {
                item = itemId,
                need = amount,
                have = have,
                farm = itemId,
                farmNeed = amount - have,
                portal = portalKey,
                levels = {
                    {
                        level = portal.level,
                        per = Modes.portalPer(portalKey)
                    }
                }
            }
        end
    end
    return {
        item = itemId,
        need = amount,
        have = have,
        unknown = true
    }
end
