            local uniquePortalData = type(uniqueItem._unique_item_data) == "table" and uniqueItem._unique_item_data._unique_portal_data or {
            }
            local ctl = type(uniquePortalData._ctl) == "table" and uniquePortalData._ctl or {
            }
            local list2 = {
            }
            for _, levelmodifier in pairs(type(ctl._levelmodifiers) == "table" and ctl._levelmodifiers or {
            }) do
