function FarmHub.bannerCost(summonBanner)
    local banner = Core.Banners [summonBanner]
    if not banner then
        return nil
    end
    if banner.item_cost then
        local itemId = banner.item_cost.item_id
        return {
            cost = tonumber(banner.item_cost.amount) or 10,
            have = function()
                return Adventure.have(itemId)
            end,
            name = (Core.Items [itemId] or {
            }).name or itemId,
            floor = "tokenFloor"
        }
    end
    local resourceCost = banner.resource_cost
    if resourceCost and resourceCost.id == "SummerPearls" then
        return {
            cost = tonumber(resourceCost.amount) or 150,
            have = function()
                return Core.cur("SummerPearls")
            end,
            name = "Summer Pearls",
            floor = "pearlFloor"
        }
    end
    if resourceCost and resourceCost.id then
        return {
            cost = tonumber(resourceCost.amount) or 50,
            have = function()
                return Core.cur(resourceCost.id)
            end,
            name = resourceCost.id == "GemsLegacy" and "Legacy Gems" or resourceCost.id,
            floor = resourceCost.id == "AprilCoins" and "aprilFloor" or "tokenFloor"
        }
    end
    return {
        cost = tonumber(banner.gem_cost) or 50,
        have = function()
            return Core.cur("gems")
        end,
        name = "gems",
        floor = "gemFloor"
    }
end

-- ===== Performance: hide or delete textures and effects, simple lighting, 3D off, FPS cap =====
-- Only what you see is touched: decals, textures, mesh skins, particles, trails, beams, smoke, fire and lights.
-- Parts, the road and the map folders stay, because placement raycasts and the lobby read them.
-- Units and characters keep their textures. Hide can be undone; Delete lasts for this map.
GUI.GFX_TEXTURE = {
    Decal = true,
    Texture = true,
    SurfaceAppearance = true,
    MeshPart = true,
    SpecialMesh = true,
}
GUI.GFX_EFFECT = {
    ParticleEmitter = true,
    Trail = true,
    Beam = true,
    Explosion = true,
    Smoke = true,
    Fire = true,
    Sparkles = true,
    PointLight = true,
    SpotLight = true,
    SurfaceLight = true,
}
GUI.GFX_MODES = {
    "keep",
    "hide",
    "delete"
}
GUI.GFX_FPS = {
    0,
    60,
    30,
    20,
    15
}
-- Something added while playing is hidden at once and deleted this many seconds later, so the game's own
-- effect code is done with it (deleting it at once would break that code's next line).
GUI.GFX_LATE_DELETE = 3
GUI.gfx = {
    saved = setmetatable({
    }, {
        __mode = "k"
    }),
    detached = {
    },
    count = {
        texture = 0,
        effect = 0
    },
    removed = {
        texture = 0,
        effect = 0
    },
    gen = 0
}

function GUI.gfxMode(kind)
    if Config.gfxLow or (kind == "effect" and Config.gfxBatchFx) then return "hide" end
    local mode = kind == "texture" and Config.gfxTextures or Config.gfxEffects
    return (mode == "hide" or mode == "delete") and mode or "keep"
end

function GUI.gfxKind(instance)
    local class = instance.ClassName
    if GUI.GFX_TEXTURE [class] then
        return "texture"
    end
    if GUI.GFX_EFFECT [class] then
        return "effect"
    end
    return nil
end

-- A mesh with no skin has nothing to hide.
function GUI.gfxBare(instance)
    local class = instance.ClassName
    local name = class == "MeshPart" and "TextureID" or class == "SpecialMesh" and "TextureId" or nil
    if not name then
        return false
    end
    local ok, value = pcall(function()
        return instance [name]
    end)
    return not ok or value == nil or value == ""
end

-- Units and characters keep their look.
function GUI.gfxKeepLook(instance)
    local units = workspace:FindFirstChild("_UNITS")
    if units and instance:IsDescendantOf(units) then
        return true
    end
    local ancestor = instance.Parent
    while ancestor and ancestor ~= workspace do
        if ancestor:IsA("Model") and ancestor:FindFirstChildOfClass("Humanoid") then
            return true
        end
        ancestor = ancestor.Parent
    end
    return false
end

function GUI.gfxHideProps(class)
    if class == "Explosion" then return { Visible = false } end
    if class == "Decal" or class == "Texture" then
        return {
            LocalTransparencyModifier = 1
        }
    elseif class == "MeshPart" then
        return {
            TextureID = ""
        }
    elseif class == "SpecialMesh" then
        return {
            TextureId = ""
        }
    elseif class == "ParticleEmitter" or class == "Trail" or class == "Beam" then
        -- Off, and see-through too: the game can still fire Emit() or switch it back on.
        local ok, clear = pcall(function()
            return NumberSequence.new(1)
        end)
        return {
            Enabled = false,
            Transparency = ok and clear or nil
        }
    end
    return {
        Enabled = false
    }
end

function GUI.gfxHide(instance, kind)
    local state = GUI.gfx
    if state.saved [instance] then
        return false
    end
    if instance.ClassName == "SurfaceAppearance" then
        -- Its properties are locked, so it is taken off the part and kept to be put back.
        local parent = instance.Parent
        if not parent or not pcall(function()
            instance.Parent = nil
        end) then
            return false
        end
        local record = {
            kind = kind,
            parent = parent
        }
        state.saved [instance], state.detached [instance] = record, record
        state.count [kind] = state.count [kind] + 1
        return true
    end
    local old = {
    }
    for name, value in pairs(GUI.gfxHideProps(instance.ClassName)) do
        local ok, previous = pcall(function()
            return instance [name]
        end)
        if ok and previous ~= value and pcall(function()
            instance [name] = value
        end) then
            old [name] = previous
        end
    end
    if next(old) == nil then
        return false
    end
    state.saved [instance] = {
        kind = kind,
        old = old
    }
    state.count [kind] = state.count [kind] + 1
    return true
end

function GUI.gfxRestore(kind)
    local state = GUI.gfx
    local list = {
    }
    for instance, record in pairs(state.saved) do
        if record.kind == kind then
            table.insert(list, instance)
        end
    end
    for _, instance in ipairs(list) do
        local record = state.saved [instance]
        state.saved [instance], state.detached [instance] = nil, nil
        if record.parent then
            state.restoring = true
            pcall(function()
                instance.Parent = record.parent
            end)
            state.restoring = nil
        else
            for name, value in pairs(record.old) do
                pcall(function()
                    instance [name] = value
                end)
            end
        end
    end
    state.count [kind] = 0
end

function GUI.gfxDelete(instance, kind)
    local state = GUI.gfx
    if state.saved [instance] then
        state.saved [instance], state.detached [instance] = nil, nil
        state.count [kind] = math.max(0, state.count [kind] - 1)
    end
    local class = instance.ClassName
    local ok = pcall(function()
        if class == "MeshPart" then
            instance.TextureID = ""
        elseif class == "SpecialMesh" then
            instance.TextureId = ""
        else
            instance:Destroy()
        end
    end)
    if ok then
        state.removed [kind] = state.removed [kind] + 1
    end
    return ok
end

-- late: added while playing (not found by the scan of what was already there).
function GUI.gfxHandle(instance, late, safeOnly)
    -- Explosions are only touched by the new reversible effect options.
    if instance.ClassName == "Explosion" and not (Config.gfxLow or Config.gfxBatchFx) then return end
    local kind = GUI.gfxKind(instance)
    if not kind then
        return
    end
    local mode = GUI.gfxMode(kind)
    if mode == "keep" or (safeOnly and mode == "delete") then
        return
    end
    if kind == "texture" and (GUI.gfxBare(instance) or GUI.gfxKeepLook(instance)) then
        return
    end
    if mode == "hide" then
        GUI.gfxHide(instance, kind)
    elseif late then
        if GUI.gfxHide(instance, kind) then
            task.delay(GUI.GFX_LATE_DELETE, function()
                if GUI.gfxMode(kind) == "delete" and GUI.gfx.saved [instance] then
                    GUI.gfxDelete(instance, kind)
                end
            end)
        end
    else
        GUI.gfxDelete(instance, kind)
    end
end

function GUI.gfxLighting(on)
    local state = GUI.gfx
    if not on then
        local light = state.light
        if not light then
            return
        end
        state.light = nil
        if light.conn then
            pcall(function()
                light.conn:Disconnect()
            end)
        end
        for index = # light.saved, 1, - 1 do
            local entry = light.saved [index]
            pcall(function()
                entry [1] [entry [2]] = entry [3]
            end)
        end
        return
    end
    if state.light then
        return
    end
    local light = {
        saved = {
        }
    }
    state.light = light
    local function set(object, name, value)
        local ok, previous = pcall(function()
            return object [name]
        end)
        if ok and previous ~= value and pcall(function()
            object [name] = value
        end) then
            table.insert(light.saved, {
                object,
                name,
                previous
            })
        end
    end
    local function calm(object)
        if object:IsA("PostEffect") then
            set(object, "Enabled", false)
        elseif object:IsA("Atmosphere") then
            set(object, "Density", 0)
            set(object, "Haze", 0)
            set(object, "Glare", 0)
        elseif object:IsA("Clouds") then
            set(object, "Enabled", false)
        end
    end
    local ok, lighting = pcall(function()
        return game:GetService("Lighting")
    end)
    if ok and lighting then
        set(lighting, "GlobalShadows", false)
        for _, object in ipairs(lighting:GetDescendants()) do
            pcall(calm, object)
        end
        light.conn = lighting.DescendantAdded:Connect(function(object)
            pcall(calm, object)
        end)
    end
    local camera = workspace.CurrentCamera
    if camera then
        for _, object in ipairs(camera:GetChildren()) do
            pcall(calm, object)
        end
    end
    local terrain = workspace:FindFirstChildOfClass("Terrain")
    if terrain then
        set(terrain, "WaterWaveSize", 0)
        set(terrain, "WaterWaveSpeed", 0)
        set(terrain, "WaterReflectance", 0)
        set(terrain, "Decoration", false)
        for _, object in ipairs(terrain:GetChildren()) do
            pcall(calm, object)
        end
    end
    pcall(function()
        set(settings().Rendering, "QualityLevel", Enum.QualityLevel.Level01)
    end)
end

function GUI.gfx3d(off)
    local state = GUI.gfx
    off = off == true
    if (state.r3dOff == true) == off then
        return
    end
    local ok = pcall(function()
        game:GetService("RunService"):Set3dRenderingEnabled(not off)
    end)
    if ok then
        state.r3dOff = off
    end
end

function GUI.gfxFps(cap)
    local state = GUI.gfx
    cap = math.max(0, math.floor(tonumber(cap) or 0))
    if cap == (state.fps or 0) then
        state.fpsMissing = nil
        return
    end
    if type(setfpscap) ~= "function" then
        state.fpsMissing = cap > 0 or nil
        return
    end
    if cap > 0 and not state.fps then
        local ok, previous = pcall(function() return getfpscap() end)
        state.fpsOriginal = ok and tonumber(previous) or 60
    end
    state.fpsMissing = nil
    if pcall(setfpscap, cap > 0 and cap or state.fpsOriginal or 60) then
        state.fps = cap > 0 and cap or nil
        if cap == 0 then state.fpsOriginal = nil end
    end
end

-- One bounded queue for newly spawned effects. Disabling/reapplying invalidates the old worker.
function GUI.gfxQueue(instance)
    local state = GUI.gfx
    if not GUI.GFX_EFFECT[instance.ClassName] then return end
    local queue = state.queue
    if not queue then
        queue = { list = {}, seen = {}, gen = state.gen }
        state.queue = queue
        task.defer(function()
            task.wait()
            local index = 1
            while state.queue == queue and state.gen == queue.gen and index <= #queue.list do
                local stop = math.min(#queue.list, index + 127)
                while index <= stop do
                    local object = queue.list[index]
                    queue.list[index] = false
                    queue.seen[object] = nil
                    if object.Parent then pcall(GUI.gfxHandle, object, true, true) end
                    index = index + 1
                end
                -- Effects keep coming during a farm: drop the handled part so the list stays short.
                if index > 512 then
                    local rest = {}
                    for i = index, #queue.list do
                        table.insert(rest, queue.list[i])
                    end
                    queue.list, index = rest, 1
                end
                task.wait()
            end
            if state.queue == queue then state.queue = nil end
        end)
    end
    if not queue.seen[instance] then
        queue.seen[instance] = true
        table.insert(queue.list, instance)
    end
end

function GUI.gfxFocus(on)
    local state = GUI.gfx
    if not on then
        for _, conn in ipairs(state.focusConns or {}) do conn:Disconnect() end
        state.focusConns, state.focused = nil, nil
        return
    end
    if state.focusConns then return end
    state.focusConns, state.focused = {}, true
    local input = game:GetService("UserInputService")
    local function setFocus(focused)
        state.focused = focused
        GUI.gfx3d(Config.gfx3dOff == true or not focused)
    end
    local ok = pcall(function()
        table.insert(state.focusConns, input.WindowFocusReleased:Connect(function() setFocus(false) end))
        table.insert(state.focusConns, input.WindowFocused:Connect(function() setFocus(true) end))
    end)
    if not ok then GUI.gfxFocus(false) end
end

-- Apply the Performance settings: called at start and on every change there.
function GUI.gfxApply(safeOnly)
    local state = GUI.gfx
    if not (Config.gfxLow or Config.gfxBatchFx) then
        for instance, record in pairs(state.saved) do
            if instance.ClassName == "Explosion" then
                for name, value in pairs(record.old or {}) do
                    pcall(function() instance[name] = value end)
                end
                state.saved[instance] = nil
                state.count.effect = math.max(0, state.count.effect - 1)
            end
        end
    end
    for _, kind in ipairs({
        "texture",
        "effect"
    }) do
        if GUI.gfxMode(kind) ~= "hide" then
            GUI.gfxRestore(kind)
        end
    end
    local any = GUI.gfxMode("texture") ~= "keep" or GUI.gfxMode("effect") ~= "keep"
    if any and not state.conn then
        state.conn = workspace.DescendantAdded:Connect(function(instance)
            if state.restoring then return end
            if (Config.gfxLow or Config.gfxBatchFx) and GUI.GFX_EFFECT[instance.ClassName] then
                GUI.gfxQueue(instance)
            else
                pcall(GUI.gfxHandle, instance, true)
            end
        end)
    elseif not any and state.conn then
        pcall(function()
            state.conn:Disconnect()
        end)
        state.conn = nil
    end
    state.gen = state.gen + 1
    state.queue = nil
    if any then
        local gen = state.gen
        task.spawn(function()
            for index, instance in ipairs(workspace:GetDescendants()) do
                if state.gen ~= gen then
                    return
                end
                pcall(GUI.gfxHandle, instance, false, safeOnly)
                if index % 250 == 0 then
                    task.wait()
                end
            end
        end)
    end
    GUI.gfxLighting(Config.gfxLighting == true or Config.gfxLow == true)
    GUI.gfxFocus(Config.gfxUnfocused == true)
    GUI.gfx3d(Config.gfx3dOff == true or (Config.gfxUnfocused == true and GUI.gfx.focused == false))
    local cap = tonumber(Config.gfxFps) or 0
    GUI.gfxFps(Config.gfxLow and cap == 0 and 30 or cap)
end

-- Everything back as the game draws it (the script is closing).
function GUI.gfxOff()
    local state = GUI.gfx
    state.gen = state.gen + 1
    state.queue = nil
    GUI.gfxFocus(false)
    GUI.lowCpuAt = nil
    if state.conn then
        pcall(function()
            state.conn:Disconnect()
        end)
        state.conn = nil
    end
    GUI.gfxRestore("texture")
    GUI.gfxRestore("effect")
    GUI.gfxLighting(false)
    GUI.gfx3d(false)
    if state.fps then
        GUI.gfxFps(0)
    end
end

function GUI.gfxText()
    local state = GUI.gfx
    local parts = {
    }
    for _, entry in ipairs({
        {
            "texture",
            "textures"
        },
        {
            "effect",
            "effects"
        }
    }) do
        local kind, label = entry [1], entry [2]
        local mode = GUI.gfxMode(kind)
        if mode == "hide" then
            table.insert(parts, string.format("%s hidden: %d", label, state.count [kind]))
        elseif mode == "delete" then
            table.insert(parts, string.format("%s deleted: %d", label, state.removed [kind] + state.count [kind]))
        end
    end
    if state.light then
        table.insert(parts, "simple lighting")
    end
    if state.r3dOff then
        table.insert(parts, "3D off")
    end
    if state.fps then
        table.insert(parts, string.format("FPS cap %d", state.fps))
    elseif state.fpsMissing then
        table.insert(parts, "FPS cap: your executor has no setfpscap")
    end
    if Config.gfxLow then table.insert(parts, "low graphics preset") end
    if Config.gfxBatchFx then table.insert(parts, "batched effects") end
    if Config.gfxUnfocused then table.insert(parts, "3D pauses outside focus") end
    if Config.gfxLowCpu or Config.gfxLow then table.insert(parts, "panels refresh every 3s") end
    if # parts == 0 then
        return "Graphics as the game draws them."
    end
    return table.concat(parts, " · ")
end

function FarmHub.quietFx(arg1)
    local flag = Config.skipSummonFx and not arg1
    local svc = Core.svc("SummonFX")
    if svc and type(svc.open_star_new) == "function" then
        if rawget(svc, "__aaOrig") == nil then
            rawset(svc, "__aaOrig", svc.open_star_new)
        end
        svc.open_star_new = flag and function(_arg1, _arg2, _arg3, _arg4, arg5)
            if type(arg5) == "function" then
                task.defer(arg5)
            end
        end or rawget(svc, "__aaOrig")
    end
    local dropObtainedUi = Core.GUIS and Core.GUIS.drop_obtained_ui
    if type(dropObtainedUi) == "table" then
        for _, value in ipairs({
            "show_message",
            "show_message_custom"
        }) do
            rawset(dropObtainedUi, value, flag and function()
            end or nil)
        end
    end
end

function FarmHub.summonText()
    local bannerCost = Config.summonBanner ~= "" and FarmHub.bannerCost(Config.summonBanner)
    if not bannerCost then
        return "Pick a banner. It stops at the line below, or when your unit storage is full."
    end
    return string.format("You have %s %s. 10 summons cost %s, and it keeps %s.%s", Utils.fmt(bannerCost.have()), bannerCost.name, Utils.fmt(bannerCost.cost * 10), Utils.fmt(Config [bannerCost.floor]), Status.Summon and ("\n" .. tostring(Status.Summon)) or "")
end

function FarmHub.smartEvolve()
    if Config.unitsPaused then
        return App.status("Evolve", "paused: Smart Play For Units is off (Units → Goals)")
    end
    if not Config.smartEvolve then
        return App.status("Evolve", "smart evolve is off (Units → Goals)")
    end
    local session = Core.session()
    if not session then
        return
    end
    local list = {
    }
    for _, goal in ipairs(Brain.goals or {
    }) do
        table.insert(list, goal)
    end
    table.sort(list, function(arg1, arg2)
        return (arg1.gain or 0) > (arg2.gain or 0)
    end)
    local list2 = {
    }
    for _, item in ipairs(Units.equipped()) do
        list2 [item.uuid] = true
    end
    local list3, count, list4 = {
    }, 0, {
    }
    for _, item in ipairs(list) do
        if item.pinned then
            for _, item in ipairs(item.items or {
            }) do
                list3 [item.id] = (list3 [item.id] or 0) + item.amount
            end
        end
    end
    for _, item in ipairs(list) do
        local str, flag
        if item.ready and not item.pinned and count < 2 and (FarmHub.evoBlocked [item.uuid] or 0) < os.time() then
            if item.hidden and (item.tierRank or 0) < Adventure.TIER_RANK.S then
                str = "its strength is unknown (the game hides its upgrades until it's in a match), so this one is your call"
            end
            for _, item in ipairs(str and {
            } or item.items or {
            }) do
                if Adventure.have(item.id) - item.amount < (list3 [item.id] or 0) then
                    str = string.format("keeps %s for a bigger evolution", (Core.Items [item.id] or {
                    }).name or item.id)
                    break
                end
            end
            str = str or FarmHub.evoEats(item, list2)
            if not str then
                local evolve, evolve2 = FarmHub.evolve(item, "smart evolve: ready, stronger at full upgrade, uses only spare items" .. (# (item.eats or {
                }) > 0 and " and spare copies" or ""))
                if evolve then
                    count, flag = count + 1, true
                    table.insert(list4, "evolved " .. Units.name(item.from) .. " → " .. Units.name(item.to))
                else
                    FarmHub.evoBlocked [item.uuid] = os.time() + 3600
                    str = evolve2
                end
            end
            if str then
                table.insert(list4, Units.name(item.from) .. ": " .. str)
            end
        end
        if not flag then
            for _, item in ipairs(item.items or {
            }) do
                list3 [item.id] = (list3 [item.id] or 0) + item.amount
            end
        end
    end
    App.status("Evolve", # list4 > 0 and table.concat(list4, " · ") or "nothing ready to evolve")
end
Training.BONUS = 1.5
Training.SLOW = 1.4

function Training.boost(arg1, count, item, ratio)
    if count < 2 or item >= math.min(Config.dangerReach, (ratio or 1) * 0.9) then
        return
    end
    local flag = item < math.min(Config.safeReach, (ratio or 1) * 0.75)
    local count = 0
    for _, value in ipairs(arg1) do
        if not value.farm and not value.train and value.cost > 0 then
            count = math.max(count, value.gain / value.cost)
        end
    end
    for _, value in ipairs(arg1) do
        if value.train == "first" or (value.train == "more" and flag) then
            value.gain = math.max(value.gain, count * value.cost * 1.05)
        end
    end
end
Training.HOLD_REACH = 0.3
Training.ZONE = 0.25

function Training.hold(pressure, count, holding)
    if count < 2 or pressure >= Training.HOLD_REACH + (holding and 0.1 or 0) then
        return false
    end
    return true, string.format("holding your other units back so enemies reach the trainee (they die at %d%% of the road)", math.floor(pressure * 100 + 0.5))
end

function Training.same(team, uuids)
    if # team ~= # uuids then
        return false
    end
    local list = {
    }
    for _, member in ipairs(team) do
        list[member] = (list[member] or 0) + 1
    end
    for _, uuid in ipairs(uuids) do
        if (list[uuid] or 0) == 0 then
            return false
        end
        list[uuid] = list[uuid] - 1
    end
    return true
end

function Training.team()
    local list = {
    }
    for _, item in ipairs(Units.equipped()) do
        table.insert(list, item.uuid)
    end
    return list
end

function Training.target()
    local session = Core.session()
    if not session then
        return nil
    end
    local value, value2
    local evolveUnit = Config.autoEvolve and Config.evolveUnit ~= "" and Config.evolveUnit or nil
    for i, goal in ipairs(Brain.goals or {
    }) do
        local value3, count = nil, 0
        for _, plan in ipairs(goal.plans or {
        }) do
            if plan.takedown then
                value3 = plan
            else
                count = count + 1
            end
        end
        local unitObj = value3 and goal.intoTeam and (goal.pinned or not goal.unknown) and (not evolveUnit or goal.uuid == evolveUnit) and session.collection:get_unit_by_uuid(goal.uuid)
        if unitObj then
            local totalKills = tonumber(value3.what == "kills" and unitObj.total_kills or unitObj.total_takedowns) or 0
            if totalKills < value3.need then
                local num = (count == 0 and 1000 or 0) + (tonumber(goal.tierRank) or 0) * 10 - i * 0.01
                if not value or num > value2 then
                    value, value2 = {
                        uuid = goal.uuid,
                        id = goal.from,
                        to = goal.to,
                        what = value3.what,
                        have = totalKills,
                        need = value3.need
                    }, num
                end
            end
        end
    end
    return value
end

function Training.realHave(on)
    local session = Core.session()
    local unitObj = session and session.collection:get_unit_by_uuid(on.uuid)
    local totalTakedowns = unitObj and tonumber(on.what == "kills" and unitObj.total_kills or unitObj.total_takedowns) or 0
    return math.max(totalTakedowns, on.have + (on.got or 0))
end

function Training.now()
    if Training._at and Utils.now() - Training._at < 10 then
        return Training._t, Training._base
    end
    local base = (Brain.train.on and Brain.train.on.base) or Training.team()
    local base2 = table.clone(base)
    table.sort(base2)
    Training._t, Training._base, Training._at = Training.target(), table.concat(base2, ","), Utils.now()
    return Training._t, Training._base
end

function Training.valueFor(arg1)
    if not (Config.trainTakedowns and Config.goals) then
        return 0, 1
    end
    local item = Brain.trainSim [arg1.key]
    if not (item and item.ok and os.time() - (item.at or 0) < 6 * 3600) then
        return 0, 1
    end
    local now, now2 = Training.now()
    local list = {
    }
    for i, value in ipairs(Brain.savedTeam or {
    }) do
        list [i] = value
    end
    table.sort(list)
    if not (now and item.uuid == now.uuid and (item.base == now2 or item.base == table.concat(list, ","))) or not Training.eligible(arg1) then
        return 0, 1
    end
    local perRun = Training.perRun(arg1.key, now.id) or 0
    local value = math.max(1, now.need - now.have)
    return Config.goalValue * math.min(perRun, value) / value, item.slow or 1
end

function Training.scan()
    local now = Config.trainTakedowns and Config.sim and Training.now()
    if not now then
        return
    end
    local base = (Brain.train.on and Brain.train.on.base) or Training.team()
    for _, value in ipairs(base) do
        if value == now.uuid then
            return
        end
    end
    local count, count2 = 0, 0
    for _, value in ipairs(Modes.lastScored or {
    }) do
        if count >= 3 or count2 >= 2 then
            break
        end
        if Training.eligible(value) then
            local item = Brain.trainSim [value.key]
            local value2 = item and item.uuid == now.uuid and os.time() - (item.at or 0) < 6 * 3600
            local plan = Training.plan(value, now, base)
            if not value2 then
                count2 = count2 + 1
            end
            if plan.ok then
                count = count + 1
            end
        end
    end
    local bestInfinite = Training.bestInfinite()
    if bestInfinite then
        Training.plan(bestInfinite, now, base)
    end
end

function Training.bestInfinite()
    local value, value2
    for _, value3 in ipairs(Modes.lastScored or {
    }) do
        if value3.kind == "infinite" and Training.eligible(value3) then
            local value4, rec = Brain.train.real [value3.key], value3.rec or Modes.rec(value3.key)
            local ratio = (tonumber(rec.timed) or 0) > 0 and rec.sec / rec.timed / 60 or 0
            local ratio2 = (value4 and value4.n > 0 and ratio > 0) and (value4.sum / value4.n) / ratio or 0
            if ratio2 <= 0 then
                ratio2 = Reports.hiveTrainRate(value3.key) or 0
            end
            if ratio2 > (value2 or 0) then
                value, value2 = value3, ratio2
            end
        end
    end
    return value
end

function Training.ratio()
    local cal = Brain.train.cal
    if not (cal and (cal.n or 0) > 0 and (cal.sim or 0) > 0) then
        return 1
    end
    return Utils.clamp(cal.real / cal.sim, 0.05, 2)
end

function Training.perRun(key, id)
    local value = Brain.train.real [key]
    if value and value.n > 0 then
        return value.sum / value.n, true
    end
    local hiveTrain = Reports.hiveTrain(key, id)
    if hiveTrain then
        return hiveTrain, true
    end
    local count, count2 = 0, 0
    local isInf = Modes.isInf(key)
    for key, value in pairs(Brain.train.real) do
        if Modes.isInf(key) == isInf then
            count, count2 = count + value.sum, count2 + value.n
        end
    end
    if count2 > 0 then
        return count / count2, true
    end
    local value = Brain.trainSim [key]
    return value and value.tk and value.tk * Training.ratio() or nil, false
end

function Training.eligible(value)
    if value.kind == "daily" or value.kind == "challenge" then
        return false, "a limited reward, played with your own team"
    end
    if value.kind == "dungeon" then
        return false, "a lost dungeon room costs a life: played with your own team"
    end
    if Core.Levels [value.level] and Core.Levels [value.level]._randomequippedmode then
        return false, "this mode deals you a random team"
    end
    if (Brain.train.bad [value.key] or 0) > os.time() then
        return false, "a training run lost there, so not before " .. os.date("%H:%M", Brain.train.bad [value.key])
    end
    local rec = value.rec or Modes.rec(value.key)
    if rec.runs >= 3 and rec.wins / rec.runs < 0.8 then
        return false, "your farm wins it less than 80% of the time"
    end
    local sim = Modes.sim(value)
    if sim and sim.trust and not sim.trust.ok then
        return false, "the simulator doesn't match real runs there yet"
    end
    return true
end

function Training.plan(bestInfinite, now, base)
    local session = Core.session()
    local base2 = table.clone(base)
    table.sort(base2)
    local joined = table.concat(base2, ",")
    local flag = (tonumber((Brain.simCal [bestInfinite.key] or {
    }).n) or 0) > 0
    local num = flag and 1.3 or 2
    local text = joined .. "+" .. now.uuid .. (flag and "#c" or "#n") .. "#r4"
    local value = Brain.trainSim [bestInfinite.key]
    if value and value.sig == text and not value.pending and os.time() - (value.at or 0) < 6 * 3600 then
        return value
    end
    local info = {
        sig = text,
        base = joined,
        uuid = now.uuid,
        at = os.time(),
        ok = false,
        margin = num,
        pending = true
    }
    Brain.trainSim [bestInfinite.key] = info
    local levelFor, levelFor2 = Simulator.levelFor(bestInfinite)
    if bestInfinite.ldOverride then
        levelFor = bestInfinite.ldOverride
    end
    if not levelFor then
        info.why, info.pending = "the simulator can't play this mode", nil
        return info
    end
    local info2 = Simulator.info(levelFor, bestInfinite.key, levelFor2, bestInfinite.mod)
    local list = {
    }
    for _, value in ipairs(base) do
        local unitObj = session.collection:get_unit_by_uuid(value)
        if unitObj then
            table.insert(list, unitObj)
        end
    end
    local unitObj = session.collection:get_unit_by_uuid(now.uuid)
    if not unitObj or # list == 0 then
        info.why, info.pending = "the unit wasn't found", nil
        return info
    end
    local value = Simulator.run(info2, Simulator.teamFrom(list, info2.map), {
        hpMul = 1
    })
    local unbound = info2.infinite and Simulator.unbound(levelFor)
    local infTier = unbound and Modes.infTier(Simulator.run(info2, Simulator.teamFrom(list, info2.map), {
        hpMul = num
    }).wave) or nil
    local list2 = {
    }
    for i, item in ipairs(list) do
        if not Units.isFarm(item.unit_id) then
            local ok, res = pcall(Units.score, item, bestInfinite.mod)
            table.insert(list2, {
                i = i,
                sc = ok and res or 0
            })
        end
    end
    table.sort(list2, function(arg1, arg2)
        return arg1.sc < arg2.sc
    end)
    local value2
    for i = 1, math.min(3, # list2) do
        local list3 = table.clone(list)
        list3 [list2 [i].i] = unitObj
        local teamFrom = Simulator.teamFrom(list3, info2.map)
        local simResult = Simulator.run(info2, teamFrom, {
            hpMul = num,
            train = now.uuid
        })
        if (unbound and Modes.infTier(simResult.wave) >= infTier) or (not unbound and simResult.won) then
            local value = Simulator.run(info2, teamFrom, {
                hpMul = 1,
                train = now.uuid
            })
            local ratio = (value.tk or 0) / math.max(0.5, value.t / 60)
            if (value.won or unbound) and (not value2 or ratio > math.max(value2.rate * 1.5, value2.rate + 1)) then
                value2 = {
                    out = list [list2 [i].i].unit_id,
                    r = value,
                    rate = ratio,
                    trial = list3
                }
            end
        end
    end
    info.ownMin = value.t / 60
    if not value2 then
        info.why = unbound and string.format("every swap loses a daily milestone (wave %d) against %s enemies in the simulator", infTier, flag and "30% tougher" or "twice as tough") or flag and "no swap still wins with 30% tougher enemies in the simulator" or "no swap still wins against twice as tough enemies in the simulator (no real run there yet)"
    else
        info.out, info.tk, info.minutes = value2.out, value2.r.tk or 0, value2.r.t / 60
        info.uuids = {
        }
        for _, item in ipairs(value2.trial) do
            table.insert(info.uuids, item.uuid)
        end
        info.slow = (value.won and not unbound) and info.minutes / math.max(0.1, info.ownMin) or 1
        if info.tk <= 0 and next(Brain.train.real) == nil then
            info.why = "the simulator says it would hit nothing there"
        elseif info.slow > Training.SLOW then
            info.why = string.format("the clear would be %d%% slower", math.floor((info.slow - 1) * 100 + 0.5))
        else
            info.ok = true
        end
    end
    info.pending = nil
    App.log(1, "TRAIN", string.format("%s: %s%s → %s", bestInfinite.label, Units.name(now.id), info.out and (" in for " .. Units.name(info.out)) or "", info.ok and string.format("trains here (≈%d %s a run, %.1f min vs %.1f with your team)", math.floor((Training.perRun(bestInfinite.key, now.id) or 0) + 0.5), now.what, info.minutes, info.ownMin) or tostring(info.why)))
    App.saveSoon()
    return info
end

function Training.home()
    local on = Brain.train.on
    if not on then
        return
    end
    Brain.train.on = nil
    App.saveSoon()
    if not Training.same(Training.team(), on.uuids or {
    }) then
        App.log(1, "TRAIN", "your team was changed outside the farm, so it stays as it is")
        if not Config.autoTeam then
            Brain.savedTeam = nil
        end
        return
    end
    if Brain.savedTeam and Training.same(Brain.savedTeam, on.base) then
        FarmHub.restoreTeam()
    else
        FarmHub.equipTeam(on.base, "back from takedown training")
    end
    App.log(1, "TRAIN", Units.name(on.out or "?") .. " is back in your team")
end

function Training.apply(train)
    if Modes.hasOwnTeam(train) then
        -- teamFor has already restored training, then equipped the requested lineup.
        if Brain.train.on then
            pcall(Training.home)
        end
        Brain.train.on = nil
        return App.status("Training", "paused for this mode team")
    end
    local testTeam = Brain.testTeam
    if testTeam and (testTeam.left or 0) > 0 and train and testTeam.key == train.key then
        Training.home()
        return App.status("Training", "paused for a team test")
    end
    local target = Config.trainTakedowns and Training.target() or nil
    if not target then
        Training.home()
        return App.status("Training", Config.trainTakedowns and "no evolution is waiting on takedowns" or "off (Units → Goals)")
    end
    local name = Units.name(target.id)
    local text = string.format("%s %s/%s", target.what, Utils.fmt(target.have), Utils.fmt(target.need))
    local on = Brain.train.on
    local base = on and on.base or Training.team()
    for _, value in ipairs(base) do
        if value == target.uuid then
            return App.status("Training", string.format("%s is on your team (%s)", name, text))
        end
    end
    local eligible, eligible2 = Training.eligible(train)
    local plan
    if eligible then
        App.status("Training", string.format("checking %s in %s with the simulator…", name, train.label))
        plan = Training.plan(train, target, base)
        eligible, eligible2 = plan.ok, plan.why
    end
    if not eligible then
        Training.home()
        return App.status("Training", string.format("%s · %s · not in %s: %s", name, text, train.label, tostring(eligible2)))
    end
    if not (on and Training.same(Training.team(), plan.uuids)) then
        FarmHub.equipTeam(plan.uuids, string.format("takedown training: %s in for %s (%s)", name, Units.name(plan.out), train.label))
        local now = Utils.now()
        while Utils.now() - now < 4 and not Training.same(Training.team(), plan.uuids) do
            task.wait(0.25)
        end
        if not Training.same(Training.team(), plan.uuids) then
            if Brain.savedTeam and Training.same(Brain.savedTeam, base) then
                FarmHub.restoreTeam()
            else
                FarmHub.equipTeam(base, "takedown training swap didn't work")
            end
            Brain.train.bad [train.key] = os.time() + 3600
            App.log(1, "TRAIN", "the game didn't take the training team for " .. train.label .. ": your own team is back")
            return App.status("Training", name .. ": the swap didn't work, trying again in an hour")
        end
        Brain.train.on = {
            uuid = target.uuid,
            id = target.id,
            to = target.to,
            what = target.what,
            have = target.have,
            need = target.need,
            got = 0,
            base = base,
            uuids = plan.uuids,
            out = plan.out,
            key = train.key,
            at = os.time()
        }
        App.log(1, "TRAIN", string.format("%s in for %s for %s (%s)", name, Units.name(plan.out), train.label, text))
    end
    Brain.train.on.key = train.key
    local perRun, perRun2 = Training.perRun(train.key, target.id)
    App.status("Training", string.format("%s in for %s in %s · %s · ≈%d a run%s", name, Units.name(plan.out), train.label, text, math.floor((perRun or 0) + 0.5), perRun2 and "" or " (simulated)"))
end

function Training.text()
    if not Config.trainTakedowns then
        return "Off. A unit whose evolution needs takedowns only earns them while you keep it on your team."
    end
    local target = Training.target()
    if not target then
        return "No evolution that would join your team is waiting on takedowns."
    end
    local count, count2 = 0, 0
    for _, value in pairs(Brain.train.real) do
        count = count + value.sum
        count2 = count2 + value.n
    end
    local ratio = count2 > 0 and count / count2 or nil
    local list = {
    }
    for _, value in ipairs(Brain.train.log) do
        if # list < 5 then
            table.insert(list, string.format("+%d (%s, %s)", value.got, GUI.keyName and GUI.keyName(value.key) or value.key, value.won and "won" or "lost"))
        end
    end
    return string.format("%s needs %s %s for %s and has %s.%s%s\n" .. "It joins your team only where the simulator says you still win with 30%% tougher enemies (twice as tough where the farm has no real run yet), in place of your weakest unit that passes that test (a stronger one of your 3 weakest only if it trains 1.5× faster). " .. "Never in the challenges, where your farm wins under 80%% of runs, or where clearing gets more than 40%% slower. " .. "Its progress counts in the mode ranking (Goal Value, spread over the takedowns it still needs). " .. "Your own team goes back after every run, and a lost run stops training in that mode for 6 hours.", Units.name(target.id), Utils.fmt(target.need), target.what, Units.name(target.to), Utils.fmt(target.have), ratio and string.format(" It gets about %d a run, so ≈%d more runs.", math.floor(ratio + 0.5), math.ceil((target.need - target.have) / math.max(1, ratio))) or "", # list > 0 and (" Last runs: " .. table.concat(list, " · ") .. ".") or "")
end

function FarmHub.every(arg1, arg2)
    local now = Utils.now()
    if FarmHub.last [arg1] and now - FarmHub.last [arg1] < arg2 then
        return false
    end
    FarmHub.last [arg1] = now
    return true
end

function FarmHub.refreshLive()
    local live = Brain.live
    local ok, res = App.request("live_n", "get_normal_challenge")
    if ok and type(res) == "table" and res.current_uuid then
        local lost = (live.normal and live.normal.uuid == res.current_uuid) and live.normal.lost or 0
        local doneUuid = (live.normal and live.normal.uuid == res.current_uuid) and live.normal.doneUuid or nil
        local challengeDuration = Core.GS.CHALLENGE_DURATION or 1800
        local ratio = (math.floor(os.time() / challengeDuration) + 1) * challengeDuration
        live.normal = {
            uuid = res.current_uuid,
            level = res.current_level_id,
            challenge = res.current_challenge,
            value = Modes.rewardValue(res.current_reward),
            expires = ratio,
            lost = lost,
            doneUuid = doneUuid
        }
    end
    local ok, res = App.request("live_d", "get_daily_challenge")
    if ok and type(res) == "table" and res.current_uuid then
        local currentLevel = type(res.current_level) == "table" and res.current_level or {
        }
        local dailyMod = Modes.dailyMod(currentLevel._challenge_uuid or res.current_uuid, currentLevel._daily_challenge_weak_against or res.weak_against, currentLevel._daily_challenge_strong_against or res.strong_against)
        local lost = (live.daily and live.daily.uuid == res.current_uuid) and live.daily.lost or 0
        local doneUuid = (live.daily and live.daily.uuid == res.current_uuid) and live.daily.doneUuid or nil
        local slim = type(res.current_level) == "table" and Simulator.slim(res.current_level) or nil
        if slim then
            slim._challenge = res.current_challenge
        end
        live.daily = {
            uuid = res.current_uuid,
            value = Modes.rewardValue(res.current_reward),
            challenge = res.current_challenge,
            mod = dailyMod,
            lost = lost,
            doneUuid = doneUuid,
            ld = slim
        }
    end
    local ok, res = App.request("live_e", "get_event_challenges")
    if ok and type(res) == "table" then
        live.event = nil
        for key, value in pairs(res) do
            local currentLevelData = type(value) == "table" and value.current_level_data
            if type(currentLevelData) == "string" then
                currentLevelData = Core.Levels [currentLevelData]
            end
            if currentLevelData then
                local slim = Simulator.slim(currentLevelData)
                slim._difficulty = slim._difficulty or "Hard"
                live.event = {
                    level = currentLevelData.id or key,
                    name = currentLevelData.name,
                    pad = Core.GS.ACTIVE_EVENT_CHALLENGES and Core.GS.ACTIVE_EVENT_CHALLENGES [key],
                    board = key,
                    map = currentLevelData.map,
                    weather = value.current_weather,
                    ld = slim,
                    forecast = type(value.forecast) == "table" and {
                        map = value.forecast.map,
                        weather = value.forecast.weather,
                        map_hint = value.forecast.map_hint,
                        weather_hint = value.forecast.weather_hint
                    } or nil
                }
            end
        end
    end
    local ok, res, res2 = App.request("live_a", "get_current_artifacts")
    if ok and type(res) == "table" and type(res.world_ids) == "table" then
        local list = {
        }
        for _, worldId in ipairs(res.world_ids) do
            local world = Core.Worlds [worldId]
            local level = world and type(world.levels) == "table" and (world.levels ["1"] or world.levels [1])
            if level and Core.Levels [level.id] then
                table.insert(list, {
                    level = level.id,
                    world = worldId
                })
            end
        end
        live.artifact = {
            list = list,
            interval = res.interval,
            ends = tonumber(res.ends_at),
            ad = type(res2) == "table" and res2 or (live.artifact and live.artifact.interval == res.interval and live.artifact.ad) or nil
        }
    end
    live.at = os.time()
    App.saveSoon()
end

function FarmHub.rewards()
    if not Config.rewards then
        return App.status("Rewards", "off")
    end
    local session = Core.session()
    local prof = Core.prof()
    if not (session and prof) then
        return
    end
    local list = {
    }
    if (os.time() - (tonumber(prof.last_daily_reward_claimed_time) or 0)) >= (Core.GS.DAILY_REWARD_WAIT or 82800) then
        local ok, res = App.request("daily", "claim_daily_reward")
        if ok and res then
            table.insert(list, "daily login")
        end
    end
    for questKey, quest in pairs(session.quest_handler.quest_profile_data.quests or {
    }) do
        local ok, res = pcall(Core.QCC.is_quest_complete, session, quest)
        if ok and res and not Brain.claims [questKey] then
            local ok, res = App.request("quest", "redeem_quest", questKey)
            if ok and res then
                Brain.claims [questKey] = os.time()
                table.insert(list, "quest " .. tostring(quest.quest_info and (quest.quest_info.name or quest.quest_info.id) or ""))
            else
                Brain.claims [questKey] = os.time() - 259200 + 3600
            end
            task.wait(0.3)
        end
    end
    if FarmHub.every("bp", 600) then
        App.request("bp", "claim_battlepass_rewards")
    end
    if FarmHub.every("bingo", 120) then
        pcall(Hunt.claim)
    end
    if FarmHub.every("clr", 300) then
        for completedStoryLevelKey, completedStoryLevel in pairs(prof.level_data.completed_story_levels or {
        }) do
            local level = Core.Levels [completedStoryLevelKey]
            if level and level.clear_rewards and completedStoryLevel.difficulty_completed_data then
                for clearRewardKey, clearReward in pairs(level.clear_rewards) do
                    local timesCompleted = completedStoryLevel.difficulty_completed_data [clearRewardKey] and completedStoryLevel.difficulty_completed_data [clearRewardKey].times_completed or 0
                    for _, value in pairs(clearReward) do
                        local value2 = prof.clear_rewards [completedStoryLevelKey] and prof.clear_rewards [completedStoryLevelKey] [clearRewardKey] and prof.clear_rewards [completedStoryLevelKey] [clearRewardKey] [value._id]
                        local text = completedStoryLevelKey .. clearRewardKey .. tostring(value._id)
                        if not value2 and timesCompleted >= (value.clears or 1e9) and not Brain.claims [text] then
                            local ok, res = App.request("clr", "claim_first_clear_rewards", completedStoryLevelKey, clearRewardKey, value._id)
                            Brain.claims [text] = os.time()
                            if ok and res then
                                table.insert(list, "milestone " .. Modes.levelName(completedStoryLevelKey))
                            end
                        end
                    end
                end
            end
        end
    end
    if FarmHub.every("clrA", 300) then
        for _, item in ipairs(Brain.live.artifact and Brain.live.artifact.list or {
        }) do
            local level = Core.Levels [item.level]
            local artifactLeft, _, _, artifactLeft4 = Modes.artifactLeft(item.level)
            for _, value in pairs(level and level.clear_rewards and level.clear_rewards.Hard or {
            }) do
                local text = "ar" .. item.level .. tostring(Brain.live.artifact.interval) .. tostring(value._id)
                if not artifactLeft4 [value._id] and artifactLeft >= (tonumber(value.clears) or 1e9) and not Brain.claims [text] then
                    local ok, res = App.request("clr", "claim_first_clear_rewards", item.level, "Hard", value._id)
                    Brain.claims [text] = os.time()
                    if ok and res then
                        table.insert(list, "Artifact Stage " .. tostring(value._reward_text or value._id))
                    end
                end
            end
        end
    end
    for claimKey, claim in pairs(Brain.claims) do
        if os.time() - claim > 259200 then
            Brain.claims [claimKey] = nil
        end
    end
    if # list > 0 then
        App.log(1, "REWARD", "claimed " .. table.concat(list, ", "))
    end
    App.status("Rewards", # list > 0 and ("claimed " .. table.concat(list, ", ")) or "nothing waiting")
end

function FarmHub.goldShop()
    if not Config.goldShop then
        return App.status("Gold Shop", "off")
    end
    Brain.str.shopAt = os.time()
    local prof = Core.prof()
    local session = Core.session()
    if not (prof and session) then
        return
    end
    local ok, res = App.request("gshop", "request_current_gold_shop")
    if not (ok and type(res) == "table") then
        return App.status("Gold Shop", "shop not answering")
    end
    local count = 0
    local boughtItems = (type(prof.gold_shop_data) == "table" and type(prof.gold_shop_data.bought_items) == "table") and prof.gold_shop_data.bought_items or {
    }
    local function helper(arg1, arg2)
        if arg2.stock == "inf" then
            return math.huge
        end
        return math.max(0, (tonumber(arg2.stock) or 0) - (tonumber(boughtItems [arg1]) or 0))
    end
    for key, value in pairs(res) do
        if type(value) == "table" and tostring(value.id or key):find("^StarFruit") and helper(key, value) > 0 then
            local itemCap = Core.GS.ITEM_CAPS and Core.GS.ITEM_CAPS [value.id] or 1e9
            local count2 = 0
            pcall(function()
                count2 = session.inventory:get_number_of_owned_item(value.id)
            end)
            local goldCost = tonumber(value.gold_cost) or 1e12
            local value2 = helper(key, value)
            while value2 > 0 and count2 < itemCap and (tonumber(prof.gold_amount) or 0) - goldCost >= Config.goldFloor and count < 10 do
                local goldAmount = tonumber(prof.gold_amount) or 0
                local now = Utils.now()
                local ok, res = App.request("gbuy", "buy_gold_shop_item", key, "1")
                local now2 = Utils.now()
                while Utils.now() - now2 < 3 and (tonumber(prof.gold_amount) or 0) >= goldAmount do
                    task.wait(0.2)
                end
                if not ok or (tonumber(prof.gold_amount) or 0) >= goldAmount then
                    App.log(1, "SHOP", "gold shop refused " .. tostring(key) .. " (" .. tostring(App.gameSaid(now) or res) .. ")")
                    App.backoff("gbuy", 600)
                    break
                end
                count = count + 1
                value2 = value2 - 1
                count2 = count2 + 1
                Spending.add((Core.Items [value.id] and Core.Items [value.id].name or value.id), goldCost, "gold", string.format("evolve material, %d/%d held · gold floor %s", count2, itemCap, Utils.fmt(Config.goldFloor)))
            end
        end
    end
    local count2, count3 = 0, 0
    if Config.team and Config.teamXp and Config.teamBuyXp then
        local core, value
        pcall(function()
            core = Core.core("ProgressionServiceCore")
            value = Core.data("WorldLevelOrder")
        end)
        local function helper2(arg1)
            local value2 = Core.LU and type(Core.LU.xp_items_order) == "table" and Core.LU.xp_items_order [arg1]
            local value3 = value2 and value and type(value.WORLD_ORDER) == "table" and value.WORLD_ORDER [value2]
            if not (value3 and core and core.check_if_unlocked_story_world) then
                return true
            end
            local ok, res = pcall(core.check_if_unlocked_story_world, Core.session(), value3)
            return ok and res == true
        end
        local list, count = {
        }, 0
        for key, value in pairs(res) do
            local item = type(value) == "table" and Core.Items [value.id or key]
            if item and type(item.usage) == "table" and item.usage.type == "xp_feed" and helper(key, value) > 0 and tonumber(value.gold_cost) and (tonumber(item.usage.xp_amount) or 0) / math.max(1, tonumber(value.gold_cost)) >= 3 then
                if helper2(value.id or key) then
                    table.insert(list, {
                        key = key,
                        id = value.id or key,
                        it = value,
                        xp = tonumber(item.usage.xp_amount) or 0,
                        cost = tonumber(value.gold_cost)
                    })
                else
                    count = count + 1
                end
            end
        end
        table.sort(list, function(arg1, arg2)
            return arg1.xp / arg1.cost > arg2.xp / arg2.cost
        end)
        local xpRoom = Strategy.xpRoom()
        for _, value in ipairs(Strategy.foodHeld()) do
            xpRoom = xpRoom - value.n * value.xp
        end
        if Config.strDry then
            local list2, goldAmount, count2 = {
            }, tonumber(prof.gold_amount) or 0, 0
            for _, item in ipairs(list) do
                local value = math.min(helper(item.key, item.it), math.floor(math.max(0, goldAmount - Config.xpGoldFloor) / item.cost), item.xp > 0 and math.floor(xpRoom / item.xp) or 0)
                if value > 0 then
                    table.insert(list2, string.format("%d %s", value, (Core.Items [item.id] or {
                    }).name or item.id))
                    goldAmount, xpRoom, count2 = goldAmount - value * item.cost, xpRoom - value * item.xp, count2 + value
                end
            end
            local text = (count2 > 0 and string.format("dry run: would buy %s for %s gold", table.concat(list2, ", "), Utils.fmt((tonumber(prof.gold_amount) or 0) - goldAmount)) or "dry run: no XP food worth buying (your core units are full, or gold is at the line)") .. (count > 0 and string.format(" · %d kinds locked behind later worlds", count) or "")
            if Brain.str.dryShop ~= text then
                Brain.str.dryShop = text
                App.log(1, Strategy.LOG, text)
            end
        else
            local flag
            local function helper2()
                return tonumber(Core.cur("gold")) or tonumber(prof.gold_amount) or 0
            end
            for _, item in ipairs(list) do
                if flag then
                    break
                end
                local value = helper(item.key, item.it)
                while value > 0 and xpRoom > 0 and item.xp > 0 and helper2() - item.cost >= Config.xpGoldFloor and count2 < 80 do
                    local num = (value >= 10 and helper2() - item.cost * 10 >= Config.xpGoldFloor and xpRoom >= item.xp * 10) and 10 or 1
                    local value2, have = helper2(), Adventure.have(item.id)
                    local now = Utils.now()
                    local ok, res = App.request("xpbuy", "buy_gold_shop_item", item.key, tostring(num))
                    if not ok and (res == "slowing down" or res == "waiting") then
                        task.wait(3.5)
                        continue
                    end
                    local now2 = Utils.now()
                    while Utils.now() - now2 < 3 and helper2() >= value2 and Adventure.have(item.id) <= have do
                        task.wait(0.2)
                    end
                    if not ok or (helper2() >= value2 and Adventure.have(item.id) <= have) then
                        App.log(1, "SHOP", "gold shop refused " .. tostring(item.key) .. " ×" .. num .. " (" .. tostring(App.gameSaid(now) or res) .. "): XP food waits for the next pass")
                        App.backoff("xpbuy", 600)
                        flag = true
                        break
                    end
                    count2, value, xpRoom, count3 = count2 + num, value - num, xpRoom - item.xp * num, count3 + item.xp * num
                    Spending.add((Core.Items [item.id] or {
                    }).name or item.id, item.cost * num, "gold", string.format("XP food for your team: %s XP · gold kept %s", Utils.fmt(item.xp * num), Utils.fmt(Config.xpGoldFloor)))
                end
            end
            if count2 > 0 then
                App.log(1, Strategy.LOG, string.format("bought %d XP food (%s XP) in the gold shop · gold %s", count2, Utils.fmt(count3), Utils.fmt(prof.gold_amount)))
            end
        end
    end
    App.status("Gold Shop", (count > 0 or count2 > 0) and string.format("bought %d Star Fruit(s), %d XP food", count, count2) or string.format("nothing to buy (gold %s, floor %s)", Utils.fmt(prof.gold_amount), Utils.fmt(Config.goldFloor)))
end
FarmHub.SNIPE_KEEP = {
    gems = "snipeGemFloor",
    SummerPearls = "snipePearlFloor",
    GemsLegacy = "snipeLegacyFloor"
}
FarmHub.SNIPE_ALSO = {
    griffith = {
        "griffith_reincarnation"
    }
}

function FarmHub.snipeForms(arg1)
    local list, list2 = {
    }, {
    }
    while arg1 and Core.Units [arg1] and not list2 [arg1] do
        list2 [arg1] = true
        table.insert(list, arg1)
        local evolve = Core.Units [arg1].evolve
        arg1 = type(evolve) == "table" and evolve.evolve_unit or nil
    end
    for _, value in ipairs(FarmHub.SNIPE_ALSO [list [1]] or {
    }) do
        table.insert(list, value)
    end
    return list
end

function FarmHub.snipeHas(snipeUnit)
    snipeUnit = snipeUnit or Config.snipeUnit
    if not snipeUnit or snipeUnit == "" then
        return false
    end
    for _, snipeForm in ipairs(FarmHub.snipeForms(snipeUnit)) do
        if FarmHub.hatched [snipeForm] or Units.owns(snipeForm) then
            return true
        end
    end
    return false
end

function FarmHub.snipeCost(snipeWhere)
    local bannerCost = FarmHub.bannerCost(snipeWhere)
    local banner = Core.Banners [snipeWhere]
    if not (bannerCost and banner) then
        return nil
    end
    bannerCost.cur = (banner.item_cost and banner.item_cost.item_id) or (banner.resource_cost and banner.resource_cost.id) or "gems"
    bannerCost.keep = tonumber(Config [FarmHub.SNIPE_KEEP [bannerCost.cur] or bannerCost.floor]) or 0
    bannerCost.label = FarmHub.BANNER_NAME [snipeWhere] or snipeWhere
    return bannerCost
end

function FarmHub.watchRoom()
    local prof = Core.prof()
    local count = 0
    for _ in pairs(prof.collection.owned_units) do
        count = count + 1
    end
    return count + 20 <= (tonumber(prof.collection.capacity) or math.huge)
end

function FarmHub.snipeSay(arg1, arg2)
    Brain.snipe.note, Brain.snipe.noteAt = arg1, os.time()
    App.log(1, "SUMMON", "Banner Snipe: " .. arg1)
    if App.notify then
        App.notify("Banner Snipe", arg1, arg2 or "success")
    end
    App.saveSoon()
end

function FarmHub.snipeRate()
    local huge
    for _, banner in pairs(Core.Banners or {
    }) do
        if type(banner) == "table" and banner.active and not banner._does_not_rotate and tonumber(banner.HATCH_REFRESH_RATE) then
            huge = math.min(huge or math.huge, tonumber(banner.HATCH_REFRESH_RATE))
        end
    end
    return huge or 14400
end

function FarmHub.snipeTurnAfter(now)
    local snipeRate = FarmHub.snipeRate()
    local clock = Brain.snipe.clock
    local value = (clock and tonumber(clock.next) or 0) % snipeRate
    return math.floor((now - value) / snipeRate + 1) * snipeRate + value
end

function FarmHub.snipeStale()
    local snipe = Brain.snipe
    if not snipe.lookAt then
        return true
    end
    return os.time() >= FarmHub.snipeTurnAfter(snipe.lookAt) or (tonumber(snipe.changedAt) or 0) > snipe.lookAt
end

function FarmHub.snipeHeard(arg1, ...)
    local snipe = Brain.snipe
    local pack = table.pack(...)
    local function helper()
        local list = {
        }
        for i = 1, math.min(pack.n, 4) do
            local value = pack [i]
            if type(value) == "table" then
                local list2 = {
                }
                for key in pairs(value) do
                    if # list2 < 8 then
                        table.insert(list2, tostring(key))
                    end
                end
                table.insert(list, "{" .. table.concat(list2, ",") .. "}")
            else
                table.insert(list, tostring(value):sub(1, 40))
            end
        end
        return table.concat(list, ", ")
    end
    if arg1 == "hatch_refresh_remaining_time_changed" then
        if not snipe.clockSeen then
            snipe.clockSeen = true
            App.log(1, "SUMMON", "Banner Snipe: the game's hourly countdown says " .. helper())
        end
        return
    end
    snipe.clock = {
        next = math.floor((os.time() + 30) / 60) * 60 + FarmHub.snipeRate(),
        at = os.time(),
        src = "changed"
    }
    local list, text = {
    }, nil
    for i = 1, pack.n do
        if type(pack [i]) == "table" then
            for key, value in pairs(pack [i]) do
                if type(value) == "table" and Core.Banners [key] then
                    if not text then
                        local list = {
                        }
                        for key, value in pairs(value) do
                            if # list < 10 then
                                table.insert(list, tostring(key) .. ":" .. type(value))
                            end
                        end
                        text = tostring(key) .. " {" .. table.concat(list, ",") .. "}"
                    end
                    local rateupUnits = type(value.rateup_units) == "table" and value.rateup_units or nil
                    if rateupUnits then
                        local list2 = {
                        }
                        for _, rateupUnit in pairs(rateupUnits) do
                            if type(rateupUnit) == "string" and Core.Units [rateupUnit] then
                                table.insert(list2, rateupUnit)
                            end
                        end
                        table.sort(list2)
                        if # list2 > 0 then
                            list [key] = list2
                        end
                    end
                end
            end
        end
    end
    if next(list) then
        for key, value in pairs(snipe.feat or {
        }) do
            if not list [key] then
                list [key] = value
            end
        end
        snipe.feat, snipe.lookAt, snipe.changedAt = list, os.time(), os.time()
        local list2 = {
        }
        for itemKey, item in pairs(list) do
            local list = {
            }
            for _, unitId in ipairs(item) do
                table.insert(list, Units.name(unitId))
                snipe.seen [unitId] = {
                    banner = itemKey,
                    at = os.time()
                }
            end
            table.insert(list2, (FarmHub.BANNER_NAME [itemKey] or itemKey) .. ": " .. table.concat(list, ", "))
        end
        table.sort(list2)
        App.log(1, "SUMMON", "Banner Snipe: the banners changed: " .. table.concat(list2, " · "))
        local snipeWhere = Config.snipeOn and Config.snipeUnit ~= "" and not FarmHub.snipeHas() and FarmHub.snipeWhere(Config.snipeUnit)
        if snipeWhere and snipe.featured ~= snipeWhere then
            snipe.featured = snipeWhere
            FarmHub.snipeSay(string.format("%s is featured on %s right now%s", Units.name(Config.snipeUnit), FarmHub.BANNER_NAME [snipeWhere] or snipeWhere, App.where == "match" and ": the lobby pulls after this match" or ""))
        end
    else
        snipe.changedAt = os.time()
        App.log(1, "SUMMON", "Banner Snipe: the game says a banner changed (" .. helper() .. (text and ("; " .. text) or "") .. ")" .. (App.where == "match" and ": the lobby looks after this match" or ""))
    end
    FarmHub.last.snipe = nil
    App.saveSoon()
end

function FarmHub.snipeLook()
    local snipe = Brain.snipe
    local ok, res = App.request("hatch", "get_hatch_setup_data")
    if not (ok and type(res) == "table") then
        return nil
    end
    local list, list2 = {
    }, {
    }
    for key, value in pairs(res) do
        if type(value) == "table" then
            for key in pairs(value) do
                list2 [tostring(key)] = true
            end
            if type(value.rateup_units) == "table" and Core.Banners [key] then
                local list2 = {
                }
                for _, rateupUnit in pairs(value.rateup_units) do
                    if type(rateupUnit) == "string" and Core.Units [rateupUnit] then
                        table.insert(list2, rateupUnit)
                    end
                end
                table.sort(list2)
                list [key] = list2
                for _, item in ipairs(list2) do
                    snipe.seen [item] = {
                        banner = key,
                        at = os.time()
                    }
                end
            end
        end
    end
    if not snipe.keysSeen then
        local list = {
        }
        for itemKey in pairs(list2) do
            table.insert(list, itemKey)
        end
        table.sort(list)
        snipe.keysSeen = true
        App.log(1, "SUMMON", "Banner Snipe: a banner from the game carries " .. table.concat(list, ", "))
    end
    snipe.feat, snipe.lookAt = list, os.time()
    return list
end

function FarmHub.snipeWhere(snipeUnit)
    local value, value2
    for key, value3 in pairs(Brain.snipe.feat or {
    }) do
        local banner = Core.Banners [key]
        if banner and banner.active and table.find(value3, snipeUnit) then
            local snipeCost = FarmHub.snipeCost(key)
            local num = not snipeCost and 9 or snipeCost.cur == "GemsLegacy" and 1 or snipeCost.cur == "gems" and 3 or 2
            if not value2 or num < value2 then
                value, value2 = key, num
            end
        end
    end
    return value
end

function FarmHub.bannerSnipe()
    if Config.unitsPaused then
        return
    end
    if not (Config.snipeOn and Config.snipeUnit ~= "") then
        return
    end
    local snipe = Brain.snipe
    local snipeUnit = Config.snipeUnit
    local name = Units.name(snipeUnit)
    if snipe.unit ~= snipeUnit then
        snipe.unit, snipe.pulls, snipe.got, snipe.featured, snipe.note, snipe.saidAt = snipeUnit, 0, nil, nil, nil, nil
    end
    if Adventure.have("celestial_compass_u21") > 0 and not (snipe.compass and snipe.compass.unit == snipeUnit) then
        local ok, res = App.request("hatch", "get_celestial_compass_units", "celestial_compass_u21")
        if ok and type(res) == "table" then
            local flag, count = false, 0
            for _, value in pairs(res) do
                count = count + 1
                if value == snipeUnit then
                    flag = true
                end
            end
            snipe.compass = {
                unit = snipeUnit,
                at = os.time(),
                n = count,
                on = flag
            }
            App.log(1, "SUMMON", string.format("Celestial Compass: it can pick %d units, %s", count, flag and (name .. " among them") or ("not " .. name)))
            if flag then
                FarmHub.snipeSay("your Celestial Compass can pick " .. name .. ". It's still in your bag: that pick is yours to make")
            end
        end
    end
    if FarmHub.snipeHas(snipeUnit) then
        if not snipe.got then
            snipe.got = os.time()
            FarmHub.snipeSay("you have " .. name .. "!")
        end
        return
    end
    if not FarmHub.snipeLook() then
        return
    end
    local snipeWhere = FarmHub.snipeWhere(snipeUnit)
    if not snipeWhere then
        if snipe.featured then
            FarmHub.snipeSay(string.format("%s isn't featured any more. It waits for the next turnover (%s)", name, os.date("%H:%M", FarmHub.snipeTurnAfter(os.time()))), "warning")
        end
        snipe.featured = nil
        return
    end
    local snipeCost = FarmHub.snipeCost(snipeWhere)
    if not snipeCost then
        return
    end
    if snipe.featured ~= snipeWhere then
        snipe.featured = snipeWhere
        FarmHub.snipeSay(string.format("%s is featured on %s right now", name, snipeCost.label))
    end
    local list = {
    }
    for _, value in ipairs({
        "gems",
        "GemsLegacy",
        "SummerPearls"
    }) do
        if value ~= snipeCost.cur then
            list [value] = tonumber(Core.cur(value)) or 0
        end
    end
    local count, count2 = 0, 0
    while App.alive and Config.snipeOn and Config.snipeUnit == snipeUnit and snipeCost.have() - snipeCost.cost * 10 >= snipeCost.keep and FarmHub.watchRoom() and not FarmHub.snipeHas(snipeUnit) do
        local have, now = snipeCost.have(), Utils.now()
        local ok, res = App.request("snipe", "buy_from_banner", snipeWhere, "gems10")
        if not ok and (res == "slowing down" or res == "waiting") and count2 < 3 then
            count2 = count2 + 1
            task.wait(3.5)
            continue
        end
        local now2 = Utils.now()
        while Utils.now() - now2 < 4 and snipeCost.have() >= have do
            task.wait(0.25)
        end
        for itemKey, item in pairs(list) do
            if (tonumber(Core.cur(itemKey)) or 0) < item then
                Config.snipeOn = false
                pcall(function()
                    GUI.UI.snipeOn.Set(false, true)
                end)
                App.saveSoon()
                return FarmHub.snipeSay(string.format("%s went down during a pull on %s, so Banner Snipe switched itself off", itemKey == "gems" and "Gems" or itemKey, snipeCost.label), "warning")
            end
        end
        if snipeCost.have() >= have then
            local gameSaid = App.gameSaid(now) or res
            if tostring(gameSaid):lower():find("too fast") and count2 < 3 then
                count2 = count2 + 1
                task.wait(6)
                continue
            end
            App.log(1, "SUMMON", "Banner Snipe: " .. snipeCost.label .. " refused (" .. tostring(gameSaid) .. ")")
            App.backoff("snipe", 600)
            break
        end
        count2 = 0
        count = count + 10
        snipe.pulls = (tonumber(snipe.pulls) or 0) + 10
        Spending.add("10 summons on " .. snipeCost.label, have - snipeCost.have(), snipeCost.name, "Banner Snipe: " .. name .. " is featured")
        task.wait(5)
    end
    local snipeTurnAfter = FarmHub.snipeTurnAfter(os.time())
    if FarmHub.snipeHas(snipeUnit) then
        snipe.got = os.time()
        FarmHub.snipeSay(string.format("you have %s! It dropped after %d pulls", name, tonumber(snipe.pulls) or 0))
    elseif snipe.saidAt ~= snipeTurnAfter and not FarmHub.watchRoom() then
        snipe.saidAt = snipeTurnAfter
        FarmHub.snipeSay(name .. " is featured, but your unit storage is nearly full. Sell some units and it carries on", "warning")
    elseif snipe.saidAt ~= snipeTurnAfter and snipeCost.have() - snipeCost.cost * 10 < snipeCost.keep then
        snipe.saidAt = snipeTurnAfter
        FarmHub.snipeSay(string.format("%s is featured, but %s is at your Keep line (%s, keeping %s) after %d pulls", name, snipeCost.name, Utils.fmt(snipeCost.have()), Utils.fmt(snipeCost.keep), tonumber(snipe.pulls) or 0), "warning")
    end
end

function FarmHub.snipeWanted()
    if not (Config.snipeOn and Config.snipeUnit ~= "") or FarmHub.snipeHas() or FarmHub.snipeStale() then
        return false
    end
    if App.req.back.snipe and Utils.now() < App.req.back.snipe then
        return false
    end
    local snipeWhere = FarmHub.snipeWhere(Config.snipeUnit)
    local snipeCost = snipeWhere and FarmHub.snipeCost(snipeWhere)
    return snipeCost ~= nil and snipeCost.have() - snipeCost.cost * 10 >= snipeCost.keep and FarmHub.watchRoom()
end

function FarmHub.snipeDue()
    if not (Config.snipeOn and Config.snipeUnit ~= "") or FarmHub.snipeHas() or not FarmHub.snipeStale() then
        return false
    end
    local snipe = Brain.snipe
    local snipeTurnAfter = FarmHub.snipeTurnAfter(os.time()) - FarmHub.snipeRate()
    if (tonumber(snipe.askAt) or 0) >= math.max(snipeTurnAfter, tonumber(snipe.changedAt) or 0) or not FarmHub.watchRoom() then
        return false
    end
    local flag = false
    for bannerKey, banner in pairs(Core.Banners or {
    }) do
        local snipeCost = type(banner) == "table" and banner.active and FarmHub.snipeCost(bannerKey)
        if snipeCost and snipeCost.have() - snipeCost.cost * 10 >= snipeCost.keep then
            flag = true
        end
    end
    if not flag then
        return false
    end
    snipe.askAt = os.time()
    return true
end

function FarmHub.snipeText()
    local snipe = Brain.snipe
    local snipeUnit = Config.snipeUnit
    local list = {
    }
    if snipeUnit == "" then
        table.insert(list, "Pick a unit below. It's pulled on whichever banner features it, until it drops or a Keep line below is reached.")
    elseif FarmHub.snipeHas(snipeUnit) then
        table.insert(list, "You have " .. Units.name(snipeUnit) .. ".")
    elseif not Config.snipeOn then
        table.insert(list, Units.name(snipeUnit) .. " is picked. Switch Banner Snipe on to pull for it.")
    else
        local snipeWhere = not FarmHub.snipeStale() and FarmHub.snipeWhere(snipeUnit)
        table.insert(list, snipeWhere and (Units.name(snipeUnit) .. " is featured on " .. (FarmHub.BANNER_NAME [snipeWhere] or snipeWhere) .. " right now.") or ("Waiting for " .. Units.name(snipeUnit) .. " to be featured."))
    end
    if snipe.lookAt then
        local list2 = {
        }
        for key, value in pairs(snipe.feat or {
        }) do
            local list = {
            }
            for _, unitId in ipairs(value) do
                table.insert(list, Units.name(unitId))
            end
            if # list > 0 then
                table.insert(list2, (FarmHub.BANNER_NAME [key] or key) .. ": " .. table.concat(list, ", "))
            end
        end
        table.sort(list2)
        table.insert(list, "Featured at " .. os.date("%H:%M", snipe.lookAt) .. " · " .. table.concat(list2, " · "))
    end
    table.insert(list, string.format("Banners turn over next at %s%s", os.date("%H:%M", FarmHub.snipeTurnAfter(os.time())), snipe.clock and "" or " (expected)"))
    table.insert(list, string.format("Gems %s · Pearls %s · Legacy Gems %s · pulled so far: %d", Utils.fmt(tonumber(Core.cur("gems")) or 0), Utils.fmt(tonumber(Core.cur("SummerPearls")) or 0), Utils.fmt(tonumber(Core.cur("GemsLegacy")) or 0), tonumber(snipe.pulls) or 0))
    if snipe.note then
        table.insert(list, os.date("%H:%M", snipe.noteAt or os.time()) .. " " .. snipe.note)
    end
    return table.concat(list, "\n")
end

function FarmHub.summon()
    if Config.unitsPaused then
        return
    end
    local prof = Core.prof()
    if not prof then
        return
    end
    local list = {
    }
    local function helper(arg1, _arg2, arg3, arg4, arg5, arg6, arg7, arg8)
        local count, count2 = 0, 0
        while count < Config.summonsPerVisit and arg3() - arg5 * 10 >= arg4 and not (arg8 and arg8()) do
            local value = arg3()
            local now = Utils.now()
            local ok, res = App.request("summon", "buy_from_banner", arg1, "gems10")
            if not ok and (res == "slowing down" or res == "waiting") and count2 < 3 then
                count2 = count2 + 1
                task.wait(3.5)
                continue
            end
            local now2 = Utils.now()
            while Utils.now() - now2 < 4 and arg3() >= value do
                task.wait(0.1)
            end
            if not ok or arg3() >= value then
                local gameSaid = App.gameSaid(now) or res
                if tostring(gameSaid):lower():find("too fast") and count2 < 3 then
                    count2 = count2 + 1
                    task.wait(2 * count2)
                    continue
                end
                App.log(1, "SUMMON", arg1 .. " refused (" .. tostring(gameSaid) .. ")")
                App.backoff("summon", 600)
                break
            end
            count2 = 0
            count = count + 10
            Spending.add("10 summons on " .. arg1, value - arg3(), arg7, arg6)
            task.wait(0.3)
        end
        return count
    end
    if Config.summonApril and Core.Banners.April2025 then
        local pullGoal = Adventure.pullGoal()
        local list2, list3 = {
        }, {
        }
        local function helper2(unitId)
            if not table.find(list3, unitId) then
                table.insert(list2, Units.name(unitId))
                table.insert(list3, unitId)
            end
        end
        if pullGoal then
            if pullGoal.step == "pull" then
                helper2(pullGoal.id)
            end
        else
            for _, value in ipairs({
                "osaka",
                "dokuro",
                "rikka",
                "chihiro"
            }) do
                local _, tierBest2 = Adventure.tierBest(value)
                if not Units.owns(value) and (not Config.community or tierBest2 >= Adventure.TIER_RANK.S) then
                    helper2(value)
                end
            end
        end
        for _, aprilTarget in ipairs(Config.aprilTargets or {
        }) do
            if Core.Units [aprilTarget] and not Units.owns(aprilTarget) and not FarmHub.hatched [aprilTarget] then
                helper2(aprilTarget)
            end
        end
        local aprilFloor = Config.aprilFloor
        if pullGoal and pullGoal.item and not pullGoal.haveItem then
            aprilFloor = math.max(aprilFloor, pullGoal.itemCost)
        end
        local fn = function()
            return Core.cur("AprilCoins")
        end
        if # list2 == 0 then
            table.insert(list, pullGoal and ("April banner: " .. Units.name(pullGoal.id) .. " is yours ✓") or (Config.community and "April banner: you have every limited unit worth the coins ✓" or "April banner: all limited units owned ✓"))
        else
            local function helper2(arg1)
                return FarmHub.hatched [arg1] or Units.owns(arg1)
            end
            local fn2 = function()
                for _, item in ipairs(list3) do
                    if not helper2(item) then
                        return false
                    end
                end
                return true
            end
            local value = helper("April2025", "AprilCoins", fn, aprilFloor, 150, "for " .. table.concat(list2, ", "), "AprilCoins", fn2)
            for _, item in ipairs(list3) do
                if helper2(item) then
                    App.log(1, "SUMMON", Units.name(item) .. " dropped from the April banner!")
                    if pullGoal and item == pullGoal.id then
                        if App.notify then
                            App.notify("Main goal", Units.name(pullGoal.id) .. " is yours! Next: its evolve item (" .. Utils.fmt(pullGoal.itemCost) .. " AprilCoins)", "success")
                        end
                        pcall(Adventure.refresh)
                    elseif App.notify then
                        App.notify("April banner", Units.name(item) .. " is yours!", "success")
                    end
                end
            end
            table.insert(list, string.format("April banner: %s (%s coins, keeping %s)", value > 0 and (value .. " summons") or "saving", Utils.fmt(fn()), Utils.fmt(aprilFloor)))
        end
    end
    if Config.summonGems then
        local equipped = Units.equipped()
        local huge = math.huge
        for _, value in ipairs(equipped) do
            if not Units.isFarm(value.id) then
                huge = math.min(huge, Units.score(value.u))
            end
        end
        local ok, res = App.request("hatch", "get_hatch_setup_data")
        local list2, count = {
        }, 0
        if ok and type(res) == "table" and res.EventClover and res.EventClover.rateup_units then
            for _, rateupUnit in pairs(res.EventClover.rateup_units) do
                local tierBest, tierBest2 = Adventure.tierBest(rateupUnit, true)
                if Core.Units [rateupUnit] and not Units.owns(rateupUnit) and Units.hidden(rateupUnit) and tierBest2 >= Adventure.TIER_RANK.S then
                    table.insert(list2, Units.name(tierBest) .. " (tier " .. tostring((Adventure.tier(tierBest, true))) .. ")")
                elseif Core.Units [rateupUnit] and not Units.owns(rateupUnit) and Units.hidden(rateupUnit) then
                    count = count + 1
                elseif Core.Units [rateupUnit] and not Units.owns(rateupUnit) then
                    local info = {
                        unit_id = rateupUnit,
                        uuid = "sim:" .. rateupUnit,
                        xp = 0,
                        traits = {
                        },
                        trait_stats = {
                            potency_stat = 1,
                            speed_stat = 1,
                            range_stat = 1
                        }
                    }
                    local ok, res = pcall(Units.score, info)
                    if ok and res > huge then
                        table.insert(list2, Units.name(rateupUnit))
                    end
                end
            end
        end
        if # list2 == 0 then
            table.insert(list, "gem banner: nothing that beats your team" .. (count > 0 and string.format(" (%d featured units can't be judged: the game hides their upgrades)", count) or ""))
        else
            local fn = function()
                return Core.cur("gems")
            end
            local value = helper("EventClover", "gems", fn, Config.gemFloor, 50, "would beat your weakest unit: " .. table.concat(list2, ", "), "gems")
            table.insert(list, string.format("gem banner: %s", value > 0 and (value .. " summons") or "saving"))
        end
    end
    if Config.autoSummon and Config.summonBanner ~= "" and not (App.req.back.summon and Utils.now() < App.req.back.summon) then
        local bannerCost = FarmHub.bannerCost(Config.summonBanner)
        if bannerCost then
            local function helper2()
                local count = 0
                for _ in pairs(prof.collection.owned_units) do
                    count = count + 1
                end
                return count + 20 > (tonumber(prof.collection.capacity) or math.huge)
            end
            local value = helper(Config.summonBanner, bannerCost.name, bannerCost.have, Config [bannerCost.floor], bannerCost.cost, "Auto Summon: your pick (Units → Summon)", bannerCost.name, helper2)
            local summonBanner = FarmHub.BANNER_NAME [Config.summonBanner] or Config.summonBanner
            table.insert(list, value > 0 and string.format("%s: %d summons", summonBanner, value) or (helper2() and (summonBanner .. ": your unit storage is full") or (summonBanner .. ": at your Keep At Least line")))
        end
    end
    App.status("Summon", # list > 0 and table.concat(list, " · ") or "off")
end

function FarmHub.buyStorage()
    local buyStorage = Brain.buyStorage
    if not buyStorage then
        return
    end
    Brain.buyStorage = nil
    App.saveNow()
    local prof = Core.prof()
    local units = Core.GS.CAPACITY_INCREASES and Core.GS.CAPACITY_INCREASES.units
    local unitCapacityIncrease = prof.inventory_capacity_increases and tonumber(prof.inventory_capacity_increases.unit_capacity_increase) or 0
    local unit = units and units [unitCapacityIncrease + 1]
    if not unit then
        return App.log(1, "SHOP", "unit storage: no more steps to buy")
    end
    local goldCost = tonumber(unit.gold_cost) or math.huge
    if goldCost > (tonumber(buyStorage.maxGold) or 0) then
        return App.log(1, "SHOP", string.format("unit storage: the next step costs %s gold, more than the %s you agreed: not bought", Utils.fmt(goldCost), Utils.fmt(buyStorage.maxGold)))
    end
    local cur, capacity = tonumber(Core.cur("gold")) or 0, prof.collection.capacity
    local now = Utils.now()
    local ok, res = App.request("storage", "try_purchase_unit_capacity")
    while Utils.now() - now < 5 and (tonumber(Core.cur("gold")) or 0) >= cur do
        task.wait(0.25)
    end
    local cur2 = cur - (tonumber(Core.cur("gold")) or 0)
    if cur2 > 0 then
        Spending.add("+" .. tostring(unit.increase) .. " unit storage", cur2, "gold", "your go-ahead: the collection was full, which refuses every pad")
        App.log(1, "SHOP", string.format("bought +%s unit storage for %s gold (storage was %s) · gold %s", tostring(unit.increase), Utils.fmt(cur2), tostring(capacity), Utils.fmt(Core.cur("gold"))))
        Modes.rec("dc").restUntil, Modes.rec("dc").restWhy = nil, nil
        Modes.lastScored, FarmHub.last.pick = nil, nil
    else
        task.wait(0.5)
        App.log(1, "SHOP", string.format("the game didn't sell unit storage (%s): not trying again", tostring(App.gameSaid(now) or (ok and res) or "no answer")))
    end
    App.saveSoon()
end

function FarmHub.buyOnce()
    local buyOnce = Brain.buyOnce
    if not buyOnce then
        return
    end
    local name = (Core.Items [buyOnce.item] or {
    }).name or buyOnce.item
    Brain.buyOnce = nil
    App.saveNow()
    if Adventure.have(buyOnce.item) >= 1 then
        return App.log(1, "SHOP", name .. ": you have one already, so nothing was bought")
    end
    local cur = tonumber(Core.cur(buyOnce.cur)) or 0
    if cur < (tonumber(buyOnce.max) or 0) then
        return App.log(1, "SHOP", string.format("%s: %s short of its %s %s, so nothing was bought", name, Utils.fmt(cur), Utils.fmt(buyOnce.max), tostring(buyOnce.cur)))
    end
    local now = Utils.now()
    local ok, res = App.request("eshop", "buy_item_generic", buyOnce.item, buyOnce.shop or "event", buyOnce.gui or "event_shop", "1")
    while Utils.now() - now < 5 and Adventure.have(buyOnce.item) < 1 do
        task.wait(0.25)
    end
    local cur2 = cur - (tonumber(Core.cur(buyOnce.cur)) or 0)
    if Adventure.have(buyOnce.item) >= 1 then
        Spending.add(name, cur2, tostring(buyOnce.cur), tostring(buyOnce.why or "your go-ahead"))
        pcall(Adventure.refresh)
        FarmHub.last.goals = nil
        if App.notify then
            App.notify("Shop", "Bought " .. name, "success")
        end
    else
        task.wait(0.5)
        App.log(1, "SHOP", string.format("the shop didn't sell %s (%s): not trying again", name, tostring(App.gameSaid(now) or (ok and res) or "no answer")))
    end
end

function FarmHub.pad(kind, mode)
    local function helper(inst)
        for _, child in ipairs(inst:GetChildren()) do
            local owner = child:FindFirstChild("Owner")
            local active = child:FindFirstChild("Active")
            if owner and owner.Value == nil and not (active and active.Value) then
                return child
            end
        end
    end
    if kind == "story" or kind == "infinite" then
        return helper(workspace._LOBBIES.Story)
    end
    if kind == "raid" then
        return helper(workspace._RAID.Raid)
    end
    if kind == "challenge" then
        return workspace._CHALLENGES.Challenges:GetChildren() [1]
    end
    if kind == "daily" then
        return workspace._CHALLENGES.DailyChallenge:GetChildren() [1]
    end
    if kind == "event" then
        local pad = Brain.live.event and Brain.live.event.pad
        return pad and workspace._EVENT_CHALLENGES.Lobbies:FindFirstChild(pad) or nil
    end
end

function FarmHub.launch(mode)
    if Modes.hasOwnTeam(mode) and not FarmHub.teamFor(mode) then return false end
    if mode.kind == "dungeon" then
        return Dungeon.launch(mode)
    end
    local ok, res = pcall(Strategy.relicsApply)
    if not ok then
        App.log(1, "ERROR", "relics: " .. tostring(res))
    end
    local live = Modes.liveChallenge(mode.key)
    if live then
        local rotation = Modes.rotation(mode)
        if rotation and rotation ~= tostring(live.uuid) then
            Modes.lastScored = nil
            return false
        end
        local test = Brain.testTeam
        local override = Brain.trial or (test and (test.left or 0) > 0 and test.key == mode.key)
            or (mode.kind == "daily" and Config.dailyLoop)
        if not override then
            if Config.sim and not FarmHub.simFresh(mode) then
                local ok, result = pcall(Simulator.plan, mode, false)
                if not ok then App.log(1, "ERROR", "sim with equipped team: " .. tostring(result)) end
            end
            local accepted, reason = Modes.chOk(mode, true)
            if accepted and mode.kind == "daily" and not FarmHub.matchOn(mode) and Modes.needsHelp(mode, true) then
                accepted, reason = false, "the equipped team needs matchmaking"
            end
            if not accepted then
                App.log(1, "MODE", mode.label .. ": " .. reason)
                local rec = Modes.rec(mode.key)
                rec.restUntil, rec.restWhy, rec.restRotation = os.time() + 120, "equipped team", rotation
                Modes.lastScored = nil
                App.backoff("launch", 20)
                return false
            end
        end
    end
    Brain.watch = nil
    for portalKey, portal in pairs(Modes.PORTALS) do
        if (mode.kind == "portal" and mode.level == portal.level) or (mode.portalMap and mode.level == portal.from) then
            Brain.watch = {
                key = mode.key,
                portal = portalKey,
                item = portal.item,
                have = Adventure.have(portal.item),
                held = # Modes.portalsHeld(portalKey),
                used = mode.kind == "portal",
                at = os.time()
            }
        end
    end
    if mode.kind == "portal" or mode.kind == "artifact" then
        return FarmHub.launchPortal(mode)
    end
    local pad = FarmHub.pad(mode.kind, mode)
    if not pad then
        App.log(1, "MODE", "no free pad for " .. mode.label)
        App.backoff("launch", 20)
        return false
    end
    Brain.pending = {
        key = mode.key,
        kind = mode.kind,
        level = mode.level,
        diff = mode.diff,
        label = mode.label,
        at = os.time(),
        value = mode.value,
        rotation = Modes.rotation(mode)
    }
    if Brain.nextMode == mode.key then
        Brain.nextMode = nil
    end
    App.log(1, "MODE", string.format("launching %s on %s — %s (≈%.0f gems/min)", mode.label, pad.Name, mode.why or "", mode.score or 0))
    App.saveNow()
    App.status("Mode", "starting " .. mode.label)
    if FarmHub.matchOn(mode) then
        FarmHub.matchmake(mode)
        local ok, res = pcall(Modes.needsHelp, mode, true)
        if App.alive and mode.kind == "daily" and ok and res then
            App.log(1, "MODE", "nobody joined the Daily Challenge, and the simulator says your team can't win it alone: not played alone, matchmaking again in 10 min")
            Brain.pending = nil
            local rec = Modes.rec(mode.key)
            rec.restUntil, rec.restWhy, rec.restRotation = os.time() + 600, "alone", Modes.rotation(mode)
            Modes.lastScored = nil
            App.backoff("launch", 5)
            return false
        end
    end
    local now = Utils.now()
    local ok, res = App.request("join", "request_join_lobby", pad.Name)
    if not (ok and res) then
        local sent = res ~= "waiting" and res ~= "slowing down" and not tostring(res):find("^no remote")
        if not ok and sent then
            -- the join was sent but got no answer / a connection error: it may still go through on the server (2.31)
            FarmHub.leaveIfSeated(pad.Name, tostring(res))
        end
        task.wait(0.5)
        local gameSaid = App.gameSaid(now)
        App.log(1, "MODE", "join refused on " .. pad.Name .. " (" .. tostring(gameSaid or res) .. ")" .. (gameSaid and (": " .. mode.label .. " rests for half an hour") or ""))
        Brain.pending = nil
        if gameSaid then
            local rec = Modes.rec(mode.key)
            rec.restUntil, rec.restWhy, rec.restRotation = os.time() + 1800, "refused", Modes.rotation(mode)
            Modes.lastScored = nil
        end
        App.backoff("launch", gameSaid and 5 or 15)
        return false
    end
    if mode.kind == "story" or mode.kind == "raid" or mode.kind == "infinite" then
        local ok, res = App.request("lock", "request_lock_level", pad.Name, mode.level, false, mode.diff)
        if not (ok and res) then
            App.log(1, "MODE", "lock refused for " .. mode.label .. " (" .. tostring(res) .. ")")
            App.request("leave", "request_leave_lobby", pad.Name)
            local rec = Modes.rec(mode.key)
            rec.restUntil, rec.restWhy = os.time() + 1800, "refused"
            Brain.pending = nil
            App.backoff("launch", 10)
            return false
        end
    end
    task.wait(0.5)
    App.request("start", "request_start_game", pad.Name)
    local now = Utils.now()
    while App.alive and Utils.now() - now < 45 do
        task.wait(1)
    end
    if App.alive then
        App.log(1, "MODE", "no teleport after 45s for " .. mode.label .. " — leaving the pad")
        App.request("leave", "request_leave_lobby", pad.Name)
        local rec = Modes.rec(mode.key)
        rec.restUntil, rec.restWhy, rec.restRotation = os.time() + 900, "no teleport", Modes.rotation(mode)
        Brain.pending = nil
        App.backoff("launch", 10)
    end
    return false
end

-- ===== A join without an answer must not leave us on the pad (2.31) =====
-- A join whose answer never came (timeout) may still have gone through: the game then shows AlreadyInLobby and the farm,
-- waiting for it to clear, started nothing for hours. Leave that pad now and check again a few times, because a late
-- answer can seat us after the first leave. Only the pad this farm tried itself, never one you joined by hand.
function FarmHub.ownsPad(padName)
    for _, name in ipairs({"_LOBBIES", "_CHALLENGES", "_EVENT_CHALLENGES"}) do
        local root = workspace:FindFirstChild(name)
        if root then
            for _, pad in ipairs(root:GetDescendants()) do
                if pad.Name == padName then
                    local owner = pad:FindFirstChild("Owner")
                    if owner and owner.Value == LocalPlayer then
                        return true
                    end
                end
            end
        end
    end
    return false
end

function FarmHub.leaveIfSeated(padName, why)
    App.log(1, "MODE", string.format("no answer to joining %s (%s): leaving it in case the game seated us anyway", padName, tostring(why)))
    App.request("leave", "request_leave_lobby", padName)
    local app = App
    task.spawn(function()
        for _, pause in ipairs({10, 25, 45}) do
            task.wait(pause)
            if not app.alive or _G.AA_SF ~= app or Brain.pending then
                return
            end
            local flag = LocalPlayer:FindFirstChild("AlreadyInLobby")
            if (flag and flag.Value) or FarmHub.ownsPad(padName) then
                App.log(1, "MODE", string.format("still seated on %s after the join without an answer: leaving again", padName))
                App.request("leave", "request_leave_lobby", padName)
            else
                return
            end
        end
    end)
end

function FarmHub.matchOn(mode)
    if Brain.trial or (Brain.testTeam and (Brain.testTeam.left or 0) > 0) then
        return false
    end
    if mode.kind == "daily" then
        return Config.dailyMatch == true
    end
    local mmLegend = (mode.kind == "raid" and Config.mmRaid) or (mode.kind == "infinite" and Config.mmInfinite) or (mode.kind == "story" and mode.legend and Config.mmLegend) or (mode.kind == "event" and Config.mmEvent)
    local level = mmLegend and Core.Levels [mode.level]
    return level ~= nil and level ~= false and type(level._MATCHMAKING) == "table"
end

function FarmHub.matchmake(mode)
    local serverToClient = ReplicatedStorage.endpoints.server_to_client
    local flag, flag2, list = false, false, {
    }
    if serverToClient:FindFirstChild("matchmaking_started") then
        table.insert(list, serverToClient.matchmaking_started.OnClientEvent:Connect(function()
            flag = true
        end))
    end
    if serverToClient:FindFirstChild("matchmaking_ended") then
        table.insert(list, serverToClient.matchmaking_ended.OnClientEvent:Connect(function()
            flag2 = true
        end))
    end
    for _, item in ipairs(list) do
        table.insert(App.conns, item)
    end
    local function helper()
        for _, item in ipairs(list) do
            item:Disconnect()
        end
    end
    local now = Utils.now()
    local str = mode.kind == "daily" and "__DAILY_CHALLENGE" or mode.level
    local label = tostring(mode.label or str)
    local ok, res = App.request("match", "request_matchmaking", str)
    while App.alive and Utils.now() - now < 5 and not flag do
        task.wait(0.25)
    end
    if not flag then
        App.log(1, "MODE", "matchmaking didn't start for " .. label .. " (" .. tostring(App.gameSaid(now) or (ok and res) or "no answer") .. "): alone")
        helper()
        return false
    end
    local value = math.max(30, tonumber(Config.dailyMatchWait) or 120)
    App.log(1, "MODE", string.format("matchmaking for %s: up to %d s for other players, then alone", label, value))
    App.status("Mode", "matchmaking: " .. label)
    local now2
    while App.alive and Utils.now() - now < value do
        if flag2 and not now2 then
            now2 = Utils.now()
        end
        if now2 and Utils.now() - now2 > 30 then
            break
        end
        task.wait(1)
    end
    if not App.alive then
        return true
    end
    helper()
    App.request("match_leave", "leave_matchmaking")
    App.log(1, "MODE", now2 and ("matchmaking ended with no match: " .. label .. " alone") or string.format("nobody joined in %d s: %s alone", value, label))
    task.wait(2)
    return false
end

function FarmHub.launchPortal(mode)
    if Modes.hasOwnTeam(mode) and not FarmHub.teamFor(mode) then return false end
    Brain.pending = {
        key = mode.key,
        kind = mode.kind,
        level = mode.level,
        diff = mode.diff,
        label = mode.label,
        at = os.time(),
        value = mode.value
    }
    App.log(1, "MODE", string.format("launching %s %s — %s (≈%.0f gems/min)", mode.label, mode.kind == "artifact" and "alone" or ("with a " .. ((Core.Items [(Brain.watch or {
    }).portal or ""] or {
    }).name or "portal")), mode.why or "", mode.score or 0))
    App.saveNow()
    App.status("Mode", "opening " .. mode.label)
    local now = Utils.now()
    local value
    if mode.kind == "artifact" then
        _, value = App.request("portal", "open_portal_level_new", mode.level, {
            difficulty = "Hard"
        })
    else
        _, value = App.request("portal", "use_portal", mode.portal)
    end
    local svc = Core.svc("LobbyServiceClient")
    local function helper()
        local currentLobby = svc and svc.current_lobby
        if currentLobby then
            return currentLobby
        end
        local lobbies = workspace:FindFirstChild("_PORTALS") and workspace._PORTALS:FindFirstChild("Lobbies")
        for _, child in ipairs(lobbies and lobbies:GetChildren() or {
        }) do
            local owner = child:FindFirstChild("Owner")
            if owner and owner.Value == LocalPlayer then
                return child.Name
            end
        end
    end
    local value2
    while App.alive and Utils.now() - now < 28 and not value2 do
        value2 = helper()
        if not value2 then
            if App.gameSaid(now) then
                break
            end
            task.wait(0.5)
        end
    end
    if value2 and Utils.now() - now > 10 then
        App.log(1, "MODE", string.format("the portal opened late (after %.0f s): it plays", Utils.now() - now))
    end
    if not value2 then
        local gameSaid = App.gameSaid(now)
        local value2 = gameSaid and gameSaid:lower():find("once every", 1, true)
        FarmHub.badPortal = FarmHub.badPortal or {
        }
        if mode.portal and not value2 then
            FarmHub.badPortal [mode.portal] = os.time() + 3600
        end
        local flag = mode.kind == "artifact" and not value2
        if flag then
            Modes.rec(mode.key).restUntil, Modes.rec(mode.key).restWhy = os.time() + 1800, "refused"
            Modes.lastScored = nil
        end
        App.log(1, "MODE", string.format("the %s didn't open (%s): trying again %s", mode.kind == "artifact" and "Artifact Stage" or "portal", tostring(gameSaid or value or "no answer"), value2 and "once the game's 30 s are up" or (flag and "in half an hour" or "with another portal")))
        task.wait(2)
        local value = helper()
        if value then
            App.request("leave", "request_leave_lobby", value)
        end
        Brain.pending, Brain.watch = nil, nil
        App.backoff("launch", math.max(5, 32 - (Utils.now() - now)))
        return false
    end
    task.wait(0.5)
    pcall(function()
        local moreLobbyParam = svc and svc.more_lobby_params and svc.more_lobby_params [value2]
        local levelData = moreLobbyParam and moreLobbyParam._level_data
        if type(levelData) ~= "table" then
            return
        end
        local level = Core.Levels [mode.level] or {
        }
        local list = {
        }
        for key, value in pairs(levelData) do
            local value2 = level [key]
            if type(value) ~= "table" and type(value) ~= "function" and value ~= value2 then
                table.insert(list, tostring(key) .. "=" .. tostring(value))
            elseif type(value) == "table" and type(value2) ~= "table" then
                local ok, res = pcall(HttpService.JSONEncode, HttpService, value)
                table.insert(list, tostring(key) .. "=" .. (ok and res:sub(1, 120) or "{…}"))
            end
        end
        table.sort(list)
        local joined = # list > 0 and table.concat(list, " · ") or "none beyond the plain level"
        Brain.portalMods = joined
        App.saveNow()
        App.log(1, "PORTAL", string.format("%s opened: %s", mode.label, joined:sub(1, 400)))
        local value = joined:find("weak") or joined:find("challenge") or joined:find("difficulty") or joined:find("resist") or joined:find("health")
        if value and Config.autoTeam and not Modes.hasOwnTeam(mode) then
            mode.ldOverride = levelData
            local ok, res = pcall(FarmHub.teamFor, mode, FarmHub.QUICK_SEARCH)
            if not ok then
                App.log(1, "ERROR", "portal team: " .. tostring(res))
            end
            mode.ldOverride = nil
        end
    end)
    local now = Utils.now()
    local list = {
    }
    for i = 1, 3 do
        local ok, res = App.request("start", "request_start_game", value2)
        table.insert(list, tostring(ok and res))
        local now = Utils.now()
        while App.alive and Utils.now() - now < 12 do
            task.wait(1)
        end
        if not App.alive then
            return false
        end
        value2 = (svc and svc.current_lobby) or value2
    end
    if App.alive then
        local gameSaid = App.gameSaid(now)
        App.log(1, "MODE", string.format("no teleport after 3 Starts (%s%s) for %s — leaving the portal lobby, %s", table.concat(list, ", "), gameSaid and (", the game said: " .. gameSaid) or "", mode.label, mode.kind == "artifact" and "trying again in 15 min" or "next try with another portal"))
        App.request("leave", "request_leave_lobby", value2)
        FarmHub.badPortal = FarmHub.badPortal or {
        }
        if mode.portal then
            FarmHub.badPortal [mode.portal] = os.time() + 3600
        end
        if mode.kind == "artifact" then
            Modes.rec(mode.key).restUntil, Modes.rec(mode.key).restWhy = os.time() + 900, "no teleport"
            Modes.lastScored = nil
        end
        Brain.pending, Brain.watch = nil, nil
        App.backoff("launch", 10)
    end
    return false
end

function FarmHub.portalLine(arg1)
    local text = Core.FOLDER .. "/portal_runs.txt"
    local ok, res = pcall(readfile, text)
    pcall(writefile, text, (ok and res or "") .. arg1 .. "\n")
end

function FarmHub.watchDone()
    local watch = Brain.watch
    if not watch then
        return
    end
    Brain.watch = nil
    if os.time() - (tonumber(watch.at) or 0) > 3 * 3600 then
        return
    end
    local have = Adventure.have(watch.item) - (tonumber(watch.have) or 0)
    local portalsHeldCount = # Modes.portalsHeld(watch.portal)
    local function helper(arg1, arg2)
        local value = Brain.portalPay [arg1] or {
            n = 0
        }
        value.n = (tonumber(value.n) or 0) + 1
        value.per = value.per and (value.per + (arg2 - value.per) * math.max(0.25, 1 / value.n)) or arg2
        Brain.portalPay [arg1] = value
    end
    local name, name2 = (Core.Items [watch.item] or {
    }).name or watch.item, (Core.Items [watch.portal] or {
    }).name or watch.portal
    if watch.used then
        FarmHub.portalLine(string.format("%s · paid +%d %s (now %d) · %d portals left", os.date("%m-%d %H:%M"), have, name, Adventure.have(watch.item), portalsHeldCount))
        if watch.won == false then
            App.log(1, "PORTAL", string.format("%s: lost, so +%d %s (now %d) · %d portals left · not counted as what a portal pays", Modes.levelName(Modes.PORTALS [watch.portal].level), have, name, Adventure.have(watch.item), portalsHeldCount))
        else
            helper(watch.portal, math.max(0, have))
            App.log(1, "PORTAL", string.format("%s: +%d %s (now %d) · %d portals left", Modes.levelName(Modes.PORTALS [watch.portal].level), have, name, Adventure.have(watch.item), portalsHeldCount))
        end
    else
        local portalsHeldCount2 = portalsHeldCount - (tonumber(watch.held) or 0)
        helper("drop:" .. watch.portal, math.max(0, portalsHeldCount2))
        App.log(1, "PORTAL", string.format("%s dropped %d %s (now %d)%s", Modes.levelName(Modes.PORTALS [watch.portal].from), portalsHeldCount2, name2, portalsHeldCount, have > 0 and string.format(" · +%d %s", have, name) or ""))
    end
    Modes.lastScored = nil
    App.saveSoon()
end

function FarmHub.simFresh(mode)
    local fixed = Modes.hasOwnTeam(mode)
    local ownProfile = fixed and Modes.ownProfile(mode)
    if fixed and not ownProfile then return false end
    local profile = ownProfile or Modes.equippedProfile()
    local simRe = Brain.simRes [mode.key]
    if not simRe or simRe.rotation ~= Modes.rotation(mode) then
        return false
    end
    local num = simRe.none and 120 or 6 * 3600
    return os.time() - (tonumber(simRe.at) or 0) < num and simRe.profile == profile
end

function FarmHub.relicClash(arg1)
    local session = Core.session()
    local list = {
    }
    for _, value in ipairs(Brain.savedTeam or {
    }) do
        list [value] = true
    end
    local list2 = {
    }
    for _, value in ipairs(arg1) do
        local unitObj = session.collection:get_unit_by_uuid(value)
        local itemByUuid = unitObj and unitObj._equipped_relic and session.inventory:get_item_by_uuid(unitObj._equipped_relic)
        if itemByUuid and itemByUuid.item_id and (Core.Items [itemByUuid.item_id] or {
        }).unique_equip then
            table.insert(list2, {
                uuid = value,
                u = unitObj,
                kind = itemByUuid.item_id,
                relic = unitObj._equipped_relic,
                k = (list [value] and 1e12 or 0) + Strategy.score(unitObj)
            })
        end
    end
    table.sort(list2, function(item, item2)
        if item.k ~= item2.k then
            return item.k > item2.k
        end
        return item.uuid < item2.uuid
    end)
    local list = {
    }
    for _, item in ipairs(list2) do
        if list [item.kind] then
            local name = (Core.Items [item.kind] or {
            }).name or item.kind
            local _, res = App.request("relicOff", "request_unequip_relic", item.relic)
            local now = Utils.now()
            while Utils.now() - now < 3 and item.u._equipped_relic == item.relic do
                task.wait(0.25)
            end
            if item.u._equipped_relic ~= item.relic then
                Brain.relicOff [item.uuid] = item.relic
                App.log(1, "TEAM", string.format("%s took off its %s for this team: %s has one, and a team can hold one of each", Units.name(item.u.unit_id), name, Units.name(list [item.kind])))
            else
                App.log(1, "TEAM", string.format("%s's %s wouldn't come off (%s): the game won't take both on a team", Units.name(item.u.unit_id), name, tostring(res)))
            end
        else
            list [item.kind] = item.u.unit_id
        end
    end
end

function FarmHub.relicBack()
    if Config.team and Config.teamRelics then
        table.clear(Brain.relicOff)
        return
    end
    local session = Core.session()
    for key, value in pairs(Brain.relicOff) do
        local unitObj = session.collection:get_unit_by_uuid(key)
        local itemByUuid = session.inventory:get_item_by_uuid(value)
        local uniqueRelicData = itemByUuid and itemByUuid._unique_item_data and itemByUuid._unique_item_data._unique_relic_data
        if unitObj and uniqueRelicData and not unitObj._equipped_relic and not uniqueRelicData._equipped_unit_uuid and not Strategy.slotOf(key) then
            local item
            for _, value in ipairs(Units.equipped()) do
                local itemByUuid2 = value.u._equipped_relic and session.inventory:get_item_by_uuid(value.u._equipped_relic)
                if itemByUuid2 and itemByUuid2.item_id == itemByUuid.item_id then
                    item = value
                end
            end
            if item then
                Brain.str.reequip = {
                    uuid = item.uuid,
                    slot = item.slot
                }
                App.saveNow()
                App.request("uneq", "unequip_unit", item.uuid)
                local now = Utils.now()
                while Utils.now() - now < 4 and Strategy.slotOf(item.uuid) do
                    task.wait(0.25)
                end
            end
            App.request("relicOff", "use_unique_item", value, {
                unit_uuid = key
            })
            local now = Utils.now()
            while Utils.now() - now < 3 and unitObj._equipped_relic ~= value do
                task.wait(0.25)
            end
            if item then
                Strategy.reequip()
            end
            App.log(1, "TEAM", string.format("%s has its %s back%s", Units.name(unitObj.unit_id), (Core.Items [itemByUuid.item_id] or {
            }).name or tostring(itemByUuid.item_id), unitObj._equipped_relic == value and "" or ": the game didn't take it"))
        end
        Brain.relicOff [key] = nil
    end
end

function FarmHub.equipTeam(uuids, label)
    local session = Core.session()
    if not session or type(uuids) ~= "table" or #uuids == 0 then
        return false
    end
    local requested = {}
    for _, uuid in ipairs(uuids) do
        if requested[uuid] or not session.collection:get_unit_by_uuid(uuid) then
            App.log(1, "TEAM", "the requested team contains a duplicate or missing unit: " .. tostring(uuid))
            return false
        end
        requested[uuid] = true
    end
    local list = {
    }
    for _, item in ipairs(Units.equipped()) do
        list [item.uuid] = true
    end
    local teamBefore = TeamLog.names(Units.equipped())
    if not Brain.savedTeam then
        local list = {
        }
        for _, item in ipairs(Units.equipped()) do
            table.insert(list, item.uuid)
        end
        Brain.savedTeam = list
    end
    local ok, res = pcall(FarmHub.relicClash, uuids)
    if not ok then
        App.log(1, "ERROR", "relic clash: " .. tostring(res))
    end
    local requested2 = requested
    local flag, list2 = false, {
    }
    for i = 1, 4 do
        for itemKey in pairs(list) do
            if not requested2 [itemKey] then
                local _, res = App.request("uneq", "unequip_unit", itemKey)
                table.insert(list2, string.format("out %s: %s", Units.name((Core.session().collection:get_unit_by_uuid(itemKey) or {
                }).unit_id or "?"), tostring(res)))
                task.wait(0.8)
            end
        end
        for _, uuid in ipairs(uuids) do
            if not list [uuid] then
                local value
                if i > 2 then
                    local list = {
                    }
                    for _, value in ipairs(Units.equipped()) do
                        list [value.slot] = true
                    end
                    for i = 1, 6 do
                        if not list [i] then
                            value = i
                            break
                        end
                    end
                end
                local ok, value2
                if # Units.equipped() >= 6 then
                    -- 2.33: all 6 slots are still taken (the unit going out didn't leave — its unequip got no answer):
                    -- the game would refuse; the next round asks for the unequip again instead
                    ok, value2 = false, "skipped: all 6 slots still taken"
                elseif value then
                    ok, value2 = App.request("eq", "equip_unit", uuid, value)
                else
                    ok, value2 = App.request("eq", "equip_unit", uuid)
                end
                table.insert(list2, string.format("in %s%s: %s %s", Units.name((Core.session().collection:get_unit_by_uuid(uuid) or {
                }).unit_id or "?"), value and (" slot " .. value) or "", tostring(ok), tostring(value2)))
                task.wait(0.8)
            end
        end
        local now = Utils.now()
        while Utils.now() - now < 3 and not Training.same(Training.team(), uuids) do
            task.wait(0.25)
        end
        flag = Training.same(Training.team(), uuids)
        if flag then
            break
        end
        list = {
        }
        for _, item in ipairs(Units.equipped()) do
            list [item.uuid] = true
        end
    end
    Modes._sigAt = nil
    pcall(TeamLog.write, teamBefore, TeamLog.names(Units.equipped()), label, flag)
    if flag then
        App.log(1, "TEAM", "equipped " .. # uuids .. " units — " .. tostring(label))
    else
        local list = {
        }
        for _, value in ipairs(Units.equipped()) do
            table.insert(list, Units.name(value.id))
        end
        App.log(1, "TEAM", "the team swap didn't take (" .. tostring(label) .. "): the game has " .. table.concat(list, ", ") .. " · calls: " .. table.concat(list2, " · "))
        if not FarmHub.refilling and # Units.equipped() < 6 then
            FarmHub.refilling = true
            local list, list2 = {
            }, {
            }
            for _, item in ipairs(Units.equipped()) do
                list2 [item.uuid] = true
            end
            for _, value in ipairs(Brain.savedTeam or {
            }) do
                if not list2 [value] and Core.session().collection:get_unit_by_uuid(value) then
                    table.insert(list, value)
                end
            end
            local count = 0
            for _, item in ipairs(list) do
                if # Units.equipped() >= 6 then
                    break
                end
                App.request("eq", "equip_unit", item)
                task.wait(0.8)
                local now = Utils.now()
                while Utils.now() - now < 3 and # Units.equipped() < math.min(6, count + 1 + (6 - # list)) do
                    task.wait(0.25)
                end
                for _, item2 in ipairs(Units.equipped()) do
                    if item2.uuid == item then
                        count = count + 1
                    end
                end
            end
            local list = {
            }
            for _, value in ipairs(Units.equipped()) do
                table.insert(list, Units.name(value.id))
            end
            App.log(1, "TEAM", string.format("filled the empty slots with %d of your own units back: the team is %s", count, table.concat(list, ", ")))
            Modes._sigAt = nil
            FarmHub.refilling = nil
        end
    end
    App.saveSoon()
    return flag
end

function FarmHub.ownSwap()
    local ownSwap = Brain.ownSwap
    if not ownSwap then
        return
    end
    local ok = App.request("hatch", "get_hatch_setup_data")
    if not ok then
        return
    end
    if Brain.train.on then
        Training.home()
    end
    local session = Core.session()
    local savedTeam = table.clone(Brain.savedTeam or Training.team())
    local value, flag
    for i, value2 in ipairs(savedTeam) do
        local unitObj = session.collection:get_unit_by_uuid(value2)
        if unitObj and unitObj.unit_id == ownSwap.out then
            value = i
        end
        if unitObj and unitObj.unit_id == ownSwap.into then
            flag = true
        end
    end
    local value2, xp
    for ownedUnitKey, ownedUnit in pairs(session.profile_data.collection.owned_units) do
        if ownedUnit.unit_id == ownSwap.into and (not value2 or (tonumber(ownedUnit.xp) or 0) > xp) then
            value2, xp = ownedUnitKey, tonumber(ownedUnit.xp) or 0
        end
    end
    if flag or not value or not value2 then
        Brain.ownSwap = nil
        App.log(1, "TEAM", string.format("your own team: %s for %s wasn't needed (%s), nothing changed", Units.name(ownSwap.into), Units.name(ownSwap.out), flag and "it's already on" or not value and "that unit isn't on your team" or "you don't have that unit"))
        return App.saveSoon()
    end
    savedTeam [value] = value2
    local savedTeam2 = Brain.savedTeam
    Brain.savedTeam = nil
    if FarmHub.equipTeam(savedTeam, string.format("your own team: %s in for %s", Units.name(ownSwap.into), Units.name(ownSwap.out))) then
        Brain.savedTeam, Brain.ownSwap = nil, nil
        Modes.lastScored = nil
        if App.notify then
            App.notify("Team", string.format("%s is on your team, in for %s", Units.name(ownSwap.into), Units.name(ownSwap.out)), "success")
        end
    else
        Brain.savedTeam = savedTeam2 or Brain.savedTeam
    end
    App.saveSoon()
end

function FarmHub.restoreTeam()
    if not Brain.savedTeam then
        return false
    end
    local session = Core.session()
    if not session then return false end
    local list, seen = {}, {}
    for _, uuid in ipairs(Brain.savedTeam) do
        if not seen[uuid] and session.collection:get_unit_by_uuid(uuid) then
            table.insert(list, uuid)
            seen[uuid] = true
        end
    end
    Brain.savedTeam = nil
    if #list == 0 then
        App.log(1, "TEAM", "none of the saved team's units are still owned; keeping the equipped team")
        App.saveSoon()
        return #Units.equipped() > 0
    end
    Brain.savedTeam = not FarmHub.equipTeam(list, "your own team back") and list or nil
    if not Brain.savedTeam then
        local ok, res = pcall(FarmHub.relicBack)
        if not ok then
            App.log(1, "ERROR", "relic back: " .. tostring(res))
        end
    end
    App.saveSoon()
    return Brain.savedTeam == nil
end
FarmHub.QUICK_SEARCH = 7

function FarmHub.teamFor(train, quickSearch)
    if Modes.hasOwnTeam(train) then
        local uuids, why = Modes.ownTeam(train)
        if not uuids then return false, why end
        if Brain.train.on then Training.home() end
        if not Training.same(Training.team(), uuids) then
            return FarmHub.equipTeam(uuids, "your " .. tostring(Modes.teamKey(train)) .. " team")
        end
        return true
    end
    if train.key == "dg" then
        return not Brain.savedTeam or FarmHub.restoreTeam()
    end
    local session = Core.session()
    if not session then return false end
    local testTeam = Brain.testTeam
    if testTeam and (testTeam.left or 0) > 0 and testTeam.key == train.key and type(testTeam.uuids) == "table" then
        local count = 0
        for _, uuid in ipairs(testTeam.uuids) do
            if session.collection:get_unit_by_uuid(uuid) then
                count = count + 1
            end
        end
        if count > 0 and count == # testTeam.uuids then
            if Brain.train.on then
                Training.home()
            end
            if not Training.same(Training.team(), testTeam.uuids) then
                return FarmHub.equipTeam(testTeam.uuids, "team test: " .. tostring(testTeam.label))
            end
            return true
        end
    end
    if Config.dailyLoop and train.kind == "daily" and type(Config.dailyTeam) == "table" and # Config.dailyTeam > 0 then
        local list, list2 = {
        }, {
        }
        for _, value in ipairs(Brain.savedTeam or Training.team()) do
            local unitObj = session.collection:get_unit_by_uuid(value)
            if unitObj then
                list2 [unitObj.unit_id] = value
            end
        end
        for _, unitId in ipairs(Config.dailyTeam) do
            local item, value = list2 [unitId], nil
            if not item then
                local isFarm, rows = Units.isFarm(unitId), Units.rows(unitId)
                for _, ownedUnit in pairs(session.profile_data.collection.owned_units) do
                    if ownedUnit.unit_id == unitId then
                        local unitObj = session.collection:get_unit_by_uuid(ownedUnit.uuid) or ownedUnit
                        local ok, value2
                        if isFarm then
                            ok, value2 = pcall(Units.farm, unitObj, rows and rows.max or 0)
                        else
                            ok, value2 = pcall(Units.score, unitObj)
                        end
                        value2 = ok and value2 or 0
                        if not value or value2 > value then
                            item, value = ownedUnit.uuid, value2
                        end
                    end
                end
            end
            if item then
                table.insert(list, item)
            end
        end
        if # list == # Config.dailyTeam then
            if Brain.train.on then
                Training.home()
            end
            if not Training.same(Training.team(), list) then
                return FarmHub.equipTeam(list, "your team for the Daily Challenge")
            end
            return true
        end
        App.log(1, "TEAM", "your Daily Challenge team has a unit you no longer own: the search picks instead")
    end
    local savedTeam = Brain.savedTeam or (Brain.train.on and Brain.train.on.base) or Training.team()
    local list = {
    }
    for _, value in ipairs(savedTeam) do
        local unitObj = session.collection:get_unit_by_uuid(value)
        if unitObj then
            table.insert(list, unitObj)
        end
    end
    if Brain.savedTeam and (#list == 0 or #list ~= #savedTeam) then
        return FarmHub.restoreTeam()
    end
    if # list == 0 then
        return false
    end
    local profileSig = Simulator.profileSig(list)
    if Config.sim and Config.simTeams and not Modes.teamPlan(train, profileSig) then
        App.status("Mode", "looking for the best team for " .. tostring(train.label))
        Simulator.memoOn()
        local ok, res = pcall(Simulator.plan, train, true, quickSearch or 20, list)
        Simulator.memo = nil
        if not ok then
            App.log(1, "ERROR", "team search: " .. tostring(res))
        end
    end
    local teamPlan = Modes.teamPlan(train, profileSig)
    local uuids = teamPlan and teamPlan.better and teamPlan.uuids or savedTeam
    local on = Brain.train.on
    if on and not Training.same(on.base or {
    }, uuids) then
        Training.home()
        on = nil
    end
    if not on and not Training.same(Training.team(), uuids) then
        if uuids == savedTeam and Brain.savedTeam then
            return FarmHub.restoreTeam()
        end
        return FarmHub.equipTeam(uuids, (teamPlan and teamPlan.why) and (teamPlan.why .. ": " .. tostring(train.label)) or ("the simulator's best team for " .. tostring(train.label)))
    end
    return true
end

function FarmHub.recalculatePlan(notify)
    local function report(message, tone)
        App.log(1, "SIM", message)
        notify("Simulator", message, tone)
    end
    if App.where ~= "lobby" then
        return report("Team planning is available in the lobby.", "warning")
    end
    if not Config.sim then
        return report("Enable Use The Simulator.", "warning")
    end
    if FarmHub.manualPlanning then
        return report("Team planning is already running.", "warning")
    end
    FarmHub.manualPlanning = true
    FarmHub.manualPlan = nil
    local ok, message, tone = pcall(function()
        local session = Core.session()
        if not (session and session.profile_data and session.collection) then
            return "Game profile is unavailable. Wait until your units load in the lobby and retry.", "warning"
        end
        local mode = Modes.pick()
        if not mode then
            return "No available mode to plan. Check Farm mode settings.", "warning"
        end
        if mode.kind == "dungeon" then
            return "dungeon: own team not supported yet; room planner is separate", "warning"
        end
        if Modes.hasOwnTeam(mode) then
            local team, why = Modes.ownTeam(mode)
            if not team then return why, "warning" end
            if not FarmHub.teamFor(mode) then return "Saved team could not be equipped; run held.", "warning" end
            local result = Simulator.plan(mode, false)
            if not result then return "No forecast for the saved team.", "warning" end
            return mode.label .. ": saved team · " .. result.margin, "success"
        end
        if not Config.simTeams then return "Enable Plan Best Teams.", "warning" end
        if #Units.equipped() == 0 then
            return "Equip at least one unit and recalculate.", "warning"
        end
        report("Planning team for " .. mode.label .. "…", "default")
        Simulator.memoOn()
        local planned, result, searchError = pcall(Simulator.plan, mode, true, nil, nil, true)
        Simulator.memo = nil
        if not planned then
            Simulator.finishProgress()
            error(result, 0)
        end
        if searchError then
            return "Team search failed for " .. mode.label .. ": " .. searchError, "error"
        end
        if not result then
            return "No level data for " .. mode.label .. ".", "warning"
        end
        local team = Brain.simTeam[mode.key]
        FarmHub.manualPlan = { mode = mode, team = team, current = Modes.equippedProfile() }
        if team and team.better then
            return mode.label .. ": " .. (team.why or "better team found") .. ". Use Equip planned team.", "success"
        end
        return mode.label .. ": " .. (result.teamReason or "no stronger team found"), "default"
    end)
    FarmHub.manualPlanning = nil
    if not ok then
        return report("Team planning failed: " .. tostring(message), "error")
    end
    report(message, tone)
end

-- ===== Farming sessions: Quick Start and Routines =====
-- A session is one Quick Start or one Routine: an ordered list of tasks (mode, map, difficulty, runs,
-- optional settings). It drives the usual Auto Farm: while a task runs, its mode, map and settings are laid
-- over Config for this session only (Farming.base keeps your own values, and settings.json always gets
-- those). A run counts once, when the game confirms it was won (Infinite: when it ends, as it always
-- ends with the base falling). Brain.farmRun keeps the session across teleports and restarts.
Farming.MODES = {
    {
        id = "story",
        name = "Story",
        only = "onlyStory",
        enable = {
            "firstClears",
            "farm"
        },
        pick = "pickStory",
        maps = "story"
    },
    {
        id = "legend",
        name = "Legend Stage",
        only = "onlyLegend",
        enable = {
        },
        pick = "pickLegend",
        maps = "legend",
        mm = "mmLegend"
    },
    {
        id = "raid",
        name = "Raid",
        only = "onlyRaids",
        enable = {
            "raids"
        },
        pick = "pickRaid",
        maps = "raid",
        mm = "mmRaid"
    },
    {
        id = "infinite",
        name = "Infinite",
        only = "onlyInfinite",
        enable = {
            "infinite"
        },
        pick = "pickInfinite",
        maps = "infinite",
        mm = "mmInfinite",
        endEarly = true
    },
    {
        id = "portal",
        name = "Portal",
        only = "onlyPortals",
        enable = {
            "portals"
        },
        pick = "pickPortal",
        maps = "portal"
    },
    {
        id = "challenge",
        name = "Challenges",
        only = "onlyChallenges",
        enable = {
            "dailyChallenge",
            "challenge"
        },
        mm = "dailyMatch"
    },
    {
        id = "artifact",
        name = "Artifact Stage",
        only = "onlyArtifact",
        enable = {
            "artifact"
        }
    },
    {
        id = "dungeon",
        name = "Dungeon",
        only = "onlyDungeons",
        enable = {
            "dungeon",
            "dungeonStart"
        }
    },
    {
        id = "event",
        name = "Event",
        only = "onlyCoins",
        enable = {
            "event"
        },
        mm = "mmEvent",
        needsEvent = true
    }
}
Farming.SAME = {
    autoBuff = "same",
    buffKind = "same",
    matchmake = "same",
    endEarly = "same"
}
-- A start that fails this many times in a row, or no playable mode for this long, pauses the session.
Farming.MAX_FAILS = 3
Farming.NO_MODE_WAIT = 120
Farming.base = {
}
Farming.overlaid = false

function Farming.mode(id)
    for _, mode in ipairs(Farming.MODES) do
        if mode.id == id then
            return mode
        end
    end
    return nil
end

function Farming.copy(value)
    if type(value) ~= "table" then
        return value
    end
    local copy = {
    }
    for key, item in pairs(value) do
        copy [key] = Farming.copy(item)
    end
    return copy
end

function Farming.newTask(mode)
    return {
        mode = mode or "story",
        map = "",
        diff = "",
        runs = 10,
        adv = Farming.copy(Farming.SAME)
    }
end

-- Maps a mode offers. Story maps are acts; their difficulty is a separate field (Farming.diffOptions).
function Farming.mapOptions(modeId)
    local mode = Farming.mode(modeId)
    if not mode then
        return {
        }
    end
    if not mode.maps then
        return {
            {
                text = mode.id == "event" and "The current event" or "Set by the game",
                value = ""
            }
        }
    end
    local ok, rows = pcall(GUI.modeOptions, mode.maps)
    rows = ok and type(rows) == "table" and rows or {
    }
    local list, seen = {
    }, {
    }
    for _, row in ipairs(rows) do
        local text, value = tostring(row.text or ""), row.value
        if text:find("not open right now", 1, true) then
            continue
        end
        if mode.id == "story" then
            local level = type(value) == "string" and value:match("^st:(.+):%a+$")
            if level then
                if not seen [level] then
                    seen [level] = true
                    table.insert(list, {
                        text = (text:gsub("%s*%(%a+%)$", "")),
                        value = "st:" .. level
                    })
                end
            else
                table.insert(list, {
                    text = text,
                    value = value
                })
            end
        else
            table.insert(list, {
                text = text,
                value = value
            })
        end
    end
    return list
end

-- Difficulties open for a story act; nothing to pick for other modes.
function Farming.diffOptions(task)
    if task.mode ~= "story" then
        return {
        }
    end
    local level = type(task.map) == "string" and task.map:match("^st:(.+)$")
    if not level then
        return {
        }
    end
    local ok, rows = pcall(GUI.modeOptions, "story")
    local list = {
    }
    for _, row in ipairs(ok and type(rows) == "table" and rows or {
    }) do
        local id, diff = tostring(row.value):match("^st:(.+):(%a+)$")
        if id == level then
            table.insert(list, {
                text = diff,
                value = diff
            })
        end
    end
    return list
end

function Farming.mapName(task)
    for _, row in ipairs(Farming.mapOptions(task.mode)) do
        if row.value == task.map then
            local text = tostring(row.text):gsub("^%S+%s+Smart:.*$", "Smart"):gsub("^%S+%s+Progress:.*$", "Progress")
            return text
        end
    end
    return task.map ~= "" and tostring(task.map) or "Smart"
end

-- "Story → Planet Namak (Hard) ×50"
function Farming.label(task, noRuns)
    if type(task) ~= "table" then
        return "?"
    end
    local mode = Farming.mode(task.mode)
    local text = (mode and mode.name or tostring(task.mode)) .. " → " .. Farming.mapName(task)
    if task.mode == "story" and type(task.map) == "string" and task.map:match("^st:") and task.diff ~= "" then
        text = text .. " (" .. tostring(task.diff) .. ")"
    end
    if not noRuns then
        text = text .. " ×" .. tostring(task.runs)
    end
    return text
end

-- The pick value Auto Farm reads for this task's map.
function Farming.pickValue(task)
    local map = type(task.map) == "string" and task.map or ""
    if task.mode == "story" and map:match("^st:") then
        return map .. ":" .. tostring(task.diff)
    end
    if task.mode == "portal" and map == "" then
        return "smart"
    end
    return map
end

-- Nil when the task can start; otherwise the field that's missing or wrong.
function Farming.check(task)
    if type(task) ~= "table" then
        return "Pick a Mode"
    end
    local mode = Farming.mode(task.mode)
    if not mode then
        return "Pick a Mode"
    end
    if mode.needsEvent and not Modes.eventNow() then
        return "Mode: no event is running right now"
    end
    if mode.maps then
        if task.map == nil then
            return "Pick a Map"
        end
        local found = false
        for _, row in ipairs(Farming.mapOptions(task.mode)) do
            if row.value == task.map then
                found = true
                break
            end
        end
        if not found then
            return "Map: " .. tostring(task.map) .. " isn't open for you"
        end
    end
    if task.mode == "story" and type(task.map) == "string" and task.map:match("^st:") then
        local found = false
        for _, row in ipairs(Farming.diffOptions(task)) do
            if row.value == task.diff then
                found = true
            end
        end
        if not found then
            return "Pick a Difficulty for " .. Farming.mapName(task)
        end
    end
    local runs = tonumber(task.runs)
    if not runs or runs < 1 or runs ~= math.floor(runs) then
        return "Set Runs to a whole number, 1 or more"
    end
    return nil
end

-- What a task lays over Config: only its mode is on, with its map and the optional settings it changes.
function Farming.overlayFor(task)
    local values = {
        dailyLoop = false,
        pickPortal = "smart"
    }
    for _, mode in ipairs(Farming.MODES) do
        values [mode.only] = false
        for _, key in ipairs(mode.enable) do
            values [key] = false
        end
    end
    local mode = Farming.mode(task.mode)
    values [mode.only] = true
    for _, key in ipairs(mode.enable) do
        values [key] = true
    end
    if mode.pick then
        values [mode.pick] = Farming.pickValue(task)
    end
    local adv = type(task.adv) == "table" and task.adv or {
    }
    if adv.autoBuff == "on" or adv.autoBuff == "off" then
        values.autoBuff = adv.autoBuff == "on"
    end
    if adv.buffKind == "auto" or adv.buffKind == "physical" or adv.buffKind == "magic" then
        values.autoBuffKind = adv.buffKind
    end
    if mode.mm and (adv.matchmake == "on" or adv.matchmake == "off") then
        values [mode.mm] = adv.matchmake == "on"
    end
    if mode.endEarly and (adv.endEarly == "on" or adv.endEarly == "off") then
        values.infiniteStop = adv.endEarly == "on"
    end
    return values
end

function Farming.clearOverlay()
    if Farming.overlaid then
        for key, value in pairs(Farming.base) do
            Config [key] = value
        end
    end
    Farming.base, Farming.overlaid = {
    }, false
    Modes.lastScored = nil
    if type(FarmHub.last) == "table" then
        FarmHub.last.pick = nil
    end
end

function Farming.applyOverlay(task)
    Farming.clearOverlay()
    for key, value in pairs(Farming.overlayFor(task)) do
        Farming.base [key] = Config [key]
        Config [key] = value
    end
    Farming.overlaid = true
end

-- Your own (manual Auto Farm) value of a setting, whatever a session lays over it.
function Farming.baseValue(key)
    if Farming.overlaid and Farming.base [key] ~= nil then
        return Farming.base [key]
    end
    return Config [key]
end

-- A change you make to a setting: during a session it goes to your own settings, not the session's.
function Farming.setBase(key, value)
    if Farming.overlaid and Farming.base [key] ~= nil then
        Farming.base [key] = value
        return true
    end
    Config [key] = value
    return false
end

-- What settings.json gets: always your own values.
function Farming.savedConfig()
    if not Farming.overlaid then
        return Config
    end
    local copy = table.clone(Config)
    for key, value in pairs(Farming.base) do
        copy [key] = value
    end
    return copy
end

function Farming.active()
    local run = Brain.farmRun
    if type(run) == "table" and run.state == "running" then
        return run
    end
    return nil
end

function Farming.title(run)
    return run.source == "quick" and "Quick Start" or (run.name == "Queue" and "Queue" or ("Routine " .. tostring(run.name)))
end

function Farming.hold(why)
    Brain.holdLobby = {
        why = why,
        at = os.time(),
        farming = true
    }
end

function Farming.sync()
    if GUI.farmSync then
        pcall(GUI.farmSync)
    end
end

-- source: "quick" or "routine". Only one session at a time, manual Auto Farm included.
function Farming.start(source, name, tasks)
    local running = Farming.active()
    if running then
        return false, string.format("%s is running (%s). Press Stop first", Farming.title(running), Farming.progressText(true))
    end
    if type(tasks) ~= "table" or # tasks == 0 then
        return false, "The queue is empty: add a task"
    end
    for index, task in ipairs(tasks) do
        local why = Farming.check(task)
        if why then
            return false, (# tasks > 1 and ("Task " .. index .. ": ") or "") .. why
        end
    end
    local manual = Config.master and Config.play and not Brain.holdLobby
    local copy = Farming.copy(tasks)
    for _, task in ipairs(copy) do
        task.runs = math.floor(tonumber(task.runs) or 1)
    end
    Brain.farmRun = {
        source = source,
        name = name,
        tasks = copy,
        index = 1,
        done = 0,
        state = "running",
        fails = 0,
        counted = {
        },
        startedAt = os.time()
    }
    Farming.applyOverlay(copy [1])
    Config.master, Config.play = true, true
    Brain.holdLobby = nil
    App.saveNow()
    Farming.sync()
    local text = string.format("%s started: %s%s", Farming.title(Brain.farmRun), Farming.label(copy [1]), # copy > 1 and string.format(" (task 1 of %d)", # copy) or "")
    App.log(1, "FARM", text .. (manual and " · it replaces manual Auto Farm until it ends" or ""))
    return true, text .. (App.where == "match" and " · it starts after this match" or "")
end

function Farming.stop(why)
    why = why or "you pressed Stop"
    local run = Brain.farmRun
    local had = Farming.active() ~= nil
    if had then
        run.state, run.why = "stopped", why
        Farming.clearOverlay()
    end
    Farming.hold(why)
    App.saveNow()
    Farming.sync()
    App.log(1, "FARM", (had and (Farming.title(run) .. " stopped") or "farming stopped") .. ": " .. why .. " · no new run starts until you start again")
    return true, App.where == "match" and "stopped: this match finishes, then no new run starts" or "stopped: no new run starts"
end

-- Stopped or paused: go on from the confirmed count.
function Farming.retry()
    local run = Brain.farmRun
    if type(run) ~= "table" or run.state == "running" then
        return false, run and "it's already running" or "nothing to retry"
    end
    if run.state == "finished" then
        return false, "it finished: start it again instead"
    end
    local task = run.tasks [run.index]
    local why = Farming.check(task)
    if why then
        return false, "Task " .. run.index .. ": " .. why
    end
    run.state, run.why, run.fails, run.noModeAt = "running", nil, 0, nil
    Farming.applyOverlay(task)
    Config.master, Config.play = true, true
    Brain.holdLobby = nil
    App.saveNow()
    Farming.sync()
    App.log(1, "FARM", string.format("%s goes on: %s", Farming.title(run), Farming.progressText(true)))
    return true, "going on from " .. run.done .. "/" .. task.runs
end

function Farming.finish(why)
    local run = Brain.farmRun
    run.state, run.why = "finished", why
    Farming.clearOverlay()
    Farming.hold(Farming.title(run) .. " finished")
    App.log(1, "FARM", string.format("%s finished: %d task%s done", Farming.title(run), # run.tasks, # run.tasks == 1 and "" or "s"))
    pcall(Discord.alert, "Farming finished", string.format("%s: %d task%s done · no new runs until you start again", Farming.title(run), # run.tasks, # run.tasks == 1 and "" or "s"))
    Farming.sync()
end

function Farming.fail(why)
    local run = Brain.farmRun
    run.state, run.why = "failed", why
    Farming.clearOverlay()
    Farming.hold("farming paused: " .. why)
    App.log(1, "FARM", string.format("%s paused: %s · press Retry to go on from %d/%d", Farming.title(run), why, run.done, run.tasks [run.index].runs))
    pcall(Discord.alert, "Farming paused", string.format("%s paused: %s · press Retry to go on from %d/%d", Farming.title(run), tostring(why), run.done, run.tasks [run.index].runs))
    App.saveNow()
    Farming.sync()
end

function Farming.advance()
    local run = Brain.farmRun
    run.index, run.done, run.fails, run.noModeAt = run.index + 1, 0, 0, nil
    if run.index > # run.tasks then
        run.index = # run.tasks
        run.done = run.tasks [run.index].runs
        Farming.finish("all tasks done")
        return
    end
    Farming.applyOverlay(run.tasks [run.index])
    App.log(1, "FARM", string.format("%s: task %d of %d · %s", Farming.title(run), run.index, # run.tasks, Farming.label(run.tasks [run.index])))
    Farming.sync()
end

function Farming.isLegend(id)
    local level = id and Core.Levels [id]
    local world = level and Core.Worlds [level.world]
    return world ~= nil and world.legend_stage and true or false
end

-- Was this match a run of the task?
function Farming.matches(task, key, kind)
    key = tostring(key)
    if task.mode == "story" or task.mode == "legend" then
        if kind ~= "story" then
            return false
        end
        if (task.mode == "legend") ~= Farming.isLegend(key:match("^st:(.+):%a+$")) then
            return false
        end
        local pick = Farming.pickValue(task)
        return pick == "" or pick == "progress" or key == pick
    end
    if task.mode == "raid" or task.mode == "infinite" then
        return kind == task.mode and (task.map == "" or key == task.map)
    end
    if task.mode == "challenge" then
        return kind == "challenge" or kind == "daily"
    end
    return kind == task.mode
end

-- A confirmed match result. id is the same for the same result, so a restart on the results screen
-- doesn't count it twice.
function Farming.onResult(key, kind, won, id)
    local run = Farming.active()
    if not run then
        return nil
    end
    local task = run.tasks [run.index]
    if not task then
        return nil
    end
    if not Farming.matches(task, key, kind) then
        App.log(1, "FARM", tostring(key) .. " isn't this task's mode: not counted")
        return false
    end
    if not won then
        App.log(1, "FARM", "lost: not counted, still " .. run.done .. "/" .. task.runs)
        return false
    end
    run.counted = type(run.counted) == "table" and run.counted or {
    }
    if table.find(run.counted, id) then
        return false
    end
    table.insert(run.counted, id)
    while # run.counted > 30 do
        table.remove(run.counted, 1)
    end
    run.done, run.fails, run.why = run.done + 1, 0, nil
    App.log(1, "FARM", string.format("%s · task %d of %d · %s · %d/%d", Farming.title(run), run.index, # run.tasks, Farming.label(task, true), run.done, task.runs))
    if run.done >= task.runs then
        Farming.advance()
    end
    App.saveSoon()
    return true
end

-- The lobby tried to start a run of this session and the game didn't take it.
function Farming.launchFailed(mode, why)
    local run = Farming.active()
    if not run then
        return
    end
    run.fails = (run.fails or 0) + 1
    run.why = string.format("couldn't start %s: %s", type(mode) == "table" and tostring(mode.label) or "the run", tostring(why or "no reason given"))
    if run.fails >= Farming.MAX_FAILS then
        Farming.fail(run.why)
    end
end

function Farming.launching()
    local run = Farming.active()
    if run then
        run.noModeAt = nil
    end
end

-- Nothing of this session's mode can be played right now.
function Farming.noMode(text)
    local run = Farming.active()
    if not run then
        return
    end
    run.noModeAt = run.noModeAt or os.time()
    run.why = tostring(text)
    if os.time() - run.noModeAt >= Farming.NO_MODE_WAIT then
        Farming.fail(Farming.label(run.tasks [run.index], true) .. " can't be played: " .. tostring(text))
    end
end

-- After a teleport or a restart: lay the running task over your settings again.
function Farming.resume()
    local run = Brain.farmRun
    if type(run) ~= "table" or type(run.tasks) ~= "table" or # run.tasks == 0 then
        Brain.farmRun = nil
        return
    end
    run.index = math.clamp(math.floor(tonumber(run.index) or 1), 1, # run.tasks)
    run.done = math.max(0, math.floor(tonumber(run.done) or 0))
    if run.state == "running" then
        Farming.applyOverlay(run.tasks [run.index])
    end
end

function Farming.progressText(short)
    local run = Brain.farmRun
    if type(run) ~= "table" or type(run.tasks) ~= "table" or # run.tasks == 0 then
        return "Nothing running. Set it up and press Start."
    end
    local task = run.tasks [run.index] or run.tasks [1]
    local line = string.format("Task %d of %d · %s · %d/%d", run.index, # run.tasks, Farming.label(task, true), run.done, task.runs)
    if short then
        return line
    end
    local title = Farming.title(run)
    if run.state == "running" then
        return title .. " · " .. line .. (run.why and ("\nWaiting: " .. run.why) or "")
    elseif run.state == "finished" then
        return string.format("%s finished: %d task%s done.", title, # run.tasks, # run.tasks == 1 and "" or "s")
    elseif run.state == "failed" then
        return string.format("%s paused · %s\nWhy: %s\nFix it, then press Retry to go on from %d/%d.", title, line, tostring(run.why), run.done, task.runs)
    end
    return string.format("%s stopped · %s\nRetry goes on from %d/%d.", title, line, run.done, task.runs)
end

-- Saved routines live in Config.routines: { { name =, tasks = { task, … } }, … }.
function Farming.routines()
    if type(Config.routines) ~= "table" then
        Config.routines = {
        }
    end
    return Config.routines
end

function Farming.routine(name)
    for index, routine in ipairs(Farming.routines()) do
        if type(routine) == "table" and routine.name == name then
            return routine, index
        end
    end
    return nil
end

-- Save under name; oldName renames that routine. Returns ok, message.
function Farming.saveRoutine(oldName, name, tasks)
    name = tostring(name or ""):gsub("^%s+", ""):gsub("%s+$", "")
    if name == "" then
        return false, "Type a name for the routine first"
    end
    local other = Farming.routine(name)
    local own = oldName and oldName ~= "" and Farming.routine(oldName) or nil
    if other and other ~= own then
        if own then
            return false, "Another routine is already called " .. name
        end
        own = other
    end
    if own then
        own.name, own.tasks = name, Farming.copy(tasks or {
        })
    else
        table.insert(Farming.routines(), {
            name = name,
            tasks = Farming.copy(tasks or {
            })
        })
    end
    Config.routineSel = name
    App.saveNow()
    return true, (own and oldName and oldName ~= "" and oldName ~= name) and ("renamed to " .. name) or ("saved: " .. name)
end

function Farming.deleteRoutine(name)
    local routine, index = Farming.routine(name)
    if not routine then
        return false
    end
    table.remove(Farming.routines(), index)
    if Config.routineSel == name then
        Config.routineSel = ""
    end
    App.saveNow()
    return true
end

-- 2.27: Home → Auto Farm. One row per mode Smart may pick (the same flags as Farming → Modes) and one per job between runs (the same switch as on its own tab).
Farming.PICK_MODES = {
    { value = "story", text = "Story", enable = { "firstClears", "farm" }, only = "onlyStory" },
    { value = "infinite", text = "Infinite", enable = { "infinite" }, only = "onlyInfinite" },
    { value = "portals", text = "Portals", enable = { "portals" }, only = "onlyPortals" },
    { value = "raids", text = "Raids", enable = { "raids" }, only = "onlyRaids" },
    { value = "artifact", text = "Artifact Stage", enable = { "artifact" }, only = "onlyArtifact" },
    { value = "dungeon", text = "Dungeon", enable = { "dungeon" }, only = "onlyDungeons" },
    { value = "challenges", text = "Challenges", enable = { "dailyChallenge", "challenge" }, only = "onlyChallenges" },
    { value = "event", text = "Event (Summer Hunt)", enable = { "event" }, only = "onlyCoins" },
}
Farming.PICK_JOBS = {
    { value = "team", text = "Make My Team Stronger" },
    { value = "smartEvolve", text = "Smart Evolve" },
    { value = "goals", text = "Farm Toward Goals" },
    { value = "trainTakedowns", text = "Takedown Training" },
    { value = "teamFuse", text = "Limit Break Core Units" },
    { value = "autoSummon", text = "Auto Summon (gems)" },
    { value = "snipeOn", text = "Banner Snipe (gems)" },
    { value = "rewards", text = "Auto Rewards" },
    { value = "codes", text = "Redeem Codes" },
    { value = "goldShop", text = "Star Fruits For Gold" },
}
Farming.ONLY_KEYS = { "onlyStory", "onlyLegend", "onlyInfinite", "onlyPortals", "onlyRaids", "onlyArtifact", "onlyDungeons", "onlyChallenges", "onlyCoins" }

-- Ticked: any of its On flags, or its Only this. Your own values, not a running session's.
function Farming.pickOn(item)
    if item.only and Farming.baseValue(item.only) then
        return true
    end
    for _, key in ipairs(item.enable or { item.value }) do
        if Farming.baseValue(key) then
            return true
        end
    end
    return false
end

function Farming.picked(list)
    local values = {}
    for _, item in ipairs(list) do
        if Farming.pickOn(item) then
            table.insert(values, item.value)
        end
    end
    return values
end

-- Writes only the rows whose tick changed, so an Only this on a row that stays ticked is kept.
function Farming.applyPicks(list, values)
    local want, changed = {}, {}
    for _, value in ipairs(values or {}) do
        want [value] = true
    end
    for _, item in ipairs(list) do
        local on = want [item.value] == true
        if on ~= Farming.pickOn(item) then
            for _, key in ipairs(item.enable or { item.value }) do
                Farming.setBase(key, on)
            end
            if item.only and not on then
                Farming.setBase(item.only, false)
            end
            if item.value == "teamFuse" then
                Farming.setBase("fuseArmSig", "")
            end
            table.insert(changed, (on and "+" or "-") .. item.text)
        end
    end
    if # changed == 0 then
        return false
    end
    Farming.pickReset()
    App.log(1, "FARM", "Auto Farm choices: " .. table.concat(changed, ", "))
    return true
end

-- Every Only this off: Smart goes back to all ticked modes.
function Farming.clearOnly()
    local cleared = {}
    for _, key in ipairs(Farming.ONLY_KEYS) do
        if Farming.baseValue(key) then
            Farming.setBase(key, false)
            table.insert(cleared, key)
        end
    end
    if # cleared == 0 then
        return false
    end
    Farming.pickReset()
    App.log(1, "FARM", "Only this cleared: " .. table.concat(cleared, ", "))
    return true
end

-- The same resets as the switches on their own tabs.
function Farming.pickReset()
    Modes.lastScored = nil
    local last = type(FarmHub) == "table" and FarmHub.last
    if type(last) == "table" then
        last.pick, last.teamPlan, last.summon, last.snipe = nil, nil, nil, nil
    end
    if type(Brain.str) == "table" then
        Brain.str.next = nil
    end
end

function Farming.pickText()
    if not Farming.baseValue("master") then
        return "Auto Farm is off: press Start Auto Farming."
    end
    local okEvent, eventNow = pcall(Modes.eventNow)
    local only, on = {}, {}
    if Farming.baseValue("onlyLegend") then
        table.insert(only, "Legend Stages")
    end
    for _, item in ipairs(Farming.PICK_MODES) do
        if item.only and Farming.baseValue(item.only) and (item.only ~= "onlyCoins" or (okEvent and eventNow ~= nil)) then
            table.insert(only, item.text)
        elseif Farming.pickOn(item) then
            table.insert(on, item.text)
        end
    end
    local text
    if # only > 0 then
        text = "Plays only " .. table.concat(only, ", ") .. " (an old Only this: untick and tick it again to clear)."
    elseif # on == 0 then
        text = "No mode ticked: it plays nothing but Legend Stages a goal needs."
    else
        text = "Smart: plays whichever pays best of " .. table.concat(on, ", ") .. "."
    end
    text = text .. " Jobs between runs: " .. # Farming.picked(Farming.PICK_JOBS) .. " on."
    local run = Farming.active()
    if run then
        text = text .. " " .. Farming.title(run) .. " is running: it plays its own task, these apply when it stops."
    end
    if not Farming.baseValue("play") then
        text = text .. " Auto Play is off: you start runs yourself."
    end
    if Farming.baseValue("unitsPaused") then
        text = text .. " Units jobs are paused (Units → Goals → Smart Play For Units)."
    end
    return text
end

function FarmHub.run()
    App.status("Mode", "in the lobby")
    local now = Utils.now()
    pcall(Units.markHidden)
    pcall(function()
        local unitsHatchedThroughBanner = ReplicatedStorage.endpoints.server_to_client:FindFirstChild("units_hatched_through_banner")
        if not unitsHatchedThroughBanner then
            return
        end
        table.insert(App.conns, unitsHatchedThroughBanner.OnClientEvent:Connect(function(arg1)
            for _, value in pairs(type(arg1) == "table" and arg1 or {
            }) do
                local unitObj = Core.session() and Core.session().collection:get_unit_by_uuid(value)
                if unitObj and unitObj.unit_id then
                    FarmHub.hatched [unitObj.unit_id] = true
                    App.log(2, "SUMMON", "pulled " .. Units.name(unitObj.unit_id))
                end
            end
        end))
    end)
    App.listenGame()
    task.delay(6, function()
        local ok, res = pcall(Strategy.xpSettle)
        if not ok then
            App.log(1, "ERROR", "xp settle: " .. tostring(res))
        end
    end)
    task.delay(8, function()
        local ok, res = pcall(FarmHub.watchDone)
        if not ok then
            App.log(1, "ERROR", "portal count: " .. tostring(res))
        end
    end)
    while App.alive do
        if Config.master and not Brain.holdLobby then
            if Brain.str.reequip then
                pcall(Strategy.reequip)
            end
            if Brain.buyStorage then
                local ok, res = pcall(FarmHub.buyStorage)
                if not ok then
                    App.log(1, "ERROR", "unit storage: " .. tostring(res))
                end
            end
            if Brain.buyOnce then
                local ok, res = pcall(FarmHub.buyOnce)
                if not ok then
                    App.log(1, "ERROR", "shop item: " .. tostring(res))
                end
            end
            if Brain.ownSwap and FarmHub.every("ownSwap", 60) then
                local ok, res = pcall(FarmHub.ownSwap)
                if not ok then
                    App.log(1, "ERROR", "team change: " .. tostring(res))
                end
            end
            if Brain.train.on then
                local ok, res = pcall(Training.home)
                if not ok then
                    App.log(1, "ERROR", "training: " .. tostring(res))
                end
            end
            if FarmHub.every("live", 60) then
                pcall(FarmHub.refreshLive)
            end
            if FarmHub.every("huntShop", 3600) then
                pcall(Hunt.shopLook)
            end
            if FarmHub.every("hive", 60) then
                pcall(Reports.sendHive)
            end
            if FarmHub.every("hiveUnit", 60) then
                task.delay(20, function()
                    pcall(Reports.sendUnit)
                end)
            end
            if # Brain.studyQ > 0 and FarmHub.every("hiveStudy", 15) then
                task.spawn(function()
                    pcall(Reports.sendStudy, 3)
                end)
            end
            if Config.useHive and FarmHub.every("hiveGet", 6 * 3600) then
                task.spawn(function()
                    local ok, res = pcall(Reports.hiveFetch)
                    if not ok then
                        App.log(1, "ERROR", "local learning read: " .. tostring(res))
                    end
                end)
            end
            if FarmHub.every("rewards", 45) then
                local ok, res = pcall(FarmHub.rewards)
                if not ok then
                    App.log(1, "ERROR", "rewards: " .. tostring(res))
                end
            end
            if FarmHub.every("gold", 600) then
                local ok, res = pcall(FarmHub.goldShop)
                if not ok then
                    App.log(1, "ERROR", "gold shop: " .. tostring(res))
                end
            end
            if Config.snipeOn and (FarmHub.every("snipe", 600) or (FarmHub.snipeStale() and FarmHub.every("snipeStale", 30))) then
                local ok, res = pcall(FarmHub.bannerSnipe)
                if not ok then
                    App.log(1, "ERROR", "Banner Snipe: " .. tostring(res))
                end
            end
            if FarmHub.every("summon", 30) then
                local ok, res = pcall(FarmHub.summon)
                if not ok then
                    App.log(1, "ERROR", "summon: " .. tostring(res))
                end
                local ok, res = pcall(FarmHub.eventShop)
                if not ok then
                    App.log(1, "ERROR", "event shop: " .. tostring(res))
                end
            end
            if FarmHub.every("codes", 21600) then
                local ok, res = pcall(FarmHub.codes)
                if not ok then
                    App.log(1, "ERROR", "codes: " .. tostring(res))
                end
            end
            if FarmHub.every("rshopCache", 1800) then
                local ok, res = App.request("rshopList", "request_current_raidshop_shop")
                if ok and type(res) == "table" then
                    table.clear(Brain.raidShop)
                    for key, value in pairs(res) do
                        if type(value) == "table" and value.id and value.item_cost then
                            Brain.raidShop [key] = {
                                id = value.id,
                                costItem = value.item_cost.item_id,
                                cost = tonumber(value.item_cost.amount) or 0,
                                stock = value.stock
                            }
                        end
                    end
                end
            end
            if FarmHub.every("lbInfo", 1800) then
                local item = Units.equipped() [1]
                if item then
                    local ok, res = App.request("lbInfo", "request_fusion_information", item.uuid)
                    if ok and type(res) == "table" then
                        Brain.lb = {
                            requirement = res.requirement,
                            allowed = res.allowed
                        }
                    end
                end
            end
            if FarmHub.every("goals", 300) then
                local ok, res = pcall(Adventure.refresh)
                if not ok then
                    App.log(1, "ERROR", "goals: " .. tostring(res))
                else
                    local ok, res = pcall(Adventure.buyShopGoals)
                    if ok and res then
                        pcall(Adventure.refresh)
                    end
                    local ok, res = pcall(FarmHub.smartEvolve)
                    if not ok then
                        App.log(1, "ERROR", "smart evolve: " .. tostring(res))
                    end
                end
                Modes.lastScored = nil
            end
            if FarmHub.every("picks", 20) then
                for _, value in ipairs({
                    FarmHub.focusNextUp,
                    FarmHub.autoEvolve,
                    FarmHub.autoFuse,
                    FarmHub.autoFuseXp,
                    Hunt.skinTick
                }) do
                    local ok, res = pcall(value)
                    if not ok then
                        App.log(1, "ERROR", "lobby picks: " .. tostring(res))
                    end
                end
                local ok, res = pcall(Strategy.tick)
                if not ok then
                    App.log(1, "ERROR", "team: " .. tostring(res))
                end
            end
            local ok, res = pcall(Strategy.finishWork)
            if not ok then
                App.log(1, "ERROR", "team work: " .. tostring(res))
            end
            local value = Modes.lastScored and Modes.lastScored [1]
            if FarmHub.every("pick", 5) or not value then
                local ok, res = pcall(Modes.pick)
                if not ok then
                    App.log(1, "ERROR", "ranking: " .. tostring(res))
                    res = nil
                end
                value = res
            end
            if not FarmHub.manualPlanning and Config.sim and Config.simTeams and not (Config.autoTeam and Config.play) and FarmHub.every("simTeam", 600) then
                task.spawn(function()
                    for _, value in ipairs(Modes.lastScored or {
                    }) do
                        if value.kind == "daily" or value.kind == "challenge" or value.first then
                            local ok, res = pcall(Simulator.plan, value, true)
                            if not ok then
                                App.log(1, "ERROR", "planner: " .. tostring(res))
                            end
                            break
                        end
                    end
                end)
            end
            if Config.trainTakedowns and not Config.unitsPaused and Config.sim and Modes.lastScored and FarmHub.every("trainScan", 600) then
                FarmHub.scanning = Utils.now()
                task.spawn(function()
                    local ok, res = pcall(Training.scan)
                    if not ok then
                        App.log(1, "ERROR", "training planner: " .. tostring(res))
                    end
                    FarmHub.scanning = nil
                    Modes.lastScored = nil
                end)
                value = nil
            end
            if FarmHub.scanning and Utils.now() - FarmHub.scanning < 30 then
                value = nil
            end
            if not FarmHub.manualPlanning and Config.play and Config.sim and value and not FarmHub.simFresh(value) and (value.kind ~= "event" or Modes.hasOwnTeam(value)) and value.kind ~= "dungeon" and not (Modes.hasOwnTeam(value) and not Modes.ownProfile(value)) then
                local doTeamSearch = Modes.canSearch(value) and not Modes.teamPlan(value)
                App.status("Mode", (doTeamSearch and "planning best team for " or "simulating ") .. value.label .. "…")
                if doTeamSearch then Simulator.memoOn() end
                local ok, res = pcall(Simulator.plan, value, doTeamSearch, doTeamSearch and 20 or nil)
                if doTeamSearch then Simulator.memo = nil end
                if not ok then
                    App.log(1, "ERROR", "sim: " .. tostring(res))
                end
                if not (ok and res) then
                    Brain.simRes [value.key] = {
                        none = true,
                        sig = Modes.teamSig(),
                        profile = Modes.hasOwnTeam(value) and Modes.ownProfile(value) or Modes.equippedProfile(),
                        rotation = Modes.rotation(value),
                        at = os.time()
                    }
                end
                Modes.lastScored = nil
                value = nil
            end
            if not FarmHub.manualPlanning and Config.play and value and Utils.now() - now > 8 and not (App.req.back.launch and Utils.now() < App.req.back.launch) then
                local alreadyInLobby = LocalPlayer:FindFirstChild("AlreadyInLobby")
                if Brain.trial and not Modes.hasOwnTeam(value) then
                    local ok, res = pcall(Modes.trialTeam)
                    if not ok then
                        App.log(1, "ERROR", "trial team: " .. tostring(res))
                        Brain.trial = nil
                    end
                    if ok and res and not (alreadyInLobby and alreadyInLobby.Value) then
                        pcall(FarmHub.launch, value)
                    end
                else
                    local teamReady = true
                    if Modes.hasOwnTeam(value) or Config.autoTeam or (Brain.testTeam and (Brain.testTeam.left or 0) > 0 and Brain.testTeam.key == value.key) then
                        local ok, equipped = pcall(FarmHub.teamFor, value)
                        teamReady = ok and equipped
                        if not teamReady then
                            App.log(1, "TEAM", ok and "waiting for the requested team" or tostring(equipped))
                            Modes.lastScored = nil
                            App.backoff("launch", 15)
                        end
                    end
                    if teamReady then
                        local ok, res = pcall(Training.apply, value)
                        if not ok then
                            App.log(1, "ERROR", "training: " .. tostring(res))
                            pcall(Training.home)
                        end
                        local ok, res = pcall(Hunt.charmTick, value)
                        if not ok then
                            App.log(1, "ERROR", "charm: " .. tostring(res))
                        end
                        if not (alreadyInLobby and alreadyInLobby.Value) then
                            pcall(Farming.launching)
                            local launched, launchError = pcall(FarmHub.launch, value)
                            if not launched then App.log(1, "ERROR", "launch: " .. tostring(launchError)) end
                            -- FarmHub.launch only comes back when no teleport followed.
                            if not launched or launchError == false then
                                pcall(Farming.launchFailed, value, launched and Farming.lastWhy or tostring(launchError))
                            end
                        end
                    end
                end
            elseif not Config.play then
                App.status("Mode", "Auto Play is off")
            elseif not value then
                local noModeText = Modes.onlyOn() and string.format("only %s is on and none can be played right now: waiting", Modes.onlyText()) or "nothing to play (all modes off or resting)"
                App.status("Mode", noModeText)
                if Farming.active() then
                    local reasons = {
                    }
                    for _, why in pairs(Modes.skipped) do
                        table.insert(reasons, tostring(why))
                    end
                    pcall(Farming.noMode, # reasons > 0 and table.concat(reasons, "; ") or noModeText)
                end
            end
        else
            App.status("Mode", Brain.holdLobby and ("held in the lobby: " .. tostring(Brain.holdLobby.why)) or "paused")
            if not Config.master or Brain.holdLobby then
                if # Brain.studyQ > 0 and FarmHub.every("hiveStudy", 15) then
                    task.spawn(function()
                        pcall(Reports.sendStudy, 3)
                    end)
                end
                if FarmHub.every("summon", 30) then
                    local ok, res = pcall(FarmHub.summon)
                    if not ok then
                        App.log(1, "ERROR", "summon: " .. tostring(res))
                    end
                end
                if Config.snipeOn and (FarmHub.every("snipe", 600) or (FarmHub.snipeStale() and FarmHub.every("snipeStale", 30))) then
                    local ok, res = pcall(FarmHub.bannerSnipe)
                    if not ok then
                        App.log(1, "ERROR", "Banner Snipe: " .. tostring(res))
                    end
                end
                if FarmHub.every("picks", 20) then
                    for _, value in ipairs({
                        FarmHub.autoFuse,
                        FarmHub.autoFuseXp,
                        Hunt.skinTick
                    }) do
                        local ok, res = pcall(value)
                        if not ok then
                            App.log(1, "ERROR", "lobby picks: " .. tostring(res))
                        end
                    end
                end
            end
        end
        task.wait(2)
    end
end

Economy.REACH_CAP = 2

-- How much more road a wider circle reaches. With a spot known, reachOf(range) measures it;
-- otherwise the stretch of road inside a circle grows about in step with its radius.
function Economy.reachRatio(curRange, newRange, reachOf)
    curRange = math.max(1, tonumber(curRange) or 1)
    newRange = tonumber(newRange) or curRange
    if newRange <= curRange then
        return 1
    end
    if reachOf then
        local ok, before = pcall(reachOf, curRange)
        local ok2, after = pcall(reachOf, newRange)
        if ok and ok2 and tonumber(before) and tonumber(after) then
            if before <= 0 then
                return after > 0 and Economy.REACH_CAP or 1
            end
            return Utils.clamp(after / before, 1, Economy.REACH_CAP)
        end
    end
    return math.min(Economy.REACH_CAP, newRange / curRange)
end

-- Damage a level puts out, per second of a target in reach: hits per second times targets per hit.
function Economy.rowRate(row)
    if not (row and row.cd and row.cd > 0) then
        return 0
    end
    return row.damage / row.cd * math.max(0.3, Units.aoe(row.atk, row.range) or 0.3)
end

-- The gain of one upgrade, in the damage per second it adds. A unit's power is its rate times the
-- road it reaches, so a wider circle multiplies the whole unit, not only the added damage: an
-- upgrade that only widens the circle is worth something too. One and two steps ahead use the same
-- rate (area of effect included), so a weak step before a strong one is judged on equal terms.
function Economy.upgradeGain(liveDps, rows, level, cost, costMul, nextDps, reachOf, budget)
    local cur, nxt = rows [level], rows [level + 1]
    local curRate = Economy.rowRate(cur)
    local curRange = cur and cur.range or 1
    local function powerAt(row)
        return Economy.rowRate(row) / curRate * Economy.reachRatio(curRange, row and row.range or curRange, reachOf)
    end
    local gain = curRate > 0 and liveDps * (powerAt(nxt) - 1) or (nextDps or 0)
    -- 2.26: the best yen-for-damage over the whole road to any later level, not only the next two. A weak
    -- step before strong ones (Fused Hero: levels 2 and 3 hit slower than level 1, 4 to 6 recover) is
    -- then worth the part of that road it buys; for an ordinary table the first step stays the best and
    -- nothing changes as long as no later level is a better buy per yen than the next one. A road the
    -- yen still to come can't pay for (budget) doesn't count.
    if curRate > 0 and cost and cost > 0 and (rows.max or 0) >= level + 2 then
        local base = math.max(0, gain)
        local baseEff = base / cost
        local bestEff, total = baseEff, cost
        for k = level + 2, rows.max do
            local row = rows [k]
            if not row then
                break
            end
            total = total + (row.cost or 0) * (costMul or 1)
            if budget and total > budget then
                break
            end
            if Economy.rowRate(row) > 0 then
                local eff = liveDps * (powerAt(row) - 1) / total
                if eff > bestEff then
                    bestEff = eff
                end
            end
        end
        if bestEff > baseEff then
            gain = base + (bestEff * cost - base) * 0.5
        end
    end
    return math.max(0, gain)
end

function Economy.dpsFor(arg1, reward)
    if reward <= 0 then
        return 0
    end
    local list = {
    }
    for _, value in ipairs(arg1) do
        if not value.farm and value.gain > 0 then
            table.insert(list, value)
        end
    end
    table.sort(list, function(arg1, arg2)
        return arg1.gain / arg1.cost > arg2.gain / arg2.cost
    end)
    local count, count2 = 0, 0
    for _, item in ipairs(list) do
        if reward <= 0 then
            break
        end
        count2 = item.gain / item.cost
        local value = math.min(1, reward / item.cost)
        count = count + item.gain * value
        reward = reward - item.cost * value
    end
    return count + math.max(0, reward) * count2 * 0.7
end

function Economy.shieldDps(arg1, cd, n, count, num, eff, hits)
    if (count or 0) <= 0 or (arg1 or 0) <= 0 or (num or 0) <= 0 then
        return arg1 or 0
    end
    cd, n, eff = math.max(0.3, cd or 2), math.max(1, n or 1), eff or 1
    local ratio = arg1 * eff * cd / n
    return num * n / ((count / math.max(1, hits or 1) + math.max(1, num / ratio)) * cd) / eff
end

function Economy.shieldGain(dpsAll, row, dps, row2, count, num, cd, eff)
    local attackInfo, attackInfo2 = Units.attackInfo(row.atk, row.range), Units.attackInfo(row2.atk, row2.range)
    local shieldDps = Economy.shieldDps(dpsAll, (tonumber(row.cd) or 2) * (cd or 1), attackInfo.n, count, num, eff, attackInfo.hits)
    local shieldDps2 = Economy.shieldDps(dps, (tonumber(row2.cd) or 2) * (cd or 1), attackInfo2.n, count, num, eff, attackInfo2.hits)
    local value = math.max(0, ((tonumber(row2.range) or 0) - (tonumber(row.range) or 0)) / math.max(1, tonumber(row.range) or 1))
    return math.max(0, shieldDps2 - shieldDps) + shieldDps * value
end

function Economy.shieldWork(n, value, count, count2, tab, waveSec, count3, num, hits)
    if (count2 or 0) <= 0 then
        return 0
    end
    local ratio = 3 * count2 * (tab or 1) / math.max(1, waveSec or 20)
    if (count or 0) >= ratio then
        return 0
    end
    return math.max(1, n or 1) * math.max(1, hits or 1) / math.max(0.3, value or 2) * math.min(count3 or 0, num or 0)
end

function Economy.holdGain(attackInfo, count, ratio, count2)
    if not attackInfo or (count or 0) <= 0 then
        return 0
    end
    local stun, slowTime = tonumber(attackInfo.stun) or 0, tonumber(attackInfo.slowTime) or 0
    if stun <= 0 and slowTime <= 0 then
        return 0
    end
    local stun2, num = stun > 0 and stun or slowTime, stun > 0 and 1 or (tonumber(attackInfo.slowPct) or 0.3)
    local ratio2 = num * stun2 / (stun2 + (tonumber(attackInfo.ccCd) or 8))
    local ratio3 = ratio2 / math.max(0.1, 1 - ratio2)
    return count * ratio3 * Utils.clamp(ratio or 0.5, 0, 1) * math.min(1, (tonumber(attackInfo.n) or 1) / 2) / (1 + (count2 or 0))
end

function Economy.bleedGain(regen, count, coming, arg4)
    if (regen or 0) <= 0 then
        return 0
    end
    local count2 = count or 0
    for _, value in ipairs(coming or {
    }) do
        count2 = math.max(count2, (tonumber(value.hp) or 0) * 0.5)
    end
    return regen * count2 * (arg4 and 0.5 or 1)
end

function Economy.bleedShare(bleedGain, bleeds, arg3, arg4)
    if bleedGain <= 0 or not bleeds then
        return 0
    end
    if arg4 then
        return bleeds == 0 and bleedGain or bleedGain / (bleeds + 1)
    end
    return arg3 < bleeds and bleedGain / (bleeds - arg3) or 0
end

function Economy.keepsUp(ctx, options, cost, addedDps, farmGain)
    local coming = ctx.coming
    if not (coming and # coming > 0 and ctx.waveSec) then
        return true
    end
    local eff = ctx.eff or 1
    local money = ctx.money - cost
    local killRate = (ctx.teamDps or 0) * (ctx.shieldK or 1) + (addedDps or 0) * eff + Economy.dpsFor(options, math.max(0, money)) * eff
    local farmNow = (ctx.farmNow or 0) + (farmGain or 0)
    local roadSec = (ctx.roadSec or 130) * Utils.clamp(ctx.cover or 0.6, 0.1, 1)
    local hpAlive = ctx.hpAlive or 0
    for i, wave in ipairs(coming) do
        hpAlive = math.max(0, hpAlive + wave.hp - killRate * ctx.waveSec)
        local canKill = killRate * roadSec
        if hpAlive > canKill then
            return false, i, canKill / math.max(1, hpAlive)
        end
        if i < # coming then
            killRate = killRate + Economy.dpsFor(options, (wave.reward or 0) + farmNow) * eff * (0.85 ^ i)
        end
    end
    -- Flying enemies are taken only by the units that reach the air (ctx.airShare of the damage), so
    -- they get their own check: enough damage overall does not help if it cannot hit them. Future
    -- buys are assumed to reach the air in the same share as the team does now.
    local airShare = tonumber(ctx.airShare)
    if airShare and airShare < 0.999 then
        local airRate = ((ctx.teamDps or 0) * (ctx.shieldK or 1) + (addedDps or 0) * eff + Economy.dpsFor(options, math.max(0, money)) * eff) * airShare
        local airAlive = tonumber(ctx.airAlive) or 0
        for i, wave in ipairs(coming) do
            local airHp = tonumber(wave.airHp) or 0
            if airHp > 0 or airAlive > 0 then
                airAlive = math.max(0, airAlive + airHp - airRate * ctx.waveSec)
                local canKill = airRate * roadSec
                if airAlive > canKill then
                    return false, i, canKill / math.max(1, airAlive), "air"
                end
            end
            if i < # coming then
                airRate = airRate + Economy.dpsFor(options, (wave.reward or 0) + farmNow) * eff * (0.85 ^ i) * airShare
            end
        end
    end
    return true
end

Economy.SUPPORT_TRUST = 0.6

-- Saving for Fused Hero: while the defense keeps up, yen goes only to the two Fusion
-- units (and farms). Returns the narrowed option list, or nil when everything may be bought.
Economy.FUSION_NEAR = 3

function Economy.fusionFocus(options, ctx, belongs, remaining)
    local focus, found = {
    }, false
    for _, option in ipairs(options) do
        if belongs(option) then
            found = true
            table.insert(focus, option)
        elseif option.farm then
            table.insert(focus, option)
        end
    end
    if not found then
        return nil, "nothing left to buy for the Fusion units"
    end
    if (ctx.attackers or 0) < 1 then
        return focus, "opening with a Fusion unit"
    end
    local cover = Utils.clamp(ctx.cover or 0.6, 0.1, 1)
    if ctx.leak then
        return nil, "an enemy got past your units"
    end
    if (ctx.pressure or 0) >= math.min(Config.dangerReach, cover * 0.9) then
        return nil, string.format("enemies reach %d%% of the road", math.floor((ctx.pressure or 0) * 100))
    end
    -- On the finish line (the rest of the pair costs about three waves of income) the forecast for
    -- later waves no longer stops the saving: only enemies actually getting far do.
    local budget = ctx.money or 0
    for index = 1, math.min(Economy.FUSION_NEAR, ctx.coming and # ctx.coming or 0) do
        budget = budget + (ctx.coming [index].reward or 0) + (ctx.farmNow or 0)
    end
    local near = remaining and remaining <= budget
    if near then
        return focus, "the pair is almost ready to fuse"
    end
    if ctx.coming and not Economy.keepsUp(ctx, focus, 0, 0, 0) then
        return nil, "the next waves need more damage than the Fusion units alone add"
    end
    return focus, "the defense holds"
end

-- ===== Farm order (2.23) =====
-- Which farm buy comes next is found by playing short buy orders forward wave by wave: up to FARM_STEPS
-- buys from the FARM_PICK fastest-paying farms, each bought as soon as the yen is there (saving for it
-- otherwise), with the yen each wave pays and what the farms bought so far earn; the farms left out
-- follow in payback order. An order is worth the yen it ends the horizon with, plus what its farms keep
-- earning for the waves after it, so it can differ from "the most yen right after this buy". The first buy
-- of the best order is made (or saved for); when no order beats buying nothing, no farm. This answers
-- both "buy the farm I can afford now or save for the better one" and "three small upgrades beat one
-- big one for the same yen", which picking the single fastest payback each time can get wrong.
Economy.FARM_PICK, Economy.FARM_STEPS, Economy.FARM_HORIZON = 6, 3, 12

-- A buy's name for ties: unit and level, never where the option sits in the list, so the same team in
-- another order buys the same (2.23).
function Economy.optKey(option)
    local entry = option.e or (option.c and option.c.e)
    return tostring(entry and entry.id or option.what or "") .. (option.place and "+" or ("^" .. tostring(option.c and option.c.lvl or option.level or "")))
end

-- Yen the i-th wave from now pays, without farms (the forecast for the next waves, then its last one).
function Economy.farmPay(ctx, i)
    local coming = ctx.coming
    local item = type(coming) == "table" and (coming [i] or coming [# coming]) or nil
    local reward = item and tonumber(item.reward)
    if reward then
        return math.max(0, reward)
    end
    return math.max(0, (tonumber(ctx.incomeRate) or 0) * (tonumber(ctx.waveSec) or 20) - (tonumber(ctx.farmNow) or 0))
end

-- farms: options that pass the payback rule. left: waves the farms can still earn for.
-- Returns the first buy of the best order, the yen it adds over buying no farm, and the order itself.
function Economy.farmPlan(farms, ctx, left)
    left = math.floor(tonumber(left) or 0)
    local horizon = math.min(Economy.FARM_HORIZON, left)
    if horizon < 1 or # farms == 0 then
        return nil
    end
    local pick = {
    }
    for _, option in ipairs(farms) do
        table.insert(pick, option)
    end
    local key = Economy.optKey
    table.sort(pick, function(a, b)
        if a.payback ~= b.payback then
            return a.payback < b.payback
        end
        if a.cost ~= b.cost then
            return a.cost < b.cost
        end
        return key(a) < key(b)
    end)
    while # pick > Economy.FARM_PICK do
        table.remove(pick)
    end
    local pays = {
    }
    for i = 1, horizon do
        pays [i] = Economy.farmPay(ctx, i)
    end
    local after = math.max(0, left - horizon)
    local farmNow = tonumber(ctx.farmNow) or 0
    -- An order is played out, then the farms it left out follow it, fastest payback first, so every
    -- order is judged with the same later buys (a short order would otherwise look worse only for
    -- stopping sooner). follow = false plays the order alone (the "no farm" baseline).
    local function value(order, used, follow)
        local seq = {
        }
        for _, option in ipairs(order) do
            table.insert(seq, option)
        end
        if follow then
            for _, option in ipairs(pick) do
                if not used [option] then
                    table.insert(seq, option)
                end
            end
        end
        local money, farm, k = tonumber(ctx.money) or 0, farmNow, 1
        for wave = 1, horizon do
            while seq [k] and seq [k].cost <= money do
                money, farm, k = money - seq [k].cost, farm + seq [k].gain, k + 1
            end
            money = money + pays [wave] + farm
        end
        return money + (farm - farmNow) * after
    end
    local order, used = {
    }, {
    }
    local base = value(order, used, false)
    local best, bestValue, bestOrder = nil, base, nil
    local function walk(depth)
        if depth > 0 then
            local v = value(order, used, true)
            if v > bestValue + 1e-6 then
                best, bestValue, bestOrder = order [1], v, table.clone(order)
            end
        end
        if depth >= Economy.FARM_STEPS then
            return
        end
        for _, option in ipairs(pick) do
            if not used [option] then
                used [option], order [depth + 1] = true, option
                walk(depth + 1)
                used [option], order [depth + 1] = nil, nil
            end
        end
    end
    walk(0)
    return best, bestValue - base, bestOrder
end

-- Buy order (2.25): stages of the chosen order go first while the defense holds. Inside a stage the usual
-- rules decide (a farm still has to pay back and leave the defense keeping up); a stage with nothing worth
-- buying passes to the next, and with the defense in trouble the order is skipped.
Economy.ORDERS = {
    "Smart",
    "Farms first",
    "Team first"
}
Economy.STAGES = {
    ["Farms first"] = {
        "farms",
        "team",
        "fused"
    },
    ["Team first"] = {
        "team",
        "farms",
        "fused"
    }
}
Economy.STAGE_WORDS = {
    farms = "farms first",
    team = "every unit down",
    fused = "Fused Hero"
}

function Economy.inStage(option, stage)
    if stage == "farms" then
        return option.farm == true
    elseif stage == "team" then
        return option.place == true and not option.farm and option.firstCopy == true
    elseif stage == "fused" then
        return option.fusionStep == true or option.fusedUp == true
    end
    return false
end

function Economy.ordered(options, ctx)
    local order = Economy.STAGES [Config.upgradeOrder]
    if not order or ctx.leak or (ctx.attackers or 0) == 0 then
        return Economy.decide(options, ctx)
    end
    local cover = Utils.clamp(ctx.cover or 0.6, 0.1, 1)
    if (ctx.pressure or 0) >= math.min(Config.dangerReach, cover * 0.9) or (ctx.piling and (ctx.enemies or 0) >= 18) then
        return Economy.decide(options, ctx)
    end
    -- The next waves checked against everything that can be bought (not just one stage): if the defense falls
    -- behind, the order waits and the usual rules buy damage.
    if ctx.coming and not Economy.keepsUp(ctx, options, 0, 0, 0) then
        return Economy.decide(options, ctx)
    end
    for _, stage in ipairs(order) do
        local subset = {
        }
        for _, option in ipairs(options) do
            if Economy.inStage(option, stage) then
                table.insert(subset, option)
            end
        end
        if # subset > 0 then
            local choice, why, waitText = Economy.decide(subset, ctx)
            if choice or waitText then
                local tag = string.format("%s: %s", tostring(Config.upgradeOrder), Economy.STAGE_WORDS [stage] or stage)
                return choice, why and (tag .. " · " .. why) or why, waitText and (tag .. " · " .. waitText) or waitText
            end
        end
    end
    return Economy.decide(options, ctx)
end

function Economy.decide(options, ctx)
    local cover = Utils.clamp(ctx.cover or 0.6, 0.1, 1)
    local clearLimit = math.max(Config.clearSec, 0.7 * (ctx.roadSec or 50) * cover)
    local slowClear = (ctx.clearSec or 0) > clearLimit
    ctx.piling = ctx.piling and slowClear
    local safe = ctx.attackers > 0 and ctx.pressure < math.min(Config.safeReach, cover * 0.75) and not ctx.piling and not slowClear
    local danger = ctx.pressure >= math.min(Config.dangerReach, cover * 0.9) or (ctx.piling and ctx.enemies >= 18)
    local bestFarm, bestDamage, bestDirect
    -- Waves a farm can still earn for: the match's own count, or in Infinite what past runs say (2.23).
    local farmLeft = tonumber(ctx.farmLeft) or ctx.left
    local farmList = {
    }
    for _, option in ipairs(options) do
        if option.farm then
            if Config.farmUnits and option.gain and option.gain > 0 then
                option.payback = option.cost / math.max(0.0001, option.gain)
                if farmLeft - 1 >= option.payback + Config.farmSpare then
                    table.insert(farmList, option)
                    if not bestFarm or option.payback < bestFarm.payback then
                        bestFarm = option
                    end
                end
            end
        else
            option.ratio = (tonumber(option.gain) or 0) / math.max(1, tonumber(option.cost) or 0)
            if not bestDamage or option.ratio > bestDamage.ratio or (option.ratio == bestDamage.ratio and Economy.optKey(option) < Economy.optKey(bestDamage)) then
                bestDamage = option
            end
            if not option.support and (not bestDirect or option.ratio > bestDirect.ratio or (option.ratio == bestDirect.ratio and Economy.optKey(option) < Economy.optKey(bestDirect))) then
                bestDirect = option
            end
        end
    end
    -- The farm to buy (or save for) next: the first of the best buy order, not just the fastest payback.
    local farmOrder
    if # farmList > 1 then
        local planned, planGain, order = Economy.farmPlan(farmList, ctx, farmLeft)
        bestFarm = planned
        if planned then
            farmOrder = {
                gain = planGain,
                order = order
            }
        end
    end
    if ctx.leak and ctx.attackers > 0 then
        local blocker, bestLeakUpgrade
        for _, option in ipairs(options) do
            local hitsAir = not ctx.airLeak or (option.e and Match.cardAir(option.e.id))
            if not option.farm and option.cost <= ctx.money then
                if option.place and hitsAir and not (option.e and Units.allyBuff(option.e.id)) and (not blocker or option.gain > blocker.gain) then
                    blocker = option
                elseif not option.place and (not bestLeakUpgrade or option.gain > bestLeakUpgrade.gain) then
                    bestLeakUpgrade = option
                end
            end
        end
        if blocker then
            return blocker, string.format("an enemy got past all your units (%d%% of the road): a unit in its way", math.floor(ctx.leak * 100))
        elseif bestLeakUpgrade then
            return bestLeakUpgrade, string.format("an enemy got past (%d%% of the road): emergency upgrade", math.floor(ctx.leak * 100))
        end
    end
    local farmNeeded = ctx.future < ctx.wantLeft * 1.1
    local farmKeepsUp, shortWave, shortCover, shortKind = true, nil, nil, nil
    if bestFarm then
        farmKeepsUp, shortWave, shortCover, shortKind = Economy.keepsUp(ctx, options, bestFarm.cost, 0, bestFarm.gain)
    end
    local behindOk, _, _, behindKind = true, nil, nil, nil
    if ctx.coming then
        behindOk, _, _, behindKind = Economy.keepsUp(ctx, options, 0, 0, 0)
    end
    local fallsBehind = ctx.coming and not behindOk
    local cheapFarm = false
    if Match.random and bestFarm and not danger and farmKeepsUp and ctx.attackers >= 2 and bestFarm.payback <= farmLeft / 3 then
        local farmCount = 0
        for _, unit in ipairs(Match.mine or {
        }) do
            if Units.isFarm(unit._stats.id.Value) then
                farmCount = farmCount + 1
            end
        end
        cheapFarm = not bestFarm.place or farmCount < 4
    end
    if fallsBehind and ctx.attackers > 0 then
        danger = true
    end
    -- A weak defense buys damage it can count on first: a buffer's gain is an estimate
    -- (who stands in its circle, how long the buff is up), so it must beat direct damage clearly.
    local buffLater = false
    if danger and bestDamage and bestDamage.support and bestDirect and bestDirect.ratio >= bestDamage.ratio * Economy.SUPPORT_TRUST then
        bestDamage, buffLater = bestDirect, true
    end
    local incomeRate = math.max(1, ctx.incomeRate or 20)
    local waveSec = ctx.waveSec or 20
    local function damageOver(option, after, horizon)
        local waitSec = math.max(0, (option.cost - ctx.money) / incomeRate)
        local dealt = option.gain * math.max(0, horizon - waitSec)
        if after then
            local moneyLeft = math.max(0, ctx.money - option.cost)
            local afterWaitSec = waitSec + math.max(0, (after.cost - moneyLeft) / incomeRate)
            dealt = dealt + after.gain * math.max(0, horizon - afterWaitSec)
        end
        return dealt
    end
    local choice, why
    if ctx.attackers == 0 and bestDamage then
        local horizon = 4 * waveSec
        local urgent = (ctx.enemies or 0) > 0 or (ctx.pressure or 0) > 0.12
        local bestWindowOpen, bestWindowDealt, bestOpen, bestOpenDealt
        for _, option in ipairs(options) do
            if option.place and not option.farm and not (option.e and Units.allyBuff(option.e.id)) then
                local waitT = math.max(0, (option.cost - ctx.money) / incomeRate)
                if not urgent or waitT <= waveSec * 0.9 then
                    local airMul = (ctx.airLeak and option.e and Match.cardAir(option.e.id)) and 2.5 or 1
                    local dealt = damageOver(option, nil, horizon) * airMul
                    if not bestWindowDealt or dealt > bestWindowDealt then
                        bestWindowOpen, bestWindowDealt = option, dealt
                    end
                end
                if option.cost <= ctx.money then
                    local airMul = (ctx.airLeak and option.e and Match.cardAir(option.e.id)) and 2.5 or 1
                    local dealt = damageOver(option, nil, horizon) * airMul
                    if not bestOpenDealt or dealt > bestOpenDealt then
                        bestOpen, bestOpenDealt = option, dealt
                    end
                end
            end
        end
        if urgent and bestOpen and (not bestWindowOpen or (bestWindowOpen.cost > ctx.money and (bestWindowOpen.cost - ctx.money) / incomeRate > 8)) then
            choice, why = bestOpen, "opening (urgent): deploying best affordable defender now"
        else
            choice, why = bestWindowOpen or bestOpen or bestDamage, "opening: the unit that does the most damage over the first waves"
        end
    elseif bestFarm and safe and farmNeeded and not danger and farmKeepsUp then
        choice = bestFarm
        why = string.format("farm pays back in %.1f waves (%d left) and the defense still keeps up with the next %d waves", bestFarm.payback, farmLeft, ctx.coming and # ctx.coming or 0)
        if farmOrder then
            why = why .. string.format(" · first of the best farm order (+¥%s by the end over buying no farm)", Utils.fmt(math.floor(farmOrder.gain)))
        end
    elseif cheapFarm then
        choice = bestFarm
        why = string.format("farm pays back in %.1f waves (%d left) and nothing is close to the base", bestFarm.payback, farmLeft)
    elseif bestDamage then
        choice = bestDamage
        if buffLater then
            why = "the defense is weak: direct damage first, the buffer after"
        elseif fallsBehind then
            why = behindKind == "air" and "the next waves bring more flying HP than your units that hit the air can kill: damage now" or "the next waves bring more HP than your units can kill: damage now"
        elseif danger then
            why = string.format("enemies reach %d%% of the road (your units cover %d%%): damage now", math.floor(ctx.pressure * 100), math.floor(cover * 100))
        elseif bestFarm and not farmKeepsUp then
            why = string.format("defense first: after that farm buy, wave +%d would only be %d%% covered%s", shortWave or 1, math.floor((shortCover or 0) * 100), shortKind == "air" and " (flying enemies, only units that hit the air count)" or "")
        elseif bestFarm and slowClear then
            why = string.format("defense first: killing what's alive takes %ds (farm only under %ds)", math.min(999, math.floor(ctx.clearSec)), math.floor(clearLimit))
        elseif bestFarm and ctx.piling then
            why = string.format("defense first: %d enemies piling up", ctx.enemies)
        elseif bestFarm and not safe then
            why = "defense first (enemies get too far to farm)"
        elseif bestFarm and not farmNeeded then
            why = "farm not needed: coming yen already covers every upgrade"
        else
            why = "most damage per yen"
        end
    end
    if not choice then
        return nil
    end
    if choice.cost > ctx.money then
        local instead
        if not choice.farm then
            local waitSaving = (choice.cost - ctx.money) / incomeRate
            local horizon = ((ctx.pressure or 0) >= 0.95 and 0.5 or danger and 1.5 or (waitSaving > 25 and 3 or 6)) * waveSec
            local insteadDealt
            for _, option in ipairs(options) do
                if not option.farm and option ~= choice and option.cost <= ctx.money then
                    local withOption = damageOver(option, choice, horizon)
                    local withChoice = damageOver(choice, option, horizon)
                    if withOption > withChoice and (not insteadDealt or withOption > insteadDealt) then
                        instead, insteadDealt = option, withOption
                    end
                end
            end
        end
        if not instead then
            return nil, nil, string.format("saving ¥%s for: %s (≈%ds at ¥%d/s) — %s", Utils.fmt(choice.cost), choice.what or "?", math.ceil((choice.cost - ctx.money) / incomeRate), math.floor(incomeRate), why)
        end
        choice, why = instead, why .. " (worth buying while saving)"
    end
    return choice, why
end
Simulator.DT = 1
Simulator.BINS = 20
Simulator.PRIOR = {
    waveSec = 20,
    walk = 0.0054,
    spawnGap = 1,
    baseHp = 100,
    baseRel = 0.3,
    start = 600,
    eff = 0.7,
    waveTimer = 60,
    skipDelay = 5,
    voteAt = 30,
    voteBase = 2,
    votePer = 1.9
}

function Simulator.voteSec(arg1, count)
    local value = arg1.voteWave and tonumber(arg1.voteWave [tostring(count)])
    if value then
        return value
    end
    if count <= 2 then
        return 5
    elseif count <= 5 then
        return 10
    end
    return arg1.voteAt
end
Simulator.LAND_CAP = 1.3
-- An attacker whose damage type an equipped buffer raises goes down a little sooner.
Simulator.BUFF_MATCH = 1.15
-- Short modes: with the opening defense down, the first copy of a matching buffer is worth this much more.
Simulator.BUFF_EARLY = 1.3

function Simulator.autoskip()
    local ok, res = pcall(function()
        return LocalPlayer._settings.autoskip_waves.Value
    end)
    if ok and type(res) == "boolean" then
        return res
    end
    return true
end

function Simulator.calKey(key, ld, challenge, rotation)
    if key == "ch" then
        return string.format("ch@%q:%q", tostring(ld.id), tostring(challenge or ld._challenge))
    elseif key == "dc" then
        return "dc@" .. tostring(rotation or ld._challenge_uuid or "unknown")
    end
    return key
end

function Simulator.cal(calKey)
    local value = Brain.simCal [calKey]
    if not value then
        value = {
        }
        Brain.simCal [calKey] = value
    end
    return value
end

-- How much of the model's damage really lands, in three levels: all modes → this map → this mode.
-- Each level leans on the one above until it has its own runs (3 runs weigh as much as the level
-- above), so a new mode on a known map starts from that map, not from the average of all maps.
-- Per unit there is one more correction (Units.nudge, from each unit's share of the real damage).
Simulator.EFF_PRIOR_RUNS = 3

function Simulator.effFor(arg1, map)
    local count, count2, mapSum, mapN = 0, 0, 0, 0
    local mapName = map and tostring(map):match("^(.-)~%d+$") or (map and tostring(map))
    for _, value in pairs(Brain.simCal) do
        local eff, n = tonumber(type(value) == "table" and value.eff), type(value) == "table" and (tonumber(type(value.nf) == "table" and value.nf.eff) or tonumber(value.n)) or 0
        if eff and n > 0 then
            count = count + eff * n
            count2 = count2 + n
            local ld = type(value.ld) == "table" and value.ld
            if mapName and ld and tostring(ld.map) == mapName and value ~= arg1 then
                mapSum, mapN = mapSum + eff * n, mapN + n
            end
        end
    end
    local ratio = count2 > 0 and count / count2 or Simulator.PRIOR.eff
    local prior = Simulator.EFF_PRIOR_RUNS
    if mapN > 0 then
        ratio = (mapSum + ratio * prior) / (mapN + prior)
    end
    local eff, n = tonumber(arg1 and arg1.eff), tonumber(arg1 and type(arg1.nf) == "table" and arg1.nf.eff) or tonumber(arg1 and arg1.n) or 0
    if not eff then
        return ratio
    end
    return (eff * n + ratio * prior) / (n + prior)
end
Simulator.LD_FIELDS = {
    "id",
    "map",
    "waves",
    "world",
    "story_world_rank",
    "story_level_rank",
    "_gamemode",
    "_OVERRIDE_GAMEMODE",
    "_difficulty",
    "_challenge",
    "_challenge_uuid",
    "infinite",
    "_use_max",
    "_override_infinite_bound_waves",
    "_override_infinite_boss_interval",
    "_override_multiplayer_diff_scale",
    "_no_multiplayer_scale",
    "_raid_multiplayer_scale",
    "portal_group",
    "_infinite_bound_level",
    "_lobby_difficulty_scale",
    "_location_name",
    "name",
    "boss",
    "_world_diff_scale_multiplier",
    "_portal_lanes"
}

function Simulator.unbound(ld)
    return not tonumber(ld._override_infinite_bound_waves) and not ld._infinite_bound_level
end

function Simulator.boundEnd(ld, itemCount, calKey)
    if not (ld and ld._infinite_bound_level) or tonumber(ld._override_infinite_bound_waves) then
        return nil
    end
    local value = calKey and Brain.simCal [calKey]
    if type(value) == "table" and (tonumber(value.lastWave) or 0) > 15 then
        return nil
    end
    return (itemCount or 0) > 0 and math.min(itemCount, 15) or 15
end

function Simulator.slim(arg1)
    local list = {
    }
    for _, ldField in ipairs(Simulator.LD_FIELDS) do
        local value = arg1 [ldField]
        if type(value) ~= "table" and type(value) ~= "function" then
            list [ldField] = value
        end
    end
    if type(arg1._override_waves) == "table" then
        list._override_waves = {
            infinite = arg1._override_waves.infinite,
            template = arg1._override_waves.template
        }
    end
