        local value2, count2 = math.floor(value + 0.5), 0
        for i, item in ipairs(list2) do
            local ratio = (i == # list2) and math.max(0, value2 - count2) or math.floor(value2 * item.c / count + 0.5)
            for i = 1, ratio do
