                    for _, tower in ipairs(list3) do
                        if tower.e == entry and (not lead or tower.lvl > lead.lvl) then lead = tower end
                    end
                    if option.place then return lead == nil end
                    return option.c == lead and lead.lvl < fusion.upgrade
                end, pathLeft)
                if focus then
                    options = focus
                    stats.saved = stats.saved + 1
                else
                    stats.paused = stats.paused or {
                    }
                    stats.paused [focusWhy] = (stats.paused [focusWhy] or 0) + 1
                end
            end
            local decide = Economy.ordered(options, ctx)
            if not decide or decide.cost > start then
                break
            end
            start = start - decide.cost
            list9 [count4] = (list9 [count4] or 0) + decide.cost
            local boughtFor = decide.e or (decide.c and decide.c.e)
            if boughtFor and boughtFor.farm then
                stats.farmSpent = stats.farmSpent + decide.cost
            end
            if decide.place then
                stats.placedWave [decide.e.id] = stats.placedWave [decide.e.id] or count4
                local info = {
                    e = decide.e,
                    lvl = 0,
                    spent = decide.cost
                }
                for _, item in ipairs(list3) do
                    if item.e == decide.e then
                        info.later = true
                        break
                    end
                end
                if flag42 and Simulator.holds(decide.e.id) then
                    info.ctlN = 1
                    for _, item in ipairs(list3) do
                        if item.ctlN then
                            info.ctlN = info.ctlN + 1
                        end
                    end
                end
                if not flag42 and not decide.e.farm and ratio and count2 > ratio then
                    info.lo = math.floor(count2 * Simulator.BINS) + 2
                end
                helper5(info)
                table.insert(list3, info)
                if Units.BLESS.by [info.e.id] then
                    count11 = count11 + 1
                    for _, item in ipairs(list3) do
                        if Units.SUMMONER [item.e.id] then
                            helper5(item)
                        end
                    end
                end
                if arg3.buys then
                    table.insert(arg3.buys, string.format("%.0fs w%d place %s", count3, count4, Units.name(info.e.id)))
                end
            else
                decide.c.lvl = decide.c.lvl + 1
                decide.c.spent = (decide.c.spent or 0) + decide.cost
                helper5(decide.c)
                if arg3.buys then
                    table.insert(arg3.buys, string.format("%.0fs w%d up %s L%d", count3, count4, Units.name(decide.c.e.id), decide.c.lvl))
                end
            end
            fuseReadyParents()
            helper8()
            count7 = 0
            for _, item in ipairs(list3) do
                count7 = count7 + helper9(item)
            end
        end
        if arg3.trace then
            arg3.trace(count3, count4, start, list3, list2, baseHp)
        end
        count3 = count3 + dt
        count8 = count8 + 1
        if count8 % 120 == 0 then
            task.wait()
        end
    end
    return finish({
        won = false,
        wave = count4,
        t = count3,
        aliveAt = list5,
        dpsAt = list8,
        spentAt = list9,
        money = start,
        timeout = true,
        tk = count
    })
end
Simulator.INF_CAP = 80

function Simulator.evaluate(applyFx, teamFrom, extra)
    local function at(hpMul)
        local opts = {
            hpMul = hpMul
        }
        for key, option in pairs(extra or {
        }) do
            opts [key] = option
        end
        return opts
    end
    local simResult = Simulator.run(applyFx, teamFrom, at(1))
    local info = {
        won = simResult.won,
        wave = simResult.wave,
        minutes = simResult.t / 60,
        seconds = simResult.t,
        aliveAt = simResult.aliveAt,
        fusionWave = simResult.fusionWave,
        total = applyFx.total,
        at = os.time()
    }
    if applyFx.infinite and Simulator.unbound(applyFx.ld) then
        info.p = 1
        info.margin = simResult.won and string.format("lasts past wave %d", applyFx.total) or string.format("lasts to wave %d (%.0f min)", simResult.wave, simResult.t / 60)
    elseif simResult.won then
        local value = Simulator.run(applyFx, teamFrom, at(1.3))
        info.p = value.won and 0.92 or 0.7
        info.margin = value.won and "wins with room to spare" or "wins, but only just"
    else
        local value = Simulator.run(applyFx, teamFrom, at(0.75))
        info.p = value.won and 0.25 or 0.05
        info.margin = value.won and string.format("loses at wave %d (would win vs 25%% weaker enemies)", simResult.wave) or string.format("loses at wave %d of %d", simResult.wave, applyFx.total)
        if not value.won then
            local value = Simulator.run(applyFx, teamFrom, at(0.25))
            if not value.won then
                info.p, info.hopeless = 0.005, true
                info.margin = string.format("loses at wave %d of %d, even against enemies at a quarter of their health", simResult.wave, applyFx.total)
            end
        end
    end
    return info
end

function Simulator.trust(arg1, teamFrom)
    local cal = arg1.cal or {
    }
    if type(cal.alive) ~= "table" or not cal.teamProfile then
        return nil
    end
    local units = {}
    for _, entry in ipairs(teamFrom) do table.insert(units, entry.u) end
    if cal.teamProfile ~= Simulator.profileSig(units) then
        return nil
    end
    if arg1.key == "ch" and not cal.aliveLvl then
        return nil
    end
    if cal.aliveLvl and arg1.ld and arg1.ld.id and cal.aliveLvl ~= tostring(arg1.ld.id) .. (Hunt.is(arg1.ld.id) and ("@" .. tostring(arg1.ld.map)) or "") then
        return nil
    end
    local value = Simulator.run(arg1, teamFrom, {
        hpMul = 1
    })
    local count, count2, count3 = 0, 0, 0
    for i = 3, math.min(value.wave, tonumber(cal.lastWave) or 99) do
        local value2 = tonumber(cal.alive [tostring(i)])
        local value3 = value.aliveAt [i]
        if value2 and value3 and (value2 > 0 or value3 > 0) then
            count = count + value2
            count2 = count2 + value3
            count3 = count3 + 1
        end
    end
    if count3 < 2 then
        return nil
    end
    local ratio = count2 > 0 and count / count2 or 1000000
    return {
        ratio = ratio,
        ok = ratio >= 0.75 and ratio <= 1.33,
        waves = count3
    }
end
Simulator.GROWN_LEVEL, Simulator.GROWN_MIN = 50, 6

function Simulator.grownKinds()
    local session = Core.session()
    local list, count = {
    }, 0
    for _, ownedUnit in pairs(session.profile_data.collection.owned_units) do
        local unitId = ownedUnit.unit_id
        if not list [unitId] and Core.Units [unitId] and not Units.isFarm(unitId) and Units.rows(unitId) and not Units.hidden(unitId) then
            local ok, res = pcall(Core.USC.calculate_level, unitId, tonumber(ownedUnit.xp) or 0)
            if ok and (tonumber(res) or 0) >= Simulator.GROWN_LEVEL then
                list [unitId] = true
                count = count + 1
            end
        end
    end
    return count
end

function Simulator.pool(mod, level)
    local session = Core.session()
    local list, list2 = {
    }, {
    }
    local flag = Simulator.grownKinds() >= Simulator.GROWN_MIN
    local fusionParents = {}
    local needAir = level and ((level.flyChance or 0) > 0 or level.mapFly)
    local needShield = level and (level.shield or 0) > 0
    local needRegen = level and (level.regen or 0) > 0
    for _, ownedUnit in pairs(session.profile_data.collection.owned_units) do
        local unitObj = session.collection:get_unit_by_uuid(ownedUnit.uuid) or ownedUnit
        local ok, res = pcall(Core.USC.calculate_level, unitObj.unit_id, tonumber(unitObj.xp) or 0)
        local lvl = ok and (tonumber(res) or 0) or 0
        local isUtility = Units.allyBuff(unitObj.unit_id) ~= nil or Units.idol(unitObj.unit_id)
            or (needRegen and Units.bleeds(unitObj.unit_id) ~= nil)
            or (needAir and Units.airFrom(unitObj.unit_id) == 0)
            or Units.effects(unitObj.unit_id).useful
        if not isUtility and Units.rows(unitObj.unit_id) and Units.rows(unitObj.unit_id)[0] then
            local r0 = Units.rows(unitObj.unit_id)[0]
            local ai0 = r0.atk and Units.attackInfo(r0.atk, r0.range)
            if ai0 and ((ai0.stun or 0) >= 1 or (ai0.slowTime or 0) >= 2) then
                isUtility = true
            end
        end
        local isFarm = Units.isFarm(unitObj.unit_id) or not flag or lvl >= Simulator.GROWN_LEVEL or isUtility
        local fusionParent = Units.FUSION.attacks[unitObj.unit_id]
        if Core.Units [unitObj.unit_id] and Units.rows(unitObj.unit_id) and not Units.hidden(unitObj.unit_id) and (isFarm or fusionParent) then
            local isFarm2 = Units.isFarm(unitObj.unit_id)
            local ok, res = pcall(isFarm2 and function()
                return Units.farm(unitObj, Units.rows(unitObj.unit_id).max)
            end or Units.score, unitObj, mod)
            res = (ok and res or 0) * (isFarm2 and 1 or Units.skinMul(unitObj, level and level.skinSet))
            if not isFarm2 then
                if needAir and Units.airFrom(unitObj.unit_id) == 0 then res = res * 1.25 end
                if needRegen and Units.bleeds(unitObj.unit_id) then res = res * 1.25 end
                if needShield and Units.rows(unitObj.unit_id)[0] and Units.rows(unitObj.unit_id)[0].atk then
                    local ai0 = Units.attackInfo(Units.rows(unitObj.unit_id)[0].atk, Units.rows(unitObj.unit_id)[0].range)
                    if ai0.breakShields or (ai0.hits or 1) >= 3 then res = res * 1.2 end
                end
            end
            local list22 = isFarm2 and list2 or list
            if fusionParent and (not fusionParents[unitObj.unit_id] or res > fusionParents[unitObj.unit_id].sc) then
                fusionParents[unitObj.unit_id] = { u = unitObj, sc = res }
            end
            if isFarm and (not list22 [unitObj.unit_id] or res > list22 [unitObj.unit_id].sc) then
                list22 [unitObj.unit_id] = { u = unitObj, sc = res }
            end
        end
    end
    local list3, list4 = {
    }, {
    }
    for _, item in pairs(list) do
        table.insert(list3, item)
    end
    for _, item in pairs(list2) do
        table.insert(list4, item)
    end
    table.sort(list3, function(arg1, arg2)
        return arg1.sc > arg2.sc
    end)
    table.sort(list4, function(arg1, arg2)
        return arg1.sc > arg2.sc
    end)
    local list = {
    }
    for i = 1, math.min(10, # list3) do
        table.insert(list, list3 [i].u)
    end
    local list2, list5 = {
    }, {
    }
    for i = 11, # list3 do
        local rows = Units.rows(list3 [i].u.unit_id)
        for i2 = 0, rows.max do
            if rows [i2] and rows [i2].atk and Units.attackInfo(rows [i2].atk, rows [i2].range).dot > 0 then
                table.insert(i2 == 0 and list2 or list5, list3 [i].u)
                break
            end
        end
    end
    for i = 1, math.min(4, # list2) do
        table.insert(list, list2 [i])
    end
    for i = 1, math.min(2, # list5) do
        table.insert(list, list5 [i])
    end
    for i = 1, math.min(3, # list4) do
        table.insert(list, list4 [i].u)
    end
    local list2 = {
    }
    for i = 11, # list3 do
        local row = Units.rows(list3 [i].u.unit_id) [0]
        local attackInfo = row and row.atk and Units.attackInfo(row.atk, row.range)
        if attackInfo and (attackInfo.slowTime > 0 or attackInfo.stun > 0) then
            table.insert(list2, list3 [i].u)
        end
    end
    for i = 1, math.min(3, # list2) do
        table.insert(list, list2 [i])
    end
    local bleedCount = 0
    for i = 11, # list3 do
        local unitId = list3 [i].u.unit_id
        if Units.allyBuff(unitId) or Units.BLESS.by [unitId] or Units.GALE [unitId] or Units.idol(unitId) then
            table.insert(list, list3 [i].u)
        elseif needRegen and bleedCount < 3 and Units.bleeds(unitId) then
            bleedCount = bleedCount + 1
            table.insert(list, list3 [i].u)
        end
    end
    -- A support is not dropped for low personal DPS: the three strongest confirmed effects
    -- outside the top ten (control, enemy amplification, ally buffs from an ability) join the pool.
    do
        local helpful = {
        }
        for i = 11, # list3 do
            local effects = Units.effects(list3 [i].u.unit_id)
            if effects.useful then
                table.insert(helpful, {
                    u = list3 [i].u,
                    v = effects.score
                })
            end
        end
        table.sort(helpful, function(arg1, arg2)
            return arg1.v > arg2.v
        end)
        for i = 1, math.min(3, # helpful) do
            table.insert(list, helpful [i].u)
        end
    end
    if level and ((level.flyChance or 0) > 0 or level.mapFly or (level.shield or 0) > 0) then
        local list2, list4 = {
        }, {
        }
        for i = 11, # list3 do
            local u = list3 [i].u
            local row = Units.rows(u.unit_id) [0]
            if Units.airFrom(u.unit_id) == 0 then
                table.insert(list2, u)
            end
            local cd, cost = tonumber(row and row.cd) or 0, tonumber((Core.Units [u.unit_id] or {
            }).cost) or 0
            if cd > 0 and cost > 0 and Units.range(u, 0) >= 15 then
                local attackInfo = Units.attackInfo(row.atk, row.range)
                table.insert(list4, {
                    u = u,
                    v = attackInfo.n * attackInfo.hits / cd / cost * math.min(6,
                    Units.cap(u))
                })
            end
        end
        table.sort(list4, function(arg1, arg2)
            return arg1.v > arg2.v
        end)
        for i = 1, math.min(4, # list2) do
            table.insert(list, list2 [i])
        end
        for i = 1, math.min(6, # list4) do
            table.insert(list, list4 [i].u)
        end
    end
    -- Tier list first: the units real runs rate highest lead the search; tier C stops taking its time
    -- when the collection is big (it stays in the reserve the search looks at last).
    local ranks = level and level.key and Simulator.tierRanks(level.key) or {
    }
    if # ranks > 0 then
        local byId = {
        }
        for _, item in ipairs(list3) do
            byId [item.u.unit_id] = item.u
        end
        local front, cut, inFront = {
        }, {
        }, {
        }
        for _, item in ipairs(ranks) do
            if item.fusion then
                if item.tier == "S" or item.tier == "A" then
                    for _, parent in ipairs(Units.FUSION.parents) do
                        local entry = fusionParents [parent]
                        if entry and not inFront [entry.u] then
                            table.insert(front, entry.u)
                            inFront [entry.u] = true
                        end
                    end
                end
            elseif item.tier == "C" then
                cut [item.id] = true
            elseif byId [item.id] and # front < Simulator.TIER.POOL then
                table.insert(front, byId [item.id])
                inFront [byId [item.id]] = true
            end
        end
        local big = # list3 > 10
        for _, unit in ipairs(list) do
            -- farms and buffers are judged by whole lineups (farm rule, buffer types), never cut here
            local plain = not Units.isFarm(unit.unit_id) and not Units.allyBuff(unit.unit_id) and not fusionParents [unit.unit_id]
            if not inFront [unit] and not (big and plain and cut [unit.unit_id]) then
                table.insert(front, unit)
            end
        end
        list = front
    end
    local list2, list4 = {
    }, {
    }
    for _, item in ipairs(list) do
        if not list2 [item] then
            list2 [item] = true
            table.insert(list4, item)
        end
    end
    list4.rest = {
    }
    list4.fusionParents = fusionParents
    for _, item in ipairs(list3) do
        if not list2 [item.u] then
            table.insert(list4.rest, item.u)
        end
    end
    return list4
end

-- ===== Tier list: what each of your units is worth here, from real simulator runs =====
-- The team search has a time budget, and with a big collection it can only look closely at about ten
-- units, picked by a formula (damage × range × copies at max level) that misses cheap starters, area
-- damage on this map's road, and so on. The tier list measures every unit you own in the simulator,
-- a few per plan, and remembers it per mode: the strongest go to the front of the search, the weakest
-- (tier C) stop taking its time. The measuring adds up to a quarter to the plan's time; the search keeps
-- its own budget. Farms and buffers get no tier: what they are worth shows only in a whole lineup
-- (payback, matching damage types), which the search compares anyway. How a unit is measured: your equipped team without one attacker
-- (the weakest) is the base; the unit joins it; the gain in the simulator's score against enemies at
-- your team's breaking point is its value. A unit of your team is measured the same way, with itself
-- taken out to make the base.
Simulator.TIER = {
    FUSION_KEY = "fusion:pair",
    SHARE = 0.25,
    MAX_AGE = 3 * 86400,
    POOL = 6
}

function Simulator.tierBook(key, create)
    if type(Brain.tiers) ~= "table" then
        Brain.tiers = {
        }
    end
    local book = Brain.tiers [key]
    if type(book) ~= "table" then
        if not create then
            return nil
        end
        book = {
            units = {
            }
        }
        Brain.tiers [key] = book
    end
    if type(book.units) ~= "table" then
        book.units = {
        }
    end
    return book
end

function Simulator.tierUpdate(info, ref, pool, budget)
    if not (info and info.key and ref and # ref > 0) then
        return 0
    end
    local started = Utils.now()
    local book = Simulator.tierBook(info.key, true)
    local refSig = Simulator.profileSig(ref)
    local cliff = Simulator.cliff(info, Simulator.teamFrom(ref, info.map))
    local function score(team, extra)
        local entries = Simulator.teamFrom(team, info.map)
        local function at(mul)
            local opts = {
                hpMul = mul
            }
            for key, value in pairs(extra or {
            }) do
                opts [key] = value
            end
            return Simulator.objective(Simulator.run(info, entries, opts))
        end
        return (at(cliff) + at(cliff * 0.92)) / 2
    end
    local weakest, low
    for index, unit in ipairs(ref) do
        if not Units.isFarm(unit.unit_id) and not Units.allyBuff(unit.unit_id) then
            local ok, value = pcall(Units.score, unit, info.mod)
            value = ok and value or 0
            if not low or value < low then
                weakest, low = index, value
            end
        end
    end
    weakest = weakest or # ref
    local bases, members = {
    }, {
    }
    for index, unit in ipairs(ref) do
        members [unit.unit_id] = index
    end
    local function base(index)
        if not bases [index] then
            local team = table.clone(ref)
            table.remove(team, index)
            bases [index] = {
                team = team,
                score = score(team)
            }
        end
        return bases [index]
    end
    -- Never measured first, and among those the reserve first: the search looks closely at its priority
    -- units anyway, the reserve is where a unit the formula overlooked hides. Then the ones measured
    -- against another team or long ago.
    local cands, seen = {
    }, {
    }
    for _, list in ipairs({
        pool and pool.rest or {
        },
        pool or {
        },
        ref
    }) do
        for _, unit in ipairs(list) do
            local plain = not Units.isFarm(unit.unit_id) and not Units.allyBuff(unit.unit_id)
            if plain and not seen [unit.unit_id] and Units.rows(unit.unit_id) then
                seen [unit.unit_id] = true
                table.insert(cands, unit)
            end
        end
    end
    local now, order = os.time(), {
    }
    for index, unit in ipairs(cands) do
        local rec = book.units [unit.unit_id]
        local known = type(rec) == "table" and tonumber(rec.v) ~= nil
        if not (known and rec.ref == refSig and now - (tonumber(rec.at) or 0) < Simulator.TIER.MAX_AGE) then
            table.insert(order, {
                unit = unit,
                known = known and 1 or 0,
                at = known and tonumber(rec.at) or 0,
                index = index
            })
        end
    end
    table.sort(order, function(a, b)
        if a.known ~= b.known then
            return a.known < b.known
        end
        if a.at ~= b.at then
            return a.at < b.at
        end
        return a.index < b.index
    end)
    local measured = 0
    for _, item in ipairs(order) do
        if measured > 0 and Utils.now() - started > budget then
            break
        end
        local unit = item.unit
        local from = base(members [unit.unit_id] or weakest)
        local team = table.clone(from.team)
        table.insert(team, unit)
        book.units [unit.unit_id] = {
            v = score(team) - from.score,
            ref = refSig,
            at = now,
            name = Units.name(unit.unit_id)
        }
        measured = measured + 1
    end
    -- Fused Hero is not a unit you own: Carrot and Vego fuse into it in a match. Alone each of them is
    -- worth little, so the pair is measured together, in place of the two weakest attackers, with the
    -- regular buying and with yen saved for the pair; the better of the two is its value.
    local parents = pool and pool.fusionParents
    local first, second = Units.FUSION.parents [1], Units.FUSION.parents [2]
    local fusionKey = Simulator.TIER.FUSION_KEY
    local rec = book.units [fusionKey]
    local stale = not (type(rec) == "table" and rec.ref == refSig and now - (tonumber(rec.at) or 0) < Simulator.TIER.MAX_AGE)
    if stale and Config.actives ~= false and parents and parents [first] and parents [second] and (measured == 0 or Utils.now() - started <= budget * 1.2) then
        local team, out = table.clone(ref), {
        }
        for index = # team, 1, - 1 do
            local id = team [index].unit_id
            if id == first or id == second then
                table.remove(team, index)
            end
        end
        while # team > 4 do
            local slot, lowest
            for index, unit in ipairs(team) do
                if not Units.isFarm(unit.unit_id) and not Units.allyBuff(unit.unit_id) then
                    local ok, value = pcall(Units.score, unit, info.mod)
                    value = ok and value or 0
                    if not lowest or value < lowest then
                        slot, lowest = index, value
                    end
                end
            end
            table.insert(out, table.remove(team, slot or # team))
        end
        local baseScore = score(team)
        table.insert(team, parents [first].u)
        table.insert(team, parents [second].u)
        local value = math.max(score(team), score(team, {
            fusionSave = true
        })) - baseScore
        book.units [fusionKey] = {
            v = value,
            ref = refSig,
            at = now,
            name = string.format("%s (%s + %s)", Units.name(Units.FUSION.hero), Units.name(first), Units.name(second)),
            fusion = true
        }
        measured = measured + 1
    end
    book.at, book.cliff = now, cliff
    return measured, # order - measured
end

-- Measured units, best first, with their tier: S the top 15%, A to 40%, B to 70%, C the rest.
function Simulator.tierRanks(key)
    local book = key and Simulator.tierBook(key)
    local list = {
    }
    for id, rec in pairs(book and book.units or {
    }) do
        local fusion = type(rec) == "table" and rec.fusion
        if type(rec) == "table" and tonumber(rec.v) and (fusion or (not Units.isFarm(id) and not Units.allyBuff(id))) then
            local learned = Brain.learn and Brain.learn [id] and (tonumber(Brain.learn [id].n) or 0) >= 3
            local ok, effects = pcall(Units.effects, id)
            local hidden = not fusion and not learned and ok and type(effects) == "table" and (tonumber(effects.passives) or 0) > 0
            table.insert(list, {
                id = id,
                v = tonumber(rec.v),
                name = tostring(rec.name or id) .. (hidden and "*" or ""),
                fusion = fusion,
                hidden = hidden
            })
        end
    end
    table.sort(list, function(a, b)
        if a.v ~= b.v then
            return a.v > b.v
        end
        return tostring(a.id) < tostring(b.id)
    end)
    for index, item in ipairs(list) do
        local share = (index - 1) / math.max(1, # list)
        item.tier = (index == 1 or share < 0.15) and "S" or share < 0.4 and "A" or share < 0.7 and "B" or "C"
    end
    return list
end

function Simulator.tierText(key, oneLine)
    local list = Simulator.tierRanks(key)
    if # list == 0 then
        return nil
    end
    local groups, hidden = {
    }, false
    for _, item in ipairs(list) do
        groups [item.tier] = groups [item.tier] or {
        }
        table.insert(groups [item.tier], item.name)
        hidden = hidden or item.hidden
    end
    local parts = {
    }
    for _, tier in ipairs({
        "S",
        "A",
        "B",
        "C"
    }) do
        if groups [tier] then
            table.insert(parts, tier .. ": " .. table.concat(groups [tier], ", "))
        end
    end
    if hidden then
        table.insert(parts, "* passives the simulator does not model: corrected from 3 real runs with the unit")
    end
    return table.concat(parts, oneLine and " · " or "\n")
end

function Simulator.objective(value)
    return (value.won and 1000 or 0) + value.wave * 10 - (value.won and value.t / 60 or ((value.left or 1) * 9 - math.min(9, value.t / 60)))
end
Simulator.LADDER = {
    1,
    1.3,
    1.7,
    2.2,
    3,
    4,
    6,
    8,
    12,
    16,
    24
}

-- Binary search for the stress threshold over the monotonic Simulator.LADDER
function Simulator.cliff(arg1, teamFrom, arg3)
    local ladder = Simulator.LADDER
    local low, high = 1, #ladder
    local firstLossIdx, firstLossRes = nil, nil
    local lastWinRes = nil
    while low <= high do
        local mid = math.floor((low + high) / 2)
        local res = Simulator.run(arg1, teamFrom, {
            hpMul = ladder[mid],
            layout = arg3
        })
        if not res.won then
            firstLossIdx = mid
            firstLossRes = res
            high = mid - 1
        else
            lastWinRes = res
            low = mid + 1
        end
    end
    if firstLossIdx then
        return ladder[firstLossIdx], firstLossRes
    else
        return ladder[#ladder], lastWinRes
    end
end

function Simulator.exam(level, current, extra)
    local teamFrom, count, count2 = Simulator.teamFrom(current, level.map), 0, 0
    for _, value in ipairs(Simulator.LADDER) do
        local count3, count4 = 0, 0
        for _, value2 in ipairs({
            0.92,
            1,
            1.08
        }) do
            local opts = {
                hpMul = value * value2
            }
            for key, option in pairs(extra or {
            }) do
                opts [key] = option
            end
            local simResult = Simulator.run(level, teamFrom, opts)
            if simResult.won then
                count3 = count3 + 1
            end
            count4 = count4 + simResult.wave
        end
        count, count2 = count + count3, count4 / 3
        task.wait()
        if count3 == 0 then
            break
        end
    end
    return count, count2
end
Simulator.ZONE_CLOSE, Simulator.ZONE_GAIN = 1.3, 20

function Simulator.zoneKey(arg1)
    return tostring(arg1.key) .. ":" .. tostring(arg1.map)
end

function Simulator.zoneChoice(arg1, arg2, arg3, arg4)
    if Config.killZone == false or arg1.zone or (arg1.infinite and Simulator.unbound(arg1.ld)) then
        return false
    end
    local value = Brain.zoneRec [Simulator.zoneKey(arg1)]
    local value2 = value and (value.style == "box" or (value.style == nil and value.zone == true))
    if value and value.won then
        return value2 == true, value2 and "the kill box won here last time" or nil
    end
    if value and value2 then
        return false, "the kill box lost here last time"
    end
    local mode = Brain.modes [arg1.key]
    local streak = mode and tonumber(mode.streak) or 0
    if not value and mode and (tonumber(mode.wins) or 0) > 0 and streak == 0 and arg1.key ~= "ch" and arg1.key ~= "dc" then
        return false
    end
    local value2 = value ~= nil or streak > 0
    local value = arg4 and arg3 <= 1 or (not arg4 and arg3 <= Simulator.ZONE_CLOSE)
    if not (value2 or value) then
        return false
    end
    local arg12 = table.clone(arg1)
    arg12.zone = true
    local function helper(arg1)
        local count = 0
        for _, value in ipairs({
            0.92,
            1,
            1.08
        }) do
            count = count + Simulator.objective(Simulator.run(arg1, arg2, {
                hpMul = arg3 * value
            }))
        end
        return count / 3
    end
    local value3 = helper(arg12) - helper(arg1)
    if value2 and value3 > - Simulator.ZONE_GAIN then
        return true, "spread-out units lost here last time", value3
    end
    if value and value3 > Simulator.ZONE_GAIN then
        return true, string.format("the simulator says your team is close to losing here (enemies ×%.1f), and it plays better stacked", arg3), value3
    end
    return false, nil, value3
end

function Simulator.strength(applyFx, arg2)
    local teamFrom, count, count2, count3, count4 = Simulator.teamFrom(arg2, applyFx.map), 0, 0, 0, 0
    for _, value in ipairs(Simulator.LADDER) do
        local count5, count6 = 0, 0
        for _, value2 in ipairs({
            0.92,
            1,
            1.08
        }) do
            local simResult = Simulator.run(applyFx, teamFrom, {
                hpMul = value * value2
            })
            if simResult.won then
                count5 = count5 + 1
            end
            count6 = count6 + simResult.wave
        end
        count, count4 = count + count5, count6 / 3
        if value == 1 then
            count2, count3 = count5, count6 / 3
        end
        task.wait()
        if count5 == 0 then
            break
        end
    end
    return count, count2, count3, count4
end

Simulator.SHORT_WAVES = 20
-- Farming is judged per hour. When two lineups both clear with room to spare (they beat enemies with
-- ×SAFE_MUL HP in 2 of 3 tries), the one that finishes sooner gives more runs, so more rewards, an hour.
-- Endless modes keep the old rule: the team that lasts longer earns more there.
Simulator.SAFE_MUL, Simulator.FASTER = 1.3, 0.03
-- Room to spare is checked against three different ways the model can be wrong, not only thicker
-- enemies: the team must also win when its real damage is 15% under the model's and when enemies
-- walk 15% faster. The buying inside those runs does not know about the error.
Simulator.MODEL_ERRORS = {
    {
        dpsErr = 0.85,
        what = "15% less damage than the model"
    },
    {
        speedErr = 1.15,
        what = "enemies 15% faster"
    }
}

function Simulator.farmsPerHour(level)
    return not (level.infinite and Simulator.unbound(level.ld))
end

function Simulator.safeWin(level, teamFrom, extra)
    local wins, tries = 0, 0
    for _, jitter in ipairs({
        1,
        0.92,
        1.08
    }) do
        local opts = {
            hpMul = Simulator.SAFE_MUL * jitter
        }
        for key, value in pairs(extra or {
        }) do
            opts [key] = value
        end
        tries = tries + 1
        if Simulator.run(level, teamFrom, opts).won then
            wins = wins + 1
        end
        if wins >= 2 then
            break
        end
        if tries - wins >= 2 then
            return false, string.format("enemies ×%.1f HP", Simulator.SAFE_MUL)
        end
    end
    if wins < 2 then
        return false, string.format("enemies ×%.1f HP", Simulator.SAFE_MUL)
    end
    for _, err in ipairs(Simulator.MODEL_ERRORS) do
        local opts = {
            hpMul = 1
        }
        for key, value in pairs(extra or {
        }) do
            opts [key] = value
        end
        for key, value in pairs(err) do
            if key ~= "what" then
                opts [key] = value
            end
        end
        if not Simulator.run(level, teamFrom, opts).won then
            return false, err.what
        end
    end
    return true
end

-- Minutes one run takes, the time back to the lobby and into the next run included.
function Simulator.runMinutes(run)
    return (tonumber(run and (run.seconds or run.t)) or 0) / 60 + ((Modes and Modes.OVERHEAD) or 0.7)
end

-- "+12% runs per hour" for the log.
function Simulator.perHourText(fastMin, slowMin)
    return string.format("%d%% more runs per hour", math.floor((slowMin / math.max(0.01, fastMin) - 1) * 100 + 0.5))
end
Simulator.FARM_SLACK = 3
Simulator.SUPPORT_TRIES = 3
Simulator.STATUS = {
    untested = "NOT TESTED",
    failed = "TESTED, DID NOT WORK",
    worked = "WORKED, ANOTHER LINEUP IS BETTER",
    chosen = "CHOSEN"
}

-- Modes that end by wave 15-20: here two farms and an early buffer get the first look.
function Simulator.isShort(level)
    return not (level.infinite and Simulator.unbound(level.ld)) and (tonumber(level.total) or 99) <= Simulator.SHORT_WAVES
end

function Simulator.newReport(level, label)
    return {
        label = label,
        map = level.map,
        total = level.total,
        endless = (level.infinite and Simulator.unbound(level.ld)) and true or false,
        short = Simulator.isShort(level),
        rows = {
        },
        supports = {
        },
        fusion = {
            status = "untested",
            note = "the team search did not run"
        }
    }
end

-- The planner view shows this while a search runs.
function Simulator.stage(fraction, text)
    local progress = Simulator.progress
    if not progress then
        return
    end
    progress.frac = math.max(progress.frac or 0, fraction)
    if text then
        progress.text = text
    end
    progress.at = Utils.now()
end

-- Units the structured comparison draws from: the pool first (its copy of a unit is the
-- strongest one owned), then anything else already in the lineup.
function Simulator.roster(pool, extra, level)
    local roster = {
        farms = {
        },
        buffers = {
        },
        attackers = {
        },
        supports = {
        }
    }
    local seen, rank = {
    }, {
    }
    local function add(unit)
        local id = unit.unit_id
        if seen [id] or not Units.rows(id) then
            return
        end
        seen [id] = true
        if Units.isFarm(id) then
            local ok, income = pcall(Units.farm, unit, Units.rows(id).max)
            rank [unit] = ok and income or 0
            table.insert(roster.farms, unit)
        elseif Units.allyBuff(id) then
            rank [unit] = Units.effects(id).score
            if Units.buffAllowed(id) then
                table.insert(roster.buffers, unit)
            else
                roster.blocked = roster.blocked or {
                }
                table.insert(roster.blocked, Units.name(id))
            end
        else
            local ok, score = pcall(Units.score, unit, level.mod)
            rank [unit] = (ok and score or 0) * Units.skinMul(unit, level.skinSet)
            table.insert(roster.attackers, unit)
            if Units.effects(id).useful and not Units.FUSION.attacks [id] then
                table.insert(roster.supports, unit)
            end
        end
    end
    for _, unit in ipairs(pool) do
        add(unit)
    end
    for _, unit in ipairs(extra or {
    }) do
        add(unit)
    end
    local function byRank(a, b)
        return rank [a] > rank [b]
    end
    table.sort(roster.farms, byRank)
    table.sort(roster.buffers, byRank)
    table.sort(roster.attackers, byRank)
    table.sort(roster.supports, function(a, b)
        return Units.effects(a.unit_id).score > Units.effects(b.unit_id).score
    end)
    roster.rank = rank
    return roster
end

-- farms, then the buffer, then attackers. With a buffer in, attackers whose own damage type
-- it raises come first: a second element or a name does not make a unit fit the buff.
function Simulator.compose(roster, farmCount, buffer, kind, must)
    local team, used = {
    }, {
    }
    local function add(unit)
        if unit and # team < 6 and not used [unit.unit_id] then
            used [unit.unit_id] = true
            table.insert(team, unit)
        end
    end
    for _, unit in ipairs(must or {
    }) do
        add(unit)
    end
    for index = 1, farmCount do
        add(roster.farms [index])
    end
    if buffer then
        add(buffer)
        for _, unit in ipairs(roster.attackers) do
            local _, base = Units.types(unit.unit_id)
            if base == kind then
                add(unit)
            end
        end
    end
    for _, unit in ipairs(roster.attackers) do
        add(unit)
    end
    return team
end

function Simulator.fusionLineup(level, team, pool, farmCount, roster)
    if not Config.actives then return nil, "Auto Abilities is off, and Fusion is cast as an ability" end
    local fusion = Units.FUSION
    if not Units.rows(fusion.hero) then return nil, "Fused Hero stats are unavailable" end
    local lineup, used = {}, {}
    for _, id in ipairs(fusion.parents) do
        local candidate = pool.fusionParents and pool.fusionParents[id]
        local unit = candidate and candidate.u
        if not unit then
            for _, equipped in ipairs(team) do
                if equipped.unit_id == id then unit = equipped break end
            end
        end
        if not unit then return nil, Units.name(id) .. " was not found in the inventory or the equipped team" end
        local rows = Units.rows(id)
        if not rows or rows.max < fusion.upgrade then
            return nil, Units.name(id) .. " is owned, but its upgrade 7 data is unavailable"
        end
        table.insert(lineup, unit)
        used[id] = true
    end
    local entries = Simulator.teamFrom(lineup, level.map)
    if #entries < 2 or not entries[1].placeable or not entries[2].placeable then
        return nil, "this map has no hill spot for " .. Units.name(fusion.parents[1])
    end

    local farms, others = {}, {}
    local function sortIn(unit)
        if used[unit.unit_id] then return end
        used[unit.unit_id] = true
        table.insert(Units.isFarm(unit.unit_id) and farms or others, unit)
    end
    for _, unit in ipairs(team) do sortIn(unit) end
    if farmCount and roster then
        for _, unit in ipairs(roster.farms) do sortIn(unit) end
        for _, unit in ipairs(roster.attackers) do sortIn(unit) end
    end
    if farmCount then
        while #farms > farmCount do table.remove(farms) end
    end
    -- Both Fusion units and Fused Hero deal physical damage: a physical buffer stays ahead of plain attackers.
    local function weight(unit)
        local buff = Units.allyBuff(unit.unit_id)
        if buff then return buff.types.physical and math.huge or -1 end
        local ok, score = pcall(Units.score, unit, level.mod)
        return ok and score or 0
    end
    table.sort(others, function(a, b) return weight(a) > weight(b) end)
    for _, unit in ipairs(farms) do
        if #lineup < 6 then table.insert(lineup, unit) end
    end
    for _, unit in ipairs(others) do
        if #lineup < 6 then table.insert(lineup, unit) end
    end
    return lineup
end

function Simulator.describeFusion(result)
    if result.fusionWave then return "Fused Hero at wave " .. tostring(result.fusionWave) end
    if not result.fusionLevels then return "Fusion was not available in this simulation" end
    local function progress(id)
        local level = result.fusionLevels[id]
        return level and ("U" .. tostring(math.min(level, Units.FUSION.upgrade)) .. "/7") or "not placed"
    end
    return "no fusion · Carrot " .. progress(Units.FUSION.parents[1]) .. " · Vego " .. progress(Units.FUSION.parents[2])
end

function Simulator.planTrace(label)
    Simulator.planSequence = (Simulator.planSequence or 0) + 1
    local id, started = Simulator.planSequence, Utils.now()
    Simulator.progress = { label = label, text = "Started", frac = 0, started = started, at = started, running = true }
    local progress = Simulator.progress
    return function(message, quiet)
        if not quiet then
            progress.text, progress.at = message, Utils.now()
        end
        App.log(1, "PLAN", string.format("#%d +%.1fs %s · %s", id, Utils.now() - started, label, message))
    end
end

function Simulator.lineupNames(team)
    local names = {}
    for _, unit in ipairs(team) do
        table.insert(names, Units.name(unit.unit_id))
    end
    return #names > 0 and table.concat(names, ", ") or "none"
end

-- Why a lineup plays the way it does, from what its own run bought: farms, the buffer, Fusion.
function Simulator.whyLine(level, team, run)
    local stats = run and run.stats or {
    }
    local farms, buffKinds, parts = 0, {
    }, {
    }
    for _, unit in ipairs(team) do
        if Units.isFarm(unit.unit_id) then
            farms = farms + 1
        end
        local buff = Units.allyBuff(unit.unit_id)
        for kind in pairs(buff and buff.types or {
        }) do
            if not table.find(buffKinds, kind) then
                table.insert(buffKinds, kind)
            end
        end
    end
    if run and run.fusionWave then
        table.insert(parts, "Fused Hero at wave " .. tostring(run.fusionWave) .. ((stats.saved or 0) > 0 and " (yen saved for it while the defense held)" or ""))
    end
    if farms > 0 then
        local word = farms >= 2 and "two farms" or "one farm"
        if (stats.farmKinds or 0) == 0 then
            table.insert(parts, word .. " equipped, never bought: the defense needed the yen")
        elseif stats.farmPaidWave then
            table.insert(parts, string.format("%s by wave %d", (stats.farmKinds or 0) >= 2 and "two farms pay back" or "one farm pays back", stats.farmPaidWave))
        else
            table.insert(parts, string.format("farms earn back ¥%s of ¥%s", Utils.fmt(stats.farmEarned or 0), Utils.fmt(stats.farmSpent or 0)))
        end
    end
    if # buffKinds > 0 then
        table.sort(buffKinds)
        local name = table.concat(buffKinds, "/")
        if stats.buffWave and stats.buffShare then
            local copies = 0
            for _, count in pairs(stats.buffCopies or {
            }) do
                copies = math.max(copies, count)
            end
            table.insert(parts, string.format("%s buff%s from wave %d reaches %d%% of team damage (+%d%%)", name, copies > 1 and string.format(" (%d copies)", copies) or "", stats.buffWave, math.floor(stats.buffShare * 100 + 0.5), math.floor((stats.buffGain or 0) * 100 + 0.5)))
        elseif stats.buffWave then
            table.insert(parts, name .. " buffer bought at wave " .. tostring(stats.buffWave))
        else
            table.insert(parts, name .. " buffer never bought: damage was worth more")
        end
    end
    return # parts > 0 and table.concat(parts, " · ") or nil
end

-- One line for the log on a unit the player asked about: what the data confirms, what cannot be simulated.
function Simulator.unitNote(id, pool, team)
    local session = Core.session()
    local owned = false
    for _, unit in pairs(session and session.profile_data.collection.owned_units or {
    }) do
        if unit.unit_id == id then
            owned = true
            break
        end
    end
    local name = Units.name(id)
    if not Core.Units [id] then
        return name .. " (" .. id .. "): not in the game's unit data"
    end
    if not owned then
        return name .. " (" .. id .. "): not owned"
    end
    if Units.hidden(id) then
        return name .. " (" .. id .. "): NOT TESTED · the game sends its upgrades only inside a match, so its strength is unknown here"
    end
    local effects = Units.effects(id)
    local known = # effects.tags > 0 and table.concat(effects.tags, ", ") or "no team effect in the data the game sent (damage only)"
    local unknown = # effects.unmodeled > 0 and (" · not simulated: " .. table.concat(effects.unmodeled, ", ")) or ""
    local where = "not in the search pool (too weak a copy for this stage)"
    for _, unit in ipairs(team or {
    }) do
        if unit.unit_id == id then
            where = "in the planned lineup"
        end
    end
    if where:find("^not") then
        for _, unit in ipairs(pool or {
        }) do
            if unit.unit_id == id then
                where = "tested by the search, another unit did better in its slot"
            end
        end
        for _, unit in ipairs(pool and pool.rest or {
        }) do
            if unit.unit_id == id then
                where = "in the reserve pool: only tried when it tops the weakest slot"
            end
        end
    end
    return string.format("%s (%s): %s%s · %s", name, id, known, unknown, where)
end
-- Units whose effects players ask about by name: always get a line in planner.log.
Simulator.NAMED_SUPPORTS = {
    "homura",
    "homura_evolved"
}

function Simulator.bestTeam(applyFx, arg2, pool, num, trace, report)
    local now = Utils.now()
    num = num or 25
    report = report or Simulator.newReport(applyFx, "")
    local say = trace or function()
    end
    local arg22 = table.clone(arg2)
    Simulator.stage(0.05)
    say("Finding the enemy-HP threshold for the current team")
    local cliff, cliff2 = Simulator.cliff(applyFx, Simulator.teamFrom(arg22, applyFx.map))
    say(string.format("Stress threshold ×%.2f HP · wave %d", cliff, cliff2.wave or 0))
    local function helper(arg1)
        local count = 0
        for _, unitData in ipairs(arg1) do
            if not Units.isFarm(unitData.unit_id) and not Units.allyBuff(unitData.unit_id) then
                count = count + Units.cap(unitData)
            end
        end
        return count
    end
    local function hasUnitId(team, id)
        for _, member in ipairs(team) do
            if member.unit_id == id then return true end
        end
        return false
    end
    local function isBetterObj(newObj, oldObj, newRun, oldRun)
        if newObj > oldObj + 0.05 then return true end
        if newRun and oldRun and newRun.won == oldRun.won and newRun.wave == oldRun.wave and newRun.won then
            return (oldRun.t or 0) - (newRun.t or 0) >= 3
        end
        return false
    end
    local function withOpts(hpMul, extra)
        local opts = { hpMul = hpMul }
        for key, value in pairs(extra or {}) do opts[key] = value end
        return opts
    end
    local value
    while # arg22 < 6 do
        say(string.format("Testing eligible candidates for slot %d", #arg22 + 1))
        local value2, value3
        for _, unitData in ipairs(pool) do
            if value2 and Utils.now() - now > num * 0.4 then
                say("Slot search cut short: the search's time budget is running out", true)
                break
            end
            if not hasUnitId(arg22, unitData.unit_id) then
                local arg222 = table.clone(arg22)
                table.insert(arg222, unitData)
                local value4 = Simulator.run(applyFx, Simulator.teamFrom(arg222, applyFx.map), { hpMul = cliff })
                local objective = Simulator.objective(value4)
                if not value3 or objective > value3 then
                    value2, value3, value = unitData, objective, value4
                end
            end
        end
        if not value2 then break end
        table.insert(arg22, value2)
    end
    local function helper2(arg1, arg2, extra)
        local teamFrom = Simulator.teamFrom(arg1, applyFx.map)
        return (Simulator.objective(arg2) + Simulator.objective(Simulator.run(applyFx, teamFrom, withOpts(cliff * 0.92, extra)))
            + Simulator.objective(Simulator.run(applyFx, teamFrom, withOpts(cliff * 1.08, extra)))) / 3
    end
    local value2, score2 = value or cliff2, helper2(arg22, value or cliff2)
    Simulator.stage(0.2)
    -- Multi-start: build synthetic meta/economy seeds from the pool to escape local optima
    do
        local farms, dpsPool, buffPool = {}, {}, {}
        for _, cand in ipairs(pool) do
            if Units.isFarm(cand.unit_id) then
                table.insert(farms, cand)
            elseif Units.allyBuff(cand.unit_id) then
                table.insert(buffPool, cand)
            else
                table.insert(dpsPool, cand)
            end
        end
        local function buildSeed(targetFarms, includeBuff)
            local seed = {}
            for i = 1, math.min(targetFarms, #farms) do
                table.insert(seed, farms[i])
            end
            for _, d in ipairs(dpsPool) do
                if #seed >= (includeBuff and #buffPool > 0 and 5 or 6) then break end
                if not hasUnitId(seed, d.unit_id) then table.insert(seed, d) end
            end
            if includeBuff and #seed < 6 then
                for _, b in ipairs(buffPool) do
                    if #seed >= 6 then break end
                    if not hasUnitId(seed, b.unit_id) then table.insert(seed, b) end
                end
            end
            for _, d in ipairs(dpsPool) do
                if #seed >= 6 then break end
                if not hasUnitId(seed, d.unit_id) then table.insert(seed, d) end
            end
            return seed
        end
        local seeds = {}
        if #dpsPool > 0 then
            table.insert(seeds, buildSeed(applyFx.total >= 8 and 1 or 0, true))
            if applyFx.total >= 13 and #farms >= 2 then
                table.insert(seeds, buildSeed(2, false))
            end
        end
        for _, seed in ipairs(seeds) do
            if #seed >= math.min(6, #arg22) and helper(seed) >= 1 and Simulator.profileSig(seed) ~= Simulator.profileSig(arg22) then
                local tested = Simulator.teamFrom(seed, applyFx.map)
                local res = Simulator.run(applyFx, tested, { hpMul = cliff })
                local obj = Simulator.objective(res)
                local curSingleObj = Simulator.objective(value2)
                if obj > math.min(score2, curSingleObj) + 0.05 or isBetterObj(obj, curSingleObj, res, value2) then
                    local avgObj = helper2(seed, res)
                    if isBetterObj(avgObj, score2, res, value2) then
                        arg22, value2, score2 = seed, res, avgObj
                        say("Synthetic seed ahead: " .. Simulator.lineupNames(seed), true)
                    end
                end
            end
        end
    end

    -- Named lineups, compared on this map with the same buying rules: how many farms, which buffer.
    local roster = Simulator.roster(pool, arg22, applyFx)
    local short = report.short
    local rows = {
    }
    local farmLock = false
    local function measure(name, kind, team, extra)
        local entries = Simulator.teamFrom(team, applyFx.map)
        local normal = Simulator.run(applyFx, entries, withOpts(1, extra))
        local stress = cliff == 1 and normal or Simulator.run(applyFx, entries, withOpts(cliff, extra))
        local row = {
            name = name,
            kind = kind,
            team = team,
            run = normal,
            stress = stress,
            obj = Simulator.objective(stress),
            extra = extra,
            status = "worked"
        }
        table.insert(rows, row)
        return row
    end
    local function skip(name, kind, note)
        table.insert(rows, {
            name = name,
            kind = kind,
            status = "untested",
            note = note
        })
    end
    local function farmCountOf(team)
        local count = 0
        for _, unit in ipairs(team) do
            if Units.isFarm(unit.unit_id) then
                count = count + 1
            end
        end
        return count
    end
    local aiMod = Core and Core.AI
    if Config.aiTeam ~= false and aiMod and aiMod.buildLiveTeamInputs and aiMod.searchTeams then
        local okTeamNN, teamErr = pcall(function()
            local liveIn = aiMod.buildLiveTeamInputs(applyFx, pool, arg22, num)
            if type(liveIn) ~= "table" or type(liveIn.candidates) ~= "table" or #liveIn.candidates == 0 then
                return
            end
            local wantK = 3
            if (tonumber(num) or 25) <= 10 then
                wantK = 2
            end
            local sr = aiMod.searchTeams(liveIn.candidates, liveIn.ctx, {
                topK = wantK,
                beamWidth = 6,
                maxShortlist = 28
            })
            if type(sr) ~= "table" or type(sr.topTeams) ~= "table" or #sr.topTeams == 0 then
                return
            end
            local mapInfo = Brain and Brain.maps and applyFx.map and Brain.maps[applyFx.map]
            local noHills = (mapInfo and mapInfo.hill == false)
            local seenSigs = {}
            local testedK = 0
            local bestNeuralName = ""
            local bestNeuralScore = -1e9
            for k = 1, #sr.topTeams do
                local item = sr.topTeams[k]
                if type(item) == "table" and type(item.team) == "table" then
                    local candTeam = {}
                    local idSeen = {}
                    local valid = true
                    for idx = 1, #item.team do
                        local normU = item.team[idx]
                        local rawU = normU and normU._raw
                        if type(rawU) ~= "table" or not rawU.unit_id or not rawU.uuid then
                            valid = false
                            break
                        end
                        local uid = rawU.unit_id
                        if idSeen[uid] then
                            valid = false
                            break
                        end
                        if Config.farmUnits == false and Units.isFarm(uid) then
                            valid = false
                            break
                        end
                        if Units.allyBuff(uid) then
                            if Config.actives == false then
                                valid = false
                                break
                            end
                            if Units.buffAllowed and not Units.buffAllowed(uid) then
                                valid = false
                                break
                            end
                        end
                        if noHills then
                            local uData = Core.Units and Core.Units[uid]
                            if uData and uData.hill_unit and not uData.hybrid_placement then
                                valid = false
                                break
                            end
                        end
                        idSeen[uid] = true
                        candTeam[#candTeam + 1] = rawU
                    end
                    if valid and #candTeam >= 1 and #candTeam <= 6 and helper(candTeam) >= 1 then
                        local sig = Simulator.profileSig(candTeam)
                        if not seenSigs[sig] then
                            seenSigs[sig] = true
                            testedK = testedK + 1
                            local rowName = "Neural AI team #" .. tostring(testedK)
                            say(string.format("Testing %s (TeamNN score=%.3f)", rowName, tonumber(item.score) or 0))
                            local row = measure(rowName, "neural", candTeam)
                            row.farms = farmCountOf(candTeam)
                            row.buff = nil
                            if testedK == 1 then
                                bestNeuralName = Simulator.lineupNames(candTeam)
                                bestNeuralScore = tonumber(item.score) or 0
                            end
                            App.log(2, "AI_TEAM", string.format("%s: score=%.3f wave=%d won=%s [%s]", rowName, tonumber(item.score) or 0, (row.run and row.run.wave) or 0, tostring(row.run and row.run.won == true), Simulator.lineupNames(candTeam)))
                        end
                    end
                end
            end
            if testedK > 0 then
                App.log(1, "AI_TEAM", string.format("%s: evaluated %d neural teams (%d evals, %.1fms, top=%.3f: %s)", tostring(applyFx.key or applyFx.gm or "stage"), testedK, tonumber(sr.evalCount) or 0, tonumber(sr.elapsedMs) or 0, bestNeuralScore, bestNeuralName))
            end
        end)
        if not okTeamNN then
            App.log(2, "AI_TEAM", "Fallback to v2.34 team planner (" .. tostring(teamErr) .. ")")
        end
    end
    do
        local buffOptions = {
            false
        }
        local bestByKind = {
        }
        for _, unit in ipairs(roster.buffers) do
            local buff = Units.allyBuff(unit.unit_id)
            for kind, rate in pairs(buff.types or {
            }) do
                local power = (tonumber(rate) or 0) * (buff.uptime or 0)
                if not bestByKind [kind] or power > bestByKind [kind].power then
                    bestByKind [kind] = {
                        kind = kind,
                        buffer = unit,
                        power = power,
                        matched = 0,
                        weight = 0
                    }
                end
            end
        end
        for _, unit in ipairs(roster.attackers) do
            local _, base = Units.types(unit.unit_id)
            local option = bestByKind [base]
            if option then
                option.matched = option.matched + 1
                option.weight = option.weight + (roster.rank [unit] or 0)
            end
        end
        local kinds = {
        }
        for _, option in pairs(bestByKind) do
            table.insert(kinds, option)
        end
        table.sort(kinds, function(a, b)
            if a.weight ~= b.weight then
                return a.weight > b.weight
            end
            return a.kind < b.kind
        end)
        for index = 1, math.min(2, # kinds) do
            table.insert(buffOptions, kinds [index])
        end
        for index = 3, # kinds do
            skip(kinds [index].kind .. " buffer", "mix", "only the two buff types with the most matching damage are compared")
        end
        for _, name in ipairs(roster.blocked or {
        }) do
            skip(name, "mix", "Auto Buff is set to " .. tostring(Config.autoBuffKind) .. " only")
        end
        local farmCounts = short and {
            2,
            1,
            0
        } or {
            0,
            1,
            2
        }
        local total, index, measured = # farmCounts * # buffOptions, 0, 0
        for _, farmCount in ipairs(farmCounts) do
            for _, option in ipairs(buffOptions) do
                index = index + 1
                local name = (farmCount == 0 and "no farms" or farmCount == 1 and "1 farm" or "2 farms") .. (option and (" + " .. option.kind .. " buffer") or ", no buffer")
                if farmCount > 0 and Config.farmUnits == false then
                    skip(name, "mix", "Farm Units is switched off")
                elseif farmCount > # roster.farms then
                    skip(name, "mix", string.format("only %d farm unit%s owned", # roster.farms, # roster.farms == 1 and "" or "s"))
                elseif option and Config.actives == false then
                    skip(name, "mix", "Auto Abilities is off, so the buff is never cast")
                elseif option and option.matched < 2 then
                    skip(name, "mix", string.format("only %d attacker%s deal%s %s damage", option.matched, option.matched == 1 and "" or "s", option.matched == 1 and "s" or "", option.kind))
                elseif measured >= 3 and Utils.now() - now > num * 0.6 then
                    skip(name, "mix", "the search's time budget ran out first")
                else
                    local team = Simulator.compose(roster, farmCount, option and option.buffer, option and option.kind)
                    if helper(team) < 1 then
                        skip(name, "mix", "no attacker is left for this lineup")
                    else
                        Simulator.stage(0.2 + 0.3 * index / total)
                        say(string.format("Comparing lineup %d of %d: %s", index, total, name))
                        local row = measure(name, "mix", team)
                        row.farms, row.buff = farmCountOf(team), option
                        measured = measured + 1
                    end
                end
            end
        end
        local topWave = 0
        for _, row in ipairs(rows) do
            if row.run then
                topWave = math.max(topWave, row.run.wave or 0)
            end
        end
        for _, row in ipairs(rows) do
            local stats = row.run and row.run.stats or {
            }
            if row.run and row.buff then
                if not stats.buffWave then
                    row.status, row.note = "failed", "the buffer was never bought in the simulation: damage was always worth more"
                elseif short and stats.buffWave > math.ceil(applyFx.total / 2) then
                    row.status, row.note = "failed", string.format("the buffer first comes up at wave %d of %d: too late for a short mode", stats.buffWave, applyFx.total)
                end
            end
            if row.run and row.status ~= "failed" then
                row.note = Simulator.whyLine(applyFx, row.team, row.run)
            end
            if row.run and (row.farms or 0) > 0 then
                if (stats.farmKinds or 0) < row.farms then
                    row.farmOk, row.farmNote = false, string.format("only %d of %d farm units were ever bought: the defense needed the yen", stats.farmKinds or 0, row.farms)
                elseif not stats.farmPaidWave then
                    row.farmOk, row.farmNote = false, string.format("the farms earn back ¥%s of the ¥%s they cost: no time to pay back", Utils.fmt(stats.farmEarned or 0), Utils.fmt(stats.farmSpent or 0))
                else
                    row.farmOk, row.farmNote = true, string.format("%s by wave %d", row.farms >= 2 and "two farms pay back" or "one farm pays back", stats.farmPaidWave)
                end
            end
        end
        local function bestOf(filter)
            local best
            for _, row in ipairs(rows) do
                if row.run and row.status ~= "failed" and (not filter or filter(row)) and (not best or row.obj > best.obj) then
                    best = row
                end
            end
            return best
        end
        local top = bestOf()
        local pick, priority = top, nil
        if short and top then
            -- Short modes: two farms go first when they pay back and the defense holds; then one; then none.
            for _, wanted in ipairs({
                2,
                1
            }) do
                local best = bestOf(function(row)
                    return row.farms == wanted and row.farmOk and (row.run.won or (row.run.wave or 0) >= topWave)
                end)
                if best and best.obj >= top.obj - Simulator.FARM_SLACK then
                    pick, priority = best, best.farmNote .. " and the team holds the waves"
                    break
                end
                for _, row in ipairs(rows) do
                    if row.run and row.farms == wanted and row.status ~= "failed" then
                        if not row.farmOk then
                            row.status, row.note = "failed", row.farmNote
                        elseif not (row.run.won or (row.run.wave or 0) >= topWave) then
                            row.status, row.note = "failed", string.format("the base falls at wave %d while the farms are being paid for", row.run.wave or 0)
                        else
                            row.note = row.farmNote .. ", but \"" .. top.name .. "\" holds more enemy HP"
                        end
                    end
                end
            end
        end
        if pick then
            report.priority = priority
            local same = Simulator.profileSig(pick.team) == Simulator.profileSig(arg22)
            local adopt = same
            if not same then
                if priority then
                    adopt = pick.obj >= Simulator.objective(value2) - Simulator.FARM_SLACK
                else
                    adopt = isBetterObj(helper2(pick.team, pick.stress), score2, pick.stress, value2)
                end
                if adopt then
                    arg22, value2, score2 = pick.team, pick.stress, helper2(pick.team, pick.stress)
                else
                    pick.note = (pick.note and (pick.note .. " · ") or "") .. "the unit-by-unit search holds more enemy HP"
                    report.priority = nil
                end
            end
            farmLock = adopt and priority ~= nil
        end
    end

    -- Supports with effects the data confirms: each gets a real run in place of the weakest attacker.
    Simulator.stage(0.55)
    do
        local tried = 0
        for _, unit in ipairs(roster.supports) do
            local id = unit.unit_id
            local effects = Units.effects(id)
            local line = {
                name = Units.name(id),
                id = id,
                effects = table.concat(effects.tags, ", "),
                unmodeled = # effects.unmodeled > 0 and table.concat(effects.unmodeled, ", ") or nil
            }
            table.insert(report.supports, line)
            if hasUnitId(arg22, id) then
                line.status, line.note = "chosen", "already in the leading lineup"
            elseif tried >= Simulator.SUPPORT_TRIES then
                line.status, line.note = "untested", string.format("only the %d strongest effects get a run of their own", Simulator.SUPPORT_TRIES)
            elseif tried >= 1 and Utils.now() - now > num * 0.7 then
                line.status, line.note = "untested", "the search's time budget ran out first"
            else
                tried = tried + 1
                local slot, lowest
                for index, member in ipairs(arg22) do
                    if not Units.isFarm(member.unit_id) and not Units.allyBuff(member.unit_id) and not Units.FUSION.attacks [member.unit_id] then
                        local score = roster.rank [member] or 0
                        if not lowest or score < lowest then
                            slot, lowest = index, score
                        end
                    end
                end
                if not slot then
                    line.status, line.note = "untested", "no attacker slot to give up"
                else
                    local team = table.clone(arg22)
                    local out = team [slot]
                    team [slot] = unit
                    say(string.format("Testing support %s in place of %s", line.name, Units.name(out.unit_id)))
                    local row = measure(line.name .. " instead of " .. Units.name(out.unit_id), "support", team)
                    row.farms = farmCountOf(team)
                    local before = value2
                    if row.obj > Simulator.objective(before) + 0.05 and isBetterObj(helper2(team, row.stress), score2, row.stress, before) then
                        arg22, value2, score2 = team, row.stress, helper2(team, row.stress)
                        line.status = "chosen"
                        line.note = string.format("holds wave %d against ×%.1f HP, %s held wave %d", row.stress.wave or 0, cliff, Units.name(out.unit_id), before.wave or 0)
                    elseif row.stress.won == before.won and (row.stress.wave or 0) >= (before.wave or 0) then
                        line.status = "worked"
                        line.note = string.format("as good as %s (wave %d against ×%.1f HP), but not better: the attacker stays", Units.name(out.unit_id), row.stress.wave or 0, cliff)
                    else
                        line.status = "failed"
                        line.note = string.format("wave %d against ×%.1f HP, %s reaches wave %d: its effect does not replace that damage here", row.stress.wave or 0, cliff, Units.name(out.unit_id), before.wave or 0)
                    end
                    row.status, row.note = line.status == "chosen" and "worked" or line.status, line.note
                end
            end
        end
    end

    -- Carrot + Vego: always at least one full lineup, with regular buying and with yen saved for the pair.
    Simulator.stage(0.6)
    local fusion = report.fusion
    do
        local fusionTeam, reason = Simulator.fusionLineup(applyFx, arg22, pool)
        if not fusionTeam then
            fusion.status, fusion.note = "untested", reason
        else
            local variants, seen = {
            }, {
            }
            local function addVariant(team)
                if team and not seen [Simulator.sig(team)] then
                    seen [Simulator.sig(team)] = true
                    table.insert(variants, team)
                end
            end
            addVariant(fusionTeam)
            for _, farmCount in ipairs(short and {
                2,
                1,
                0
            } or {
                1,
                0,
                2
            }) do
                if # variants < 3 and farmCount <= # roster.farms then
                    addVariant((Simulator.fusionLineup(applyFx, arg22, pool, farmCount, roster)))
                end
            end
            local best, closest
            for index, team in ipairs(variants) do
                if index > 1 and Utils.now() - now > num * 0.85 then
                    skip("Fusion lineup " .. index, "fusion", "the search's time budget ran out first")
                else
                    for _, save in ipairs({
                        false,
                        true
                    }) do
                        Simulator.stage(0.6 + 0.15 * index / # variants)
                        say(string.format("Fusion lineup %d of %d, %s: %s", index, # variants, save and "saving yen for the pair" or "regular buying", Simulator.lineupNames(team)))
                        local row = measure(string.format("Fusion, %d farm%s, %s", farmCountOf(team), farmCountOf(team) == 1 and "" or "s", save and "saving for the pair" or "regular buying"), "fusion", team, save and {
                            fusionSave = true
                        } or nil)
                        row.save, row.farms = save, farmCountOf(team)
                        local stats = row.run.stats or {
                        }
                        fusion.cost = stats.fusionCost or fusion.cost
                        if row.run.fusionWave then
                            row.note = string.format("Fused Hero at wave %d · the team %s", row.run.fusionWave, row.run.won and "clears the mode" or ("reaches wave " .. tostring(row.run.wave)))
                            local normalObj = Simulator.objective(row.run)
                            if not best or normalObj > best.normalObj + 0.05 or (math.abs(normalObj - best.normalObj) <= 0.05 and row.obj > best.obj) then
                                best = row
                                best.normalObj = normalObj
                            end
                        else
                            row.status = "failed"
                            row.note = string.format("%s by wave %d of %d", Simulator.describeFusion(row.run), row.run.wave or 0, applyFx.total)
                            local levels = row.run.fusionLevels or {
                            }
                            local reach = (levels [Units.FUSION.parents [1]] or 0) + (levels [Units.FUSION.parents [2]] or 0)
                            if not closest or reach > closest.reach then
                                closest = row
                                closest.reach = reach
                            end
                        end
                    end
                end
            end
            if best then
                fusion.status, fusion.team, fusion.run, fusion.opts, fusion.save = "worked", best.team, best.run, best.extra, best.save
                fusion.stress, fusion.row = best.stress, best
                fusion.note = best.note .. (best.save and " · yen is saved for the pair while the defense holds" or " · regular buying")
            else
                fusion.status = "failed"
                fusion.team, fusion.run = closest and closest.team, closest and closest.run
                fusion.note = (closest and closest.note or "no fusion in the simulation") .. (fusion.cost and string.format(" · the pair needs ¥%s for both placements and both upgrade 7s", Utils.fmt(fusion.cost)) or "")
            end
        end
    end

    Simulator.stage(0.75)
    local outOfTime = false
    if type(pool.rest) == "table" and # pool.rest > 0 then
        local value, value2
        for i, unitData in ipairs(arg22) do
            if not Units.isFarm(unitData.unit_id) and not Units.allyBuff(unitData.unit_id) then
                local ok, res = pcall(Units.score, unitData, applyFx.mod)
                res = (ok and res or 0) * Units.skinMul(unitData, applyFx.skinSet)
                if not value2 or res < value2 then
                    value, value2 = i, res
                end
            end
        end
        if value then
            local list, now2 = {
            }, Utils.now()
            for _, unitData in ipairs(pool.rest) do
                if Utils.now() - now2 > 4 then
                    break
                end
                if not hasUnitId(arg22, unitData.unit_id) then
                    local arg222 = table.clone(arg22)
                    arg222 [value] = unitData
                    table.insert(list, {
                        u = unitData,
                        o = Simulator.objective(Simulator.run(applyFx, Simulator.teamFrom(arg222, applyFx.map), { hpMul = cliff }))
                    })
                end
            end
            table.sort(list, function(arg1, arg2)
                return arg1.o > arg2.o
            end)
            pool = table.clone(pool)
            for i = 1, math.min(5, # list) do
                table.insert(pool, 1, list [i].u)
            end
            now = now + (Utils.now() - now2)
        end
    end
    for i = 1, 2 do
        if outOfTime then
            break
        end
        say(string.format("Testing substitutions, pass %d of 2", i))
        local flag = false
        for i = 1, # arg22 do
            if outOfTime then
                break
            end
            -- A lineup picked for its farms keeps them: only its other slots are searched.
            if not (farmLock and Units.isFarm(arg22 [i].unit_id)) then
                for _, unit in ipairs(pool) do
                    if Utils.now() - now > num then
                        say("Substitution budget reached; comparing the finalists found so far")
                        outOfTime = true
                        break
                    end
                    local flag2 = false
                    for i2, unitData in ipairs(arg22) do
                        if i2 ~= i and unitData.unit_id == unit.unit_id then
                            flag2 = true
                            break
                        end
                    end
                    if not flag2 and unit.uuid ~= arg22[i].uuid then
                        local arg222 = table.clone(arg22)
                        arg222 [i] = unit
                        if helper(arg222) >= 1 then
                            local value = Simulator.run(applyFx, Simulator.teamFrom(arg222, applyFx.map), {
                                hpMul = cliff
                            })
                            local objective = Simulator.objective(value)
                            local curSingleObj = Simulator.objective(value2)
                            if objective > math.min(score2, curSingleObj) + 0.05 or isBetterObj(objective, curSingleObj, value, value2) then
                                objective = helper2(arg222, value)
                                if isBetterObj(objective, score2, value, value2) then
                                    arg22, score2, value2, flag = arg222, objective, value, true
                                end
                            end
                        end
                    end
                end
            end
        end
        if not flag then
            break
        end
    end
    Simulator.stage(0.92)
    -- 2-opt synergy pair swaps (e.g. Buffer+DPS, Farm+Carry) when time budget remains
    if not outOfTime and #arg22 >= 4 and Utils.now() - now < num * 0.8 then
        local rankedSlots = {}
        for idx, unit in ipairs(arg22) do
            local okS, sc = pcall(Units.score, unit, applyFx.mod)
            local weight = Units.isFarm(unit.unit_id) and 1e12 or (Units.allyBuff(unit.unit_id) and 5e11 or ((okS and sc or 0) * Units.skinMul(unit, applyFx.skinSet)))
            table.insert(rankedSlots, { idx = idx, w = weight })
        end
        table.sort(rankedSlots, function(a, b) return a.w < b.w end)
        local s1, s2 = rankedSlots[1].idx, rankedSlots[2].idx
        local pairCandidates = {}
        local topBuffs, topFarm, topDps, freeDps = {}, nil, {}, {}
        for _, cand in ipairs(pool) do
            if not hasUnitId(arg22, cand.unit_id) then
                if #topBuffs < 2 and Units.allyBuff(cand.unit_id) and Units.buffAllowed(cand.unit_id) then table.insert(topBuffs, cand) end
                if not topFarm and Units.isFarm(cand.unit_id) then topFarm = cand end
                if not Units.isFarm(cand.unit_id) and not Units.allyBuff(cand.unit_id) then
                    table.insert(freeDps, cand)
                    if #topDps < 3 then table.insert(topDps, cand) end
                end
            end
        end
        -- A buffer pays only with attackers of the damage type it raises: pair it with the strongest free one.
        local function buffMate(buffer)
            local buff = Units.allyBuff(buffer.unit_id)
            for _, cand in ipairs(freeDps) do
                local _, base = Units.types(cand.unit_id)
                if buff and buff.types and buff.types [base] then
                    return cand
                end
            end
            return topDps[1]
        end
        for _, buffer in ipairs(topBuffs) do
            local mate = buffMate(buffer)
            if mate then table.insert(pairCandidates, { buffer, mate }) end
        end
        if topFarm and topDps[1] then table.insert(pairCandidates, { topFarm, topDps[1] }) end
        if topDps[1] and topDps[2] then table.insert(pairCandidates, { topDps[1], topDps[2] }) end
        for _, pair in ipairs(pairCandidates) do
            if Utils.now() - now > num then break end
            local candTeam = table.clone(arg22)
            candTeam[s1], candTeam[s2] = pair[1], pair[2]
            if helper(candTeam) >= 1 then
                local res = Simulator.run(applyFx, Simulator.teamFrom(candTeam, applyFx.map), { hpMul = cliff })
                local obj = Simulator.objective(res)
                local curSingleObj = Simulator.objective(value2)
                if obj > math.min(score2, curSingleObj) + 0.05 or isBetterObj(obj, curSingleObj, res, value2) then
                    local avgObj = helper2(candTeam, res)
                    if isBetterObj(avgObj, score2, res, value2) then
                        arg22, score2, value2 = candTeam, avgObj, res
                        say("Synergy pair improved lineup: " .. Units.name(pair[1].unit_id) .. " + " .. Units.name(pair[2].unit_id), true)
                    end
                end
            end
        end
    end

    -- Farming per hour: among the compared lineups that clear with room to spare, a clearly faster one
    -- beats the one that only holds more enemy HP. Lineups picked by the short-mode farm rule keep
    -- their farm count; Fusion lineups are compared later, in Simulator.plan.
    report.faster = nil
    if Simulator.farmsPerHour(applyFx) and Utils.now() - now < num * 1.2 then
        local chosenRun = Simulator.run(applyFx, Simulator.teamFrom(arg22, applyFx.map), {
            hpMul = 1
        })
        if chosenRun.won then
            local chosenMin, chosenSig = Simulator.runMinutes(chosenRun), Simulator.profileSig(arg22)
            local faster = {
            }
            for _, row in ipairs(rows) do
                if row.run and row.run.won and row.team and row.stress and row.kind ~= "fusion" and not row.extra and row.status ~= "failed"
                    and (not farmLock or farmCountOf(row.team) == farmCountOf(arg22))
                    and Simulator.profileSig(row.team) ~= chosenSig then
                    local rowMin = Simulator.runMinutes(row.run)
                    if rowMin <= chosenMin * (1 - Simulator.FASTER) and chosenMin - rowMin >= 5 / 60 then
                        table.insert(faster, row)
                    end
                end
            end
            table.sort(faster, function(a, b)
                return Simulator.runMinutes(a.run) < Simulator.runMinutes(b.run)
            end)
            if # faster > 0 and Simulator.safeWin(applyFx, Simulator.teamFrom(arg22, applyFx.map)) then
                for index, row in ipairs(faster) do
                    if index > 3 then
                        break
                    end
                    if Simulator.safeWin(applyFx, Simulator.teamFrom(row.team, applyFx.map)) then
                        local rowMin = Simulator.runMinutes(row.run)
                        report.faster = string.format("\"%s\" clears with room to spare (×%.1f enemy HP) in %.1f min a run instead of %.1f: %s",
                            row.name, Simulator.SAFE_MUL, rowMin, chosenMin, Simulator.perHourText(rowMin, chosenMin))
                        arg22, value2, score2 = row.team, row.stress, helper2(row.team, row.stress)
                        say(report.faster, true)
                        break
                    end
                end
            end
        end
    end

    -- A farm or buffer the simulation never buys only takes a slot away. Each one is swapped for the
    -- strongest unused attacker when that holds as much enemy HP (within the farm slack).
    do
        local normal = Simulator.run(applyFx, Simulator.teamFrom(arg22, applyFx.map), { hpMul = 1 })
        local stressed = cliff == 1 and normal or Simulator.run(applyFx, Simulator.teamFrom(arg22, applyFx.map), { hpMul = cliff })
        report.idle = {
        }
        for index = # arg22, 1, - 1 do
            local unit = arg22 [index]
            local id = unit.unit_id
            local bought = (normal.stats and normal.stats.placedWave [id]) or (stressed.stats and stressed.stats.placedWave [id])
            if not bought and (Units.isFarm(id) or Units.allyBuff(id)) then
                -- In a short mode a farm that cannot pay back is certain to stay unbought, so its slot goes to
                -- the spare attacker that still gets the same result at normal HP; elsewhere the swap must
                -- also hold about as much enemy HP.
                local certain = short and Units.isFarm(id)
                local swapped, best
                local tries = 0
                for _, spare in ipairs(roster.attackers) do
                    if tries >= 4 or Utils.now() - now > num * 1.2 then
                        break
                    end
                    if not hasUnitId(arg22, spare.unit_id) then
                        tries = tries + 1
                        local team = table.clone(arg22)
                        team [index] = spare
                        local entries = Simulator.teamFrom(team, applyFx.map)
                        local res = Simulator.run(applyFx, entries, { hpMul = cliff })
                        local plain = cliff == 1 and res or Simulator.run(applyFx, entries, { hpMul = 1 })
                        if plain.won == normal.won and (plain.wave or 0) >= (normal.wave or 0) then
                            local objective = Simulator.objective(res)
                            if (certain or objective >= Simulator.objective(value2) - 10) and (not best or objective > best.objective) then
                                best = { team = team, res = res, plain = plain, spare = spare, objective = objective }
                            end
                            if not certain and best then
                                break
                            end
                        end
                    end
                end
                if best then
                    arg22, value2, score2, swapped, normal = best.team, best.res, helper2(best.team, best.res), best.spare, best.plain
                end
                table.insert(report.idle, string.format("%s was never bought in the simulation: %s", Units.name(id), swapped and ("its slot goes to " .. Units.name(swapped.unit_id)) or "kept only because no spare attacker does as well"))
            end
        end
    end
    -- What was compared, for the log and the planner view.
    local finalSig, named = Simulator.profileSig(arg22), false
    for _, row in ipairs(rows) do
        if row.team and row.kind ~= "fusion" and row.status ~= "failed" and Simulator.profileSig(row.team) == finalSig then
            row.status, named = "chosen", true
            row.note = Simulator.whyLine(applyFx, row.team, row.run) or row.note
        end
    end
    if not named then
        local normal = Simulator.run(applyFx, Simulator.teamFrom(arg22, applyFx.map), { hpMul = 1 })
        table.insert(rows, {
            name = "unit-by-unit search",
            kind = "search",
            team = arg22,
            run = normal,
            stress = value2,
            status = "chosen",
            note = "found by swapping single units, it holds the most enemy HP"
        })
    end
    report.regular = arg22
    for _, line in ipairs(report.supports) do
        local kept = hasUnitId(arg22, line.id)
        if line.status == "chosen" and not kept then
            line.status = "worked"
            line.note = "was in the leading lineup, then a swap in its slot held more enemy HP"
        elseif kept and line.status ~= "chosen" then
            line.status, line.note = "chosen", "a later swap brought it into the final lineup"
        end
    end
    for _, row in ipairs(rows) do
        local entry = {
            name = row.name,
            kind = row.kind,
            status = row.status,
            note = row.note,
            team = row.team and Simulator.lineupNames(row.team) or nil,
            wave = row.run and row.run.wave or nil,
            won = row.run and row.run.won or nil,
            fusionWave = row.run and row.run.fusionWave or nil
        }
        if row.status == "worked" and not entry.note then
            entry.note = "plays, but holds less enemy HP than the chosen lineup"
        end
        table.insert(report.rows, entry)
        row.entry = entry
    end
    Simulator.stage(0.95)
    if fusion.status == "worked" then
        return arg22, value2, cliff, cliff2, fusion.team, fusion.run, fusion.opts
    end
    return arg22, value2, cliff, cliff2, nil, nil, nil
end

-- Auto Buff in the plan: how many copies the simulation bought and what their rotation gives.
function Simulator.buffNotes(team, run)
    local lines = {
    }
    if Config.autoBuff == false then
        return { "Auto Buff · off: buffers cast one at a time, the rotation is not counted" }
    end
    local stats = run and run.stats or {
    }
    for _, unit in ipairs(team) do
        local id = unit.unit_id
        local buff = Units.allyBuff(id)
        if buff then
            local kinds, base = {
            }, 0
            for kind, rate in pairs(buff.types) do
                table.insert(kinds, tostring(kind))
                base = math.max(base, tonumber(rate) or 0)
            end
            table.sort(kinds)
            local copies = stats.buffCopies and stats.buffCopies [id] or 0
            if not Units.buffAllowed(id) then
                table.insert(lines, string.format("Auto Buff · %s (%s): not used, the type is set to %s", Units.name(id), id, tostring(Config.autoBuffKind)))
            elseif copies == 0 then
                table.insert(lines, string.format("Auto Buff · %s (%s) raises %s damage: never bought in the simulation", Units.name(id), id, table.concat(kinds, "/")))
            elseif buff.chain and Units.chainOn() then
                local seen = Brain.stack [buff.attack]
                local cycle = Units.buffCycle(base, copies, buff.cd, seen and tonumber(seen.dur) or buff.time, seen and tonumber(seen.cap) or 1, buff.follow)
                local order = {
                }
                for index = 1, math.min(4, # cycle.casts) do
                    table.insert(order, string.format("#%d at %ds", cycle.casts [index].copy, cycle.casts [index].t))
                end
                table.insert(lines, string.format("Auto Buff · %s (%s) raises %s damage: %d cop%s → +%d%% per cast, rotation averages +%d%% (peak +%d%%, up %d%% of the time; cooldown %ds, buff %ds%s) · order: %s", Units.name(id), id, table.concat(kinds, "/"), copies, copies == 1 and "y" or "ies", math.floor(base * 100 + 0.5), math.floor(cycle.avg * 100 + 0.5), math.floor(cycle.peak * 100 + 0.5), math.floor(cycle.uptime * 100 + 0.5), math.floor(buff.cd + 0.5), math.floor((seen and tonumber(seen.dur) or buff.time or 0) + 0.5), (seen and seen.dur) and ", length measured in a match" or ", length from game data", table.concat(order, ", ")))
            else
                table.insert(lines, string.format("Auto Buff · %s (%s) raises %s damage: %d cop%s taking turns, +%d%% for %d%% of the time", Units.name(id), id, table.concat(kinds, "/"), copies, copies == 1 and "y" or "ies", math.floor(base * 100 + 0.5), math.floor(math.min(1, copies * buff.uptime) * 100 + 0.5)))
            end
        end
    end
    if # lines == 0 then
        table.insert(lines, "Auto Buff · no buffer in the planned lineup")
    end
    return lines
end

-- The comparison as lines for planner.log: every lineup with what happened to it.
function Simulator.reportLines(report, level)
    local lines = {
    }
    table.insert(lines, string.format("Compared %d lineups on %s (%s, %s waves):", # report.rows, tostring(report.map), report.endless and "Infinite" or (report.short and "short mode" or "long mode"), report.endless and "no end" or tostring(report.total)))
    for _, row in ipairs(report.rows) do
        local result = row.wave and (row.won and string.format(" → clears %d/%d", row.wave, level.total) or string.format(" → wave %d", row.wave)) or ""
        table.insert(lines, string.format("  [%s] %s%s%s%s", Simulator.STATUS [row.status] or tostring(row.status), row.name, row.team and (": " .. row.team) or "", result, row.note and (" · " .. row.note) or ""))
    end
    local function farmLine(count, word)
        local best
        for _, row in ipairs(report.rows) do
            if row.kind == "mix" and row.name:find(word, 1, true) == 1 and (not best or (best.status == "untested" and row.status ~= "untested") or row.status == "chosen") then
                best = row
            end
        end
        return best and string.format("%s: %s%s", word, Simulator.STATUS [best.status], best.note and (" (" .. best.note .. ")") or "") or (word .. ": NOT TESTED")
    end
    table.insert(lines, "Farms · " .. farmLine(2, "2 farms") .. " · " .. farmLine(1, "1 farm") .. " · " .. farmLine(0, "no farms"))
    if report.priority then
        table.insert(lines, "Short-mode rule applied: " .. report.priority)
    elseif report.short then
        table.insert(lines, "Short-mode rule: two farms did not pass (pay back + hold the waves), so lineups were compared on enemy HP held")
    else
        table.insert(lines, "Infinite/long mode: no farm rule, the lineup that lasts longest wins whatever its farm count")
    end
    for _, line in ipairs(report.supports) do
        table.insert(lines, string.format("Support · %s (%s): %s%s · [%s] %s", line.name, line.id, line.effects ~= "" and line.effects or "no confirmed effect", line.unmodeled and (" · not simulated: " .. line.unmodeled) or "", Simulator.STATUS [line.status] or "?", line.note or ""))
    end
    for _, text in ipairs(report.idle or {
    }) do
        table.insert(lines, "Idle slot · " .. text)
    end
    table.insert(lines, string.format("Fusion · [%s] %s", Simulator.STATUS [report.fusion.status] or "?", tostring(report.fusion.note)))
    return lines
end

function Simulator.evolutions()
    local session = Core.session()
    local list, list2 = {
    }, {
    }
    local inventory = session.inventory
    local function helper(arg1)
        local count = 0
        pcall(function()
            count = inventory:get_number_of_owned_item(arg1)
        end)
        return count
    end
    for _, ownedUnit in pairs(session.profile_data.collection.owned_units) do
        local unit = Core.Units [ownedUnit.unit_id]
        if unit and unit.evolve and unit.evolve.evolve_unit and not unit.evolve.hide_from_ui and not list2 [ownedUnit.unit_id] and Core.Units [unit.evolve.evolve_unit] then
            list2 [ownedUnit.unit_id] = true
            local shiny = ownedUnit.shiny and unit.evolve.shiny or unit.evolve.normal
            if shiny then
                local list2 = {
                }
                for _, value in pairs(shiny.item_requirement or {
                }) do
                    if helper(value.item_id) < (value.amount or 1) then
                        table.insert(list2, string.format("%s %d/%d", (Core.Items [value.item_id] or {
                        }).name or value.item_id, helper(value.item_id), value.amount))
                    end
                end
                for _, unitData in pairs(shiny.unit_requirement or {
                }) do
                    local count = 0
                    for _, ownedUnit in pairs(session.profile_data.collection.owned_units) do
                        if ownedUnit.unit_id == unitData.unit_id and (not unitData.shiny or ownedUnit.shiny) then
                            count = count + 1
                        end
                    end
                    if count < (unitData.amount or 1) then
                        table.insert(list2, string.format("%s %d/%d", Units.name(unitData.unit_id), count, unitData.amount))
                    end
                end
                local killsShort = Adventure.killsShort(session.collection:get_unit_by_uuid(ownedUnit.uuid) or ownedUnit, shiny)
                if killsShort then
                    table.insert(list2, string.format("%s %s/%s", killsShort.what, Utils.fmt(killsShort.have), Utils.fmt(killsShort.need)))
                end
                if # list2 <= 1 then
                    local unitObj = session.collection:get_unit_by_uuid(ownedUnit.uuid) or ownedUnit
                    table.insert(list, {
                        u = unitObj,
                        from = ownedUnit.unit_id,
                        to = unit.evolve.evolve_unit,
                        missing = list2,
                        evolved = {
                            unit_id = unit.evolve.evolve_unit,
                            uuid = "evo:" .. tostring(unitObj.uuid),
                            xp = unitObj.xp,
                            traits = unitObj.traits,
                            trait_stats = unitObj.trait_stats,
                            further_modifiers = unitObj.further_modifiers
                        }
                    })
                end
            end
        end
    end
    return list
end

function Simulator.levelFor(mode)
    local value = Brain.simCal[mode.key]
    if mode.kind == "daily" then
        local live = Brain.live.daily
        if not live or Modes.rotation(mode) ~= tostring(live.uuid) then return nil end
        if live.ld then return live.ld, live.challenge end
        local calibration = Brain.simCal[Simulator.calKey("dc", {}, nil, live.uuid)]
        return calibration and calibration.ld, live.challenge
    end
    if mode.kind == "challenge" then
        value = Brain.simCal[Simulator.calKey("ch", {id = mode.level}, mode.challenge)]
    end
    if Hunt.is(mode.level) and Brain.live.event and Brain.live.event.ld then
        return Brain.live.event.ld, nil
    end
    local value2 = mode.kind ~= "challenge" or (value and type(value.ld) == "table" and value.ld.id == mode.level and value.ch == mode.challenge)
    if value and type(value.ld) == "table" and value2 then
        return value.ld, value.ch
    end
    if mode.kind == "challenge" and Core.Levels [mode.level] then
        local slim = Simulator.slim(Core.Levels [mode.level])
        slim._difficulty = "Hard"
        slim._gamemode = "challenge"
        slim._challenge = mode.challenge
        return slim, mode.challenge
    end
    if Core.Levels [mode.level] then
        local slim = Simulator.slim(Core.Levels [mode.level])
        slim._difficulty = mode.diff
        slim._gamemode = slim._OVERRIDE_GAMEMODE or ((mode.kind == "raid" or mode.kind == "artifact") and "raid") or (slim.infinite and "infinite") or "story"
        return slim, nil
    end
end

function Simulator.slots(team)
    local slots = {
    }
    for index, unit in ipairs(team) do
        slots [index] = {
            name = Units.name(unit.unit_id),
            role = Units.roleName(unit.unit_id)
        }
    end
    return slots
end

function Simulator.finishProgress()
    if Simulator.progress then
        Simulator.progress.running, Simulator.progress.frac, Simulator.progress.at = false, 1, Utils.now()
    end
end

-- Lines for planner.log about units players ask for by name (Homura and her evolved form).
function Simulator.namedNotes(pool, team)
    local lines, owned = {
    }, false
    local session = Core.session()
    for _, id in ipairs(Simulator.NAMED_SUPPORTS) do
        for _, unit in pairs(session and session.profile_data.collection.owned_units or {
        }) do
            if unit.unit_id == id then
                owned = true
                table.insert(lines, "Unit check · " .. Simulator.unitNote(id, pool, team))
                break
            end
        end
    end
    if not owned then
        table.insert(lines, "Unit check · Homura (ids homura, homura_evolved): not owned, so not planned")
    end
    return lines
end

-- [Removed in v2.5: Simulator.compareFusion and Simulator.testNamekFusion were uncalled diagnostic functions]

-- How one side of a comparison ended, in a few words.
function Simulator.sideText(side, total, endless)
    if not side then return "not simulated" end
    local result = side.won and (endless and string.format("lasts past wave %d", side.wave or 0) or string.format("clears all %d waves", total or side.wave or 0))
        or string.format("reaches wave %d", side.wave or 0)
    local fusion = side.fusionWave and (" · Fused Hero at wave " .. tostring(side.fusionWave)) or (side.progress and (" · " .. side.progress) or "")
    return result .. fusion
end

function Simulator.compareTeams(level, current, proposed, currentRun, proposedRun, options)
    options = options or {
    }
    if currentRun.won ~= proposedRun.won then
        return proposedRun.won, proposedRun.won and "proposed team clears at normal HP" or "proposed team loses at normal HP"
    end
    if currentRun.wave ~= proposedRun.wave then
        local better = proposedRun.wave > currentRun.wave
        return better, string.format("normal HP: proposed wave %d, current wave %d", proposedRun.wave, currentRun.wave)
    end
    -- Both clear: when both do it with room to spare, the faster one farms more an hour. The short-mode
    -- farm rule (options.prefer) is the user's choice and is not overruled by speed.
    if currentRun.won and proposedRun.won and not options.prefer and Simulator.farmsPerHour(level) then
        local curMin, propMin = Simulator.runMinutes(currentRun), Simulator.runMinutes(proposedRun)
        if math.abs(curMin - propMin) >= math.max(5 / 60, Simulator.FASTER * math.max(curMin, propMin))
            and Simulator.safeWin(level, Simulator.teamFrom(current, level.map), options.currentOpts)
            and Simulator.safeWin(level, Simulator.teamFrom(proposed, level.map), options.proposedOpts) then
            local better = propMin < curMin
            return better, string.format("both clear with room to spare (×%.1f enemy HP): proposed %.1f min a run, current %.1f min (lobby included): %s",
                Simulator.SAFE_MUL, propMin, curMin, better and Simulator.perHourText(propMin, curMin) .. " with the proposed team" or Simulator.perHourText(curMin, propMin) .. " with the current team")
        end
    end
    local currentWins, currentWaves = Simulator.exam(level, current, options.currentOpts)
    local proposedWins, proposedWaves = Simulator.exam(level, proposed, options.proposedOpts)
    if proposedWins ~= currentWins or math.abs(proposedWaves - currentWaves) > 0.001 then
        local better = proposedWins > currentWins or (proposedWins == currentWins and proposedWaves > currentWaves)
        return better, string.format("stress test: proposed %d wins and %.1f wave points, current %d wins and %.1f wave points",
            proposedWins, proposedWaves, currentWins, currentWaves)
    end
    if options.prefer then
        -- Same result at normal HP and under stress: the short-mode rule decides, not a few seconds.
        return true, options.prefer
    end
    if currentRun.won and proposedRun.won then
        local saved = (currentRun.seconds or currentRun.t) - proposedRun.t
        if math.abs(saved) >= math.max(5, currentRun.seconds * 0.03) then
            return saved > 0, string.format("same clear and stress result: proposed %.0fs, current %.0fs", proposedRun.t, currentRun.seconds)
        end
    end
    return #proposed > #current, #proposed > #current and "same performance with more equipped slots" or "the two teams performed about the same"
end

function Simulator.plan(mode, arg2, arg3, arg4, freshSearch)
    local revision = Modes._teamRevision
    local fixed = Modes.hasOwnTeam(mode)
    if fixed then
        local units, why = Modes.ownUnits(mode)
        if not units then return nil, why end
        arg4, arg2 = units, false
    end
    local function stale()
        return revision ~= Modes._teamRevision or fixed ~= Modes.hasOwnTeam(mode)
    end
    local trace = arg2 and Simulator.planTrace(tostring(mode.label or mode.key))
    if trace then trace(freshSearch and "Started manual search" or "Started automatic search") end
    local levelFor, levelFor2 = Simulator.levelFor(mode)
    if mode.ldOverride then
        levelFor = mode.ldOverride
    end
    if not levelFor then
        if trace then trace("Stopped: level data is unavailable") end
        Simulator.finishProgress()
        return nil
    end
    local mod = mode.mod or (mode.kind == "daily" and Brain.live.daily and Brain.live.daily.mod) or Modes.levelMod(mode.level)
    local rotation = Modes.rotation(mode)
    local info = Simulator.info(levelFor, mode.key, levelFor2, mod, rotation)
    info._memoKey = tostring(mode.key) .. ":" .. tostring(rotation or "") .. ":" .. tostring(info.map)
    local report = Simulator.newReport(info, tostring(mode.label or mode.key))
    local arg42 = arg4
    if not arg42 then
        arg42 = {
        }
        for _, value in ipairs(Units.equipped()) do
            table.insert(arg42, value.u)
        end
    end
    local profile = Simulator.profileSig(arg42)
    local teamFrom = Simulator.teamFrom(arg42, info.map)
    if trace then trace("Simulating equipped lineup: " .. Simulator.lineupNames(arg42)) end
    local evaluate = Simulator.evaluate(info, teamFrom)
    if trace then
        trace(string.format("Baseline: wave %d/%d · %.0fs · clear=%s", evaluate.wave, evaluate.total, evaluate.seconds, tostring(evaluate.won)))
    end
    local ok, res = pcall(Simulator.zoneChoice, info, teamFrom, evaluate.p >= 0.92 and 1.7 or evaluate.p >= 0.7 and 1.3 or 1, false)
    if ok and res then
        info.zone = true
        evaluate = Simulator.evaluate(info, teamFrom)
        evaluate.zone = true
        evaluate.margin = evaluate.margin .. " with the kill box"
    end
    if evaluate.fusionWave then
        evaluate.margin = evaluate.margin .. " · Fused Hero at wave " .. tostring(evaluate.fusionWave)
    end
    evaluate.sig = Simulator.sig(arg42)
    evaluate.profile, evaluate.rotation = profile, rotation
    evaluate.trust = Simulator.trust(info, teamFrom)
    evaluate.label = mode.label
    evaluate.calibrated = (tonumber(info.cal.n) or 0) > 0
    if stale() or (fixed and Modes.ownProfile(mode) ~= profile) then return nil, "mode team changed; recalculate" end
    Brain.simRes [mode.key] = evaluate
    if fixed then
        Brain.simTeam[mode.key] = nil
        evaluate.teamReason = "saved mode team; no replacements"
    end
    evaluate.aliveAt = nil
    App.log(1, "SIM", string.format("%s: your team %s (%s, %s)", mode.label, evaluate.margin, evaluate.calibrated and "calibrated on real runs" or "not calibrated yet", evaluate.trust and string.format("real/sim HP %.2f", evaluate.trust.ratio) or "no same-team run to compare"))
    local rec = Modes.rec(mode.key)
    local savedWinner = rec.winTeam
    local sameRotation = (mode.key ~= "ch" and mode.key ~= "dc") or (rotation and rec.winRotation == rotation)
    if Config.simTeams and arg2 and not freshSearch and sameRotation and Modes.provenWinner(mode, rec.winProfile)
        and type(savedWinner) == "table" and # savedWinner > 0 then
        local session = Core.session()
        local list = {
        }
        for _, value in ipairs(rec.winTeam) do
            local unitObj = session.collection:get_unit_by_uuid(value)
            if unitObj then
                table.insert(list, unitObj)
            end
        end
        if # list == # savedWinner and Simulator.profileSig(list) == rec.winProfile then
            local teamFrom = Simulator.teamFrom(list, info.map)
            local simResult = Simulator.run(info, teamFrom, {
                hpMul = 1
            })
            local trust = Simulator.trust(info, teamFrom)
            local flag = trust and not trust.ok
            if not evaluate.won or (evaluate.trust and not evaluate.trust.ok) then
                local list2, list3 = {
                }, {
                }
                for _, item in ipairs(list) do
                    table.insert(list2, Units.name(item.unit_id))
                    table.insert(list3, item.unit_id)
                end
                if stale() then return nil, "mode team changed; recalculate" end
                Brain.simTeam [mode.key] = {
                    uuids = rec.winTeam,
                    names = list2,
                    ids = list3,
                    won = true,
                    wave = info.total,
                    better = rec.winProfile ~= profile,
                    profile = profile,
                    targetProfile = rec.winProfile,
                    rotation = rotation,
                    prediction = { p = 0.7, wave = info.total, won = true, margin = "won this match with the same team" },
                    cur = {
                        won = evaluate.won,
                        wave = evaluate.wave
                    },
                    at = os.time(),
                    label = mode.label,
                    base = evaluate.sig,
                    why = "the team that won here last run, no search",
                    whyShort = "won here last run with this team",
                    view = {
                        label = mode.label,
                        map = tostring(info.map),
                        total = info.total,
                        endless = report.endless,
                        short = report.short,
                        current = Simulator.slots(arg42),
                        currentWave = evaluate.wave,
                        currentWon = evaluate.won,
                        planned = Simulator.slots(list),
                        plannedWave = info.total,
                        plannedWon = true,
                        better = rec.winProfile ~= profile,
                        why = "won here last run with this team (no new search)",
                        rows = {
                        }
                    }
                }
                App.log(1, "SIM", string.format("%s: the team that won here last run plays again (%s): %s, and real runs won %d in a row", mode.label, table.concat(list2, ", "), flag and string.format((trust.ratio or 0) < 0.1 and "the simulator is off ×%.2f against real runs here" or "the simulator is off ×%.1f against real runs here", trust.ratio or 0) or (simResult.won and "the simulator also predicts a win" or string.format("the simulator calls it a loss at wave %d", simResult.wave)), rec.winTeamN or 1))
                if trace then trace("Finished: selected a team with a recorded real win") end
                Simulator.finishProgress()
                return evaluate
            end
        end
    end
    if Config.simTeams and arg2 then
        if trace then trace("Reading the unit collection and ranking candidates") end
        local pool = Simulator.pool(mod, info)
        if trace then trace(string.format("Pool: %d priority candidates · %d reserve candidates", #pool, #(pool.rest or {}))) end
        local budget, tierLine = arg3 or 25, nil
        if Simulator.TIER.SHARE > 0 then
            local t0 = Utils.now()
            local okT, measured, left = pcall(Simulator.tierUpdate, info, arg42, pool, budget * Simulator.TIER.SHARE)
            local spent = Utils.now() - t0
            pool = Simulator.pool(mod, info)
            tierLine = okT and Simulator.tierText(info.key, true) or nil
            if trace then
                trace(okT and string.format("Tier list: %d of your units measured in %.1fs, %d to go", measured or 0, spent, left or 0) or ("Tier list skipped: " .. tostring(measured)))
            end
            if okT and tierLine then
                App.log(1, "TIER", tostring(mode.label) .. ": " .. tierLine)
            end
        end
        local ok, res, res2, res3, res32, fusionTeam, fusionRun, fusionOpts = pcall(Simulator.bestTeam, info, arg42, pool, budget, trace, report)
        if ok and res then
            local candidate = Simulator.teamFrom(res, info.map)
            local fusionRun2 = Simulator.run(info, candidate, { hpMul = 1 })
            -- `strategy` is how the chosen lineup buys: nil = regular, fusionSave = yen kept for Carrot + Vego.
            local strategy
            local fusion = report.fusion
            local fusionPicked = false
            if fusionRun and (fusionOpts or Simulator.profileSig(fusionTeam) ~= Simulator.profileSig(res)) then
                if trace then trace("Comparing the Fusion lineup with the best regular lineup") end
                local normal = { won = fusionRun2.won, wave = fusionRun2.wave, seconds = fusionRun2.t }
                local fusionBetter, fusionWhy = Simulator.compareTeams(info, res, fusionTeam, normal, fusionRun, { proposedOpts = fusionOpts })
                if fusionBetter then
                    res, fusionRun2, strategy, fusionPicked = fusionTeam, fusionRun, fusionOpts, true
                    candidate = Simulator.teamFrom(res, info.map)
                    local stressOpts = { hpMul = res3 }
                    for key, option in pairs(strategy or {}) do stressOpts[key] = option end
                    res2 = Simulator.run(info, candidate, stressOpts)
                    fusion.note = tostring(fusion.note) .. " · ahead of the best regular lineup (" .. fusionWhy .. ")"
                else
                    fusion.note = tostring(fusion.note) .. " · the best regular lineup stays (" .. fusionWhy .. ")"
                end
            elseif fusionRun then
                fusionPicked = true
                fusion.note = tostring(fusion.note) .. " · this is also the lineup the regular search found"
            end
            local flag = Simulator.profileSig(res) ~= profile
            local str = ""
            local keptCurrent = false
            if flag or strategy then
                if trace then trace("Comparing the equipped team with: " .. Simulator.lineupNames(res)) end
                local better, reason = Simulator.compareTeams(info, arg42, res, evaluate, fusionRun2, {
                    proposedOpts = strategy,
                    prefer = (not fusionPicked and flag) and report.priority or nil
                })
                if fusionRun2.fusionWave then
                    reason = reason .. " · proposed Fused Hero at wave " .. tostring(fusionRun2.fusionWave)
                end
                evaluate.teamReason = reason
                App.log(1, "SIM", mode.label .. ": " .. reason .. (better and (flag and " · proposed team selected" or " · same team, yen is saved for Fusion") or " · current team kept"))
                if better then
                    str = " · " .. reason
                else
                    -- The real run, not the summary: later comparisons read its clear time.
                    res, flag, strategy, keptCurrent = arg42, false, nil, true
                    fusionRun2 = Simulator.run(info, teamFrom, { hpMul = 1 })
                    candidate = teamFrom
                end
            else
                evaluate.teamReason = "the team search kept your current lineup"
            end
            -- Close the comparison: one lineup is CHOSEN, the rest keep the reason they lost.
            do
                local chosenNamed = false
                if fusionPicked and not keptCurrent and fusion.status == "worked" then
                    fusion.status = "chosen"
                elseif fusion.status == "worked" and keptCurrent then
                    fusion.note = tostring(fusion.note) .. " · your equipped team does as well or better"
                end
                for _, row in ipairs(report.rows) do
                    if row.status == "chosen" then
                        row.status = "worked"
                        row.note = (row.note and (row.note .. " · ") or "") .. (keptCurrent and "your equipped team does as well or better" or "the Fusion lineup does better")
                    end
                end
                if fusion.row and fusion.row.entry and fusion.status == "chosen" then
                    fusion.row.entry.status, chosenNamed = "chosen", true
                end
                if not chosenNamed then
                    for _, row in ipairs(report.rows) do
                        local source = row.kind ~= "fusion" and row.team
                        if source and not chosenNamed and row.status ~= "failed" and row.status ~= "untested" and source == Simulator.lineupNames(res) then
                            row.status, chosenNamed = "chosen", true
                            row.note = Simulator.whyLine(info, res, fusionRun2) or row.note
                        end
                    end
                end
                if not chosenNamed then
                    table.insert(report.rows, 1, {
                        name = keptCurrent and "equipped team" or "planned lineup",
                        kind = "current",
                        status = "chosen",
                        team = Simulator.lineupNames(res),
                        wave = fusionRun2.wave,
                        won = fusionRun2.won,
                        fusionWave = fusionRun2.fusionWave,
                        note = evaluate.teamReason
                    })
                end
            end
            local whyShort = (not keptCurrent and not fusionPicked and (report.priority or report.faster)) or Simulator.whyLine(info, res, fusionRun2) or evaluate.teamReason
            if trace then
                for _, line in ipairs(Simulator.reportLines(report, info)) do trace(line, true) end
                for _, line in ipairs(Simulator.buffNotes(res, fusionRun2)) do trace(line, true) end
                for _, line in ipairs(Simulator.namedNotes(pool, res)) do trace(line, true) end
            end
            local forecast
            if flag then
                if not info.zone then
                    local okZ, wantZ = pcall(Simulator.zoneChoice, info, candidate, fusionRun2.won and 1.3 or 1, false)
                    if okZ and wantZ then
                        local zLevel = table.clone(info)
                        zLevel.zone = true
                        forecast = Simulator.evaluate(zLevel, candidate, strategy)
                        forecast.zone = true
                        forecast.margin = forecast.margin .. " with the kill box"
                    end
                end
                if not forecast then
                    forecast = Simulator.evaluate(info, candidate, strategy)
                end
                forecast.trust = Simulator.trust(info, candidate)
                forecast.calibrated = evaluate.calibrated
                forecast.aliveAt = nil
                evaluate.playing = fusionRun2.won and "the best team wins" or string.format("the best team reaches wave %d of %d", fusionRun2.wave, info.total)
                if fusionRun2.fusionWave then
                    evaluate.playing = evaluate.playing .. " · Fused Hero at wave " .. tostring(fusionRun2.fusionWave)
                end
            end
            local list, list2 = {
            }, {
            }
            for _, unit in ipairs(res) do
                table.insert(list, unit.uuid)
                table.insert(list2, Units.name(unit.unit_id))
            end
            local list3 = {
            }
            for _, unitData in ipairs(res) do
                table.insert(list3, unitData.unit_id)
            end
            if stale() then return nil, "mode team changed; recalculate" end
            Brain.simTeam [mode.key] = {
                uuids = list,
                names = list2,
                ids = list3,
                won = fusionRun2.won,
                wave = fusionRun2.wave,
                better = flag,
                cur = {
                    won = evaluate.won,
                    wave = evaluate.wave
                },
                at = os.time(),
                label = mode.label,
                base = evaluate.sig,
                profile = profile,
                targetProfile = Simulator.profileSig(res),
                rotation = rotation,
                prediction = forecast,
                why = evaluate.teamReason,
                whyShort = whyShort,
                -- Read by the match: buy only for Carrot + Vego while the defense holds.
                strategy = strategy and strategy.fusionSave and { fusionSave = true } or nil,
                view = {
                    label = mode.label,
                    map = tostring(info.map),
                    total = info.total,
                    endless = report.endless,
                    short = report.short,
                    current = Simulator.slots(arg42),
                    currentWave = evaluate.wave,
                    currentWon = evaluate.won,
                    currentFusion = evaluate.fusionWave,
                    planned = Simulator.slots(res),
                    plannedWave = fusionRun2.wave,
                    plannedWon = fusionRun2.won,
                    plannedFusion = fusionRun2.fusionWave,
                    better = flag,
                    saving = strategy and strategy.fusionSave or nil,
                    why = whyShort,
                    detail = evaluate.teamReason,
                    tiers = Simulator.tierText(info.key),
                    fusion = {
                        status = report.fusion.status,
                        note = report.fusion.note
                    },
                    rows = (function()
                        local rows = {
                        }
                        for index = 1, math.min(18, # report.rows) do
                            rows [index] = report.rows [index]
                        end
                        return rows
                    end)()
                }
            }
            App.log(1, "SIM", string.format("%s: best team from your units %s (%s)%s", mode.label, fusionRun2.won and "wins" or ("reaches wave " .. fusionRun2.wave), table.concat(list2, ", "), flag and (string.format(" · it plays · against enemies ×%.1f: %s at wave %d, yours %s at wave %d", res3, res2.won and "wins" or "falls", res2.wave, res32.won and "wins" or "falls", res32.wave) .. str) or " · the same as yours"))
            if trace then trace("Decision: " .. (flag and "new lineup · " or (strategy and "keep equipped, save yen for Fusion · " or "keep equipped · ")) .. evaluate.teamReason .. (whyShort and whyShort ~= evaluate.teamReason and (" · " .. whyShort) or "")) end
            if trace then trace("Checking available evolutions") end
            local list = {
            }
            for _, evolution in ipairs(Simulator.evolutions()) do
                local str
                if Units.hidden(evolution.from) or Units.hidden(evolution.to) then
                    str = "strength unknown (the game shows its upgrades only in a match)"
                else
                    local res2 = table.clone(res)
                    local flag = false
                    for i, unitData in ipairs(res2) do
                        if unitData.unit_id == evolution.from then
                            res2 [i] = evolution.evolved
                            flag = true
                        end
                    end
                    if not flag then
                        local value, huge = nil, math.huge
                        for i, unitData in ipairs(res2) do
                            if not Units.isFarm(unitData.unit_id) then
                                local ok, res = pcall(Units.score, unitData, mod)
                                if ok and res < huge then
                                    value, huge = i, res
                                end
                            end
                        end
                        if value then
                            res2 [value] = evolution.evolved
                        end
                    end
                    local simResult = Simulator.run(info, Simulator.teamFrom(res2, info.map), {
                        hpMul = 1
                    })
                    if simResult.won and not fusionRun2.won then
                        str = "turns " .. mode.label .. " into a win"
                    elseif simResult.wave > fusionRun2.wave then
                        str = string.format("%s: reaches wave %d instead of %d", mode.label, simResult.wave, fusionRun2.wave)
                    elseif simResult.won and fusionRun2.won and simResult.t < fusionRun2.t - 6 then
                        str = string.format("clears %s %.1f min faster", mode.label, (fusionRun2.t - simResult.t) / 60)
                    else
                        str = fusionRun2.won and ("no difference in " .. mode.label .. " (already a win)") or ("doesn't help in " .. mode.label)
                    end
                end
                table.insert(list, {
                    from = Units.name(evolution.from),
                    to = Units.name(evolution.to),
                    ready = # evolution.missing == 0,
                    missing = evolution.missing [1],
                    gain = str,
                    mode = mode.label
                })
            end
            Brain.simEvo = list
        elseif not ok then
            if trace then trace("Stopped: " .. tostring(res)) end
            Simulator.finishProgress()
            return evaluate, tostring(res)
        end
    elseif trace then
        trace("Team selection is disabled")
    end
    App.saveSoon()
    if trace then trace("Finished") end
    Simulator.finishProgress()
    return evaluate
end
Dungeon.T = {
    CURSE = 0,
    SHOP = 1,
    MONEY = 2,
    GOLD = 3,
    CHEST = 4,
    BOSS = 5,
    OPEN = 6,
    SHRINE = 7
}
Dungeon.TAG_NAMES = {
    [0] = "curse",
    [1] = "shop",
    [2] = "coins",
    [3] = "rare chest",
    [4] = "chest",
    [5] = "final boss",
    [6] = "chest opening",
    [7] = "shrine"
}
Dungeon.KNOWN = {
    _started = true,
    _items = true,
    selected_next = true,
    next = true,
    _resources = true
}
Dungeon.ROOMS = 20

function Dungeon.core()
    if not Dungeon._core then
        Dungeon._core = Core.core("DungeonServiceCore")
    end
    return Dungeon._core
end

function Dungeon.data()
    local prof = Core.prof()
    return prof and type(prof.dungeon_data) == "table" and prof.dungeon_data or nil
end

function Dungeon.item(id)
    local core = Dungeon.core()
    return id and core and type(core.ITEMS) == "table" and core.ITEMS [id] or nil
end

function Dungeon.isCurse(itemKey)
    return tostring(itemKey):sub(1, 7) == "_curse_"
end

function Dungeon.tags(arg1)
    local list = {
    }
    for key, value in pairs(type(arg1) == "table" and type(arg1._t) == "table" and arg1._t or {
    }) do
        if value then
            list [tonumber(key) or - 1] = true
        end
    end
    return list
end

function Dungeon.list(next2)
    local list = {
    }
    for key, value in pairs(type(next2) == "table" and next2 or {
    }) do
        local key2 = tonumber(key)
        if key2 and type(value) == "table" then
            table.insert(list, {
                choice = key2,
                key = key,
                r = value,
                tags = Dungeon.tags(value),
                d = tonumber(value._d) or 1
            })
        end
    end
    table.sort(list, function(arg1, arg2)
        return arg1.choice < arg2.choice
    end)
    return list
end

function Dungeon.rooms(arg1)
    return Dungeon.list(arg1 and arg1.next)
end

function Dungeon.after(arg1, choice)
    return Dungeon.list(arg1 and type(arg1.next) == "table" and arg1.next ["next" .. tostring(choice)] or nil)
end

function Dungeon.depth(arg1)
    local room = Dungeon.rooms(arg1) [1]
    return room and room.d or nil
end

function Dungeon.items(arg1)
    local list = {
    }
    for _, item in pairs(arg1 and type(arg1._items) == "table" and arg1._items or {
    }) do
        local id = type(item) == "table" and item.id or (type(item) == "string" and item) or nil
        if id then
            list [id] = (list [id] or 0) + 1
        end
    end
    return list
end

function Dungeon.curses(arg1)
    local count = 0
    for itemKey, item in pairs(Dungeon.items(arg1)) do
        if Dungeon.isCurse(itemKey) then
            count = count + item
        end
    end
    return count
end

function Dungeon.res(arg1)
    local resources = arg1 and type(arg1._resources) == "table" and arg1._resources or {
    }
    return tonumber(resources.money) or 0, tonumber(resources.treasure) or 0, tonumber(resources.treasure_gold) or 0
end

function Dungeon.lives(arg1)
    local lives = tonumber(arg1 and arg1.lives) or tonumber(arg1 and type(arg1.selected_next) == "table" and arg1.selected_next.lives)
    if lives then
        if lives ~= Brain.dg.lives then
            Brain.dg.lives = lives
            App.saveSoon()
        end
        return lives
    end
    local lives = tonumber(Brain.dg.lives)
    return (lives and lives > 0) and lives or 5
end

function Dungeon.luck(arg1)
    local core = Dungeon.core()
    local ok, res = pcall(function()
        return core.calculate_luck_multiplier(arg1)
    end)
    return ok and tonumber(res) or 1
end

function Dungeon.tagText(tags)
    local list = {
    }
    for i = 0, 7 do
        if tags [i] then
            table.insert(list, Dungeon.TAG_NAMES [i])
        end
    end
    return # list > 0 and table.concat(list, " + ") or "fight only"
end

function Dungeon.share(arg1)
    local count, count2 = 0, 0
    for _, value in ipairs(Units.equipped()) do
        local id = value.id or (value.u and value.u.unit_id)
        if id and value.u and not Units.isFarm(id) and not Units.allyBuff(id) then
            local rows = Units.rows(id)
            local ok, res = pcall(Units.dps, value.u, rows and rows.max or 0, nil)
            res = ok and tonumber(res) or 0
            local _, types2 = Units.types(id)
            count = count + res
            if types2 == arg1 or types2 == arg1 .. "_damage" then
                count2 = count2 + res
            end
        end
    end
    return count > 0 and count2 / count or 0.5
end

function Dungeon.itemValue(id, arg2)
    local item = Dungeon.item(id)
    if not item or Dungeon.isCurse(id) then
        return 0
    end
    local count = 0
    if tonumber(item.luck_increase) then
        count = count + 300 * item.luck_increase
    end
    if tonumber(item.star_remnant_chest_add) then
        count = count + 150 * item.star_remnant_chest_add
    end
    if id == "philospher_stone" then
        local _, res2 = Dungeon.res(arg2)
        count = count + 60 + 25 * res2
    end
    if id == "chest_mock_item" then
        count = count + 120
    end
    for _, waveModifierEffect in pairs(type(item.wave_modifier_effects) == "table" and item.wave_modifier_effects or {
    }) do
        local amount = math.abs(tonumber(waveModifierEffect.amount) or 0)
        if waveModifierEffect.type == "stat_mul" and waveModifierEffect.stat == "damage" then
            count = count + 100 * amount
        elseif waveModifierEffect.type == "stat_mul" and waveModifierEffect.stat == "attack_cooldown" then
            count = count + 100 * amount / math.max(0.2, 1 - amount)
        elseif waveModifierEffect.type == "stat_mul" and waveModifierEffect.stat == "range" then
            count = count + 50 * amount
        elseif waveModifierEffect.type == "stat_attr_add" and waveModifierEffect.stat == "_dmg_mul_physical" then
            count = count + 100 * amount * Dungeon.share("physical")
        elseif waveModifierEffect.type == "stat_attr_add" and waveModifierEffect.stat == "_dmg_mul_magic" then
            count = count + 100 * amount * Dungeon.share("magic")
        elseif waveModifierEffect.type == "stat_attr_add" and waveModifierEffect.stat == "_dmg_mul_true_damage" then
            count = count + 100 * amount * Dungeon.share("true")
        elseif waveModifierEffect.type == "stat_add" and waveModifierEffect.stat == "physical_crit_chance" then
            count = count + 60 * amount * Dungeon.share("physical")
        elseif waveModifierEffect.type == "boss_damage" then
            count = count + 40 * amount
        elseif waveModifierEffect.type == "enemy_speedup" then
            count = count + 80 * amount
        elseif waveModifierEffect.type == "unit_cost" then
            count = count + 80 * amount
        end
    end
    return count
end
Dungeon.CURSE_COST = {
    _curse_money = 0.5,
    _curse_shop = 0.5,
    _curse_health = 0.5,
    _curse_speed = 0.5,
    _curse_regen = 0.5,
    _curse_shield = 1,
    _curse_explode = 1.5,
    _curse_random = 2,
    _curse_super_health = 1,
    _curse_super_speed = 1,
    _curse_super_regen = 1,
    _curse_super_armored = 3,
    _curse_super_burst = 3,
    _curse_super_explode = 3,
    _curse_super_chaos = 3
}

function Dungeon.curseCost(roomCurse)
    if roomCurse == "_curse_fly" then
        local count, count2 = 0, 0
        for _, value in ipairs(Units.equipped()) do
            local id = value.id or (value.u and value.u.unit_id)
            if id and not Units.isFarm(id) then
                count = count + 1
                local ok, res = pcall(Units.airFrom, id)
                if ok and res then
                    count2 = count2 + (res == 0 and 1 or 0.5)
                end
            end
        end
        return 1 + 2 * (count > 0 and 1 - count2 / count or 0.5)
    end
    return Dungeon.CURSE_COST [roomCurse] or 1.5
end

function Dungeon.roomValue(room, res)
    local tags, d = room.tags, room.d
    local count = 0
    if tags [Dungeon.T.GOLD] then
        count = count + 12
    end
    if tags [Dungeon.T.CHEST] then
        count = count + 4
    end
    if tags [Dungeon.T.MONEY] then
        count = count + (d <= 15 and 2 or 0.5)
    end
    if tags [Dungeon.T.SHOP] then
        if d >= 10 and d <= 15 then
            count = count + (res >= 300 and 5 or 1)
        else
            count = count + (res >= 300 and (d > 15 and 3 or 1) or 0.3)
        end
    end
    if tags [Dungeon.T.SHRINE] then
        count = count + 1.5
    end
    if tags [Dungeon.T.CURSE] then
        count = count - Dungeon.curseCost(Dungeon.roomCurse(room.r))
    end
    return count
end

function Dungeon.mod(l)
    local info = {
        weak = {
        },
        strong = {
        }
    }
    for _, value in pairs(type(l) == "table" and type(l._weak_against) == "table" and l._weak_against or {
    }) do
        if type(value) == "table" and value.damage_type then
            info.weak [value.damage_type] = Modes.weakAmp(value.amplification)
        end
    end
    for _, value in pairs(type(l) == "table" and type(l._strong_against) == "table" and l._strong_against or {
    }) do
        info.strong [type(value) == "table" and value.damage_type or value] = true
    end
    return (next(info.weak) or next(info.strong)) and info or nil
end

function Dungeon.roomCurse(r)
    local t = type(r) == "table" and type(r._t) == "table" and r._t or {
    }
    local value = t [0] or t ["0"]
    return type(value) == "table" and value.id or nil
end

function Dungeon.fx(arg1, roomCurse, arg3)
    local info = {
        dmg = 1,
        cd = 1,
        range = 1,
        cost = 1,
        hp = 1,
        speed = 1,
        regen = 0,
        crit = 0,
        kinds = {
        },
        shield = 0,
        fly = 0
    }
    local items = Dungeon.items(arg1)
    if roomCurse and Dungeon.item(roomCurse) then
        items [roomCurse] = (items [roomCurse] or 0) + 1
    end
    for _, extra in ipairs(type(arg3) == "table" and arg3 or {
        arg3
    }) do
        if extra and Dungeon.item(extra) then
            items [extra] = (items [extra] or 0) + 1
        end
    end
    for itemKey, item in pairs(items) do
        local item2 = Dungeon.item(itemKey)
        for _, waveModifierEffect in pairs(type(item2 and item2.wave_modifier_effects) == "table" and item2.wave_modifier_effects or {
        }) do
            local amount = (tonumber(waveModifierEffect.amount) or 0) * item
            if waveModifierEffect.type == "stat_mul" and waveModifierEffect.stat == "damage" then
                info.dmg = info.dmg + amount
            elseif waveModifierEffect.type == "stat_mul" and waveModifierEffect.stat == "attack_cooldown" then
                info.cd = info.cd + amount
            elseif waveModifierEffect.type == "stat_mul" and waveModifierEffect.stat == "range" then
                info.range = info.range + amount
            elseif waveModifierEffect.type == "stat_attr_add" and tostring(waveModifierEffect.stat):sub(1, 9) == "_dmg_mul_" then
                local stat = tostring(waveModifierEffect.stat):sub(10)
                info.kinds [stat] = (info.kinds [stat] or 0) + amount
            elseif waveModifierEffect.type == "stat_add" and waveModifierEffect.stat == "physical_crit_chance" then
                info.crit = info.crit + amount
            elseif waveModifierEffect.type == "unit_cost" then
                info.cost = info.cost + amount
            elseif waveModifierEffect.type == "enemy_stat_mul" and waveModifierEffect.stat == "health" then
                info.hp = info.hp + amount
            elseif waveModifierEffect.type == "enemy_speedup" then
                info.speed = info.speed + amount
            elseif waveModifierEffect.type == "enemy_regen" then
                info.regen = info.regen + amount
            elseif waveModifierEffect.type == "enemy_shield" then
                info.shield = info.shield + amount
            elseif waveModifierEffect.type == "enemy_passive_chance" and waveModifierEffect.passive == "Flying" then
                info.fly = info.fly + amount
            end
        end
    end
    info.cd, info.cost, info.speed = math.max(0.1, info.cd), math.max(0.1, info.cost), math.max(0.1, info.speed)
    return info
end

function Dungeon.fxText(fx)
    local list = {
    }
    local function helper(arg1, arg2)
        if math.abs(arg2 - 1) > 0.001 then
            table.insert(list, string.format("%s ×%.2f", arg1, arg2))
        end
    end
    helper("damage", fx.dmg)
    helper("cooldown", fx.cd)
    helper("range", fx.range)
    helper("unit prices", fx.cost)
    for kindKey, kind in pairs(fx.kinds) do
        table.insert(list, string.format("%s +%d%%", kindKey, math.floor(kind * 100 + 0.5)))
    end
    if fx.crit > 0 then
        table.insert(list, string.format("physical crit +%d%%", math.floor(fx.crit * 100 + 0.5)))
    end
    helper("enemy HP", fx.hp)
    helper("enemy speed", fx.speed)
    if fx.regen > 0 then
        table.insert(list, string.format("enemy regen %d%%", math.floor(fx.regen * 100 + 0.5)))
    end
    if fx.shield > 0 then
        table.insert(list, string.format("enemy shield +%d", math.floor(fx.shield + 0.5)))
    end
    if fx.fly > 0 then
        table.insert(list, string.format("flyers +%d%%", math.floor(fx.fly * 100 + 0.5)))
    end
    return # list > 0 and table.concat(list, ", ") or "none"
end

function Dungeon.sim(arg1, arg2, arg3, noOwn)
    if not Config.sim or type(arg1.r._l) ~= "table" then
        return nil
    end
    if type(arg2) == "table" then
        arg2 = # arg2 > 1 and arg2 or arg2 [1]
    end
    local extraText = type(arg2) == "table" and table.concat(arg2, "+") or (arg2 and tostring(arg2)) or nil
    local text = tostring(arg1.r._r or (arg1.d .. ":" .. tostring(arg1.parent or "") .. arg1.choice)) .. (extraText and ("+" .. extraText) or "") .. (arg3 and "#spread" or "") .. (noOwn and "#noown" or "")
    local value = Dungeon.data()
    local fx = Dungeon.fx(value, not noOwn and Dungeon.roomCurse(arg1.r) or nil, arg2)
    local text2 = Modes.teamSig() .. "#" .. Dungeon.fxText(fx) .. (Config.killZone ~= false and "#stack" or "")
    local value = Brain.dg.sim [text]
    if value and value.sig == text2 then
        return not value.none and value or nil
    end
    local list = {
    }
    for _, value in ipairs(Units.equipped()) do
        table.insert(list, value.u)
    end
    if # list == 0 then
        return nil
    end
    local applyFx = Simulator.applyFx(Simulator.info(Simulator.slim(arg1.r._l), "dg", nil, Dungeon.mod(arg1.r._l)), fx)
    if arg3 then
        applyFx.zone = false
    end
    local wave = Simulator.wave(applyFx, 1, true)
    if # wave == 0 then
        value = {
            none = true,
            sig = text2,
            at = os.time()
        }
    else
        local evaluate = Simulator.evaluate(applyFx, Simulator.teamFrom(list, applyFx.map))
        value = {
            p = evaluate.p,
            wave = evaluate.wave,
            won = evaluate.won,
            total = applyFx.total,
            margin = evaluate.margin,
            sig = text2,
            at = os.time()
        }
    end
    Brain.dg.sim [text] = value
    if Utils.count(Brain.dg.sim) > 100 then
        local value, at
        for key, value2 in pairs(Brain.dg.sim) do
            if not at or (value2.at or 0) < at then
                value, at = key, value2.at or 0
            end
        end
        Brain.dg.sim [value] = nil
    end
    App.saveSoon()
    return not value.none and value or nil
end

function Dungeon.priorP(d)
    local value = tostring(math.min(4, math.max(1, math.ceil(d / 5))))
    local value2 = Brain.dg.depth [value] or {
        runs = 0,
        wins = 0
    }
    local clamp = Utils.clamp(0.95 - 0.015 * d, 0.5, 0.95)
    return ((tonumber(value2.wins) or 0) + clamp * 2) / ((tonumber(value2.runs) or 0) + 2)
end

function Dungeon.winP(room, extras)
    local ratio = Dungeon.priorP(room.d)
    local ok, res = pcall(Dungeon.sim, room, extras)
    if ok and res and res.p then
        ratio = (ratio * 2 + res.p) / 3
    end
    return ratio, ok and res or nil
end

-- [Removed in v2.5: Dungeon.hopeless obsolete unreferenced function]

function Dungeon.stake(arg1)
    local _, res2, res3 = Dungeon.res(arg1)
    return res2 + 2 * res3
end

function Dungeon.curseBar(arg1, arg2)
    local stake = Dungeon.stake(arg1)
    if arg2 >= 15 or stake >= 8 then
        return 0.9, "beat them against 30% tougher enemies", stake
    end
    if arg2 >= 10 or stake >= 4 then
        return 0.6, "beat them", stake
    end
    return 0.1, "have a chance at them", stake
end

function Dungeon.blindCurse(arg1, arg2)
    return Dungeon.fxText(Dungeon.fx(arg1, arg2)) == Dungeon.fxText(Dungeon.fx(arg1))
end

function Dungeon.curseOk(roomCurse, arg2, d, arg4, after)
    local name = tostring((Dungeon.item(roomCurse) or {
    }).name or roomCurse)
    local curseBar, curseBar2, curseBar3 = Dungeon.curseBar(arg2, d)
    if curseBar > 0.2 and Dungeon.blindCurse(arg2, roomCurse) then
        return false, string.format("the simulator can't play %s, and %d chests are riding on the run", name, curseBar3)
    end
    local function helper(arg1)
        return arg1 == nil or (tonumber(arg1.p) or 1) >= curseBar
    end
    if arg4 then
        local ok, res = pcall(Dungeon.sim, arg4, nil, true)
        if ok and not helper(res) then
            return false, string.format("with %s your team wouldn't %s (this room: %s)", name, (curseBar2:gsub("them", "this room")), tostring(res.margin or "?"))
        end
    end
    if # after == 0 then
        return true
    end
    local value
    for _, value2 in ipairs(after) do
        local ok, res = pcall(Dungeon.sim, value2, roomCurse, true)
        if not ok or helper(res) then
            return true
        end
        if not value or (tonumber(res.p) or 0) > (tonumber(value.p) or 0) then
            value = res
        end
    end
    return false, string.format("with %s your team wouldn't %s (the rooms after it, at best: %s)", name, curseBar2, tostring(value and value.margin or "?"))
end

function Dungeon.curseGate(arg1, arg2)
    local roomCurse = Dungeon.roomCurse(arg1.r)
    if not roomCurse then
        return true
    end
    return Dungeon.curseOk(roomCurse, arg2, arg1.d, arg1, Dungeon.after(arg2, arg1.choice))
end

function Dungeon.payValue()
    local count, count2 = 0, 0
    for _, value in ipairs(Brain.dg.pay or {
    }) do
        if type(value.items) == "table" then
            local gems = tonumber(value.gems) or 0
            for itemKey, item in pairs(value.items) do
                if (tonumber(item) or 0) > 0 then
                    gems = gems + Modes.itemValue(itemKey, item)
                end
            end
            count, count2 = count + gems, count2 + 1
        end
    end
    if count2 < 5 then
        return nil
    end
    return count / count2 * 0.7
end

function Dungeon.pickGreedy(arg1)
    local lives = Dungeon.lives(arg1)
    local res = Dungeon.res(arg1)
    local rooms = Dungeon.rooms(arg1)
    local text = "greedy|" .. Dungeon.pickSignature(arg1)
    if Dungeon._pick and Dungeon._pick.sig == text and os.clock() - (Dungeon._pick.at or 0) < 5 then
        return Dungeon._pick.x
    end
    local value, value2
    for _, room in ipairs(rooms) do
        local roomValue = Dungeon.roomValue(room, res)
        local value3, value4
        for _, value in ipairs(Dungeon.after(arg1, room.choice)) do
            local roomValue = Dungeon.roomValue(value, res)
            if not value3 or roomValue > value3 then
                value3, value4 = roomValue, value
            end
        end
        local winP, winP2 = Dungeon.winP(room)
        local value5 = 1 - (1 - winP) ^ math.max(1, lives)
        local num = lives >= 3 and 1 or (lives == 2 and 2 or 6)
        room.p, room.sim, room.value, room.nextValue, room.nextRoom = winP, winP2, roomValue, value3 or 0, value4
        room.score = value5 * (roomValue + 0.6 * (value3 or 0)) - (1 - winP) * num
        local ok, res, res2 = pcall(Dungeon.curseGate, room, arg1)
        if ok and not res then
            room.blocked = res2
        end
        if not room.blocked and (not value or room.score > value.score) then
            value = room
        end
        if not value2 or room.score > value2.score then
            value2 = room
        end
    end
    value = value or value2
    Dungeon._pick = {
        sig = text,
        at = os.clock(),
        x = value,
        rooms = rooms
    }
    return value
end

-- ===== Dungeon path planner (2.11) =====
-- The game shows the rooms on offer and, for each, the rooms it opens next. Every path through what is shown is
-- scored in expected gems:
--   * chests are paid only if the run reaches room 20, so the chests held and won ride on surviving every room;
--   * coins, shops and shrines count once their room is cleared (the old room points, 1 point = a quarter chest);
--   * each lost try costs one Dungeon Room Value (time), counted for every room up to 20: a run that ends early
--     gives nothing back (the key is gone), so dying never looks like saved time;
--   * a curse lowers the win chance of the rooms after it (simulator), or costs its fixed price if the simulator
--     can't play it.
-- Rooms past what the game shows are estimated: average room seen at that depth, win chance from the depth prior.
Dungeon.CHEST_GEMS = 150
Dungeon.RARE_GEMS = 450
Dungeon.POINT_GEMS = 37.5
Dungeon.HOARD_GUESS = 350
Dungeon.TRIES = 5
Dungeon.CURSE_FLOOR = 0.3
Dungeon.CHEST_SAMPLES = 5
Dungeon.MAX_LAYERS = 6
Dungeon.MAX_PATHS = 40

function Dungeon.pct(x)
    return math.floor((tonumber(x) or 0) * 100 + 0.5)
end

function Dungeon.chestGems()
    local sums = {
        normal = {
            0,
            0
        },
        rare = {
            0,
            0
        }
    }
    for _, value in ipairs(type(Brain.dg.pay) == "table" and Brain.dg.pay or {
    }) do
        if type(value) == "table" and type(value.items) == "table" then
            local gems = tonumber(value.gems) or 0
            for itemKey, item in pairs(value.items) do
                if (tonumber(item) or 0) > 0 then
                    gems = gems + Modes.itemValue(itemKey, item)
                end
            end
            local sum = sums [value.rare and "rare" or "normal"]
            sum [1], sum [2] = sum [1] + gems, sum [2] + 1
        end
    end
    local need = Dungeon.CHEST_SAMPLES
    local normal = sums.normal [2] >= need and sums.normal [1] / sums.normal [2] or Dungeon.CHEST_GEMS
    local rare = sums.rare [2] >= need and sums.rare [1] / sums.rare [2] or Dungeon.RARE_GEMS
    local source
    if sums.normal [2] >= need and sums.rare [2] >= need then
        source = string.format("from %d chests you opened", sums.normal [2] + sums.rare [2])
    elseif sums.normal [2] >= need or sums.rare [2] >= need then
        source = string.format("%s from your chests, %s from the wiki", sums.normal [2] >= need and "chest" or "rare", sums.normal [2] >= need and "rare" or "chest")
    else
        source = string.format("wiki values until %d chests of a kind are opened", need)
    end
    return normal, rare, source
end

function Dungeon.roomParts(room, coins)
    local tags, d = room.tags, room.d
    local parts = {
        chest = 0,
        rare = 0,
        points = 0,
        coins = 0
    }
    if tags [Dungeon.T.GOLD] then
        parts.rare = 1
    end
    if tags [Dungeon.T.CHEST] then
        parts.chest = 1
    end
    if tags [Dungeon.T.MONEY] then
        parts.points = parts.points + (d <= 15 and 2 or 0.5)
        parts.coins = Dungeon.HOARD_GUESS
    end
    if tags [Dungeon.T.SHOP] then
        if d >= 10 and d <= 15 then
            parts.points = parts.points + (coins >= 300 and 5 or 1)
        else
            parts.points = parts.points + (coins >= 300 and (d > 15 and 3 or 1) or 0.3)
        end
    end
    if tags [Dungeon.T.SHRINE] then
        parts.points = parts.points + 1.5
    end
    if tags [Dungeon.T.CURSE] then
        parts.curse = Dungeon.roomCurse(room.r) or "?"
    end
    return parts
end

function Dungeon.curseName(curse)
    return tostring((Dungeon.item(curse) or {
    }).name or curse)
end

-- points a curse costs on top of what the simulator sees: its full fixed price if the simulator can't play it
-- (coins, shop prices, explosions…), else a share of it for the simulator's own error
function Dungeon.cursePoints(arg1, curse)
    local cost = Dungeon.curseCost(curse)
    if curse == "?" or Dungeon.blindCurse(arg1, curse) then
        return cost, true
    end
    return cost * Dungeon.CURSE_FLOOR, false
end

function Dungeon.paths(arg1)
    local paths, top, layers, reason = {}, {}, 0, nil
    local active = {}
    local function walk(container, prefix, parent)
        if reason then return end
        if type(container) ~= "table" or active[container] then
            reason = "unknown or cyclic room structure"
            return
        end
        active[container] = true
        local rooms = Dungeon.list(container)
        if #rooms == 0 then reason = "no visible rooms" end
        for key, value in pairs(container) do
            if tonumber(key) and (type(value) ~= "table" or tonumber(key) < 1 or tonumber(key) % 1 ~= 0) then
                reason = "invalid room entry"
            end
        end
        if reason then
            active[container] = nil
            return
        end
        for _, room in ipairs(rooms) do
            local d = tonumber(room.r._d)
            if not d or d % 1 ~= 0 or d < 1 or d > Dungeon.ROOMS or type(room.r._t) ~= "table"
                or (#prefix > 0 and d ~= prefix[#prefix].d + 1)
                or (#prefix == 0 and #top > 0 and d ~= top[1].d) then
                reason = "unknown room depth or tags"
                break
            end
            room.parent = parent
            if #prefix == 0 then table.insert(top, room) end
            local path = table.clone(prefix)
            table.insert(path, room)
            layers = math.max(layers, #path)
            local nested = container["next" .. tostring(room.choice)]
            -- Some game versions keep children on the room, even with an empty sibling nextN table.
            if #Dungeon.list(nested) == 0 and type(room.r.next) == "table" then nested = room.r.next end
            local children = Dungeon.list(nested)
            if #children > 0 then
                if d == Dungeon.ROOMS or #path >= Dungeon.MAX_LAYERS then
                    reason = "visible layers exceed planner limits"
                    break
                end
                walk(nested, path, (parent or "") .. tostring(room.choice) .. ">")
            elseif #path == 1 and d < Dungeon.ROOMS then
                reason = "second room layer is hidden"
            else
                table.insert(paths, path)
                if #paths > Dungeon.MAX_PATHS then reason = "too many visible paths" end
            end
            if reason then break end
        end
        active[container] = nil
    end
    walk(arg1 and arg1.next, {}, nil)
    return paths, layers, top, reason
end

-- the average room on offer at each depth (rooms 1–5, 6–10, 11–15, 16–20): what earlier runs offered,
-- blended with what the game shows now. An average room, not the best of three, so it errs on the low side.
function Dungeon.futureRooms(visible)
    local prior = {
        chest = 0,
        rare = 0,
        points = 0,
        n = 0
    }
    for _, parts in ipairs(visible) do
        prior.chest, prior.rare, prior.points, prior.n = prior.chest + parts.chest, prior.rare + parts.rare, prior.points + parts.points, prior.n + 1
    end
    if prior.n > 0 then
        prior.chest, prior.rare, prior.points = prior.chest / prior.n, prior.rare / prior.n, prior.points / prior.n
    end
    local out = {
    }
    for bucket = 1, 4 do
        local rec = type(Brain.dg.offers) == "table" and Brain.dg.offers [tostring(bucket)] or nil
        local n = rec and tonumber(rec.n) or 0
        local function mix(key)
            return ((rec and tonumber(rec [key]) or 0) + prior [key] * 3) / (n + 3)
        end
        out [bucket] = {
            chest = mix("chest"),
            rare = mix("rare"),
            points = mix("points"),
            seen = n
        }
    end
    return out
end

-- Clearing a room refills tries. Only the first room uses the current game count.
-- As in 2.11, charge lost tries in every room through room 20 without weighting by reach.
-- 2.29: a curse the simulator can't play still makes the rooms after it harder: its win chance is cut by this share.
Dungeon.BLIND_P = {
    _curse_money = 0.97,
    _curse_shop = 0.98,
    _curse_explode = 0.9,
    _curse_random = 0.9,
    _curse_super_explode = 0.85,
    _curse_super_chaos = 0.85,
    _curse_super_burst = 0.88,
    _curse_super_armored = 0.88
}
Dungeon.BLIND_P_DEFAULT = 0.94
-- A path that adds curses may cost this much win chance against the best path without one (CURSE_SOFT once curses
-- would outnumber buffs). An easier path within EASE_GEMS of the best is taken when it is EASE_P easier.
Dungeon.CURSE_CRIT, Dungeon.CURSE_SOFT = 0.05, 0.02
Dungeon.EASE_GEMS, Dungeon.EASE_P = 150, 0.03

function Dungeon.blindP(curses, arg1)
    local mult = 1
    for _, curse in ipairs(curses or {}) do
        local ok, blind = pcall(Dungeon.blindCurse, arg1, curse)
        if curse == "?" or (ok and blind) then
            mult = mult * (Dungeon.BLIND_P [curse] or Dungeon.BLIND_P_DEFAULT)
        end
    end
    return mult
end

-- Buffs held in this run: items that help (not curses, not the mock chest).
function Dungeon.buffsHeld(arg1)
    local count = 0
    for id, n in pairs(Dungeon.items(arg1)) do
        local ok, value = pcall(Dungeon.itemValue, id, arg1)
        if not Dungeon.isCurse(id) and id ~= "chest_mock_item" and ok and (tonumber(value) or 0) > 0 then
            count = count + n
        end
    end
    return count
end

-- The hardest visible room of a scored path.
function Dungeon.ease(entry)
    local p = 1
    for _, row in ipairs(entry.rows or {}) do
        p = math.min(p, tonumber(row.p) or 0)
    end
    return p
end

-- Pick among scored paths (highest ev first). blocked(entry) says whether its first room is barred already.
-- held/buffs: curses and buffs of the run now. Returns best, alt, eased (the richer path given up for an easier one).
function Dungeon.safePick(scored, held, buffs, blocked)
    blocked = blocked or function(entry)
        return entry.path and entry.path [1] and entry.path [1].blocked
    end
    -- the reference: the safest path without a curse (its hardest room and its reach to room 20)
    local clean
    for _, entry in ipairs(scored) do
        entry.cursed = nil
        if # (entry.curses or {}) == 0 and not blocked(entry) then
            clean = clean or { ease = 0, reach = 0 }
            clean.ease = math.max(clean.ease, Dungeon.ease(entry))
            clean.reach = math.max(clean.reach, entry.reach or 0)
        end
    end
    for _, entry in ipairs(scored) do
        if # (entry.curses or {}) > 0 and not blocked(entry) then
            local over = (held or 0) + # entry.curses > (buffs or 0) + (entry.buffs or 0)
            local limit = over and Dungeon.CURSE_SOFT or Dungeon.CURSE_CRIT
            if clean then
                local drop = math.max(clean.ease - Dungeon.ease(entry), clean.reach - (entry.reach or 0))
                if drop > limit + 1e-9 then
                    entry.cursed = string.format("its curse costs %d%% win chance (allowed %d%%%s)", math.floor(drop * 100 + 0.5), math.floor(limit * 100 + 0.5), over and ", curses would outnumber buffs" or "")
                end
            end
        end
    end
    local best
    for _, entry in ipairs(scored) do
        if not blocked(entry) and not entry.cursed then
            best = entry
            break
        end
    end
    if not best then
        for _, entry in ipairs(scored) do
            if not blocked(entry) then
                best = entry
                break
            end
        end
    end
    best = best or scored [1]
    local eased
    if best then
        local top = best
        for _, entry in ipairs(scored) do
            if entry ~= top and not blocked(entry) and not entry.cursed and (top.ev or 0) - (entry.ev or 0) <= Dungeon.EASE_GEMS
                and Dungeon.ease(entry) >= Dungeon.ease(top) + Dungeon.EASE_P and (entry.reach or 0) >= (top.reach or 0) - 0.005 then
                -- the first such path is the richest of the easier ones
                eased, best = top, entry
                break
            end
        end
    end
    local alt
    for _, entry in ipairs(scored) do
        if best and entry.path and best.path and entry.path [1] ~= best.path [1] and not blocked(entry) and not entry.cursed then
            alt = entry
            break
        end
    end
    return best, alt, eased
end

function Dungeon.scorePath(arg1, path, ctx)
    local survive, other, tries = 1, 0, 0
    local chests, rare, coins = ctx.chests, ctx.rare, ctx.coins
    local curses, rows, buffs = {}, {}, 0
    for j, room in ipairs(path) do
        local p, sim = Dungeon.winP(room, #curses > 0 and table.clone(curses) or nil)
        if #curses > 0 then
            p = p * Dungeon.blindP(curses, arg1)
        end
        local n = j == 1 and math.max(1, ctx.lives) or Dungeon.TRIES
        local clear = 1 - (1 - p) ^ n
        tries = tries + ((p > 0 and clear / p or n) - 1)
        survive = survive * clear
        local parts = Dungeon.roomParts(room, coins)
        coins = coins + parts.coins
        -- A shop is a utility estimate, not a free chest or a promise to buy. Reserve its budget once.
        if room.tags[Dungeon.T.SHOP] and coins >= 300 then
            coins = coins - 300
            buffs = buffs + 1
        end
        if room.tags[Dungeon.T.SHRINE] then
            buffs = buffs + 1
        end
        chests, rare = chests + parts.chest, rare + parts.rare
        local points, blind = parts.points, nil
        if parts.curse then
            local cost
            cost, blind = Dungeon.cursePoints(arg1, parts.curse)
            points = points - cost
            table.insert(curses, parts.curse)
        end
        other = other + survive * points * Dungeon.POINT_GEMS
        table.insert(rows, { room = room, p = p, sim = sim, clear = clear, parts = parts, blind = blind })
    end
    local last, mult = path[#path], 1
    if #curses > 0 then
        local okA, withCurses = pcall(Dungeon.sim, last, table.clone(curses), nil, true)
        local okB, without = pcall(Dungeon.sim, last, nil, nil, true)
        if okA and okB and withCurses and without and (tonumber(without.p) or 0) > 0 then
            mult = Utils.clamp((tonumber(withCurses.p) or 0) / without.p, 0, 1)
        end
        mult = mult * Dungeon.blindP(curses, arg1)
    end
    local later = 0
    for depth = last.d + 1, Dungeon.ROOMS do
        local p = Dungeon.priorP(depth) * (2 + mult) / 3
        local clear = 1 - (1 - p) ^ Dungeon.TRIES
        tries = tries + ((p > 0 and clear / p or Dungeon.TRIES) - 1)
        survive = survive * clear
        local room = ctx.future[math.min(4, math.max(1, math.ceil(depth / 5)))]
        chests, rare = chests + room.chest, rare + room.rare
        other = other + survive * room.points * Dungeon.POINT_GEMS
        later = later + 1
    end
    local chestValue = (chests * ctx.chestG + rare * ctx.rareG) * survive
    local tryCost = tries * ctx.tryCost
    return { path = path, rows = rows, ev = chestValue + other - tryCost,
        chestValue = chestValue, other = other, tryCost = tryCost, tries = tries,
        reach = survive, chests = chests, rare = rare, curses = curses, mult = mult, later = later, buffs = buffs }
end

function Dungeon.pathName(scored)
    local list = {
    }
    for _, room in ipairs(scored.path) do
        table.insert(list, Dungeon.roomName(room))
    end
    return table.concat(list, " → ")
end

function Dungeon.planWhy(plan)
    local best, alt = plan.best, plan.alt
    local skipped = ""
    local top = plan.scored [1]
    if top and top ~= best and top.path [1].blocked then
        skipped = string.format(" · %s scored higher (%d gems) but is skipped: %s", Dungeon.pathName(top), math.floor(top.ev + 0.5), top.path [1].blocked)
    elseif top and top ~= best and top.cursed then
        skipped = string.format(" · %s scored higher (%d gems) but is skipped: %s", Dungeon.pathName(top), math.floor(top.ev + 0.5), top.cursed)
    end
    if plan.eased then
        skipped = skipped .. string.format(" · easier than %s (%d gems less, its hardest room %d%% vs %d%%)", Dungeon.pathName(plan.eased), math.floor(plan.eased.ev - best.ev + 0.5), Dungeon.pct(Dungeon.ease(best)), Dungeon.pct(Dungeon.ease(plan.eased)))
    end
    skipped = skipped .. string.format(" · run: %d buff%s, %d curse%s", plan.heldBuffs or 0, (plan.heldBuffs or 0) == 1 and "" or "s", plan.heldCurses or 0, (plan.heldCurses or 0) == 1 and "" or "s")
    if not alt then
        return (#plan.top == 1 and "the only room on offer" or "no other room passes the curse safety check") .. skipped
    end
    local bits = {
    }
    local function add(label, diff)
        if math.abs(diff) >= 1 then
            table.insert(bits, {
                label = label,
                diff = diff
            })
        end
    end
    add("chests paid at room 20", best.chestValue - alt.chestValue)
    add("coins, shops and shrines", best.other - alt.other)
    add("fewer lost tries", alt.tryCost - best.tryCost)
    table.sort(bits, function(a, b)
        return math.abs(a.diff) > math.abs(b.diff)
    end)
    local list = {
    }
    for _, bit in ipairs(bits) do
        table.insert(list, string.format("%s %+d", bit.label, math.floor(bit.diff + 0.5)))
    end
    local reach = ""
    if math.abs(best.reach - alt.reach) >= 0.01 then
        reach = string.format(" · reaches room 20 %d%% vs %d%%", Dungeon.pct(best.reach), Dungeon.pct(alt.reach))
    end
    local lead = best.ev - alt.ev
    return string.format("%d gems %s the best path through another room, %s (%s)%s%s", math.floor(math.abs(lead) + 0.5), lead >= 0 and "ahead of" or "behind", Dungeon.pathName(alt), # list > 0 and table.concat(list, ", ") or "same parts", reach, skipped)
end

function Dungeon.plan(arg1)
    local paths, layers, top, reason = Dungeon.paths(arg1)
    if reason or #top == 0 then
        return nil, reason or "no visible rooms"
    end
    local coins, held, heldRare = Dungeon.res(arg1)
    local chestG, rareG, source = Dungeon.chestGems()
    local visible, seen = {
    }, {
    }
    for _, path in ipairs(paths) do
        for _, room in ipairs(path) do
            if not seen [room] then
                seen [room] = true
                table.insert(visible, Dungeon.roomParts(room, coins))
            end
        end
    end
    local ctx = {
        lives = Dungeon.lives(arg1),
        coins = coins,
        chests = held,
        rare = heldRare,
        chestG = chestG,
        rareG = rareG,
        tryCost = math.max(0, tonumber(Config.dungeonValue) or 150),
        future = Dungeon.futureRooms(visible)
    }
    local scored = {
    }
    for _, path in ipairs(paths) do
        local ok, res = pcall(Dungeon.scorePath, arg1, path, ctx)
        if ok and res then
            table.insert(scored, res)
        else
            return nil, "path forecast failed: " .. tostring(res)
        end
        task.wait()
    end
    table.sort(scored, function(a, b)
        return a.ev > b.ev
    end)
    for _, room in ipairs(top) do
        room.blocked, room.score, room.nextRoom = nil, nil, nil
        for _, entry in ipairs(scored) do
            if entry.path [1] == room then
                room.score, room.p, room.sim, room.nextRoom = entry.ev, entry.rows [1].p, entry.rows [1].sim, entry.path [2]
                break
            end
        end
        if not room.p then
            room.p, room.sim = Dungeon.winP(room)
        end
        local ok, pass, why = pcall(Dungeon.curseGate, room, arg1)
        if ok and not pass then
            room.blocked = why
        end
    end
    local held, buffs = Dungeon.curses(arg1), Dungeon.buffsHeld(arg1)
    local best, alt, eased = Dungeon.safePick(scored, held, buffs)
    local plan = {
        best = best,
        alt = alt,
        eased = eased,
        heldCurses = held,
        heldBuffs = buffs,
        scored = scored,
        top = top,
        layers = layers,
        ctx = ctx,
        source = source,
        held = held,
        heldRare = heldRare
    }
    plan.why = best and Dungeon.planWhy(plan) or nil
    return plan
end

-- Stable, typed content key: second-layer rooms, item identities/counts, learned values and settings matter.
function Dungeon.pickSignature(arg1)
    local active = {}
    local function encode(value)
        if type(value) ~= "table" then
            local text = tostring(value)
            return type(value) .. #text .. ":" .. text
        end
        if active[value] then return "cycle" end
        active[value] = true
        local entries = {}
        for key, item in pairs(value) do table.insert(entries, encode(key) .. "=" .. encode(item)) end
        table.sort(entries)
        active[value] = nil
        return "{" .. table.concat(entries, ";") .. "}"
    end
    return encode({ next = arg1 and arg1.next, items = Dungeon.items(arg1), lives = Dungeon.lives(arg1),
        resources = arg1 and arg1._resources, team = Modes.teamSig(), sim = Config.sim,
        killZone = Config.killZone, value = Config.dungeonValue, depth = Brain.dg.depth,
        offers = Brain.dg.offers, pay = Brain.dg.pay })
end

function Dungeon.pick(arg1)
    local sig = "plan|" .. Dungeon.pickSignature(arg1)
    if Dungeon._pick and Dungeon._pick.sig == sig and os.clock() - (Dungeon._pick.at or 0) < 5 then
        return Dungeon._pick.x
    end
    local ok, plan, reason = pcall(Dungeon.plan, arg1)
    if not ok or not plan or not plan.best then
        reason = not ok and ("planner error: " .. tostring(plan)) or reason or "no scored paths"
        Dungeon._pick = nil
        local value = Dungeon.pickGreedy(arg1)
        Dungeon._pick = Dungeon._pick or {}
        Dungeon._pick.sig, Dungeon._pick.at, Dungeon._pick.fallback = sig, os.clock(), reason
        App.log(1, "DUNGEON", "greedy fallback: " .. reason .. "; no reliable path forecast")
        return value
    end
    local value = plan.best.path[1]
    Dungeon._pick = { sig = sig, at = os.clock(), x = value, rooms = plan.top, plan = plan }
    return value
end

function Dungeon.planLog(plan)
    if not (plan and plan.best) then
        return
    end
    local ctx, first = plan.ctx, plan.best.path [1]
    local shown = first.d + plan.layers - 1
    App.log(1, "DUNGEON", string.format("plan for room %d: %d paths through the %d room%s the game shows%s · at stake %d chests + %d rare · %d %s · a chest ≈%d gems, a rare one ≈%d (%s) · a lost try costs %d gems",
        first.d,
        # plan.scored,
        plan.layers,
        plan.layers == 1 and "" or "s",
        shown < Dungeon.ROOMS and string.format(" (rooms %d–%d estimated)", shown + 1, Dungeon.ROOMS) or "",
        plan.held,
        plan.heldRare,
        ctx.lives,
        ctx.lives == 1 and "try left here" or "tries left here",
        math.floor(ctx.chestG + 0.5),
        math.floor(ctx.rareG + 0.5),
        plan.source,
        math.floor(ctx.tryCost + 0.5)))
    for i, entry in ipairs(plan.scored) do
        if i > 12 then
            App.log(1, "DUNGEON", string.format("… and %d more paths, all lower", # plan.scored - 12))
            break
        end
        local wins, curses = {
        }, {
        }
        for _, row in ipairs(entry.rows) do
            table.insert(wins, string.format("%d%%%s", Dungeon.pct(row.p), row.sim and "" or "*"))
            if row.parts.curse then
                table.insert(curses, Dungeon.curseName(row.parts.curse) .. (row.blind and " (not in the simulator)" or ""))
            end
        end
        local after = entry.mult < 0.995 and string.format(", later rooms ×%.2f to win", (2 + entry.mult) / 3) or ""
        App.log(1, "DUNGEON", string.format("%s %s: win %s · curses %s%s · lost tries ≈%.1f · reaches room 20 %d%% · %d gems expected%s",
            entry == plan.best and "✓" or "·",
            Dungeon.pathName(entry),
            table.concat(wins, " → "),
            # curses > 0 and table.concat(curses, ", ") or "none",
            after,
            entry.tries,
            Dungeon.pct(entry.reach),
            math.floor(entry.ev + 0.5),
            entry.path [1].blocked and (" (skipped: " .. entry.path [1].blocked .. ")") or ""))
    end
    App.log(1, "DUNGEON", "chosen: " .. Dungeon.pathName(plan.best) .. " — " .. tostring(plan.why) .. " (* = the simulator couldn't play the room: depth prior only)")
    App.log(1, "DUNGEON", Dungeon.planText(plan))
end

function Dungeon.planText(plan)
    if not (plan and plan.best) then return "Plan: greedy choice; forecast unavailable" end
    local best = plan.best
    return string.format("Plan: %s · finish ≈%d%% · ≈%d expected chest gems (net value %d) · %s · %d layers shown; later rooms estimated; clearing refills tries",
        Dungeon.pathName(best), Dungeon.pct(best.reach), math.floor(best.chestValue + 0.5), math.floor(best.ev + 0.5), tostring(plan.why), plan.layers)
end

-- the rooms on offer, by depth: what an average room gives, for the rooms past what the game shows
function Dungeon.recordOffers(plan)
    local seeds = {
    }
    for _, room in ipairs(plan.top) do
        table.insert(seeds, tostring(room.r._r))
    end
    local key = table.concat(seeds, ",")
    if Brain.dg.offerSig == key then
        return
    end
    Brain.dg.offerSig = key
    Brain.dg.offers = type(Brain.dg.offers) == "table" and Brain.dg.offers or {
    }
    for _, room in ipairs(plan.top) do
        local bucket = tostring(math.min(4, math.max(1, math.ceil(room.d / 5))))
        local rec = Brain.dg.offers [bucket] or {
            n = 0,
            chest = 0,
            rare = 0,
            points = 0
        }
        local parts = Dungeon.roomParts(room, plan.ctx.coins)
        rec.n, rec.chest, rec.rare, rec.points = (tonumber(rec.n) or 0) + 1, (tonumber(rec.chest) or 0) + parts.chest, (tonumber(rec.rare) or 0) + parts.rare, (tonumber(rec.points) or 0) + parts.points
        if rec.n > 200 then
            rec.n, rec.chest, rec.rare, rec.points = rec.n / 2, rec.chest / 2, rec.rare / 2, rec.points / 2
        end
        Brain.dg.offers [bucket] = rec
    end
    App.saveSoon()
end

-- once per shape: how many room layers the game's data shows, and what the game's dungeon module offers
function Dungeon.probe(arg1)
    local function layersOf(container, depth)
        local rooms = Dungeon.list(container)
        if # rooms == 0 or depth > 8 then
            return 0
        end
        local most = 0
        for _, room in ipairs(rooms) do
            local nested = type(container) == "table" and container ["next" .. tostring(room.choice)] or nil
            local inner = layersOf(nested, depth + 1)
            if type(room.r.next) == "table" then
                inner = math.max(inner, layersOf(room.r.next, depth + 1))
            end
            most = math.max(most, inner)
        end
        return 1 + most
    end
    local layers = layersOf(arg1 and arg1.next, 1)
    local key = "layers:" .. layers
    if layers > 0 and not Brain.dg.seen [key] then
        Brain.dg.seen [key] = os.time()
        App.log(1, "DUNGEON", string.format("the game's data shows %d room layer%s (the rooms on offer included)%s", layers, layers == 1 and "" or "s", layers <= 2 and ": rooms past that are estimated" or ": the planner uses all of them"))
        App.saveSoon()
    end
    if not Brain.dg.seen.core then
        local core = Dungeon.core()
        if type(core) == "table" then
            local names = {
            }
            for name, value in pairs(core) do
                if type(value) == "function" then
                    table.insert(names, tostring(name))
                end
            end
            table.sort(names)
            Brain.dg.seen.core = os.time()
            App.log(1, "DUNGEON", "functions in the game's dungeon module (looked at once, to see whether rooms past the shown ones can be worked out): " .. (# names > 0 and table.concat(names, ", ") or "none"))
            App.saveSoon()
        end
    end
    return layers
end

function Dungeon.roomName(arg1)
    local l = type(arg1.r._l) == "table" and arg1.r._l or {
    }
    return string.format("%s (%s)", tostring(l._location_name or l.map or "?"), Dungeon.tagText(arg1.tags))
end

function Dungeon.screens(arg1)
    local list = {
    }
    for currentShopKey, currentShop in pairs(type(arg1.current_shops) == "table" and arg1.current_shops or {
    }) do
        if type(currentShop) == "table" then
            table.insert(list, {
                i = tonumber(currentShopKey) or 0,
                t = tonumber(currentShop._t),
                data = currentShop.data
            })
        end
    end
    table.sort(list, function(arg1, arg2)
        return arg1.i < arg2.i
    end)
    return list
end

function Dungeon.cleared(arg1)
    return math.max(1, (Dungeon.depth(arg1) or (Dungeon.ROOMS + 1)) - 1)
end

function Dungeon.state(arg1)
    if arg1._dead then
        return "dead"
    end
    if arg1._finished then
        return "finished"
    end
    local screen = Dungeon.screens(arg1) [1]
    if screen then
        if screen.t == Dungeon.T.SHOP then
            return "shop", screen
        end
        if screen.t == Dungeon.T.OPEN then
            return "chests", screen
        end
        if screen.t == Dungeon.T.SHRINE then
            return "shrine", screen
        end
        return "screen", screen
    end
    return "rooms"
end

function Dungeon.logState(arg1, state)
    local list = {
    }
    for key, value in pairs(arg1) do
        if not Dungeon.KNOWN [key] and not (type(value) == "table" and next(value) == nil) then
            table.insert(list, tostring(key))
        end
    end
    table.sort(list)
    local list2 = {
    }
    for _, screen in ipairs(Dungeon.screens(arg1)) do
        table.insert(list2, tostring(screen.t))
    end
    local text = table.concat(list, ",") .. (# list2 > 0 and ("|" .. table.concat(list2, ",")) or "")
    if text == "" or Brain.dg.seen [text] then
        return
    end
    Brain.dg.seen [text] = os.time()
    local list2 = {
    }
    for _, item in ipairs(list) do
        local value = arg1 [item]
        table.insert(list2, item .. "=" .. (type(value) == "table" and Utils.json(Utils.plain(value)):sub(1, 500) or tostring(value)))
    end
    App.log(1, "DUNGEON", "new screen (" .. tostring(state) .. "): " .. table.concat(list2, " · "))
    App.saveSoon()
end

function Dungeon.note(arg1)
    App.log(1, "DUNGEON", arg1)
    table.insert(Brain.dg.log, 1, {
        at = os.time(),
        msg = arg1
    })
    while # Brain.dg.log > 15 do
        table.remove(Brain.dg.log)
    end
    App.saveSoon()
end

function Dungeon.offers(data, arg2)
    local list = {
    }
    if type(data) ~= "table" then
        return list
    end
    for entryKey, entry in pairs(data) do
        local id, cost
        if type(entry) == "table" then
            id = entry.id or entry.item_id or entry.item
            cost = tonumber(entry.cost) or tonumber(entry.price)
        elseif type(entry) == "string" then
            id = entry
        elseif Dungeon.item(entryKey) then
            id = entryKey
            cost = tonumber(entry)
        end
        if type(id) == "string" and Dungeon.item(id) then
            table.insert(list, {
                key = entryKey,
                id = id,
                cost = cost or tonumber(Dungeon.item(id).cost) or 0,
                bought = type(entry) == "table" and (entry.bought or entry.sold or entry.purchased) or nil
            })
        end
    end
    if # list == 0 and not arg2 then
        for _, entry in pairs(data) do
            if type(entry) == "table" then
                list = Dungeon.offers(entry, true)
                if # list > 0 then
                    break
                end
            end
        end
    end
    return list
end

function Dungeon.buy(item)
    local res = Dungeon.res(Dungeon.data())
    local list = {
    }
    if Brain.dg.buyArg == "id" then
        list = {
            item.id,
            item.key
        }
    else
        list = {
            item.key,
            item.id
        }
    end
    if list [1] == list [2] then
        list [2] = nil
    end
    for _, item2 in ipairs(list) do
        local ok, _ = App.request("dgBuy", "dungeon_buy_shop", item2)
        local now = Utils.now()
        while Utils.now() - now < 3 and Dungeon.res(Dungeon.data()) >= res do
            task.wait(0.25)
        end
        if Dungeon.res(Dungeon.data()) < res then
            Brain.dg.buyArg = (item2 == item.id and item.id ~= item.key) and "id" or "key"
            return true
        end
        if not ok then
            break
        end
    end
    return false
end

function Dungeon.shopAhead(arg1)
    for _, room in ipairs(Dungeon.rooms(arg1)) do
        if room.tags [Dungeon.T.SHOP] then
            return true
        end
        for _, value in ipairs(Dungeon.after(arg1, room.choice)) do
            if value.tags [Dungeon.T.SHOP] then
                return true
            end
        end
    end
    return false
end
Dungeon.LUCK_RESERVE = 500
Dungeon.MIN_WORTH = 0.02
Dungeon.TOP_WORTH = 0.08

function Dungeon.shop(arg1, state)
    local cleared = Dungeon.cleared(arg1)
    local res = Dungeon.res(arg1)
    local value = 1 + 0.1 * (Dungeon.items(arg1)._curse_shop or 0)
    local luckReserve = Dungeon.shopAhead(arg1) and math.ceil(Dungeon.LUCK_RESERVE * value) or 0
    local list = {
    }
    local list2, count = {
    }, 0
    for _, offer in ipairs(Dungeon.offers(state and state.data)) do
        offer.cost = math.ceil(offer.cost * value)
        table.insert(list2, tostring(Dungeon.item(offer.id).name or offer.id))
        if not offer.bought and not Dungeon.isCurse(offer.id) then
            offer.luck = tonumber(Dungeon.item(offer.id).luck_increase) ~= nil
            offer.v = Dungeon.itemValue(offer.id, arg1)
            if not offer.luck and offer.v / math.max(1, offer.cost) < Dungeon.MIN_WORTH then
                count = count + 1
            elseif offer.v > 0 and (offer.luck or cleared >= 10 or offer.v / math.max(1, offer.cost) >= Dungeon.TOP_WORTH) then
                table.insert(list, offer)
            end
        end
    end
    table.sort(list, function(arg1, arg2)
        if arg1.luck ~= arg2.luck then
            return arg1.luck
        end
        return arg1.v / math.max(1, arg1.cost) > arg2.v / math.max(1, arg2.cost)
    end)
    local list3, count2, count3 = {
    }, 0, 0
    for _, item in ipairs(list) do
        if item.cost <= res - (item.luck and 0 or luckReserve) then
            if Dungeon.buy(item) then
                res = Dungeon.res(Dungeon.data())
                table.insert(list3, string.format("%s (%d coins)", tostring(Dungeon.item(item.id).name or item.id), item.cost))
            end
        elseif item.cost <= res then
            count3 = count3 + 1
        else
            count2 = count2 + 1
        end
    end
    Dungeon.note(string.format("shop at depth %d (%s): %s · %d coins left%s%s%s", cleared, # list2 > 0 and table.concat(list2, ", ") or "offer not read", # list3 > 0 and ("bought " .. table.concat(list3, ", ")) or (cleared < 10 and "no chest luck on sale: coins kept for the shops at floors 10–15" or (count3 > 0 and "nothing bought" or "nothing worth buying")), res, count2 > 0 and string.format(" (%d too dear)", count2) or "", count3 > 0 and string.format(" (%d left on the shelf: %d coins kept for chest luck, a shop room is ahead)", count3, luckReserve) or "", count > 0 and string.format(" (%d would do nothing for this team's damage type)", count) or ""))
    App.request("dgCont", "dungeon_continue_shop")
end

function Dungeon.shrine(arg1, state)
    local offers = Dungeon.offers(state and state.data)
    local count, list = 0, {
    }
    local value
    for _, offer in ipairs(offers) do
        local item = Dungeon.item(offer.id)
        table.insert(list, tostring(item and item.name or offer.id))
        if Dungeon.isCurse(offer.id) then
            local ok, res, res2 = pcall(Dungeon.curseOk, offer.id, arg1, Dungeon.cleared(arg1) + 1, nil, Dungeon.rooms(arg1))
            if ok and not res then
                value = res2
            end
        else
            count = count + Dungeon.itemValue(offer.id, arg1)
        end
    end
    local flag = # offers > 0 and count > 0 and not value
    if flag then
        App.request("dgShrine", "dungeon_shrine_accept")
    else
        App.request("dgCont", "dungeon_continue_shop")
    end
    Dungeon.note(string.format("shrine (%s): %s", # list > 0 and table.concat(list, ", ") or "offer not read", flag and "taken" or (value and ("passed: " .. value) or "passed")))
end

function Dungeon.wallet()
    local profileData = Core.session() and Core.session().profile_data or {
    }
    local inventory = profileData.inventory or {
    }
    local info = {
        gems = tonumber(Core.cur("gems")) or 0,
        gold = tonumber(Core.cur("gold")) or 0,
        items = {
        },
        units = {
        },
        unique = 0
    }
    for normalItemKey, normalItem in pairs(inventory.normal_items or {
    }) do
        info.items [normalItemKey] = tonumber(normalItem) or 0
    end
    for ownedUnitKey, ownedUnit in pairs(profileData.collection and profileData.collection.owned_units or {
    }) do
        info.units [ownedUnitKey] = ownedUnit.unit_id
    end
    for _ in pairs(inventory.unique_items or {
    }) do
        info.unique = info.unique + 1
    end
    return info
end

function Dungeon.walletDiff(wallet, wallet2)
    local list = {
    }
    if wallet2.gems ~= wallet.gems then
        table.insert(list, string.format("%+d gems", wallet2.gems - wallet.gems))
    end
    if wallet2.gold ~= wallet.gold then
        table.insert(list, string.format("%+d gold", wallet2.gold - wallet.gold))
    end
    for itemKey, item in pairs(wallet2.items) do
        if item ~= (wallet.items [itemKey] or 0) then
            table.insert(list, string.format("%+d %s", item - (wallet.items [itemKey] or 0), tostring(itemKey)))
        end
    end
    for unitKey, unit in pairs(wallet2.units) do
        if not wallet.units [unitKey] then
            table.insert(list, "new unit " .. Units.name(unit))
        end
    end
    if wallet2.unique ~= wallet.unique then
        table.insert(list, string.format("%+d relics", wallet2.unique - wallet.unique))
    end
    return # list > 0 and table.concat(list, ", ") or "nothing seen"
end

function Dungeon.openChests(arg1, arg2)
    local _, res2, res3 = Dungeon.res(arg1)
    local lives = Dungeon.lives(arg1)
    local cleared = Dungeon.cleared(arg1)
    if not (arg2 or cleared >= Dungeon.ROOMS or lives <= 1) then
        Dungeon.note(string.format("chest room at depth %d: keeping %d chests and %d rare chests for floor 20 (luck ×%.1f now)", cleared, res2, res3, Dungeon.luck(arg1)))
        App.request("dgCont", "dungeon_continue_shop")
        return
    end
    local count, count2, count3 = 0, 0, 0
    local cur = tonumber(Core.cur("gems")) or 0
    local wallet = Dungeon.wallet()
    for i = 1, res2 + res3 + 12 do
        local _, res2, res3 = Dungeon.res(Dungeon.data())
        if res2 + res3 <= 0 or count3 >= 2 then
            break
        end
        local ok, value
        if res2 > 0 then
            ok, value = App.request("dgChest", "dungeon_open_chest")
        else
            ok, value = App.request("dgChest", "dungeon_open_chest", true)
        end
        if not ok and (value == "waiting" or value == "slowing down") then
            -- 2.34: our own request pause after a timeout, not the game refusing: wait it out, it isn't a failed chest
            task.wait(3)
            continue
        end
        if ok and value ~= nil then
            App.log(1, "DUNGEON", "chest: " .. (type(value) == "table" and Utils.json(Utils.plain(value)):sub(1, 300) or tostring(value)))
        end
        local now = Utils.now()
        while Utils.now() - now < 4 do
            local _, res22, res32 = Dungeon.res(Dungeon.data())
            if res22 < res2 or res32 < res3 then
                break
            end
            task.wait(0.25)
        end
        local _, res22, res32 = Dungeon.res(Dungeon.data())
        if res22 < res2 then
            count = count + (res2 - res22)
            count3 = 0
        elseif res32 < res3 then
            count2 = count2 + (res3 - res32)
            count3 = 0
        else
            count3 = count3 + 1
            task.wait(5) -- 2.34: a real failure: give the game a moment before the next try
        end
        task.wait(1)
        if res22 < res2 or res32 < res3 then
            local wallet2 = Dungeon.wallet()
            local walletDiff = Dungeon.walletDiff(wallet, wallet2)
            App.log(1, "DUNGEON", (res32 < res3 and "rare chest: " or "chest: ") .. walletDiff)
            Brain.dg.pay = Brain.dg.pay or {
            }
            local list = {
            }
            for itemKey, item in pairs(wallet2.items) do
                if item ~= (wallet.items [itemKey] or 0) then
                    list [itemKey] = item - (wallet.items [itemKey] or 0)
                end
            end
            table.insert(Brain.dg.pay, {
                at = os.time(),
                rare = res32 < res3,
                gems = wallet2.gems - wallet.gems,
                luck = Dungeon.luck(arg1),
                paid = walletDiff,
                items = list
            })
            while # Brain.dg.pay > 60 do
                table.remove(Brain.dg.pay, 1)
            end
            wallet = wallet2
        end
    end
    Dungeon.note(string.format("opened %d chests and %d rare chests (%s, luck ×%.1f) · gems %+d", count, count2, arg2 and "last room" or (lives <= 1 and "one life left" or "floor 20"), Dungeon.luck(arg1), (tonumber(Core.cur("gems")) or 0) - cur))
    local _, res2, res3 = Dungeon.res(Dungeon.data())
    if (arg2 or cleared >= Dungeon.ROOMS) and res2 + res3 > 0 then
        Dungeon.note(string.format("%d chests and %d rare chests didn't open: the last room stays open, trying again in 5 min", res2, res3))
        Modes.rec("dg").restUntil = os.time() + 300
        return "hold"
    end
    if not arg2 then
        App.request("dgCont", "dungeon_continue_shop")
    end
end

function Dungeon.act(arg1)
    local state, state2 = Dungeon.state(arg1)
    Dungeon.logState(arg1, state)
    if state == "rooms" then
        return false
    end
    if state == "screen" then
        Dungeon.note(string.format("a screen of a kind not known yet (tag %s): closed with Continue", tostring(state2 and state2.t)))
        App.request("dgCont", "dungeon_continue_shop")
        return true
    end
    if state == "dead" then
        App.request("dgDeath", "dungeon_continue_death")
        Dungeon.note("the run is over: that was the last life, and its unopened chests went with it")
        Brain.dg.lives, Brain.dg.lost = 5, {
        }
    elseif state == "finished" then
        if Dungeon.openChests(arg1, true) == "hold" then
            return "hold"
        end
        App.request("dgCont", "dungeon_continue_shop")
        local _, res2, res3 = Dungeon.res(Dungeon.data())
        table.insert(Brain.dg.runs, 1, {
            at = os.time(),
            depth = Dungeon.ROOMS,
            items = Utils.count(Dungeon.items(arg1)),
            left = res2 + res3
        })
        while # Brain.dg.runs > 10 do
            table.remove(Brain.dg.runs)
        end
        Dungeon.note("dungeon finished: all 20 rooms")
    elseif state == "shop" then
        Dungeon.shop(arg1, state2)
    elseif state == "shrine" then
        Dungeon.shrine(arg1, state2)
    elseif state == "chests" then
        if Dungeon.openChests(arg1, false) == "hold" then
            return "hold"
        end
    end
    return true
end

function Dungeon.launch(mode)
    local value = Dungeon.data()
    if not value then
        App.backoff("launch", 30)
        return false
    end
    if not value._started then
        if not (Config.dungeonStart or Config.onlyDungeons) then
            return false
        end
        local ok, res = App.request("dgStart", "dungeon_start")
        task.wait(2.5)
        value = Dungeon.data()
        if not (ok and value and value._started) then
            App.log(1, "DUNGEON", "the game didn't start a dungeon run (" .. tostring(res) .. "): trying again in 30 min")
            Modes.rec("dg").restUntil = os.time() + 1800
            App.backoff("launch", 10)
            return false
        end
        Brain.dg.lost = {
        }
        Dungeon.note(string.format("new dungeon run started (%d tries per room)", Dungeon.lives(value)))
    end
    if Dungeon.enter(value, mode.value, false) then
        return true
    end
    App.backoff("launch", 10)
    return false
end

function Dungeon.playLast()
    local playLast = Brain.dg.playLast
    return type(playLast) == "table" and os.time() - (tonumber(playLast.at) or 0) < 1800 and playLast or nil
end

function Dungeon.forced(arg1)
    local force = Brain.dg.force
    if type(force) ~= "table" or type(force.uuids) ~= "table" or force.seed ~= tostring(arg1.r._r) then
        return nil
    end
    if os.time() - (tonumber(force.at) or 0) > 3600 then
        Brain.dg.force = nil
        return nil
    end
    return force
end

function Dungeon.startTeam(uuids, arg2, label, arg4)
    Brain.startTeam = {
        uuids = table.clone(uuids),
        must = true,
        own = arg4 or nil,
        seed = tostring(arg2.r._r),
        kind = "dungeon",
        at = os.time(),
        why = label
    }
end

function Dungeon.planTeam(arg1, arg2, arg3)
    if type(Config.modeTeams) == "table" and Config.modeTeams.dungeon ~= nil and not Dungeon.ownTeamNoted then
        Dungeon.ownTeamNoted = true
        App.log(1, "TEAM", "dungeon: own team not supported yet")
    end
    if not (Config.sim and Config.simTeams) or type(arg1.r._l) ~= "table" then
        return
    end
    if Dungeon.playLast() then
        App.log(1, "SIM", string.format("dungeon room %d: your own pick stays, no search", arg1.d))
        return
    end
    local forced = Dungeon.forced(arg1)
    if forced then
        if arg3 then
            App.log(1, "SIM", string.format("dungeon room %d: your call — %s goes in as the room starts, no search", arg1.d, tostring(forced.label)))
            if not Training.same(Training.team(), forced.uuids) then
                Dungeon.startTeam(forced.uuids, arg1, tostring(forced.label))
            end
            return
        end
        App.log(1, "SIM", string.format("dungeon room %d: your call — %s goes in, no search", arg1.d, tostring(forced.label)))
        FarmHub.equipTeam(forced.uuids, tostring(forced.label))
        task.wait(0.5)
        return
    end
    if arg3 and not Config.autoTeam then
        return
    end
    local dg = Brain.simTeam.dg
    if not arg3 and Config.autoTeam and dg and dg.better and dg.seed == tostring(arg1.r._r) and os.time() - (tonumber(dg.at) or 0) < 300 then
        FarmHub.equipTeam(dg.uuids, "the best team found for dungeon room " .. arg1.d)
        task.wait(0.5)
        return
    end
    local fx = Dungeon.fx(arg2, Dungeon.roomCurse(arg1.r))
    local list = {
    }
    if arg3 and type(Brain.savedTeam) == "table" and # Brain.savedTeam > 0 then
        local session = Core.session()
        for _, value in ipairs(Brain.savedTeam) do
            local unitObj = session.collection:get_unit_by_uuid(value)
            if unitObj then
                table.insert(list, unitObj)
            end
        end
    else
        for _, value in ipairs(Units.equipped()) do
            table.insert(list, value.u)
        end
    end
    if # list == 0 then
        return
    end
    local mod = Dungeon.mod(arg1.r._l)
    local applyFx = Simulator.applyFx(Simulator.info(Simulator.slim(arg1.r._l), "dg", nil, mod), fx)
    App.status("Mode", "looking for the best team for dungeon room " .. arg1.d)
    Simulator.memoOn()
    local pool = Simulator.pool(mod, applyFx)
    local bestTeam, bestTeam2, _, bestTeam4 = Simulator.bestTeam(applyFx, list, pool, Dungeon.lives(arg2) <= 1 and 45 or 20)
    local function helper(arg12)
        local sig = Simulator.sig(arg12)
        local team = type(Brain.dg.teams) == "table" and Brain.dg.teams [sig] or {
        }
        local value = type(Brain.dg.lost) == "table" and Brain.dg.lost [tostring(arg1.r._r)] and Brain.dg.lost [tostring(arg1.r._r)] [sig] or 0
        if type(Brain.dg.bail) == "table" and Brain.dg.bail.sig == sig and os.time() - (tonumber(Brain.dg.bail.at) or 0) < 1800 then
            value = value + 1
        end
        local strength, strength2, strength3, strength4 = Simulator.strength(applyFx, arg12)
        local value2 = math.clamp((tonumber(team.w) or 0) - 2 * (tonumber(team.l) or 0), - 6, 3)
        if arg1.d >= 13 then
            value2 = math.min(value2, 1)
        end
        value2 = value2 - 3 * value
        return {
            score = strength + value2,
            wins = strength,
            atOne = strength2,
            reach = strength3,
            far = strength4,
            lostHere = value,
            w = tonumber(team.w) or 0,
            l = tonumber(team.l) or 0
        }
    end
    local flag = Simulator.sig(bestTeam) == Simulator.sig(list)
    local value = helper(list)
    local value2 = flag and value or helper(bestTeam)
    if (applyFx.regen or 0) > 0 then
        local flag2 = false
        for _, item in ipairs(list) do
            if Units.bleeds(item.unit_id) then
                flag2 = true
            end
        end
        for _, unitData in ipairs(bestTeam) do
            if Units.bleeds(unitData.unit_id) then
                flag2 = true
            end
        end
        local bestBleeder = not flag2 and Units.bestBleeder(list) or nil
        if bestBleeder then
            local list2 = {
            }
            for i, item in ipairs(list) do
                if not Units.isFarm(item.unit_id) and not Units.allyBuff(item.unit_id) then
                    local list3 = table.clone(list)
                    list3 [i] = bestBleeder
                    local value = helper(list3)
                    table.insert(list2, string.format("%s out: %d tries", Units.name(item.unit_id), value.wins))
                    if value.score > value2.score then
                        bestTeam, value2, flag = list3, value, false
                        bestTeam2 = {
                            won = value.wins > 0,
                            wave = value.reach
                        }
                    end
                    task.wait()
                end
            end
            App.log(1, "SIM", string.format("dungeon room %d: enemies regenerate, so %s (bleeds from upgrade %d) was tried in each slot: %s", arg1.d, Units.name(bestBleeder.unit_id), Units.bleeds(bestBleeder.unit_id) or 0, table.concat(list2, " · ")))
        end
    end
    Simulator.memo = nil
    local value3 = value2.wins > value.wins or (value2.wins == value.wins and (value2.far or 0) > (value.far or 0))
    local value4 = not flag and value3 and value2.lostHere <= value.lostHere
    local list, list2 = {
    }, {
    }
    for _, unit in ipairs(bestTeam) do
        table.insert(list, unit.uuid)
        table.insert(list2, Units.name(unit.unit_id))
    end
    Brain.simTeam.dg = {
        uuids = list,
        names = list2,
        won = bestTeam2.won,
        wave = bestTeam2.wave,
        better = value4,
        cur = {
            won = bestTeam4.won,
            wave = bestTeam4.wave
        },
        at = os.time(),
        label = "Dungeon",
        seed = tostring(arg1.r._r)
    }
    local function helper(arg1)
        return string.format("wins %d simulated tries up the rising test, gets to wave %d at normal strength, real rooms %d won and %d lost", arg1.wins, math.floor(arg1.reach + 0.5), arg1.w, arg1.l)
    end
    if not value4 then
        if flag then
            App.log(1, "SIM", string.format("dungeon room %d: tried %d units, none beats your team (%s)", arg1.d, # pool, helper(value)))
        elseif not value3 then
            App.log(1, "SIM", string.format("dungeon room %d: your team goes in (%s): the search's pick, %s, doesn't go further up the rising test (%s)", arg1.d, helper(value), table.concat(list2, ", "), helper(value2)))
        else
            App.log(1, "SIM", string.format("dungeon room %d: your team goes in (%s): the search's pick, %s, already lost here %d times (%s)", arg1.d, helper(value), table.concat(list2, ", "), value2.lostHere, helper(value2)))
        end
        if arg3 and type(Brain.savedTeam) == "table" and not Training.same(Training.team(), Brain.savedTeam) then
            Dungeon.startTeam(Brain.savedTeam, arg1, "your own team back for dungeon room " .. arg1.d, true)
        end
        return
    end
    App.log(1, "SIM", string.format("dungeon room %d: the search's top pick: %s (%s; yours: %s)", arg1.d, table.concat(list2, ", "), helper(value2), helper(value)))
    if arg3 then
        if not Training.same(Training.team(), list) then
            Dungeon.startTeam(list, arg1, "the simulator's best team for dungeon room " .. arg1.d)
        end
        return
    end
    if Config.autoTeam then
        FarmHub.equipTeam(list, "the simulator's best team for dungeon room " .. arg1.d)
        task.wait(0.5)
    else
        App.log(1, "SIM", "Auto-Equip Best Team is off, so your team stays as it is")
    end
end

function Dungeon.enter(arg1, dungeonValue, arg3)
    for i = 1, 5 do
        local ok, res = pcall(Dungeon.act, arg1)
        if not ok then
            App.log(1, "ERROR", "dungeon screen: " .. tostring(res))
            break
        end
        if res == "hold" then
            return false
        end
        if not res then
            break
        end
        task.wait(2)
        arg1 = Dungeon.data()
        if not (arg1 and arg1._started) then
            return false
        end
    end
    Dungeon._pick = nil
    pcall(Dungeon.probe, arg1)
    local value = Dungeon.pick(arg1)
    if not value then
        Dungeon.logState(arg1, "no rooms on offer")
        local _, res2, res3 = Dungeon.res(arg1)
        if res2 + res3 > 0 then
            App.log(1, "DUNGEON", string.format("no room on offer and %d + %d chests unopened: nothing pressed, trying again in 30 min", res2, res3))
            Modes.rec("dg").restUntil = os.time() + 1800
            return false
        end
        App.log(1, "DUNGEON", "no room on offer: leaving the screen it's on")
        App.request("dgCont", "dungeon_continue_shop")
        return false
    end
    local ok, res = pcall(Dungeon.planTeam, value, arg1, arg3)
    if not ok then
        App.log(1, "ERROR", "dungeon team: " .. tostring(res))
    end
    if not arg3 then
        local dg = Brain.simTeam.dg
        local r = tostring(value.r._r)
        Brain.dg.swapFail = type(Brain.dg.swapFail) == "table" and Brain.dg.swapFail or {
        }
        local value2 = tonumber(Brain.dg.swapFail [r]) or 0
        local forced = Dungeon.forced(value)
        local uuids = (forced and forced.uuids) or ((dg and dg.better and dg.seed == r and value2 < 2) and dg.uuids) or Brain.savedTeam
        local team = Training.team()
        local flag = # team == 6 and (not uuids or Training.same(team, uuids))
        if not flag then
            Brain.dg.swapFail [r] = value2 + 1
            local list = {
            }
            for _, value in ipairs(Units.equipped()) do
                table.insert(list, Units.name(value.id))
            end
            if value2 + 1 >= 2 and dg and dg.better and dg.seed == r then
                dg.better = false
                App.log(1, "TEAM", string.format("the planned team for room %d wouldn't equip twice: your own team goes in instead", value.d))
                pcall(FarmHub.restoreTeam)
            end
            App.log(1, "DUNGEON", string.format("room %d not entered: the team isn't right yet (%d units: %s). Trying the swap again in a moment", value.d, # team, table.concat(list, ", ")))
            App.status("Mode", "waiting for the right team before dungeon room " .. value.d)
            Modes.rec("dg").restUntil = os.time() + 45
            Brain.pending = nil
            App.saveSoon()
            return false
        end
        Brain.dg.swapFail [r] = nil
        local ok, res = pcall(Strategy.relicsApply)
        if not ok then
            App.log(1, "ERROR", "relics: " .. tostring(res))
        end
    end
    if Dungeon.lives(arg1) <= 1 then
        Brain.dg.lost = Brain.dg.lost or {
        }
        local sim = Dungeon.sim(value)
        local value2 = (Brain.dg.lost [tostring(value.r._r)] or {
        }) [Modes.teamSig()] or 0
        local flag = # Units.equipped() < 6
        if (not sim or value2 >= 2 or flag) and not (Dungeon.playLast() and not flag) then
            local text = flag and string.format("the team has only %d units", # Units.equipped()) or value2 >= 2 and string.format("this team already lost here %d times", value2) or "the simulator can't play this room"
            Dungeon.note(string.format("last life on room %d: holding it (%s). Looks again in an hour", value.d, text))
            Modes.rec("dg").restUntil = os.time() + 3600
            Brain.pending = nil
            App.saveSoon()
            return false
        end
    end
    Brain.dg.room = {
        seed = value.r._r,
        d = value.d
    }
    pcall(function()
        local best = Dungeon._pick and Dungeon._pick.plan and Dungeon._pick.plan.best
        if best and best.path [1] and best.path [1].r and best.path [1].r._r == value.r._r then
            Brain.dg.room.path = Dungeon.pathName(best)
        end
    end)
    Brain.pending = {
        key = "dg",
        kind = "dungeon",
        level = "dungeon",
        diff = "Hard",
        label = "Dungeon room " .. value.d,
        at = os.time(),
        value = dungeonValue,
        depth = value.d
    }
    if Brain.nextMode == "dg" then
        Brain.nextMode = nil
    end
    local res, res2, res3 = Dungeon.res(arg1)
    local text = string.format("win ≈%d%%%s · leads to %s · %d lives · %d coins · chests %d + %d rare", math.floor(value.p * 100 + 0.5), value.sim and (" (sim: " .. tostring(value.sim.margin) .. ")") or "", value.nextRoom and Dungeon.roomName(value.nextRoom) or "the last room", Dungeon.lives(arg1), res, res2, res3)
    App.log(1, "MODE", string.format("entering dungeon room %d/%d%s: %s — %s", value.d, Dungeon.ROOMS, arg3 and " from the results screen" or "", Dungeon.roomName(value), text))
    local plan = Dungeon._pick and Dungeon._pick.plan
    if plan then
        local ok, res = pcall(Dungeon.planLog, plan)
        if not ok then
            App.log(1, "ERROR", "dungeon plan log: " .. tostring(res))
        end
        pcall(Dungeon.recordOffers, plan)
    else
        local list = {
        }
        for _, room in ipairs(Dungeon._pick and Dungeon._pick.rooms or {
        }) do
            if room ~= value then
                table.insert(list, string.format("%s, win ≈%d%%%s", Dungeon.roomName(room), math.floor((room.p or 0) * 100 + 0.5), room.blocked and (" (skipped: " .. room.blocked .. ")") or ""))
            end
        end
        if # list > 0 then
            App.log(1, "DUNGEON", "chosen over (one-room choice, the path planner had nothing): " .. table.concat(list, " · "))
        end
    end
    App.saveNow()
    App.status("Mode", "entering dungeon room " .. value.d)
    local choiceStr = type(arg1.selected_next) == "table" and arg1.selected_next.choice_str and tostring(arg1.selected_next.choice_str) or nil
    local list = {
        tostring(value.key)
    }
    if choiceStr and choiceStr ~= tostring(value.key) and not arg3 then
        table.insert(list, choiceStr)
    end
    for i, item in ipairs(list) do
        if i == 2 then
            local value
            for _, room in ipairs(Dungeon.rooms(arg1)) do
                if tostring(room.key) == item then
                    value = room
                end
            end
            App.log(1, "DUNGEON", string.format("the game only lets the run enter its selected room %s: %s", item, value and Dungeon.roomName(value) or "?"))
        end
        local _, res = App.request("dgEnter", "dungeon_enter_room", item)
        local now = Utils.now()
        while App.alive and Utils.now() - now < 15 do
            task.wait(1)
        end
        if not App.alive then
            return true
        end
        App.log(1, "DUNGEON", string.format("no teleport after entering room %s (answer %s)", item, tostring(res)))
    end
    Dungeon.logState(arg1, "enter didn't teleport")
    Brain.pending = nil
    if not arg3 then
        Modes.rec("dg").restUntil = os.time() + 900
    end
    App.saveSoon()
    return false
end

function Dungeon.chain()
    task.wait(4)
    local value = Dungeon.data()
    if not (value and value._started) then
        return false
    end
    return Dungeon.enter(value, Config.dungeonValue, true)
end

function Dungeon.roomDone(arg1)
    Brain.dg.playLast = nil
    local depth = tonumber(type(Match.ld._dungeon) == "table" and Match.ld._dungeon.depth) or (Brain.pending and tonumber(Brain.pending.depth)) or 1
    local value = tostring(math.min(4, math.max(1, math.ceil(depth / 5))))
    local value2 = Brain.dg.depth [value] or {
        runs = 0,
        wins = 0
    }
    value2.runs, value2.wins = (tonumber(value2.runs) or 0) + 1, (tonumber(value2.wins) or 0) + (arg1 and 1 or 0)
    Brain.dg.depth [value] = value2
    local value = Dungeon.data()
    local res, res2, res3 = Dungeon.res(value)
    Dungeon.note(string.format("room %d/%d %s · %d coins · chests %d + %d rare · %d lives", depth, Dungeon.ROOMS, arg1 and "cleared" or "lost", res, res2, res3, Dungeon.lives(value)))
    Brain.dg.teams = type(Brain.dg.teams) == "table" and Brain.dg.teams or {
    }
    local team = Brain.dg.teams [Modes.teamSig()] or {
        w = 0,
        l = 0
    }
    if arg1 then
        team.w = (tonumber(team.w) or 0) + 1
    else
        team.l = (tonumber(team.l) or 0) + 1
    end
    Brain.dg.teams [Modes.teamSig()] = team
    if arg1 then
        Brain.dg.lives = 5
    elseif Brain.dg.room and Brain.dg.room.d == depth then
        Brain.dg.lost = Brain.dg.lost or {
        }
        local seed, teamSig = tostring(Brain.dg.room.seed), Modes.teamSig()
        Brain.dg.lost [seed] = Brain.dg.lost [seed] or {
        }
        Brain.dg.lost [seed] [teamSig] = (Brain.dg.lost [seed] [teamSig] or 0) + 1
    end
end

function Dungeon.text()
    if not Config.dungeon then
        return "Off."
    end
    local value = Dungeon.data()
    if not value then
        return "No dungeon data yet (shows in the lobby)."
    end
    if not value._started then
        return Config.dungeonStart and "No run going: the farm starts one when the dungeon ranks first." or "No run going (starting new runs is off)."
    end
    local res, res2, res3 = Dungeon.res(value)
    local list, list2 = {
    }, {
    }
    for itemKey, item in pairs(Dungeon.items(value)) do
        local text = tostring((Dungeon.item(itemKey) or {
        }).name or itemKey) .. (item > 1 and (" ×" .. item) or "")
        table.insert(Dungeon.isCurse(itemKey) and list2 or list, text)
    end
    local list3 = {
        string.format("Room %s/%d · %d lives · %d coins · chests %d + %d rare · luck ×%.1f",
        tostring(Dungeon.depth(value) or "?"),
        Dungeon.ROOMS,
        Dungeon.lives(value),
        res,
        res2,
        res3,
        Dungeon.luck(value))
    }
    table.insert(list3, "Items: " .. (# list > 0 and table.concat(list, ", ") or "none") .. " · Curses: " .. (# list2 > 0 and table.concat(list2, ", ") or "none"))
    table.insert(list3, "They add up to: " .. Dungeon.fxText(Dungeon.fx(value)))
    local x = Dungeon._pick and Dungeon._pick.x
    if x then
        table.insert(list3, string.format("Next: %s, win ≈%d%%", Dungeon.roomName(x), math.floor((x.p or 0) * 100 + 0.5)))
    end
    local plan = Dungeon._pick and Dungeon._pick.plan
    if plan and plan.best then
        table.insert(list3, Dungeon.planText(plan))
    end
    for i, value in ipairs(Brain.dg.log) do
        if i <= 4 then
            table.insert(list3, os.date("%H:%M ", value.at) .. value.msg)
        end
    end
    return table.concat(list3, "\n")
end
