    AI.CARD_NET = CARD_NET

    local LN10 = 2.302585092994046
    local GROUND_PROBE = { hill_unit = false, hybrid_placement = false }
    local HILL_PROBE = { hill_unit = true, hybrid_placement = false }
    local EMPTY_LIST = {}

    local GRID_CELL = 22
    local SAMPLE_GRID_CELL = 28
    local GRID_OFF = 32768
    local GRID_STRIDE = 65536

    local VEC_RAY_UP = nil
    local VEC_RAY_DN = nil
    local VEC_PROBE_Y = nil
    local VEC_CLEAR35 = nil
    local VEC_CLEAR24 = nil
    if Vector3 and Vector3.new then
        VEC_RAY_UP = Vector3.new(0, 40, 0)
        VEC_RAY_DN = Vector3.new(0, -120, 0)
        VEC_PROBE_Y = Vector3.new(0, 1.35, 0)
        VEC_CLEAR35 = Vector3.new(3.5, 2.5, 3.5)
        VEC_CLEAR24 = Vector3.new(4.8, 2.5, 4.8)
    end

    local function gridKey(cx, cz)
        return (cx + GRID_OFF) * GRID_STRIDE + (cz + GRID_OFF)
    end

    local function spotKey2(isHill, x, z)
        local prefix = "G:"
        if isHill then
            prefix = "H:"
        end
        return prefix .. tostring(math.floor(x * 2 + 0.5)) .. "," .. tostring(math.floor(z * 2 + 0.5))
    end

    local function xzKey2(x, z)
        return tostring(math.floor(x * 2 + 0.5)) .. "," .. tostring(math.floor(z * 2 + 0.5))
    end

    local function safePivotPos(model)
        return model:GetPivot().Position
    end

    local function probeBlocked35(pos)
        Match.probe.Size = VEC_CLEAR35
        Match.probe.CFrame = CFrame.new(pos + VEC_PROBE_Y)
        return #workspace:GetPartsInPart(Match.probe, Match.overlap) > 0
    end

    local function probeClear24(pos)
        Match.probe.Size = VEC_CLEAR24
        Match.probe.CFrame = CFrame.new(pos + VEC_PROBE_Y)
        return #workspace:GetPartsInPart(Match.probe, Match.overlap) == 0
    end

    local function getBuffKind(allyBuff, unitId)
        if type(allyBuff) == "table" and type(allyBuff.types) == "table" then
            if (tonumber(allyBuff.types.magic) or 0) > 0 then
                return "magic"
            end
            if (tonumber(allyBuff.types.physical) or 0) > 0 then
                return "physical"
            end
            for k, rate in pairs(allyBuff.types) do
                if (tonumber(rate) or 0) > 0 then
                    return tostring(k)
                end
            end
        end
        if unitId and Units and Units.types then
            local _, baseType = Units.types(unitId)
            return tostring(baseType or "physical")
        end
        return "physical"
    end

    local function buffMatchesKind(allyBuff, buffKind, dmgKind)
        if not dmgKind then
            return false
        end
        if type(allyBuff) == "table" and type(allyBuff.types) == "table" then
            if (tonumber(allyBuff.types[dmgKind]) or 0) > 0 then
                return true
            end
        end
        return buffKind == dmgKind
    end

    local function normalizeAoe(atkInfo, fullR)
        if type(atkInfo) ~= "table" then
            return { type = "single" }
        end
        if atkInfo.full then
            return { type = "full_aoe" }
        end
        local sh = atkInfo.shape
        if type(sh) ~= "table" or not sh.type then
            return { type = "single" }
        end
        local kind = tostring(sh.type)
        if kind == "target_aoe_circ" or kind == "circ" then
            kind = "circle"
        elseif kind == "straight" then
            kind = "line"
        elseif kind == "full" then
            kind = "full_aoe"
        end
        if kind == "circle" then
            return {
                type = "circle",
                radius = tonumber(sh.radius) or 8,
            }
        elseif kind == "line" then
            return {
                type = "line",
                length = tonumber(sh.length) or fullR,
                width = tonumber(sh.width) or 6,
            }
        elseif kind == "cone" then
            return {
                type = "cone",
                angle = tonumber(sh.angle) or 45,
            }
        elseif kind == "full_aoe" then
            return { type = "full_aoe" }
        end
        return { type = "single" }
    end

    local function checkClear24(cache, pos, key)
        local cached = cache.clear24[key]
        if cached ~= nil then
            return cached
        end
        local isClear = true
        if Match and Match.probe and Match.overlap and VEC_CLEAR24 and typeof and typeof(pos) == "Vector3" then
            local okP, resP = pcall(probeClear24, pos)
            if okP then
                isClear = (resP == true)
            end
        end
        cache.clear24[key] = isClear
        return isClear
    end

    local function clearArray(t)
        for i = #t, 1, -1 do
            t[i] = nil
        end
    end

    local function clearMap(t)
        for k in pairs(t) do
            t[k] = nil
        end
    end

    local function initNetBuffers(net)
        if not net or type(net.dims) ~= "table" then
            return
        end
        local dims = net.dims
        local nDims = #dims
        local inB = net._inBuf or {}
        local h1B = net._h1Buf or {}
        local h2B = net._h2Buf or {}
        local outB = net._outBuf or {}
        for i = 1, (dims[1] or 0) do
            inB[i] = 0.0
        end
        for i = 1, (dims[2] or 0) do
            h1B[i] = 0.0
        end
        for i = 1, (dims[3] or 0) do
            h2B[i] = 0.0
        end
        for i = 1, (dims[4] or 0) do
            outB[i] = 0.0
        end
        net._inBuf = inB
        net._h1Buf = h1B
        net._h2Buf = h2B
        net._outBuf = outB
        if nDims == 4 then
            net._act = { inB, h1B, h2B, outB }
        else
            local act = {}
            for li = 1, nDims do
                act[li] = {}
            end
            net._act = act
        end
    end

    initNetBuffers(PLACEMENT_NET)
    initNetBuffers(TARGET_NET)
    initNetBuffers(ECONOMY_NET)
    initNetBuffers(ACTIVE_NET)
    initNetBuffers(SKIP_NET)
    initNetBuffers(TEAM_NET)
    initNetBuffers(CARD_NET)

    AI._pFeatBuf = {}
    AI._pPlacedListBuf = {}
    AI._pPlacedRowPool = {}
    AI._pTeamByUuidBuf = {}
    AI._pTeamByIdBuf = {}
    AI._pRoadDpsBuf = {}
    AI._pRoadCtrlBuf = {}
    AI._pSameBufsBuf = {}
    AI._pMatchAtksBuf = {}
    AI._pInRangeBuf = {}
    AI._pLaneSeenBuf = {}
    AI._pStepCtxBuf = {}
    AI._pWorkCandsBuf = {}
    AI._pSeenCandBuf = {}
    AI._tFeatBuf = {}
    AI._tInRangeBuf = {}
    AI._tLaneSeenBuf = {}
    AI._tLogitsBuf = { 0.0, 0.0, 0.0, 0.0 }
    AI._eFeatBuf = {}
    AI._bpLookaheadBuf = {}
    AI._econNormBuf = {}
    AI._econSaveActBuf = {}
    AI._econStateBuf = {}
    AI._econActionsBuf = {}
    AI._econActionPool = {}
    AI._econEnvBuf = {}
    AI._econCandBuf = {}
    AI._econFilterBuf = {}
    AI._unitMaxDpsByIdBuf = {}
    AI._placedByIdBuf = {}
    AI._teamEconCache = nil
    AI._lastEconEnvOptions = nil
    AI._lastEconEnv = nil
    AI._unitBornAt = setmetatable({}, { __mode = "k" })
    AI._soldSpots = {}
    AI._sellTried = setmetatable({}, { __mode = "k" })
    AI._lastStarterSell = -9999
    AI._starterSellCount = 0
    AI._econRowsCache = {}
    AI._aFeatBuf = {}
    AI._sFeatBuf = {}
    AI._teamFeatBuf = {}
    AI._cFeatBuf = {}
    AI._matchLog = nil
    AI._matchLogFlushed = false
    AI._matchLogSeq = 0
    AI._lastSkipEvalWave = -1
    AI._lastBaseHp = nil
    AI._leakEvents = 0

    function AI.resetCache()
        AI._mapCache = nil
        clearArray(AI._pPlacedListBuf)
        clearMap(AI._pTeamByUuidBuf)
        clearMap(AI._pTeamByIdBuf)
        clearArray(AI._pSameBufsBuf)
        clearArray(AI._pMatchAtksBuf)
        clearArray(AI._pWorkCandsBuf)
        clearMap(AI._pSeenCandBuf)
        clearArray(AI._econActionsBuf)
        clearArray(AI._econCandBuf)
        clearArray(AI._econFilterBuf)
        clearMap(AI._unitMaxDpsByIdBuf)
        clearMap(AI._placedByIdBuf)
        AI._teamEconCache = nil
        AI._lastEconEnvOptions = nil
        AI._lastEconEnv = nil
        AI._matchLog = nil
        AI._matchLogFlushed = false
        AI._unitBornAt = setmetatable({}, { __mode = "k" })
        clearMap(AI._soldSpots)
        AI._sellTried = setmetatable({}, { __mode = "k" })
        AI._lastStarterSell = -9999
        AI._starterSellCount = 0
        clearMap(AI._econRowsCache)
        AI._lastSkipEvalWave = -1
        AI._lastBaseHp = nil
        AI._leakEvents = 0
    end

    -- Zero-allocation 4x-unrolled MLP Forward (exact IEEE-754 left-to-right parity with engine/mlp.js)
    local function forwardMLP(net, x)
        local dims = net.dims
        local nDims = #dims
        local h1 = net._h1Buf
        if not h1 then
            initNetBuffers(net)
            h1 = net._h1Buf
        end

        if nDims == 4 then
            local d1 = dims[1]
            local d2 = dims[2]
            local d3 = dims[3]
            local d4 = dims[4]
            local inB = net._inBuf
            local h2 = net._h2Buf
            local outB = net._outBuf
            local W = net.W
            local B = net.b
            local w1 = W[1]
            local b1 = B[1]
            local w2 = W[2]
            local b2 = B[2]
            local w3 = W[3]
            local b3 = B[3]

            for i = 1, d1 do
                inB[i] = x[i] or 0
            end

            local d1_4 = d1 - (d1 % 4)
            local rowOff1 = 0
            for o = 1, d2 do
                local sum = b1[o]
                for i = 1, d1_4, 4 do
                    local ri = rowOff1 + i
                    sum = sum
                        + w1[ri] * inB[i]
                        + w1[ri + 1] * inB[i + 1]
                        + w1[ri + 2] * inB[i + 2]
                        + w1[ri + 3] * inB[i + 3]
                end
                for i = d1_4 + 1, d1 do
                    sum = sum + w1[rowOff1 + i] * inB[i]
                end
                if sum > 0 then
                    h1[o] = sum
                else
                    h1[o] = 0
                end
                rowOff1 = rowOff1 + d1
            end

            local d2_4 = d2 - (d2 % 4)
            local rowOff2 = 0
            for o = 1, d3 do
                local sum = b2[o]
                for i = 1, d2_4, 4 do
                    local ri = rowOff2 + i
                    sum = sum
                        + w2[ri] * h1[i]
                        + w2[ri + 1] * h1[i + 1]
                        + w2[ri + 2] * h1[i + 2]
                        + w2[ri + 3] * h1[i + 3]
                end
                for i = d2_4 + 1, d2 do
                    sum = sum + w2[rowOff2 + i] * h1[i]
                end
                if sum > 0 then
                    h2[o] = sum
                else
                    h2[o] = 0
                end
                rowOff2 = rowOff2 + d2
            end

            local d3_4 = d3 - (d3 % 4)
            local rowOff3 = 0
            for o = 1, d4 do
                local sum = b3[o]
                for i = 1, d3_4, 4 do
                    local ri = rowOff3 + i
                    sum = sum
                        + w3[ri] * h2[i]
                        + w3[ri + 1] * h2[i + 1]
                        + w3[ri + 2] * h2[i + 2]
                        + w3[ri + 3] * h2[i + 3]
                end
                for i = d3_4 + 1, d3 do
                    sum = sum + w3[rowOff3 + i] * h2[i]
                end
                outB[o] = sum
                rowOff3 = rowOff3 + d3
            end

            return outB
        end

        local numLayers = nDims - 1
        local act = net._act
        local a0 = act[1]
        local d0 = dims[1]
        for i = 1, d0 do
            a0[i] = x[i] or 0
        end

        for l = 1, numLayers do
            local inD = dims[l]
            local outD = dims[l + 1]
            local prev = act[l]
            local curr = act[l + 1]
            local wl = net.W[l]
            local bl = net.b[l]
            local isLast = (l == numLayers)
            local inD4 = inD - (inD % 4)
            local rowOff = 0

            for o = 1, outD do
                local sum = bl[o]
                for i = 1, inD4, 4 do
                    local ri = rowOff + i
                    sum = sum
                        + wl[ri] * prev[i]
                        + wl[ri + 1] * prev[i + 1]
                        + wl[ri + 2] * prev[i + 2]
                        + wl[ri + 3] * prev[i + 3]
                end
                for i = inD4 + 1, inD do
                    sum = sum + wl[rowOff + i] * prev[i]
                end
                if isLast then
                    curr[o] = sum
                else
                    if sum > 0 then
                        curr[o] = sum
                    else
                        curr[o] = 0
                    end
                end
                rowOff = rowOff + inD
            end
        end
        return act[numLayers + 1]
    end

    AI.forward = forwardMLP
    AI.forwardMLP = forwardMLP

    function AI.scorePlacement(feat)
        local out = forwardMLP(AI.PLACEMENT_NET, feat)
        return out[1]
    end

    function AI.predictTarget(feat)
        local out = forwardMLP(AI.TARGET_NET, feat)
        local bestIdx = 1
        local bestVal = out[1]
        local logits = AI._tLogitsBuf
        logits[1] = bestVal
        local nOut = #out
        for c = 2, nOut do
            local v = out[c]
            logits[c] = v
            if v > bestVal then
                bestVal = v
                bestIdx = c
            end
        end
        return bestIdx - 1, logits
    end

    -- Static per-match geometric cache (rebuilt automatically whenever Match.samples changes)
    function AI.ensureMapCache()
        local samples = Match.samples
        local cands = Match.cands
        if AI._mapCache and AI._mapCache.samplesRef == samples and AI._mapCache.candsRef == cands then
            return AI._mapCache
        end

        local sx, sz, sp, sl, sc = {}, {}, {}, {}, {}
        local laneMap = {}
        local numLanes = 0
        local nS = samples and #samples or 0

        for i = 1, nS do
            local s = samples[i]
            local p = s.flat or s.pos
            sx[i] = p.X
            sz[i] = p.Z
            sp[i] = tonumber(s.prog) or 0
            local lk = tostring(s.lane or "1")
            local li = laneMap[lk]
            if li == nil then
                li = numLanes
                laneMap[lk] = li
                numLanes = numLanes + 1
            end
            sl[i] = li
            sc[i] = 0
        end
        if numLanes < 1 then
            numLanes = 1
        end

        -- Per-sample unit tangent vectors along same lane, then curvature via abs(atan2(cross, dot)) / pi
        local tx, tz = {}, {}
        for i = 1, nS do
            local ux, uz = 1, 0
            if i < nS and sl[i + 1] == sl[i] then
                ux = sx[i + 1] - sx[i]
                uz = sz[i + 1] - sz[i]
            elseif i > 1 and sl[i - 1] == sl[i] then
                ux = sx[i] - sx[i - 1]
                uz = sz[i] - sz[i - 1]
            end
            local len = math.sqrt(ux * ux + uz * uz)
            if len > 1e-5 then
                tx[i] = ux / len
                tz[i] = uz / len
            elseif i > 1 and sl[i - 1] == sl[i] then
                tx[i] = tx[i - 1] or 1
                tz[i] = tz[i - 1] or 0
            else
                tx[i] = 1
                tz[i] = 0
            end
        end

        for i = 1, nS do
            local laneI = sl[i]
            local prevIdx = i
            local nextIdx = i
            for k = 1, 3 do
                if i - k >= 1 and sl[i - k] == laneI then
                    prevIdx = i - k
                end
                if i + k <= nS and sl[i + k] == laneI then
                    nextIdx = i + k
                end
            end
            local ax, az = tx[prevIdx], tz[prevIdx]
            local bx, bz = tx[nextIdx], tz[nextIdx]
            local cross = ax * bz - az * bx
            local dot = ax * bx + az * bz
            sc[i] = math.abs(math.atan2(cross, dot)) / math.pi
        end

        -- Build static groundSpots / hillSpots pools from Match.cands (reuses & populates Match._staticCache)
        local groundSpots = {}
        local hillSpots = {}
        local groundCands = {}
        local hillCands = {}
        local gx, gz = {}, {}
        local hx, hz = {}, {}
        local gSeen = {}
        local hSeen = {}
        local canRay = (Core and Core.PC and Core.PC.raycast and Core.PC.is_valid_raycast_hit and VEC_RAY_UP) ~= nil
        local hasProbe = (Match and Match.probe and Match.overlap and VEC_CLEAR35) ~= nil
        local sCache = Match and Match._staticCache
        local nCands = cands and #cands or 0
        local rayCount = 0

        for idx = 1, nCands do
            local cand = cands[idx]
            if cand then
                local gPos = cand
                local hPos = cand
                local isG = false
                local isH = false
                if canRay then
                    local gSKey = nil
                    local hSKey = nil
                    local gCached = nil
                    local hCached = nil
                    if sCache and cand.X and cand.Z then
                        gSKey = string.format("%.1f,%.1f:G:N:18", cand.X, cand.Z)
                        hSKey = string.format("%.1f,%.1f:H:N:18", cand.X, cand.Z)
                        gCached = sCache[gSKey]
                        hCached = sCache[hSKey]
                    end
                    if gCached ~= nil and hCached ~= nil then
                        if gCached ~= false then
                            isG = true
                            gPos = gCached
                        end
                        if hCached ~= false then
                            isH = true
                            hPos = hCached
                        end
                        if idx % 240 == 0 and task and task.wait then
                            task.wait()
                        end
                    else
                        rayCount = rayCount + 1
                        if rayCount % 60 == 0 and task and task.wait then
                            task.wait()
                        end
                        local okR, ray = pcall(Core.PC.raycast, cand + VEC_RAY_UP, VEC_RAY_DN)
                        if okR then
                            if ray and ray.Instance then
                                local pos = ray.Position
                                local okG, resG = pcall(Core.PC.is_valid_raycast_hit, ray.Instance, GROUND_PROBE)
                                local okH, resH = pcall(Core.PC.is_valid_raycast_hit, ray.Instance, HILL_PROBE)
                                isG = (okG and resG == true)
                                isH = (okH and resH == true)
                                local okO = true
                                if (isG or isH) and hasProbe then
                                    local blocked = false
                                    okO, blocked = pcall(probeBlocked35, pos)
                                    if okO and blocked then
                                        isG = false
                                        isH = false
                                    end
                                end
                                gPos = pos
                                hPos = pos
                                if sCache and hasProbe and okG and okH and okO and gSKey and hSKey then
                                    if isG then
                                        sCache[gSKey] = pos
                                    else
                                        sCache[gSKey] = false
                                    end
                                    if isH then
                                        sCache[hSKey] = pos
                                    else
                                        sCache[hSKey] = false
                                    end
                                end
                            elseif sCache and hasProbe and gSKey and hSKey then
                                sCache[gSKey] = false
                                sCache[hSKey] = false
                            end
                        end
                    end
                else
                    isG = true
                end

                if isG then
                    table.insert(groundCands, cand)
                    local gk = spotKey2(false, gPos.X, gPos.Z)
                    if not gSeen[gk] then
                        gSeen[gk] = true
                        local gi = #groundSpots + 1
                        groundSpots[gi] = { x = gPos.X, z = gPos.Z, k = gk }
                        gx[gi] = gPos.X
                        gz[gi] = gPos.Z
                    end
                end
                if isH then
                    table.insert(hillCands, cand)
                    local hk = spotKey2(true, hPos.X, hPos.Z)
                    if not hSeen[hk] then
                        hSeen[hk] = true
                        local hi = #hillSpots + 1
                        hillSpots[hi] = { x = hPos.X, z = hPos.Z, k = hk }
                        hx[hi] = hPos.X
                        hz[hi] = hPos.Z
                    end
                end
            end
        end

        -- 2D spatial grid hashes (cell size 22 for ground/hill neighbor counts, 28 for road cov28)
        -- Guarantees O(N) runtime with 0 numerical difference from brute-force scans!
        local nG = #groundSpots
        local nH = #hillSpots
        local gGrid = {}
        for i = 1, nG do
            local ck = gridKey(math.floor(gx[i] / GRID_CELL), math.floor(gz[i] / GRID_CELL))
            local b = gGrid[ck]
            if not b then
                b = {}
                gGrid[ck] = b
            end
            b[#b + 1] = i
        end

        local hGrid = {}
        for i = 1, nH do
            local ck = gridKey(math.floor(hx[i] / GRID_CELL), math.floor(hz[i] / GRID_CELL))
            local b = hGrid[ck]
            if not b then
                b = {}
                hGrid[ck] = b
            end
            b[#b + 1] = i
        end

        local sGrid = {}
        for i = 1, nS do
            local ck = gridKey(math.floor(sx[i] / SAMPLE_GRID_CELL), math.floor(sz[i] / SAMPLE_GRID_CELL))
            local b = sGrid[ck]
            if not b then
                b = {}
                sGrid[ck] = b
            end
            b[#b + 1] = i
        end

        local groundFree20 = {}
        local hillNear22 = {}
        local spotCov28 = {}

        local function computeGroundFree20(x, z, k)
            local cached = groundFree20[k]
            if cached ~= nil then
                return cached
            end
            local gCnt = 0
            local minCx = math.floor((x - 20.001) / GRID_CELL)
            local maxCx = math.floor((x + 20.001) / GRID_CELL)
            local minCz = math.floor((z - 20.001) / GRID_CELL)
            local maxCz = math.floor((z + 20.001) / GRID_CELL)
            for cx = minCx, maxCx do
                for cz = minCz, maxCz do
                    local bucket = gGrid[gridKey(cx, cz)]
                    if bucket then
                        for bi = 1, #bucket do
                            local idx = bucket[bi]
                            local dx = gx[idx] - x
                            local dz = gz[idx] - z
                            if dx * dx + dz * dz <= 400 then
                                gCnt = gCnt + 1
                            end
                        end
                    end
                end
            end
            local val = math.min(1.0, gCnt / 28.0)
            groundFree20[k] = val
            return val
        end

        local function computeHillNear22(x, z, k)
            local cached = hillNear22[k]
            if cached ~= nil then
                return cached
            end
            local hCnt = 0
            local minCx = math.floor((x - 22.001) / GRID_CELL)
            local maxCx = math.floor((x + 22.001) / GRID_CELL)
            local minCz = math.floor((z - 22.001) / GRID_CELL)
            local maxCz = math.floor((z + 22.001) / GRID_CELL)
            for cx = minCx, maxCx do
                for cz = minCz, maxCz do
                    local bucket = hGrid[gridKey(cx, cz)]
                    if bucket then
                        for bi = 1, #bucket do
                            local idx = bucket[bi]
                            local dx = hx[idx] - x
                            local dz = hz[idx] - z
                            if dx * dx + dz * dz <= 484 then
                                hCnt = hCnt + 1
                            end
                        end
                    end
                end
            end
            local val = math.min(1.0, hCnt / 10.0)
            hillNear22[k] = val
            return val
        end

        local function computeSpotCov28(x, z, k)
            local cached = spotCov28[k]
            if cached ~= nil then
                return cached
            end
            local c = 0
            local minCx = math.floor((x - 28.001) / SAMPLE_GRID_CELL)
            local maxCx = math.floor((x + 28.001) / SAMPLE_GRID_CELL)
            local minCz = math.floor((z - 28.001) / SAMPLE_GRID_CELL)
            local maxCz = math.floor((z + 28.001) / SAMPLE_GRID_CELL)
            for cx = minCx, maxCx do
                for cz = minCz, maxCz do
                    local bucket = sGrid[gridKey(cx, cz)]
                    if bucket then
                        for bi = 1, #bucket do
                            local idx = bucket[bi]
                            local dx = sx[idx] - x
                            local dz = sz[idx] - z
                            if dx * dx + dz * dz <= 784 then
                                c = c + 1
                            end
                        end
                    end
                end
            end
            local frac = c / math.max(1, nS)
            spotCov28[k] = frac
            return frac
        end

        local covs = {}
        for i = 1, nG do
            if i % 80 == 0 and task and task.wait then
                task.wait()
            end
            local gs = groundSpots[i]
            computeGroundFree20(gs.x, gs.z, gs.k)
            computeHillNear22(gs.x, gs.z, gs.k)
            local frac = computeSpotCov28(gs.x, gs.z, gs.k)
            covs[i] = frac
        end
        for i = 1, nH do
            if i % 80 == 0 and task and task.wait then
                task.wait()
            end
            local hs = hillSpots[i]
            computeGroundFree20(hs.x, hs.z, hs.k)
            computeHillNear22(hs.x, hs.z, hs.k)
        end

        table.sort(covs)
        local primeThresh = 0.25
        if #covs > 0 then
            local pIdx = math.min(#covs, math.floor(#covs * 0.78) + 1)
            primeThresh = covs[pIdx]
        end

        local distRoadCache = {}
        local nearProgCache = {}

        local function distAndProg(x, z, xzk)
            local ck = xzk or xzKey2(x, z)
            local cDist = distRoadCache[ck]
            if cDist ~= nil then
                return cDist, nearProgCache[ck]
            end
            if Match and Match.progressAt and not Match.laneCut and Vector3 and Vector3.new then
                local okP, prog, dist = pcall(Match.progressAt, Vector3.new(x, 0, z))
                if okP and type(prog) == "number" and type(dist) == "number" and dist < 1e9 then
                    distRoadCache[ck] = dist
                    nearProgCache[ck] = prog
                    return dist, prog
                end
            end
            local bestD2 = math.huge
            local bestProg = 0
            for i = 1, nS do
                local dx = sx[i] - x
                local dz = sz[i] - z
                local d2 = dx * dx + dz * dz
                if d2 < bestD2 then
                    bestD2 = d2
                    bestProg = sp[i]
                end
            end
            local outDist = 0
            if bestD2 < math.huge then
                outDist = math.sqrt(bestD2)
            end
            distRoadCache[ck] = outDist
            nearProgCache[ck] = bestProg
            return outDist, bestProg
        end

        local cache = {
            samplesRef = samples,
            candsRef = cands,
            canRay = canRay,
            hasProbe = hasProbe,
            nS = nS,
            sampleX = sx,
            sampleZ = sz,
            sampleProg = sp,
            sampleLane = sl,
            sampleCurv = sc,
            laneMap = laneMap,
            numLanes = numLanes,
            groundSpots = groundSpots,
            hillSpots = hillSpots,
            groundCands = groundCands,
            hillCands = hillCands,
            hillKeySet = hSeen,
            groundFree20 = groundFree20,
            hillNear22 = hillNear22,
            spotCov28 = spotCov28,
            primeThresh = primeThresh,
            clear24 = {},
            getGroundFree20 = computeGroundFree20,
            getHillNear22 = computeHillNear22,
            getSpotCov28 = computeSpotCov28,
            distAndProg = distAndProg,
        }
        AI._mapCache = cache
        return cache
    end

    -- Exact 2D AoE hits at target sample index tIdx (1-indexed mirror of features.js aoeHitsAtSample)
    local function aoeHitsAtSample(cache, ux, uz, fullR, aoe, inRangeIdxs, nIn, tIdx)
        local sx = cache.sampleX
        local sz = cache.sampleZ
        local nS = cache.nS
        local tx = sx[tIdx]
        local tz = sz[tIdx]
        local kind = "single"
        if aoe and aoe.type then
            kind = aoe.type
        end
        if kind == "single" then
            return 1
        end
        if kind == "full_aoe" then
            return nIn
        end

        local hits = 0
        if kind == "circle" then
            local rad = (aoe and aoe.radius) or 8
            local r2 = rad * rad
            for i = 1, nS do
                local dx = sx[i] - tx
                local dz = sz[i] - tz
                if dx * dx + dz * dz <= r2 then
                    hits = hits + 1
                end
            end
            return hits
        end

        local vx0 = tx - ux
        local vz0 = tz - uz
        local len0 = math.sqrt(vx0 * vx0 + vz0 * vz0)
        local dirX = 1
        local dirZ = 0
        if len0 > 1e-5 then
            dirX = vx0 / len0
            dirZ = vz0 / len0
        end

        if kind == "line" then
            local L = (aoe and aoe.length) or fullR
            local halfW = ((aoe and aoe.width) or 6) * 0.5
            for i = 1, nS do
                local vx = sx[i] - ux
                local vz = sz[i] - uz
                local along = vx * dirX + vz * dirZ
                if along >= 0 and along <= L then
                    local cross = vx * dirZ - vz * dirX
                    if cross < 0 then
                        cross = -cross
                    end
                    if cross <= halfW then
                        hits = hits + 1
                    end
                end
            end
            return hits
        end

        if kind == "cone" then
            local ang = (aoe and aoe.angle) or 45
            local cosH = math.cos(math.rad(ang * 0.5))
            local cosH2 = cosH * cosH
            for k = 1, nIn do
                local i = inRangeIdxs[k]
                local vx = sx[i] - ux
                local vz = sz[i] - uz
                local d2 = vx * vx + vz * vz
                local dot = vx * dirX + vz * dirZ
                if dot >= 0 and dot * dot >= cosH2 * d2 then
                    hits = hits + 1
                end
            end
            return hits
        end

        return 1
    end

    -- Build normalized unit profile from team member table { id, u, uuid, data }
    local function buildUnitProfile(unit, isFarmArg)
        if type(unit) == "table" and unit._isProf then
            return unit
        end
        local id = unit.id
        local data = unit.data or (Core and Core.Units and Core.Units[id]) or {}
        local rangeScale = (Match and Match.info and tonumber(Match.info.rangeScale)) or 1
        local rows = Units and Units.rows and Units.rows(id) or nil
        local maxLvl = (rows and rows.max) or 0
        local maxRow = rows and rows[maxLvl]
        local row0 = rows and rows[0]

        local fullR = 20
        local earlyR = 20
        if unit.u and Units and Units.range then
            local okF, rF = pcall(Units.range, unit.u, maxLvl)
            local rFNum = okF and tonumber(rF) or nil
            if rFNum and rFNum > 0 then
                fullR = rFNum * rangeScale
            end
            local okE, rE = pcall(Units.range, unit.u, 0)
            local rENum = okE and tonumber(rE) or nil
            if rENum and rENum > 0 then
                earlyR = rENum * rangeScale
            else
                earlyR = fullR
            end
        else
            local rMaxRaw = maxRow and tonumber(maxRow.range) or nil
            if not rMaxRaw or rMaxRaw <= 0 then
                rMaxRaw = tonumber(data.range)
            end
            if not rMaxRaw or rMaxRaw <= 0 then
                rMaxRaw = 20
            end
            fullR = rMaxRaw * rangeScale
            local r0Raw = row0 and tonumber(row0.range) or nil
            if not r0Raw or r0Raw <= 0 then
                r0Raw = tonumber(data.range)
            end
            if r0Raw and r0Raw > 0 then
                earlyR = r0Raw * rangeScale
            else
                earlyR = fullR
            end
        end

        local isFarm = (isFarmArg == true) or (Units and Units.isFarm and Units.isFarm(id) == true)
        local allyBuff = Units and Units.allyBuff and Units.allyBuff(id) or nil
        local isBuff = (allyBuff ~= nil)
        local buffKind = nil
        if isBuff then
            buffKind = getBuffKind(allyBuff, id)
            fullR = earlyR
        end

        local dmgType = "physical"
        if Units and Units.types then
            local _, baseType = Units.types(id)
            if baseType then
                dmgType = tostring(baseType)
            end
        end

        local atkId = (maxRow and maxRow.atk) or data.primary_attack or data.primary_attack_no_upgrades
        local atkInfo = nil
        if atkId and atkId ~= "" and Units and Units.attackInfo then
            local okA, infoA = pcall(Units.attackInfo, atkId, fullR)
            if okA and type(infoA) == "table" then
                atkInfo = infoA
            end
        end

        local aoe = normalizeAoe(atkInfo, fullR)
        local isCC = false
        local hasBleed = false
        local hasMark = false
        if atkInfo then
            if (tonumber(atkInfo.slow) or 0) > 0 or (tonumber(atkInfo.stun) or 0) > 0 then
                isCC = true
            end
            if atkInfo.bleed then
                hasBleed = true
            end
            if (tonumber(atkInfo.amp) or 0) > 0 then
                hasMark = true
            end
        end
        local tip = Core and Core.TIPS and Core.TIPS[id]
        if tip and tip.target == "strongest" then
            hasMark = true
        end
        local hasClosest = (tip and tip.target == "closest") or (id == "sakamoto_evolved")

        local isHill = (data.hill_unit == true)
        local isHybrid = (data.hybrid_placement == true)
        local canAir = isHill or isHybrid
        if not canAir and Units and Units.airFrom then
            local okAir, fromLvl = pcall(Units.airFrom, id)
            if okAir and fromLvl ~= nil then
                canAir = true
            end
        end

        local rowCd = maxRow and tonumber(maxRow.cd) or nil
        local dataCd = tonumber(data.attack_cooldown)
        local effCd = 4
        if rowCd and rowCd > 0 then
            effCd = rowCd
        elseif dataCd and dataCd > 0 then
            effCd = dataCd
        end

        local dps = 0
        if not isFarm and not isBuff then
            if unit.u and Units and Units.dps then
                local okD, dVal = pcall(Units.dps, unit.u, maxLvl, Match and Match.mod)
                if okD and tonumber(dVal) and tonumber(dVal) > 0 then
                    dps = tonumber(dVal)
                end
            end
            if dps <= 0 then
                local rowDmg = maxRow and tonumber(maxRow.damage) or nil
                local dataDmg = tonumber(data.damage)
                local dmg = 100
                if rowDmg and rowDmg > 0 then
                    dmg = rowDmg
                elseif dataDmg and dataDmg > 0 then
                    dmg = dataDmg
                end
                dps = dmg / math.max(0.1, effCd)
            end
        end

        local copyCount = 1
        if unit.u and Units and Units.cap then
            local okC, capV = pcall(Units.cap, unit.u)
            if okC and tonumber(capV) then
                copyCount = math.max(1, tonumber(capV))
            end
        else
            local rawCap = tonumber(data.spawn_cap)
            if not rawCap and Units and Units.field then
                local okFc, fcVal = pcall(Units.field, id, "spawn_cap")
                if okFc then
                    rawCap = tonumber(fcVal)
                end
            end
            if rawCap then
                copyCount = math.max(1, rawCap)
            end
        end

        local placedSame = 0
        for _, m in ipairs(Match and Match.mine or EMPTY_LIST) do
            local st = m and m:FindFirstChild("_stats")
            if st and st:FindFirstChild("id") and st.id.Value == id then
                placedSame = placedSame + 1
            end
        end
        local copyIdx = math.min(math.max(0, copyCount - 1), placedSame)

        return {
            _isProf = true,
            id = id,
            uuid = unit.uuid,
            data = data,
            fullRange = fullR,
            earlyRange = earlyR,
            isFarm = isFarm,
            allyBuff = allyBuff,
            isBuff = isBuff,
            buffKind = buffKind,
            dmgType = dmgType,
            aoe = aoe,
            isCC = isCC,
            hasBleed = hasBleed,
            hasMark = hasMark,
            hasClosest = hasClosest,
            isHill = isHill,
            isHybrid = isHybrid,
            canAir = canAir,
            dps = dps,
            cd = effCd,
            copyIdx = copyIdx,
            copyCount = copyCount,
        }
    end

    -- Build normalized placed list from Match.mine (reusing AI._pPlacedListBuf & AI._pPlacedRowPool)
    local function buildPlacedList()
        local out = AI._pPlacedListBuf
        local pool = AI._pPlacedRowPool
        local outCount = 0
        local rangeScale = (Match and Match.info and tonumber(Match.info.rangeScale)) or 1
        local teamByUuid = AI._pTeamByUuidBuf
        local teamById = AI._pTeamByIdBuf
        clearMap(teamByUuid)
        clearMap(teamById)
        local teamList = (Match and Match.team) or EMPTY_LIST
        for i = 1, #teamList do
            local tm = teamList[i]
            if tm then
                if tm.uuid then
                    teamByUuid[tm.uuid] = tm
                end
                if tm.id and not teamById[tm.id] then
                    teamById[tm.id] = tm
                end
            end
        end

        local mineList = (Match and Match.mine) or EMPTY_LIST
        for i = 1, #mineList do
            local m = mineList[i]
            local st = m and m:FindFirstChild("_stats")
            if st and st:FindFirstChild("id") then
                local id = st.id.Value
                local okPos, piv = pcall(safePivotPos, m)
                if okPos and piv then
                    local isFarm = Units and Units.isFarm and (Units.isFarm(id) == true) or false
                    local allyBuff = Units and Units.allyBuff and Units.allyBuff(id) or nil
                    local isBuff = (allyBuff ~= nil)
                    local buffKind = nil
                    if isBuff then
                        buffKind = getBuffKind(allyBuff, id)
                    end
                    local dmgType = "physical"
                    if Units and Units.types then
                        local _, bt = Units.types(id)
                        if bt then
                            dmgType = tostring(bt)
                        end
                    end

                    local liveRange = st:FindFirstChild("range") and tonumber(st.range.Value) or 20
                    local uuidObj = st:FindFirstChild("uuid")
                    local tm = (uuidObj and teamByUuid[uuidObj.Value]) or teamById[id]
                    local rows = Units and Units.rows and Units.rows(id) or nil
                    local maxLvl = (rows and rows.max) or 0
                    local fullR = liveRange
                    if not isBuff and not isFarm then
                        if tm and tm.u and Units and Units.range then
                            local okR, rMax = pcall(Units.range, tm.u, maxLvl)
                            if okR and tonumber(rMax) and tonumber(rMax) > 0 then
                                fullR = math.max(liveRange, tonumber(rMax) * rangeScale)
                            end
                        elseif rows and rows[maxLvl] and tonumber(rows[maxLvl].range) and tonumber(rows[maxLvl].range) > 0 then
                            fullR = math.max(liveRange, tonumber(rows[maxLvl].range) * rangeScale)
                        end
                    end

                    local dps = 0
                    local isCC = false
                    if not isFarm and not isBuff then
                        if tm and tm.u and Units and Units.dps then
                            local okD, dMax = pcall(Units.dps, tm.u, maxLvl, Match and Match.mod)
                            if okD and tonumber(dMax) and tonumber(dMax) > 0 then
                                dps = tonumber(dMax)
                            end
                        end
                        if dps <= 0 and Match and Match.liveDps then
                            local okL, lVal = pcall(Match.liveDps, m, id)
                            if okL and tonumber(lVal) and tonumber(lVal) > 0 then
                                dps = tonumber(lVal)
                            end
                        end
                        if dps <= 0 then
                            dps = 100
                        end

                        local atkId = (rows and rows[maxLvl] and rows[maxLvl].atk) or (st:FindFirstChild("primary_attack") and st.primary_attack.Value)
                        if atkId and atkId ~= "" and Units and Units.attackInfo then
                            local okA, infoA = pcall(Units.attackInfo, atkId, fullR)
                            if okA and type(infoA) == "table" then
                                if (tonumber(infoA.slow) or 0) > 0 or (tonumber(infoA.stun) or 0) > 0 then
                                    isCC = true
                                end
                            end
                        end
                    end

                    outCount = outCount + 1
                    local row = pool[outCount]
                    if not row then
                        row = {}
                        pool[outCount] = row
                    end
                    row.id = id
                    row.x = piv.X
                    row.y = piv.Y
                    row.z = piv.Z
                    row.fullRange = fullR
                    row.isFarm = isFarm
                    row.allyBuff = allyBuff
                    row.isBuff = isBuff
                    row.buffKind = buffKind
                    row.dmgType = dmgType
                    row.dps = dps
                    row.isCC = isCC
                    out[outCount] = row
                end
            end
        end
        for i = #out, outCount + 1, -1 do
            out[i] = nil
        end
        return out
    end

    -- Precompute field context once per decision step (reuses step buffers & hoists invariant unit/team features _f26.._f36)
    local function buildStepContext(cache, placedList, prof)
        local nS = cache.nS
        local sx = cache.sampleX
        local sz = cache.sampleZ
        local roadDps = AI._pRoadDpsBuf
        local roadCtrl = AI._pRoadCtrlBuf
        for s = 1, nS do
            roadDps[s] = 0
            roadCtrl[s] = false
        end

        local maxRoadDps = 0
        local matchKind = prof.dmgType
        if prof.isBuff and prof.buffKind then
            matchKind = prof.buffKind
        end

        local sameKindBuffers = AI._pSameBufsBuf
        local matchAttackers = AI._pMatchAtksBuf
        clearArray(sameKindBuffers)
        clearArray(matchAttackers)
        local nSameBufs = 0
        local nMatchAtks = 0
        local totalMatchAtkDps = 0

        for i = 1, #placedList do
            local p = placedList[i]
            if p.isBuff and buffMatchesKind(p.allyBuff, p.buffKind, matchKind) then
                nSameBufs = nSameBufs + 1
                sameKindBuffers[nSameBufs] = p
            elseif not p.isFarm and not p.isBuff then
                if prof.isBuff then
                    if buffMatchesKind(prof.allyBuff, prof.buffKind, p.dmgType) then
                        nMatchAtks = nMatchAtks + 1
                        matchAttackers[nMatchAtks] = p
                        totalMatchAtkDps = totalMatchAtkDps + p.dps
                    end
                elseif p.dmgType == matchKind then
                    nMatchAtks = nMatchAtks + 1
                    matchAttackers[nMatchAtks] = p
                    totalMatchAtkDps = totalMatchAtkDps + p.dps
                end
                local r2 = p.fullRange * p.fullRange
                local dps = p.dps
                local isCtrl = p.isCC
                local px = p.x
                local pz = p.z
                for s = 1, nS do
                    local dx = sx[s] - px
                    local dz = sz[s] - pz
                    if dx * dx + dz * dz <= r2 then
                        local nd = roadDps[s] + dps
                        roadDps[s] = nd
                        if nd > maxRoadDps then
                            maxRoadDps = nd
                        end
                        if isCtrl then
                            roadCtrl[s] = true
                        end
                    end
                end
            end
        end

        local buffCx, buffCy, buffCz = 0, 0, 0
        local minBufR = 20
        if nSameBufs > 0 then
            minBufR = math.huge
            for i = 1, nSameBufs do
                local b = sameKindBuffers[i]
                buffCx = buffCx + b.x
                buffCy = buffCy + (b.y or 0)
                buffCz = buffCz + b.z
                if b.fullRange < minBufR then
                    minBufR = b.fullRange
                end
            end
            buffCx = buffCx / nSameBufs
            buffCy = buffCy / nSameBufs
            buffCz = buffCz / nSameBufs
        end

        local teamHasMatchingBuffer = (nSameBufs > 0)
        if not teamHasMatchingBuffer then
            local teamList = (Match and Match.team) or EMPTY_LIST
            for i = 1, #teamList do
                local tm = teamList[i]
                if tm and tm.id and Units and Units.allyBuff then
                    local ab = Units.allyBuff(tm.id)
                    if ab and (not Units.buffAllowed or Units.buffAllowed(tm.id)) then
                        if buffMatchesKind(ab, getBuffKind(ab, tm.id), matchKind) then
                            teamHasMatchingBuffer = true
                            break
                        end
                    end
                end
            end
        end

        local aoeType = "single"
        if prof.aoe and prof.aoe.type then
            aoeType = prof.aoe.type
        end
        local ctx = AI._pStepCtxBuf
        ctx.roadDps = roadDps
        ctx.roadCtrl = roadCtrl
        ctx.maxRoadDps = math.max(1, maxRoadDps)
        ctx.sameKindBuffers = sameKindBuffers
        ctx.matchAttackers = matchAttackers
        ctx.totalMatchAtkDps = math.max(1, totalMatchAtkDps)
        ctx.buffCx = buffCx
        ctx.buffCy = buffCy
        ctx.buffCz = buffCz
        ctx.minBufR = minBufR
        ctx.teamHasMatchingBuffer = teamHasMatchingBuffer
        ctx.prof = prof
        ctx.copyIdx = prof.copyIdx
        ctx.copyCount = prof.copyCount
        ctx.inRangeBuf = AI._pInRangeBuf
        ctx.laneSeenBuf = AI._pLaneSeenBuf

        if not prof.isFarm and not prof.isBuff and not prof.isCC then
            ctx._f26 = 1.0
        else
            ctx._f26 = 0.0
        end
        if prof.isBuff then
            ctx._f27 = 1.0
        else
            ctx._f27 = 0.0
        end
        if prof.isCC then
            ctx._f28 = 1.0
        else
            ctx._f28 = 0.0
        end
        if prof.isFarm then
            ctx._f29 = 1.0
        else
            ctx._f29 = 0.0
        end
        if aoeType == "line" then
            ctx._f30 = 1.0
        elseif aoeType == "cone" then
            ctx._f30 = 0.5
        else
            ctx._f30 = 0.0
        end
        if aoeType == "full_aoe" then
            ctx._f31 = 1.0
        elseif aoeType == "circle" then
            ctx._f31 = 0.5
        else
            ctx._f31 = 0.0
        end
        if prof.isHill then
            ctx._f32 = 1.0
        else
            ctx._f32 = 0.0
        end
        if prof.canAir then
            ctx._f33 = 1.0
        else
            ctx._f33 = 0.0
        end
        if teamHasMatchingBuffer then
            ctx._f34 = 1.0
        else
            ctx._f34 = 0.0
        end
        ctx._f35 = math.min(1.0, prof.fullRange / 50.0)
        if prof.copyCount > 1 then
            ctx._f36 = prof.copyIdx / (prof.copyCount - 1)
        else
            ctx._f36 = 0.0
        end

        return ctx
    end

    -- Exact 36 placement features: f[1]..f[36] === JS features.js f[0]..f[35]
    function AI.extractPlacementFeatures(cache, spot, unit, placedList, ctx, featBuf)
        local f = featBuf or {}
        if not cache then
            cache = AI.ensureMapCache()
        end
        local prof = buildUnitProfile(unit, false)
        local placed = placedList or buildPlacedList()
        if not ctx then
            ctx = buildStepContext(cache, placed, prof)
        end

        local x, z, spotPos
        local spotIsHill = false
        local distRoad, nearProg, clear24
        local xzKey, spKey
        if typeof and typeof(spot) == "Vector3" then
            x = spot.X
            z = spot.Z
            spotPos = spot
            xzKey = xzKey2(x, z)
            if prof.isHill and not prof.isHybrid then
                spotIsHill = true
            elseif prof.isHybrid then
                spotIsHill = (cache.hillKeySet["H:" .. xzKey] == true)
            end
            if spotIsHill then
                spKey = "H:" .. xzKey
            else
                spKey = "G:" .. xzKey
            end
            distRoad, nearProg = cache.distAndProg(x, z, xzKey)
            clear24 = checkClear24(cache, spotPos, spKey)
        else
            x = spot.x or spot.X or 0
            z = spot.z or spot.Z or 0
            spotPos = spot.pos
            spotIsHill = (spot.isHill == true)
            xzKey = xzKey2(x, z)
            if spotIsHill then
                spKey = "H:" .. xzKey
            else
                spKey = "G:" .. xzKey
            end
            if spot.distRoad ~= nil and spot.nearProg ~= nil then
                distRoad = spot.distRoad
                nearProg = spot.nearProg
            else
                distRoad, nearProg = cache.distAndProg(x, z, xzKey)
            end
            if spot.clearR ~= nil then
                clear24 = (spot.clearR >= 2.4)
            else
                clear24 = checkClear24(cache, spotPos, spKey)
            end
        end

        local fullR = prof.fullRange
        local earlyR = prof.earlyRange or fullR
        local fullR2 = fullR * fullR
        local earlyR2 = earlyR * earlyR

        local sx = cache.sampleX
        local sz = cache.sampleZ
        local sp = cache.sampleProg
        local sl = cache.sampleLane
        local sc = cache.sampleCurv
        local nS = cache.nS
        local roadDps = ctx.roadDps
        local roadCtrl = ctx.roadCtrl

        local inRange = ctx.inRangeBuf
        local laneSeen = ctx.laneSeenBuf
        for b = 0, 7 do
            laneSeen[b] = false
        end

        local nIn = 0
        local earlyCnt = 0
        local sumProg = 0
        local minProg = 1
        local maxProg = 0
        local sumCurv = 0
        local reentries = 0
        local prevIn = false
        local prevLane = -1
        local lanesHit = 0
        local sumRoadDps = 0
        local ctrlHits = 0

        for i = 1, nS do
            local dx = sx[i] - x
            local dz = sz[i] - z
            local d2 = dx * dx + dz * dz
            local lane = sl[i]
            if lane ~= prevLane then
                prevIn = false
                prevLane = lane
            end
            if d2 <= fullR2 then
                nIn = nIn + 1
                inRange[nIn] = i
                if not prevIn then
                    reentries = reentries + 1
                    prevIn = true
                end
                if d2 <= earlyR2 then
                    earlyCnt = earlyCnt + 1
                end
                local pr = sp[i]
                sumProg = sumProg + pr
                if pr < minProg then
                    minProg = pr
                end
                if pr > maxProg then
                    maxProg = pr
                end
                sumCurv = sumCurv + sc[i]
                local lb = lane % 8
                if not laneSeen[lb] then
                    laneSeen[lb] = true
                    lanesHit = lanesHit + 1
                end
                sumRoadDps = sumRoadDps + roadDps[i]
                if roadCtrl[i] then
                    ctrlHits = ctrlHits + 1
                end
            else
                prevIn = false
            end
        end

        -- Shape score: sample up to 6 representative targets along road in range
        local shapeScore = 0
        if nIn > 0 and not prof.isFarm and not prof.isBuff then
            local aoe = prof.aoe
            local aoeKind = "single"
            if aoe and aoe.type then
                aoeKind = aoe.type
            end
            if aoeKind == "full_aoe" then
                shapeScore = math.min(1.0, nIn / math.max(1, nS * 0.45))
            elseif aoeKind == "single" then
                shapeScore = math.min(1.0, nIn / math.max(1, nS * 0.35))
            else
                local bestH = 0
                local sumH = 0
                local cntH = 0
                local step = math.max(1, math.floor(nIn / 6))
                for k = 1, nIn, step do
                    local h = aoeHitsAtSample(cache, x, z, fullR, aoe, inRange, nIn, inRange[k])
                    if h > bestH then
                        bestH = h
                    end
                    sumH = sumH + h
                    cntH = cntH + 1
                end
                local effH = 0.55 * bestH + 0.45 * (sumH / math.max(1, cntH))
                shapeScore = math.min(1.0, effH / 22.0)
            end
        end

        -- 1..12 (JS 0..11): Geometry
        f[1] = nIn / math.max(1, nS)
        f[2] = earlyCnt / math.max(1, nS)
        if nIn > 0 then
            f[3] = sumProg / nIn
            f[4] = minProg
            f[5] = maxProg
            f[6] = maxProg - minProg
            f[8] = sumCurv / nIn
        else
            f[3] = nearProg
            f[4] = nearProg
            f[5] = nearProg
            f[6] = 0
            f[8] = 0
        end
        f[7] = math.min(1.0, reentries / 3.0)
        f[9] = lanesHit / math.max(1, cache.numLanes)
        f[10] = shapeScore
        f[11] = math.min(1.0, distRoad / 45.0)
        f[12] = nearProg

        -- 13..20 (JS 12..19): Buff Hub & Packing
        local bufs = ctx.sameKindBuffers
        local nBufs = #bufs
        local inBufCnt = 0
        local linkedBufCnt = 0
        for i = 1, nBufs do
            local b = bufs[i]
            local dx = x - b.x
            local dz = z - b.z
            local d2 = dx * dx + dz * dz
            if d2 <= b.fullRange * b.fullRange then
                inBufCnt = inBufCnt + 1
            end
            local linkR = math.min(fullR, b.fullRange)
            if d2 <= linkR * linkR then
                linkedBufCnt = linkedBufCnt + 1
            end
        end

        local bufCoversDps = 0
        if prof.isBuff then
            local mAtks = ctx.matchAttackers
            for i = 1, #mAtks do
                local a = mAtks[i]
                local dx = x - a.x
                local dz = z - a.z
                if dx * dx + dz * dz <= fullR2 then
                    bufCoversDps = bufCoversDps + a.dps
                end
            end
        end

        f[13] = math.min(1.0, inBufCnt / 4.0)
        if nBufs >= 4 and inBufCnt >= 4 then
            f[14] = 1.0
        else
            f[14] = 0.0
        end
        if nBufs > 0 then
            local bdx = x - ctx.buffCx
            local bdz = z - ctx.buffCz
            f[15] = math.max(0.0, 1.0 - math.sqrt(bdx * bdx + bdz * bdz) / 45.0)
        else
            f[15] = 0.0
        end
        if prof.isBuff and nBufs > 0 then
            f[16] = linkedBufCnt / nBufs
        else
            f[16] = 0.0
        end
        if prof.isBuff then
            f[17] = bufCoversDps / ctx.totalMatchAtkDps
        else
            f[17] = 0.0
        end
        f[18] = cache.getGroundFree20(x, z, spKey)
        f[19] = cache.getHillNear22(x, z, spKey)
        if clear24 then
            f[20] = 1.0
        else
            f[20] = 0.0
        end

        -- 21..25 (JS 20..24): Team & Field Synergy
        local minSameD = math.huge
        local minAnyD = math.huge
        local myId = prof.id
        for i = 1, #placed do
            local p = placed[i]
            local dx = x - p.x
            local dz = z - p.z
            local d = math.sqrt(dx * dx + dz * dz)
            if d < minAnyD then
                minAnyD = d
            end
            if p.id == myId and d < minSameD then
                minSameD = d
            end
        end

        local cov28 = 0
        if not spotIsHill and distRoad < 14 then
            cov28 = cache.getSpotCov28(x, z, spKey)
        end
        if nIn > 0 then
            f[21] = sumRoadDps / (nIn * ctx.maxRoadDps)
            f[22] = ctrlHits / nIn
        else
            f[21] = 0.0
            f[22] = 0.0
        end
        if minSameD < math.huge then
            f[23] = math.max(0.0, 1.0 - minSameD / 35.0)
        else
            f[23] = 0.0
        end
        if minAnyD < math.huge then
            f[24] = math.max(0.0, 1.0 - minAnyD / 25.0)
        else
            f[24] = 0.0
        end
        if not spotIsHill and distRoad < 14 and cov28 >= cache.primeThresh then
            f[25] = 1.0
        else
            f[25] = 0.0
        end

        -- 26..36 (JS 25..35): Unit Role & Context (hoisted in ctx when available)
        if ctx._f26 ~= nil then
            f[26] = ctx._f26
            f[27] = ctx._f27
            f[28] = ctx._f28
            f[29] = ctx._f29
            f[30] = ctx._f30
            f[31] = ctx._f31
            f[32] = ctx._f32
            f[33] = ctx._f33
            f[34] = ctx._f34
            f[35] = ctx._f35
            f[36] = ctx._f36
        else
            local aoeType = "single"
            if prof.aoe and prof.aoe.type then
                aoeType = prof.aoe.type
            end
            if not prof.isFarm and not prof.isBuff and not prof.isCC then
                f[26] = 1.0
            else
                f[26] = 0.0
            end
            if prof.isBuff then
                f[27] = 1.0
            else
                f[27] = 0.0
            end
            if prof.isCC then
                f[28] = 1.0
            else
                f[28] = 0.0
            end
            if prof.isFarm then
                f[29] = 1.0
            else
                f[29] = 0.0
            end
            if aoeType == "line" then
                f[30] = 1.0
            elseif aoeType == "cone" then
                f[30] = 0.5
            else
                f[30] = 0.0
            end
            if aoeType == "full_aoe" then
                f[31] = 1.0
            elseif aoeType == "circle" then
                f[31] = 0.5
            else
                f[31] = 0.0
            end
            if prof.isHill then
                f[32] = 1.0
            else
                f[32] = 0.0
            end
            if prof.canAir then
                f[33] = 1.0
            else
                f[33] = 0.0
            end
            if ctx.teamHasMatchingBuffer then
                f[34] = 1.0
            else
                f[34] = 0.0
            end
            f[35] = math.min(1.0, fullR / 50.0)
            if ctx.copyCount > 1 then
                f[36] = ctx.copyIdx / (ctx.copyCount - 1)
            else
                f[36] = 0.0
            end
        end

        return f, nIn
    end

    -- Exact 24 targeting features: f[1]..f[24] === JS features.js f[0]..f[23]
    function AI.extractTargetFeatures(cache, unitModel, allMine, prevSameModes, featBuf)
        local f = featBuf or {}
        if not cache then
            cache = AI.ensureMapCache()
        end
        local stats = unitModel and unitModel:FindFirstChild("_stats")
        if not stats or not stats:FindFirstChild("id") then
            for i = 1, 24 do
                f[i] = 0
            end
            return f
        end

        local id = stats.id.Value
        local okPos, pos = pcall(safePivotPos, unitModel)
        if not okPos or not pos then
            for i = 1, 24 do
                f[i] = 0
            end
            return f
        end
        local x = pos.X
        local z = pos.Z
        local fullR = stats:FindFirstChild("range") and tonumber(stats.range.Value) or 20
        if fullR <= 0 then
            fullR = 20
        end
        local fullR2 = fullR * fullR
        local cd = stats:FindFirstChild("attack_cooldown") and tonumber(stats.attack_cooldown.Value) or 4
        if cd <= 0 then
            cd = 4
        end
        local rawDmg = stats:FindFirstChild("damage") and tonumber(stats.damage.Value) or 1
        local primaryAtk = stats:FindFirstChild("primary_attack") and stats.primary_attack.Value or nil
        if not primaryAtk or primaryAtk == "" then
            local rows = Units and Units.rows and Units.rows(id)
            if rows and rows.max ~= nil then
                local upgObj = stats:FindFirstChild("upgrade")
                local curLvl = upgObj and tonumber(upgObj.Value) or rows.max
                if curLvl < 0 then
                    curLvl = 0
                elseif curLvl > rows.max then
                    curLvl = rows.max
                end
                local curRow = rows[curLvl] or rows[rows.max]
                if curRow then
                    primaryAtk = curRow.atk
                end
            end
        end
        local atkInfo = nil
        if primaryAtk and primaryAtk ~= "" and Units and Units.attackInfo then
            local okA, infoA = pcall(Units.attackInfo, primaryAtk, fullR)
            if okA and type(infoA) == "table" then
                atkInfo = infoA
            end
        end
        local aoe = normalizeAoe(atkInfo, fullR)
        local aoeType = aoe.type or "single"

        local isCC = false
        local hasBleed = false
        local hasMark = false
        if atkInfo then
            if (tonumber(atkInfo.slow) or 0) > 0 or (tonumber(atkInfo.stun) or 0) > 0 then
                isCC = true
            end
            if atkInfo.bleed then
                hasBleed = true
            end
            if (tonumber(atkInfo.amp) or 0) > 0 then
                hasMark = true
            end
        end
        local tip = Core and Core.TIPS and Core.TIPS[id]
        if tip and tip.target == "strongest" then
            hasMark = true
        end
        local hasClosest = (tip and tip.target == "closest") or (id == "sakamoto_evolved")

        local canAir = false
        if Match and Match.canAir then
            local okAir, airVal = pcall(Match.canAir, unitModel)
            if okAir and airVal then
                canAir = true
            end
        end

        -- Count same-id copies on field & this copy's 0-based index
        local mineList = allMine or (Match and Match.mine) or EMPTY_LIST
        local copyCount = 0
        local copyIdx = 0
        for i = 1, #mineList do
            local m = mineList[i]
            local st = m and m:FindFirstChild("_stats")
            if st and st:FindFirstChild("id") and st.id.Value == id then
                if m == unitModel then
                    copyIdx = copyCount
                end
                copyCount = copyCount + 1
            end
        end
        if copyCount < 1 then
            copyCount = 1
        end

        local sx = cache.sampleX
        local sz = cache.sampleZ
        local sp = cache.sampleProg
        local sl = cache.sampleLane
        local sc = cache.sampleCurv
        local nS = cache.nS

        local inRange = AI._tInRangeBuf
        local laneSeen = AI._tLaneSeenBuf
        for b = 0, 7 do
            laneSeen[b] = false
        end
        local nIn = 0
        local frontIdx = 0
        local backIdx = 0
        local closeIdx = 0
        local bestFront = -1
        local bestBack = 2
        local bestCloseD2 = math.huge
        local sumProg = 0
        local minP = 1
        local maxP = 0
        local sumCurv = 0
        local lanesHit = 0

        for i = 1, nS do
            local dx = sx[i] - x
            local dz = sz[i] - z
            local d2 = dx * dx + dz * dz
            if d2 <= fullR2 then
                nIn = nIn + 1
                inRange[nIn] = i
                local pr = sp[i]
                sumProg = sumProg + pr
                if pr < minP then
                    minP = pr
                end
                if pr > maxP then
                    maxP = pr
                end
                sumCurv = sumCurv + sc[i]
                local lb = sl[i] % 8
                if not laneSeen[lb] then
                    laneSeen[lb] = true
                    lanesHit = lanesHit + 1
                end
                if pr > bestFront then
                    bestFront = pr
                    frontIdx = i
                end
                if pr < bestBack then
                    bestBack = pr
                    backIdx = i
                end
                if d2 < bestCloseD2 then
                    bestCloseD2 = d2
                    closeIdx = i
                end
            end
        end

        local hFirst = 0
        local hLast = 0
        local hClose = 0
        if frontIdx > 0 then
            hFirst = aoeHitsAtSample(cache, x, z, fullR, aoe, inRange, nIn, frontIdx)
        end
        if backIdx > 0 then
            hLast = aoeHitsAtSample(cache, x, z, fullR, aoe, inRange, nIn, backIdx)
        end
        if closeIdx > 0 then
            hClose = aoeHitsAtSample(cache, x, z, fullR, aoe, inRange, nIn, closeIdx)
        end
        local maxH = math.max(1, hFirst, hLast, hClose)

        local prevF = 0
        local prevL = 0
        local prevS = 0
        local prevC = 0
        local prevList = prevSameModes or EMPTY_LIST
        local nPrev = #prevList
        for i = 1, nPrev do
            local tm = prevList[i]
            if type(tm) == "string" then
                tm = AI.TARGET_TO_IDX[tm] or 0
            end
            if tm == 0 then
                prevF = prevF + 1
            elseif tm == 1 then
                prevL = prevL + 1
            elseif tm == 2 then
                prevS = prevS + 1
            elseif tm == 3 then
                prevC = prevC + 1
            end
        end
        local prevDen = math.max(1, nPrev)

        local dmgPerHit = math.max(1, rawDmg)
        if rawDmg <= 1 and Match and Match.liveDps then
            local okD, lDps = pcall(Match.liveDps, unitModel, id)
            if okD and tonumber(lDps) and tonumber(lDps) > 0 then
                dmgPerHit = math.max(1, tonumber(lDps) * cd)
            end
        end

        f[1] = 0
        f[2] = 0
        f[3] = 0
        f[4] = 0
        f[5] = 0
        if aoeType == "single" then
            f[1] = 1
        elseif aoeType == "circle" then
            f[2] = 1
        elseif aoeType == "line" then
            f[3] = 1
        elseif aoeType == "cone" then
            f[4] = 1
        elseif aoeType == "full_aoe" then
            f[5] = 1
        end

        if isCC then
            f[6] = 1
        else
            f[6] = 0
        end
        if isCC and hasBleed then
            f[7] = 1
        else
            f[7] = 0
        end
        if hasMark then
            f[8] = 1
        else
            f[8] = 0
        end
        if hasClosest then
            f[9] = 1
        else
            f[9] = 0
        end
        if canAir then
            f[10] = 1
        else
            f[10] = 0
        end
        f[11] = math.min(1.0, cd / 10.0)
        f[12] = math.min(1.0, (math.log(dmgPerHit) / LN10) / 6.0)
        f[13] = math.min(1.0, fullR / 50.0)
        if copyCount > 1 then
            f[14] = copyIdx / (copyCount - 1)
            f[15] = 1
        else
            f[14] = 0
            f[15] = 0
        end
        f[16] = hFirst / maxH
        f[17] = hLast / maxH
        f[18] = hClose / maxH
        if nIn > 0 then
            f[19] = sumProg / nIn
            f[20] = maxP - minP
            f[21] = sumCurv / nIn
        else
            f[19] = 0.5
            f[20] = 0
            f[21] = 0
        end
        f[22] = lanesHit / math.max(1, cache.numLanes)
        f[23] = prevF / prevDen
        f[24] = (prevS + prevL + prevC) / prevDen

        return f
    end

    -- Neural Placement Inference: evaluates Match.cands + buff/mate rings with PlacementNN
    -- Enforces 4-clique buffer safety invariant so chained buffer squads never break!
    function AI.chooseSpot(unit, isFarm)
        if not (unit and unit.id and unit.data and Match and Match.samples and #Match.samples > 0 and Match.cands and #Match.cands > 0) then
            return nil, 0, nil
        end

        local cache = AI.ensureMapCache()
        if cache.nS == 0 then
            return nil, 0, nil
        end

        local prof = buildUnitProfile(unit, isFarm)
        local placedList = buildPlacedList()
        local ctx = buildStepContext(cache, placedList, prof)

        local baseCands = Match.cands
        local isRealFarm = prof.isFarm and (not (Units and Units.isFarm) or Units.isFarm(unit.id) == true)
        local unitHitboxR = tonumber(unit.data.override_hitbox_radius) or 1.5
        if isRealFarm and Config and Config.farmFar and Match.farmCandidates then
            local fc = Match.farmCandidates()
            if fc and #fc > 0 then
                baseCands = fc
            end
        elseif cache.canRay and cache.hasProbe and unitHitboxR >= 1.5 then
            if prof.isHill and not prof.isHybrid then
                baseCands = cache.hillCands
            elseif not prof.isHill and not prof.isHybrid then
                baseCands = cache.groundCands
            end
        end

        local workCands = AI._pWorkCandsBuf
        local seenCand = AI._pSeenCandBuf
        clearArray(workCands)
        clearMap(seenCand)
        local nWorkCands = 0
        local function addCand(v)
            if not v then
                return
            end
            local k = xzKey2(v.X, v.Z)
            if not seenCand[k] then
                seenCand[k] = true
                nWorkCands = nWorkCands + 1
                workCands[nWorkCands] = v
            end
        end

        for i = 1, #baseCands do
            addCand(baseCands[i])
        end

        -- Buffer mates ring + 4-clique safety tracking (anchors on largest linked subset)
        local allyBuff = prof.allyBuff
        local range0 = prof.earlyRange

        local anchors = nil
        local enforceClique = false
        if prof.isBuff and allyBuff and allyBuff.chain and Units and Units.chainOn and Units.chainOn() then
            local mates = {}
            for _, fb in ipairs(Match.fieldBuffers and Match.fieldBuffers() or EMPTY_LIST) do
                if fb and fb.b and fb.b.attack == allyBuff.attack then
                    table.insert(mates, fb)
                end
            end
            local needSz = allyBuff.squad or (Units and Units.BUFF_COPIES) or 4
            if #mates > 0 then
                anchors = mates
                if #mates > 1 and Match.buffSquad then
                    local adapted = {}
                    for i = 1, #mates do
                        adapted[i] = {
                            position = mates[i].pos,
                            range = mates[i].range,
                            orig = mates[i],
                        }
                    end
                    local maxSub = math.min(#adapted, math.max(1, needSz - 1))
                    for k = maxSub, 1, -1 do
                        local okSq, sub = pcall(Match.buffSquad, adapted, k)
                        if okSq and sub and #sub > 0 then
                            anchors = {}
                            for si = 1, #sub do
                                anchors[si] = sub[si].orig
                            end
                            break
                        end
                    end
                end
                if #anchors > 0 then
                    local center = Vector3.new(0, 0, 0)
                    local reach = range0
                    for i = 1, #anchors do
                        center = center + anchors[i].pos
                        if anchors[i].range < reach then
                            reach = anchors[i].range
                        end
                    end
                    center = center / #anchors
                    addCand(center)
                    for _, part in ipairs({ 0.2, 0.4, 0.6 }) do
                        for i = 0, 11 do
                            local angle = i * math.pi / 6
                            addCand(center + Vector3.new(math.cos(angle), 0, math.sin(angle)) * reach * part)
                        end
                    end
                    if #anchors < needSz then
                        enforceClique = true
                    end
                end
            end
        end

        -- Attacker / CC ring around matching squad buffer centroid so buff-hub spots are always explored
        if not prof.isFarm and not prof.isBuff and #ctx.sameKindBuffers > 0 and Vector3 and Vector3.new then
            local bCenter = Vector3.new(ctx.buffCx, ctx.buffCy, ctx.buffCz)
            local bReach = math.max(8, math.min(20, ctx.minBufR or 16))
            addCand(bCenter)
            for _, part in ipairs({ 0.25, 0.5, 0.75 }) do
                for i = 0, 11 do
                    local angle = i * math.pi / 6
                    addCand(bCenter + Vector3.new(math.cos(angle), 0, math.sin(angle)) * bReach * part)
                end
            end
        end

        local featBuf = AI._pFeatBuf
        local bestSpot, bestCover, bestScore = nil, 0, -math.huge
        local bestLinkedSpot, bestLinkedCover, bestLinkedScore = nil, 0, -math.huge
        local data = unit.data

        for idx = 1, nWorkCands do
            if idx % 80 == 0 and task and task.wait then
                task.wait()
            end
            local valid = Match.valid(workCands[idx], data)
            if valid then
                local _, nIn = AI.extractPlacementFeatures(cache, valid, prof, placedList, ctx, featBuf)
                local sc = AI.scorePlacement(featBuf)
                if sc > bestScore then
                    bestScore = sc
                    bestSpot = valid
                    bestCover = nIn
                end
                if enforceClique and anchors then
                    local allLinked = true
                    for mIdx = 1, #anchors do
                        local mt = anchors[mIdx]
                        local linkR = math.min(range0, mt.range)
                        local dx = valid.X - mt.pos.X
                        local dz = valid.Z - mt.pos.Z
                        if dx * dx + dz * dz > linkR * linkR then
                            allLinked = false
                            break
                        end
                    end
                    if allLinked and sc > bestLinkedScore then
                        bestLinkedScore = sc
                        bestLinkedSpot = valid
                        bestLinkedCover = nIn
                    end
                end
            end
        end

        local winSpot = bestSpot
        local winCover = bestCover
        local winScore = bestScore
        if enforceClique and bestLinkedSpot then
            winSpot = bestLinkedSpot
            winCover = bestLinkedCover
            winScore = bestLinkedScore
        end

        if not winSpot then
            return nil, 0, nil
        end
        if Match.cover then
            local okCov, covVal = pcall(Match.cover, winSpot, prof.fullRange)
            if okCov and tonumber(covVal) then
                winCover = tonumber(covVal)
            end
        end
        return winSpot, winCover, winScore
    end

    -- Neural Targeting Inference: returns (targetStr, idx0to3, logits)
    function AI.pickTarget(unitModel, prevSameModes)
        if not (unitModel and Match and Match.samples and #Match.samples > 0) then
            return nil, nil, nil
        end
        local cache = AI.ensureMapCache()
        if cache.nS == 0 then
            return nil, nil, nil
        end
        local featBuf = AI.extractTargetFeatures(cache, unitModel, Match.mine, prevSameModes, AI._tFeatBuf)
        local bestIdx0to3, logits = AI.predictTarget(featBuf)
        local targetStr = AI.TARGET_NAMES[bestIdx0to3 + 1] or "first"
        return targetStr, bestIdx0to3, logits
    end

    -- ========================================================================
    -- Stage 5: Smart Economy & Build Order (v2.36 AI)
    -- Exact 1-to-1 mirror of engine/econ_features.js (28 features, k=1..4
    -- breakpoint lookahead, synthetic SAVE action, safe midgame starter sell)
    -- ========================================================================
    local ECON_REACH_CAP = 2.0
    local ECON_SELL_REFUND_RATE = 0.25
    local ECON_BUFF_CURVE = { 1.0, 1.18, 1.38, 1.62, 2.0 }

    local function econIsFinite(x)
        return type(x) == "number" and x == x and x ~= math.huge and x ~= -math.huge
    end

    local function econClamp(x, lo, hi)
        if not econIsFinite(x) then
            return lo
        end
        if x < lo then
            return lo
        end
        if x > hi then
            return hi
        end
        return x
    end

    local function econClamp01(x)
        return econClamp(x, 0.0, 1.0)
    end

    local function econRowRate(row)
        if not row then
            return 0.0
        end
        local cd = tonumber(row.cd) or 0.0
        if cd <= 0.0 then
            return 0.0
        end
        local dmg = math.max(0.0, tonumber(row.damage) or 0.0)
        local aoe = math.max(0.3, tonumber(row.aoeMul) or 1.0)
        return (dmg / cd) * aoe
    end

    function AI.scoreEconomy(feat)
        local out = forwardMLP(AI.ECONOMY_NET, feat)
        return out[1]
    end

    -- Enrich & cache Units.rows(unitId) with aoeMul, canAir, bleed, isFullAoe, hasCC, maxDps
    local function getEnrichedEconRows(unitId)
        if not unitId then
            return nil
        end
        local cached = AI._econRowsCache[unitId]
        if cached ~= nil then
            if cached == false then
                return nil
            end
            return cached
        end
        if not (Units and Units.rows) then
            AI._econRowsCache[unitId] = false
            return nil
        end
        local okR, rawRows = pcall(Units.rows, unitId)
        if not okR or type(rawRows) ~= "table" or rawRows.max == nil then
            AI._econRowsCache[unitId] = false
            return nil
        end

        local airFromLvl = nil
        if Units.airFrom then
            local okAir, airVal = pcall(Units.airFrom, unitId)
            if okAir and type(airVal) == "number" then
                airFromLvl = airVal
            end
        end
        local bleedFromLvl = nil
        if Units.bleeds then
            local okBl, blVal = pcall(Units.bleeds, unitId)
            if okBl and type(blVal) == "number" then
                bleedFromLvl = blVal
            end
        end

        local eRows = {
            max = rawRows.max,
            hasAnyCC = false,
            maxDps = 0.0,
        }
        local r0Range = 20.0
        if rawRows[0] and tonumber(rawRows[0].range) and tonumber(rawRows[0].range) > 0 then
            r0Range = tonumber(rawRows[0].range)
        end

        for l = 0, rawRows.max do
            local r = rawRows[l]
            if r then
                local rng = tonumber(r.range) or r0Range
                if rng <= 0 then
                    rng = r0Range
                end
                local atkId = r.atk
                local atkInfo = nil
                if atkId and atkId ~= "" and Units.attackInfo then
                    local okA, infoA = pcall(Units.attackInfo, atkId, rng)
                    if okA and type(infoA) == "table" then
                        atkInfo = infoA
                    end
                end
                local aoeMul = 1.0
                if atkId and atkId ~= "" and Units.aoe then
                    local okM, mVal = pcall(Units.aoe, atkId, rng)
                    if okM and tonumber(mVal) then
                        aoeMul = math.max(0.3, tonumber(mVal))
                    end
                elseif atkInfo then
                    aoeMul = math.max(0.3, (tonumber(atkInfo.n) or 1.0) * (1.0 + (tonumber(atkInfo.dot) or 0.0)))
                end

                local canAir = (airFromLvl ~= nil and l >= airFromLvl)
                local bleed = false
                if atkInfo and atkInfo.bleed == true then
                    bleed = true
                elseif bleedFromLvl ~= nil and l >= bleedFromLvl then
                    bleed = true
                end
                local isFullAoe = false
                if atkInfo then
                    if atkInfo.full == true then
                        isFullAoe = true
                    elseif type(atkInfo.shape) == "table" and atkInfo.shape.type == "full_aoe" then
                        isFullAoe = true
                    end
                end
                local hasCC = false
                if atkInfo then
                    if (tonumber(atkInfo.slow) or 0) > 0 or (tonumber(atkInfo.stun) or 0) > 0 then
                        hasCC = true
                    end
                end
                if hasCC then
                    eRows.hasAnyCC = true
                end

                local rowObj = {
                    cost = tonumber(r.cost) or 0.0,
                    damage = tonumber(r.damage) or 0.0,
                    cd = tonumber(r.cd) or 0.0,
                    range = rng,
                    farm = tonumber(r.farm) or 0.0,
                    aoeMul = aoeMul,
                    canAir = canAir,
                    bleed = bleed,
                    isFullAoe = isFullAoe,
                    hasCC = hasCC,
                }
                eRows[l] = rowObj

                local rate = econRowRate(rowObj)
                local rBoost = econClamp(rng / math.max(1.0, r0Range), 1.0, ECON_REACH_CAP)
                local eff = rate * rBoost
                if eff > eRows.maxDps then
                    eRows.maxDps = eff
                end
            end
        end

        AI._econRowsCache[unitId] = eRows
        return eRows
    end

    -- Exact 1-to-1 mirror of engine/econ_features.js computeBreakpointLookahead (supports optional outBuf for 0 allocations)
    local function fillEmptyBp(out)
        out.immGain = 0.0
        out.immCost = 0.0
        out.immRate = 0.0
        out.bpGain = 0.0
        out.bpCost = 0.0
        out.bpRate = 0.0
        out.bpSteps = 0
        out.bpMultiplier = 0.0
        out.isBreakpointStep = false
        out.unlocksAir = false
        out.unlocksBleed = false
        out.unlocksFullAoe = false
        out.unlocksCC = false
        out.bpUnlocksAir = false
        out.bpUnlocksBleed = false
        out.bpUnlocksFullAoe = false
        out.bpUnlocksCC = false
        out.paybackWaves = 0.0
        return out
    end

    function AI.computeBreakpointLookahead(rows, curLvl, curDps, costMul, maxSteps, outBuf)
        local out = outBuf or {}
        if type(rows) ~= "table" then
            return fillEmptyBp(out)
        end
        local maxLvl = -1
        if econIsFinite(rows.max) then
            maxLvl = rows.max
        elseif rows[0] ~= nil then
            maxLvl = #rows
        end
        if maxLvl < 0 then
            return fillEmptyBp(out)
        end

        local lvl0 = -1
        if econIsFinite(curLvl) then
            lvl0 = math.floor(curLvl)
        end
        if lvl0 >= maxLvl then
            return fillEmptyBp(out)
        end

        local cMul = 1.0
        if econIsFinite(costMul) and costMul > 0.0 then
            cMul = costMul
        end
        local steps = 4
        if econIsFinite(maxSteps) then
            steps = math.max(1, math.min(8, math.floor(maxSteps)))
        end
        local isPlace = (lvl0 < 0)

        local firstRow = rows[lvl0 + 1]
        if not firstRow then
            return fillEmptyBp(out)
        end

        local curRow = nil
        if not isPlace then
            curRow = rows[lvl0]
        end
        local isFarm = ((tonumber(firstRow.farm) or 0.0) > 0.0) or (curRow ~= nil and (tonumber(curRow.farm) or 0.0) > 0.0)

        local curCanAir = (curRow ~= nil and curRow.canAir == true)
        local curBleed = (curRow ~= nil and curRow.bleed == true)
        local curFullAoe = (curRow ~= nil and curRow.isFullAoe == true)
        local curCC = (curRow ~= nil and curRow.hasCC == true)

        local curFarm = 0.0
        local curRate = 0.0
        local curRange = math.max(1.0, tonumber(firstRow.range) or 1.0)
        if curRow ~= nil then
            curFarm = math.max(0.0, tonumber(curRow.farm) or 0.0)
            curRate = econRowRate(curRow)
            curRange = math.max(1.0, tonumber(curRow.range) or 1.0)
        end

        local baseLive = 0.0
        local liveScale = 1.0
        if isFarm then
            if econIsFinite(curDps) and curDps > 0.0 then
                baseLive = curDps
            else
                baseLive = curFarm
            end
        elseif isPlace then
            local r0 = econRowRate(firstRow)
            if econIsFinite(curDps) and curDps > 0.0 and r0 > 1e-9 then
                liveScale = curDps / r0
            end
            baseLive = 0.0
        else
            if econIsFinite(curDps) and curDps > 0.0 then
                baseLive = curDps
            else
                baseLive = curRate
            end
            if curRate > 1e-9 and baseLive > 0.0 then
                liveScale = baseLive / curRate
            end
        end

        local cumCost = 0.0
        local immGain = 0.0
        local immCost = 0.0
        local immRate = 0.0

        local bpGain = 0.0
        local bpCost = 0.0
        local bpRate = 0.0
        local bpSteps = 1

        local unlocksAir = false
        local unlocksBleed = false
        local unlocksFullAoe = false
        local unlocksCC = false
        local bpUnlocksAir = false
        local bpUnlocksBleed = false
        local bpUnlocksFullAoe = false
        local bpUnlocksCC = false

        local lastTarget = math.min(maxLvl, lvl0 + steps)
        for k = lvl0 + 1, lastTarget do
            local r = rows[k]
            if not r then
                break
            end
            local stepIdx = k - lvl0
            local stepCost = math.max(1.0, (tonumber(r.cost) or 0.0) * cMul)
            cumCost = cumCost + stepCost

            local cumGain = 0.0
            if isFarm then
                local rf = math.max(0.0, tonumber(r.farm) or 0.0)
                cumGain = math.max(0.0, rf - curFarm)
            else
                local newRate = econRowRate(r)
                local newRange = math.max(1.0, tonumber(r.range) or curRange)
                if isPlace then
                    local reachRatio = econClamp(newRange / curRange, 1.0, ECON_REACH_CAP)
                    cumGain = math.max(0.0, newRate * liveScale * reachRatio)
                elseif curRate > 1e-9 then
                    local reachRatio = econClamp(newRange / curRange, 1.0, ECON_REACH_CAP)
                    local powerMul = (newRate / curRate) * reachRatio
                    cumGain = math.max(0.0, baseLive * (powerMul - 1.0))
                else
                    cumGain = math.max(0.0, newRate * liveScale)
                end
            end

            local cumRate = cumGain / math.max(1.0, cumCost)
            if stepIdx == 1 then
                immGain = cumGain
                immCost = cumCost
                immRate = cumRate
                bpGain = cumGain
                bpCost = cumCost
                bpRate = cumRate
                bpSteps = 1

                if not curCanAir and r.canAir == true then
                    unlocksAir = true
                end
                if not curBleed and r.bleed == true then
                    unlocksBleed = true
                end
                if not curFullAoe and r.isFullAoe == true then
                    unlocksFullAoe = true
                end
                if not curCC and r.hasCC == true then
                    unlocksCC = true
                end
            elseif cumRate > bpRate then
                bpGain = cumGain
                bpCost = cumCost
                bpRate = cumRate
                bpSteps = stepIdx
            end

            if not curCanAir and r.canAir == true then
                bpUnlocksAir = true
            end
            if not curBleed and r.bleed == true then
                bpUnlocksBleed = true
            end
            if not curFullAoe and r.isFullAoe == true then
                bpUnlocksFullAoe = true
            end
            if not curCC and r.hasCC == true then
                bpUnlocksCC = true
            end
        end

        local bpMultiplier = 0.0
        if bpRate > 0.0 then
            bpMultiplier = econClamp01(((bpRate / math.max(immRate, 1e-6)) - 1.0) / 3.0)
        end

        local multiStepJump = false
        if bpSteps >= 2 then
            if immRate > 1e-9 then
                multiStepJump = ((bpRate / immRate) >= 1.6)
            else
                multiStepJump = (bpRate > 0.0)
            end
        end
        local directJump = false
        if not isPlace and baseLive > 1e-6 then
            directJump = (((baseLive + immGain) / baseLive) >= 1.6)
        end
        local anyUnlock = (not isFarm) and (
            unlocksAir or unlocksBleed or unlocksFullAoe or unlocksCC or
            bpUnlocksAir or bpUnlocksBleed or bpUnlocksFullAoe or bpUnlocksCC
        )
        local isBreakpointStep = multiStepJump or directJump or anyUnlock
        local paybackWaves = 0.0
        if isFarm and immGain > 1e-6 then
            paybackWaves = immCost / immGain
        end

        out.immGain = immGain
        out.immCost = immCost
        out.immRate = immRate
        out.bpGain = bpGain
        out.bpCost = bpCost
        out.bpRate = bpRate
        out.bpSteps = bpSteps
        out.bpMultiplier = bpMultiplier
        out.isBreakpointStep = isBreakpointStep
        out.unlocksAir = unlocksAir
        out.unlocksBleed = unlocksBleed
        out.unlocksFullAoe = unlocksFullAoe
        out.unlocksCC = unlocksCC
        out.bpUnlocksAir = bpUnlocksAir
        out.bpUnlocksBleed = bpUnlocksBleed
        out.bpUnlocksFullAoe = bpUnlocksFullAoe
        out.bpUnlocksCC = bpUnlocksCC
        out.paybackWaves = paybackWaves
        return out
    end

    -- Exact 1-to-1 mirror of engine/econ_features.js computeActionNormStats
    function AI.computeActionNormStats(state, actions, outBuf)
        local bestAtkImmRate = 0.0
        local bestAtkBpRate = 0.0
        local bestFarmImmRate = 0.0
        local bestFarmBpRate = 0.0

        for i = 1, #actions do
            local a = actions[i]
            if a and a.kind ~= "save" then
                local ir = math.max(0.0, tonumber(a.immRate) or 0.0)
                local br = math.max(ir, tonumber(a.bpRate) or 0.0)
                if a.isFarm then
                    if ir > bestFarmImmRate then
                        bestFarmImmRate = ir
                    end
                    if br > bestFarmBpRate then
                        bestFarmBpRate = br
                    end
                else
                    if ir > bestAtkImmRate then
                        bestAtkImmRate = ir
                    end
                    if br > bestAtkBpRate then
                        bestAtkBpRate = br
                    end
                end
            end
        end

        local yen = math.max(0.0, tonumber(state.yen) or 0.0)
        local nextWaveIncome = math.max(1.0, tonumber(state.nextWaveIncome) or 1.0)
        local wavesLeft = math.max(1.0, tonumber(state.wavesLeft) or 1.0)
        local teamBestMaxDps = math.max(1.0, tonumber(state.teamBestMaxDps) or 1.0)
        local pressure = econClamp01(tonumber(state.defensePressure) or 0.0)
        local placedAttackers = tonumber(state.placedAttackers) or 0
        local placedBuffers = tonumber(state.placedBuffers) or 0

        local bestSaveTarget = nil
        local bestSaveScore = -1.0

        for i = 1, #actions do
            local a = actions[i]
            if a and a.kind ~= "save" then
                local cost = math.max(0.0, tonumber(a.cost) or 0.0)
                if cost > yen then
                    local wta = econClamp01((cost - yen) / math.max(1.0, nextWaveIncome * 3.0))
                    local uScore = 0.0
                    local eligible = true
                    if a.isFarm then
                        local pb = tonumber(a.paybackWaves) or 999.0
                        if pb > math.max(1.0, wavesLeft - 2.0) or a.farmUnprofitable then
                            eligible = false
                        else
                            local farmEff = econClamp01(1.0 - pb / math.max(1.0, wavesLeft))
                            local bpN = 0.0
                            if bestFarmBpRate > 1e-9 then
                                bpN = econClamp01((tonumber(a.bpRate) or 0.0) / bestFarmBpRate)
                            end
                            if pressure < 0.55 and placedAttackers >= 1 then
                                uScore = (0.55 * farmEff + 0.45 * bpN) / (1.0 + 1.5 * wta)
                            else
                                uScore = 0.02
                            end
                        end
                    else
                        local irN = 0.0
                        if bestAtkImmRate > 1e-9 then
                            irN = econClamp01((tonumber(a.immRate) or 0.0) / bestAtkImmRate)
                        end
                        local brN = 0.0
                        if bestAtkBpRate > 1e-9 then
                            brN = econClamp01((tonumber(a.bpRate) or 0.0) / bestAtkBpRate)
                        end
                        local tierN = econClamp01((tonumber(a.unitMaxDps) or 0.0) / teamBestMaxDps)
                        local val = 0.50 * brN + 0.25 * irN + 0.25 * tierN
                        if (a.unlocksAir or a.bpUnlocksAir) and state.needAir then
                            val = val + 0.55
                        end
                        if (a.unlocksBleed or a.bpUnlocksBleed) and state.needBleed then
                            val = val + 0.45
                        end
                        if a.unlocksFullAoe or a.bpUnlocksFullAoe then
                            val = val + 0.25
                        end
                        if (a.unlocksCC or a.bpUnlocksCC) and state.needCC then
                            val = val + 0.20
                        end
                        if a.kind == "place" and a.isBuff and placedBuffers < 4 and state.hasCarries then
                            val = val + 0.30 * ((placedBuffers + 1) / 4.0)
                        end
                        if a.isBreakpointStep then
                            val = val + 0.20
                        end
                        uScore = val / (1.0 + 1.8 * wta)
                    end

                    if eligible then
                        if uScore > bestSaveScore + 1e-9 or (math.abs(uScore - bestSaveScore) <= 1e-9 and bestSaveTarget ~= nil and cost < (tonumber(bestSaveTarget.cost) or math.huge)) then
                            bestSaveScore = uScore
                            bestSaveTarget = a
                        end
                    end
                end
            end
        end

        local out = outBuf or {}
        out.bestAtkImmRate = bestAtkImmRate
        out.bestAtkBpRate = bestAtkBpRate
        out.bestFarmImmRate = bestFarmImmRate
        out.bestFarmBpRate = bestFarmBpRate
        out.bestSaveTarget = bestSaveTarget
        return out
    end

    -- Exact 1-to-1 mirror of engine/econ_features.js buildSaveAction (supports optional outBuf)
    function AI.buildSaveAction(targetOpt, outBuf)
        if not targetOpt then
            return nil
        end
        local curL = 0
        if econIsFinite(targetOpt.curLvl) then
            curL = targetOpt.curLvl
        end
        local out = outBuf or {}
        out.kind = "save"
        out.targetKind = targetOpt.kind
        out.key = "save:" .. tostring(targetOpt.key or "target")
        out.isFarm = (targetOpt.isFarm == true)
        out.isBuff = (targetOpt.isBuff == true)
        out.isCC = (targetOpt.isCC == true)
        out.cost = tonumber(targetOpt.cost) or 0.0
        out.gain = tonumber(targetOpt.gain) or 0.0
        out.immRate = tonumber(targetOpt.immRate) or 0.0
        out.bpRate = tonumber(targetOpt.bpRate) or 0.0
        out.bpMultiplier = tonumber(targetOpt.bpMultiplier) or 0.0
        out.paybackWaves = tonumber(targetOpt.paybackWaves) or 0.0
        out.isBreakpointStep = (targetOpt.isBreakpointStep == true)
        out.unlocksAir = (targetOpt.unlocksAir == true)
        out.unlocksBleed = (targetOpt.unlocksBleed == true)
        out.unlocksFullAoe = (targetOpt.unlocksFullAoe == true)
        out.unlocksCC = (targetOpt.unlocksCC == true)
        out.bpUnlocksAir = (targetOpt.bpUnlocksAir == true)
        out.bpUnlocksBleed = (targetOpt.bpUnlocksBleed == true)
        out.bpUnlocksFullAoe = (targetOpt.bpUnlocksFullAoe == true)
        out.bpUnlocksCC = (targetOpt.bpUnlocksCC == true)
        out.unitMaxDps = tonumber(targetOpt.unitMaxDps) or 0.0
        out.placedCopies = tonumber(targetOpt.placedCopies) or 0
        out.unitCap = tonumber(targetOpt.unitCap) or 1
        out.curLvl = curL
        out.maxLvl = tonumber(targetOpt.maxLvl) or 1
        out.saveTargetKey = tostring(targetOpt.key or "")
        return out
    end

    -- Exact 28 EconomyNN features: f[1]..f[28] === JS engine/econ_features.js f[0]..f[27]
    function AI.extractEconFeatures(state, action, outBuf)
        local f = outBuf or {}
        local st = state or EMPTY_LIST
        local a = action or EMPTY_LIST

        local isSave = (a.kind == "save")
        local isPlace = (a.kind == "place")
        local isUpg = (a.kind == "upgrade")
        local isFarm = (a.isFarm == true)
        local isBuff = (a.isBuff == true)
        local isCC = (a.isCC == true)

        -- 1..8 (JS 0..7): Action type indicators (1-hot)
        if isPlace and isFarm then
            f[1] = 1.0
        else
            f[1] = 0.0
        end
        if isUpg and isFarm then
            f[2] = 1.0
        else
            f[2] = 0.0
        end
        if isPlace and not isFarm and not isBuff and not isCC then
            f[3] = 1.0
        else
            f[3] = 0.0
        end
        if isUpg and not isFarm and not isBuff then
            f[4] = 1.0
        else
            f[4] = 0.0
        end
        if isPlace and isBuff then
            f[5] = 1.0
        else
            f[5] = 0.0
        end
        if isUpg and isBuff then
            f[6] = 1.0
        else
            f[6] = 0.0
        end
        if isPlace and not isFarm and not isBuff and isCC then
            f[7] = 1.0
        else
            f[7] = 0.0
        end
        if isSave then
            f[8] = 1.0
        else
            f[8] = 0.0
        end

        -- 9..16 (JS 8..15): Value & Breakpoint Lookahead
        local yen = math.max(0.0, tonumber(st.yen) or 0.0)
        local cost = math.max(0.0, tonumber(a.cost) or 0.0)
        local nextWaveIncome = math.max(1.0, tonumber(st.nextWaveIncome) or 1.0)
        local wavesLeft = math.max(1.0, tonumber(st.wavesLeft) or 1.0)

        local immRate = 0.0
        if econIsFinite(a.immRate) then
            immRate = math.max(0.0, a.immRate)
        else
            immRate = math.max(0.0, math.max(0.0, tonumber(a.gain) or 0.0) / math.max(1.0, cost))
        end
        local bpRate = immRate
        if econIsFinite(a.bpRate) and a.bpRate > bpRate then
            bpRate = a.bpRate
        end

        local bestImm = 0.0
        local bestBp = 0.0
        if isFarm then
            if st.bestFarmImmRate ~= nil then
                bestImm = math.max(0.0, tonumber(st.bestFarmImmRate) or 0.0)
            else
                bestImm = math.max(0.0, tonumber(st.bestImmRate) or 0.0)
            end
            if st.bestFarmBpRate ~= nil then
                bestBp = math.max(0.0, tonumber(st.bestFarmBpRate) or 0.0)
            else
                bestBp = math.max(0.0, tonumber(st.bestBpRate) or 0.0)
            end
        else
            if st.bestAtkImmRate ~= nil then
                bestImm = math.max(0.0, tonumber(st.bestAtkImmRate) or 0.0)
            else
                bestImm = math.max(0.0, tonumber(st.bestImmRate) or 0.0)
            end
            if st.bestAtkBpRate ~= nil then
                bestBp = math.max(0.0, tonumber(st.bestAtkBpRate) or 0.0)
            else
                bestBp = math.max(0.0, tonumber(st.bestBpRate) or 0.0)
            end
        end

        local immRateNorm = 0.0
        if bestImm > 1e-9 then
            immRateNorm = econClamp01(immRate / bestImm)
        end
        local bpRateNorm = 0.0
        if bestBp > 1e-9 then
            bpRateNorm = econClamp01(bpRate / bestBp)
        end
        local bpMultiplier = 0.0
        if econIsFinite(a.bpMultiplier) then
            bpMultiplier = econClamp01(a.bpMultiplier)
        elseif bpRate > 0.0 then
            bpMultiplier = econClamp01(((bpRate / math.max(immRate, 1e-6)) - 1.0) / 3.0)
        end

        local affordNow = 1.0
        if yen < cost then
            affordNow = econClamp01(yen / math.max(1.0, cost))
        end
        local wavesToAfford = econClamp01(math.max(0.0, cost - yen) / math.max(1.0, nextWaveIncome * 3.0))

        local farmPaybackNorm = 0.0
        if isFarm then
            local pb = 0.0
            if econIsFinite(a.paybackWaves) and a.paybackWaves > 0.0 then
                pb = a.paybackWaves
            else
                pb = cost / math.max(1e-6, tonumber(a.gain) or 0.0)
            end
            farmPaybackNorm = econClamp01(pb / wavesLeft)
        end

        local costShareNorm = econClamp01(cost / math.max(1.0, yen + nextWaveIncome))
        local isBreakpointStep = 0.0
        if a.isBreakpointStep then
            isBreakpointStep = 1.0
        end

        f[9] = immRateNorm
        f[10] = bpRateNorm
        f[11] = bpMultiplier
        f[12] = affordNow
        f[13] = wavesToAfford
        f[14] = farmPaybackNorm
        f[15] = costShareNorm
        f[16] = isBreakpointStep

        -- 17..22 (JS 16..21): Urgency & Tactical Unlocks
        local unlocksAirWhenNeeded = 0.0
        if (a.unlocksAir or a.bpUnlocksAir) and st.needAir then
            unlocksAirWhenNeeded = 1.0
        end
        local unlocksBleedWhenNeeded = 0.0
        if (a.unlocksBleed or a.bpUnlocksBleed) and st.needBleed then
            unlocksBleedWhenNeeded = 1.0
        end
        local unlocksFullAoe = 0.0
        if a.unlocksFullAoe or a.bpUnlocksFullAoe then
            unlocksFullAoe = 1.0
        end
        local unlocksCC = 0.0
        if (a.unlocksCC or a.bpUnlocksCC) and st.needCC then
            unlocksCC = 1.0
        end

        local placedBuffers = math.max(0, tonumber(st.placedBuffers) or 0)
        local isBuffPlaceAction = (isPlace and isBuff) or (isSave and a.targetKind == "place" and isBuff)
        local buffCliqueProgress = 0.0
        if isBuffPlaceAction and placedBuffers < 4 and st.hasCarries then
            buffCliqueProgress = econClamp01((placedBuffers + 1.0) / 4.0)
        end
        local defensePressure = econClamp01(tonumber(st.defensePressure) or 0.0)

        f[17] = unlocksAirWhenNeeded
        f[18] = unlocksBleedWhenNeeded
        f[19] = unlocksFullAoe
        f[20] = unlocksCC
        f[21] = buffCliqueProgress
        f[22] = defensePressure

        -- 23..28 (JS 22..27): Match & Unit Context
        local wave = math.max(0.0, tonumber(st.wave) or 0.0)
        local totalWaves = math.max(1.0, tonumber(st.totalWaves) or 15.0)
        local waveProgress = 0.0
        if st.isInfinite then
            waveProgress = econClamp01(wave / 60.0)
        else
            waveProgress = econClamp01(wave / totalWaves)
        end
        local wavesLeftNorm = econClamp01((tonumber(st.wavesLeft) or 0.0) / 30.0)

        local maxFarmVal = math.max(0.0, tonumber(st.maxFarmValue) or 0.0)
        local farmSaturation = 0.0
        if maxFarmVal > 0.0 then
            farmSaturation = econClamp01((tonumber(st.placedFarmValue) or 0.0) / maxFarmVal)
        end

        local unitTierRank = econClamp01((tonumber(a.unitMaxDps) or 0.0) / math.max(1.0, tonumber(st.teamBestMaxDps) or 1.0))
        local copySaturation = econClamp01((tonumber(a.placedCopies) or 0.0) / math.max(1.0, tonumber(a.unitCap) or 1.0))
        local curLvlClamped = math.max(0.0, tonumber(a.curLvl) or 0.0)
        local upgradeProgress = econClamp01(curLvlClamped / math.max(1.0, tonumber(a.maxLvl) or 1.0))

        f[23] = waveProgress
        f[24] = wavesLeftNorm
        f[25] = farmSaturation
        f[26] = unitTierRank
        f[27] = copySaturation
        f[28] = upgradeProgress

        return f
    end

    -- Exact 1-to-1 mirror of engine/econ_features.js evaluateStarterSell
    function AI.evaluateStarterSell(state, unitObj)
        local no = { sell = false, refund = 0, reason = "" }
        if not state or not unitObj then
            return no
        end
        if unitObj.isFarm or unitObj.isBuff or unitObj.isCC or unitObj.hasCC or
            unitObj.isTrainee or unitObj.isFusion or unitObj.unsellable then
            return no
        end
        if unitObj.isSoleAir or unitObj.isSoleBleed then
            return no
        end

        local ageSec = 0.0
        if econIsFinite(unitObj.ageSec) then
            ageSec = unitObj.ageSec
        else
            ageSec = (tonumber(state.nowSec) or 0.0) - (tonumber(unitObj.placedAtSec) or 0.0)
        end
        if ageSec < 45.0 then
            return no
        end
        if (tonumber(state.wave) or 0) < 8 then
            return no
        end
        if state.leak then
            return no
        end

        local safeReach = 0.45
        if econIsFinite(state.safeReach) then
            safeReach = state.safeReach
        end
        if (tonumber(state.defensePressure) or 0.0) >= safeReach then
            return no
        end
        if (tonumber(state.placedAttackers) or 0) < 2 then
            return no
        end

        local lastSell = -9999.0
        if econIsFinite(state.lastStarterSellSec) then
            lastSell = state.lastStarterSellSec
        end
        if ((tonumber(state.nowSec) or 0.0) - lastSell) < 30.0 then
            return no
        end

        local bestMaxDps = math.max(1.0, tonumber(state.teamBestMaxDps) or 1.0)
        local unitMaxDps = math.max(0.0, tonumber(unitObj.maxDps) or 0.0)
        if unitMaxDps >= 0.25 * bestMaxDps then
            return no
        end

        local teamDps = math.max(0.0, tonumber(state.currentTeamDps) or 0.0)
        local unitDps = math.max(0.0, tonumber(unitObj.currentDps) or 0.0)
        local remDps = math.max(0.0, teamDps - unitDps)
        if teamDps > 0.0 and remDps < 0.65 * teamDps then
            return no
        end
        local reqDps = tonumber(state.requiredDps) or 0.0
        if reqDps > 0.0 and remDps < reqDps * 1.15 then
            return no
        end

        local totalInvested = math.max(0.0, tonumber(unitObj.totalInvested) or 0.0)
        local refund = math.floor(totalInvested * ECON_SELL_REFUND_RATE)
        if econIsFinite(unitObj.refund) then
            refund = math.max(0.0, unitObj.refund)
        end

        local maxCap = tonumber(state.maxPlacementCap) or 20
        local totalPlaced = tonumber(state.totalPlaced) or 0
        if totalPlaced >= maxCap and state.wantsHigherTierPlacement then
            return { sell = true, refund = refund, reason = "free_placement_cap" }
        end

        local yen = math.max(0.0, tonumber(state.yen) or 0.0)
        local goal = state.bestHighValueTarget
        if goal and (tonumber(goal.cost) or 0.0) > yen and (yen + refund) >= (tonumber(goal.cost) or 0.0) and refund > 0 then
            local highTier = ((tonumber(goal.unitMaxDps) or 0.0) >= 0.55 * bestMaxDps)
            local unlocks = (goal.isBreakpointStep == true) or
                ((goal.unlocksAir or goal.bpUnlocksAir) and state.needAir) or
                ((goal.unlocksBleed or goal.bpUnlocksBleed) and state.needBleed) or
                (goal.kind == "place" and goal.isBuff and (tonumber(state.placedBuffers) or 0) < 4 and state.hasCarries)
            if highTier or unlocks then
                return { sell = true, refund = refund, reason = "unlock_carry_or_breakpoint" }
            end
        end

        return no
    end

    -- Build live EconomyNN state & normalized action wrappers from Match.econ()'s (options, ctx)
    local function buildLiveEconEnv(options, ctx)
        local now = (Utils and Utils.now and Utils.now()) or os.clock()
        local money = tonumber(ctx and ctx.money)
        if money == nil and Match and Match.money then
            money = tonumber(Match.money())
        end
        money = math.max(0.0, money or 0.0)

        local wave = 0
        if Match and Match.wave then
            local okW, wVal = pcall(Match.wave)
            if okW and tonumber(wVal) then
                wave = tonumber(wVal)
            end
        end
        local totalWaves = (Match and tonumber(Match.total)) or 15
        local isInfinite = (Match and Match.infinite == true) or (totalWaves >= 1000)

        local wavesLeft = 1
        if isInfinite then
            wavesLeft = tonumber(ctx and ctx.farmLeft) or math.max(5, 65 - wave)
        else
            local rawLeft = tonumber(ctx and ctx.left)
            if rawLeft ~= nil then
                wavesLeft = math.max(1, rawLeft)
            else
                wavesLeft = math.max(1, totalWaves - wave)
            end
        end

        local waveSec = tonumber(ctx and ctx.waveSec) or (Match and Match.info and tonumber(Match.info.waveSec)) or 20.0
        if waveSec <= 0.0 then
            waveSec = 20.0
        end
        local farmIncome = math.max(0.0, tonumber(ctx and ctx.farmNow) or 0.0)
        local coming1Reward = (ctx and ctx.coming and ctx.coming[1] and tonumber(ctx.coming[1].reward)) or nil
        local estIncomeRate = tonumber(ctx and ctx.incomeRate) or 0.0
        local nextWaveIncome = 500.0 + farmIncome
        if coming1Reward and coming1Reward > 0.0 then
            nextWaveIncome = coming1Reward + farmIncome
        elseif estIncomeRate > 0.0 then
            nextWaveIncome = estIncomeRate * waveSec
        end
        nextWaveIncome = math.max(1.0, nextWaveIncome)
        local incomeRate = estIncomeRate
        if incomeRate <= 0.0 then
            incomeRate = nextWaveIncome / math.max(1.0, waveSec)
        end

        -- Hoisted & cached Match.team economy metadata (recomputed only if Match.team or Match.mod changes)
        local teamMembers = (Match and Match.team) or EMPTY_LIST
        local curMod = Match and Match.mod
        local tCache = AI._teamEconCache
        if not tCache or tCache.teamRef ~= teamMembers or tCache.teamLen ~= #teamMembers or tCache.modRef ~= curMod then
            local baseBestMaxDps = 1.0
            local baseMaxFarmVal = 0.0
            local baseMaxDpsById = {}
            local baseCapById = {}
            for i = 1, #teamMembers do
                local tm = teamMembers[i]
                if tm and tm.id then
                    local id = tm.id
                    local eRows = getEnrichedEconRows(id)
                    local maxLvl = (eRows and eRows.max) or 0
                    local cap = 1
                    if tm.u and Units and Units.cap then
                        local okC, capV = pcall(Units.cap, tm.u)
                        if okC and tonumber(capV) then
                            cap = math.max(1, tonumber(capV))
                        end
                    elseif tm.data and tonumber(tm.data.spawn_cap) then
                        cap = math.max(1, tonumber(tm.data.spawn_cap))
                    end
                    baseCapById[id] = cap

                    local isF = (Units and Units.isFarm and Units.isFarm(id) == true) or false
                    local isB = (Units and Units.allyBuff and Units.allyBuff(id) ~= nil) or false
                    if isF then
                        local maxF = 0.0
                        if tm.u and Units and Units.farm then
                            local okF, fVal = pcall(Units.farm, tm.u, maxLvl)
                            if okF and tonumber(fVal) then
                                maxF = tonumber(fVal)
                            end
                        elseif eRows and eRows[maxLvl] then
                            maxF = tonumber(eRows[maxLvl].farm) or 0.0
                        end
                        baseMaxFarmVal = baseMaxFarmVal + cap * math.max(0.0, maxF)
                        baseMaxDpsById[id] = 0.0
                    elseif isB then
                        baseMaxDpsById[id] = 0.0
                    else
                        local mDps = 0.0
                        if tm.u and Units and Units.dps then
                            local okD, dVal = pcall(Units.dps, tm.u, maxLvl, curMod)
                            if okD and tonumber(dVal) and tonumber(dVal) > 0.0 then
                                mDps = tonumber(dVal)
                            end
                        end
                        if mDps <= 0.0 and eRows then
                            mDps = eRows.maxDps or 0.0
                        end
                        if mDps > (baseMaxDpsById[id] or 0.0) then
                            baseMaxDpsById[id] = mDps
                        end
                        if mDps > baseBestMaxDps then
                            baseBestMaxDps = mDps
                        end
                    end
                end
            end
            tCache = {
                teamRef = teamMembers,
                teamLen = #teamMembers,
                modRef = curMod,
                teamBestMaxDps = baseBestMaxDps,
                maxFarmValue = baseMaxFarmVal,
                baseMaxDpsById = baseMaxDpsById,
                unitCapById = baseCapById,
            }
            AI._teamEconCache = tCache
        end

        local teamBestMaxDps = tCache.teamBestMaxDps
        local maxFarmValue = tCache.maxFarmValue
        local unitCapById = tCache.unitCapById
        local unitMaxDpsById = AI._unitMaxDpsByIdBuf
        clearMap(unitMaxDpsById)
        for k, v in pairs(tCache.baseMaxDpsById) do
            unitMaxDpsById[k] = v
        end

        -- Scan Match.mine once for placed counts, tactical coverage, and unit ages
        local placedById = AI._placedByIdBuf
        clearMap(placedById)
        local placedAttackers = 0
        local placedBuffers = 0
        local placedCC = 0
        local airUnits = 0
        local bleedUnits = 0
        local hasCarries = false
        local totalRawCarryDps = 0.0
        local liveTeamDpsSum = 0.0
        local mineList = (Match and Match.mine) or EMPTY_LIST
        local totalPlaced = #mineList
        if Match and Match.fieldCount then
            local okFc, fcVal = pcall(Match.fieldCount)
            if okFc and tonumber(fcVal) then
                totalPlaced = tonumber(fcVal)
            end
        end

        for i = 1, #mineList do
            local m = mineList[i]
            if m then
                if AI._unitBornAt[m] == nil then
                    AI._unitBornAt[m] = now
                end
                local st = m:FindFirstChild("_stats")
                local idObj = st and st:FindFirstChild("id")
                if idObj then
                    local id = idObj.Value
                    placedById[id] = (placedById[id] or 0) + 1
                    local lvl = 0
                    local upgObj = st:FindFirstChild("upgrade")
                    if upgObj and tonumber(upgObj.Value) then
                        lvl = tonumber(upgObj.Value)
                    end
                    local isF = (Units and Units.isFarm and Units.isFarm(id) == true) or false
                    local isB = (Units and Units.allyBuff and Units.allyBuff(id) ~= nil) or false
                    if isB then
                        placedBuffers = placedBuffers + 1
                    elseif not isF then
                        placedAttackers = placedAttackers + 1
                        local eRows = getEnrichedEconRows(id)
                        local curR = nil
                        if eRows then
                            curR = eRows[math.min(lvl, eRows.max)]
                        end
                        local uMax = unitMaxDpsById[id] or (eRows and eRows.maxDps) or 0.0
                        if uMax > teamBestMaxDps then
                            teamBestMaxDps = uMax
                        end
                        if uMax >= 0.45 * teamBestMaxDps then
                            hasCarries = true
                        end
                        local mDps = 0.0
                        if Match and Match.liveDps then
                            local okL, lVal = pcall(Match.liveDps, m, id)
                            if okL and tonumber(lVal) and tonumber(lVal) > 0 then
                                mDps = tonumber(lVal)
                            end
                        end
                        liveTeamDpsSum = liveTeamDpsSum + mDps
                        if uMax >= 0.40 * teamBestMaxDps then
                            totalRawCarryDps = totalRawCarryDps + mDps
                        end

                        local canHitAir = (curR ~= nil and curR.canAir == true)
                        if not canHitAir and Match and Match.canAir then
                            local okCa, caVal = pcall(Match.canAir, m)
                            if okCa and caVal == true then
                                canHitAir = true
                            end
                        end
                        if canHitAir then
                            airUnits = airUnits + 1
                        end
                        if curR and curR.bleed == true then
                            bleedUnits = bleedUnits + 1
                        end
                        if curR and curR.hasCC == true then
                            placedCC = placedCC + 1
                        end
                    end
                end
            end
        end

        local currentTeamDps = tonumber(ctx and ctx.teamDps) or 0.0
        if currentTeamDps <= 0.0 then
            currentTeamDps = liveTeamDpsSum
        end

        local cover = econClamp(tonumber(ctx and ctx.cover) or 0.6, 0.1, 1.0)
        local cfgDanger = (Config and tonumber(Config.dangerReach)) or 0.70
        local cfgSafe = (Config and tonumber(Config.safeReach)) or 0.45
        local effDanger = math.min(cfgDanger, cover * 0.9)
        local effSafe = math.min(cfgSafe, cover * 0.75)

        local defensePressure = econClamp01(tonumber(ctx and ctx.pressure) or 0.0)
        local leak = (ctx and ctx.leak ~= nil and ctx.leak ~= false)
        local airLeak = (ctx and ctx.airLeak ~= nil and ctx.airLeak ~= false)

        local upcomingAirHp = 0.0
        local upcomingMaxHp = tonumber(ctx and ctx.hpAlive) or 0.0
        if ctx and type(ctx.coming) == "table" then
            for ci = 1, math.min(3, #ctx.coming) do
                local cItem = ctx.coming[ci]
                if cItem then
                    upcomingAirHp = upcomingAirHp + (tonumber(cItem.airHp) or 0.0)
                    if ci <= 2 and (tonumber(cItem.hp) or 0.0) > upcomingMaxHp then
                        upcomingMaxHp = tonumber(cItem.hp) or 0.0
                    end
                end
            end
        end
        local roadSec = tonumber(ctx and ctx.roadSec) or 40.0
        if roadSec < 10.0 then
            roadSec = 10.0
        end
        local requiredDps = upcomingMaxHp / math.max(10.0, roadSec * 0.85)

        local hasAirThreat = airLeak or upcomingAirHp > 0.0 or (Match and (Match.comingAir == true or Match.flyerSeen == true))
        local airShare = tonumber(ctx and ctx.airShare)
        local needAir = airLeak or (hasAirThreat and (airUnits == 0 or (airShare ~= nil and airShare < 0.35)))

        local hasRegenThreat = (Match and Match.info and (Match.info.regen == true or (tonumber(Match.info.regen) or 0.0) > 0.0)) or false
        if not hasRegenThreat and options then
            for oi = 1, #options do
                local wStr = options[oi] and options[oi].what
                if type(wStr) == "string" and string.find(wStr, "bleed", 1, true) ~= nil then
                    hasRegenThreat = true
                    break
                end
            end
        end
        local needBleed = hasRegenThreat and (bleedUnits == 0)
        local needCC = (placedCC == 0) and (wave >= 4 or defensePressure >= 0.35)

        local farmSpare = (Config and tonumber(Config.farmSpare)) or 2.0
        local farmUnitsOn = (not Config) or (Config.farmUnits ~= false)
        local farmNeeded = true
        if ctx and tonumber(ctx.future) and tonumber(ctx.wantLeft) and tonumber(ctx.wantLeft) > 0.0 then
            if tonumber(ctx.future) >= tonumber(ctx.wantLeft) * 1.1 then
                farmNeeded = false
            end
        end

        local maxCap = (Match and (tonumber(Match.effectiveFieldMax) or tonumber(Match.FIELD_MAX))) or 20
        local wantsHigherTierPlacement = false
        for i = 1, #teamMembers do
            local tm = teamMembers[i]
            if tm and tm.id then
                local id = tm.id
                local isF = (Units and Units.isFarm and Units.isFarm(id) == true) or false
                local isB = (Units and Units.allyBuff and Units.allyBuff(id) ~= nil) or false
                local cap = unitCapById[id] or 1
                local cnt = placedById[id] or 0
                if not isF and cnt < cap then
                    local uMax = unitMaxDpsById[id] or 0.0
                    if uMax >= 0.45 * teamBestMaxDps or (isB and placedBuffers < 4 and hasCarries) then
                        wantsHigherTierPlacement = true
                        break
                    end
                end
            end
        end

        local state = AI._econStateBuf
        state.yen = money
        state.wave = wave
        state.totalWaves = totalWaves
        state.isInfinite = isInfinite
        state.wavesLeft = wavesLeft
        state.nextWaveIncome = nextWaveIncome
        state.incomeRate = incomeRate
        state.defensePressure = defensePressure
        state.leak = leak
        state.airLeak = airLeak
        state.needAir = needAir
        state.needBleed = needBleed
        state.needCC = needCC
        state.placedBuffers = placedBuffers
        state.hasCarries = hasCarries
        state.placedAttackers = placedAttackers
        state.placedCC = placedCC
        state.airUnits = airUnits
        state.bleedUnits = bleedUnits
        state.placedFarmValue = farmIncome
        state.maxFarmValue = maxFarmValue
        state.teamBestMaxDps = teamBestMaxDps
        state.currentTeamDps = currentTeamDps
        state.requiredDps = requiredDps
        state.totalPlaced = totalPlaced
        state.maxPlacementCap = maxCap
        state.nowSec = now
        state.lastStarterSellSec = AI._lastStarterSell or -9999.0
        state.safeReach = effSafe
        state.effDanger = effDanger
        state.farmNeeded = farmNeeded
        state.wantsHigherTierPlacement = wantsHigherTierPlacement
        state.bestAtkImmRate = 0.0
        state.bestAtkBpRate = 0.0
        state.bestFarmImmRate = 0.0
        state.bestFarmBpRate = 0.0
        state.bestSaveTarget = nil
        state.bestHighValueTarget = nil

        -- Convert all 6 v2.34 Match.econ() option shapes into normalized econAction entries (reusing AI._econActionPool)
        local econActions = AI._econActionsBuf
        local actionPool = AI._econActionPool
        local nActions = 0
        local bpBuf = AI._bpLookaheadBuf
        local optList = options or EMPTY_LIST
        for oi = 1, #optList do
            local opt = optList[oi]
            if opt then
                local id = nil
                if opt.e and opt.e.id then
                    id = opt.e.id
                elseif opt.m then
                    local mst = opt.m:FindFirstChild("_stats")
                    if mst and mst:FindFirstChild("id") then
                        id = mst.id.Value
                    end
                end

                if id then
                    local isFarm = (opt.farm == true) or (Units and Units.isFarm and Units.isFarm(id) == true) or false
                    local isBuff = (opt.support == true) or (Units and Units.allyBuff and Units.allyBuff(id) ~= nil) or false
                    local isPlace = (opt.place == true)
                    local kind = "upgrade"
                    if isPlace then
                        kind = "place"
                    end
                    local curLvl = -1
                    if not isPlace then
                        curLvl = 0
                        local mst = opt.m and opt.m:FindFirstChild("_stats")
                        if mst and mst:FindFirstChild("upgrade") and tonumber(mst.upgrade.Value) then
                            curLvl = tonumber(mst.upgrade.Value)
                        end
                    end

                    local eRows = getEnrichedEconRows(id)
                    local maxLvl = (eRows and eRows.max) or 1
                    local isCC = (not isFarm and not isBuff and eRows ~= nil and eRows.hasAnyCC == true)
                    local cost = math.max(1.0, tonumber(opt.cost) or 1.0)
                    local optGain = math.max(0.0, tonumber(opt.gain) or 0.0)

                    local costMul = 1.0
                    if eRows and eRows[curLvl + 1] and (tonumber(eRows[curLvl + 1].cost) or 0.0) > 0.0 then
                        costMul = cost / tonumber(eRows[curLvl + 1].cost)
                    end

                    local curDps = 0.0
                    if isFarm then
                        if isPlace then
                            curDps = optGain
                        else
                            local mst = opt.m and opt.m:FindFirstChild("_stats")
                            local fa = mst and mst:FindFirstChild("farm_amount")
                            if fa and tonumber(fa.Value) then
                                curDps = tonumber(fa.Value)
                            elseif opt.e and opt.e.u and Units and Units.farm then
                                local okF, fV = pcall(Units.farm, opt.e.u, curLvl)
                                if okF and tonumber(fV) then
                                    curDps = tonumber(fV)
                                end
                            end
                        end
                    elseif not isBuff then
                        if isPlace then
                            if opt.e and opt.e.u and Units and Units.dps then
                                local okD, dV = pcall(Units.dps, opt.e.u, 0, Match and Match.mod)
                                if okD and tonumber(dV) and tonumber(dV) > 0.0 then
                                    curDps = tonumber(dV)
                                end
                            end
                            if curDps <= 0.0 then
                                curDps = optGain
                            end
                        else
                            if opt.m and Match and Match.liveDps then
                                local okL, lV = pcall(Match.liveDps, opt.m, id)
                                if okL and tonumber(lV) and tonumber(lV) > 0.0 then
                                    curDps = tonumber(lV)
                                end
                            end
                        end
                    end

                    local immGain = optGain
                    local immRate = optGain / cost
                    local bpRate = immRate
                    local bpMultiplier = 0.0
                    local paybackWaves = 0.0
                    local isBreakpointStep = false
                    local unlocksAir = false
                    local unlocksBleed = false
                    local unlocksFullAoe = false
                    local unlocksCC = false
                    local bpUnlocksAir = false
                    local bpUnlocksBleed = false
                    local bpUnlocksFullAoe = false
                    local bpUnlocksCC = false
                    local farmUnprofitable = false

                    if isFarm then
                        local bp = AI.computeBreakpointLookahead(eRows, curLvl, curDps, costMul, 4, bpBuf)
                        if bp.immGain > 0.0 then
                            immGain = bp.immGain
                            immRate = bp.immRate
                            bpRate = bp.bpRate
                            bpMultiplier = bp.bpMultiplier
                            isBreakpointStep = bp.isBreakpointStep
                            paybackWaves = bp.paybackWaves
                        else
                            paybackWaves = cost / math.max(1e-6, optGain)
                        end
                        if (not farmUnitsOn) or (not farmNeeded) or (wavesLeft - 1.0 < paybackWaves + farmSpare) then
                            farmUnprofitable = true
                        end
                    elseif isBuff then
                        if isPlace then
                            local kBuf = math.min(3, placedBuffers)
                            local bpGainB = optGain
                            local bpCostB = cost
                            if totalRawCarryDps > 0.0 and kBuf < 3 then
                                local remCopies = 4 - kBuf
                                local chainMul = (ECON_BUFF_CURVE[5] - ECON_BUFF_CURVE[kBuf + 1]) * 0.9
                                local chainGain = totalRawCarryDps * chainMul
                                local chainCost = cost * remCopies
                                if chainCost > 0.0 and (chainGain / chainCost) > immRate then
                                    bpGainB = chainGain
                                    bpCostB = chainCost
                                end
                            end
                            bpRate = math.max(immRate, bpGainB / math.max(1.0, bpCostB))
                            if bpRate > 0.0 then
                                bpMultiplier = econClamp01(((bpRate / math.max(immRate, 1e-6)) - 1.0) / 3.0)
                            end
                            isBreakpointStep = (kBuf == 3 and hasCarries)
                        end
                    else
                        local bp = AI.computeBreakpointLookahead(eRows, curLvl, curDps, costMul, 4, bpBuf)
                        if bp.immRate > 0.0 or bp.bpRate > 0.0 then
                            local g1 = bp.immGain
                            local gBp = bp.bpGain
                            if isCC and currentTeamDps > 0.0 then
                                local holdAdd = currentTeamDps * 0.24 / (1.0 + placedCC)
                                if bp.unlocksCC then
                                    g1 = g1 + holdAdd
                                end
                                if bp.bpUnlocksCC then
                                    gBp = gBp + holdAdd
                                end
                            end
                            immGain = g1
                            immRate = g1 / cost
                            bpRate = math.max(immRate, gBp / math.max(1.0, bp.bpCost))
                            if bpRate > 0.0 then
                                bpMultiplier = econClamp01(((bpRate / math.max(immRate, 1e-6)) - 1.0) / 3.0)
                            end
                            isBreakpointStep = bp.isBreakpointStep
                            unlocksAir = bp.unlocksAir
                            unlocksBleed = bp.unlocksBleed
                            unlocksFullAoe = bp.unlocksFullAoe
                            unlocksCC = bp.unlocksCC
                            bpUnlocksAir = bp.bpUnlocksAir
                            bpUnlocksBleed = bp.bpUnlocksBleed
                            bpUnlocksFullAoe = bp.bpUnlocksFullAoe
                            bpUnlocksCC = bp.bpUnlocksCC
                        end
                    end

                    local uMaxDps = unitMaxDpsById[id] or (eRows and eRows.maxDps) or 0.0
                    if isFarm or isBuff then
                        uMaxDps = 0.0
                    end
                    local uCap = unitCapById[id] or 1
                    local pCopies = placedById[id] or 0
                    local actKey = kind .. ":" .. tostring(id) .. ":L" .. tostring(curLvl)

                    if not (isFarm and farmUnprofitable) then
                        nActions = nActions + 1
                        local act = actionPool[nActions]
                        if not act then
                            act = {}
                            actionPool[nActions] = act
                        end
                        act.orig = opt
                        act.kind = kind
                        act.key = actKey
                        act.unitId = id
                        act.isFarm = isFarm
                        act.isBuff = isBuff
                        act.isCC = isCC
                        act.farmUnprofitable = farmUnprofitable
                        act.cost = cost
                        act.gain = immGain
                        act.immRate = immRate
                        act.bpRate = bpRate
                        act.bpMultiplier = bpMultiplier
                        act.paybackWaves = paybackWaves
                        act.isBreakpointStep = isBreakpointStep
                        act.unlocksAir = unlocksAir
                        act.unlocksBleed = unlocksBleed
                        act.unlocksFullAoe = unlocksFullAoe
                        act.unlocksCC = unlocksCC
                        act.bpUnlocksAir = bpUnlocksAir
                        act.bpUnlocksBleed = bpUnlocksBleed
                        act.bpUnlocksFullAoe = bpUnlocksFullAoe
                        act.bpUnlocksCC = bpUnlocksCC
                        act.unitMaxDps = uMaxDps
                        act.placedCopies = pCopies
                        act.unitCap = uCap
                        act.curLvl = curLvl
                        act.maxLvl = math.max(1, maxLvl)
                        econActions[nActions] = act
                    end
                end
            end
        end
        for i = #econActions, nActions + 1, -1 do
            econActions[i] = nil
        end

        local norm = AI.computeActionNormStats(state, econActions, AI._econNormBuf)
        state.bestAtkImmRate = norm.bestAtkImmRate
        state.bestAtkBpRate = norm.bestAtkBpRate
        state.bestFarmImmRate = norm.bestFarmImmRate
        state.bestFarmBpRate = norm.bestFarmBpRate
        state.bestSaveTarget = norm.bestSaveTarget
        state.bestHighValueTarget = norm.bestSaveTarget

        local envOut = AI._econEnvBuf
        envOut.state = state
        envOut.actions = econActions
        envOut.unitMaxDpsById = unitMaxDpsById
        return envOut
    end

    -- Safe midgame starter selling obeying EVERY AirflowLab watchdog rule:
    --   - age >= 45s (4.5x safety over 10s sell_immediately_after_spawn)
    --   - saves sold spotKey in AI._soldSpots for 15s (0 sell_and_rebuy_same_spot)
    --   - checks uData.unsellable, non-farm, non-buff, non-CC, non-trainee, non-fusion, non-bless, non-summon
    --   - cooldown >= 30s, max 1 attempt per model, checks model.Parent == workspace._UNITS
    function AI.maybeSellStarter(ctx, options)
        if not (Match and Match.mine and App and App.request) then
            return false
        end
        if Match.finished then
            return false
        end
        local overOk, over = pcall(function()
            return workspace and workspace._DATA and workspace._DATA.GameFinished and workspace._DATA.GameFinished.Value
        end)
        if overOk and over then
            return false
        end

        local now = (Utils and Utils.now and Utils.now()) or os.clock()
        if (now - (AI._lastStarterSell or -9999.0)) < 30.0 then
            return false
        end
        local wave = 0
        if Match.wave then
            local okW, wVal = pcall(Match.wave)
            if okW and tonumber(wVal) then
                wave = tonumber(wVal)
            end
        end
        if wave < 8 then
            return false
        end
        if ctx and (ctx.leak or ctx.airLeak) then
            return false
        end

        -- Fast O(#Match.mine) age & tried pre-check: avoid building full econ env when no unit is >= 45s old
        local preMine = Match.mine or EMPTY_LIST
        local hasAgedCandidate = false
        for i = 1, #preMine do
            local m = preMine[i]
            if m then
                local bAt = AI._unitBornAt[m]
                if bAt == nil then
                    AI._unitBornAt[m] = now
                elseif not AI._sellTried[m] and (now - bAt) >= 45.0 then
                    hasAgedCandidate = true
                end
            end
        end
        if not hasAgedCandidate then
            return false
        end

        local env = buildLiveEconEnv(options, ctx)
        local st = env.state
        if st.defensePressure >= st.safeReach or st.placedAttackers < 2 then
            return false
        end
        AI._lastEconEnvOptions = options
        AI._lastEconEnv = env
        local canNeedCap = (st.totalPlaced >= st.maxPlacementCap and st.wantsHigherTierPlacement)
        local canUnlockGoal = (st.bestHighValueTarget ~= nil and (tonumber(st.bestHighValueTarget.cost) or 0.0) > st.yen)
        if not canNeedCap and not canUnlockGoal then
            return false
        end

        local unitsFolder = workspace and workspace:FindFirstChild("_UNITS")
        local mineList = Match.mine or EMPTY_LIST
        for i = 1, #mineList do
            local m = mineList[i]
            if m and not AI._sellTried[m] and (not unitsFolder or m.Parent == unitsFolder) then
                local bornAt = AI._unitBornAt[m]
                if bornAt and (now - bornAt) >= 45.0 then
                    local mst = m:FindFirstChild("_stats")
                    local idObj = mst and mst:FindFirstChild("id")
                    local id = idObj and idObj.Value
                    local uData = id and Core and Core.Units and Core.Units[id]
                    if id and uData and not uData.unsellable then
                        local isSummon = (mst:FindFirstChild("parent_unit") ~= nil and mst.parent_unit.Value ~= nil)
                        local isFarm = (Units and Units.isFarm and Units.isFarm(id) == true) or false
                        local isBuff = (Units and Units.allyBuff and Units.allyBuff(id) ~= nil) or false
                        local isBless = (Units and Units.BLESS and Units.BLESS.by and Units.BLESS.by[id] ~= nil) or false
                        local isFusion = (Units and Units.FUSION and ((Units.FUSION.attacks and Units.FUSION.attacks[id] ~= nil) or id == Units.FUSION.hero)) or false
                        local uuidObj = mst:FindFirstChild("uuid")
                        local isTrainee = (Match.trainee ~= nil and uuidObj ~= nil and uuidObj.Value == Match.trainee)
                        local isTrial = (Match.trialId ~= nil and id == Match.trialId)

                        if not isSummon and not isFarm and not isBuff and not isBless and not isFusion and not isTrainee and not isTrial then
                            local lvl = 0
                            local upgObj = mst:FindFirstChild("upgrade")
                            if upgObj and tonumber(upgObj.Value) then
                                lvl = tonumber(upgObj.Value)
                            end
                            local eRows = getEnrichedEconRows(id)
                            local curR = nil
                            if eRows then
                                curR = eRows[math.min(lvl, eRows.max)]
                            end
                            local isCC = (eRows ~= nil and eRows.hasAnyCC == true)
                            local hasCC = (curR ~= nil and curR.hasCC == true)
                            local canAir = (curR ~= nil and curR.canAir == true)
                            if not canAir and Match.canAir then
                                local okA, aV = pcall(Match.canAir, m)
                                if okA and aV == true then
                                    canAir = true
                                end
                            end
                            local hasBleed = (curR ~= nil and curR.bleed == true)

                            local curDps = 0.0
                            if Match.liveDps then
                                local okL, lV = pcall(Match.liveDps, m, id)
                                if okL and tonumber(lV) then
                                    curDps = tonumber(lV)
                                end
                            end
                            local totalSpent = 0.0
                            local spentObj = mst:FindFirstChild("total_spent")
                            if spentObj and tonumber(spentObj.Value) and tonumber(spentObj.Value) > 0 then
                                totalSpent = tonumber(spentObj.Value)
                            elseif eRows then
                                for lv = 0, math.min(lvl, eRows.max) do
                                    if eRows[lv] then
                                        totalSpent = totalSpent + (tonumber(eRows[lv].cost) or 0.0)
                                    end
                                end
                            end

                            local uMaxDps = env.unitMaxDpsById[id] or (eRows and eRows.maxDps) or 0.0
                            local unitObj = {
                                isFarm = false,
                                isBuff = false,
                                isCC = isCC,
                                hasCC = hasCC,
                                isTrainee = false,
                                isFusion = false,
                                unsellable = false,
                                isSoleAir = (canAir and st.airUnits <= 1),
                                isSoleBleed = (hasBleed and st.bleedUnits <= 1),
                                placedAtSec = bornAt,
                                ageSec = now - bornAt,
                                maxDps = uMaxDps,
                                currentDps = curDps,
                                totalInvested = totalSpent,
                            }

                            local ev = AI.evaluateStarterSell(st, unitObj)
                            if ev.sell then
                                AI._sellTried[m] = true
                                local soldSpotKey = nil
                                local okPos, pos = pcall(safePivotPos, m)
                                if okPos and pos and Match.spotKey then
                                    soldSpotKey = Match.spotKey(pos)
                                end
                                local _, res = App.request("sell", "sell_unit_ingame", m)
                                AI._lastStarterSell = now
                                AI._lastEconEnvOptions = nil
                                AI._lastEconEnv = nil
                                if res == true then
                                    AI._starterSellCount = (AI._starterSellCount or 0) + 1
                                    if soldSpotKey then
                                        AI._soldSpots[soldSpotKey] = now
                                    end
                                    Match.noSpot = {}
                                    Match.saveSince = nil
                                    local uName = (Units and Units.name and Units.name(id)) or tostring(id)
                                    local fmtRef = (Utils and Utils.fmt and Utils.fmt(ev.refund)) or tostring(ev.refund)
                                    App.log(2, "AI_SELL_STARTER", string.format("sold starter %s (age=%.0fs, refund=¥%s, reason=%s)", uName, now - bornAt, fmtRef, tostring(ev.reason)))
                                    App.status("Economy", string.format("Sold starter %s (+¥%s) — %s", uName, fmtRef, tostring(ev.reason)))
                                    return true
                                end
                                return false
                            end
                        end
                    end
                end
            end
        end

        return false
    end

    -- Neural Economy Inference: scores affordable options + synthetic SAVE with EconomyNN
    -- Enforces hard safety & watchdog guardrails BEFORE scoring:
    --   1. NEVER returns an unaffordable option as buy (0 spend_over_balance)
    --   2. leak / pressure >= dangerReach / piling -> blocks farms & SAVE
    --   3. airLeak -> filters to air-unlocking options when available
    --   4. saveSec >= 55s -> disables SAVE to prevent 90s idle_in_match_with_money watchdog
    function AI.chooseEconOption(options, ctx)
        if not options or #options == 0 then
            return nil, nil, nil, nil
        end

        local env = nil
        if options ~= nil and AI._lastEconEnvOptions == options and AI._lastEconEnv ~= nil then
            env = AI._lastEconEnv
            AI._lastEconEnvOptions = nil
            AI._lastEconEnv = nil
        else
            env = buildLiveEconEnv(options, ctx)
        end
        local st = env.state
        local actions = env.actions
        if #actions == 0 then
            return nil, nil, nil, nil
        end

        local dangerThresh = math.min(0.72, st.effDanger or 0.70)
        local enemiesCnt = tonumber(ctx and ctx.enemies) or 0
        local emergency = st.leak or (st.defensePressure >= dangerThresh) or
            (st.placedAttackers == 0 and (st.defensePressure > 0.10 or enemiesCnt > 0)) or
            (ctx ~= nil and ctx.piling == true and enemiesCnt >= 18)

        local saveSec = 0.0
        if Match and Match.saveSince then
            saveSec = st.nowSec - Match.saveSince
        end
        local antiStall = (saveSec >= 55.0)

        local candidates = AI._econCandBuf
        clearArray(candidates)
        local nCand = 0
        local hasNonStarterBuy = false
        local needOpener = (st.placedAttackers == 0)
        for i = 1, #actions do
            local a = actions[i]
            if a.cost <= st.yen then
                local blockOpener = needOpener and (a.isFarm or a.isBuff)
                local blockEmergency = emergency and (a.isFarm or (a.isBuff and st.placedAttackers < 2))
                if not blockOpener and not blockEmergency then
                    local isStarterPlace = (a.kind == "place" and not a.isFarm and not a.isBuff and not a.isCC and a.unitMaxDps < 0.25 * st.teamBestMaxDps)
                    if not isStarterPlace then
                        hasNonStarterBuy = true
                    end
                    nCand = nCand + 1
                    candidates[nCand] = a
                end
            end
        end

        -- Avoid re-buying sold starters once starter selling has begun and better buys exist
        if (AI._starterSellCount or 0) > 0 and hasNonStarterBuy and nCand > 1 then
            local w = 0
            for i = 1, nCand do
                local a = candidates[i]
                local isStarterPlace = (a.kind == "place" and not a.isFarm and not a.isBuff and not a.isCC and a.unitMaxDps < 0.25 * st.teamBestMaxDps)
                if not isStarterPlace then
                    w = w + 1
                    candidates[w] = a
                end
            end
            if w > 0 then
                for i = nCand, w + 1, -1 do
                    candidates[i] = nil
                end
                nCand = w
            end
        end

        if st.airLeak and nCand > 0 then
            local hasAnyAir = false
            for i = 1, nCand do
                if candidates[i].unlocksAir then
                    hasAnyAir = true
                    break
                end
            end
            if hasAnyAir then
                local w = 0
                for i = 1, nCand do
                    local a = candidates[i]
                    if a.unlocksAir then
                        w = w + 1
                        candidates[w] = a
                    end
                end
                for i = nCand, w + 1, -1 do
                    candidates[i] = nil
                end
                nCand = w
            end
        end

        if nCand == 0 then
            if st.bestSaveTarget and st.bestSaveTarget.orig then
                local tgt = st.bestSaveTarget
                local waitEta = math.ceil(math.max(0.0, tgt.cost - st.yen) / math.max(1.0, st.incomeRate))
                local fmtCost = (Utils and Utils.fmt and Utils.fmt(tgt.cost)) or tostring(math.floor(tgt.cost))
                local waitStr = string.format("saving ¥%s for: %s (≈%ds) — EconomyNN", fmtCost, tostring(tgt.orig.what or "upgrade"), waitEta)
                return nil, 0.0, "EconomyNN save", waitStr
            end
            return nil, nil, nil, nil
        end

        if not emergency and not antiStall and st.bestSaveTarget then
            local saveAct = AI.buildSaveAction(st.bestSaveTarget, AI._econSaveActBuf)
            if saveAct then
                nCand = nCand + 1
                candidates[nCand] = saveAct
            end
        end

        local featBuf = AI._eFeatBuf
        local bestCand = candidates[1]
        local bestScore = -math.huge
        for i = 1, #candidates do
            local cand = candidates[i]
            AI.extractEconFeatures(st, cand, featBuf)
            local sc = AI.scoreEconomy(featBuf)
            if not econIsFinite(sc) then
                return nil, nil, nil, nil
            end
            if sc > bestScore then
                bestScore = sc
                bestCand = cand
            end
        end

        if not bestCand then
            return nil, nil, nil, nil
        end

        if bestCand.kind == "save" then
            local tgt = st.bestSaveTarget
            local tgtWhat = (tgt and tgt.orig and tgt.orig.what) or "breakpoint"
            local waitEta = math.ceil(math.max(0.0, bestCand.cost - st.yen) / math.max(1.0, st.incomeRate))
            local fmtCost = (Utils and Utils.fmt and Utils.fmt(bestCand.cost)) or tostring(math.floor(bestCand.cost))
            local waitStr = string.format("saving ¥%s for: %s (≈%ds) — EconomyNN (score=%.2f)", fmtCost, tostring(tgtWhat), waitEta, bestScore)
            return nil, bestScore, "EconomyNN save", waitStr
        end

        -- Double-check strict affordability invariant (0 spend_over_balance)
        if not bestCand.orig or (tonumber(bestCand.orig.cost) or math.huge) > st.yen then
            return nil, nil, nil, nil
        end

        local reason = "EconomyNN"
        if bestCand.unlocksAir and st.needAir then
            reason = "EconomyNN (anti-air unlock)"
        elseif bestCand.unlocksBleed and st.needBleed then
            reason = "EconomyNN (bleed unlock)"
        elseif bestCand.isBreakpointStep then
            reason = "EconomyNN (breakpoint lookahead)"
        elseif bestCand.isFarm then
            reason = "EconomyNN (farm snowball)"
        elseif bestCand.isBuff and bestCand.kind == "place" then
            reason = "EconomyNN (buffer clique)"
        end
        return bestCand.orig, bestScore, reason, nil
    end

    -- ========================================================================
    -- Stage 6: Neural AI Tactics (v2.37 AI) — ActiveNN (22d) & SkipNN (18d)
    -- Exact 1-to-1 mirror of engine/tactics_features.js
    -- ========================================================================
    function AI.scoreActive(feat)
        local out = forwardMLP(AI.ACTIVE_NET, feat)
        return out[1]
    end

    function AI.scoreSkip(feat)
        local out = forwardMLP(AI.SKIP_NET, feat)
        return out[1]
    end

    -- Pure boss-next-wave heuristic matching engine/tactics_features.js isBossNextWave
    function AI.isBossNextWave(wave, totalWaves, isInfinite)
        local wNum = tonumber(wave)
        if not econIsFinite(wNum) then
            wNum = 0
        end
        local nextW = math.floor(wNum) + 1
        if nextW <= 0 then
            return false
        end
        if (nextW % 5) == 0 then
            return true
        end
        local totNum = tonumber(totalWaves)
        if not econIsFinite(totNum) then
            totNum = 0
        end
        local tot = math.floor(totNum)
        if (not isInfinite) and tot > 0 and nextW == tot then
            return true
        end
        return false
    end

    -- Safe reader for player base HP fraction + leak-event tracker
    function AI.getBaseHpFrac()
        local ok, hp, maxHp = pcall(function()
            local bases = workspace and workspace:FindFirstChild("_BASES")
            local pBase = bases and bases:FindFirstChild("player")
            local base = pBase and pBase:FindFirstChild("base")
            local fakeUnit = base and base:FindFirstChild("fake_unit")
            local hum = fakeUnit and fakeUnit:FindFirstChildOfClass("Humanoid")
            if hum and hum.MaxHealth and hum.MaxHealth > 0 then
                return hum.Health, hum.MaxHealth
            end
            return nil, nil
        end)
        if ok and econIsFinite(hp) and econIsFinite(maxHp) and maxHp > 0 then
            if AI._lastBaseHp ~= nil and hp < AI._lastBaseHp - 1e-3 then
                AI._leakEvents = (AI._leakEvents or 0) + 1
            end
            AI._lastBaseHp = hp
            return econClamp01(hp / maxHp)
        end
        return 1.0
    end

    -- Exact 1-to-1 mirror of engine/tactics_features.js checkActiveGuardrails
    function AI.checkActiveGuardrails(ctx)
        local c = ctx or EMPTY_LIST
        local rawCount = tonumber(c.count)
        if not econIsFinite(rawCount) or rawCount < 0.0 then
            rawCount = 0.0
        end
        local rawCrowd = tonumber(c.crowd)
        if not econIsFinite(rawCrowd) or rawCrowd < 0.0 then
            rawCrowd = 0.0
        end
        local wholeMap = (c.isWholeMap == true)
        local effCount = rawCount
        if wholeMap then
            effCount = math.max(rawCount, rawCrowd)
        end

        if effCount <= 0.0 then
            return { decided = true, cast = false, reason = "no_targets" }
        end

        local maxProg = tonumber(c.maxInRangeProg)
        if not econIsFinite(maxProg) then
            maxProg = 0.0
        end
        local nearBase = (c.nearBase == true) or (maxProg >= 0.82)

        local baseHpFrac = 1.0
        if econIsFinite(c.baseHpFrac) then
            baseHpFrac = c.baseHpFrac
        end

        if nearBase then
            return { decided = true, cast = true, reason = "emergency_near_base" }
        end
        if baseHpFrac < 0.5 and effCount > 0.0 then
            return { decided = true, cast = true, reason = "emergency_low_base_hp" }
        end

        return { decided = false }
    end

    -- Exact 1-to-1 mirror of engine/tactics_features.js checkSkipGuardrails
    function AI.checkSkipGuardrails(ctx)
        local c = ctx or EMPTY_LIST
        local wNum = tonumber(c.wave)
        if not econIsFinite(wNum) then
            wNum = 0
        end
        local wave = math.floor(wNum)

        local totNum = tonumber(c.totalWaves)
        if not econIsFinite(totNum) then
            totNum = 0
        end
        local totalWaves = math.floor(totNum)
        local isInfinite = (c.isInfinite == true)

        local dangerReach = 0.72
        if econIsFinite(c.dangerReach) then
            dangerReach = c.dangerReach
        end

        if wave < 1 then
            return { decided = true, skip = false, reason = "pre_wave_1" }
        end
        if (not isInfinite) and totalWaves > 0 and wave >= totalWaves then
            return { decided = true, skip = false, reason = "final_wave" }
        end
        if c.bossAlive == true then
            return { decided = true, skip = false, reason = "boss_alive" }
        end
        if c.piling == true then
            return { decided = true, skip = false, reason = "piling" }
        end

        local maxProg = tonumber(c.maxEnemyProg)
        if not econIsFinite(maxProg) then
            maxProg = 0.0
        end
        local pressure = tonumber(c.pressure)
        if not econIsFinite(pressure) then
            pressure = 0.0
        end
        if maxProg >= 0.72 or pressure >= dangerReach then
            return { decided = true, skip = false, reason = "near_base_pressure" }
        end

        local baseHpFrac = 1.0
        if econIsFinite(c.baseHpFrac) then
            baseHpFrac = c.baseHpFrac
        end
        if baseHpFrac < 0.85 then
            return { decided = true, skip = false, reason = "low_base_hp" }
        end

        local hasFlyers = (c.hasFlyers == true)
        local hasAirCoverage = true
        if c.hasAirCoverage ~= nil then
            hasAirCoverage = (c.hasAirCoverage == true)
        end
        local airMaxProg = tonumber(c.airMaxProg)
        if not econIsFinite(airMaxProg) then
            airMaxProg = 0.0
        end
        if hasFlyers and ((not hasAirCoverage) or airMaxProg >= 0.50) then
            return { decided = true, skip = false, reason = "flyer_danger" }
        end

        return { decided = false }
    end

    -- Exact 22 ActiveNN features: f[1]..f[22] === JS engine/tactics_features.js f[0]..f[21]
    function AI.extractActiveFeatures(ctx, outBuf)
        local f = outBuf or {}
        local c = ctx or EMPTY_LIST

        local isWholeMap = (c.isWholeMap == true)
        local isFullAoe = (c.isFullAoe == true)

        local crowd = tonumber(c.crowd)
        if not econIsFinite(crowd) or crowd < 0.0 then
            crowd = 0.0
        end
        local rawCount = tonumber(c.count)
        if not econIsFinite(rawCount) or rawCount < 0.0 then
            rawCount = 0.0
        end
        local count = rawCount
        if isWholeMap then
            count = math.max(rawCount, crowd)
        end

        local hpAlive = tonumber(c.hpAlive)
        if not econIsFinite(hpAlive) or hpAlive < 0.0 then
            hpAlive = 0.0
        end
        local rawInRangeHp = tonumber(c.inRangeHp)
        if not econIsFinite(rawInRangeHp) or rawInRangeHp < 0.0 then
            rawInRangeHp = 0.0
        end
        local inRangeHp = rawInRangeHp
        if isWholeMap then
            inRangeHp = math.max(rawInRangeHp, hpAlive)
        end

        local teamDps = tonumber(c.teamDps)
        if not econIsFinite(teamDps) or teamDps <= 0.0 then
            teamDps = 1.0
        else
            teamDps = math.max(1.0, teamDps)
        end
        local ttkInRange = inRangeHp / teamDps
        local ttkAlive = hpAlive / teamDps

        local bossInRange = (c.bossInRange == true)
        local bossHpFrac = 0.0
        local bossProg = 0.0
        if bossInRange then
            bossHpFrac = econClamp01(tonumber(c.bossHpFrac) or 0.0)
            bossProg = econClamp01(tonumber(c.bossProg) or 0.0)
        end

        local wave = tonumber(c.wave)
        if not econIsFinite(wave) or wave == 0.0 then
            wave = 1.0
        end
        wave = math.max(1.0, wave)

        local totalWaves = tonumber(c.totalWaves)
        if not econIsFinite(totalWaves) or totalWaves == 0.0 then
            totalWaves = 15.0
        end
        totalWaves = math.max(1.0, totalWaves)

        local isInfinite = (c.isInfinite == true)
        local bossNext = false
        if c.bossNextWave ~= nil then
            bossNext = (c.bossNextWave == true)
        else
            bossNext = AI.isBossNextWave(wave, totalWaves, isInfinite)
        end

        local maxInRangeProg = econClamp01(tonumber(c.maxInRangeProg) or 0.0)
        local nearBase = 0.0
        if (c.nearBase == true) or (maxInRangeProg >= 0.82) then
            nearBase = 1.0
        end
        local mapPressure = maxInRangeProg
        if econIsFinite(c.pressure) then
            mapPressure = econClamp01(c.pressure)
        end
        local baseHpFrac = 1.0
        if econIsFinite(c.baseHpFrac) then
            baseHpFrac = econClamp01(c.baseHpFrac)
        end

        local isStun = (c.isStun == true)
        local isSlow = (c.isSlow == true)
        local isDebuff = (c.isDebuff == true)
        local isNuke = false
        if c.isNuke ~= nil then
            isNuke = (c.isNuke == true)
        else
            isNuke = (not isStun) and (not isSlow) and (not isDebuff)
        end

        local cd = tonumber(c.cd)
        if not econIsFinite(cd) or cd == 0.0 then
            cd = 30.0
        end
        cd = math.max(1.0, cd)

        local held = tonumber(c.held)
        if not econIsFinite(held) or held < 0.0 then
            held = 0.0
        end

        local waveTimeLeft = 15.0
        if econIsFinite(c.waveTimeLeft) then
            waveTimeLeft = math.max(0.0, c.waveTimeLeft)
        end

        -- 1..5 (JS 0..4): Target Cluster & Value in Range
        f[1] = econClamp01(count / 12.0)
        if crowd > 0.0 then
            f[2] = econClamp01(count / crowd)
        else
            f[2] = 0.0
        end
        if hpAlive > 1e-6 then
            f[3] = econClamp01(inRangeHp / hpAlive)
        else
            f[3] = 0.0
        end
        f[4] = econClamp01(ttkInRange / 12.0)
        if (not bossInRange) and (ttkInRange < 1.5) then
            f[5] = econClamp01(1.0 - (ttkInRange / 1.5))
        else
            f[5] = 0.0
        end

        -- 6..9 (JS 5..8): Boss & Lookahead Status
        if bossInRange then
            f[6] = 1.0
        else
            f[6] = 0.0
        end
        f[7] = bossHpFrac
        f[8] = bossProg
        if bossNext and (not bossInRange) and (ttkAlive < 10.0) then
            f[9] = 1.0
        else
            f[9] = 0.0
        end

        -- 10..13 (JS 9..12): Leak Danger & Map Pressure
        f[10] = maxInRangeProg
        f[11] = nearBase
        f[12] = mapPressure
        f[13] = econClamp01(1.0 - baseHpFrac)

        -- 14..18 (JS 13..17): Ability Type & Scope Flags
        if isNuke then
            f[14] = 1.0
        else
            f[14] = 0.0
        end
        if isStun then
            f[15] = 1.0
        else
            f[15] = 0.0
        end
        if isSlow then
            f[16] = 1.0
        else
            f[16] = 0.0
        end
        if isDebuff then
            f[17] = 1.0
        else
            f[17] = 0.0
        end
        if isWholeMap then
            f[18] = 1.0
        elseif isFullAoe then
            f[18] = 0.65
        else
            f[18] = 0.0
        end

        -- 19..22 (JS 18..21): Cooldown Economy & Wave Timing
        f[19] = econClamp01(cd / 120.0)
        f[20] = econClamp01(held / math.max(10.0, cd * 0.5))
        f[21] = econClamp01(cd / math.max(10.0, waveTimeLeft + 15.0))
        if isInfinite then
            f[22] = econClamp01(wave / 60.0)
        else
            f[22] = econClamp01(wave / totalWaves)
        end

        return f
    end

    -- Exact 18 SkipNN features: f[1]..f[18] === JS engine/tactics_features.js f[0]..f[17]
    function AI.extractSkipFeatures(ctx, outBuf)
        local f = outBuf or {}
        local c = ctx or EMPTY_LIST

        local mode = string.lower(tostring(c.mode or "story"))
        local isInfinite = (c.isInfinite == true) or (mode == "infinite")
        local isDungeon = (not isInfinite) and (mode == "dungeon" or mode == "raid" or mode == "legend")
        local isEvent = (not isInfinite) and (not isDungeon) and (mode == "event" or mode == "portal")
        local isStory = (not isInfinite) and (not isDungeon) and (not isEvent)

        local wave = tonumber(c.wave)
        if not econIsFinite(wave) or wave == 0.0 then
            wave = 1.0
        end
        wave = math.max(1.0, wave)

        local defTot = 15.0
        if isEvent then
            defTot = 50.0
        end
        local totalWaves = tonumber(c.totalWaves)
        if not econIsFinite(totalWaves) or totalWaves == 0.0 then
            totalWaves = defTot
        end
        totalWaves = math.max(1.0, totalWaves)

        local bossAlive = (c.bossAlive == true)
        local bossNext = false
        if c.bossNextWave ~= nil then
            bossNext = (c.bossNextWave == true)
        else
            bossNext = AI.isBossNextWave(wave, totalWaves, isInfinite)
        end

        local maxEnemyProg = econClamp01(tonumber(c.maxEnemyProg) or 0.0)
        local activeEnemyCount = tonumber(c.activeEnemyCount)
        if not econIsFinite(activeEnemyCount) or activeEnemyCount < 0.0 then
            activeEnemyCount = 0.0
        end

        local hpAlive = tonumber(c.hpAlive)
        if not econIsFinite(hpAlive) or hpAlive < 0.0 then
            hpAlive = 0.0
        end
        local teamDps = tonumber(c.teamDps)
        if not econIsFinite(teamDps) or teamDps <= 0.0 then
            teamDps = 1.0
        else
            teamDps = math.max(1.0, teamDps)
        end

        local estWaveHp = tonumber(c.estWaveHp)
        if not econIsFinite(estWaveHp) or estWaveHp == 0.0 then
            estWaveHp = math.max(hpAlive, teamDps * 8.0)
        end
        estWaveHp = math.max(1.0, estWaveHp)

        local pressure = maxEnemyProg
        if econIsFinite(c.pressure) then
            pressure = econClamp01(c.pressure)
        end

        local farmCount = tonumber(c.farmCount)
        if not econIsFinite(farmCount) or farmCount < 0.0 then
            farmCount = 0.0
        end
        local unmaxedFarmFrac = econClamp01(tonumber(c.unmaxedFarmFrac) or 0.0)
        local leaksSoFar = tonumber(c.leaksSoFar)
        if not econIsFinite(leaksSoFar) or leaksSoFar < 0.0 then
            leaksSoFar = 0.0
        end
        local baseHpFrac = 1.0
        if econIsFinite(c.baseHpFrac) then
            baseHpFrac = econClamp01(c.baseHpFrac)
        end

        local hasFlyers = (c.hasFlyers == true)
        local hasAirCoverage = true
        if c.hasAirCoverage ~= nil then
            hasAirCoverage = (c.hasAirCoverage == true)
        end
        local airMaxProg = econClamp01(tonumber(c.airMaxProg) or 0.0)

        -- 1..4 (JS 0..3): Game Mode Flags (1-hot)
        if isStory then
            f[1] = 1.0
        else
            f[1] = 0.0
        end
        if isDungeon then
            f[2] = 1.0
        else
            f[2] = 0.0
        end
        if isEvent then
            f[3] = 1.0
        else
            f[3] = 0.0
        end
        if isInfinite then
            f[4] = 1.0
        else
            f[4] = 0.0
        end

        -- 5..8 (JS 4..7): Wave Progression & Boss Lookahead
        if isInfinite then
            f[5] = econClamp01(wave / 60.0)
            f[6] = 1.0
        else
            f[5] = econClamp01(wave / totalWaves)
            f[6] = econClamp01((totalWaves - wave) / 20.0)
        end
        if bossAlive then
            f[7] = 1.0
        else
            f[7] = 0.0
        end
        if bossNext then
            f[8] = 1.0
        else
            f[8] = 0.0
        end

        -- 9..13 (JS 8..12): Active Board Threat & DPS Margin
        f[9] = maxEnemyProg
        f[10] = econClamp01(activeEnemyCount / 25.0)
        f[11] = econClamp01((hpAlive / teamDps) / 15.0)
        f[12] = econClamp01(((teamDps * 12.0) / estWaveHp) / 3.0)
        f[13] = pressure

        -- 14..18 (JS 13..17): Economy, Survival & Air Safety
        f[14] = econClamp01(farmCount / 6.0)
        f[15] = unmaxedFarmFrac
        f[16] = econClamp01(leaksSoFar / 5.0)
        f[17] = baseHpFrac
        if hasFlyers then
            if hasAirCoverage then
                f[18] = airMaxProg
            else
                f[18] = 1.0
            end
        else
            f[18] = 0.0
        end

        return f
    end

    -- Neural Active Ability Inference: returns (shouldCastBool, scoreOrNil, reasonStr)
    function AI.shouldUseActive(ctx)
        local g = AI.checkActiveGuardrails(ctx)
        if g.decided then
            return g.cast, nil, g.reason
        end
        local feat = AI.extractActiveFeatures(ctx, AI._aFeatBuf)
        local score = AI.scoreActive(feat)
        if not econIsFinite(score) then
            return nil, nil, "non_finite"
        end
        local cast = (score > 0.0)
        local why = "ActiveNN hold"
        if cast then
            if ctx and ctx.bossInRange then
                why = "ActiveNN (boss burst)"
            elseif (tonumber(ctx and ctx.count) or 0) >= 6 then
                why = "ActiveNN (crowd value)"
            else
                why = "ActiveNN (optimal cast)"
            end
        end
        return cast, score, why
    end

    -- Neural Wave Skip Inference: returns (shouldSkipBool, scoreOrNil, reasonStr)
    function AI.shouldSkipWave(ctx)
        local g = AI.checkSkipGuardrails(ctx)
        if g.decided then
            return false, nil, g.reason
        end
        local feat = AI.extractSkipFeatures(ctx, AI._sFeatBuf)
        local score = AI.scoreSkip(feat)
        if not econIsFinite(score) then
            return false, nil, "non_finite"
        end
        local doSkip = (score > 0.0)
        local why = "SkipNN hold"
        if doSkip then
            why = "SkipNN (safe speed-skip)"
        end
        return doSkip, score, why
    end

    -- Build live SkipNN context from Match & workspace state
    function AI.buildLiveSkipContext()
        local wave = 0
        if Match and Match.wave then
            local okW, wVal = pcall(Match.wave)
            if okW and tonumber(wVal) then
                wave = tonumber(wVal)
            end
        end
        local isInfinite = (Match and Match.infinite == true)
        local mode = tostring((Match and Match.kind) or "story")
        local totalWaves = tonumber(Match and Match.total) or 15
        if isInfinite then
            totalWaves = 0
        end

        local enemies = (Match and Match.enemies) or EMPTY_LIST
        local bossAlive = false
        local maxEnemyProg = tonumber(Match and Match.front) or 0.0
        local hasFlyers = false
        local airMaxProg = 0.0
        for i = 1, #enemies do
            local e = enemies[i]
            if e then
                local pr = tonumber(e.prog) or 0.0
                if pr > maxEnemyProg then
                    maxEnemyProg = pr
                end
                if e.boss then
                    bossAlive = true
                end
                if e.fly and (tonumber(e.hp) or 0.0) > 0.0 then
                    hasFlyers = true
                    if pr > airMaxProg then
                        airMaxProg = pr
                    end
                end
            end
        end
        if (tonumber(Match and Match.airFar) or 0.0) > airMaxProg and hasFlyers then
            airMaxProg = tonumber(Match.airFar) or airMaxProg
        end

        local farmCount = 0
        local unmaxedFarms = 0
        local hasAirCoverage = false
        local mineList = (Match and Match.mine) or EMPTY_LIST
        for i = 1, #mineList do
            local m = mineList[i]
            local mst = m and m:FindFirstChild("_stats")
            local idObj = mst and mst:FindFirstChild("id")
            local id = idObj and idObj.Value
            if id then
                if Units and Units.isFarm and Units.isFarm(id) then
                    farmCount = farmCount + 1
                    local upgObj = mst:FindFirstChild("upgrade")
                    local lvl = (upgObj and tonumber(upgObj.Value)) or 0
                    local eRows = getEnrichedEconRows(id)
                    local maxL = (eRows and eRows.max) or 0
                    if maxL > 0 and lvl < maxL then
                        unmaxedFarms = unmaxedFarms + 1
                    end
                elseif not hasAirCoverage and Match and Match.canAir then
                    local okA, aV = pcall(Match.canAir, m)
                    if okA and aV == true then
                        hasAirCoverage = true
                    end
                end
            end
        end

        local unmaxedFarmFrac = 0.0
        if farmCount > 0 then
            unmaxedFarmFrac = unmaxedFarms / farmCount
        end

        local hpAlive = tonumber(Match and Match.hpAlive) or 0.0
        local teamDps = math.max(1.0, tonumber(Match and Match.teamDps) or 1.0)
        local pressure = tonumber(Match and Match.pressure) or maxEnemyProg
        local dangerReach = tonumber(Config and Config.dangerReach) or 0.72
        if dangerReach > 0.72 then
            dangerReach = 0.72
        end
        local baseHpFrac = AI.getBaseHpFrac()

        return {
            mode = mode,
            isInfinite = isInfinite,
            wave = wave,
            totalWaves = totalWaves,
            bossAlive = bossAlive,
            piling = (Match and Match.piling == true),
            maxEnemyProg = maxEnemyProg,
            activeEnemyCount = #enemies,
            hpAlive = hpAlive,
            teamDps = teamDps,
            estWaveHp = math.max(hpAlive, teamDps * 8.0),
            pressure = pressure,
            dangerReach = dangerReach,
            farmCount = farmCount,
            unmaxedFarmFrac = unmaxedFarmFrac,
            leaksSoFar = tonumber(AI._leakEvents) or 0,
            baseHpFrac = baseHpFrac,
            hasFlyers = hasFlyers,
            hasAirCoverage = hasAirCoverage,
            airMaxProg = airMaxProg,
        }
    end

    -- ========================================================================
    -- Stage 7: Neural AI Team Planner (v2.38 AI) — TeamNN (34d) & Beam/Swap Search
    -- Exact 1-to-1 pure Lua 5.1 / Luau mirror of engine/team_features.js
    -- ========================================================================
    local function teamClamp(x, lo, hi)
        local n = tonumber(x)
        if not econIsFinite(n) then
            return lo
        end
        if n < lo then
            return lo
        end
        if n > hi then
            return hi
        end
        return n
    end

    local function teamClamp01(x)
        return teamClamp(x, 0.0, 1.0)
    end

    local function teamFiniteOr(x, defVal)
        local n = tonumber(x)
        if econIsFinite(n) then
            return n
        end
        return defVal
    end

    local function teamPositiveOr(x, defVal)
        local n = tonumber(x)
        if econIsFinite(n) and n ~= 0.0 then
            return n
        end
        return defVal
    end

    local function teamSumTopK(vals, k)
        local n = #vals
        if n == 0 or k <= 0 then
            return 0.0
        end
        local used = {}
        local total = 0.0
        local lim = k
        if n < lim then
            lim = n
        end
        for pick = 1, lim do
            local bestIdx = 0
            local bestVal = -1.0
            for i = 1, n do
                if not used[i] and vals[i] > bestVal then
                    bestVal = vals[i]
                    bestIdx = i
                end
            end
            if bestIdx <= 0 or bestVal <= 0.0 then
                break
            end
            used[bestIdx] = true
            total = total + bestVal
        end
        return total
    end

    local _tkSortBuf = { 0, 0, 0, 0, 0, 0 }
    local function teamIntKeyFromIdx(idxs)
        local len = #idxs
        if len == 0 then
            return 0
        end
        if len == 1 then
            return idxs[1]
        end
        local k = 0
        for i = 1, len do
            local v = idxs[i]
            local j = i - 1
            while j >= 1 and _tkSortBuf[j] > v do
                _tkSortBuf[j + 1] = _tkSortBuf[j]
                j = j - 1
            end
            _tkSortBuf[j + 1] = v
        end
        for i = 1, len do
            k = k * 64 + _tkSortBuf[i]
        end
        return k
    end

    local function teamKeyFromIdx(idxs)
        local len = #idxs
        if len == 0 then
            return ""
        end
        if len == 1 then
            return tostring(idxs[1])
        end
        for i = 1, len do
            local v = idxs[i]
            local j = i - 1
            while j >= 1 and _tkSortBuf[j] > v do
                _tkSortBuf[j + 1] = _tkSortBuf[j]
                j = j - 1
            end
            _tkSortBuf[j + 1] = v
        end
        if len == 2 then
            return _tkSortBuf[1] .. "," .. _tkSortBuf[2]
        elseif len == 3 then
            return _tkSortBuf[1] .. "," .. _tkSortBuf[2] .. "," .. _tkSortBuf[3]
        elseif len == 4 then
            return _tkSortBuf[1] .. "," .. _tkSortBuf[2] .. "," .. _tkSortBuf[3] .. "," .. _tkSortBuf[4]
        elseif len == 5 then
            return _tkSortBuf[1] .. "," .. _tkSortBuf[2] .. "," .. _tkSortBuf[3] .. "," .. _tkSortBuf[4] .. "," .. _tkSortBuf[5]
        elseif len == 6 then
            return _tkSortBuf[1] .. "," .. _tkSortBuf[2] .. "," .. _tkSortBuf[3] .. "," .. _tkSortBuf[4] .. "," .. _tkSortBuf[5] .. "," .. _tkSortBuf[6]
        end
        local parts = {}
        for i = 1, len do
            parts[i] = tostring(_tkSortBuf[i])
        end
        return table.concat(parts, ",")
    end

    function AI.scoreTeam(feat)
        local out = forwardMLP(AI.TEAM_NET, feat)
        return out[1]
    end

    -- Exact 1-to-1 mirror of engine/team_features.js normalizeMode (fast-paths already normalized ctx)
    function AI.normalizeTeamMode(ctx)
        if type(ctx) == "table" and ctx._normalized == true then
            return ctx
        end
        local c = ctx or EMPTY_LIST
        local rawM = c.mode
        if rawM == nil or rawM == "" then
            rawM = c.gm
        end
        if rawM == nil or rawM == "" then
            rawM = "story_15"
        end
        local m = string.lower(tostring(rawM))

        local isInfinite = (c.isInfinite == true) or (m == "infinite") or (m == "endless")
        local isDungeon = (not isInfinite) and (m == "dungeon_15" or m == "dungeon" or m == "raid" or m == "legend")
        local isEvent = (not isInfinite) and (not isDungeon) and (m == "event_50" or m == "event" or m == "portal")
        local isStory = (not isInfinite) and (not isDungeon) and (not isEvent)

        local defWaves = 15.0
        if isInfinite then
            defWaves = 60.0
        elseif isEvent then
            defWaves = 50.0
        end
        local totalWaves = math.max(1.0, teamPositiveOr(c.totalWaves, defWaves))

        local hasHills = true
        if c.hasHills ~= nil then
            hasHills = (c.hasHills == true)
        elseif c.hillCap ~= nil then
            local hcNum = tonumber(c.hillCap)
            hasHills = (econIsFinite(hcNum) and hcNum > 0.0)
        end

        local hillCap = 0.0
        if hasHills then
            hillCap = math.max(0.0, teamFiniteOr(c.hillCap, 6.0))
        end

        local allowFarm = true
        if c.allowFarm ~= nil then
            allowFarm = (c.allowFarm == true)
        end
        local allowBuff = true
        if c.allowBuff ~= nil then
            allowBuff = (c.allowBuff == true)
        end

        local maxSlots = math.floor(teamPositiveOr(c.maxSlots, 6))
        if maxSlots < 1 then
            maxSlots = 1
        elseif maxSlots > 6 then
            maxSlots = 6
        end

        local startYen = math.max(100.0, teamPositiveOr(c.startYen, 650.0))
        local costScale = teamClamp(teamFiniteOr(c.costScale, 1.0), 0.4, 3.0)
        local hpScale = teamClamp(teamFiniteOr(c.hpScale, 1.0), 0.3, 5.0)
        local speedScale = teamClamp(teamFiniteOr(c.speedScale, 1.0), 0.5, 2.5)
        local airThreat = teamClamp01(teamFiniteOr(c.airThreat, 0.25))
        local regenThreat = teamClamp01(teamFiniteOr(c.regenThreat, 0.0))
        local shieldThreat = teamClamp01(teamFiniteOr(c.shieldThreat, 0.0))
        local livesNorm = teamClamp01(teamFiniteOr(c.livesNorm, 0.75))
        local noCC = (c.noCC == true)

        local modeName = "story_15"
        if isInfinite then
            modeName = "infinite"
        elseif isDungeon then
            modeName = "dungeon_15"
        elseif isEvent then
            modeName = "event_50"
        end

        return {
            _normalized = true,
            mode = modeName,
            isStory = isStory,
            isDungeon = isDungeon,
            isEvent = isEvent,
            isInfinite = isInfinite,
            totalWaves = totalWaves,
            hasHills = hasHills,
            hillCap = hillCap,
            allowFarm = allowFarm,
            allowBuff = allowBuff,
            maxSlots = maxSlots,
            startYen = startYen,
            costScale = costScale,
            hpScale = hpScale,
            speedScale = speedScale,
            airThreat = airThreat,
            regenThreat = regenThreat,
            shieldThreat = shieldThreat,
            livesNorm = livesNorm,
            noCC = noCC
        }
    end

    -- Exact 1-to-1 mirror of engine/team_features.js normalizeUnit
    function AI.normalizeTeamUnit(raw)
        local u = raw or EMPTY_LIST
        local isFarm = (u.isFarm == true)
        local isBuffer = (not isFarm) and (u.isBuffer == true)
        local isAttacker = (not isFarm) and (not isBuffer)

        local cap = math.max(1, math.floor(teamPositiveOr(u.cap, 3)))
        local cost = math.max(50.0, teamPositiveOr(u.cost, 500.0))
        local totalCost = math.max(cost, teamPositiveOr(u.totalCost, cost * 10.0))

        local maxDps = 0.0
        local earlyDps = 0.0
        local teamDps = 0.0
        local bossDps = 0.0
        if isAttacker then
            maxDps = math.max(0.0, teamFiniteOr(u.maxDps, 0.0))
            earlyDps = math.max(0.0, teamFiniteOr(u.earlyDps, maxDps * 0.14))
            teamDps = math.max(0.0, teamFiniteOr(u.teamDps, maxDps * cap))
            bossDps = math.max(0.0, teamFiniteOr(u.bossDps, teamDps))
        end

        local farmIncome = 0.0
        if isFarm then
            farmIncome = math.max(0.0, teamFiniteOr(u.farmIncome, 0.0))
        end

        local buffPower = 0.0
        local buffKind = "none"
        if isBuffer then
            buffPower = teamClamp(teamFiniteOr(u.buffPower, 0.0), 0.0, 1.5)
            local rawBK = u.buffKind
            if rawBK == nil or rawBK == "" then
                rawBK = "all"
            end
            buffKind = string.lower(tostring(rawBK))
        end

        local rawDT = u.dmgType
        if rawDT == nil or rawDT == "" then
            rawDT = "physical"
        end
        local dmgType = string.lower(tostring(rawDT))

        local isPhys = false
        if u.isPhys ~= nil then
            isPhys = (u.isPhys == true)
        else
            isPhys = (dmgType == "physical" or dmgType == "hybrid" or dmgType == "all")
        end
        local isMagic = false
        if u.isMagic ~= nil then
            isMagic = (u.isMagic == true)
        else
            isMagic = (dmgType == "magic" or dmgType == "hybrid" or dmgType == "all")
        end

        local isHybrid = (u.isHybrid == true)
        local isHill = (u.isHill == true) and (not isHybrid)
        local canAir = isAttacker and (u.canAir == true)
        local airEarly = canAir and (u.airEarly == true)
        local hasBleed = isAttacker and (u.hasBleed == true)
        local hasCC = isAttacker and (u.hasCC == true)
        local ccScore = 0.0
        if hasCC then
            ccScore = teamClamp01(teamFiniteOr(u.ccScore, 0.5))
        end
        local hasShieldBreak = isAttacker and (u.hasShieldBreak == true)
        local isFullAoe = isAttacker and (u.isFullAoe == true)
        local defAoe = 1.25
        if isFullAoe then
            defAoe = 2.8
        end
        local aoeMul = teamClamp(teamFiniteOr(u.aoeMul, defAoe), 0.5, 4.0)
        local range = teamClamp(teamFiniteOr(u.range, 22.0), 4.0, 80.0)
        local elemMul = teamClamp(teamFiniteOr(u.elemMul, 1.0), 0.25, 2.5)

        local fusionGroup = ""
        if u.fusionGroup ~= nil then
            fusionGroup = tostring(u.fusionGroup)
        end
        local isFusionPart = (u.isFusionPart == true) or (#fusionGroup > 0)
        local isIdol = (u.isIdol == true)
        local required = (u.required == true)

        local idVal = u.id
        if idVal == nil or idVal == "" then
            idVal = u.unit_id
        end
        local idStr = ""
        if idVal ~= nil then
            idStr = tostring(idVal)
        end

        local uuidStr = ""
        if u.uuid ~= nil then
            uuidStr = tostring(u.uuid)
        end

        local roleStr = u.role
        if roleStr == nil or roleStr == "" then
            if isFarm then
                roleStr = "farm"
            elseif isBuffer then
                roleStr = "buffer"
            else
                roleStr = "carry"
            end
        else
            roleStr = tostring(roleStr)
        end

        local rawRef = u._raw
        if rawRef == nil then
            rawRef = raw
        end

        return {
            id = idStr,
            uuid = uuidStr,
            role = roleStr,
            isFarm = isFarm,
            isBuffer = isBuffer,
            isAttacker = isAttacker,
            cap = cap,
            cost = cost,
            totalCost = totalCost,
            maxDps = maxDps,
            earlyDps = earlyDps,
            teamDps = teamDps,
            bossDps = bossDps,
            farmIncome = farmIncome,
            buffPower = buffPower,
            buffKind = buffKind,
            dmgType = dmgType,
            isPhys = isPhys,
            isMagic = isMagic,
            isHybrid = isHybrid,
            isHill = isHill,
            canAir = canAir,
            airEarly = airEarly,
            hasBleed = hasBleed,
            hasCC = hasCC,
            ccScore = ccScore,
            hasShieldBreak = hasShieldBreak,
            isFullAoe = isFullAoe,
            aoeMul = aoeMul,
            range = range,
            elemMul = elemMul,
            fusionGroup = fusionGroup,
            isFusionPart = isFusionPart,
            isIdol = isIdol,
            required = required,
            _raw = rawRef
        }
    end

    -- Exact 1-to-1 mirror of engine/team_features.js computePoolStats
    function AI.computePoolStats(pool, rawCtx)
        local c = AI.normalizeTeamMode(rawCtx)
        local atkDps = {}
        local bossDps = {}
        local earlyAfford = {}
        local earlyAll = {}
        local farmIncs = {}
        local airDps = {}
        local fusionCounts = {}

        local hasPoolFarm = false
        local hasPoolPhysBuff = false
        local hasPoolMagicBuff = false
        local hasPoolAllBuff = false
        local hasPoolBleed = false
        local hasPoolCC = false
        local hasPoolAir = false
        local hasPoolShieldBreak = false
        local hasPoolFusion = false
        local eligibleCount = 0

        local nPool = 0
        if pool then
            nPool = #pool
        end

        for i = 1, nPool do
            local u = pool[i]
            if u then
                local skip = false
                if u.isFarm and (not c.allowFarm) and (not u.required) then
                    skip = true
                elseif u.isBuffer and (not c.allowBuff) and (not u.required) then
                    skip = true
                elseif u.isHill and (not c.hasHills) and (not u.required) then
                    skip = true
                end
                if not skip then
                    eligibleCount = eligibleCount + 1
                    if u.isFarm then
                        hasPoolFarm = true
                        farmIncs[#farmIncs + 1] = u.farmIncome
                    elseif u.isBuffer then
                        if u.buffKind == "physical" then
                            hasPoolPhysBuff = true
                        elseif u.buffKind == "magic" then
                            hasPoolMagicBuff = true
                        else
                            hasPoolAllBuff = true
                        end
                    else
                        local effDps = u.teamDps * u.elemMul
                        local effBoss = u.bossDps * u.elemMul
                        atkDps[#atkDps + 1] = effDps
                        bossDps[#bossDps + 1] = effBoss
                        local earlyVal = u.earlyDps * u.elemMul
                        earlyAll[#earlyAll + 1] = earlyVal
                        if (u.cost * c.costScale) <= (c.startYen * 1.15) then
                            earlyAfford[#earlyAfford + 1] = earlyVal
                        end
                        if u.canAir then
                            hasPoolAir = true
                            airDps[#airDps + 1] = effDps
                        end
                        if u.hasBleed then
                            hasPoolBleed = true
                        end
                        if u.hasCC and u.ccScore > 0.05 then
                            hasPoolCC = true
                        end
                        if u.hasShieldBreak then
                            hasPoolShieldBreak = true
                        end
                        if u.isFusionPart and u.fusionGroup and #u.fusionGroup > 0 then
                            local fg = u.fusionGroup
                            local cnt = (fusionCounts[fg] or 0) + 1
                            fusionCounts[fg] = cnt
                            if cnt >= 2 then
                                hasPoolFusion = true
                            end
                        end
                    end
                end
            end
        end

        local refTeamDps = math.max(1.0, teamSumTopK(atkDps, 4))
        local refBossDps = math.max(1.0, teamSumTopK(bossDps, 3))
        local refEarlyRaw = 0.0
        if #earlyAfford > 0 then
            refEarlyRaw = teamSumTopK(earlyAfford, 2)
        else
            refEarlyRaw = teamSumTopK(earlyAll, 2)
        end
        local refEarlyDps = math.max(1.0, refEarlyRaw)
        local refFarmIncome = math.max(1.0, teamSumTopK(farmIncs, 2))
        local refAirDps = math.max(1.0, teamSumTopK(airDps, 2))

        return {
            eligibleCount = eligibleCount,
            refTeamDps = refTeamDps,
            refBossDps = refBossDps,
            refEarlyDps = refEarlyDps,
            refFarmIncome = refFarmIncome,
            refAirDps = refAirDps,
            hasPoolFarm = hasPoolFarm,
            hasPoolPhysBuff = hasPoolPhysBuff,
            hasPoolMagicBuff = hasPoolMagicBuff,
            hasPoolAllBuff = hasPoolAllBuff,
            hasPoolBleed = hasPoolBleed,
            hasPoolCC = hasPoolCC,
            hasPoolAir = hasPoolAir,
            hasPoolShieldBreak = hasPoolShieldBreak,
            hasPoolFusion = hasPoolFusion
        }
    end

    -- Exact 34 TeamNN features: f[1]..f[34] === JS engine/team_features.js f[0]..f[33]
    function AI.extractTeamFeatures(team, rawCtx, poolStats, outBuf)
        local f = outBuf or {}
        local c = AI.normalizeTeamMode(rawCtx)
        local ps = poolStats
        if not ps then
            ps = AI.computePoolStats(team, c)
        end

        local n = 0
        if team then
            n = #team
        end

        local attackerCount = 0
        local farmCount = 0
        local bufferCount = 0
        local totalHillCopies = 0
        local totalFarmIncome = 0.0
        local totalUpgradeCost = 0.0
        local hasIdol = false

        local bestPhysBuff = 0.0
        local bestMagicBuff = 0.0
        local bestAllBuff = 0.0
        local sumAllBuffPower = 0.0

        local hasCompleteFusion = false
        local hasHalfFusion = false

        for i = 1, n do
            local u = team[i]
            if u then
                totalUpgradeCost = totalUpgradeCost + (u.totalCost * u.cap)
                if u.isIdol then
                    hasIdol = true
                end
                if u.isFarm then
                    farmCount = farmCount + 1
                    totalFarmIncome = totalFarmIncome + u.farmIncome
                elseif u.isBuffer then
                    bufferCount = bufferCount + 1
                    sumAllBuffPower = sumAllBuffPower + u.buffPower
                    if u.buffKind == "physical" then
                        if u.buffPower > bestPhysBuff then
                            bestPhysBuff = u.buffPower
                        end
                    elseif u.buffKind == "magic" then
                        if u.buffPower > bestMagicBuff then
                            bestMagicBuff = u.buffPower
                        end
                    else
                        if u.buffPower > bestAllBuff then
                            bestAllBuff = u.buffPower
                        end
                    end
                else
                    attackerCount = attackerCount + 1
                    if u.isHill then
                        totalHillCopies = totalHillCopies + u.cap
                    end
                    if u.isFusionPart and u.fusionGroup and #u.fusionGroup > 0 then
                        hasHalfFusion = true
                        for j = i + 1, n do
                            local v = team[j]
                            if v and v.isAttacker and v.isFusionPart and v.fusionGroup == u.fusionGroup then
                                hasCompleteFusion = true
                            end
                        end
                    end
                end
            end
        end

        local hillScale = 1.0
        local hillOverflow = 0.0
        if totalHillCopies > 0 then
            if (not c.hasHills) or c.hillCap <= 0.0 then
                hillScale = 0.0
                hillOverflow = 1.0
            elseif totalHillCopies > c.hillCap then
                hillScale = c.hillCap / totalHillCopies
                hillOverflow = teamClamp01((totalHillCopies - c.hillCap) / totalHillCopies)
            end
        end

        local rawTeamDps = 0.0
        local buffedTeamDps = 0.0
        local buffedBossDps = 0.0
        local buffedAirDps = 0.0
        local earlyAirShare = 0.0
        local physRawDps = 0.0
        local magicRawDps = 0.0
        local weightedAoe = 0.0
        local weightedRange = 0.0
        local weightedElem = 0.0
        local totalWeight = 0.0

        local minAtkCost = 1e9
        local earlyAffordDps = 0.0
        local earlyBestFallback = 0.0

        local hasBleed = false
        local bleedDpsShare = 0.0
        local shieldBreakDps = 0.0
        local ccUnitCount = 0
        local bestCcScore = 0.0
        local secondCcScore = 0.0

        for i = 1, n do
            local u = team[i]
            if u and u.isAttacker then
                local hMul = 1.0
                if u.isHill then
                    hMul = hillScale
                end
                local unitCostScaled = u.cost * c.costScale
                if unitCostScaled < minAtkCost then
                    minAtkCost = unitCostScaled
                end

                local inCompleteFusion = false
                if hasCompleteFusion and u.isFusionPart and u.fusionGroup and #u.fusionGroup > 0 then
                    for j = 1, n do
                        if j ~= i and team[j] and team[j].isAttacker and team[j].isFusionPart and team[j].fusionGroup == u.fusionGroup then
                            inCompleteFusion = true
                            break
                        end
                    end
                end
                local fusionDpsMul = 1.0
                local fusionBossMul = 1.0
                if inCompleteFusion then
                    fusionDpsMul = 1.85
                    fusionBossMul = 2.00
                end

                local baseDps = u.teamDps * u.elemMul * hMul * fusionDpsMul
                local baseBoss = u.bossDps * u.elemMul * hMul * fusionBossMul

                local typeBonus = 0.0
                if u.isPhys and bestPhysBuff > typeBonus then
                    typeBonus = bestPhysBuff
                end
                if u.isMagic and bestMagicBuff > typeBonus then
                    typeBonus = bestMagicBuff
                end
                local allFactor = 1.0
                if typeBonus > 0.0 then
                    allFactor = 0.45
                end
                local allAdd = bestAllBuff * allFactor
                local totalBuffBonus = math.min(1.35, typeBonus + allAdd)
                local buffMul = 1.0 + totalBuffBonus

                local bDps = baseDps * buffMul
                local bBoss = baseBoss * buffMul

                rawTeamDps = rawTeamDps + baseDps
                buffedTeamDps = buffedTeamDps + bDps
                buffedBossDps = buffedBossDps + bBoss

                if u.isPhys then
                    physRawDps = physRawDps + baseDps
                end
                if u.isMagic then
                    magicRawDps = magicRawDps + baseDps
                end

                local eVal = u.earlyDps * u.elemMul * hMul
                if eVal > earlyBestFallback then
                    earlyBestFallback = eVal
                end
                if unitCostScaled <= (c.startYen * 1.02) then
                    earlyAffordDps = earlyAffordDps + eVal
                elseif unitCostScaled <= (c.startYen * 1.35) then
                    earlyAffordDps = earlyAffordDps + (eVal * 0.45)
                end

                if u.canAir or inCompleteFusion then
                    buffedAirDps = buffedAirDps + bDps
                    if u.airEarly then
                        earlyAirShare = earlyAirShare + bDps
                    end
                end

                if u.hasBleed and hMul > 0.0 then
                    hasBleed = true
                    bleedDpsShare = bleedDpsShare + bDps
                end
                if u.hasShieldBreak and hMul > 0.0 then
                    shieldBreakDps = shieldBreakDps + bDps
                end
                if u.hasCC and u.ccScore > 0.05 and hMul > 0.0 then
                    ccUnitCount = ccUnitCount + 1
                    if u.ccScore > bestCcScore then
                        secondCcScore = bestCcScore
                        bestCcScore = u.ccScore
                    elseif u.ccScore > secondCcScore then
                        secondCcScore = u.ccScore
                    end
                end

                local w = math.max(1e-6, bDps)
                local aoeScore = 0.0
                if u.isFullAoe then
                    aoeScore = 1.0
                else
                    aoeScore = teamClamp01((u.aoeMul - 0.8) / 2.2)
                end
                weightedAoe = weightedAoe + (aoeScore * w)
                weightedRange = weightedRange + (u.range * w)
                weightedElem = weightedElem + (u.elemMul * w)
                totalWeight = totalWeight + w
            end
        end

        local buffSynergyRatio = 0.0
        if rawTeamDps > 1e-6 then
            buffSynergyRatio = teamClamp01((buffedTeamDps - rawTeamDps) / rawTeamDps)
        end

        local buffWaste = 0.0
        if bufferCount > 0 and sumAllBuffPower > 1e-6 then
            local effPhysShare = 0.0
            local effMagicShare = 0.0
            if rawTeamDps > 1e-6 then
                effPhysShare = teamClamp01(physRawDps / rawTeamDps)
                effMagicShare = teamClamp01(magicRawDps / rawTeamDps)
            end
            local realizedBuffPower = (bestPhysBuff * effPhysShare) + (bestMagicBuff * effMagicShare) + (bestAllBuff * 0.85)
            buffWaste = teamClamp01(1.0 - (realizedBuffPower / sumAllBuffPower))
        end

        local cheapestAtkAffordable = 0.0
        if attackerCount > 0 then
            cheapestAtkAffordable = teamClamp01(c.startYen / math.max(100.0, minAtkCost))
        end
        local earlySurvivalNorm = teamClamp01(
            ((earlyAffordDps / math.max(1.0, ps.refEarlyDps)) * 0.85) +
            ((earlyBestFallback / math.max(1.0, ps.refEarlyDps)) * 0.15 * cheapestAtkAffordable)
        )

        local effWaves = c.totalWaves
        if c.isInfinite then
            effWaves = 55.0
        end
        local baseMatchBudget = c.startYen + (effWaves * (520.0 + (38.0 * effWaves)))
        local activeFarmWaves = math.max(0.0, effWaves - 4.0) * 0.72
        local projectedBudget = baseMatchBudget + (totalFarmIncome * activeFarmWaves)
        local costDiscount = 1.0
        if hasIdol then
            costDiscount = 0.85
        end
        local teamUpgradeNeed = math.max(1.0, totalUpgradeCost * costDiscount * c.costScale)
        local econAffordability = teamClamp01(projectedBudget / teamUpgradeNeed)

        local airDpsNorm = 0.0
        if ps.hasPoolAir then
            airDpsNorm = teamClamp01(buffedAirDps / (1.5 * math.max(1.0, ps.refAirDps)))
        end
        local airEarlyFactor = 0.0
        if buffedAirDps > 1e-6 then
            airEarlyFactor = teamClamp01(0.55 + (0.45 * teamClamp01(earlyAirShare / buffedAirDps)))
        end
        local airSatisfaction = teamClamp01(airDpsNorm * 1.35 * airEarlyFactor)
        local airGap = 0.0
        if ps.hasPoolAir then
            airGap = teamClamp01(c.airThreat * (1.0 - airSatisfaction))
        else
            airGap = teamClamp01(c.airThreat * 0.35)
        end

        local regenCovered = 0.0
        if hasBleed then
            regenCovered = teamClamp01(0.75 + (0.25 * teamClamp01(bleedDpsShare / math.max(1.0, buffedTeamDps * 0.2))))
        end
        local regenPoolFactor = 0.35
        if ps.hasPoolBleed then
            regenPoolFactor = 1.0
        end
        local regenGap = c.regenThreat * (1.0 - regenCovered) * regenPoolFactor

        local shieldCoverage = 0.0
        if buffedTeamDps > 1e-6 then
            shieldCoverage = teamClamp01((shieldBreakDps / buffedTeamDps) * 2.2)
        end
        local shieldPoolFactor = 0.35
        if ps.hasPoolShieldBreak then
            shieldPoolFactor = 1.0
        end
        local shieldGap = c.shieldThreat * (1.0 - shieldCoverage) * shieldPoolFactor

        local rawCcUtility = teamClamp01(bestCcScore + (0.35 * secondCcScore))
        local ccUtilityNorm = rawCcUtility
        if c.noCC then
            ccUtilityNorm = 0.0
        end

        local aoeCoverageNorm = 0.0
        local rangeCoverageNorm = 0.0
        local avgElemMul = 1.0
        if totalWeight > 1e-6 then
            aoeCoverageNorm = teamClamp01(weightedAoe / totalWeight)
            rangeCoverageNorm = teamClamp01((weightedRange / totalWeight) / 42.0)
            avgElemMul = weightedElem / totalWeight
        end
        local avgElemMulNorm = teamClamp01((avgElemMul - 0.5) / 1.5)

        local dominantTypeShare = 0.0
        if rawTeamDps > 1e-6 then
            dominantTypeShare = teamClamp01(math.max(physRawDps, magicRawDps) / rawTeamDps)
        end
        local typeHarmony = 0.5
        if bufferCount > 0 then
            typeHarmony = dominantTypeShare
        end
        local ccOverstackPen = 0.0
        if ccUnitCount > 2 then
            ccOverstackPen = 0.25
        end
        local idolTerm = 0.0
        if hasIdol then
            idolTerm = 1.0
        end
        local utilitySupportSynergy = teamClamp01(
            (0.45 * typeHarmony) +
            (0.25 * idolTerm) +
            (0.30 * (1.0 - buffWaste)) -
            ccOverstackPen
        )

        local elig = c.maxSlots
        if ps.eligibleCount > 0 then
            elig = ps.eligibleCount
        end
        local targetFill = math.max(1, math.min(c.maxSlots, elig))

        -- 1..4 (JS 0..3): Mode 1-hot
        if c.isStory then
            f[1] = 1.0
        else
            f[1] = 0.0
        end
        if c.isDungeon then
            f[2] = 1.0
        else
            f[2] = 0.0
        end
        if c.isEvent then
            f[3] = 1.0
        else
            f[3] = 0.0
        end
        if c.isInfinite then
            f[4] = 1.0
        else
            f[4] = 0.0
        end

        -- 5..10 (JS 4..9): Stage / Map Threats & Constraints
        if c.isInfinite then
            f[5] = 1.0
        else
            f[5] = teamClamp01(c.totalWaves / 50.0)
        end
        f[6] = c.airThreat
        f[7] = c.regenThreat
        f[8] = c.shieldThreat
        if not c.hasHills then
            f[9] = 1.0
        else
            f[9] = teamClamp01(1.0 - (c.hillCap / 8.0))
        end
        f[10] = teamClamp01((0.65 * (1.0 - c.livesNorm)) + (0.35 * teamClamp01((c.speedScale - 0.85) / 0.85)))

        -- 11..16 (JS 10..15): Core Combat Power & Buff-Hub Synergy
        f[11] = teamClamp01(rawTeamDps / (1.35 * ps.refTeamDps))
        f[12] = teamClamp01(buffedTeamDps / (2.25 * ps.refTeamDps))
        f[13] = buffSynergyRatio
        f[14] = buffWaste
        f[15] = teamClamp01(buffedBossDps / (2.25 * ps.refBossDps))
        f[16] = aoeCoverageNorm

        -- 17..21 (JS 16..20): Economy, Early Waves & Cost Curve
        f[17] = earlySurvivalNorm
        f[18] = cheapestAtkAffordable
        f[19] = teamClamp01(farmCount / 2.0)
        if ps.hasPoolFarm then
            f[20] = teamClamp01(totalFarmIncome / ps.refFarmIncome)
        else
            f[20] = 0.0
        end
        f[21] = econAffordability

        -- 22..27 (JS 21..26): Threat-Matched Utility Coverage
        f[22] = airDpsNorm
        f[23] = teamClamp01(airGap)
        f[24] = teamClamp01(regenGap)
        f[25] = teamClamp01(shieldGap)
        f[26] = ccUtilityNorm
        f[27] = rangeCoverageNorm

        -- 28..34 (JS 27..33): Composition Structure, Constraints & Special Synergies
        f[28] = teamClamp01(attackerCount / 6.0)
        f[29] = teamClamp01(bufferCount / 2.0)
        f[30] = hillOverflow
        f[31] = teamClamp01(n / targetFill)
        f[32] = avgElemMulNorm
        if hasCompleteFusion then
            f[33] = 1.0
        elseif hasHalfFusion then
            f[33] = 0.20
        else
            f[33] = 0.0
        end
        f[34] = utilitySupportSynergy

        return f
    end

    -- Exact 1-to-1 mirror of engine/team_features.js filterAndDedupPool (preserves insertion order)
    function AI.filterAndDedupPool(rawPool, rawCtx)
        local c = AI.normalizeTeamMode(rawCtx)
        local order = {}
        local byId = {}
        local nRaw = 0
        if rawPool then
            nRaw = #rawPool
        end
        for i = 1, nRaw do
            local u = AI.normalizeTeamUnit(rawPool[i])
            if u.id == "" then
                u.id = "u_" .. tostring(i - 1)
            end
            local skip = false
            if u.isFarm and (not c.allowFarm) and (not u.required) then
                skip = true
            elseif u.isBuffer and (not c.allowBuff) and (not u.required) then
                skip = true
            elseif u.isHill and (not c.hasHills) and (not u.required) then
                skip = true
            end
            if not skip then
                local prev = byId[u.id]
                if not prev then
                    byId[u.id] = u
                    order[#order + 1] = u.id
                else
                    local prevReq = 0.0
                    if prev.required then
                        prevReq = 1e12
                    end
                    local curReq = 0.0
                    if u.required then
                        curReq = 1e12
                    end
                    local prevScore = prevReq + (prev.teamDps * prev.elemMul) + (prev.farmIncome * 10.0) + (prev.buffPower * 1e6)
                    local curScore = curReq + (u.teamDps * u.elemMul) + (u.farmIncome * 10.0) + (u.buffPower * 1e6)
                    if curScore > prevScore then
                        byId[u.id] = u
                    end
                end
            end
        end
        local out = {}
        for i = 1, #order do
            out[i] = byId[order[i]]
        end
        return out
    end

    -- Exact 1-to-1 mirror of engine/team_features.js buildShortlist (with deterministic stable tie-break)
    function AI.buildTeamShortlist(pool, c, maxShortlist)
        local limit = maxShortlist or 28
        if #pool <= limit then
            local copy = {}
            for i = 1, #pool do
                copy[i] = pool[i]
            end
            return copy
        end

        local picked = {}
        local out = {}
        local function add(u)
            if (not u) or picked[u.id] or (#out >= limit) then
                return
            end
            picked[u.id] = true
            out[#out + 1] = u
        end

        local function addTopBy(filterFn, scoreFn, count)
            local sub = {}
            for i = 1, #pool do
                local u = pool[i]
                if (not picked[u.id]) and filterFn(u) then
                    sub[#sub + 1] = { u = u, s = scoreFn(u), ord = i }
                end
            end
            table.sort(sub, function(a, b)
                if a.s ~= b.s then
                    return a.s > b.s
                end
                return a.ord < b.ord
            end)
            local lim = count
            if #sub < lim then
                lim = #sub
            end
            for i = 1, lim do
                add(sub[i].u)
            end
        end

        -- 1. All required units first
        for i = 1, #pool do
            if pool[i].required then
                add(pool[i])
            end
        end

        -- 2. Fusion pairs (both parts, in group insertion order!)
        local fGroupOrder = {}
        local fGroups = {}
        for i = 1, #pool do
            local u = pool[i]
            if u.isAttacker and u.isFusionPart and u.fusionGroup and #u.fusionGroup > 0 then
                local g = fGroups[u.fusionGroup]
                if not g then
                    g = {}
                    fGroups[u.fusionGroup] = g
                    fGroupOrder[#fGroupOrder + 1] = u.fusionGroup
                end
                g[#g + 1] = u
            end
        end
        for i = 1, #fGroupOrder do
            local parts = fGroups[fGroupOrder[i]]
            if #parts >= 2 then
                add(parts[1])
                add(parts[2])
            end
        end

        -- 3. Top farms, buffers, idols
        addTopBy(function(u) return u.isFarm end, function(u) return u.farmIncome end, 3)
        addTopBy(function(u) return u.isBuffer and u.buffKind == "physical" end, function(u) return u.buffPower end, 2)
        addTopBy(function(u) return u.isBuffer and u.buffKind == "magic" end, function(u) return u.buffPower end, 2)
        addTopBy(function(u) return u.isBuffer and u.buffKind == "all" end, function(u) return u.buffPower end, 1)
        addTopBy(function(u) return u.isIdol end, function(u) return (u.teamDps * u.elemMul) + (u.buffPower * 1e4) + 1.0 end, 1)

        -- 4. Role specialists
        addTopBy(
            function(u) return u.isAttacker and ((u.cost * c.costScale) <= (c.startYen * 1.15)) end,
            function(u) return u.earlyDps * u.elemMul end,
            3
        )
        addTopBy(
            function(u) return u.isAttacker and u.canAir end,
            function(u)
                local mul = 1.0
                if u.airEarly then
                    mul = 1.25
                end
                return u.teamDps * u.elemMul * mul
            end,
            3
        )
        addTopBy(function(u) return u.isAttacker and u.hasBleed end, function(u) return (u.teamDps * u.elemMul) + 1.0 end, 2)
        addTopBy(function(u) return u.isAttacker and u.hasCC end, function(u) return (u.ccScore * 1e5) + (u.teamDps * u.elemMul) end, 2)
        addTopBy(function(u) return u.isAttacker and u.hasShieldBreak end, function(u) return (u.teamDps * u.elemMul) + 1.0 end, 2)
        addTopBy(function(u) return u.isAttacker and u.isPhys end, function(u) return u.teamDps * u.elemMul end, 4)
        addTopBy(function(u) return u.isAttacker and u.isMagic end, function(u) return u.teamDps * u.elemMul end, 4)
        addTopBy(function(u) return u.isAttacker end, function(u) return u.bossDps * u.elemMul end, 3)

        -- 5. Fill remaining capacity with overall strongest attackers
        addTopBy(function(u) return u.isAttacker end, function(u) return u.teamDps * u.elemMul end, limit)

        return out
    end

    -- Exact 1-to-1 mirror of engine/team_features.js isTeamValid
    function AI.isTeamValid(team, c)
        if (not team) or (#team < 1) or (#team > c.maxSlots) then
            return false
        end
        local attackers = 0
        for i = 1, #team do
            local u = team[i]
            if not u then
                return false
            end
            if u.isAttacker then
                attackers = attackers + 1
            end
            if u.isFarm and (not c.allowFarm) and (not u.required) then
                return false
            end
            if u.isBuffer and (not c.allowBuff) and (not u.required) then
                return false
            end
            if u.isHill and (not c.hasHills) and (not u.required) then
                return false
            end
            for j = i + 1, #team do
                if team[j] and team[j].id == u.id then
                    return false
                end
            end
        end
        return attackers >= 1
    end

    -- Exact 1-to-1 mirror of engine/team_features.js searchBestTeamWithNN
    -- Includes watchdog-safe task.wait() yielding if CPU slice exceeds 0.08s!
    function AI.searchTeams(rawPool, rawCtx, opts)
        local t0 = os.clock()
        local sliceT0 = t0
        local o = opts or EMPTY_LIST
        local beamWidth = math.floor(teamPositiveOr(o.beamWidth, 6))
        if beamWidth < 2 then
            beamWidth = 2
        elseif beamWidth > 10 then
            beamWidth = 10
        end
        local topK = math.floor(teamPositiveOr(o.topK, 3))
        if topK < 1 then
            topK = 1
        elseif topK > 6 then
            topK = 6
        end
        local maxShortlist = math.floor(teamPositiveOr(o.maxShortlist, 28))
        if maxShortlist < 12 then
            maxShortlist = 12
        elseif maxShortlist > 40 then
            maxShortlist = 40
        end

        local c = AI.normalizeTeamMode(rawCtx)
        local cleaned = AI.filterAndDedupPool(rawPool or EMPTY_LIST, c)
        if #cleaned == 0 then
            return {
                bestTeam = {},
                bestScore = -1e9,
                topTeams = {},
                evalCount = 0,
                elapsedMs = (os.clock() - t0) * 1000.0
            }
        end

        local poolStats = AI.computePoolStats(cleaned, c)
        local cand = AI.buildTeamShortlist(cleaned, c, maxShortlist)
        local M = #cand
        local targetSize = math.min(c.maxSlots, M)

        local featBuf = AI._teamFeatBuf
        if not featBuf then
            featBuf = {}
            AI._teamFeatBuf = featBuf
        end
        local teamBuf = {}
        local inCurBuf = {}
        local evalCount = 0
        local scoreCache = {}

        local function maybeYield()
            if task and task.wait then
                local nowC = os.clock()
                if (nowC - sliceT0) > 0.08 then
                    task.wait()
                    sliceT0 = os.clock()
                end
            end
        end

        local function evalIdxTeam(idxs, preKey)
            local key = preKey or teamIntKeyFromIdx(idxs)
            local cached = scoreCache[key]
            if cached ~= nil then
                return cached
            end
            local len = #idxs
            local t = teamBuf
            for i = 1, len do
                t[i] = cand[idxs[i]]
            end
            for i = #t, len + 1, -1 do
                t[i] = nil
            end
            AI.extractTeamFeatures(t, c, poolStats, featBuf)
            local s = AI.scoreTeam(featBuf)
            evalCount = evalCount + 1
            if (evalCount % 64) == 0 then
                maybeYield()
            end
            scoreCache[key] = s
            return s
        end

        local function copyIdxs(idxs)
            local cp = {}
            for i = 1, #idxs do
                cp[i] = idxs[i]
            end
            return cp
        end

        local function concatIdxs(base, extra)
            local res = {}
            for i = 1, #base do
                res[#res + 1] = base[i]
            end
            for i = 1, #extra do
                res[#res + 1] = extra[i]
            end
            return res
        end

        -- Identify required unit indices (1-based)
        local reqIdx = {}
        local reqSet = {}
        for i = 1, M do
            if cand[i].required and #reqIdx < targetSize then
                reqIdx[#reqIdx + 1] = i
                reqSet[i] = true
            end
        end

        -- Build synergy pair seeds
        local bestPhysCarry = {}
        local bestMagicCarry = {}
        local bestOverallAtk = {}
        local bestEarly = {}
        local bestFarmIdx = 0
        local bestPhysBuffIdx = 0
        local bestMagicBuffIdx = 0
        local fusionPairs = {}

        for i = 1, M do
            local u = cand[i]
            if u.isFarm then
                if bestFarmIdx == 0 or u.farmIncome > cand[bestFarmIdx].farmIncome then
                    bestFarmIdx = i
                end
            elseif u.isBuffer then
                if u.buffKind == "physical" and (bestPhysBuffIdx == 0 or u.buffPower > cand[bestPhysBuffIdx].buffPower) then
                    bestPhysBuffIdx = i
                end
                if u.buffKind == "magic" and (bestMagicBuffIdx == 0 or u.buffPower > cand[bestMagicBuffIdx].buffPower) then
                    bestMagicBuffIdx = i
                end
            else
                bestOverallAtk[#bestOverallAtk + 1] = i
                if u.isPhys then
                    bestPhysCarry[#bestPhysCarry + 1] = i
                end
                if u.isMagic then
                    bestMagicCarry[#bestMagicCarry + 1] = i
                end
                if (u.cost * c.costScale) <= (c.startYen * 1.15) then
                    bestEarly[#bestEarly + 1] = i
                end
            end
        end

        local function cmpDps(a, b)
            local da = cand[a].teamDps * cand[a].elemMul
            local db = cand[b].teamDps * cand[b].elemMul
            if da ~= db then
                return da > db
            end
            return a < b
        end
        table.sort(bestOverallAtk, cmpDps)
        table.sort(bestPhysCarry, cmpDps)
        table.sort(bestMagicCarry, cmpDps)
        table.sort(bestEarly, function(a, b)
            local ea = cand[a].earlyDps * cand[a].elemMul
            local eb = cand[b].earlyDps * cand[b].elemMul
            if ea ~= eb then
                return ea > eb
            end
            return a < b
        end)

        for i = 1, M do
            if cand[i].isAttacker and cand[i].isFusionPart and cand[i].fusionGroup and #cand[i].fusionGroup > 0 then
                for j = i + 1, M do
                    if cand[j].isAttacker and cand[j].isFusionPart and cand[j].fusionGroup == cand[i].fusionGroup then
                        fusionPairs[#fusionPairs + 1] = { i, j }
                        break
                    end
                end
            end
        end

        -- Collect initial partial seeds keyed by length (preserving insertion order)
        local seedsByLen = {}
        local seedSeq = 0
        local function pushSeed(idxs)
            if #idxs > targetSize then
                return
            end
            local seen = {}
            local uniq = {}
            for i = 1, #idxs do
                local v = idxs[i]
                if not seen[v] then
                    seen[v] = true
                    uniq[#uniq + 1] = v
                end
            end
            if #uniq > targetSize then
                return
            end
            local len = #uniq
            local bucket = seedsByLen[len]
            if not bucket then
                bucket = { map = {}, list = {} }
                seedsByLen[len] = bucket
            end
            local key = teamIntKeyFromIdx(uniq)
            if not bucket.map[key] then
                seedSeq = seedSeq + 1
                local item = { idxs = uniq, score = evalIdxTeam(uniq, key), key = key, seq = seedSeq }
                bucket.map[key] = item
                bucket.list[#bucket.list + 1] = item
            end
        end

        pushSeed(reqIdx)
        local topAtkSeeds = math.min(3, #bestOverallAtk)
        for k = 1, topAtkSeeds do
            pushSeed(concatIdxs(reqIdx, { bestOverallAtk[k] }))
        end
        if bestPhysBuffIdx > 0 and #bestPhysCarry > 0 then
            pushSeed(concatIdxs(reqIdx, { bestPhysBuffIdx, bestPhysCarry[1] }))
        end
        if bestMagicBuffIdx > 0 and #bestMagicCarry > 0 then
            pushSeed(concatIdxs(reqIdx, { bestMagicBuffIdx, bestMagicCarry[1] }))
        end
        if bestFarmIdx > 0 and #bestEarly > 0 then
            pushSeed(concatIdxs(reqIdx, { bestFarmIdx, bestEarly[1] }))
        elseif bestFarmIdx > 0 and #bestOverallAtk > 0 then
            pushSeed(concatIdxs(reqIdx, { bestFarmIdx, bestOverallAtk[1] }))
        end
        local topFSeeds = math.min(2, #fusionPairs)
        for f = 1, topFSeeds do
            pushSeed(concatIdxs(reqIdx, fusionPairs[f]))
        end

        -- Step 1: Beam Search from #reqIdx up to targetSize
        local beam = {}
        for depth = #reqIdx, targetSize - 1 do
            local bucket = seedsByLen[depth]
            if bucket then
                local existKeys = {}
                for bi = 1, #beam do
                    existKeys[beam[bi].key or teamIntKeyFromIdx(beam[bi].idxs)] = true
                end
                for si = 1, #bucket.list do
                    local item = bucket.list[si]
                    if not existKeys[item.key] then
                        beam[#beam + 1] = item
                        existKeys[item.key] = true
                    end
                end
            end

            if #beam > 0 then
                local nextMap = {}
                local nextList = {}
                local nextSeq = 0
                local isFinalStep = ((depth + 1) == targetSize)

                for bi = 1, #beam do
                    local cur = beam[bi].idxs
                    for m = 1, M do
                        inCurBuf[m] = false
                    end
                    local curAtk = 0
                    for k = 1, #cur do
                        inCurBuf[cur[k]] = true
                        if cand[cur[k]].isAttacker then
                            curAtk = curAtk + 1
                        end
                    end

                    for u = 1, M do
                        if not inCurBuf[u] then
                            local allowU = true
                            if isFinalStep and curAtk == 0 and (not cand[u].isAttacker) then
                                allowU = false
                            end
                            if allowU then
                                local nextIdxs = copyIdxs(cur)
                                nextIdxs[#nextIdxs + 1] = u
                                local key = teamIntKeyFromIdx(nextIdxs)
                                if not nextMap[key] then
                                    local sc = evalIdxTeam(nextIdxs, key)
                                    nextSeq = nextSeq + 1
                                    local entry = { idxs = nextIdxs, score = sc, key = key, seq = nextSeq }
                                    nextMap[key] = entry
                                    nextList[#nextList + 1] = entry
                                end
                            end
                        end
                    end
                end

                table.sort(nextList, function(a, b)
                    if a.score ~= b.score then
                        return a.score > b.score
                    end
                    return a.seq < b.seq
                end)

                beam = {}
                local keep = math.min(beamWidth, #nextList)
                for k = 1, keep do
                    beam[k] = nextList[k]
                end
            end
        end

        -- Include any seeds that already started at targetSize
        local fullBucket = seedsByLen[targetSize]
        if fullBucket then
            local existKeys = {}
            for bi = 1, #beam do
                existKeys[beam[bi].key or teamIntKeyFromIdx(beam[bi].idxs)] = true
            end
            for si = 1, #fullBucket.list do
                local item = fullBucket.list[si]
                if not existKeys[item.key] then
                    local tObj = {}
                    for k = 1, #item.idxs do
                        tObj[k] = cand[item.idxs[k]]
                    end
                    if AI.isTeamValid(tObj, c) then
                        beam[#beam + 1] = item
                        existKeys[item.key] = true
                    end
                end
            end
            table.sort(beam, function(a, b)
                if a.score ~= b.score then
                    return a.score > b.score
                end
                return (a.seq or 0) < (b.seq or 0)
            end)
        end

        -- Step 2: Steepest-Ascent 1-Swap Local Search on Top 3 distinct beam teams
        local refinedMap = {}
        local refinedList = {}
        local refinedSeq = 0
        local function recordRefined(idxs, score)
            local key = teamIntKeyFromIdx(idxs)
            local prev = refinedMap[key]
            if not prev then
                refinedSeq = refinedSeq + 1
                local item = { idxs = copyIdxs(idxs), score = score, key = key, seq = refinedSeq }
                refinedMap[key] = item
                refinedList[#refinedList + 1] = item
            elseif score > prev.score then
                prev.idxs = copyIdxs(idxs)
                prev.score = score
            end
        end

        local numRefine = math.min(3, #beam)
        for r = 1, numRefine do
            local cur = copyIdxs(beam[r].idxs)
            local curScore = beam[r].score
            recordRefined(cur, curScore)

            for pass = 1, 3 do
                for m = 1, M do
                    inCurBuf[m] = false
                end
                local curAtk = 0
                for k = 1, #cur do
                    inCurBuf[cur[k]] = true
                    if cand[cur[k]].isAttacker then
                        curAtk = curAtk + 1
                    end
                end

                local bestSwapSlot = 0
                local bestSwapU = 0
                local bestSwapScore = curScore + 1e-9

                for slot = 1, #cur do
                    local oldU = cur[slot]
                    if not reqSet[oldU] then
                        local oldIsAtk = 0
                        if cand[oldU].isAttacker then
                            oldIsAtk = 1
                        end
                        local atkWithout = curAtk - oldIsAtk

                        for u = 1, M do
                            if not inCurBuf[u] then
                                local newIsAtk = 0
                                if cand[u].isAttacker then
                                    newIsAtk = 1
                                end
                                if (atkWithout + newIsAtk) >= 1 then
                                    cur[slot] = u
                                    local sc = evalIdxTeam(cur)
                                    if sc > bestSwapScore then
                                        bestSwapScore = sc
                                        bestSwapSlot = slot
                                        bestSwapU = u
                                    end
                                end
                            end
                        end
                        cur[slot] = oldU
                    end
                end

                if bestSwapSlot > 0 then
                    cur[bestSwapSlot] = bestSwapU
                    curScore = bestSwapScore
                    recordRefined(cur, curScore)
                else
                    break
                end
            end
        end

        -- Step 3: Targeted Synergy 2-Swap Polish on Best Team
        local sortedRefined = {}
        for i = 1, #refinedList do
            sortedRefined[i] = refinedList[i]
        end
        table.sort(sortedRefined, function(a, b)
            if a.score ~= b.score then
                return a.score > b.score
            end
            return a.seq < b.seq
        end)

        if #sortedRefined > 0 and targetSize >= 2 then
            local bestCur = copyIdxs(sortedRefined[1].idxs)
            local bestScore = sortedRefined[1].score

            local synPairs = {}
            if bestPhysBuffIdx > 0 then
                local limP = math.min(2, #bestPhysCarry)
                for k = 1, limP do
                    synPairs[#synPairs + 1] = { bestPhysBuffIdx, bestPhysCarry[k] }
                end
            end
            if bestMagicBuffIdx > 0 then
                local limM = math.min(2, #bestMagicCarry)
                for k = 1, limM do
                    synPairs[#synPairs + 1] = { bestMagicBuffIdx, bestMagicCarry[k] }
                end
            end
            local limF = math.min(2, #fusionPairs)
            for f = 1, limF do
                synPairs[#synPairs + 1] = fusionPairs[f]
            end
            if bestFarmIdx > 0 and #bestOverallAtk > 0 then
                synPairs[#synPairs + 1] = { bestFarmIdx, bestOverallAtk[1] }
            end
            if #bestEarly > 0 and #bestOverallAtk > 0 and bestEarly[1] ~= bestOverallAtk[1] then
                synPairs[#synPairs + 1] = { bestEarly[1], bestOverallAtk[1] }
            end

            local inCur = {}
            local curAtk = 0
            for k = 1, #bestCur do
                inCur[bestCur[k]] = true
                if cand[bestCur[k]].isAttacker then
                    curAtk = curAtk + 1
                end
            end

            local improved2 = false
            local winS1 = 0
            local winS2 = 0
            local winU1 = 0
            local winU2 = 0
            local winScore = bestScore + 1e-9

            for p = 1, #synPairs do
                local u1 = synPairs[p][1]
                local u2 = synPairs[p][2]
                if u1 ~= u2 and (not inCur[u1]) and (not inCur[u2]) then
                    local addAtk = 0
                    if cand[u1].isAttacker then
                        addAtk = addAtk + 1
                    end
                    if cand[u2].isAttacker then
                        addAtk = addAtk + 1
                    end

                    for s1 = 1, #bestCur do
                        local o1 = bestCur[s1]
                        if not reqSet[o1] then
                            for s2 = s1 + 1, #bestCur do
                                local o2 = bestCur[s2]
                                if not reqSet[o2] then
                                    local remAtk = 0
                                    if cand[o1].isAttacker then
                                        remAtk = remAtk + 1
                                    end
                                    if cand[o2].isAttacker then
                                        remAtk = remAtk + 1
                                    end
                                    if (curAtk - remAtk + addAtk) >= 1 then
                                        bestCur[s1] = u1
                                        bestCur[s2] = u2
                                        local sc = evalIdxTeam(bestCur)
                                        if sc > winScore then
                                            winScore = sc
                                            winS1 = s1
                                            winS2 = s2
                                            winU1 = u1
                                            winU2 = u2
                                            improved2 = true
                                        end
                                        bestCur[s1] = o1
                                        bestCur[s2] = o2
                                    end
                                end
                            end
                        end
                    end
                end
            end

            if improved2 and winS1 > 0 and winS2 > 0 then
                bestCur[winS1] = winU1
                bestCur[winS2] = winU2
                bestScore = winScore
                recordRefined(bestCur, bestScore)

                local inAfter = {}
                local atkAfter = 0
                for k = 1, #bestCur do
                    inAfter[bestCur[k]] = true
                    if cand[bestCur[k]].isAttacker then
                        atkAfter = atkAfter + 1
                    end
                end
                for slot = 1, #bestCur do
                    local oldU = bestCur[slot]
                    if not reqSet[oldU] then
                        local oldIsAtk = 0
                        if cand[oldU].isAttacker then
                            oldIsAtk = 1
                        end
                        local atkWithout = atkAfter - oldIsAtk
                        local bU = 0
                        local bS = bestScore + 1e-9
                        for u = 1, M do
                            if not inAfter[u] then
                                local newIsAtk = 0
                                if cand[u].isAttacker then
                                    newIsAtk = 1
                                end
                                if (atkWithout + newIsAtk) >= 1 then
                                    bestCur[slot] = u
                                    local sc = evalIdxTeam(bestCur)
                                    if sc > bS then
                                        bS = sc
                                        bU = u
                                    end
                                end
                            end
                        end
                        if bU > 0 then
                            inAfter[oldU] = false
                            inAfter[bU] = true
                            local newIsAtk = 0
                            if cand[bU].isAttacker then
                                newIsAtk = 1
                            end
                            atkAfter = atkWithout + newIsAtk
                            bestCur[slot] = bU
                            bestScore = bS
                            recordRefined(bestCur, bestScore)
                        else
                            bestCur[slot] = oldU
                        end
                    end
                end
            end
        end

        -- Collect top K distinct valid teams
        local finalAll = {}
        for i = 1, #refinedList do
            finalAll[i] = refinedList[i]
        end
        table.sort(finalAll, function(a, b)
            if a.score ~= b.score then
                return a.score > b.score
            end
            return a.seq < b.seq
        end)

        local topTeams = {}
        for i = 1, #finalAll do
            if #topTeams >= topK then
                break
            end
            local idxs = finalAll[i].idxs
            local team = {}
            for k = 1, #idxs do
                team[k] = cand[idxs[k]]
            end
            if AI.isTeamValid(team, c) then
                topTeams[#topTeams + 1] = {
                    team = team,
                    score = finalAll[i].score,
                    key = teamKeyFromIdx(idxs)
                }
            end
        end

        local bestTeam = {}
        local bestScore = -1e9
        if #topTeams > 0 then
            bestTeam = topTeams[1].team
            bestScore = topTeams[1].score
        end

        return {
            bestTeam = bestTeam,
            bestScore = bestScore,
            topTeams = topTeams,
            evalCount = evalCount,
            elapsedMs = (os.clock() - t0) * 1000.0
        }
    end

    -- Build live TeamNN candidates & mode context from Simulator.bestTeam inputs
    -- Safe on both full Roblox accounts and minimal AirflowLab 13-unit fixtures (0 nil errors)
    function AI.buildLiveTeamInputs(applyFx, pool, arg22, num)
        local fxInfo = applyFx or EMPTY_LIST
        local mapName = fxInfo.map
        local mapInfo = nil
        if Brain and Brain.maps and mapName then
            mapInfo = Brain.maps[mapName]
        end

        local hasHills = true
        local hillCap = 6.0
        if mapInfo and mapInfo.hill == false then
            hasHills = false
            hillCap = 0.0
        elseif mapInfo and tonumber(mapInfo.hillSpots) and tonumber(mapInfo.hillSpots) > 0 then
            hillCap = tonumber(mapInfo.hillSpots)
        end

        local gm = tostring(fxInfo.gm or "story")
        local isInfinite = (fxInfo.infinite == true) or (fxInfo.endless == true)
        local totalWaves = tonumber(fxInfo.total) or 15
        if isInfinite and totalWaves <= 0 then
            totalWaves = 60
        end

        local fxTbl = fxInfo.fx or EMPTY_LIST
        local airThreat = 0.25
        if fxInfo.flyChance ~= nil and econIsFinite(tonumber(fxInfo.flyChance)) then
            airThreat = teamClamp01(tonumber(fxInfo.flyChance))
        elseif fxInfo.mapFly == true or fxTbl.fly == true then
            airThreat = 0.65
        end
        if fxInfo.mapFly == true and airThreat < 0.45 then
            airThreat = 0.45
        end

        local regenThreat = 0.0
        if fxInfo.regen == true or fxTbl.regen == true then
            regenThreat = 0.85
        elseif tonumber(fxInfo.regen) and tonumber(fxInfo.regen) > 0 then
            regenThreat = teamClamp01(tonumber(fxInfo.regen))
        end

        local shieldThreat = 0.0
        if fxInfo.shield == true or fxTbl.shield == true or fxInfo.armorAll == true then
            shieldThreat = 0.75
        elseif tonumber(fxInfo.shield) and tonumber(fxInfo.shield) > 0 then
            shieldThreat = teamClamp01(tonumber(fxInfo.shield))
        end

        local livesNorm = 0.75
        local baseHp = tonumber(fxInfo.baseHp)
        if econIsFinite(baseHp) and baseHp > 0 then
            livesNorm = teamClamp01(baseHp / 100.0)
        end
        if gm == "dungeon" then
            livesNorm = math.min(livesNorm, 0.25)
        end

        local ctx = {
            mode = gm,
            gm = gm,
            isInfinite = isInfinite,
            totalWaves = totalWaves,
            hasHills = hasHills,
            hillCap = hillCap,
            allowFarm = (Config == nil) or (Config.farmUnits ~= false),
            allowBuff = (Config == nil) or (Config.actives ~= false),
            maxSlots = 6,
            startYen = tonumber(fxInfo.start) or 650.0,
            costScale = tonumber(fxInfo.costScale) or 1.0,
            hpScale = tonumber(fxInfo.hpScale) or 1.0,
            speedScale = tonumber(fxInfo.speedScale) or 1.0,
            airThreat = airThreat,
            regenThreat = regenThreat,
            shieldThreat = shieldThreat,
            livesNorm = livesNorm,
            noCC = (fxInfo.noCC == true) or (fxTbl.noCC == true)
        }

        -- Collect deduped union of pool[1..N] + arg22 + top reserve pool.rest (capped at 32)
        local rawList = {}
        local seenIds = {}
        local function addRaw(u)
            if type(u) ~= "table" or not u.unit_id or not u.uuid then
                return
            end
            if seenIds[u.unit_id] then
                return
            end
            if #rawList >= 32 then
                return
            end
            seenIds[u.unit_id] = true
            rawList[#rawList + 1] = u
        end

        if type(pool) == "table" then
            for i = 1, #pool do
                addRaw(pool[i])
            end
        end
        if type(arg22) == "table" then
            for i = 1, #arg22 do
                addRaw(arg22[i])
            end
        end
        if type(pool) == "table" and type(pool.rest) == "table" then
            for i = 1, #pool.rest do
                if #rawList >= 32 then
                    break
                end
                addRaw(pool.rest[i])
            end
        end

        local fusionParents = nil
        if Units and Units.FUSION and type(Units.FUSION.parents) == "table" then
            fusionParents = Units.FUSION.parents
        end

        local candidates = {}
        for i = 1, #rawList do
            local u = rawList[i]
            local id = u.unit_id
            local data = (Core and Core.Units and Core.Units[id]) or EMPTY_LIST
            local isFarm = (Units and Units.isFarm and Units.isFarm(id) == true)
            local buffInfo = nil
            if (not isFarm) and Units and Units.allyBuff then
                local okB, bVal = pcall(Units.allyBuff, id)
                if okB and type(bVal) == "table" then
                    buffInfo = bVal
                end
            end
            local isBuffer = (not isFarm) and (buffInfo ~= nil)

            -- Respect Config.autoBuffKind via Units.buffAllowed(id)
            local skipUnit = false
            if isBuffer and Units and Units.buffAllowed then
                local okAllow, allowed = pcall(Units.buffAllowed, id)
                if okAllow and allowed == false then
                    skipUnit = true
                end
            end

            if not skipUnit then
                local cap = 3
                if Units and Units.cap then
                    local okC, cVal = pcall(Units.cap, u)
                    if okC and tonumber(cVal) and tonumber(cVal) >= 1 then
                        cap = math.floor(tonumber(cVal))
                    end
                elseif tonumber(data.spawn_cap) and tonumber(data.spawn_cap) >= 1 then
                    cap = math.floor(tonumber(data.spawn_cap))
                end

                local rows = nil
                if Units and Units.rows then
                    local okR, rVal = pcall(Units.rows, id)
                    if okR and type(rVal) == "table" then
                        rows = rVal
                    end
                end
                local maxLvl = (rows and tonumber(rows.max)) or 0
                local r0 = rows and rows[0]
                local rMax = rows and rows[maxLvl]

                local placeCost = tonumber((r0 and r0.cost) or data.cost) or 500.0
                local totalCost = placeCost
                if rows and maxLvl > 0 then
                    for lv = 1, maxLvl do
                        local rl = rows[lv]
                        if rl and tonumber(rl.cost) then
                            totalCost = totalCost + tonumber(rl.cost)
                        end
                    end
                else
                    totalCost = placeCost * 10.0
                end

                local elemMul = 1.0
                if Units and Units.elem then
                    local okE, eVal = pcall(Units.elem, id, fxInfo.mod)
                    if okE and econIsFinite(tonumber(eVal)) and tonumber(eVal) > 0 then
                        elemMul = tonumber(eVal)
                    end
                end
                local skinMul = 1.0
                if Units and Units.skinMul and fxInfo.skinSet then
                    local okS, sVal = pcall(Units.skinMul, u, fxInfo.skinSet)
                    if okS and econIsFinite(tonumber(sVal)) and tonumber(sVal) > 0 then
                        skinMul = tonumber(sVal)
                    end
                end
                local fxDpsMul = 1.0
                if Simulator and Simulator.fxDps then
                    local okF, fVal = pcall(Simulator.fxDps, fxInfo, id)
                    if okF and econIsFinite(tonumber(fVal)) and tonumber(fVal) > 0 then
                        fxDpsMul = tonumber(fVal)
                    end
                end

                local maxDps = 0.0
                local earlyDps = 0.0
                local farmIncome = 0.0
                local buffPower = 0.0
                local buffKind = "none"
                local rangeVal = tonumber((rMax and rMax.range) or data.range) or 22.0

                if Units and Units.range then
                    local okRg, rgVal = pcall(Units.range, u, maxLvl)
                    if okRg and econIsFinite(tonumber(rgVal)) and tonumber(rgVal) > 0 then
                        rangeVal = tonumber(rgVal)
                    end
                end

                if isFarm then
                    local perCopy = tonumber((rMax and rMax.farm) or data.farm_amount) or 0.0
                    if Units and Units.farm then
                        local okFm, fmVal = pcall(Units.farm, u, maxLvl)
                        if okFm and econIsFinite(tonumber(fmVal)) and tonumber(fmVal) > 0 then
                            perCopy = tonumber(fmVal)
                        end
                    end
                    farmIncome = perCopy * cap
                elseif isBuffer then
                    local uptime = tonumber(buffInfo.uptime) or 0.85
                    local bestRate = 0.0
                    local hasPhysB = false
                    local hasMagicB = false
                    local kindCnt = 0
                    if type(buffInfo.types) == "table" then
                        for bk, rate in pairs(buffInfo.types) do
                            local rv = tonumber(rate) or 0.0
                            if rv > bestRate then
                                bestRate = rv
                            end
                            kindCnt = kindCnt + 1
                            local bkl = string.lower(tostring(bk))
                            if bkl == "physical" then
                                hasPhysB = true
                            elseif bkl == "magic" then
                                hasMagicB = true
                            end
                        end
                    end
                    buffPower = teamClamp(bestRate * uptime, 0.0, 1.5)
                    if hasPhysB and (not hasMagicB) and kindCnt == 1 then
                        buffKind = "physical"
                    elseif hasMagicB and (not hasPhysB) and kindCnt == 1 then
                        buffKind = "magic"
                    else
                        buffKind = "all"
                    end
                else
                    if Units and Units.dps then
                        local okD, dMax = pcall(Units.dps, u, maxLvl, nil)
                        if okD and econIsFinite(tonumber(dMax)) and tonumber(dMax) > 0 then
                            maxDps = tonumber(dMax) * skinMul * fxDpsMul
                        end
                        local okD0, d0 = pcall(Units.dps, u, 0, nil)
                        if okD0 and econIsFinite(tonumber(d0)) and tonumber(d0) > 0 then
                            earlyDps = tonumber(d0) * skinMul * fxDpsMul
                        else
                            earlyDps = maxDps * 0.14
                        end
                    else
                        local dmg = tonumber((rMax and rMax.damage) or data.damage) or 100.0
                        local cd = math.max(0.1, tonumber((rMax and rMax.cd) or data.attack_cooldown) or 4.0)
                        maxDps = (dmg / cd) * skinMul * fxDpsMul
                        earlyDps = maxDps * 0.14
                    end
                end

                local isPhys = false
                local isMagic = false
                local dmgType = "physical"
                if Units and Units.types then
                    local okT, tSet, baseT = pcall(Units.types, id)
                    if okT then
                        if type(tSet) == "table" then
                            if tSet.physical then
                                isPhys = true
                            end
                            if tSet.magic then
                                isMagic = true
                            end
                        end
                        if baseT ~= nil then
                            dmgType = string.lower(tostring(baseT))
                            if dmgType == "physical" then
                                isPhys = true
                            elseif dmgType == "magic" then
                                isMagic = true
                            end
                        end
                    end
                else
                    local bt = string.lower(tostring(data._base_damage_type or "physical"))
                    dmgType = bt
                    if bt == "magic" then
                        isMagic = true
                    else
                        isPhys = true
                    end
                end
                if (not isPhys) and (not isMagic) then
                    isPhys = true
                end

                local isHybrid = (data.hybrid_placement == true)
                local isHill = (data.hill_unit == true) and (not isHybrid)

                local canAir = false
                local airEarly = false
                if (not isFarm) and (not isBuffer) and Units and Units.airFrom then
                    local okA, af = pcall(Units.airFrom, id)
                    if okA and tonumber(af) ~= nil then
                        canAir = true
                        airEarly = (tonumber(af) <= 2)
                    end
                end

                local hasBleed = false
                if (not isFarm) and (not isBuffer) and Units and Units.bleeds then
                    local okBl, bl = pcall(Units.bleeds, id)
                    if okBl and bl ~= nil then
                        hasBleed = true
                    end
                end

                local hasCC = false
                local ccScore = 0.0
                local effAmp = 0.0
                if (not isFarm) and (not isBuffer) and Units and Units.effects then
                    local okEf, ef = pcall(Units.effects, id)
                    if okEf and type(ef) == "table" then
                        if ef.bleed then
                            hasBleed = true
                        end
                        if tonumber(ef.amp) and tonumber(ef.amp) > 0 then
                            effAmp = tonumber(ef.amp)
                        end
                        local rawCc = 0.0
                        if (tonumber(ef.stun) or 0) > 0 then
                            rawCc = rawCc + 0.55
                        end
                        if (tonumber(ef.slow) or 0) > 0 then
                            rawCc = rawCc + 0.45
                        end
                        if ef.activeStun then
                            rawCc = rawCc + 0.25
                        end
                        if ef.control or rawCc > 0 then
                            hasCC = true
                            local scVal = tonumber(ef.score)
                            if econIsFinite(scVal) and scVal > 0 then
                                ccScore = teamClamp01(math.max(rawCc, scVal / 100.0))
                            else
                                ccScore = teamClamp01(math.max(0.5, rawCc))
                            end
                        end
                    end
                end

                local hasShieldBreak = false
                local isFullAoe = false
                local aoeMul = 1.3
                if (not isFarm) and (not isBuffer) and Units and Units.attackInfo and rMax and rMax.atk then
                    local okAi, aInfo = pcall(Units.attackInfo, rMax.atk, rangeVal)
                    if okAi and type(aInfo) == "table" then
                        if aInfo.breakShields == true then
                            hasShieldBreak = true
                        end
                        if aInfo.bleed == true then
                            hasBleed = true
                        end
                        if aInfo.full == true or (type(aInfo.shape) == "table" and aInfo.shape.type == "full_aoe") then
                            isFullAoe = true
                        end
                        if tonumber(aInfo.n) and tonumber(aInfo.n) > 0 then
                            aoeMul = teamClamp(tonumber(aInfo.n), 0.5, 4.0)
                        elseif isFullAoe then
                            aoeMul = 2.8
                        end
                    end
                end

                local isFusionPart = false
                local fusionGroup = ""
                if fusionParents then
                    if id == fusionParents[1] or id == fusionParents[2] then
                        isFusionPart = true
                        fusionGroup = "vegito"
                    end
                end

                local isIdol = false
                if Units and Units.idol then
                    local okId, idVal = pcall(Units.idol, id)
                    if okId and idVal == true then
                        isIdol = true
                    end
                end

                local teamDps = maxDps * cap
                local bossMul = 1.04
                if isFullAoe then
                    bossMul = 0.92
                end
                if effAmp > 0 then
                    bossMul = bossMul + math.min(0.35, effAmp)
                end
                local bossDps = teamDps * bossMul

                candidates[#candidates + 1] = {
                    id = id,
                    unit_id = id,
                    uuid = u.uuid,
                    isFarm = isFarm,
                    isBuffer = isBuffer,
                    cap = cap,
                    cost = placeCost,
                    totalCost = totalCost,
                    maxDps = maxDps,
                    earlyDps = earlyDps,
                    teamDps = teamDps,
                    bossDps = bossDps,
                    farmIncome = farmIncome,
                    buffPower = buffPower,
                    buffKind = buffKind,
                    dmgType = dmgType,
                    isPhys = isPhys,
                    isMagic = isMagic,
                    isHybrid = isHybrid,
                    isHill = isHill,
                    canAir = canAir,
                    airEarly = airEarly,
                    hasBleed = hasBleed,
                    hasCC = hasCC,
                    ccScore = ccScore,
                    hasShieldBreak = hasShieldBreak,
                    isFullAoe = isFullAoe,
                    aoeMul = aoeMul,
                    range = rangeVal,
                    elemMul = elemMul,
                    fusionGroup = fusionGroup,
                    isFusionPart = isFusionPart,
                    isIdol = isIdol,
                    required = false,
                    _raw = u
                }
            end
        end

        return {
            candidates = candidates,
            ctx = ctx
        }
    end


    -- ========================================================================
    -- Stage 9: Neural AI Card Picker (CardNN, 28d) & Passive Match Calibration Logger (v2.40 AI)
    -- Exact 1-to-1 pure Lua 5.1 / Luau mirror of engine/card_features.js
    -- ========================================================================
    local CARD_LN2 = math.log(2.0)

    local function cardIsFinite(x)
        return type(x) == "number" and x == x and x ~= math.huge and x ~= -math.huge
    end

    local function cardClamp(x, lo, hi)
        local n = tonumber(x)
        if not cardIsFinite(n) then
            return lo
        end
        if n < lo then
            return lo
        end
        if n > hi then
            return hi
        end
        return n
    end

    local function cardClamp01(x)
        return cardClamp(x, 0.0, 1.0)
    end

    local function cardFiniteOr(v, defVal)
        local n = tonumber(v)
        if cardIsFinite(n) then
            return n
        end
        return defVal
    end

    local function cardNumOr(v, defVal)
        local n = tonumber(v)
        if cardIsFinite(n) and n ~= 0.0 then
            return n
        end
        return defVal
    end

    local function cardRound(x, dec)
        local n = tonumber(x)
        if not cardIsFinite(n) then
            return 0
        end
        local mul = 10 ^ (dec or 2)
        if n >= 0 then
            return math.floor(n * mul + 0.5) / mul
        end
        return math.ceil(n * mul - 0.5) / mul
    end

    function AI.normalizeDamageType(raw)
        if raw == nil then
            return ""
        end
        local s = string.lower(tostring(raw))
        local suffix = "_damage"
        if #s > #suffix and string.sub(s, #s - #suffix + 1) == suffix then
            s = string.sub(s, 1, #s - #suffix)
        end
        return s
    end

    local WEATHER_FX_CACHE = {
        clear = { dmg = 1.0, cd = 1.0, range = 1.0, hp = 1.0, speed = 1.0, physMod = 0.0, magicMod = 0.0, fly = 0.0, ice = 0.0, noCC = false, shroud = 0.0, starfall = false },
        rain = { dmg = 1.0, cd = 1.0, range = 1.0, hp = 1.0, speed = 1.2, physMod = 0.0, magicMod = 0.0, fly = 0.0, ice = 0.0, noCC = false, shroud = 0.0, starfall = false },
        windy = { dmg = 1.0, cd = 1.0, range = 1.0, hp = 1.0, speed = 1.25, physMod = 0.0, magicMod = 0.0, fly = 0.2, ice = 0.0, noCC = false, shroud = 0.0, starfall = false },
        snow = { dmg = 1.0, cd = 1.0, range = 1.0, hp = 1.0, speed = 1.0, physMod = 0.0, magicMod = 0.0, fly = 0.0, ice = 0.5, noCC = false, shroud = 0.0, starfall = false },
        downpour = { dmg = 0.85, cd = 1.0, range = 0.7, hp = 1.0, speed = 1.0, physMod = 0.0, magicMod = 0.0, fly = 0.0, ice = 0.0, noCC = false, shroud = 0.0, starfall = false },
        mana = { dmg = 1.0, cd = 1.0, range = 1.0, hp = 1.0, speed = 1.0, physMod = 100.0 / 250.0 - 1.0, magicMod = 0.25, fly = 0.0, ice = 0.0, noCC = false, shroud = 0.0, starfall = false },
        fire = { dmg = 1.0, cd = 1.0, range = 1.0, hp = 1.0, speed = 1.5, physMod = 0.0, magicMod = 0.0, fly = 0.0, ice = 0.0, noCC = true, shroud = 0.0, starfall = false },
        underwater = { dmg = 1.0, cd = 1.0, range = 1.0, hp = 1.0, speed = 1.25, physMod = 0.0, magicMod = 0.0, fly = 0.0, ice = 0.0, noCC = false, shroud = 0.0, starfall = false },
        sandstorm = { dmg = 1.0, cd = 1.0, range = 1.0, hp = 1.0, speed = 1.0, physMod = 0.25, magicMod = 100.0 / 175.0 - 1.0, fly = 0.0, ice = 0.0, noCC = false, shroud = 0.0, starfall = false },
        meteor_shower = { dmg = 1.0, cd = 1.0, range = 1.0, hp = 1.0, speed = 1.0, physMod = 0.0, magicMod = 0.0, fly = 0.0, ice = 0.0, noCC = false, shroud = 0.0, starfall = true },
    }

    function AI.getWeatherFx(weatherName)
        local w = string.lower(tostring(weatherName or "clear"))
        return WEATHER_FX_CACHE[w] or WEATHER_FX_CACHE.clear
    end

    function AI.normalizeCardState(raw)
        local s = type(raw) == "table" and raw or {}
        local modeStr = string.lower(tostring(s.mode or "event_50"))
        local isEvent = false
        if s.isEvent ~= nil then
            isEvent = (s.isEvent == true)
        else
            if modeStr == "event_50" or modeStr == "event" or modeStr == "hunt" or modeStr == "summer_hunt" then
                isEvent = true
            end
        end

        local defTotal = 15.0
        if isEvent then
            defTotal = 50.0
        end
        local totalWaves = math.max(1.0, cardNumOr(s.totalWaves, defTotal))
        local wave = cardClamp(cardNumOr(s.wave, 1.0), 0.0, totalWaves)
        local wavesLeft = math.max(0.0, totalWaves - wave)

        local baseHpFrac = cardClamp01(cardFiniteOr(s.baseHpFrac, 1.0))
        local leakPressure = cardClamp01(cardFiniteOr(s.leakPressure, 0.0))
        local leak = (s.leak == true) or leakPressure >= 0.78 or baseHpFrac < 0.45

        local physShare = cardClamp01(cardFiniteOr(s.physShare, 0.5))
        local magicShare = cardClamp01(cardFiniteOr(s.magicShare, 1.0 - physShare))
        local fireShare = cardClamp01(cardFiniteOr(s.fireShare, 0.2))

        local airCov = cardClamp01(cardFiniteOr(s.airCov, 0.55))
        local bleedCov = cardClamp01(cardFiniteOr(s.bleedCov, 0.35))
        local shieldBreakCov = cardClamp01(cardFiniteOr(s.shieldBreakCov, 0.45))
        local ccReliance = cardClamp01(cardFiniteOr(s.ccReliance, 0.25))
        local rangeNeed = cardClamp01(cardFiniteOr(s.rangeNeed, 0.5))
        local hillReliance = cardClamp01(cardFiniteOr(s.hillReliance, 0.3))
        local defUpProg = cardClamp01(wave / math.max(1.0, totalWaves * 0.72))
        local upgradeProgress = cardClamp01(cardFiniteOr(s.upgradeProgress, defUpProg))

        local powerMargin = cardClamp(cardFiniteOr(s.powerMargin, 1.15), 0.25, 3.5)
        local safetyFloor = cardClamp(cardFiniteOr(s.safetyFloor, 1.0), 0.4, 2.0)
        local fhP = cardClamp(cardFiniteOr(s.fhP, powerMargin), 0.15, 10.0)
        local accumCurseLoad = cardClamp(cardFiniteOr(s.accumCurseLoad, 0.0), 0.0, 5.0)
        local accumEnemySpeed = cardClamp(cardFiniteOr(s.accumEnemySpeed, 1.0), 0.5, 4.0)
        local accumEnemyHp = cardClamp(cardFiniteOr(s.accumEnemyHp, 1.0), 0.5, 6.0)
        local accumFlyThreat = cardClamp01(cardFiniteOr(s.accumFlyThreat, 0.2))

        local physResistPct = cardClamp(cardFiniteOr(s.physResistPct, 0.0), 0.0, 95.0)
        local magicResistPct = cardClamp(cardFiniteOr(s.magicResistPct, 0.0), 0.0, 95.0)

        local weather = string.lower(tostring(s.weather or "clear"))

        local goalBias = 0.5
        if cardIsFinite(tonumber(s.goalBias)) then
            goalBias = cardClamp01(tonumber(s.goalBias))
        elseif type(s.huntCards) == "string" then
            local hc = string.lower(s.huntCards)
            if hc == "easiest win" then
                goalBias = 0.0
            elseif hc == "gems" then
                goalBias = 0.85
            elseif hc == "secret luck" then
                goalBias = 1.0
            else
                goalBias = 0.5
            end
        end

        local defBudget = 8000.0
        if isEvent then
            defBudget = 12000.0
        end
        local waveBudget = math.max(2000.0, cardNumOr(s.waveBudget, defBudget))
        local isBossSoon = (s.isBossSoon == true)
        if not isBossSoon then
            if isEvent then
                if (wave % 10) >= 6 or wave >= 36 then
                    isBossSoon = true
                end
            else
                if (wave % 5) >= 3 or wave >= 11 then
                    isBossSoon = true
                end
            end
        end

        return {
            _normalized = true,
            isEvent = isEvent,
            totalWaves = totalWaves,
            wave = wave,
            wavesLeft = wavesLeft,
            baseHpFrac = baseHpFrac,
            leakPressure = leakPressure,
            leak = leak,
            physShare = physShare,
            magicShare = magicShare,
            fireShare = fireShare,
            airCov = airCov,
            bleedCov = bleedCov,
            shieldBreakCov = shieldBreakCov,
            ccReliance = ccReliance,
            rangeNeed = rangeNeed,
            hillReliance = hillReliance,
            upgradeProgress = upgradeProgress,
            powerMargin = powerMargin,
            safetyFloor = safetyFloor,
            fhP = fhP,
            accumCurseLoad = accumCurseLoad,
            accumEnemySpeed = accumEnemySpeed,
            accumEnemyHp = accumEnemyHp,
            accumFlyThreat = accumFlyThreat,
            physResistPct = physResistPct,
            magicResistPct = magicResistPct,
            weather = weather,
            goalBias = goalBias,
            waveBudget = waveBudget,
            isBossSoon = isBossSoon
        }
    end

    function AI.computeTeamDamageShare(st, dmgType)
        local dt = AI.normalizeDamageType(dmgType)
        if dt == "" or dt == "all" then
            return 1.0
        end
        if dt == "physical" or dt == "phys" then
            return st.physShare
        end
        if dt == "magic" or dt == "magical" then
            return st.magicShare
        end
        if dt == "fire" then
            return st.fireShare
        end
        return 0.35
    end

    local function cardExistingResistPct(st, dmgType)
        local dt = AI.normalizeDamageType(dmgType)
        if dt == "physical" or dt == "phys" then
            return st.physResistPct
        end
        if dt == "magic" or dt == "magical" then
            return st.magicResistPct
        end
        return 0.0
    end

    function AI.evalWeatherForTeam(weatherName, st)
        local fx = AI.getWeatherFx(weatherName)
        local mul = fx.dmg / fx.cd / fx.hp
        if fx.range < 1.0 then
            mul = mul * (1.0 - (1.0 - fx.range) * (0.45 + 0.55 * st.rangeNeed))
        end
        if fx.speed > 1.0 then
            mul = mul / (1.0 + (fx.speed - 1.0) * 0.85)
        end
        if fx.physMod ~= 0.0 or fx.magicMod ~= 0.0 then
            local typeFactor = st.physShare * (1.0 + fx.physMod) + st.magicShare * (1.0 + fx.magicMod)
            mul = mul * cardClamp(typeFactor, 0.25, 1.5)
        end
        if fx.fly > 0.0 then
            local airGap = 1.0 - 0.78 * st.airCov
            mul = mul * math.max(0.35, 1.0 - fx.fly * 1.15 * airGap)
        end
        if fx.ice > 0.0 then
            mul = mul * math.max(0.55, 1.0 - fx.ice * 0.35 * (1.0 - st.fireShare))
        end
        if fx.noCC then
            mul = mul * math.max(0.55, 1.0 - 0.42 * st.ccReliance)
        end
        if fx.shroud > 0.0 then
            mul = mul * math.max(0.65, 1.0 - fx.shroud * 0.6)
        end
        return { fx = fx, mul = cardClamp(mul, 0.2, 2.0) }
    end

    function AI.parseCardEffects(card, rawState)
        local st = rawState
        if type(st) ~= "table" or not st._normalized then
            st = AI.normalizeCardState(rawState)
        end
        local c = type(card) == "table" and card or {}
        local effects = type(c.effects) == "table" and c.effects or {}

        local dmgBonus = 0.0
        local speedBonus = 0.0
        local rangeBonus = 0.0
        local critAoeBonus = 0.0
        local bossBonus = 0.0
        local econBonus = 0.0
        local sustainBonus = 0.0
        local rewardValue = 0.0

        local enemyHpDanger = 0.0
        local enemySpeedDanger = 0.0
        local regenDanger = 0.0
        local shieldFlyDanger = 0.0
        local teamPenaltyDanger = 0.0
        local otherHazardDanger = 0.0

        local netCombatMul = 1.0
        local pushesResistCritical = false

        local econNeed = cardClamp01((1.0 - st.upgradeProgress) * (st.wavesLeft / math.max(1.0, st.totalWaves * 0.55)))
        local bossBoost = 0.0
        if st.isBossSoon then
            bossBoost = 0.25
        end
        local bossRel = cardClamp01(0.25 + 0.55 * (st.wave / st.totalWaves) + bossBoost)
        local speedComp = 1.0 + math.max(0.0, st.accumEnemySpeed - 1.0) * 0.65
        local hpComp = 1.0 + math.max(0.0, st.accumEnemyHp - 1.0) * 0.35

        for _, eff in pairs(effects) do
            if type(eff) == "table" then
                local et = string.lower(tostring(eff.type or ""))
                local stat = string.lower(tostring(eff.stat or ""))
                local amt = cardFiniteOr(eff.amount, 0.0)

                if et == "stat_mul" or et == "stat_add" or et == "stat_attr_add" then
                    if stat == "damage" or stat == "dmg" then
                        if amt >= 0.0 then
                            dmgBonus = dmgBonus + amt
                            netCombatMul = netCombatMul * (1.0 + amt)
                        else
                            local pen = math.min(0.7, -amt)
                            teamPenaltyDanger = teamPenaltyDanger + pen
                            netCombatMul = netCombatMul * math.max(0.3, 1.0 - pen)
                        end
                    elseif stat == "range" then
                        if amt >= 0.0 then
                            rangeBonus = rangeBonus + amt
                            netCombatMul = netCombatMul * (1.0 + amt * (0.28 + 0.42 * st.rangeNeed))
                        else
                            local pen = math.min(0.6, -amt)
                            teamPenaltyDanger = teamPenaltyDanger + pen * (0.45 + 0.55 * st.rangeNeed)
                            netCombatMul = netCombatMul * math.max(0.45, 1.0 - pen * (0.35 + 0.45 * st.rangeNeed))
                        end
                    elseif string.find(stat, "cooldown", 1, true) ~= nil or stat == "spa" then
                        if amt < 0.0 then
                            local gain = (1.0 / math.max(0.35, 1.0 + amt)) - 1.0
                            speedBonus = speedBonus + gain
                            netCombatMul = netCombatMul * (1.0 + gain * (1.0 + 0.15 * (1.0 - st.shieldBreakCov)))
                        elseif amt > 0.0 then
                            local pen = 1.0 - 1.0 / (1.0 + amt)
                            teamPenaltyDanger = teamPenaltyDanger + pen
                            netCombatMul = netCombatMul * (1.0 - pen)
                        end
                    elseif stat == "attack_speed" or stat == "atk_speed" then
                        if amt >= 0.0 then
                            speedBonus = speedBonus + amt
                            netCombatMul = netCombatMul * (1.0 + amt)
                        else
                            local pen = math.min(0.65, -amt)
                            teamPenaltyDanger = teamPenaltyDanger + pen
                            netCombatMul = netCombatMul * math.max(0.35, 1.0 - pen)
                        end
                    elseif stat == "crit" or stat == "aoe" or stat == "dot" then
                        if amt >= 0.0 then
                            critAoeBonus = critAoeBonus + amt
                            netCombatMul = netCombatMul * (1.0 + amt * 0.72)
                        end
                    end
                elseif et == "stat_mul_real" then
                    local rel = amt - 1.0
                    if stat == "damage" or stat == "dmg" then
                        if rel >= 0.0 then
                            dmgBonus = dmgBonus + rel
                            netCombatMul = netCombatMul * math.max(0.3, amt)
                        else
                            local pen = math.min(0.7, -rel)
                            teamPenaltyDanger = teamPenaltyDanger + pen
                            netCombatMul = netCombatMul * math.max(0.3, amt)
                        end
                    elseif stat == "range" then
                        if rel >= 0.0 then
                            rangeBonus = rangeBonus + rel
                            netCombatMul = netCombatMul * (1.0 + rel * (0.28 + 0.42 * st.rangeNeed))
                        else
                            local pen = math.min(0.6, -rel)
                            teamPenaltyDanger = teamPenaltyDanger + pen * (0.45 + 0.55 * st.rangeNeed)
                            netCombatMul = netCombatMul * math.max(0.45, 1.0 - pen * (0.35 + 0.45 * st.rangeNeed))
                        end
                    elseif string.find(stat, "cooldown", 1, true) ~= nil or stat == "spa" then
                        if amt > 0.0 and amt < 1.0 then
                            local gain = (1.0 / math.max(0.35, amt)) - 1.0
                            speedBonus = speedBonus + gain
                            netCombatMul = netCombatMul * (1.0 + gain)
                        elseif amt > 1.0 then
                            local pen = 1.0 - 1.0 / amt
                            teamPenaltyDanger = teamPenaltyDanger + pen
                            netCombatMul = netCombatMul * (1.0 / amt)
                        end
                    end
                elseif et == "boss_damage" then
                    if amt > 0.0 then
                        bossBonus = bossBonus + amt
                        netCombatMul = netCombatMul * (1.0 + amt * (0.14 + 0.46 * bossRel))
                    end
                elseif et == "flying_damage" then
                    if amt > 0.0 then
                        local flyWeight = cardClamp01(0.20 + 0.80 * st.accumFlyThreat + 0.35 * (1.0 - st.airCov))
                        critAoeBonus = critAoeBonus + amt * flyWeight * 0.75
                        netCombatMul = netCombatMul * (1.0 + amt * 0.38 * flyWeight)
                    end
                elseif et == "crit_bonus" or et == "aoe_bonus" or et == "dot_bonus" then
                    if amt > 0.0 then
                        critAoeBonus = critAoeBonus + amt
                        netCombatMul = netCombatMul * (1.0 + amt * 0.75)
                    end
                elseif et == "enemy_amp_specific" then
                    local share = AI.computeTeamDamageShare(st, eff.damage_type)
                    local effGain = math.max(0.0, amt) * share
                    dmgBonus = dmgBonus + effGain
                    netCombatMul = netCombatMul * (1.0 + effGain)
                elseif et == "enemy_resistance_specific" then
                    local share = AI.computeTeamDamageShare(st, eff.damage_type)
                    local curRes = cardExistingResistPct(st, eff.damage_type)
                    local newRes = math.min(95.0, curRes + math.max(0.0, amt))
                    local relLoss = 1.0 - (100.0 + curRes) / math.max(100.0, 100.0 + newRes)
                    local cliffMul = 1.0
                    if newRes >= 60.0 and share >= 0.55 then
                        cliffMul = 1.45
                    end
                    local d = share * relLoss * cliffMul
                    enemyHpDanger = enemyHpDanger + d * 1.35
                    local extraPenalty = 1.0
                    if newRes >= 75.0 then
                        extraPenalty = 1.25
                    end
                    netCombatMul = netCombatMul * math.max(0.2, 1.0 - share * relLoss * extraPenalty)
                    if newRes >= 75.0 and share >= 0.60 then
                        pushesResistCritical = true
                    end
                elseif et == "enemy_stat_mul" then
                    if stat == "speed" then
                        if amt > 0.0 then
                            local d = amt * speedComp
                            enemySpeedDanger = enemySpeedDanger + d
                            netCombatMul = netCombatMul / (1.0 + amt * 0.90 * speedComp)
                        elseif amt < 0.0 then
                            sustainBonus = sustainBonus + math.min(0.4, -amt)
                            netCombatMul = netCombatMul * (1.0 + math.min(0.35, -amt * 0.7))
                        end
                    else
                        if amt > 0.0 then
                            local d = amt * hpComp
                            enemyHpDanger = enemyHpDanger + d
                            netCombatMul = netCombatMul / (1.0 + amt * hpComp)
                        elseif amt < 0.0 then
                            dmgBonus = dmgBonus + math.min(0.4, -amt)
                            netCombatMul = netCombatMul * (1.0 + math.min(0.4, -amt))
                        end
                    end
                elseif et == "enemy_speedup" or et == "burst_speed" then
                    local mult = 1.0
                    if et == "burst_speed" then
                        mult = 0.62
                    end
                    local d = math.max(0.0, amt) * mult * speedComp
                    enemySpeedDanger = enemySpeedDanger + d
                    netCombatMul = netCombatMul / (1.0 + d * 0.92)
                elseif et == "enemy_regen" then
                    local unmit = 1.0 - 0.80 * st.bleedCov
                    local rawR = math.max(0.0, amt) * 24.0
                    local d = rawR * unmit * hpComp
                    regenDanger = regenDanger + d
                    netCombatMul = netCombatMul * math.max(0.28, 1.0 - math.min(0.72, d * 0.95))
                elseif et == "enemy_shield" then
                    local unmit = 1.0 - 0.72 * st.shieldBreakCov
                    local rawS = math.max(0.0, amt) * 0.045
                    local d = rawS * unmit
                    shieldFlyDanger = shieldFlyDanger + d
                    netCombatMul = netCombatMul * math.max(0.35, 1.0 - math.min(0.65, d * 0.90))
                elseif et == "weather_flying_chance" or et == "weather_soaring_share" then
                    local scale = 0.45
                    if et == "weather_flying_chance" then
                        scale = 0.95
                    end
                    local unmit = 1.0 - 0.78 * st.airCov
                    local d = math.max(0.0, amt) * scale * unmit
                    shieldFlyDanger = shieldFlyDanger + d
                    netCombatMul = netCombatMul * math.max(0.32, 1.0 - math.min(0.68, d * 1.05))
                elseif et == "enemy_bomb" or et == "lightning_strikes" or et == "enemy_passive_chance" then
                    local d = 0.0
                    if et == "enemy_bomb" then
                        d = 0.14 * math.max(1.0, math.abs(amt))
                    elseif et == "lightning_strikes" then
                        d = math.max(0.05, math.abs(amt) * 0.14)
                    else
                        d = math.max(0.05, math.abs(amt) * 0.90)
                    end
                    otherHazardDanger = otherHazardDanger + d
                    netCombatMul = netCombatMul * math.max(0.45, 1.0 - math.min(0.55, d * 0.85))
                elseif et == "enemy_double_spawn" then
                    local d = math.max(0.15, amt) * 0.85 * hpComp
                    enemyHpDanger = enemyHpDanger + d * 0.7
                    enemySpeedDanger = enemySpeedDanger + d * 0.3
                    netCombatMul = netCombatMul / (1.0 + d * 0.85)
                elseif et == "enemy_boss_buff" then
                    local d = math.max(0.1, amt) * (0.55 + 0.65 * bossRel)
                    enemyHpDanger = enemyHpDanger + d
                    netCombatMul = netCombatMul / (1.0 + d * 0.80)
                elseif et == "new_path" then
                    local d = 0.34 * speedComp
                    enemySpeedDanger = enemySpeedDanger + d
                    netCombatMul = netCombatMul * math.max(0.55, 1.0 - d * 0.78)
                elseif et == "no_cc" then
                    local d = 0.45 * st.ccReliance
                    teamPenaltyDanger = teamPenaltyDanger + d
                    netCombatMul = netCombatMul * math.max(0.55, 1.0 - d * 0.90)
                elseif et == "anti_hill" then
                    local d = 0.55 * st.hillReliance
                    teamPenaltyDanger = teamPenaltyDanger + d
                    netCombatMul = netCombatMul * math.max(0.45, 1.0 - d * 0.95)
                elseif et == "resource_gain" then
                    local normYen = cardClamp(amt / st.waveBudget, 0.0, 1.5)
                    local effGain = normYen * 0.42
                    econBonus = econBonus + effGain
                    netCombatMul = netCombatMul * (1.0 + effGain * econNeed * 0.85)
                elseif et == "farm_income" then
                    local effGain = cardClamp(amt, 0.0, 1.0) * 0.55
                    econBonus = econBonus + effGain
                    netCombatMul = netCombatMul * (1.0 + effGain * econNeed * 0.95)
                elseif et == "unit_cost" then
                    if amt > 0.0 then
                        local d = amt * (0.12 + 0.88 * econNeed)
                        teamPenaltyDanger = teamPenaltyDanger + d
                        netCombatMul = netCombatMul / (1.0 + d * 0.75)
                    elseif amt < 0.0 then
                        local disc = math.min(0.45, -amt)
                        econBonus = econBonus + disc * 0.95
                        netCombatMul = netCombatMul * (1.0 + disc * (0.15 + 0.85 * econNeed) * 0.80)
                    end
                elseif et == "base_heal" or et == "base_shield" then
                    local needHp = 0.0
                    if et == "base_heal" then
                        needHp = cardClamp01(1.0 - st.baseHpFrac)
                    else
                        needHp = cardClamp01(0.35 + 0.65 * (1.0 - st.baseHpFrac) + 0.35 * st.leakPressure)
                    end
                    local gain = math.max(0.0, amt) * needHp
                    sustainBonus = sustainBonus + gain
                    local hpMult = 0.22
                    if st.baseHpFrac < 0.65 then
                        hpMult = 0.70
                    end
                    netCombatMul = netCombatMul * (1.0 + gain * hpMult)
                elseif et == "random_effects" then
                    local tierVal = cardNumOr(eff.tier, 1.0)
                    local mag = math.max(1.0, math.abs(amt)) * math.max(1.0, math.abs(tierVal))
                    if eff._type == "Good" then
                        local g = math.min(0.55, (1.12 ^ mag) - 1.0)
                        dmgBonus = dmgBonus + g * 0.7
                        critAoeBonus = critAoeBonus + g * 0.3
                        netCombatMul = netCombatMul * (1.0 + g)
                    else
                        local d = math.min(0.65, 1.0 - (0.80 ^ mag))
                        otherHazardDanger = otherHazardDanger + d
                        netCombatMul = netCombatMul * math.max(0.35, 1.0 - d)
                    end
                elseif et == "candy_multiplier" then
                    local remFrac = st.wavesLeft / st.totalWaves
                    rewardValue = rewardValue + math.abs(amt) * (0.45 + 1.55 * remFrac)
                elseif et == "add_reward" then
                    local gemAmt = math.abs(amt)
                    if type(eff.reward) == "table" then
                        local gr = tonumber(eff.reward.gem_reward)
                        if cardIsFinite(gr) and gr ~= 0.0 then
                            gemAmt = gr
                        end
                    end
                    rewardValue = rewardValue + cardClamp(gemAmt / 300.0, 0.0, 1.0)
                elseif et == "golem_chance" then
                    rewardValue = rewardValue + math.abs(amt) * 0.45
                elseif et == "secret_drop" then
                    rewardValue = rewardValue + math.abs(amt) * (0.55 + 0.45 * st.goalBias)
                end
            end
        end

        if c.weather then
            local curW = AI.evalWeatherForTeam(st.weather, st)
            local newW = AI.evalWeatherForTeam(c.weather, st)
            local wRatio = cardClamp(newW.mul / math.max(0.15, curW.mul), 0.25, 3.0)
            netCombatMul = netCombatMul * wRatio

            if wRatio > 1.03 then
                sustainBonus = sustainBonus + math.min(0.65, wRatio - 1.0)
            elseif wRatio < 0.97 then
                local wLoss = 1.0 - wRatio
                local nfx = newW.fx
                if nfx.speed > curW.fx.speed then
                    enemySpeedDanger = enemySpeedDanger + (nfx.speed - curW.fx.speed) * 0.75 * speedComp
                end
                if nfx.fly > curW.fx.fly then
                    shieldFlyDanger = shieldFlyDanger + (nfx.fly - curW.fx.fly) * 1.15 * (1.0 - 0.78 * st.airCov)
                end
                if nfx.noCC and not curW.fx.noCC then
                    teamPenaltyDanger = teamPenaltyDanger + 0.42 * st.ccReliance
                end
                if nfx.range < curW.fx.range then
                    teamPenaltyDanger = teamPenaltyDanger + (curW.fx.range - nfx.range) * (0.45 + 0.55 * st.rangeNeed)
                end
                if nfx.physMod < 0 and st.physShare > 0.4 then
                    enemyHpDanger = enemyHpDanger + (-nfx.physMod) * st.physShare * 0.95
                end
                if nfx.magicMod < 0 and st.magicShare > 0.4 then
                    enemyHpDanger = enemyHpDanger + (-nfx.magicMod) * st.magicShare * 0.95
                end
                if nfx.ice > curW.fx.ice then
                    otherHazardDanger = otherHazardDanger + (nfx.ice - curW.fx.ice) * 0.35 * (1.0 - st.fireShare)
                end
                if nfx.shroud > curW.fx.shroud then
                    otherHazardDanger = otherHazardDanger + (nfx.shroud - curW.fx.shroud) * 0.60
                end
                if (enemyHpDanger + enemySpeedDanger + shieldFlyDanger + teamPenaltyDanger + otherHazardDanger) < wLoss * 0.5 then
                    otherHazardDanger = otherHazardDanger + wLoss * 0.5
                end
            end
            if string.lower(tostring(c.weather)) == "meteor_shower" and st.weather ~= "meteor_shower" then
                rewardValue = rewardValue + 0.35
            end
        end

        if c.option_type == "Bad" then
            rewardValue = rewardValue + 0.12
        end

        local cg = tonumber(c._cardGems)
        if cardIsFinite(cg) and cg > 0 then
            local gNorm = cardClamp(cg / 450.0, 0.0, 1.2)
            if gNorm > rewardValue then
                rewardValue = gNorm
            end
        end
        local cl = tonumber(c._cardLuck)
        if cardIsFinite(cl) and cl > 0 then
            rewardValue = rewardValue + cl * (0.40 + 0.45 * st.goalBias)
        end

        netCombatMul = cardClamp(netCombatMul, 0.20, 4.0)
        local totalCurseDanger = enemyHpDanger + enemySpeedDanger + regenDanger + shieldFlyDanger + teamPenaltyDanger + otherHazardDanger
        local netLog = math.log(netCombatMul)

        local projMargin = st.powerMargin * netCombatMul
        local safeThresh = st.safetyFloor * 0.96
        if st.leak then
            safeThresh = 1.05
        elseif st.baseHpFrac < 0.70 then
            safeThresh = 1.02
        end

        local isSafe = (not pushesResistCritical) and (
            (netCombatMul >= 0.995 and totalCurseDanger < 0.25) or
            ((not st.leak) and st.baseHpFrac >= 0.70 and projMargin >= safeThresh and totalCurseDanger < 0.52)
        )

        local isFatalCurse = pushesResistCritical or (
            netCombatMul < 0.88 and (st.leak or st.baseHpFrac < 0.70 or projMargin < st.safetyFloor * 0.85)
        ) or (totalCurseDanger >= 0.68 and projMargin < st.safetyFloor * 1.10)

        local rankNum = tonumber(c.rank)
        local finalRank = 0
        if cardIsFinite(rankNum) and rankNum > 0 then
            finalRank = rankNum
        end

        return {
            dmgBonus = dmgBonus,
            speedBonus = speedBonus,
            rangeBonus = rangeBonus,
            critAoeBonus = critAoeBonus,
            bossBonus = bossBonus,
            econBonus = econBonus,
            sustainBonus = sustainBonus,
            rewardValue = rewardValue,
            enemyHpDanger = enemyHpDanger,
            enemySpeedDanger = enemySpeedDanger,
            regenDanger = regenDanger,
            shieldFlyDanger = shieldFlyDanger,
            teamPenaltyDanger = teamPenaltyDanger,
            otherHazardDanger = otherHazardDanger,
            totalCurseDanger = totalCurseDanger,
            netCombatMul = netCombatMul,
            netLog = netLog,
            projMargin = projMargin,
            isSafe = isSafe,
            isFatalCurse = isFatalCurse,
            pushesResistCritical = pushesResistCritical,
            banned = (c.banned == true),
            rank = finalRank
        }
    end

    function AI.computeOfferContext(parsedList)
        local maxNetLog = -1e9
        local minDanger = 1e9
        local maxReward = 0.0
        local hasSafe = false

        for i = 1, #parsedList do
            local p = parsedList[i]
            if p then
                if p.netLog > maxNetLog then
                    maxNetLog = p.netLog
                end
                if p.totalCurseDanger < minDanger then
                    minDanger = p.totalCurseDanger
                end
                if p.rewardValue > maxReward then
                    maxReward = p.rewardValue
                end
                if (not p.banned) and p.isSafe then
                    hasSafe = true
                end
            end
        end

        if maxNetLog < -1e8 then
            maxNetLog = 0.0
        end
        if minDanger > 1e8 then
            minDanger = 0.0
        end

        return {
            maxNetLog = maxNetLog,
            minDanger = minDanger,
            maxReward = maxReward,
            hasSafe = hasSafe
        }
    end

    function AI.extractCardFeatures(parsedCard, rawState, offerCtx, outBuf)
        local f = outBuf or {}
        local st = rawState
        if type(st) ~= "table" or not st._normalized then
            st = AI.normalizeCardState(rawState)
        end
        local p = type(parsedCard) == "table" and parsedCard or {}
        local oc = offerCtx
        if type(oc) ~= "table" then
            oc = {
                maxNetLog = p.netLog or 0.0,
                minDanger = p.totalCurseDanger or 0.0,
                maxReward = p.rewardValue or 0.0,
                hasSafe = (p.isSafe == true)
            }
        end

        local econNeed = cardClamp01((1.0 - st.upgradeProgress) * (st.wavesLeft / math.max(1.0, st.totalWaves * 0.55)))
        local bossBoost = 0.0
        if st.isBossSoon then
            bossBoost = 0.25
        end
        local bossRel = cardClamp01(0.25 + 0.55 * (st.wave / st.totalWaves) + bossBoost)

        -- 1..8 (JS 0..7): Team-Matched Card Buffs & Rewards
        f[1] = cardClamp01((p.dmgBonus or 0.0) / 0.50)
        f[2] = cardClamp01((p.speedBonus or 0.0) / 0.45)
        f[3] = cardClamp01(((p.rangeBonus or 0.0) * (0.40 + 0.60 * st.rangeNeed)) / 0.35)
        f[4] = cardClamp01(((p.bossBonus or 0.0) * bossRel) / 0.55)
        f[5] = cardClamp01((p.critAoeBonus or 0.0) / 0.45)
        f[6] = cardClamp01(((p.econBonus or 0.0) * (0.15 + 0.85 * econNeed)) / 0.45)
        f[7] = cardClamp01((p.sustainBonus or 0.0) / 0.45)
        f[8] = cardClamp01((p.rewardValue or 0.0) / 1.00)

        -- 9..15 (JS 8..14): Team-Matched Curse & Debuff Danger
        f[9] = cardClamp01((p.enemyHpDanger or 0.0) / 0.70)
        f[10] = cardClamp01((p.enemySpeedDanger or 0.0) / 0.65)
        f[11] = cardClamp01((p.regenDanger or 0.0) / 0.55)
        f[12] = cardClamp01((p.shieldFlyDanger or 0.0) / 0.60)
        f[13] = cardClamp01((p.teamPenaltyDanger or 0.0) / 0.60)
        f[14] = cardClamp01((p.otherHazardDanger or 0.0) / 0.50)
        local netLog = cardFiniteOr(p.netLog, 0.0)
        f[15] = cardClamp01(0.5 + 0.5 * (netLog / CARD_LN2))

        -- 16..23 (JS 15..22): Match & Team Context
        if st.isEvent then
            f[16] = 1.0
        else
            f[16] = 0.0
        end
        f[17] = cardClamp01(st.wave / st.totalWaves)
        f[18] = st.baseHpFrac
        f[19] = st.leakPressure
        f[20] = cardClamp01((st.powerMargin - 0.45) / 1.65)
        f[21] = cardClamp01(st.accumCurseLoad / 2.50)

        local typeFocus = math.max(st.physShare, st.magicShare)
        local utilGap = ((1.0 - st.airCov) + (1.0 - st.bleedCov) + (1.0 - st.shieldBreakCov)) / 3.0
        f[22] = cardClamp01(0.45 * typeFocus + 0.35 * utilGap + 0.20 * st.ccReliance)
        f[23] = st.goalBias

        -- 24..28 (JS 23..27): Relative Offer Context
        f[24] = cardClamp01(1.0 - (oc.maxNetLog - netLog) / 0.90)
        f[25] = cardClamp01(1.0 - ((p.totalCurseDanger or 0.0) - oc.minDanger) / 0.80)
        if oc.maxReward > 1e-6 then
            f[26] = cardClamp01((p.rewardValue or 0.0) / oc.maxReward)
        else
            f[26] = 0.0
        end
        if p.isSafe then
            f[27] = 1.0
        else
            f[27] = 0.0
        end
        if oc.hasSafe then
            f[28] = 1.0
        else
            f[28] = 0.0
        end

        return f
    end

    function AI.checkCardGuardrails(parsedList, rawState)
        local st = rawState
        if type(st) ~= "table" or not st._normalized then
            st = AI.normalizeCardState(rawState)
        end
        local n = type(parsedList) == "table" and #parsedList or 0
        if n == 0 then
            return {
                eligibleIndices = {},
                forcedIndex = 0,
                reason = "empty",
                hasSafe = false,
                allBanned = false
            }
        end

        local nonBanned = {}
        local safeNonBanned = {}
        local nonFatalNonBanned = {}

        local bestRankIdx = 0
        local bestRankVal = 1e9

        for i = 1, n do
            local p = parsedList[i]
            if p and not p.banned then
                nonBanned[#nonBanned + 1] = i
                if p.isSafe then
                    safeNonBanned[#safeNonBanned + 1] = i
                    if p.rank > 0 and p.rank < bestRankVal then
                        bestRankVal = p.rank
                        bestRankIdx = i
                    end
                end
                if not p.isFatalCurse then
                    nonFatalNonBanned[#nonFatalNonBanned + 1] = i
                end
            end
        end

        if bestRankIdx > 0 then
            return {
                eligibleIndices = { bestRankIdx },
                forcedIndex = bestRankIdx,
                reason = "priority_rank",
                hasSafe = true,
                allBanned = false
            }
        end

        if #nonBanned == 0 then
            local allIdx = {}
            for i = 1, n do
                allIdx[i] = i
            end
            return {
                eligibleIndices = allIdx,
                forcedIndex = 0,
                reason = "all_banned_fallback",
                hasSafe = false,
                allBanned = true
            }
        end

        if (st.leak or st.baseHpFrac < 0.70) and #safeNonBanned > 0 then
            return {
                eligibleIndices = safeNonBanned,
                forcedIndex = 0,
                reason = "safe_under_pressure",
                hasSafe = true,
                allBanned = false
            }
        end

        if #nonFatalNonBanned > 0 and #nonFatalNonBanned < #nonBanned then
            return {
                eligibleIndices = nonFatalNonBanned,
                forcedIndex = 0,
                reason = "exclude_fatal_curse",
                hasSafe = #safeNonBanned > 0,
                allBanned = false
            }
        end

        if st.goalBias < 0.25 and #safeNonBanned > 0 then
            return {
                eligibleIndices = safeNonBanned,
                forcedIndex = 0,
                reason = "easiest_win_safe",
                hasSafe = true,
                allBanned = false
            }
        end

        local outReason = "all_unsafe_min_harm"
        if #safeNonBanned > 0 then
            outReason = "non_banned"
        end
        return {
            eligibleIndices = nonBanned,
            forcedIndex = 0,
            reason = outReason,
            hasSafe = #safeNonBanned > 0,
            allBanned = false
        }
    end

    function AI.scoreCardCandidate(parsedCard, rawState, offerCtx, outBuf)
        local buf = outBuf or AI._cFeatBuf
        AI.extractCardFeatures(parsedCard, rawState, offerCtx, buf)
        local out = forwardMLP(CARD_NET, buf)
        local sc = out and out[1] or 0.0
        if not cardIsFinite(sc) then
            sc = cardFiniteOr(parsedCard and parsedCard.netLog, 0.0)
        end
        return sc
    end

    -- Enrich partial live ctx from Match/Units/Hunt/Core without overwriting caller-supplied fields
    function AI.buildLiveCardState(ctx)
        local raw = {}
        if type(ctx) == "table" then
            for k, v in pairs(ctx) do
                if k ~= "meta" then
                    raw[k] = v
                end
            end
        end

        if raw._rawState == true or not Match then
            return AI.normalizeCardState(raw)
        end

        if raw.wave == nil and Match.wave then
            local okW, wv = pcall(Match.wave)
            if okW and cardIsFinite(tonumber(wv)) then
                raw.wave = tonumber(wv)
            end
        end
        if raw.totalWaves == nil and Match.total then
            raw.totalWaves = tonumber(Match.total)
        end
        if raw.baseHpFrac == nil and AI.getBaseHpFrac then
            local okHp, hpF = pcall(AI.getBaseHpFrac)
            if okHp and cardIsFinite(tonumber(hpF)) then
                raw.baseHpFrac = tonumber(hpF)
            end
        end
        if raw.leakPressure == nil and Match.pressure ~= nil then
            raw.leakPressure = cardClamp01(tonumber(Match.pressure) or 0.0)
        end
        if raw.fhP == nil and Match.fhP ~= nil then
            raw.fhP = tonumber(Match.fhP)
        end
        if raw.powerMargin == nil and raw.fhP ~= nil then
            raw.powerMargin = tonumber(raw.fhP)
        end
        if raw.safetyFloor == nil and raw.floor ~= nil then
            raw.safetyFloor = tonumber(raw.floor)
        end
        if raw.weather == nil and Hunt and Hunt.weatherNow then
            local okWt, wt = pcall(Hunt.weatherNow)
            if okWt and wt ~= nil then
                raw.weather = tostring(wt)
            end
        end
        if raw.huntCards == nil and Config and Config.huntCards then
            raw.huntCards = tostring(Config.huntCards)
        end

        -- Accumulated resistances & curse stacks
        if type(Match.fhResist) == "table" then
            if raw.physResistPct == nil then
                raw.physResistPct = tonumber(Match.fhResist.physical_damage or Match.fhResist.physical) or 0.0
            end
            if raw.magicResistPct == nil then
                raw.magicResistPct = tonumber(Match.fhResist.magic_damage or Match.fhResist.magic) or 0.0
            end
        end
        if raw.accumCurseLoad == nil and type(Match.fhEffects) == "table" then
            raw.accumCurseLoad = math.min(5.0, #Match.fhEffects * 0.22)
        end

        -- Team composition & coverage from Match.mine / Match.team
        if raw.physShare == nil or raw.magicShare == nil or raw.airCov == nil or raw.bleedCov == nil then
            local physN, magicN, fireN, airN, bleedN, hillN, dpsN = 0, 0, 0, 0, 0, 0, 0
            local upgSum, upgCnt = 0, 0
            local unitIds = {}
            if type(Match.mine) == "table" and #Match.mine > 0 then
                for i = 1, #Match.mine do
                    local u = Match.mine[i]
                    local okId, uid = pcall(function() return u._stats.id.Value end)
                    if okId and uid then
                        unitIds[#unitIds + 1] = uid
                        local okUp, ulv = pcall(function() return tonumber(u._stats.upgrade.Value) or 0 end)
                        if okUp and ulv then
                            upgSum = upgSum + math.min(1.0, ulv / 8.0)
                            upgCnt = upgCnt + 1
                        end
                    end
                end
            elseif type(Match.team) == "table" then
                for i = 1, #Match.team do
                    local m = Match.team[i]
                    if type(m) == "table" and m.id then
                        unitIds[#unitIds + 1] = m.id
                    end
                end
            end

            for i = 1, #unitIds do
                local uid = unitIds[i]
                local isFarm = Units and Units.isFarm and Units.isFarm(uid)
                if not isFarm then
                    dpsN = dpsN + 1
                    local uData = Core and Core.Units and Core.Units[uid]
                    local types = Units and Units.types and Units.types(uid)
                    if type(types) == "table" then
                        if types.physical or types.physical_damage then
                            physN = physN + 1
                        end
                        if types.magic or types.magic_damage then
                            magicN = magicN + 1
                        end
                        if types.fire or types.fire_damage or types.burn then
                            fireN = fireN + 1
                        end
                        if types.bleed or types.bleed_damage then
                            bleedN = bleedN + 1
                        end
                    end
                    if type(uData) == "table" then
                        if uData.hill_unit or uData.hybrid_placement then
                            airN = airN + 1
                        end
                        if uData.hill_unit and not uData.hybrid_placement then
                            hillN = hillN + 1
                        end
                    end
                end
            end

            if dpsN > 0 then
                if raw.physShare == nil then
                    if (physN + magicN) > 0 then
                        raw.physShare = physN / (physN + magicN)
                    else
                        raw.physShare = 0.5
                    end
                end
                if raw.magicShare == nil then
                    raw.magicShare = 1.0 - raw.physShare
                end
                if raw.fireShare == nil then
                    raw.fireShare = fireN / dpsN
                end
                if raw.airCov == nil then
                    raw.airCov = math.min(1.0, airN / math.max(1.0, dpsN * 0.55))
                end
                if raw.bleedCov == nil then
                    raw.bleedCov = math.min(1.0, bleedN / math.max(1.0, dpsN * 0.40))
                end
                if raw.hillReliance == nil then
                    raw.hillReliance = hillN / dpsN
                end
                if raw.upgradeProgress == nil and upgCnt > 0 then
                    raw.upgradeProgress = upgSum / upgCnt
                end
            end
        end

        return AI.normalizeCardState(raw)
    end

    -- Full CardNN inference + hard guardrails (exact 1-to-1 mirror of JS chooseCardWithNN)
    -- Always returns strictly valid key k where choices[k] ~= nil (or nil if choices empty).
    function AI.chooseRogueCard(choices, ctx)
        if type(choices) ~= "table" then
            return nil, 0.0, "empty"
        end

        -- Collect entries deterministically while preserving exact original key types (int or string)
        local entries = {}
        local pairCount = 0
        local allSeqInt = true
        for k, v in pairs(choices) do
            if v ~= nil then
                pairCount = pairCount + 1
                if type(k) ~= "number" or k < 1 or math.floor(k) ~= k then
                    allSeqInt = false
                end
            end
        end
        if pairCount == 0 then
            return nil, 0.0, "empty"
        end
        if allSeqInt then
            for i = 1, pairCount do
                if choices[i] == nil then
                    allSeqInt = false
                    break
                end
            end
        end

        if allSeqInt then
            for i = 1, pairCount do
                entries[i] = { key = i, card = choices[i], sortKey = tostring(i) }
            end
        else
            for k, v in pairs(choices) do
                if v ~= nil then
                    entries[#entries + 1] = { key = k, card = v, sortKey = tostring(k) }
                end
            end
            table.sort(entries, function(a, b)
                return a.sortKey < b.sortKey
            end)
        end

        local st = AI.buildLiveCardState(ctx)
        local metaMap = (type(ctx) == "table" and type(ctx.meta) == "table") and ctx.meta or nil
        local parsedList = {}
        for i = 1, #entries do
            local e = entries[i]
            local c = e.card
            local evalCard = c
            local m = metaMap and metaMap[e.key] or nil
            if m ~= nil and type(c) == "table" then
                evalCard = {
                    title = c.title,
                    option_type = c.option_type,
                    weather = c.weather,
                    effects = c.effects,
                    banned = (m.banned == true) or (c.banned == true),
                    rank = m.rank or c.rank,
                    _cardGems = m.gems or c._cardGems,
                    _cardLuck = m.luck or c._cardLuck
                }
            end
            parsedList[i] = AI.parseCardEffects(evalCard, st)
        end

        local offerCtx = AI.computeOfferContext(parsedList)
        local gr = AI.checkCardGuardrails(parsedList, st)
        local elig = gr.eligibleIndices

        if gr.forcedIndex > 0 and entries[gr.forcedIndex] then
            local fKey = entries[gr.forcedIndex].key
            if choices[fKey] ~= nil then
                return fKey, 0.0, gr.reason, { index = gr.forcedIndex, parsed = parsedList, guardrails = gr }
            end
        end

        local buf = AI._cFeatBuf
        local bestIdx = elig[1] or 1
        local bestScore = -1e18

        for j = 1, #elig do
            local idx = elig[j]
            local p = parsedList[idx]
            AI.extractCardFeatures(p, st, offerCtx, buf)
            local out = forwardMLP(CARD_NET, buf)
            local sc = out and out[1] or p.netLog
            if not cardIsFinite(sc) then
                sc = p.netLog
            end
            if sc > bestScore + 1e-12 or (math.abs(sc - bestScore) <= 1e-12 and p.netLog > parsedList[bestIdx].netLog) then
                bestScore = sc
                bestIdx = idx
            end
        end

        local chosenKey = entries[bestIdx] and entries[bestIdx].key or entries[1].key
        -- Final hard invariant: key MUST exist in choices
        if choices[chosenKey] == nil then
            chosenKey = entries[1].key
        end
        return chosenKey, bestScore, gr.reason, { index = bestIdx, parsed = parsedList, guardrails = gr }
    end

    -- ========================================================================
    -- Built-in Passive Match Calibration Logger (Config.matchLogger = false default)
    -- Zero remotes, zero game-state mutation, throttled sampling, bounded memory.
    -- ========================================================================
    local MATCH_LOG_DIR = "AA_SmartFarm/match_logs"
    local MATCH_LOG_MAX_WAVES = 150
    local MATCH_LOG_MAX_PLACEMENTS = 40
    local MATCH_LOG_MAX_CARDS_PER_WAVE = 12
    local MATCH_LOG_TICK_INTERVAL = 2.0

    local function matchLogEnsureFolders()
        if type(makefolder) ~= "function" then
            return false
        end
        local hasIsFolder = (type(isfolder) == "function")
        pcall(function()
            if (not hasIsFolder) or (not isfolder("AA_SmartFarm")) then
                makefolder("AA_SmartFarm")
            end
        end)
        pcall(function()
            if (not hasIsFolder) or (not isfolder(MATCH_LOG_DIR)) then
                makefolder(MATCH_LOG_DIR)
            end
        end)
        return true
    end

    local function matchLogSanitizeName(raw)
        local s = tostring(raw or "match")
        s = string.gsub(s, "[^%w_%-]", "_")
        if #s == 0 then
            s = "match"
        end
        if #s > 48 then
            s = string.sub(s, 1, 48)
        end
        return s
    end

    local function matchLogReadUnitRow(u)
        local st = u._stats
        local uid = st and st.id and tostring(st.id.Value) or "unknown"
        local lvl = st and st.upgrade and (tonumber(st.upgrade.Value) or 0) or 0
        local tgt = st and st.priority and tostring(st.priority.Value) or "first"
        local pos = u:GetPivot().Position
        local dps = 0
        if Match.liveDps then
            local okD, dVal = pcall(Match.liveDps, u, uid)
            if okD and cardIsFinite(tonumber(dVal)) then
                dps = cardRound(tonumber(dVal), 1)
            end
        end
        local isFarm = (Units and Units.isFarm and Units.isFarm(uid)) == true
        local isBuff = (Units and Units.allyBuff and Units.allyBuff(uid) ~= nil) == true
        return {
            id = uid,
            level = lvl,
            target = tgt,
            x = cardRound(pos.X, 2),
            z = cardRound(pos.Z, 2),
            dps = dps,
            farm = isFarm,
            buff = isBuff
        }
    end

    local function matchLogSnapshotPlacements()
        local out = {}
        if not (Match and type(Match.mine) == "table") then
            return out
        end
        local lim = #Match.mine
        if lim > MATCH_LOG_MAX_PLACEMENTS then
            lim = MATCH_LOG_MAX_PLACEMENTS
        end
        for i = 1, lim do
            local u = Match.mine[i]
            if u ~= nil then
                local okRow, row = pcall(matchLogReadUnitRow, u)
                if okRow and type(row) == "table" then
                    out[#out + 1] = row
                end
            end
        end
        return out
    end

    local function matchLogEnsureInit()
        if AI._matchLog ~= nil then
            return AI._matchLog
        end
        if not Match then
            return nil
        end
        local ld = type(Match.ld) == "table" and Match.ld or {}
        local mapId = tostring(ld.map or "unknown")
        local mapName = mapId
        pcall(function()
            if Core and Core.data then
                local maps = Core.data("Maps")
                if type(maps) == "table" and type(maps[mapId]) == "table" and maps[mapId].name then
                    mapName = tostring(maps[mapId].name)
                end
            end
        end)
        local teamOut = {}
        if type(Match.team) == "table" then
            for i = 1, math.min(6, #Match.team) do
                local m = Match.team[i]
                if type(m) == "table" and m.id then
                    local uid = tostring(m.id)
                    local uname = uid
                    if Units and Units.name then
                        local okN, nm = pcall(Units.name, uid)
                        if okN and nm then
                            uname = tostring(nm)
                        end
                    end
                    teamOut[#teamOut + 1] = {
                        id = uid,
                        name = uname,
                        farm = (Units and Units.isFarm and Units.isFarm(uid)) == true,
                        buff = (Units and Units.allyBuff and Units.allyBuff(uid) ~= nil) == true
                    }
                end
            end
        end
        local nowClk = os.clock()
        AI._matchLog = {
            version = AI.VERSION,
            map = mapId,
            mapName = mapName,
            level = tostring(ld.id or ""),
            mode = tostring(Match.kind or ld._gamemode or "unknown"),
            difficulty = tostring(ld._difficulty or "Normal"),
            startClock = tonumber(Match.startClock) or nowClk,
            startTs = os.time(),
            lastTickClock = -9999.0,
            lastWave = -1,
            waveStartClock = nowClk,
            team = teamOut,
            placements = {},
            wavesByNum = {},
            waveOrder = {},
            fhPicksSeen = 0
        }
        return AI._matchLog
    end

    local function matchLogGetWaveRow(log, waveNum, nowClk)
        local row = log.wavesByNum[waveNum]
        if row then
            return row
        end
        if #log.waveOrder >= MATCH_LOG_MAX_WAVES then
            return log.wavesByNum[log.waveOrder[#log.waveOrder]]
        end
        row = {
            w = waveNum,
            maxProg = 0.0,
            enemiesPeak = 0,
            hpPeak = 0.0,
            yen = 0,
            clearSec = 0.0,
            bosses = 0,
            flyers = 0,
            cardsPicked = {},
            _startClock = nowClk
        }
        log.wavesByNum[waveNum] = row
        log.waveOrder[#log.waveOrder + 1] = waveNum
        return row
    end

    function AI.recordCardPick(waveNum, label)
        if not (Config and Config.matchLogger == true) then
            return
        end
        local log = matchLogEnsureInit()
        if not log then
            return
        end
        local w = tonumber(waveNum) or (Match and Match.wave and Match.wave()) or 0
        local row = matchLogGetWaveRow(log, w, os.clock())
        if row and #row.cardsPicked < MATCH_LOG_MAX_CARDS_PER_WAVE then
            row.cardsPicked[#row.cardsPicked + 1] = tostring(label or "card")
        end
    end

    function AI.logMatchTick()
        if not Config or Config.matchLogger ~= true or AI._matchLogFlushed or not Match then
            return false
        end
        local log = matchLogEnsureInit()
        if not log then
            return false
        end

        local nowClk = os.clock()
        local curWave = 0
        if Match.wave then
            local okW, wv = pcall(Match.wave)
            if okW and cardIsFinite(tonumber(wv)) then
                curWave = math.floor(tonumber(wv))
            end
        end

        local waveChanged = (curWave ~= log.lastWave)
        if (not waveChanged) and (nowClk - log.lastTickClock) < MATCH_LOG_TICK_INTERVAL then
            return false
        end

        -- Close previous wave clearSec when wave advances
        if waveChanged and log.lastWave >= 0 then
            local prevRow = log.wavesByNum[log.lastWave]
            if prevRow then
                prevRow.clearSec = cardRound(math.max(0.0, nowClk - (prevRow._startClock or log.waveStartClock)), 2)
            end
            log.waveStartClock = nowClk
        end

        log.lastTickClock = nowClk
        log.lastWave = curWave

        local row = matchLogGetWaveRow(log, curWave, nowClk)
        if not row then
            return false
        end

        -- Sync any server-confirmed picks not yet recorded
        if type(Match.fhPicks) == "table" and #Match.fhPicks > log.fhPicksSeen then
            for i = log.fhPicksSeen + 1, #Match.fhPicks do
                if #row.cardsPicked < MATCH_LOG_MAX_CARDS_PER_WAVE then
                    local pTxt = tostring(Match.fhPicks[i])
                    local dup = false
                    for j = 1, #row.cardsPicked do
                        if row.cardsPicked[j] == pTxt then
                            dup = true
                            break
                        end
                    end
                    if not dup then
                        row.cardsPicked[#row.cardsPicked + 1] = pTxt
                    end
                end
            end
            log.fhPicksSeen = #Match.fhPicks
        end

        -- Passive enemy scan telemetry (zero game-state mutation)
        local enemies = type(Match.enemies) == "table" and Match.enemies or {}
        local eCount = #enemies
        if eCount > row.enemiesPeak then
            row.enemiesPeak = eCount
        end
        local bossesNow, flyersNow = 0, 0
        local hpSum = 0.0
        for i = 1, eCount do
            local e = enemies[i]
            if type(e) == "table" then
                local pr = tonumber(e.prog) or 0.0
                if pr > row.maxProg then
                    row.maxProg = cardRound(cardClamp01(pr), 4)
                end
                if e.boss then
                    bossesNow = bossesNow + 1
                end
                if e.fly then
                    flyersNow = flyersNow + 1
                end
                hpSum = hpSum + (tonumber(e.hp) or 0.0)
            end
        end
        if bossesNow > row.bosses then
            row.bosses = bossesNow
        end
        if flyersNow > row.flyers then
            row.flyers = flyersNow
        end
        local rawHp = tonumber(Match.hpAliveRaw) or hpSum
        if rawHp > row.hpPeak then
            row.hpPeak = cardRound(rawHp, 1)
        end

        if Match.money then
            local okM, mon = pcall(Match.money)
            if okM and cardIsFinite(tonumber(mon)) then
                row.yen = math.floor(tonumber(mon) + 0.5)
            end
        end

        row.clearSec = cardRound(math.max(0.0, nowClk - (row._startClock or nowClk)), 2)

        -- Update latest placement snapshot passively when wave, placed count, or total spent changes
        local mineCnt = type(Match.mine) == "table" and #Match.mine or 0
        local curSpent = tonumber(Match.spent) or 0
        if mineCnt > 0 and (waveChanged or mineCnt ~= log.lastMineCount or curSpent ~= log.lastSpent or #log.placements == 0) then
            log.lastMineCount = mineCnt
            log.lastSpent = curSpent
            log.placements = matchLogSnapshotPlacements()
        end

        return true
    end

    function AI.flushMatchLog(opts)
        if not (Config and Config.matchLogger == true) then
            return false, "disabled"
        end
        if AI._matchLogFlushed then
            return false, "already_flushed"
        end
        local log = AI._matchLog
        if not log then
            return false, "no_match_data"
        end
        if type(writefile) ~= "function" then
            AI._matchLogFlushed = true
            return false, "no_writefile"
        end

        local o = type(opts) == "table" and opts or {}
        local nowClk = os.clock()
        if log.lastWave >= 0 and log.wavesByNum[log.lastWave] then
            local lastRow = log.wavesByNum[log.lastWave]
            lastRow.clearSec = cardRound(math.max(0.0, nowClk - (lastRow._startClock or nowClk)), 2)
        end
        if type(Match) == "table" and type(Match.mine) == "table" and #Match.mine > 0 then
            log.placements = matchLogSnapshotPlacements()
        end

        local wavesOut = {}
        for i = 1, #log.waveOrder do
            local r = log.wavesByNum[log.waveOrder[i]]
            if r then
                wavesOut[#wavesOut + 1] = {
                    w = r.w,
                    maxProg = r.maxProg,
                    enemiesPeak = r.enemiesPeak,
                    hpPeak = r.hpPeak,
                    yen = r.yen,
                    clearSec = r.clearSec,
                    bosses = r.bosses,
                    flyers = r.flyers,
                    cardsPicked = r.cardsPicked
                }
            end
        end

        local finalWave = tonumber(o.finalWave)
        if not cardIsFinite(finalWave) then
            if Match and Match.wave then
                local okW, wv = pcall(Match.wave)
                if okW and cardIsFinite(tonumber(wv)) then
                    finalWave = math.floor(tonumber(wv))
                end
            end
        end
        if not cardIsFinite(finalWave) then
            finalWave = math.max(0, log.lastWave)
        end

        local durSec = tonumber(o.durationSec)
        if not cardIsFinite(durSec) then
            durSec = math.max(0.0, nowClk - (log.startClock or nowClk))
        end

        local baseHpEnd = 1.0
        if AI.getBaseHpFrac then
            local okHp, hpF = pcall(AI.getBaseHpFrac)
            if okHp and cardIsFinite(tonumber(hpF)) then
                baseHpEnd = cardClamp01(tonumber(hpF))
            end
        end

        local payload = {
            version = AI.VERSION,
            ts = os.time(),
            map = log.map,
            mapName = log.mapName,
            level = log.level,
            mode = log.mode,
            difficulty = log.difficulty,
            won = (o.won == true),
            finalWave = finalWave,
            durationSec = cardRound(durSec, 2),
            leaks = tonumber(AI._leakEvents) or 0,
            baseHpEnd = cardRound(baseHpEnd, 4),
            reason = tostring(o.reason or "end"),
            team = log.team,
            placements = log.placements,
            waves = wavesOut
        }

        local okEnc, jsonStr = pcall(function()
            return HttpService:JSONEncode(payload)
        end)
        if not okEnc or type(jsonStr) ~= "string" or #jsonStr == 0 then
            AI._matchLogFlushed = true
            return false, "json_encode_failed"
        end

        matchLogEnsureFolders()
        local safeMap = matchLogSanitizeName(log.map)
        local tsNow = os.time()
        AI._matchLogSeq = (AI._matchLogSeq or 0) + 1
        local outPath = string.format("%s/%s_%d.json", MATCH_LOG_DIR, safeMap, tsNow)
        if type(isfile) == "function" then
            local okEx, exists = pcall(isfile, outPath)
            if okEx and exists then
                outPath = string.format("%s/%s_%d_%d.json", MATCH_LOG_DIR, safeMap, tsNow, AI._matchLogSeq)
            end
        end

        local okWr, wrErr = pcall(writefile, outPath, jsonStr)
        AI._matchLogFlushed = true
        if not okWr then
            if App and App.log then
                App.log(2, "MATCH_LOG", "Failed writing telemetry (" .. tostring(wrErr) .. ")")
            end
            return false, tostring(wrErr)
        end
        if App and App.log then
            App.log(2, "MATCH_LOG", string.format("Saved match telemetry -> %s (%d bytes, %d waves, won=%s)", outPath, #jsonStr, #wavesOut, tostring(payload.won)))
        end
        return true, outPath
    end

    -- Expose AI on Core so earlier lexical scopes (e.g. Simulator.bestTeam) can access AI cleanly
    if Core then
        Core.AI = AI
    end
end

Match.refused, Match.spent, Match.actions = {
}, 0, {
}
Match.waveMax = {
}

function Match.mapKey()
    return tostring(Match.ld and Match.ld.map or "?") .. (Match.laneCut and ("#L" .. Match.laneCut) or "")
end

function Match.label()
    if Match.kind == "dungeon" then
        local depth = type(Match.ld._dungeon) == "table" and Match.ld._dungeon.depth or "?"
        return string.format("Dungeon room %s/%d · %s", tostring(depth), Dungeon.ROOMS, tostring(Match.ld._location_name or Match.ld.map or "?"))
    end
    return Modes.levelName(Match.ld.id or "?") .. (Match.ld._difficulty and (" (" .. Match.ld._difficulty .. ")") or "")
end

function Match.money()
    local stats = LocalPlayer:FindFirstChild("_stats")
    return stats and stats.resource.Value or 0
end

function Match.wave()
    return workspace:FindFirstChild("_wave_num") and workspace._wave_num.Value or 0
end

function Match.buildPath()
    Match.samples = {}
    Match.segments = {}
    Match._sampleGrid = {}
    Match._spatialGrid = {}
    Match._segGrid = {}
    Match._staticCache = {}
    local value = Core.PATH and Core.PATH.PATH_CACHE and Core.PATH.PATH_CACHE [workspace._BASES.pve]
    if not value then
        return
    end
    for key, val in pairs(value) do
        if not (Core.PATH.HIDDEN_MOCK_LANES and Core.PATH.HIDDEN_MOCK_LANES [key.Name]) then
            local list = {}
            for _, point in ipairs(val.points or {}) do
                table.insert(list, point.part.Position)
            end
            local count = 0
            for i = 2, # list do
                count = count + (list [i] - list [i - 1]).Magnitude
            end
            local count2 = 0
            for i = 2, # list do
                local item, item2 = list [i - 1], list [i]
                local magnitude = (item2 - item).Magnitude
                local numSamples = math.max(1, math.floor(magnitude / 2))
                local segProgA = count2 / math.max(1, count)
                local segProgB = (count2 + magnitude) / math.max(1, count)
                local Ux = item2.X - item.X
                local Uz = item2.Z - item.Z
                local L2 = Ux * Ux + Uz * Uz
                if L2 > 0.001 then
                    local seg = {
                        A = item,
                        B = item2,
                        Ux = Ux,
                        Uz = Uz,
                        L2 = L2,
                        progA = segProgA,
                        progB = segProgB,
                        lane = key.Name,
                        minX = math.min(item.X, item2.X),
                        maxX = math.max(item.X, item2.X),
                        minZ = math.min(item.Z, item2.Z),
                        maxZ = math.max(item.Z, item2.Z),
                    }
                    table.insert(Match.segments, seg)
                    local S = 24
                    local c1x = math.floor(seg.minX / S)
                    local c2x = math.floor(seg.maxX / S)
                    local c1z = math.floor(seg.minZ / S)
                    local c2z = math.floor(seg.maxZ / S)
                    for cx = c1x, c2x do
                        for cz = c1z, c2z do
                            local k = cx .. "," .. cz
                            local b = Match._segGrid[k]
                            if not b then b = {}; Match._segGrid[k] = b end
                            table.insert(b, #Match.segments)
                        end
                    end
                end
                for idx = 0, numSamples - 1 do
                    local lerp = item:Lerp(item2, idx / numSamples)
                    table.insert(Match.samples, {
                        pos = lerp,
                        flat = Utils.flat(lerp),
                        prog = (count2 + magnitude * idx / numSamples) / math.max(1, count),
                        lane = key.Name
                    })
                end
                count2 = count2 + magnitude
            end
            if list [# list] then
                table.insert(Match.samples, {
                    pos = list [# list],
                    flat = Utils.flat(list [# list]),
                    prog = 1,
                    lane = key.Name
                })
            end
        end
    end
    Match.laneCut, Match.laneWant, Match.laneFirst = nil, nil, nil
    local portalLanes = tonumber(Match.ld and Match.ld._portal_lanes)
    local laneList = Simulator.laneList(Match.samples)
    if portalLanes and portalLanes >= 1 and laneList and # laneList > portalLanes then
        Match.laneWant = portalLanes
    end
    Match.laneTotal = laneList and # laneList or 1
    local SPATIAL_CELL = 20
    for sIdx, sEntry in ipairs(Match.samples) do
        local gx = math.floor(sEntry.pos.X / 12)
        local gz = math.floor(sEntry.pos.Z / 12)
        local gKey = gx .. "," .. gz
        local bucket = Match._sampleGrid[gKey]
        if not bucket then
            bucket = {}
            Match._sampleGrid[gKey] = bucket
        end
        table.insert(bucket, sIdx)
        local cx = math.floor(sEntry.pos.X / SPATIAL_CELL)
        local cz = math.floor(sEntry.pos.Z / SPATIAL_CELL)
        local cellKey = (cx + 2048) * 4096 + (cz + 2048)
        local sBucket = Match._spatialGrid[cellKey]
        if not sBucket then
            sBucket = {}
            Match._spatialGrid[cellKey] = sBucket
        end
        table.insert(sBucket, sIdx)
    end
    Match.countLanes()
end

function Match.samplesInRange(flatPos, range)
    local res = {}
    local grid = Match._spatialGrid
    local rSq = range * range
    local px, pz = flatPos.X, flatPos.Z
    if grid then
        local S = 20
        local minCx = math.floor((px - range) / S)
        local maxCx = math.floor((px + range) / S)
        local minCz = math.floor((pz - range) / S)
        local maxCz = math.floor((pz + range) / S)
        for cx = minCx, maxCx do
            for cz = minCz, maxCz do
                local cellKey = (cx + 2048) * 4096 + (cz + 2048)
                local bucket = grid[cellKey]
                if bucket then
                    for _, sIdx in ipairs(bucket) do
                        local s = Match.samples[sIdx]
                        local dx = s.pos.X - px
                        local dz = s.pos.Z - pz
                        if dx * dx + dz * dz <= rSq then
                            table.insert(res, s)
                        end
                    end
                end
            end
        end
        return res
    end
    for _, s in ipairs(Match.samples or {}) do
        local dx = s.pos.X - px
        local dz = s.pos.Z - pz
        if dx * dx + dz * dz <= rSq then
            table.insert(res, s)
        end
    end
    return res
end

function Match.countLanes()
    local list, count, count2 = {
    }, 0, 0
    for _, sample in ipairs(Match.samples) do
        local lane = tostring(sample.lane)
        if not list [lane] then
            count = count + 1
        end
        list [lane] = (list [lane] or 0) + 1
        count2 = count2 + 1
    end
    Match.laneCount = {
        n = count,
        by = list,
        avg = count > 0 and count2 / count or 1
    }
end

function Match.portalLanes()
    if not Match.laneWant or Match.laneCut then
        return true
    end
    if Match.planning then
        return false
    end
    local list, count = {
    }, 0
    for _, child in ipairs(workspace._UNITS:GetChildren()) do
        local stats = child:FindFirstChild("_stats")
        if stats and stats:FindFirstChild("player") and stats.player.Value == nil and stats:FindFirstChild("lane") and child:FindFirstChild("HumanoidRootPart") then
            local laneValue = tostring(stats.lane.Value)
            if not list [laneValue] then
                list [laneValue] = true
                count = count + 1
            end
        end
    end
    if count == 0 then
        if Utils.now() - (Match.startT or Utils.now()) > 45 then
            Match.laneWant = nil
            App.log(1, "MATCH", "no enemy seen in 45 s: placing for every lane")
            return true
        end
        return false
    end
    Match.laneFirst = Match.laneFirst or Utils.now()
    if count < Match.laneWant and Utils.now() - Match.laneFirst < 10 then
        return false
    end
    local list2, list3 = {
    }, {
    }
    for _, sample in ipairs(Match.samples) do
        if list [tostring(sample.lane)] then
            table.insert(list2, sample)
        end
    end
    if # list2 == 0 then
        Match.laneWant = nil
        return true
    end
    for itemKey in pairs(list) do
        table.insert(list3, itemKey)
    end
    table.sort(list3)
    Match.samples, Match.laneCut = list2, table.concat(list3, "+")
    Match.countLanes()
    local ok, res = pcall(Match.buildCandidates)
    if not ok then
        App.log(1, "ERROR", "spots on the portal's lane: " .. tostring(res))
    end
    App.log(1, "MATCH", string.format("this portal opens %d of the map's lanes, and the enemies walk lane %s: placing there", Match.laneWant, Match.laneCut))
    if Match.info and Config.simSpots and not Match.joinedMid and not Match.random and not Match.infinite and not Match.trialId then
        Match.planning = Utils.now()
        task.spawn(function()
            local ok, res = pcall(Match.planSpots)
            Match.planning = nil
            if not ok then
                App.log(1, "ERROR", "spot search: " .. tostring(res))
            end
        end)
    end
    return true
end

function Match.buildWaves()
    local ld = Match.ld
    local overrideWaves = ld and ld._dungeon and type(ld._override_waves) == "table" and ld._override_waves or nil
    local wave = ld and Core.Waves [(overrideWaves and overrideWaves.template) or ld.waves or ld.id]
    local overrideWaves
    if type(wave) == "table" then
        overrideWaves = wave.override_waves or wave.waves
        if not overrideWaves and wave.template and Core.Waves [wave.template] then
            overrideWaves = Core.Waves [wave.template].waves or Core.Waves [wave.template].override_waves
        end
    end
    Match.waveList = Utils.list(overrideWaves)
    Match.infinite = ld and (ld._gamemode == "infinite" or ld.infinite) and Simulator.unbound(ld) or false
    if Match.infinite then
        Match.waveList = {
        }
        Match.total = math.max(30, math.floor(Modes.infReach(Match.key) + 0.5))
        return
    end
    Match.total = (ld and type(ld._dungeon) == "table" and 15) or tonumber(ld and ld._override_infinite_bound_waves) or Simulator.boundEnd(ld, # Match.waveList, Match.key) or (# Match.waveList > 0 and # Match.waveList) or 15
end

function Match.infExtend()
    if Match.infinite and Match.wave() + 8 > Match.total then
        Match.total = Match.wave() + 14
    end
end

function Match.infWave(arg1)
    Match.infExtend()
    if Config.trainLeave and not Match.stopping then
        local ok, res = pcall(Match.trainLeave, arg1)
        if not ok then
            App.log(1, "ERROR", "leave when trained: " .. tostring(res))
        end
    end
    -- With Auto Play off nothing starts after this run, so ending it early would only throw the run away.
    if Config.infiniteStop and Config.master and Config.play and not Match.stopping then
        local ok, res = pcall(Match.infStop, arg1)
        if not ok then
            App.log(1, "ERROR", "Infinite stop: " .. tostring(res))
        end
    end
    local infTier = Modes.infTier(arg1 - 1)
    if infTier <= 0 or infTier == Match.infTierSeen then
        return
    end
    Match.infTierSeen = infTier
    task.delay(5, function()
        if not App.alive then
            return
        end
        local prof = Core.prof()
        local dailyInfiniteRewardClaim = prof and prof.daily_infinite_reward_claims and prof.daily_infinite_reward_claims [Match.ld.id]
        local value = type(dailyInfiniteRewardClaim) == "table" and (tonumber(dailyInfiniteRewardClaim.highest_claimed_wave) or 0) >= infTier and os.time() - (tonumber(dailyInfiniteRewardClaim.highest_claim_time) or 0) < 900
        if value then
            Brain.infLive = true
        end
        App.log(1, "MATCH", string.format("Infinite: wave %d passed — daily gems %s", infTier, value and "claimed now" or "not in your profile yet (paid at the end?)"))
    end)
end

-- Infinite, wave by wave: what going on is still worth. From this mode's own past runs: the gems a run
-- ended with by the wave it reached (averaged per wave reached, never falling with more waves), and how
-- many runs that got this far went k waves further. For k = 1..LOOK waves ahead: expected extra gems /
-- the minutes those waves take at this run's pace. The best of those rates is compared with the best
-- other mode; looking several waves ahead keeps a weak wave from ending the run just before a big pay.
Match.INF_RUNS, Match.INF_LOOK, Match.INF_MIN_RUNS = 40, 10, 5

function Match.infMarginal(runs, wave, minPerWave)
    if type(runs) ~= "table" or # runs < Match.INF_MIN_RUNS or not (minPerWave and minPerWave > 0) then
        return nil
    end
    local byWave = {
    }
    local top = 0
    for _, run in ipairs(runs) do
        local w = math.floor(tonumber(run.w) or 0)
        if w > 0 then
            byWave [w] = byWave [w] or {
                sum = 0,
                n = 0
            }
            byWave [w].sum, byWave [w].n = byWave [w].sum + (tonumber(run.g) or 0), byWave [w].n + 1
            top = math.max(top, w)
        end
    end
    -- Gems by the wave reached: running average, kept from falling with more waves.
    local gems, last = {
    }, 0
    for w = 1, top do
        if byWave [w] then
            last = math.max(last, byWave [w].sum / byWave [w].n)
        end
        gems [w] = last
    end
    local function reached(w)
        local n = 0
        for _, run in ipairs(runs) do
            if (tonumber(run.w) or 0) >= w then
                n = n + 1
            end
        end
        return n
    end
    local here = reached(wave)
    if here < 2 then
        return nil
    end
    local now = gems [math.min(wave, top)] or 0
    local best, bestK
    for k = 1, Match.INF_LOOK do
        local w = wave + k
        if w > top then
            break
        end
        local survive = reached(w) / here
        local gain = survive * math.max(0, gems [w] - now)
        local rate = gain / (k * minPerWave)
        if not best or rate > best then
            best, bestK = rate, k
        end
    end
    return best, bestK, here
end

-- Infinite (2.23): how many more waves a farm can earn for. The match's own wave count there is a
-- rolling horizon (the wave + 14), not where runs end; this mode's past runs that got this far say how
-- many waves they went on, on average (the exit rule included). nil until enough runs are known.
function Match.infLeft(runs, wave)
    if type(runs) ~= "table" or # runs < Match.INF_MIN_RUNS then
        return nil
    end
    local sum, n = 0, 0
    for _, run in ipairs(runs) do
        local reached = tonumber(run.w) or 0
        if reached >= wave then
            sum, n = sum + (reached - wave), n + 1
        end
    end
    if n < 2 then
        return nil
    end
    return sum / n
end

function Match.infStop(arg1)
    local count = 0
    for _, item in ipairs(Utils.list(Core.GS.DAILY_INFINITE_REWARDS)) do
        count = math.max(count, tonumber(item.wave) or 0)
    end
    if count <= 0 or arg1 <= count + 1 then
        return
    end
    local on = Brain.train.on
    if Match.trainee and on and on.have + (on.got or 0) + (Match.trainTk or 0) < on.need then
        return
    end
    if not FarmHub.every("infStop", 60) then
        return
    end
    local rec = Modes.rec(Match.key)
    local timed = tonumber(rec.timed) or 0
    local value = (timed > 0 and (rec.sec or 0) > 0) and math.max(0.5, ((rec.gems or 0) - 200 * timed) / (rec.sec / 60)) or 2.5
    local ok = pcall(Modes.pick)
    local value2
    for _, value in ipairs(ok and Modes.lastScored or {
    }) do
        if value.kind ~= "infinite" and (not value2 or (value.score or 0) > (value2.score or 0)) then
            value2 = value
        end
    end
    -- With enough past runs, what the rest of this run is worth replaces the mode's past average.
    local elapsedMin = (os.clock() - (Match.startClock or os.clock())) / 60
    local marginal, ahead, runsHere = Match.infMarginal(Brain.infRuns and Brain.infRuns [Match.key], arg1, arg1 > 0 and elapsedMin / arg1 or nil)
    if marginal then
        value = marginal
    end
    if not value2 or (value2.score or 0) <= value then
        if marginal and FarmHub.every("infKeep", 300) then
            App.log(1, "MATCH", string.format("Infinite: wave %d — going on: ≈%.2f gems/min over the next %d waves (from %d past runs that got this far), the best other mode gives %.2f", arg1, marginal, ahead or 0, runsHere or 0, value2 and value2.score or 0))
        end
        return
    end
    Match.stopping = true
    App.log(1, "MATCH", string.format("Infinite: wave %d, the daily gems are in and no unit trains here — ending the run (≈%.1f gems/min from here%s, %.1f in %s): selling your units", arg1, value, marginal and string.format(" over the next %d waves, from %d past runs", ahead or 0, runsHere or 0) or " (this mode's average)", value2.score, value2.label))
    Match.sellAll()
end

function Match.trainLeave(arg1)
    local on = Brain.train.on
    if not (Match.infinite and Match.trainee and on) then
        return
    end
    Match.trainCount()
    local have = on.have + (on.got or 0) + (Match.trainTk or 0)
    if have < on.need then
        return
    end
    local ok, res, res2 = pcall(Modes.infDaily, Core.prof(), Match.ld.id, (Modes.infReach(Match.key)))
    if ok and (res or 0) > 0 and res2 > 0 and arg1 <= res2 then
        App.status("Training", string.format("%s has its %s: playing to wave %d for the daily gems, then ending the run", Units.name(on.id), on.what, res2))
        return
    end
    Match.stopping = true
    App.log(1, "MATCH", string.format("Infinite: %s has its %s (%s of %s) — ending the run at wave %d so it can evolve: selling your units", Units.name(on.id), on.what, Utils.fmt(have), Utils.fmt(on.need), arg1))
    Match.sellAll()
end

function Match.sellAll()
    task.spawn(function()
        local list = {
        }
        for _, unit in ipairs(Match.mine or {
        }) do
            local stats = unit:FindFirstChild("_stats")
            local unit2 = stats and stats:FindFirstChild("id") and Core.Units [stats.id.Value]
            if not (unit2 and unit2.unsellable) then
                table.insert(list, unit)
            end
        end
        local function helper(inst)
            local stats = inst:FindFirstChild("_stats")
            return stats and stats:FindFirstChild("id") and Units.isFarm(stats.id.Value) or false
        end
        table.sort(list, function(arg1, arg2)
            return (helper(arg1) and 1 or 0) < (helper(arg2) and 1 or 0)
        end)
        local list2 = {
        }
        for i = 1, 2 do
            local list3 = {
            }
            for _, item in ipairs(i == 1 and list or list2) do
                if not App.alive or Match.finished then
                    return
                end
                if item.Parent and item.Parent.Name == "_UNITS" then
                    local _, res = App.request("sell", "sell_unit_ingame", item)
                    if res ~= true then
                        table.insert(list3, item)
                    end
                    task.wait(1.3)
                end
            end
            list2 = list3
        end
        if # list2 > 0 then
            local list = {
            }
            for _, item in ipairs(list2) do
                table.insert(list, item.Name)
            end
            App.log(1, "MATCH", "the game didn't sell " .. table.concat(list, ", ") .. " (the run still ends: nothing else is defending)")
        end
    end)
end

function Match.waveReward(i)
    if Match.info then
        return Simulator.waveYen(Match.info, i)
    end
    local value = Match.waveList and Match.waveList [i]
    return (value and tonumber(value.wave_reward) or 0) * 2.6
end

function Match.progressAt(position)
    local flat = Utils.flat(position)
    local px, pz = flat.X, flat.Z
    local bestProg, bestDistSq, bestLane = 0, math.huge, nil
    local segs = Match.segments
    if segs and #segs > 0 then
        local grid = Match._segGrid
        local S = 24
        local cx = math.floor(px / S)
        local cz = math.floor(pz / S)
        local checked = {}
        for dx = -1, 1 do
            for dz = -1, 1 do
                local bucket = grid and grid[(cx + dx) .. "," .. (cz + dz)]
                if bucket then
                    for _, segIdx in ipairs(bucket) do
                        if not checked[segIdx] then
                            checked[segIdx] = true
                            local seg = segs[segIdx]
                            local Ux, Uz, L2 = seg.Ux, seg.Uz, seg.L2
                            local t = ((px - seg.A.X) * Ux + (pz - seg.A.Z) * Uz) / L2
                            local tClamp = t < 0 and 0 or (t > 1 and 1 or t)
                            local projX = seg.A.X + tClamp * Ux
                            local projZ = seg.A.Z + tClamp * Uz
                            local dxp, dzp = px - projX, pz - projZ
                            local distSq = dxp * dxp + dzp * dzp
                            if distSq < bestDistSq then
                                bestDistSq = distSq
                                bestProg = seg.progA + tClamp * (seg.progB - seg.progA)
                                bestLane = seg.lane
                            end
                        end
                    end
                end
            end
        end
        if bestDistSq < math.huge then
            return bestProg, math.sqrt(bestDistSq), bestLane ~= nil and tostring(bestLane) or nil
        end
        for _, seg in ipairs(segs) do
            local Ux, Uz, L2 = seg.Ux, seg.Uz, seg.L2
            local t = ((px - seg.A.X) * Ux + (pz - seg.A.Z) * Uz) / L2
            local tClamp = t < 0 and 0 or (t > 1 and 1 or t)
            local projX = seg.A.X + tClamp * Ux
            local projZ = seg.A.Z + tClamp * Uz
            local dxp, dzp = px - projX, pz - projZ
            local distSq = dxp * dxp + dzp * dzp
            if distSq < bestDistSq then
                bestDistSq = distSq
                bestProg = seg.progA + tClamp * (seg.progB - seg.progA)
                bestLane = seg.lane
            end
        end
        return bestProg, bestDistSq < math.huge and math.sqrt(bestDistSq) or math.huge, bestLane ~= nil and tostring(bestLane) or nil
    end
    for _, sample in ipairs(Match.samples or {}) do
        local dxp, dzp = sample.pos.X - px, sample.pos.Z - pz
        local distSq = dxp * dxp + dzp * dzp
        if distSq < bestDistSq then
            bestDistSq, bestProg, bestLane = distSq, sample.prog, sample.lane
        end
    end
    return bestProg, bestDistSq < math.huge and math.sqrt(bestDistSq) or math.huge, bestLane ~= nil and tostring(bestLane) or nil
end

function Match.scan()
    local allies = {}
    local list, list2 = {
    }, {
    }
    for _, inst in ipairs({
        workspace._UNITS
    }) do
        for _, child in ipairs(inst:GetChildren()) do
            local stats = child:FindFirstChild("_stats")
            if stats and stats:FindFirstChild("player") then
                local parentUnit = stats:FindFirstChild("parent_unit")
                local parentUnitValue = parentUnit and parentUnit.Value
                local stats2 = parentUnitValue and parentUnitValue:FindFirstChild("_stats")
                local unit = Core.Units [stats.id.Value]
                local flag = parentUnitValue ~= nil and unit ~= nil and (tonumber(unit.cost) or 0) >= 100 and (not stats2 or (stats2:FindFirstChild("id") and stats2.id.Value == stats.id.Value))
                if stats.id.Value == "mahoraga" or stats.id.Value == Units.FUSION.hero then
                    flag = true
                end
                local flag2 = (parentUnitValue ~= nil and not flag) or not stats:FindFirstChild("attack_cooldown") or not stats:FindFirstChild("upgrade") or not stats:FindFirstChild("range")
                if stats.player.Value == LocalPlayer then
                    if not flag2 then
                        table.insert(list2, child)
                    end
                elseif stats.player.Value ~= nil and not parentUnitValue and not flag2 and unit then
                    if not Units.isFarm(stats.id.Value) and not Units.allyBuff(stats.id.Value) then
                        table.insert(allies, child)
                    end
                elseif stats.player.Value == nil and child:FindFirstChild("HumanoidRootPart") then
                    local progressAt, _, progressAt3 = Match.progressAt(child.HumanoidRootPart.Position)
                    local humanoid = child:FindFirstChildOfClass("Humanoid")
                    local health = humanoid and humanoid.Health or (stats:FindFirstChild("health") and stats.health.Value) or 0
                    local damageReductionValue = stats:FindFirstChild("damage_reduction") and tonumber(stats.damage_reduction.Value) or 0
                    local value = Match.info and Match.info.cfgById [stats.id.Value]
                    local flag = stats:FindFirstChild("Flying") and (tonumber(stats.Flying.Value) or 0) > 0 or false
                    local shieldValue = stats:FindFirstChild("shield") and tonumber(stats.shield.Value) or 0
                    table.insert(list, {
                        m = child,
                        pos = child.HumanoidRootPart.Position,
                        prog = progressAt,
                        lane = progressAt3,
                        hp = health,
                        red = damageReductionValue,
                        fly = flag,
                        sh = shieldValue,
                        boss = value and tostring(value):find("boss") ~= nil or false
                    })
                    if tostring(stats.id.Value):find("^star_golem") then
                        pcall(Match.noteStar, child, humanoid)
                    end
                end
            end
        end
    end
    Match.enemies, Match.mine, Match.allies = list, list2, allies
    if not Match.flyerSeen then
        for _, item in ipairs(list) do
            if item.fly then
                Match.flyerSeen = math.max(1, Match.wave())
                if not Match.random then
                    App.log(1, "MATCH", string.format("flyers from wave %d: units that hit them get more of the yen now", Match.flyerSeen))
                end
                break
            end
        end
    end
    if not Match.shieldSeen then
        for _, item in ipairs(list) do
            if (item.sh or 0) > 0 then
                Match.shieldSeen = true
                local stats = item.m._stats
                App.log(1, "MATCH", string.format("enemy shield seen at wave %d: %s (its most %s), %s, %.3g HP · the simulator has +%s on every enemy", Match.wave(), tostring(item.sh), tostring(stats:FindFirstChild("max_shield") and stats.max_shield.Value), tostring(stats:FindFirstChild("id") and stats.id.Value), item.hp, tostring(Match.info and Match.info.shield)))
                break
            end
        end
    end
    local wave = Match.wave()
    local count = 0
    local count2, count3, count4 = 0, 0, 0
    for _, item in ipairs(list) do
        count = math.max(count, item.prog)
        count2 = count2 + item.hp / math.max(0.1, 1 - item.red)
        count4 = count4 + item.hp
    end
    Match.hpAliveRaw = count4
    for _, item in ipairs(list2) do
        local idValue = item._stats.id.Value
        if not Units.isFarm(idValue) and item._stats:FindFirstChild("damage") then
            local ok, res = pcall(Match.liveDps, item, idValue)
            if ok and res then
                count3 = count3 + res
            end
        end
    end
    Match.hpAlive, Match.teamDps = count2, count3
    Match.clearSec = count2 > 0 and (count3 > 0 and count2 / count3 or math.huge) or 0
    Match.waveMax [wave] = math.max(Match.waveMax [wave] or 0, count)
    Match.front = count
    Match.pressure = math.max(Match.waveMax [wave] or 0, Match.waveMax [wave - 1] or 0)
    Match.depth = Match.coverage(list2, list)
    -- 2.29: what the flyers really did this match (for Match.airCalm): seconds with flyers alive, how far they got
    do
        local now, flying = Utils.now(), false
        for _, item in ipairs(list) do
            if item.fly and (item.hp or 0) > 0 then
                flying = true
                Match.airFar = math.max(Match.airFar or 0, item.prog or 0)
            end
        end
        if flying and Match.airSeenAt then
            Match.airTime = (Match.airTime or 0) + math.min(2, math.max(0, now - Match.airSeenAt))
        end
        Match.airSeenAt = flying and now or nil
    end
    local now = Utils.now()
    Match.aliveHist = Match.aliveHist or {
    }
    table.insert(Match.aliveHist, {
        t = now,
        n = # list
    })
    while Match.aliveHist [1] and now - Match.aliveHist [1].t > 12 do
        table.remove(Match.aliveHist, 1)
    end
    local value = Match.aliveHist [1]
    Match.piling = # list >= 8 and value and now - value.t >= 8 and # list > value.n + 1 or false
    if # list >= 18 then
        Match.piling = true
    end
end

function Match.setupChecks()
    Match.probe = Instance.new("Part")
    Match.probe.Name = "_aa_probe"
    Match.probe.Anchored = true
    Match.probe.CanCollide = false
    Match.probe.CanTouch = false
    Match.probe.CanQuery = false
    Match.probe.Transparency = 1
    Match.probe.Parent = workspace:FindFirstChild("ignore") or workspace
    local bounds = ReplicatedStorage:FindFirstChild("_bounds")
    Match.bounds = Instance.new("Folder")
    Match.bounds.Name = "_aa_bounds"
    if bounds then
        for _, desc in ipairs(bounds:GetDescendants()) do
            if desc:IsA("BasePart") then
                local clone = desc:Clone()
                for _, child in ipairs(clone:GetChildren()) do
                    child:Destroy()
                end
                clone.Anchored = true
                clone.CanCollide = false
                clone.CanTouch = false
                clone.CanQuery = true
                clone.Transparency = 1
                clone.CFrame = desc.CFrame
                clone.Parent = Match.bounds
            end
        end
    end
    Match.bounds.Parent = workspace:FindFirstChild("ignore") or workspace
    Match.overlap = OverlapParams.new()
    Match.overlap.FilterType = Enum.RaycastFilterType.Include
    Match.overlap.FilterDescendantsInstances = {
        workspace._road,
        Match.bounds
    }
end

function Match.spotKey(bestSpot)
    return string.format("%d,%d", math.floor(bestSpot.X + 0.5), math.floor(bestSpot.Z + 0.5))
end

function Match.killZone()
    return Config.killZone ~= false and (Match.style == "box" or (Match.style == nil and Match.kind == "dungeon"))
end

Match.BLOCK_DAYS = 7

function Match.blockedSpot(position)
    local spotKey = Match.spotKey(position)
    if Match.refused [spotKey] then
        return true
    end
    if AI and AI._soldSpots then
        local soldAt = AI._soldSpots[spotKey]
        if soldAt then
            if Utils.now() - soldAt < 15 then
                return true
            else
                AI._soldSpots[spotKey] = nil
            end
        end
    end
    -- 2.33: a spot the boss has already walked past (its unit was just sold to move up) stays closed for this boss
    -- (the boss focus is re-made every step and can blink off, so the ban follows the boss itself: while it is
    -- still on the field, for at most 2 minutes)
    local ban = Match.focusBan
    if ban and ban.spots [spotKey] and ban.m and ban.m.Parent and Utils.now() - ban.at < 120 then
        return true
    end
    local mapKey = Match.mapKey()
    local value = Brain.blocked [mapKey]
    if not (value and (tonumber(value [spotKey]) or 0) >= 2) then
        return false
    end
    -- A spot blocked by the server is tried again after a week (maps change with
    -- updates, and some spots were blocked when only the yen was short).
    Brain.blockedAt [mapKey] = Brain.blockedAt [mapKey] or {
    }
    local at = tonumber(Brain.blockedAt [mapKey] [spotKey])
    if not at then
        Brain.blockedAt [mapKey] [spotKey] = os.time()
        App.saveSoon()
    elseif os.time() - at > Match.BLOCK_DAYS * 86400 then
        value [spotKey] = nil
        Brain.blockedAt [mapKey] [spotKey] = nil
        App.saveSoon()
        return false
    end
    return true
end

function Match.valid(cand, data)
    local overrideHitboxRadius = (tonumber(data.override_hitbox_radius) or 1.5) + 0.25
    local cache = Match._staticCache
    local sKey = cache and string.format("%.1f,%.1f:%s:%s:%d", cand.X, cand.Z, data.hill_unit and "H" or "G", data.hybrid_placement and "Y" or "N", math.floor(overrideHitboxRadius * 10 + 0.5))
    local position
    if sKey and cache[sKey] ~= nil then
        if cache[sKey] == false then return nil end
        position = cache[sKey]
    else
        local raycast = Core.PC.raycast(cand + Vector3.new(0, 40, 0), Vector3.new(0, - 120, 0))
        if not raycast or not Core.PC.is_valid_raycast_hit(raycast.Instance, data) then
            if sKey then cache[sKey] = false end
            return nil
        end
        position = raycast.Position
        Match.probe.Size = Vector3.new(overrideHitboxRadius * 2, 2.5, overrideHitboxRadius * 2)
        Match.probe.CFrame = CFrame.new(position + Vector3.new(0, 1.35, 0))
        if # workspace:GetPartsInPart(Match.probe, Match.overlap) > 0 then
            if sKey then cache[sKey] = false end
            return nil
        end
        if sKey then cache[sKey] = position end
    end
    if Match.blockedSpot(position) then
        return nil
    end
    -- 2.34: while a boss we sold units behind is on the field, a fighter goes only where it reaches the road ahead of it
    -- (a spot behind the boss would be sold again a second later); farms and buffers are not affected
    local ban = Match.focusBan
    if ban and ban.ahead and ban.m and ban.m.Parent and Utils.now() - ban.at < 120
        and not (tonumber(data.farm_amount) or data.is_farm) then
        local reach = (tonumber(data.range) or 0) * ((Match.info and tonumber(Match.info.rangeScale)) or 1)
        local flat = Utils.flat(position)
        local ok = false
        for _, p in ipairs(ban.ahead) do
            if (p - flat).Magnitude <= reach then
                ok = true
                break
            end
        end
        if not ok then
            return nil
        end
    end
    for _, unit in ipairs(Match.mine or {
    }) do
        local hitbox = unit:FindFirstChild("_hitbox")
        local position2 = hitbox and hitbox.Position or unit:GetPivot().Position
        local ratio = hitbox and math.max(hitbox.Size.X, hitbox.Size.Z) / 2 or 1.5
        local dx, dz = position.X - position2.X, position.Z - position2.Z
        if dx * dx + dz * dz < (overrideHitboxRadius + ratio) * (overrideHitboxRadius + ratio) then
            return nil
        end
    end
    return position
end

function Match.buildCandidates()
    Match.cands = {
    }
    Match._staticCache = {}
    local list = {
    }
    for i = 1, # Match.samples, 2 do
        local sample = Match.samples [i]
        local sample2 = Match.samples [math.min(# Match.samples, i + 1)]
        local flat = Utils.flat(sample2.pos - sample.pos)
        if flat.Magnitude < 0.01 then
            flat = Vector3.new(1, 0, 0)
        end
        flat = flat.Unit
        local value = Vector3.new(- flat.Z, 0, flat.X)
        for _, value2 in ipairs({
            2.5,
            4,
            5.5,
            7.5,
            10,
            13,
            16.5,
            20.5
        }) do
            for _, value3 in ipairs({
                1,
                - 1
            }) do
                local pos = sample.pos + value * value2 * value3
                local text = string.format("%d,%d", math.floor(pos.X / 1.5), math.floor(pos.Z / 1.5))
                if not list [text] then
                    list [text] = true
                    table.insert(Match.cands, pos)
                end
            end
        end
    end
end

function Match.coverage(list, arg2)
    local list2 = {
    }
    for _, item in ipairs(list) do
        local stats = item._stats
        if not Units.isFarm(stats.id.Value) and stats:FindFirstChild("range") then
            table.insert(list2, {
                p = Utils.flat(item:GetPivot().Position),
                r = stats.range.Value * (Units.SUMMONER [stats.id.Value] and Units.SUMMONER [stats.id.Value].reach or 1),
                air = Match.canAir(item)
            })
        end
    end
    local count, count2 = 0, 0
    if # list2 > 0 then
        for _, sample in ipairs(Match.samples) do
            if sample.prog > count2 then
                local flat = (sample.flat or Utils.flat(sample.pos))
                for _, item in ipairs(list2) do
                    if (flat - item.p).Magnitude <= item.r then
                        if sample.prog > count then
                            count = sample.prog
                        end
                        if item.air then
                            count2 = sample.prog
                            break
                        end
                    end
                end
            end
        end
    end
    local list, laneCount = {
    }, Match.laneCount
    if laneCount and laneCount.n >= 2 and # list2 > 0 then
        local list3 = {
        }
        for _, sample in ipairs(Match.samples) do
            local flat = (sample.flat or Utils.flat(sample.pos))
            for _, item in ipairs(list2) do
                if (flat - item.p).Magnitude <= item.r then
                    local lane = tostring(sample.lane)
                    list3 [lane] = (list3 [lane] or 0) + 1
                    if sample.prog > (list [lane] or 0) then
                        list [lane] = sample.prog
                    end
                    break
                end
            end
        end
        local list, count = {
        }, 0
        for key, value in pairs(laneCount.by) do
            list [key] = (list3 [key] or 0) / math.max(1, value)
            count = math.max(count, list [key])
        end
        Match.laneW = {
        }
        for key, value in pairs(laneCount.by) do
            Match.laneW [key] = (laneCount.avg / math.max(1, value)) * (1 + 1.5 * (count > 0 and (1 - list [key] / count) or 0))
        end
        Match.laneFrac = list
    else
        Match.laneW, Match.laneFrac = nil, nil
    end
    local prog, flag, lane
    if # list2 > 0 then
        for _, value in ipairs(arg2) do
            local item = (Match.laneW and value.lane and list [value.lane]) or count
            if value.hp > 0 and value.prog > item + 0.02 and value.prog > (prog or 0) then
                prog, lane = value.prog, Match.laneW and value.lane or nil
            end
            if value.hp > 0 and value.fly and value.prog > count2 + 0.02 then
                flag = true
            end
        end
    end
    local value = # list2 > 0 and (Match.pressure or 0) >= count - 0.08
    return {
        covEnd = count,
        airEnd = count2,
        leak = prog,
        leakLane = lane,
        covL = list,
        airLeak = flag,
        push = value,
        units = # list2
    }
end

function Match.needLastLine(unit)
    if Units.isFarm(unit.id) or Units.allyBuff(unit.id) or Match.fieldCount() < 5 then
        return false
    end
    local count, count2 = 0, 0
    for _, unit in ipairs(Match.mine or {
    }) do
        local stats = unit._stats
        if not Units.isFarm(stats.id.Value) and stats:FindFirstChild("range") then
            local flat, rangeValue = Utils.flat(unit:GetPivot().Position), stats.range.Value
            for _, sample in ipairs(Match.samples) do
                if sample.prog >= 0.85 and ((sample.flat or Utils.flat(sample.pos)) - flat).Magnitude <= rangeValue then
                    count = count + 1
                    if Match.canAir(unit) then
                        count2 = count2 + 1
                    end
                    break
                end
            end
        end
    end
    return count < 2 or (count2 < 1 and Match.flyMode() and Match.cardAir(unit.id))
end
Match.airCache = setmetatable({
}, {
    __mode = "k"
})

function Match.canAir(unit)
    local upgradeValue = unit._stats:FindFirstChild("upgrade") and unit._stats.upgrade.Value or 0
    local value = Match.airCache [unit]
    if not value or value.lvl ~= upgradeValue then
        local value2 = unit:GetAttribute("_on_hill") == true or unit:GetAttribute("_anti_air") == true
        if not value2 then
            -- 2.29: the game's own data too (summoners and hill units from level 0, an attack that hits flyers
            -- from some level): the attributes alone left summoners out, and the air check then saw no air damage.
            local idObj = unit._stats:FindFirstChild("id")
            local ok, from = pcall(Units.airFrom, idObj and idObj.Value)
            value2 = ok and type(from) == "number" and type(upgradeValue) == "number" and upgradeValue >= from
        end
        value = {
            lvl = upgradeValue,
            v = value2
        }
        Match.airCache [unit] = value
    end
    return value.v
end
Units._airFrom = {
}

function Units.airFrom(id)
    local value = Units._airFrom [id]
    if value ~= nil then
        return value or nil
    end
    local unit = Core.Units [id]
    if unit and (unit.hill_unit or unit.hybrid_placement or Units.SUMMONER [id]) then
        Units._airFrom [id] = 0
        return 0
    end
    local rows = Units.rows(id)
    if not (rows and rows.max) then
        return Match.cardAir(id) and 0 or nil
    end
    local flag = false
    for i = 0, rows.max do
        local atk = rows [i] and rows [i].atk
        if atk and Core.Attacks [atk] and Core.Attacks [atk].targets_flying then
            flag = i
            break
        end
    end
    if flag == false and Match.cardAir(id) then
        flag = 0
    end
    Units._airFrom [id] = flag
    return flag or nil
end

function Match.cardAir(id)
    local unit = Core.Units [id]
    if not unit then
        return false
    end
    if unit.hill_unit or unit.hybrid_placement then
        return true
    end
    local field = Units.field(id, "primary_attack_no_upgrades") or Units.field(id, "primary_attack")
    return field and Core.Attacks [field] and Core.Attacks [field].targets_flying and true or false
end

-- 2.29: flyers have been alive on the field for 30 s in all and none got past half the road: the forecast that the
-- team can't kill the flyers coming is not borne out, so it no longer holds back farms (leaks and pressure still count).
-- The script restarts in every match, so these fields start empty each time.
Match.AIR_CALM_SEC, Match.AIR_CALM_FAR = 30, 0.5
function Match.airCalm()
    if (Match.airTime or 0) < Match.AIR_CALM_SEC then
        return false
    end
    if (Match.airFar or 0) >= Match.AIR_CALM_FAR then
        return false
    end
    return not (Match.depth and Match.depth.airLeak)
end

function Match.airShare()
    local count, count2 = 0, 0
    for _, unit in ipairs(Match.mine or {
    }) do
        local idValue = unit._stats.id.Value
        if not Units.isFarm(idValue) then
            local ok, res = pcall(Match.liveDps, unit, idValue)
            res = ok and res or 0
            count = count + res
            if Match.canAir(unit) then
                count2 = count2 + res
            end
        end
    end
    return count > 0 and count2 / count or 0
end

-- ===== Attack shape and spot (2.20) =====
-- How many stretches of road one hit covers besides its target, from spot (px, pz) with range R.
-- Road points xs/zs/progs are evenly spaced (Match.samples, ~2 studs), so a count is a length of road.
-- The target is picked two ways, half and half: the front enemy (furthest along the road, as tower
-- games usually aim) and any enemy in range (up to 12, evenly spread). Shapes:
--   circle — around the target, radius r (not cut by the unit's range);
--   line   — from the unit toward the target, length L, half width Units.lineHalf (half the attack's
--            width when the game gives one, else Units.LINE_HALF — a guess);
--   cone   — from the unit, within R, ±angle/2 around the target's direction;
--   full_aoe is the road in range itself, already what coverage counts: no extra factor for it.
Units.LINE_HALF = 1.5

-- Half width of a line attack, the same for the spot score and for turning the unit (2.22).
-- aoe_type.width is read as the full width; without it the old guess stays.
function Units.lineHalf(width)
    width = tonumber(width)
    if width and width > 0 then
        return width / 2
    end
    return Units.LINE_HALF
end

function Units.shapeHits(shape, px, pz, R, xs, zs, progs)
    local inRange, R2 = {
    }, R * R
    for i = 1, # xs do
        local dx, dz = xs [i] - px, zs [i] - pz
        if dx * dx + dz * dz <= R2 then
            table.insert(inRange, i)
        end
    end
    if # inRange == 0 then
        return nil
    end
    local kind = shape.type
    local r2 = (shape.radius or 4) ^ 2
    local L = shape.length or R
    local half = Units.lineHalf(shape.width)
    local cosHalf = math.cos(math.rad((shape.angle or 45) / 2))
    local function covered(t)
        local tx, tz = xs [t], zs [t]
        local ux, uz = tx - px, tz - pz
        local len = math.sqrt(ux * ux + uz * uz)
        if len < 1e-6 then
            ux, uz, len = 1, 0, 1
        end
        ux, uz = ux / len, uz / len
        local n = 0
        if kind == "circle" then
            for j = 1, # xs do
                if j ~= t then
                    local dx, dz = xs [j] - tx, zs [j] - tz
                    if dx * dx + dz * dz <= r2 then
                        n = n + 1
                    end
                end
            end
        elseif kind == "line" then
            for j = 1, # xs do
                if j ~= t then
                    local vx, vz = xs [j] - px, zs [j] - pz
                    local along = vx * ux + vz * uz
                    if along >= 0 and along <= L and math.abs(vx * uz - vz * ux) <= half then
                        n = n + 1
                    end
                end
            end
        elseif kind == "cone" then
            for _, j in ipairs(inRange) do
                if j ~= t then
                    local vx, vz = xs [j] - px, zs [j] - pz
                    local d = math.sqrt(vx * vx + vz * vz)
                    if d > 1e-6 and (vx * ux + vz * uz) >= d * cosHalf then
                        n = n + 1
                    end
                end
            end
        end
        return n
    end
    local front = inRange [1]
    for _, i in ipairs(inRange) do
        if (progs [i] or 0) > (progs [front] or 0) then
            front = i
        end
    end
    local step, sum, k = math.max(1, math.floor(# inRange / 12)), 0, 0
    for index = 1, # inRange, step do
        sum, k = sum + covered(inRange [index]), k + 1
    end
    return 0.5 * covered(front) + 0.5 * sum / math.max(1, k)
end

-- Shape factor of each spot for one unit: its extra coverage over the median of all spots it can
-- stand on (1 = an ordinary spot), smoothed toward 1 and kept within 0.4..2.5. nil when the attack
-- hits one enemy, covers its whole circle anyway, or the road gives nothing to compare.
Units.SHAPE_SMOOTH, Units.SHAPE_MIN, Units.SHAPE_MAX = 0.75, 0.4, 2.5

function Units.shapeFactors(shape, spots, R, xs, zs, progs, yieldEvery)
    if not shape or shape.type == "full_aoe" or (shape.type ~= "circle" and shape.type ~= "line" and shape.type ~= "cone") then
        return nil
    end
    local raw, list = {
    }, {
    }
    for index, spot in ipairs(spots) do
        local value = Units.shapeHits(shape, spot.X, spot.Z, R, xs, zs, progs)
        if value then
            raw [spot] = value
            table.insert(list, value)
        end
        if yieldEvery and index % yieldEvery == 0 then
            task.wait()
        end
    end
    if # list < 3 then
        return nil
    end
    table.sort(list)
    local median = list [math.ceil(# list / 2)]
    if median < 0.5 then
        return nil
    end
    local factors = {
    }
    for spot, value in pairs(raw) do
        factors [spot] = Utils.clamp(1 + Units.SHAPE_SMOOTH * (value / median - 1), Units.SHAPE_MIN, Units.SHAPE_MAX)
    end
    return factors, median
end

-- ===== Attack shape outside the plan (2.22) =====
-- When a unit has no planned spot (or it is taken), and in the kill box / fast / control choices,
-- the spots that rank best by road are re-ranked by the unit's attack shape, the same way the plan
-- does: score × (1 + (n − 1)·f) / n, f = the spot's extra targets over the median spot. The median
-- comes from a fixed spread of the map's candidate spots (not the ones still free), so taking one
-- spot does not change how the others score. Per unit, shape and map it is worked out once; a spot's
-- factor is kept by its key. Only the top SHAPE_TOP spots by road are looked at.
Match.SHAPE_TOP, Match.SHAPE_SAMPLE = 12, 40

function Match.shapeInfo(unit)
    if not (unit and unit.id and unit.u and Match.samples and # Match.samples > 0 and Match.cands and # Match.cands > 0) then
        return nil
    end
    local rows = Units.rows(unit.id)
    local maxRow = rows and rows [rows.max]
    local ok, info = pcall(function()
        return maxRow and maxRow.atk and Units.attackInfo(maxRow.atk, maxRow.range)
    end)
    local shape = ok and info and info.shape
    if not shape or not ((tonumber(info.n) or 1) > 1.05) or shape.type == "full_aoe" then
        return nil
    end
    local R = Units.range(unit.u, rows.max) * ((Match.info and tonumber(Match.info.rangeScale)) or 1)
    local key = table.concat({
        tostring(unit.id),
        tostring(shape.type),
        tostring(shape.radius),
        tostring(shape.angle),
        tostring(shape.length),
        tostring(shape.width),
        string.format("%.1f", R),
        tostring(# Match.samples),
        tostring(# Match.cands)
    }, "|")
    local mapKey = Match.mapKey and Match.mapKey() or ""
    if Match.shapeMemoMap ~= mapKey or type(Match.shapeMemo) ~= "table" then
        Match.shapeMemo, Match.shapeMemoMap = {
        }, mapKey
    end
    local memo = Match.shapeMemo [key]
    if memo == nil then
        memo = false
        local xs, zs, ps = {
        }, {
        }, {
        }
        for i, sample in ipairs(Match.samples) do
            xs [i], zs [i], ps [i] = sample.pos.X, sample.pos.Z, sample.prog
        end
        local spots, step = {
        }, math.max(1, math.floor(# Match.cands / Match.SHAPE_SAMPLE))
        for i = 1, # Match.cands, step do
            table.insert(spots, Match.cands [i])
        end
        local _, median = Units.shapeFactors(shape, spots, R, xs, zs, ps, 10)
        if median then
            memo = {
                id = unit.id,
                shape = shape,
                n = tonumber(info.n),
                R = R,
                median = median,
                xs = xs,
                zs = zs,
                ps = ps,
                f = {
                }
            }
        end
        Match.shapeMemo [key] = memo
    end
    return memo or nil
end

-- The shape's multiplier for one spot (1 = an ordinary spot), and the factor f itself.
function Match.shapeMul(memo, spot)
    local k = Match.spotKey(spot)
    local f = memo.f [k]
    if f == nil then
        local hits = Units.shapeHits(memo.shape, spot.X, spot.Z, memo.R, memo.xs, memo.zs, memo.ps)
        f = hits and Utils.clamp(1 + Units.SHAPE_SMOOTH * (hits / memo.median - 1), Units.SHAPE_MIN, Units.SHAPE_MAX) or 1
        memo.f [k] = f
    end
    return (1 + (memo.n - 1) * f) / memo.n, f
end

-- ranked: list of {p = spot, v = score, ...}. Returns the item with the best v × shape among the top
-- SHAPE_TOP by v (its .v2 is that product), skipping items check() refuses; nil when none.
function Match.shapeRerank(memo, ranked, check)
    table.sort(ranked, function(a, b)
        return a.v > b.v
    end)
    local best
    for i = 1, math.min(Match.SHAPE_TOP, # ranked) do
        local item = ranked [i]
        if not check or check(item) then
            local mul, f = Match.shapeMul(memo, item.p)
            item.v2, item.f = item.v * mul, f
            if not best or item.v2 > best.v2 then
                best = item
            end
        end
    end
    if best and ranked [1] and best ~= ranked [1] then
        Match.shapeSaid = Match.shapeSaid or {
        }
        if not Match.shapeSaid [memo.id] then
            Match.shapeSaid [memo.id] = true
            App.log(1, "PLACE", string.format("%s: its %s attack picks a spot with ×%.2f of an ordinary spot's extra targets over the spot with the most road", Units.name(memo.id), tostring(memo.shape.type), best.f or 1))
        end
    end
    return best
end

function Match.cover(valid, range, arg3, depth)
    local count = 0
    local flat = Utils.flat(valid)
    local dens = arg3 and Brain.maps [Match.mapKey()] and Brain.maps [Match.mapKey()].dens
    local laneW = Match.laneW
    local matched = Match.samplesInRange and Match.samplesInRange(flat, range) or Match.samples
    for _, sample in ipairs(matched) do
        local inRange = true
        if matched == Match.samples then
            local sFlat = sample.flat or Utils.flat(sample.pos)
            local dx = sFlat.X - flat.X
            local dz = sFlat.Z - flat.Z
            inRange = (dx * dx + dz * dz <= range * range)
        end
        if inRange then
            local num = 1
            if dens then
                num = 0.15 + 0.85 * (tonumber(dens [math.min(Simulator.BINS, math.floor(sample.prog * Simulator.BINS) + 1)]) or 0)
            end
            if laneW then
                num = num * (laneW [tostring(sample.lane)] or 1)
            end
            if depth then
                if depth.leak and sample.prog >= depth.leak - 0.01 and (not depth.leakLane or tostring(sample.lane) == depth.leakLane) then
                    num = num + 3
                elseif depth.push and sample.prog > depth.covEnd then
                    num = num + 0.6
                end
            end
            count = count + num
        end
    end
    return count
end

function Match.bleedGain(id, upgradeValue, arg3)
    local regen = Match.info and tonumber(Match.info.regen) or 0
    if regen <= 0 then
        return 0
    end
    local bleeds = Units.bleeds(id)
    if not bleeds then
        return 0
    end
    local flag = false
    for _, unit in ipairs(Match.mine or {
    }) do
        local stats = unit:FindFirstChild("_stats")
        local idValue = stats and stats:FindFirstChild("id") and stats.id.Value
        local upgradeValue = stats and stats:FindFirstChild("upgrade") and tonumber(stats.upgrade.Value) or 0
        if idValue and (Units.bleeds(idValue) or 99) <= upgradeValue then
            flag = true
            break
        end
    end
    return Economy.bleedShare(Economy.bleedGain(regen, Match.hpAlive or 0, Match.coming, flag), bleeds, upgradeValue, arg3)
end

function Match.fieldBuffers()
    local list = {
    }
    for _, unit in ipairs(Match.mine or {
    }) do
        local allyBuff = Units.allyBuff(unit._stats.id.Value)
        if allyBuff then
            table.insert(list, {
                pos = unit:GetPivot().Position,
                range = unit._stats.range.Value,
                b = allyBuff,
                model = unit
            })
        end
    end
    return list
end

Match.BUFF_SPOT_SHARE = 0.6

local function buffFlat(p)
    return Utils and Utils.flat and Utils.flat(p) or Vector3.new(p.X, 0, p.Z)
end

local function buffDistSq(a, b)
    local dx = a.X - b.X
    local dz = a.Z - b.Z
    return dx * dx + dz * dz
end

function Match.squadAndRelays(allyBuff)
    local mates = {
    }
    for _, fieldBuffer in ipairs(Match.fieldBuffers()) do
        if fieldBuffer.b.attack == allyBuff.attack then
            table.insert(mates, fieldBuffer)
        end
    end
    local need = allyBuff.squad or Units.BUFF_COPIES
    local state = Match.buffState and Match.buffState [allyBuff.attack]
    local squadCopies, relayCopies, running = nil, {}, false
    if state and state.squad and # state.squad >= need then
        local byModel = {
        }
        for _, m in ipairs(mates) do
            if m.model then
                byModel [m.model] = m
            end
        end
        local active = {
        }
        local inSquad = {
        }
        for _, model in ipairs(state.squad) do
            local m = byModel [model]
            if m then
                table.insert(active, m)
                inSquad [m] = true
            end
        end
        if # active >= need then
            squadCopies = active
            running = true
            for _, m in ipairs(mates) do
                if not inSquad [m] then
                    table.insert(relayCopies, m)
                end
            end
            return mates, squadCopies, relayCopies, running
        end
    end
    if # mates >= need then
        local adapted = {
        }
        for _, m in ipairs(mates) do
            table.insert(adapted, {
                position = buffFlat(m.pos),
                range = m.range,
                orig = m
            })
        end
        local found = Match.buffSquad(adapted, need)
        if found then
            squadCopies = {
            }
            local inSquad = {
            }
            for _, item in ipairs(found) do
                table.insert(squadCopies, item.orig)
                inSquad [item.orig] = true
            end
            for _, m in ipairs(mates) do
                if not inSquad [m] then
                    table.insert(relayCopies, m)
                end
            end
        end
    end
    return mates, squadCopies, relayCopies, running
end

function Match.planBuffSquad(unit, allyBuff, mates, cands, fighters)
    local need = (allyBuff and allyBuff.squad) or Units.BUFF_COPIES
    local rangeScale = (Match.info and tonumber(Match.info.rangeScale)) or 1
    local range0 = (unit and unit.u and Units.range(unit.u, 0) or 20) * rangeScale
    local data = unit and unit.data or {
    }
    local minSep = math.max(3.5, 2 * ((tonumber(data.override_hitbox_radius) or 1.5) + 0.25))
    local minSepSq = minSep * minSep
    local anchors = {
    }
    for _, m in ipairs(mates or {
    }) do
        table.insert(anchors, {
            pos = m.pos or m.position,
            flat = buffFlat(m.pos or m.position),
            range = tonumber(m.range) or range0
        })
    end
    -- If existing copies exceed 1 and some are out of range of others, keep the largest linked subset as anchors
    if # anchors > 1 then
        local adapted = {
        }
        for _, a in ipairs(anchors) do
            table.insert(adapted, {
                position = a.flat,
                range = a.range,
                orig = a
            })
        end
        local bestSub
        for k = math.min(# adapted, need), 1, - 1 do
            local sub = Match.buffSquad(adapted, k)
            if sub then
                bestSub = sub
                break
            end
        end
        if bestSub then
            anchors = {
            }
            for _, s in ipairs(bestSub) do
                table.insert(anchors, s.orig)
            end
        end
    end
    if # anchors >= need then
        local out = {
        }
        for i = 1, need do
            table.insert(out, anchors [i].pos)
        end
        return out
    end
    local attackerPts = {
    }
    if fighters then
        for _, f in ipairs(fighters) do
            if not allyBuff or not allyBuff.types or allyBuff.types [f.base] then
                local p = f.pos or f.position
                if p then
                    table.insert(attackerPts, {
                        flat = buffFlat(p),
                        dps = math.max(1, tonumber(f.dps) or 1),
                        id = f.id
                    })
                end
            end
        end
    elseif allyBuff then
        -- Weighed by the damage each one really deals in this match, its summons' included (2.24).
        local short = Match.buffShort(allyBuff)
        Match.realWeigh(short)
        for _, item in ipairs(short) do
            table.insert(attackerPts, {
                flat = buffFlat(item.pos),
                dps = math.max(1, tonumber(item.dps) or 1),
                id = item.id
            })
        end
    end
    if Match.layout then
        -- A planned spot counts as much as that unit's copies on the field (or the average attacker there),
        -- and not where a copy of it already stands (2.24; each counted a flat 50 before).
        local perId, total, n = {
        }, 0, 0
        for _, ap in ipairs(attackerPts) do
            if ap.id then
                local t = perId [ap.id] or {
                    s = 0,
                    n = 0
                }
                perId [ap.id] = t
                t.s, t.n = t.s + ap.dps, t.n + 1
            end
            total, n = total + ap.dps, n + 1
        end
        local planned = {
        }
        for id, order in pairs(Match.layout) do
            if not Units.isFarm(id) and not Units.allyBuff(id) and order [1] then
                local _, base = Units.types(id)
                if not allyBuff or not allyBuff.types or allyBuff.types [base] then
                    local flat, stands = buffFlat(order [1]), false
                    for _, ap in ipairs(attackerPts) do
                        if ap.id == id and buffDistSq(ap.flat, flat) <= 9 then
                            stands = true
                            break
                        end
                    end
                    if not stands then
                        local t = perId [id]
                        table.insert(planned, {
                            flat = flat,
                            dps = t and t.s / t.n or (n > 0 and total / n) or 50,
                            id = id
                        })
                    end
                end
            end
        end
        for _, ap in ipairs(planned) do
            table.insert(attackerPts, ap)
        end
    end
    local pool = {
    }
    local function addRaw(p)
        if p then
            table.insert(pool, p)
        end
    end
    for _, cand in ipairs(cands or Match.cands or {
    }) do
        addRaw(cand)
    end
    if # anchors > 0 then
        local center, reach = Vector3.new(0, 0, 0), range0
        for _, a in ipairs(anchors) do
            center = center + a.pos
            reach = math.min(reach, a.range)
        end
        center = center / # anchors
        addRaw(center)
        for _, r in ipairs({
            minSep + 0.5,
            reach * 0.25,
            reach * 0.45,
            reach * 0.65
        }) do
            for i = 0, 11 do
                local angle = i * math.pi / 6
                addRaw(center + Vector3.new(math.cos(angle), 0, math.sin(angle)) * r)
            end
        end
    end
    local validSpots = {
    }
    local function addValid(p)
        local valid = Match.valid(p, data)
        if not valid then
            return
        end
        local flat = buffFlat(valid)
        for _, a in ipairs(anchors) do
            if buffDistSq(flat, a.flat) < minSepSq then
                return
            end
            local reach = math.min(range0, a.range)
            if buffDistSq(flat, a.flat) > reach * reach then
                return
            end
        end
        for _, existing in ipairs(validSpots) do
            if buffDistSq(flat, existing.flat) < 1.0 then
                return
            end
        end
        local atkScore = 0
        for _, ap in ipairs(attackerPts) do
            if buffDistSq(flat, ap.flat) <= range0 * range0 then
                atkScore = atkScore + ap.dps
            end
        end
        local road = Match.cover and Match.samples and Match.cover(valid, range0, true, Match.depth) or 0
        table.insert(validSpots, {
            pos = valid,
            flat = flat,
            range = range0,
            score = atkScore * 10 + road
        })
    end
    for idx, cand in ipairs(pool) do
        if idx % 100 == 0 then
            task.wait()
        end
        addValid(cand)
    end
    table.sort(validSpots, function(a, b)
        return a.score > b.score
    end)
    -- Seed compact rings around the top candidate spots so a 4-spot cluster fits tightly near attackers/road
    local seedCount = math.min(4, # validSpots)
    for s = 1, seedCount do
        local basePos = validSpots [s].pos
        for _, r in ipairs({
            minSep + 0.5,
            minSep * 1.7
        }) do
            for i = 0, 7 do
                local angle = i * math.pi / 4
                addValid(basePos + Vector3.new(math.cos(angle), 0, math.sin(angle)) * r)
            end
        end
    end
    table.sort(validSpots, function(a, b)
        return a.score > b.score
    end)
    local topK = math.min(# validSpots, 36)
    local remain = need - # anchors
    local bestCombo, bestScore = nil, - 1
    local chosen = {
    }
    local function canFit(cand)
        for _, c in ipairs(chosen) do
            local dSq = buffDistSq(cand.flat, c.flat)
            if dSq < minSepSq then
                return false
            end
            local reach = math.min(cand.range, c.range)
            if dSq > reach * reach then
                return false
            end
        end
        return true
    end
    local combos = 0
    local function search(start, pickedScore)
        if # chosen == remain then
            combos = combos + 1
            if combos % 3000 == 0 then
                task.wait()
            end
            local allSpots = {
            }
            for _, a in ipairs(anchors) do
                table.insert(allSpots, a)
            end
            for _, c in ipairs(chosen) do
                table.insert(allSpots, c)
            end
            local jointAtk = 0
            for _, ap in ipairs(attackerPts) do
                local ok = true
                for _, sp in ipairs(allSpots) do
                    if buffDistSq(ap.flat, sp.flat) > sp.range * sp.range then
                        ok = false
                        break
                    end
                end
                if ok then
                    jointAtk = jointAtk + ap.dps
                end
            end
            local totalScore = pickedScore + jointAtk * 50
            if not bestCombo or totalScore > bestScore then
                bestScore = totalScore
                bestCombo = table.clone(chosen)
            end
            return
        end
        local needMore = remain - # chosen
        for i = start, topK - needMore + 1 do
            local cand = validSpots [i]
            if canFit(cand) then
                table.insert(chosen, cand)
                search(i + 1, pickedScore + cand.score)
                table.remove(chosen)
                if bestCombo and remain >= 3 and i >= 12 then
                    break
                end
            end
        end
    end
    search(1, 0)
    if not bestCombo then
        return nil
    end
    local out = {
    }
    for _, a in ipairs(anchors) do
        table.insert(out, a.pos)
    end
    for _, c in ipairs(bestCombo) do
        table.insert(out, c.pos)
    end
    return out
end

function Match.buffTemplateSpot(unit, allyBuff, mates)
    Match.buffTemplates = Match.buffTemplates or {
    }
    local need = (allyBuff and allyBuff.squad) or Units.BUFF_COPIES
    local rangeScale = (Match.info and tonumber(Match.info.rangeScale)) or 1
    local range0 = (unit and unit.u and Units.range(unit.u, 0) or 20) * rangeScale
    local data = unit and unit.data or {
    }
    local minSep = math.max(3.5, 2 * ((tonumber(data.override_hitbox_radius) or 1.5) + 0.25))
    local minSepSq = minSep * minSep
    local standing = {
    }
    for _, m in ipairs(mates or {
    }) do
        table.insert(standing, {
            flat = buffFlat(m.pos),
            range = tonumber(m.range) or range0
        })
    end
    local function nextFromTemplate(tpl)
        if not (tpl and type(tpl.spots) == "table" and # tpl.spots >= need) then
            return nil
        end
        local used = {
        }
        for _, m in ipairs(standing) do
            local bestIdx, bestD = nil, math.huge
            for idx, spot in ipairs(tpl.spots) do
                if not used [idx] then
                    local dSq = buffDistSq(m.flat, buffFlat(spot))
                    if dSq <= 6.25 and dSq < bestD then
                        bestIdx, bestD = idx, dSq
                    end
                end
            end
            if not bestIdx then
                return nil
            end
            used [bestIdx] = true
        end
        local nextSpot
        for idx, spot in ipairs(tpl.spots) do
            if not used [idx] then
                local valid = Match.valid(spot, data)
                local key = valid and Match.spotKey(valid) or nil
                if not valid or (Match.refused and Match.refused [key]) then
                    return nil
                end
                local vFlat = buffFlat(valid)
                local ok = true
                for _, m in ipairs(standing) do
                    local dSq = buffDistSq(vFlat, m.flat)
                    local reach = math.min(range0, m.range)
                    if dSq < minSepSq or dSq > reach * reach then
                        ok = false
                        break
                    end
                end
                if not ok then
                    return nil
                end
                nextSpot = nextSpot or valid
            end
        end
        return nextSpot
    end
    local tpl = Match.buffTemplates [allyBuff.attack]
    local spot = nextFromTemplate(tpl)
    if not spot then
        local planned = Match.planBuffSquad(unit, allyBuff, mates)
        if planned and # planned >= need then
            Match.buffTemplates [allyBuff.attack] = {
                spots = planned,
                id = unit.id,
                attack = allyBuff.attack
            }
            spot = nextFromTemplate(Match.buffTemplates [allyBuff.attack])
        else
            Match.buffTemplates [allyBuff.attack] = nil
        end
    end
    if spot then
        return spot, Match.cover and Match.samples and Match.cover(spot, range0) or 0
    end
    return nil
end

function Match.bestRelaySpot(unit, allyBuff, squadCopies, relayCopies, fighters, cands)
    if not (squadCopies and # squadCopies > 0) then
        return nil, 0, 0
    end
    local rangeScale = (Match.info and tonumber(Match.info.rangeScale)) or 1
    local range0 = (unit and unit.u and Units.range(unit.u, 0) or 20) * rangeScale
    local data = unit and unit.data or {
    }
    local minSep = math.max(3.5, 2 * ((tonumber(data.override_hitbox_radius) or 1.5) + 0.25))
    local minSepSq = minSep * minSep
    local r0Sq = range0 * range0
    local squadList = {
    }
    for _, sc in ipairs(squadCopies) do
        local p = sc.pos or sc.position
        table.insert(squadList, {
            pos = p,
            flat = buffFlat(p),
            range = tonumber(sc.range) or range0
        })
    end
    local relayList = {
    }
    for _, rc in ipairs(relayCopies or {
    }) do
        local p = rc.pos or rc.position
        table.insert(relayList, {
            pos = p,
            flat = buffFlat(p),
            range = tonumber(rc.range) or range0
        })
    end
    local atkList = {
    }
    if fighters then
        for _, f in ipairs(fighters) do
            if not allyBuff.types or allyBuff.types [f.base] then
                table.insert(atkList, {
                    flat = buffFlat(f.pos or f.position),
                    dps = math.max(1, tonumber(f.dps) or 1)
                })
            end
        end
    else
        for _, tower in ipairs(Match.mine or {
        }) do
            local idValue = tower._stats.id.Value
            local _, types2 = Units.types(idValue)
            if not Units.isFarm(idValue) and not Units.allyBuff(idValue) and allyBuff.types [types2] then
                local ok, res = pcall(Match.liveDps, tower, idValue)
                table.insert(atkList, {
                    model = tower,
                    flat = buffFlat(tower:GetPivot().Position),
                    dps = math.max(1, ok and tonumber(res) or 1)
                })
            end
        end
        Match.realWeigh(atkList)
    end
    local distant = {
    }
    for _, f in ipairs(atkList) do
        local sReach, rReach = 0, 0
        for _, sc in ipairs(squadList) do
            if buffDistSq(f.flat, sc.flat) <= sc.range * sc.range then
                sReach = sReach + 1
            end
        end
        if sReach < # squadList then
            for _, rc in ipairs(relayList) do
                if buffDistSq(f.flat, rc.flat) <= rc.range * rc.range then
                    rReach = rReach + 1
                end
            end
            table.insert(distant, {
                flat = f.flat,
                dps = f.dps,
                sReach = sReach,
                rReach = rReach
            })
        end
    end
    if # distant == 0 then
        return nil, 0, 0
    end
    local pool = {
    }
    for _, cand in ipairs(cands or Match.cands or {
    }) do
        table.insert(pool, cand)
    end
    for _, sc in ipairs(squadList) do
        local linkR = math.min(range0, sc.range)
        for _, frac in ipairs({
            0.75,
            0.9,
            0.98
        }) do
            for i = 0, 11 do
                local angle = i * math.pi / 6
                table.insert(pool, sc.pos + Vector3.new(math.cos(angle), 0, math.sin(angle)) * linkR * frac)
            end
        end
    end
    local bestSpot, bestScore, bestDps, bestCover = nil, - 1, 0, 0
    for idx, cand in ipairs(pool) do
        if idx % 100 == 0 then
            task.wait()
        end
        local valid = Match.valid(cand, data)
        if valid then
            local flat = buffFlat(valid)
            local ok = true
            local linkedSquad = 0
            local minSqDist = math.huge
            for _, sc in ipairs(squadList) do
                local dSq = buffDistSq(flat, sc.flat)
                if dSq < minSepSq then
                    ok = false
                    break
                end
                local linkR = math.min(range0, sc.range)
                if dSq <= linkR * linkR then
                    linkedSquad = linkedSquad + 1
                end
                minSqDist = math.min(minSqDist, math.sqrt(dSq))
            end
            if ok and linkedSquad > 0 then
                for _, rc in ipairs(relayList) do
                    if buffDistSq(flat, rc.flat) < minSepSq then
                        ok = false
                        break
                    end
                end
            end
            if ok and linkedSquad > 0 then
                local unbuffedDps, rawDps = 0, 0
                for _, f in ipairs(distant) do
                    if buffDistSq(flat, f.flat) <= r0Sq then
                        local w = (f.sReach == 0 and f.rReach == 0) and 1 or (f.rReach == 0 and (1 - f.sReach / # squadList) or 0.2)
                        unbuffedDps = unbuffedDps + f.dps * w
                        if f.rReach == 0 then
                            rawDps = rawDps + f.dps * (1 - f.sReach / # squadList)
                        end
                    end
                end
                if unbuffedDps > 0 then
                    local cov = Match.cover and Match.samples and Match.cover(valid, range0, true) or 0
                    local edgeBonus = minSqDist * 0.01 + cov * 0.001
                    local sc = unbuffedDps * 100 + edgeBonus
                    if sc > bestScore then
                        bestSpot, bestScore, bestDps, bestCover = valid, sc, rawDps > 0 and rawDps or unbuffedDps, cov
                    end
                end
            end
        end
    end
    return bestSpot, bestCover, bestDps
end

function Match.buffShort(allyBuff)
    local list = {
    }
    for _, fieldBuffer in ipairs(Match.fieldBuffers()) do
        if fieldBuffer.b.attack == allyBuff.attack then
            table.insert(list, fieldBuffer)
        end
    end
    local buffCopies = Units.buffCopies(allyBuff)
    local list2 = {
    }
    for _, unit in ipairs(Match.mine or {
    }) do
        local idValue = unit._stats.id.Value
        local _, types2 = Units.types(idValue)
        if not Units.isFarm(idValue) and not Units.allyBuff(idValue) and allyBuff.types [types2] then
            local flat = Utils.flat(unit:GetPivot().Position)
            local count = 0
            for _, item in ipairs(list) do
                if (Utils.flat(item.pos) - flat).Magnitude <= item.range then
                    count = count + 1
                end
            end
            if count < buffCopies then
                local ok, res = pcall(Match.liveDps, unit, idValue)
                table.insert(list2, {
                    model = unit,
                    id = idValue,
                    pos = flat,
                    base = types2,
                    n = count,
                    dps = math.max(1,
                    ok and tonumber(res) or 1)
                })
            end
        end
    end
    return list2
end

-- ===== Real damage on the field (2.24) =====
-- What each placed unit really deals a second: its own hits plus its summons' (the game's total_damage),
-- over its time on the field. A summoner reads low on its own stats though its summons may do most of the
-- team's damage, so where the buffers stand is weighed by this. Summons with no known parent are shared
-- among the placed copies of their owner.
Match.REAL_MIN_SEC = 15

function Match.dealtRates()
    local now = Utils.now()
    local memo = Match.dealtMemo
    if memo and now - memo.at < 1 then
        return memo.map
    end
    pcall(Match.sampleHelpers)
    local dealt, byId = {
    }, {
    }
    for unit, rec in pairs(Match.ownDealt or {
    }) do
        dealt [unit] = (dealt [unit] or 0) + (tonumber(rec.v) or 0)
    end
    for _, rec in pairs(Match.helperDealt or {
    }) do
        local v = tonumber(rec.v) or 0
        if v > 0 then
            if rec.parent then
                dealt [rec.parent] = (dealt [rec.parent] or 0) + v
            elseif rec.owner then
                byId [rec.owner] = (byId [rec.owner] or 0) + v
            end
        end
    end
    Match.fieldSince = Match.fieldSince or setmetatable({
    }, {
        __mode = "k"
    })
    local copies = {
    }
    for _, unit in ipairs(Match.mine or {
    }) do
        Match.fieldSince [unit] = Match.fieldSince [unit] or now
        local stats = unit._stats
        local id = stats and stats.id and stats.id.Value
        if id and byId [id] then
            copies [id] = copies [id] or {
            }
            table.insert(copies [id], unit)
        end
    end
    for id, v in pairs(byId) do
        local list = copies [id]
        if list then
            for _, unit in ipairs(list) do
                dealt [unit] = (dealt [unit] or 0) + v / # list
            end
        end
    end
    local map = {
    }
    for unit, v in pairs(dealt) do
        if v > 0 then
            local rec = Match.ownDealt and Match.ownDealt [unit]
            local since = rec and tonumber(rec.since) or Match.fieldSince [unit] or now
            map [unit] = v / math.max(Match.REAL_MIN_SEC, now - since)
        end
    end
    Match.dealtMemo = {
        at = now,
        map = map
    }
    return map
end

-- list: items with model and dps (liveDps). Units with real damage seen share the liveDps total of those
-- units by their real damage a second; a unit with none seen yet (just placed) keeps its liveDps.
function Match.realWeigh(list)
    local ok, rates = pcall(Match.dealtRates)
    if not ok or type(rates) ~= "table" then
        return
    end
    local liveSum, rateSum = 0, 0
    for _, item in ipairs(list or {
    }) do
        local rate = item.model and rates [item.model]
        if rate and rate > 0 then
            liveSum = liveSum + (tonumber(item.dps) or 0)
            rateSum = rateSum + rate
        end
    end
    if liveSum <= 0 or rateSum <= 0 then
        return
    end
    for _, item in ipairs(list) do
        local rate = item.model and rates [item.model]
        if rate and rate > 0 then
            item.live = item.dps
            item.dps = math.max(1, liveSum * rate / rateSum)
        end
    end
end

-- ===== Buff at a spot (2.24) =====
-- The bonus a unit of damage type types2 gets at a spot from the buffers on the field: for a rotation
-- (Auto Buff) the rotation's average level times the share of its copies that reach the spot; for other
-- buffers their level times their uptime. Every spot search scores spots by road × (1 + this), so a unit
-- that a rotation raises stands under it when its road there is not much worse (the kill-zone and
-- fast-clear searches counted only the road before, and units stood outside the squad). nil: no buffer
-- on the field raises this type.
function Match.buffBonusFn(fieldBuffers, types2, chainOn)
    local list, groupSize = {
    }, {
    }
    for _, fieldBuffer in ipairs(fieldBuffers or {
    }) do
        groupSize [fieldBuffer.b.attack] = (groupSize [fieldBuffer.b.attack] or 0) + 1
        if fieldBuffer.b.types [types2] then
            table.insert(list, {
                fb = fieldBuffer,
                flat = Utils.flat(fieldBuffer.pos)
            })
        end
    end
    if # list == 0 then
        return nil
    end
    local avg = {
    }
    return function(valid)
        local count, inside = 0, {
        }
        local flat = Utils.flat(valid)
        for _, item in ipairs(list) do
            local fieldBuffer = item.fb
            local value = fieldBuffer.b.types [types2]
            if (item.flat - flat).Magnitude <= fieldBuffer.range then
                if fieldBuffer.b.chain and chainOn then
                    -- The rotation only climbs for a unit every copy reaches: the bonus grows with each one.
                    local attack = fieldBuffer.b.attack
                    inside [attack] = (inside [attack] or 0) + 1
                    local needSz = fieldBuffer.b.squad or Units.BUFF_COPIES
                    local size = math.min(groupSize [attack] or 1, needSz)
                    local inCount = math.min(inside [attack], size)
                    local key = tostring(attack) .. ":" .. size .. ":" .. tostring(value)
                    local average = avg [key]
                    if not average then
                        average = Units.buffAverage(fieldBuffer.b, size, value, true)
                        avg [key] = average
                    end
                    count = math.max(count, average * inCount / size)
                else
                    count = math.max(count, math.min(value, count + value * fieldBuffer.b.uptime))
                end
            end
        end
        return count
    end
end

-- Once per unit: a buff took it off the spot with the most road (road: its spot's road, top: the best road).
function Match.buffSpotSay(unit, road, top, bonus)
    if not (bonus and bonus > 0.001 and top and top > 0 and road and road < top * 0.999) then
        return
    end
    Match.buffSaid = Match.buffSaid or {
    }
    if Match.buffSaid [unit.id] then
        return
    end
    Match.buffSaid [unit.id] = true
    App.log(1, "PLACE", string.format("%s stands under the buff (+%d%% damage there): its spot has %d%% of the road of the best spot outside it", Units.name(unit.id), math.floor(bonus * 100 + 0.5), math.floor(road / top * 100 + 0.5)))
end

function Match.spotRec(spotKey, spot, arg3)
    local mapKey = Match.mapKey()
    Brain.maps [mapKey] = Brain.maps [mapKey] or {
    }
    local lay = Brain.maps [mapKey].lay
    if not lay then
        if not arg3 then
            return nil
        end
        lay = {
        }
        Brain.maps [mapKey].lay = lay
    end
    local value = lay [spotKey]
    if not value then
        if not arg3 then
            return nil
        end
        value = {
        }
        lay [spotKey] = value
    end
    local spotKey = Match.spotKey(spot)
    if not value [spotKey] and arg3 then
        value [spotKey] = {
            runs = 0,
            wins = 0
        }
    end
    return value [spotKey]
end

function Match.lastLife(value, simResult)
    if Match.kind ~= "dungeon" then
        return
    end
    local ok, res = pcall(Dungeon.lives, Dungeon.data())
    if not (ok and res <= 1) then
        return
    end
    local won = value > 1 or simResult.won
    Dungeon.note(string.format("last life, on this map: the simulator says your team %s", won and "wins" or ("falls at wave " .. simResult.wave)))
    if not won and Dungeon.playLast() then
        Dungeon.note("last life: played all the same, the user's call")
    elseif not won then
        Match.noBuy = true
        Modes.rec("dg").restUntil = os.time() + 3600
        Brain.pending = nil
        Dungeon.note("last life kept: back to the lobby before a wave starts. Looks again in an hour")
        App.saveNow()
        task.wait(1)
        Match.toLobby("dungeon: last life kept")
    end
end
Match.STYLE_FAST, Match.STYLE_BALANCED, Match.FAST_ROAD, Match.PLAN_TOTAL = 1.5, 1.1, 0.35, 14
Match.STYLE_WORDS = {
    fast = "fast clear, at the road's start",
    balanced = "balanced, spread over the road",
    box = "kill box, on the road's last stretch"
}

function Match.styleRec(arg1)
    local styles, seed
    if Match.kind == "dungeon" then
        Brain.dg.styles = type(Brain.dg.styles) == "table" and Brain.dg.styles or {
        }
        styles, seed = Brain.dg.styles, tostring(Brain.dg.room and Brain.dg.room.seed)
    else
        styles, seed = Brain.zoneRec, Simulator.zoneKey(Match.info)
    end
    if not styles [seed] and arg1 then
        styles [seed] = {
            at = os.time()
        }
        if styles ~= Brain.zoneRec and Utils.count(styles) > 40 then
            local value, at
            for styleKey, style in pairs(styles) do
                if not at or (tonumber(style.at) or 0) < at then
                    value, at = styleKey, tonumber(style.at) or 0
                end
            end
            styles [value] = nil
        end
    end
    return styles [seed]
end

function Match.styleRecord(arg1)
    if not Match.style or not Match.info then
        return
    end
    local styleRec = Match.styleRec(true)
    styleRec.style, styleRec.zone, styleRec.won, styleRec.at = Match.style, Match.style == "box", arg1 and true or false, os.time()
    styleRec.lost = type(styleRec.lost) == "table" and styleRec.lost or {
    }
    styleRec.lost [Match.style] = (not arg1) and {
        at = os.time(),
        sig = Match.styleSig
    } or nil
    styleRec.far = type(styleRec.far) == "table" and styleRec.far or {
    }
    styleRec.far [Match.style] = math.max(tonumber(styleRec.far [Match.style]) or 0, Match.wave())
end

function Match.planSpots()
    local planStart = Utils.now()
    local info = Match.info
    local rangeScale = tonumber(info.rangeScale) or 1
    local teamUnits, attackers = {
    }, {
    }
    for _, member in ipairs(Match.team or {
    }) do
        table.insert(teamUnits, member.u)
        if not Units.isFarm(member.id) and not Units.allyBuff(member.id) and member.uuid ~= Match.trainee and Units.rows(member.id) then
            local ok, score = pcall(Units.score, member.u, Match.mod)
            table.insert(attackers, {
                e = member,
                id = member.id,
                sc = ok and score or 0
            })
        end
    end
    if # attackers == 0 then
        return
    end
    table.sort(attackers, function(a, b)
        return a.sc > b.sc
    end)
    local spotsByHitbox = {
    }
    local function validSpots(unitData)
        local cacheKey = (unitData.hill_unit and "hill" or "ground") .. ":" .. tostring(unitData.override_hitbox_radius or "")
        if spotsByHitbox [cacheKey] then
            return spotsByHitbox [cacheKey]
        end
        local spots = {
        }
        for i, cand in ipairs(Match.cands) do
            local spot = Match.valid(cand, unitData)
            if spot then
                table.insert(spots, spot)
            end
            if i % 40 == 0 then
                task.wait()
            end
        end
        spotsByHitbox [cacheKey] = spots
        return spots
    end
    local function roadCover(pos, range)
        local covered, fastScore, boxScore, rangeSq = 0, 0, 0, range * range
        for _, sample in ipairs(Match.samples) do
            local dx, dz = sample.pos.X - pos.X, sample.pos.Z - pos.Z
            if dx * dx + dz * dz <= rangeSq then
                covered = covered + 1
                if sample.prog <= Match.FAST_ROAD then
                    fastScore = fastScore + 1.5 - sample.prog
                end
                if sample.prog >= 0.6 then
                    boxScore = boxScore + sample.prog - 0.5
                end
            end
        end
        return covered, fastScore, boxScore
    end
    local function pickSpaced(ranked, want, into)
        for _, cand in ipairs(ranked) do
            if want <= 0 then
                break
            end
            local farEnough = true
            for _, taken in ipairs(into) do
                if (Utils.flat(taken) - Utils.flat(cand.p)).Magnitude < 6 then
                    farEnough = false
                    break
                end
            end
            if farEnough then
                table.insert(into, cand.p)
                want = want - 1
            end
        end
    end
    local roadX, roadZ, roadP = {
    }, {
    }, {
    }
    for i, sample in ipairs(Match.samples) do
        roadX [i], roadZ [i], roadP [i] = sample.pos.X, sample.pos.Z, sample.prog
    end
    local shapeAt, shapeNote = {
    }, {
    }
    for _, attacker in ipairs(attackers) do
        local rows = Units.rows(attacker.id)
        local fullRange = Units.range(attacker.e.u, rows.max) * rangeScale
        local earlyRange = Units.range(attacker.e.u, math.min(3, rows.max)) * rangeScale
        local byCover, byEarly, byFast, byBox = {
        }, {
        }, {
        }, {
        }
        for i, spot in ipairs(validSpots(attacker.e.data)) do
            local cover, fast, box = roadCover(spot, fullRange)
            local coverEarly, fastEarly = roadCover(spot, earlyRange)
            table.insert(byCover, {
                p = spot,
                v = cover + 0.25 * coverEarly
            })
            table.insert(byEarly, {
                p = spot,
                v = Match.cover(spot,
                earlyRange,
                true)
            })
            table.insert(byFast, {
                p = spot,
                v = fast + 0.5 * fastEarly
            })
            table.insert(byBox, {
                p = spot,
                v = box
            })
            if i % 60 == 0 then
                task.wait()
            end
        end
        for _, ranking in ipairs({
            byCover,
            byEarly,
            byFast,
            byBox
        }) do
            table.sort(ranking, function(a, b)
                return a.v > b.v
            end)
        end
        attacker.cands = {
        }
        pickSpaced(byEarly, 1, attacker.cands)
        attacker.old = attacker.cands [1]
        pickSpaced(byCover, 4, attacker.cands)
        pickSpaced(byEarly, 2, attacker.cands)
        -- Attack shape: a line wants a long straight stretch along its hit, a circle a bend where the road
        -- folds, a cone road in front of it. Spots that suit the shape join the candidates (the old ones
        -- stay), and the simulator of this plan gives each spot its own number of enemies per hit.
        local maxRow = rows [rows.max]
        local info = maxRow and maxRow.atk and Units.attackInfo(maxRow.atk, maxRow.range)
        if info and info.shape and info.n > 1.05 then
            local factors = Units.shapeFactors(info.shape, validSpots(attacker.e.data), fullRange, roadX, roadZ, roadP, 40)
            if factors then
                shapeAt [attacker.id] = factors
                local byShape, byShapeFast, byShapeBox = {
                }, {
                }, {
                }
                for _, entry in ipairs(byCover) do
                    local f = factors [entry.p]
                    if f then
                        local mul = (1 + (info.n - 1) * f) / info.n
                        table.insert(byShape, {
                            p = entry.p,
                            v = entry.v * mul
                        })
                    end
                end
                for _, list in ipairs({
                    {
                        byFast,
                        byShapeFast
                    },
                    {
                        byBox,
                        byShapeBox
                    }
                }) do
                    for _, entry in ipairs(list [1]) do
                        local f = factors [entry.p]
                        if f then
                            table.insert(list [2], {
                                p = entry.p,
                                v = entry.v * (1 + (info.n - 1) * f) / info.n
                            })
                        end
                    end
                end
                for _, ranking in ipairs({
                    byShape,
                    byShapeFast,
                    byShapeBox
                }) do
                    table.sort(ranking, function(a, b)
                        return a.v > b.v
                    end)
                end
                pickSpaced(byShape, 2, attacker.cands)
                attacker.shapeFast, attacker.shapeBox = byShapeFast, byShapeBox
                shapeNote [attacker.id] = info.shape.type
            end
        end
        local function topShare(ranked)
            local best, top = ranked [1] and ranked [1].v or 0, {
            }
            for _, cand in ipairs(ranked) do
                if best <= 0 or cand.v < best * 0.7 then
                    break
                end
                table.insert(top, cand)
            end
            return # top > 0 and top or ranked
        end
        attacker.fast, attacker.box = {
        }, {
        }
        pickSpaced(topShare(byFast), 5, attacker.fast)
        pickSpaced(topShare(byBox), 5, attacker.box)
        if attacker.shapeFast then
            pickSpaced(topShare(attacker.shapeFast), 2, attacker.fast)
            pickSpaced(topShare(attacker.shapeBox), 2, attacker.box)
            attacker.shapeFast, attacker.shapeBox = nil, nil
        end
    end
    local simTeam = Simulator.teamFrom(teamUnits, info.map)
    local simCache, runs = {
    }, 0
    local resultCache, cacheHits, swapsKept = {
    }, 0, 0
    local function layoutKey(layout, hpMul)
        local parts = {
        }
        for unitId, spot in pairs(layout.spots) do
            table.insert(parts, string.format("%s@%.2f,%.2f", tostring(unitId), spot.X, spot.Z))
        end
        table.sort(parts)
        return string.format("%s|%.4f|%s", tostring(layout.style), hpMul, table.concat(parts, ";"))
    end
    local function simulate(layout, hpMul)
        local key = layoutKey(layout, hpMul)
        local cached = resultCache [key]
        if cached then
            cacheHits = cacheHits + 1
            return cached
        end
        runs = runs + 1
        local result = Simulator.run(info, simTeam, {
            hpMul = hpMul,
            layout = layout
        })
        resultCache [key] = result
        task.wait()
        return result
    end
    local function spotHistory(layout)
        local recs = {
        }
        for spotKey, spot in pairs(layout.spots) do
            table.insert(recs, Match.spotRec(spotKey, spot) or false)
        end
        local score = 0
        for _, rec in ipairs(recs) do
            if rec then
                score = score + Match.histTerm(rec, Match.HIST.SPOT_W / # recs)
            end
        end
        return score + Match.histTerm(Match.planRec(Match.planSig(layout.spots, layout.style)), Match.HIST.PLAN_W)
    end
    local function layoutScore(layout, result)
        return Simulator.objective(result) * 100 + spotHistory(layout)
    end
    local function crowded(layout, unitId, pos)
        for spotKey, spot in pairs(layout.spots) do
            if spotKey ~= unitId and (Utils.flat(spot) - Utils.flat(pos)).Magnitude < 4.5 then
                return true
            end
        end
        return false
    end
    local function startLayout(style, listName)
        local layout = {
            samples = Match.samples,
            cache = simCache,
            spots = {
            },
            style = style,
            list = listName,
            shapeAt = shapeAt
        }
        for _, attacker in ipairs(attackers) do
            local free
            for _, cand in ipairs(attacker [listName]) do
                if not crowded(layout, attacker.id, cand) then
                    free = cand
                    break
                end
            end
            layout.spots [attacker.id] = free or attacker [listName] [1] or attacker.old
        end
        return layout
    end
    local function breakingPoint(layout)
        local limit, result = 4, nil
        for _, hpMul in ipairs({
            1,
            1.3,
            1.7,
            2.2,
            3,
            4
        }) do
            if result and Utils.now() - planStart > Match.PLAN_TOTAL * 1.5 then
                limit = hpMul
                break
            end
            result = simulate(layout, hpMul)
            if not result.won then
                limit = hpMul
                break
            end
        end
        return limit, result
    end
    local function improve(layout, hpMul, maxSec, maxRuns, firstResult)
        local started, runs0 = Utils.now(), runs
        local bestScore = layoutScore(layout, firstResult or simulate(layout, hpMul))
        for _ = 1, 2 do
            local improved = false
            for _, attacker in ipairs(attackers) do
                local current = layout.spots [attacker.id]
                local best = current
                for _, cand in ipairs(attacker [layout.list]) do
                    if Utils.now() - started > maxSec or runs - runs0 >= maxRuns or Utils.now() - planStart > Match.PLAN_TOTAL then
                        break
                    end
                    if cand ~= current and not crowded(layout, attacker.id, cand) then
                        layout.spots [attacker.id] = cand
                        local score = layoutScore(layout, simulate(layout, hpMul))
                        if score > bestScore + 1 then
                            bestScore, best = score, cand
                            improved = true
                        end
                    end
                end
                layout.spots [attacker.id] = best
            end
            if not improved then
                break
            end
        end
        -- Two units trading places: a move no single unit can make, since each spot is taken. Only
        -- units that can stand on the same ground (hill or not, same footprint) trade.
        local function kind(attacker)
            local data = attacker.e.data or {
            }
            return (data.hill_unit and "hill" or "ground") .. ":" .. tostring(data.override_hitbox_radius or "")
        end
        for i = 1, # attackers do
            for j = i + 1, # attackers do
                if Utils.now() - started > maxSec * 1.25 or runs - runs0 >= maxRuns * 1.25 or Utils.now() - planStart > Match.PLAN_TOTAL then
                    return
                end
                local a, b = attackers [i], attackers [j]
                local pa, pb = layout.spots [a.id], layout.spots [b.id]
                if pa and pb and pa ~= pb and kind(a) == kind(b) then
                    layout.spots [a.id], layout.spots [b.id] = pb, pa
                    local score = layoutScore(layout, simulate(layout, hpMul))
                    if score > bestScore + 1 then
                        bestScore = score
                        swapsKept = swapsKept + 1
                    else
                        layout.spots [a.id], layout.spots [b.id] = pa, pb
                    end
                end
            end
        end
    end
    local function robustWins(layout, hpMul)
        local wins = 0
        for _, jitter in ipairs({
            0.92,
            1,
            1.08
        }) do
            if simulate(layout, hpMul * jitter).won then
                wins = wins + 1
            end
        end
        return wins
    end
    local styleRec = Match.styleRec()
    local sig = Simulator.sig(teamUnits)
    Match.styleSig = sig
    local mode = Match.kind ~= "dungeon" and Brain.modes [info.key] or nil
    local streak = mode and tonumber(mode.streak) or 0
    local dailyLoop = Config.dailyLoop and Match.kind == "daily"
    local balanced = dailyLoop and styleRec and type(styleRec.far) == "table" and (tonumber(styleRec.far.balanced) or 0) > 0 and (tonumber(styleRec.far.balanced) or 0) >= (tonumber(styleRec.far.box) or 0) and tonumber(styleRec.far.balanced) or nil
    local function lostWith(style)
        if dailyLoop then
            return false
        end
        local lost = styleRec and type(styleRec.lost) == "table" and styleRec.lost [style]
        if lost then
            return lost.sig == sig and os.time() - (tonumber(lost.at) or 0) < 7 * 86400
        end
        if styleRec and not styleRec.style and styleRec.won == false then
            return style == (styleRec.zone and "box" or "balanced")
        end
        return not styleRec and streak > 0 and style == "balanced"
    end
    local function wonWith(style)
        if styleRec and styleRec.won then
            return (styleRec.style or (styleRec.zone and "box" or "balanced")) == style
        end
        return not styleRec and style == "balanced" and mode ~= nil and (tonumber(mode.wins) or 0) > 0 and streak == 0 and info.key ~= "ch" and info.key ~= "dc"
    end
    local killZoneOn = Config.killZone ~= false
    local ok, lives = pcall(Dungeon.lives, Dungeon.data())
    local lastLife = killZoneOn and Match.kind == "dungeon" and ok and lives <= 1
    local dailyBox = dailyLoop and Config.dailyBox and killZoneOn
    local chosen, reason, spreadLayout
    local noFast = (dailyBox and "you asked for the kill box here") or (lastLife and "it's this room's last life") or (Match.trainee and "a unit is training here and needs enemies left to hit") or (lostWith("fast") and "it lost here") or (lostWith("balanced") and "spread-out units already lost here") or ((tonumber(info.cal and info.cal.n) or 0) == 0 and "no real run here yet to check the simulator against") or nil
    if not noFast then
        runs = runs + 1
        if not Simulator.run(info, simTeam, {
            hpMul = Match.STYLE_FAST * 0.92,
            noZone = true
        }).won then
            noFast = string.format("your team doesn't beat enemies ×%.1f", Match.STYLE_FAST)
        end
    end
    if noFast then
        App.log(1, "SPOTS", "no fast clear: " .. noFast)
    else
        local t0, runs0 = Utils.now(), runs
        local fastLayout = startLayout("fast", "fast")
        improve(fastLayout, Match.STYLE_FAST, 4, 40)
        local fastWins = robustWins(fastLayout, Match.STYLE_FAST)
        App.log(1, "SPOTS", string.format("fast clear: tried %d layouts in %.1f s, the best wins %d of 3 tries against enemies ×%.1f", runs - runs0, Utils.now() - t0, fastWins, Match.STYLE_FAST))
        if fastWins >= 2 then
            chosen, reason = fastLayout, string.format("your team beats enemies ×%.1f from there", Match.STYLE_FAST)
        end
    end
    if not chosen and not lastLife and not dailyBox and (killZoneOn == false or not lostWith("balanced")) then
        local t0, runs0 = Utils.now(), runs
        local spread = startLayout("balanced", "cands")
        local spreadMul, spreadResult = breakingPoint(spread)
        for i, attacker in ipairs(attackers) do
            if i > 1 then
                local rows = Units.rows(attacker.id)
                local level = math.min(rows.max, math.max(tonumber(spreadResult.levels and spreadResult.levels [attacker.id]) or 0, 1))
                local range = Units.range(attacker.e.u, level) * rangeScale
                local rangeSq, early = range * range, {
                }
                for i, pos in ipairs(validSpots(attacker.e.data)) do
                    local covered = 0
                    for _, sample in ipairs(Match.samples) do
                        if sample.prog <= 0.5 then
                            local dx, dz = sample.pos.X - pos.X, sample.pos.Z - pos.Z
                            if dx * dx + dz * dz <= rangeSq then
                                covered = covered + 1
                            end
                        end
                    end
                    table.insert(early, {
                        p = pos,
                        v = covered
                    })
                    if i % 60 == 0 then
                        task.wait()
                    end
                end
                table.sort(early, function(a, b)
                    return a.v > b.v
                end)
                local older = attacker.cands
                attacker.cands = {
                }
                pickSpaced(early, 3, attacker.cands)
                for _, cand in ipairs(older) do
                    table.insert(attacker.cands, cand)
                end
            end
        end
        improve(spread, spreadMul, 5, 50, spreadResult)
        local spreadWins = robustWins(spread, Match.STYLE_BALANCED)
        App.log(1, "SPOTS", string.format("balanced: tried %d layouts in %.1f s, the best wins %d of 3 tries against enemies ×%.1f", runs - runs0, Utils.now() - t0, spreadWins, Match.STYLE_BALANCED))
        spreadLayout = spread
        if spreadWins >= 2 then
            chosen, reason = spread, string.format("your team beats enemies ×%.1f spread out%s", Match.STYLE_BALANCED, noFast and "" or string.format(", not ×%.1f from the road's start", Match.STYLE_FAST))
        elseif wonWith("balanced") then
            chosen, reason = spread, "it won here last time, and the simulator reads spread-out units low"
        elseif not killZoneOn then
            chosen, reason = spread, "the kill box is switched off"
        elseif balanced then
            chosen, reason = spread, string.format("it got furthest here, to wave %d", balanced)
        elseif lostWith("box") then
            chosen, reason = spread, "the kill box lost here"
        end
    end
    if not chosen then
        local t0, runs0 = Utils.now(), runs
        local boxLayout = startLayout("box", "box")
        local boxMul, boxResult = breakingPoint(boxLayout)
        improve(boxLayout, boxMul, 4, 40, boxResult)
        local boxWins = robustWins(boxLayout, 1)
        App.log(1, "SPOTS", string.format("kill box: tried %d layouts in %.1f s, the best wins %d of 3 tries against normal enemies", runs - runs0, Utils.now() - t0, boxWins))
        if boxWins == 0 and spreadLayout and robustWins(spreadLayout, 1) >= 2 then
            chosen, reason = spreadLayout, "the kill box loses at normal strength, spread-out units win"
        else
            chosen, reason = boxLayout, dailyBox and "you asked for it: a control unit works best in one" or lastLife and "it's this room's last life" or (not spreadLayout and "spread-out units lost here") or string.format("your team doesn't beat enemies ×%.1f spread out", Match.STYLE_BALANCED)
        end
    end
    Match.style = chosen.style
    Match.styleWhy = reason
    info.zone = chosen.style == "box"
    Match.layout = {
    }
    local summary = {
    }
    for _, attacker in ipairs(attackers) do
        local spot = chosen.spots [attacker.id]
        local order = {
            spot
        }
        for _, alt in ipairs(attacker [chosen.list]) do
            if alt ~= spot then
                table.insert(order, alt)
            end
        end
        Match.layout [attacker.id] = order
        if spot then
            local f = shapeAt [attacker.id] and shapeAt [attacker.id] [spot]
            table.insert(summary, string.format("%s %s (%d%% of the road at full range%s)", Units.name(attacker.id), Match.spotKey(spot), math.floor((roadCover(spot, Units.range(attacker.e.u, Units.rows(attacker.id).max) * rangeScale)) / math.max(1, # Match.samples) * 100 + 0.5),
                f and string.format(", %s attack: ×%.2f of an ordinary spot's extra targets", tostring(shapeNote [attacker.id]), f) or ""))
        end
    end
    Match.layoutSim = chosen
    local breakMul, simResult = breakingPoint(chosen)
    App.log(1, "SPOTS", string.format("placement: %s, because %s · %s · against enemies ×%.1f the simulator %s at wave %d · %d runs (+%d repeats from cache), %d trades of places kept, in %.1f s", Match.STYLE_WORDS [chosen.style], reason, table.concat(summary, " · "), breakMul, simResult.won and "wins" or "falls", simResult.wave, runs, cacheHits, swapsKept, Utils.now() - planStart))
    App.status("Placement", Match.STYLE_WORDS [chosen.style])
    Match.lastLife(breakMul, simResult)
end

-- Real results of spots and whole plans. Older runs fade (each new one weighs 1, the one before
-- DECAY, and so on), and history only nudges the simulator. With the fading a record never weighs
-- more than about 7 runs, so all of it together moves a layout's score by at most about two thirds
-- of SPOT_W + PLAN_W (= about one wave, 10 simulator points × 100). A loss is blamed on the whole
-- plan first; each spot only carries its share, since a run is often lost for reasons no spot is
-- to blame for.
Match.HIST = {
    DECAY = 0.85,
    SPOT_W = 600,
    PLAN_W = 900,
    PLANS = 40
}

function Match.histAdd(rec, won)
    local decay = Match.HIST.DECAY
    rec.runs = (tonumber(rec.runs) or 0) * decay + 1
    rec.wins = (tonumber(rec.wins) or 0) * decay + (won and 1 or 0)
    rec.at = os.time()
end

-- From -weight (only losses, many of them) to +weight (only wins, many of them).
function Match.histTerm(rec, weight)
    local runs = rec and tonumber(rec.runs) or 0
    if runs <= 0 then
        return 0
    end
    local wins = Utils.clamp(tonumber(rec.wins) or 0, 0, runs)
    local p = (wins + 0.5) / (runs + 1)
    return weight * (runs / (runs + 2)) * (p - 0.5) * 2
end

function Match.planSig(spots, style)
    local parts = {
    }
    for unitId, spot in pairs(spots or {
    }) do
        table.insert(parts, tostring(unitId) .. "=" .. Match.spotKey(spot))
    end
    table.sort(parts)
    return tostring(style) .. "|" .. table.concat(parts, ";")
end

function Match.planRec(sig, create)
    local mapKey = Match.mapKey()
    Brain.maps [mapKey] = Brain.maps [mapKey] or {
    }
    local plans = Brain.maps [mapKey].plans
    if type(plans) ~= "table" then
        if not create then
            return nil
        end
        plans = {
        }
        Brain.maps [mapKey].plans = plans
    end
    if not plans [sig] and create then
        if Utils.count(plans) >= Match.HIST.PLANS then
            local oldest, at
            for key, rec in pairs(plans) do
                if not at or (tonumber(rec.at) or 0) < at then
                    oldest, at = key, tonumber(rec.at) or 0
                end
            end
            plans [oldest] = nil
        end
        plans [sig] = {
            runs = 0,
            wins = 0
        }
    end
    return plans [sig]
end

function Match.spotResult(arg1)
    local used = 0
    for key, value in pairs(Match.layoutUsed or {
    }) do
        Match.histAdd(Match.spotRec(key, value, true), arg1)
        used = used + 1
    end
    if used > 0 and Match.style then
        Match.histAdd(Match.planRec(Match.planSig(Match.layoutUsed, Match.style), true), arg1)
    end
    if not Match.infinite then
        Match.styleRecord(arg1)
    end
end
Match.CONTROL_WORDS = {
    "at the front of",
    "at the back of",
    "in the middle of",
    "ahead of"
}

function Match.controlSpot(arg1, arg2)
    if not Match.killZone() then
        return nil
    end
    local holds = Simulator.holds
    if not holds(arg1.id) or Units.toggleOf(arg1.id) then
        return nil
    end
    local num, count, count2, list = 1, 0, 0, {
    }
    for _, unit in ipairs(Match.mine or {
    }) do
        local stats = unit._stats
        local idValue = stats.id.Value
        if stats:FindFirstChild("range") and not Units.isFarm(idValue) and not Units.allyBuff(idValue) then
            local flat, rangeValue = Utils.flat(unit:GetPivot().Position), stats.range.Value
            if holds(idValue) and not Units.toggleOf(idValue) then
                count2 = count2 + 1
                table.insert(list, {
                    p = flat,
                    r = rangeValue
                })
            else
                for _, sample in ipairs(Match.samples) do
                    if ((sample.flat or Utils.flat(sample.pos)) - flat).Magnitude <= rangeValue then
                        num, count = math.min(num, sample.prog), math.max(count, sample.prog)
                    end
                end
            end
        end
    end
    if count <= num then
        num, count = 0.75, 0.98
    end
    local arg22 = (arg2 or count2) + 1
    local value = ({
        num,
        count,
        (num + count) / 2,
        num - (count - num) / 2
    }) [arg22]
    if not value then
        return nil
    end
    local range = Units.range(arg1.u, 0) * ((Match.info and tonumber(Match.info.rangeScale)) or 1)
    local list2 = {
    }
    for i, cand in ipairs(Match.cands) do
        local flat, count, count2 = Utils.flat(cand), 0, 0
        for _, sample in ipairs(Match.samples) do
            if ((sample.flat or Utils.flat(sample.pos)) - flat).Magnitude <= range then
                count2 = count2 + 1
                if math.abs(sample.prog - value) <= 0.05 then
                    count = count + 1
                    local flat = (sample.flat or Utils.flat(sample.pos))
                    for _, item in ipairs(list) do
                        if (flat - item.p).Magnitude <= item.r then
                            count = count - 0.5
                            break
                        end
                    end
                end
            end
        end
        if count > 0 then
            table.insert(list2, {
                pos = cand,
                sc = count,
                cov = count2
            })
        end
        if i % 60 == 0 then
            task.wait()
        end
    end
    table.sort(list2, function(arg1, arg2)
        return arg1.sc > arg2.sc
    end)
    -- Attack shape (2.22): among the best spots by road, a hit that catches more of the road holds more.
    local shapeMemo = Match.shapeInfo(arg1)
    if shapeMemo and # list2 > 1 then
        local top = {
        }
        for i = 1, math.min(Match.SHAPE_TOP, # list2) do
            list2 [i].p, list2 [i].v = list2 [i].pos, list2 [i].sc
            top [i] = list2 [i]
        end
        Match.shapeRerank(shapeMemo, top)
        table.sort(top, function(a, b)
            return (a.v2 or a.v) > (b.v2 or b.v)
        end)
        for i, item in ipairs(top) do
            list2 [i] = item
        end
    end
    for i, item in ipairs(list2) do
        local valid = Match.valid(item.pos, arg1.data)
        if valid then
            App.log(1, "PLACE", string.format("%s goes %s the kill box (%d%% of the road)", Units.name(arg1.id), Match.CONTROL_WORDS [arg22], math.floor(value * 100 + 0.5)))
            return valid, item.cov, value
        end
        if i % 20 == 0 then
            task.wait()
        end
    end
    return nil
end

function Match.holdSpot(arg1)
    local holds, holds2 = Simulator.holds(arg1.id)
    if not holds then
        return nil
    end
    local list, count = {
    }, 0
    for _, unit in ipairs(Match.mine or {
    }) do
        local stats = unit._stats
        local idValue = stats.id.Value
        if stats:FindFirstChild("range") and not Units.isFarm(idValue) and not Units.allyBuff(idValue) and idValue ~= arg1.id then
            local ok, res = pcall(Match.liveDps, unit, idValue)
            res = ok and tonumber(res) or 0
            if res > 0 then
                table.insert(list, {
                    p = Utils.flat(unit:GetPivot().Position),
                    r = stats.range.Value,
                    d = res
                })
                count = count + res
            end
        end
    end
    if # list == 0 or count <= 0 then
        return nil
    end
    local list2 = {
    }
    for i, sample in ipairs(Match.samples) do
        local flat, count2 = (sample.flat or Utils.flat(sample.pos)), 0
        for _, item in ipairs(list) do
            if (flat - item.p).Magnitude <= item.r then
                count2 = count2 + item.d
            end
        end
        list2 [i] = count2 / count
    end
    local range = Units.range(arg1.u, math.min(tonumber(holds2) or 0, 3, Units.rows(arg1.id).max)) * ((Match.info and tonumber(Match.info.rangeScale)) or 1)
    local value, value2, value3
    local shapeMemo = Match.shapeInfo(arg1)
    local ranked = shapeMemo and {
    } or nil
    for i, cand in ipairs(Match.cands) do
        local flat, count, count2 = Utils.flat(cand), 0, 0
        for i, sample in ipairs(Match.samples) do
            if ((sample.flat or Utils.flat(sample.pos)) - flat).Magnitude <= range then
                count = count + list2 [i]
                count2 = count2 + 1
            end
        end
        if ranked and count > 0 then
            table.insert(ranked, {
                p = cand,
                v = count,
                c = count2
            })
        end
        if count > 0 and (not value2 or count > value2) then
            local valid = Match.valid(cand, arg1.data)
            if valid then
                value, value2, value3 = valid, count, count2
            end
        end
        if i % 40 == 0 then
            task.wait()
        end
    end
    -- Attack shape (2.22): the best free spot among the top ones by held damage × shape.
    if ranked and # ranked > 1 then
        local best = Match.shapeRerank(shapeMemo, ranked, function(item)
            item.valid = Match.valid(item.p, arg1.data)
            return item.valid ~= nil
        end)
        if best then
            value, value2, value3 = best.valid, best.v, best.c
        end
    end
    if not value then
        return nil
    end
    Match.holdSaid = Match.holdSaid or {
    }
    if not Match.holdSaid [arg1.id] then
        Match.holdSaid [arg1.id] = true
        App.log(1, "PLACE", string.format("%s holds enemies, so it stands where your attackers' damage is: what it holds stays under all of them", Units.name(arg1.id)))
    end
    return value, value3 or 0
end

-- Party front (2.25): other players hold the end of the road, so with another player in the match our attackers
-- stand nearer the start. Off with a leak (the leak rules come first) and in card modes.
function Match.partyFront()
    if not Config.partyFront or Match.random or (Match.depth and Match.depth.leak) then
        return false
    end
    local ok, players = pcall(function()
        return # Players:GetPlayers()
    end)
    return ok and (tonumber(players) or 1) > 1
end

-- Farms far from the road (2.25): extra spots 26-60 studs out (the usual ones end at 20.5), built once per map.
function Match.farmCandidates()
    if Match.farmCandsFor == Match.cands and Match.farmCandsList then
        return Match.farmCandsList
    end
    local list, seen = table.clone(Match.cands or {
    }), {
    }
    local samples = Match.samples or {
    }
    for i = 1, # samples, 4 do
        local sample = samples [i]
        local sample2 = samples [math.min(# samples, i + 1)]
        local flat = Utils.flat(sample2.pos - sample.pos)
        if flat.Magnitude < 0.01 then
            flat = Vector3.new(1, 0, 0)
        end
        flat = flat.Unit
        local side = Vector3.new(- flat.Z, 0, flat.X)
        for _, out in ipairs({
            26,
            33,
            41,
            50,
            60
        }) do
            for _, sign in ipairs({
                1,
                - 1
            }) do
                local pos = sample.pos + side * out * sign
                local key = string.format("%d,%d", math.floor(pos.X / 3), math.floor(pos.Z / 3))
                if not seen [key] then
                    seen [key] = true
                    table.insert(list, pos)
                end
            end
        end
    end
    Match.farmCandsFor, Match.farmCandsList = Match.cands, list
    return list
end

Match.FARM_CLEAR, Match.FARM_FAR = 30, 60

-- Higher is better: far from every road, little road within an attacker's reach, off the planner's attacker spots.
function Match.farmFarScore(valid, range)
    local flat = Utils.flat(valid)
    -- The road part is fixed for a spot: memo per spot and range while the road samples stay the same.
    if Match.farmMemoFor ~= Match.samples then
        Match.farmMemoFor, Match.farmMemo = Match.samples, {
        }
    end
    local key = string.format("%d,%d,%d", math.floor(flat.X), math.floor(flat.Z), math.floor(range))
    local score = Match.farmMemo [key]
    if not score then
        local near, nearProg = math.huge, 0
        for _, sample in ipairs(Match.samples or {
        }) do
            local d = ((sample.flat or Utils.flat(sample.pos)) - flat).Magnitude
            if d < near then
                near, nearProg = d, tonumber(sample.prog) or 0
            end
        end
        -- Far from the road first; between equally far spots, the one by the road's later part (the map's end).
        score = math.min(near, Match.FARM_FAR) + 3 * nearProg - Match.cover(valid, math.max(range, Match.FARM_CLEAR)) * 2 - Match.cover(valid, range) * 10
        Match.farmMemo [key] = score
    end
    for id, spots in pairs(Match.layout or {
    }) do
        if not Units.isFarm(id) and type(spots) == "table" then
            for _, spot in ipairs(spots) do
                if spot and (Utils.flat(spot) - flat).Magnitude < 8 then
                    return score - 200
                end
            end
        end
    end
    return score
end

function Match.teamOpeningSpot(unit)
    if not Match.allies or #Match.allies == 0 or Match.wave() > 5 or Match.joinedMid then
        return nil
    end
    if not Match.samples or not Match.cands or Units.allyBuff(unit.id) then
        return nil
    end
    local defenders = 0
    for _, model in ipairs(Match.mine) do
        local id = model._stats.id.Value
        if not Units.isFarm(id) and not Units.allyBuff(id) then
            defenders += 1
        end
    end
    if defenders >= 2 then return nil end

    local anchors = {}
    for _, model in ipairs(Match.allies) do
        local hitbox = model:FindFirstChild("_hitbox")
        local position = Utils.flat(hitbox and hitbox.Position or model:GetPivot().Position)
        local radius = hitbox and math.max(hitbox.Size.X, hitbox.Size.Z) / 2 or 1.5
        for _, sample in ipairs(Match.samples) do
            if sample.prog <= Match.FAST_ROAD and ((sample.flat or Utils.flat(sample.pos)) - position).Magnitude <= model._stats.range.Value then
                table.insert(anchors, {position = position, radius = radius})
                break
            end
        end
    end
    if #anchors == 0 then return nil end

    local range = Units.range(unit.u, 0) * ((Match.info and tonumber(Match.info.rangeScale)) or 1)
    local clearance = (tonumber(unit.data.override_hitbox_radius) or 1.5) + 0.25
    local opening = {}
    for _, sample in ipairs(Match.samples) do
        if sample.prog <= Match.FAST_ROAD then
            table.insert(opening, (sample.flat or Utils.flat(sample.pos)))
        end
    end
    local bestPosition, bestCoverage, bestScore, widestCoverage = nil, 0, 0, 0
    for index, candidate in ipairs(Match.cands) do
        local position = Match.valid(candidate, unit.data)
        if position then
            local flatPosition = Utils.flat(position)
            local covered = 0
            for _, point in ipairs(opening) do
                if (point - flatPosition).Magnitude <= range then covered += 1 end
            end
            widestCoverage = math.max(widestCoverage, covered)
            if covered > 0 then
                local nearest = math.huge
                for _, anchor in ipairs(anchors) do
                    local distance = (flatPosition - anchor.position).Magnitude
                    if distance < clearance + anchor.radius then
                        nearest = math.huge
                        break
                    end
                    nearest = math.min(nearest, distance)
                end
                if nearest <= 16 then
                    local score = covered * (1 + (16 - nearest) / 80)
                    if score > bestScore then
                        bestPosition, bestCoverage, bestScore = position, covered, score
                    end
                end
            end
        end
        if index % 40 == 0 then task.wait() end
    end
    if bestPosition and bestCoverage >= 0.75 * widestCoverage then
        return bestPosition, Match.cover(bestPosition, range)
    end
end

function Match.bestSpot(unit, isFarm, arg3)
    if Match.endMove and Config.endMove ~= false and not Match.focus then
        if isFarm or Units.isFarm(unit.id) or Units.allyBuff(unit.id) then return nil, 0 end
        return Match.endSpot(unit)
    end
    if Match.focus and not isFarm and not arg3 and not Units.allyBuff(unit.id) then
        local focusSpot, focusSpot2 = Match.focusSpot(unit)
        if focusSpot then
            return focusSpot, focusSpot2
        end
    end
    if Config.aiPlacement == false and not isFarm and not arg3 and not (Match.depth and Match.depth.leak) then
        local ok, res, res2 = pcall(Match.controlSpot, unit)
        if ok and res then
            return res, res2
        end
        local ok, res, res2 = pcall(Match.holdSpot, unit)
        if ok and res then
            return res, res2
        end
    end
    local leak = Match.depth and Match.depth.leak
    if not isFarm and not arg3 and not leak and not Match.focus and not Match.trialId and not Match.trainee then
        local allySpot, coverage = Match.teamOpeningSpot(unit)
        if allySpot then return allySpot, coverage, true end
    end
    if Config.aiPlacement ~= false and not leak and not arg3 and not Match.focus then
        local aiAllyBuff = Units.allyBuff(unit.id)
        local aiIsFarm = isFarm or Units.isFarm(unit.id)
        local aiSkip = false
        if isFarm and not Units.isFarm(unit.id) and not (Match.random and Units.idol and Units.idol(unit.id)) then
            aiSkip = true
        end
        if not aiSkip and not aiIsFarm and not aiAllyBuff and Match.partyFront() then
            aiSkip = true
        end
        if not aiSkip and Match.infinite and Match.trainee and unit.uuid ~= Match.trainee and not aiIsFarm and not aiAllyBuff and (Match.pressure or 0) < Config.dangerReach then
            aiSkip = true
        end
        if not aiSkip and Match.random then
            if isFarm and Units.isFarm(unit.id) then
                if (Match.farmMergeSpot and Match.farmMergeSpot(unit)) or (Match.farmMergeOk and Match.farmMergeOk()) then
                    aiSkip = true
                end
            elseif not aiAllyBuff and Match.mergeSpot and Match.mergeSpot(unit) then
                aiSkip = true
            end
        end
        if not aiSkip and aiAllyBuff and aiAllyBuff.chain and Units.chainOn() then
            local _, aiSquadCopies = Match.squadAndRelays(aiAllyBuff)
            local aiNeed = aiAllyBuff.squad or Units.BUFF_COPIES
            if aiSquadCopies and #aiSquadCopies >= aiNeed then
                aiSkip = true
            end
        end
        if not aiSkip then
            local okAi, aiSpot, aiCover, aiScore = pcall(AI.chooseSpot, unit, isFarm)
            if okAi and aiSpot then
                if Match.layout and Match.layout[unit.id] then
                    Match.layoutUsed = Match.layoutUsed or {}
                    Match.layoutUsed[unit.id] = Match.layoutUsed[unit.id] or aiSpot
                end
                App.log(2, "AI_PLACE", string.format("%s -> %s (cover=%.0f, score=%.3f)", Units.name(unit.id), Match.spotKey(aiSpot), tonumber(aiCover) or 0, tonumber(aiScore) or 0))
                return aiSpot, aiCover or 0
            end
        end
    end
    local data = unit.data
    local depth = Match.depth
    local rangeScale = (Match.info and tonumber(Match.info.rangeScale)) or 1
    local range = Units.range(unit.u, (depth and depth.leak) and 0 or math.min(3, Units.rows(unit.id).max)) * rangeScale
    local range2 = (Match.kind == "dungeon" or Match.style == "box" or Match.style == "fast") and not isFarm and not (depth and depth.leak) and not Units.isFarm(unit.id) and Units.range(unit.u, Units.rows(unit.id).max) * rangeScale or nil
    local allyBuff = Units.allyBuff(unit.id)
    local _, types2 = Units.types(unit.id)
    local chainOn = Units.chainOn()
    local fieldBuffers = allyBuff and {
    } or Match.fieldBuffers()
    local squadCircles = {
    }
    if not isFarm and not Units.isFarm(unit.id) and not allyBuff and chainOn then
        local seenAtk = {
        }
        for _, fb in ipairs(fieldBuffers) do
            if fb.b.chain and fb.b.types [types2] and not seenAtk [fb.b.attack] then
                seenAtk [fb.b.attack] = true
                local needSz = fb.b.squad or Units.BUFF_COPIES
                local _, sc = Match.squadAndRelays(fb.b)
                if sc and # sc >= needSz then
                    local list = {
                    }
                    for i = 1, needSz do
                        table.insert(list, {
                            flat = buffFlat(sc [i].pos),
                            range = sc [i].range
                        })
                    end
                    squadCircles = list
                    break
                else
                    local tpl = Match.buffTemplates and Match.buffTemplates [fb.b.attack]
                    if tpl and type(tpl.spots) == "table" and # tpl.spots >= needSz then
                        local list = {
                        }
                        for i = 1, needSz do
                            table.insert(list, {
                                flat = buffFlat(tpl.spots [i]),
                                range = fb.range
                            })
                        end
                        squadCircles = list
                        break
                    end
                end
            end
        end
    end
    -- Buff at a spot (2.24): the same bonus in the kill-zone, fast-clear and general searches.
    local buffAt = Match.buffBonusFn(fieldBuffers, types2, chainOn)
    local function inAllSquad(pos)
        if # squadCircles == 0 then
            return false
        end
        local flat = buffFlat(pos)
        for _, sc in ipairs(squadCircles) do
            if buffDistSq(flat, sc.flat) > sc.range * sc.range then
                return false
            end
        end
        return true
    end
    local partyFront = not isFarm and not arg3 and not allyBuff and not Units.isFarm(unit.id) and Match.partyFront()
    if Match.layout and Match.layout [unit.id] and not isFarm and not arg3 and not partyFront then
        local layoutSpot, layoutCover
        for _, value in ipairs(Match.layout [unit.id]) do
            local valid = Match.valid(value, unit.data)
            if valid and leak then
                local flag, flat, leakRange = false, Utils.flat(valid), Units.range(unit.u, 0) * rangeScale
                for _, sample in ipairs(Match.samples) do
                    if sample.prog >= leak + 0.02 and ((sample.flat or Utils.flat(sample.pos)) - flat).Magnitude <= leakRange then
                        flag = true
                        break
                    end
                end
                if not flag then
                    valid = nil
                end
            end
            if valid then
                layoutSpot, layoutCover = valid, Match.cover(valid, range)
                break
            end
        end
        if layoutSpot then
            local skipLayout = false
            if # squadCircles >= 4 and not inAllSquad(layoutSpot) then
                for _, cand in ipairs(Match.cands) do
                    local valid = Match.valid(cand, unit.data)
                    if valid and inAllSquad(valid) and Match.cover(valid, range) >= Match.BUFF_SPOT_SHARE * layoutCover then
                        skipLayout = true
                        break
                    end
                end
            end
            if not skipLayout then
                Match.layoutUsed = Match.layoutUsed or {
                }
                Match.layoutUsed [unit.id] = Match.layoutUsed [unit.id] or layoutSpot
                return layoutSpot, layoutCover
            end
        end
    end
    local value
    if arg3 then
        value = 1
        for _, unit2 in ipairs(Match.mine or {
        }) do
            local stats = unit2._stats
            if not Units.isFarm(stats.id.Value) and not (stats:FindFirstChild("uuid") and stats.uuid.Value == unit.uuid) then
                local flat, rangeValue = Utils.flat(unit2:GetPivot().Position), stats.range.Value
                for _, sample in ipairs(Match.samples) do
                    if sample.prog < value and ((sample.flat or Utils.flat(sample.pos)) - flat).Magnitude <= rangeValue then
                        value = sample.prog
                    end
                end
            end
        end
        if Units.ENTRY [unit.id] or (Match.studyEntry and unit.id == Match.trialId) then
            value = math.min(value, 0.1)
        end
    end
    if allyBuff and allyBuff.chain and chainOn then
        local mates, squadCopies, relayCopies = Match.squadAndRelays(allyBuff)
        local need = allyBuff.squad or Units.BUFF_COPIES
        if squadCopies and # squadCopies >= need then
            local relaySpot, relayCover = Match.bestRelaySpot(unit, allyBuff, squadCopies, relayCopies)
            return relaySpot, relayCover or 0
        else
            local tplSpot, tplCover = Match.buffTemplateSpot(unit, allyBuff, mates)
            if tplSpot then
                return tplSpot, tplCover or 0
            end
        end
    end
    if Match.killZone() and not partyFront and not isFarm and not arg3 and not allyBuff and not (depth and depth.leak) and not Units.isFarm(unit.id) then
        local range22 = range2 or range
        local list = {
        }
        for _, unit in ipairs(Match.mine or {
        }) do
            local stats = unit._stats
            local idValue = stats.id.Value
            if not Units.isFarm(idValue) and not Units.allyBuff(idValue) and stats:FindFirstChild("range") then
                table.insert(list, {
                    p = Utils.flat(unit:GetPivot().Position),
                    r = stats.range.Value
                })
            end
        end
        local list2 = {
        }
        for i, sample in ipairs(Match.samples) do
            local count = 0
            local flat = (sample.flat or Utils.flat(sample.pos))
            for _, item in ipairs(list) do
                local dx = flat.X - item.p.X
                local dz = flat.Z - item.p.Z
                if dx * dx + dz * dz <= item.r * item.r then
                    count = count + 1
                end
            end
            list2 [i] = count
        end
        local value, value2, value3
        local zoneTop, zoneRoad = 0, {
        }
        local r22Sq = range22 * range22
        local shapeMemo = Match.shapeInfo(unit)
        local ranked = shapeMemo and {
        } or nil
        for _, cand in ipairs(Match.cands) do
            Match.spotScan = (Match.spotScan or 0) + 1
            if Match.spotScan % 100 == 0 then
                task.wait()
            end
            local valid = Match.valid(cand, data)
            if valid then
                local flat, count, count2 = Utils.flat(valid), 0, 0
                for i, sample in ipairs(Match.samples) do
                    local sFlat = sample.flat or Utils.flat(sample.pos)
                    local dx = sFlat.X - flat.X
                    local dz = sFlat.Z - flat.Z
                    if dx * dx + dz * dz <= r22Sq then
                        count2 = count2 + 1
                        if sample.prog >= 0.6 then
                            count = count + (sample.prog - 0.5) * (1 + list2 [i])
                        end
                    end
                end
                zoneTop = math.max(zoneTop, count)
                zoneRoad [valid] = count
                if buffAt and count > 0 then
                    count = count * (1 + buffAt(valid))
                end
                if ranked and count > 0 then
                    table.insert(ranked, {
                        p = valid,
                        v = count,
                        c = count2
                    })
                end
                if not value2 or count > value2 then
                    value, value2, value3 = valid, count, count2
                end
            end
        end
        local best = ranked and # ranked > 1 and Match.shapeRerank(shapeMemo, ranked)
        if best then
            value, value2, value3 = best.p, best.v, best.c
        end
        if value and value2 > 0 and buffAt then
            Match.buffSpotSay(unit, zoneRoad [value], zoneTop, buffAt(value))
        end
        if value and value2 > 0 then
            if not Match.zoneSaid then
                Match.zoneSaid = true
                App.log(1, "PLACE", "attackers stack on the road's last stretch, so what walks in takes everyone's damage at once")
            end
            return value, value3 or 0
        end
    end
    if Match.style == "fast" and not isFarm and not arg3 and not allyBuff and not (depth and depth.leak) and not Units.isFarm(unit.id) then
        local range22 = range2 or range
        local r22Sq = range22 * range22
        local value, value2, value3
        local fastTop, fastRoad = 0, {
        }
        local fastMemo = Match.shapeInfo(unit)
        local fastRanked = fastMemo and {
        } or nil
        for _, cand in ipairs(Match.cands) do
            Match.spotScan = (Match.spotScan or 0) + 1
            if Match.spotScan % 100 == 0 then
                task.wait()
            end
            local valid = Match.valid(cand, data)
            if valid then
                local flat, count, count2 = Utils.flat(valid), 0, 0
                local inSamples = Match.samplesInRange and Match.samplesInRange(flat, range22) or Match.samples
                for _, sample in ipairs(inSamples) do
                    local sFlat = sample.flat or Utils.flat(sample.pos)
                    local dx = sFlat.X - flat.X
                    local dz = sFlat.Z - flat.Z
                    if dx * dx + dz * dz <= r22Sq then
                        count2 = count2 + 1
                        if sample.prog <= Match.FAST_ROAD then
                            count = count + 1.5 - sample.prog
                        end
                    end
                end
                fastTop = math.max(fastTop, count)
                fastRoad [valid] = count
                if buffAt and count > 0 then
                    count = count * (1 + buffAt(valid))
                end
                if fastRanked and count > 0 then
                    table.insert(fastRanked, {
                        p = valid,
                        v = count,
                        c = count2
                    })
                end
                if not value2 or count > value2 then
                    value, value2, value3 = valid, count, count2
                end
            end
        end
        local best = fastRanked and # fastRanked > 1 and Match.shapeRerank(fastMemo, fastRanked)
        if best then
            value, value2, value3 = best.p, best.v, best.c
        end
        if value and value2 > 0 and buffAt then
            Match.buffSpotSay(unit, fastRoad [value], fastTop, buffAt(value))
        end
        if value and value2 > 0 then
            return value, value3 or 0
        end
    end
    local zone = Match.infinite and Match.trainee and not arg3 and unit.uuid ~= Match.trainee and not Units.isFarm(unit.id) and not allyBuff and not isFarm and not (depth and depth.leak) and (Match.pressure or 0) < Config.dangerReach and Training.ZONE or nil
    local range3 = zone and Units.range(unit.u, Units.rows(unit.id).max) or nil
    local list, count = {
    }, 0
    if allyBuff then
        list = Match.buffShort(allyBuff)
        for _, item in ipairs(list) do
            count = count + item.dps
        end
    end
    local tip = Config.community and not value and Core.TIPS [unit.id]
    local flag = ((tip and tip.spot == "exit" and not partyFront) or (not value and not partyFront and Match.needLastLine(unit))) and not (depth and depth.leak)
    local mergeSpot = not (value or isFarm or allyBuff) and Match.mergeSpot(unit)
    local range4 = mergeSpot and Units.range(unit.u, 0) * 0.7
    local farmMergeSpot, value2
    if isFarm and Units.isFarm(unit.id) then
        farmMergeSpot, value2 = Match.farmMergeSpot(unit)
        value2 = farmMergeSpot and value2 * 0.8
    end
    local list2 = isFarm and not farmMergeSpot and Match.random and Units.isFarm(unit.id) and Match.farmMergeOk() and {
    } or nil
    local cands = Match.cands
    local farFarm = isFarm and Config.farmFar and Units.isFarm(unit.id) and not farmMergeSpot and not list2
    if farFarm then
        cands = Match.farmCandidates()
    end
    local farmMergeSpot2, value22 = farmMergeSpot or mergeSpot, farmMergeSpot and value2 or range4
    if farmMergeSpot2 and value22 and value22 > 0 then
        cands = table.clone(Match.cands)
        for _, value in ipairs({
            0.5,
            0.7,
            0.9
        }) do
            for i = 0, 11 do
                local ratio = i * math.pi / 6
                table.insert(cands, farmMergeSpot2 + Vector3.new(math.cos(ratio), 0, math.sin(ratio)) * value22 * value)
            end
        end
    end
    local value3, value4, cover
    local dens = Brain.maps [Match.mapKey()] and Brain.maps [Match.mapKey()].dens
    -- Auto Buff: copies of one buffer stand as a group. A spot counts as linked when the new copy
    -- reaches every copy already down and they reach it.
    local mates, range0 = nil, Units.range(unit.u, 0) * rangeScale
    if allyBuff and allyBuff.chain and Units.chainOn() then
        mates = {
        }
        for _, fieldBuffer in ipairs(Match.fieldBuffers()) do
            if fieldBuffer.b.attack == allyBuff.attack then
                table.insert(mates, fieldBuffer)
            end
        end
    end
    if mates and # mates > 0 then
        -- Spots around the group, so a spot that reaches every copy is there to be found.
        local center, reach = Vector3.new(0, 0, 0), range0
        for _, mate in ipairs(mates) do
            center = center + mate.pos
            reach = math.min(reach, mate.range)
        end
        center = center / # mates
        if cands == Match.cands then
            cands = table.clone(Match.cands)
        end
        table.insert(cands, center)
        for _, part in ipairs({
            0.2,
            0.4,
            0.6
        }) do
            for i = 0, 11 do
                local angle = i * math.pi / 6
                table.insert(cands, center + Vector3.new(math.cos(angle), 0, math.sin(angle)) * reach * part)
            end
        end
    end
    local bestUnbuffedScore, bestUnbuffedRoad = nil, 0
    local fullSquadCands = {
    }
    -- Attack shape (2.22): a plain attacker's best spots by road are re-ranked by its shape.
    local plainMemo = not (isFarm or Units.isFarm(unit.id) or allyBuff or value or zone or flag or mergeSpot or farmMergeSpot or (mates and # mates > 0) or (depth and depth.leak)) and Match.shapeInfo(unit) or nil
    local plainRanked = plainMemo and {
    } or nil
    local checkFullSquad = # squadCircles >= 4 and not isFarm and not allyBuff and not value and not zone and not flag and not mergeSpot and not farmMergeSpot
    for _, cand in ipairs(cands) do
        Match.spotScan = (Match.spotScan or 0) + 1
        if Match.spotScan % 100 == 0 then
            task.wait()
        end
        local valid = Match.valid(cand, data)
        if valid then
            local cover2, rawRoad, unbuffedScore
            if isFarm then
                cover2 = farFarm and Match.farmFarScore(valid, range) or - Match.cover(valid, range)
            elseif value then
                cover2 = 0
                local flat = Utils.flat(valid)
                for _, sample in ipairs(Match.samples) do
                    if ((sample.flat or Utils.flat(sample.pos)) - flat).Magnitude <= range then
                        cover2 = cover2 + (sample.prog <= value + 0.05 and 1 or 0.1)
                    end
                end
            elseif zone then
                cover2 = 0
                local flat = Utils.flat(valid)
                for _, sample in ipairs(Match.samples) do
                    local magnitude = ((sample.flat or Utils.flat(sample.pos)) - flat).Magnitude
                    if sample.prog < zone then
                        if magnitude <= range3 then
                            cover2 = cover2 - 2
                        end
                    elseif magnitude <= range then
                        cover2 = cover2 + 1
                    end
                end
            elseif flag then
                cover2 = 0
                local flat = Utils.flat(valid)
                for _, sample in ipairs(Match.samples) do
                    if ((sample.flat or Utils.flat(sample.pos)) - flat).Magnitude <= range then
                        cover2 = cover2 + sample.prog * sample.prog
                    end
                end
            elseif allyBuff and count > 0 then
                local count2 = 0
                for _, item in ipairs(list) do
                    local magnitude = (Utils.flat(item.pos) - Utils.flat(valid)).Magnitude
                    if magnitude <= range then
                        count2 = count2 + item.dps * (1.1 - 0.1 * magnitude / math.max(1, range))
                    end
                end
                cover2 = count2 / count * 100 + Match.cover(valid, range, true) * 0.05
            else
                local cover = Match.cover(valid, range, true, depth)
                if range2 then
                    cover = Match.cover(valid, range2) + cover * 0.25
                end
                cover2 = cover + (dens and 0 or (1 - Match.progressAt(valid)) * 0.5)
                if partyFront then
                    cover2 = cover2 * (0.5 + 1.5 * (1 - Match.progressAt(valid)))
                end
                unbuffedScore = cover2
                rawRoad = Match.cover(valid, range)
                local count = buffAt and buffAt(valid) or 0
                cover2 = cover2 * (1 + count)
                if plainRanked and cover2 > 0 then
                    table.insert(plainRanked, {
                        p = valid,
                        v = cover2,
                        road = rawRoad
                    })
                end
            end
            if checkFullSquad and unbuffedScore then
                if not bestUnbuffedScore or unbuffedScore > bestUnbuffedScore then
                    bestUnbuffedScore, bestUnbuffedRoad = unbuffedScore, rawRoad or 0
                end
                if inAllSquad(valid) then
                    table.insert(fullSquadCands, {
                        pos = valid,
                        sc = cover2,
                        road = rawRoad or 0
                    })
                end
            end
            if mates and # mates > 0 then
                -- A copy that reaches every copy already down (and is reached by them) always wins.
                local linked = 0
                for _, mate in ipairs(mates) do
                    if (Utils.flat(mate.pos) - Utils.flat(valid)).Magnitude <= math.min(range0, mate.range) then
                        linked = linked + 1
                    end
                end
                cover2 = cover2 + (linked == # mates and 1e5 or 0) + 1000 * linked / # mates
            end
            if mergeSpot and (Utils.flat(mergeSpot) - Utils.flat(valid)).Magnitude <= range4 then
                cover2 = cover2 + 1e6
            end
            if farmMergeSpot and (Utils.flat(farmMergeSpot) - Utils.flat(valid)).Magnitude <= value2 then
                cover2 = cover2 + 1e6
            end
            if list2 then
                table.insert(list2, {
                    p = valid,
                    sc = cover2
                })
            end
            if not value4 or cover2 > value4 then
                value3, value4, cover = valid, cover2, rawRoad or Match.cover(valid, range)
            end
        end
    end
    if plainRanked and # plainRanked > 1 then
        local best = Match.shapeRerank(plainMemo, plainRanked)
        if best then
            value3, value4, cover = best.p, best.v2, best.road or Match.cover(best.p, range)
        end
    end
    if checkFullSquad and # fullSquadCands > 0 and bestUnbuffedRoad > 0 then
        local bestFull
        local minRoad = Match.BUFF_SPOT_SHARE * bestUnbuffedRoad
        for _, cand in ipairs(fullSquadCands) do
            if cand.road >= minRoad and (not bestFull or cand.sc > bestFull.sc) then
                bestFull = cand
            end
        end
        if bestFull then
            value3, value4, cover = bestFull.pos, bestFull.sc, bestFull.road
        end
    end
    if allyBuff and # list > 0 and value3 and not (mates and # mates > 0) then
        local flag = false
        for _, item in ipairs(list) do
            if (Utils.flat(item.pos) - Utils.flat(value3)).Magnitude <= range then
                flag = true
                break
            end
        end
        if not flag then
            return nil, 0
        end
    end
    if list2 and # list2 > 0 then
        table.sort(list2, function(arg1, arg2)
            return arg1.sc > arg2.sc
        end)
        for i = 1, math.min(15, # list2) do
            local p, count = list2 [i].p, 0
            for i = 0, 7 do
                local ratio = i * math.pi / 4
                if Match.valid(p + Vector3.new(math.cos(ratio), 0, math.sin(ratio)) * 5, data) then
                    count = count + 1
                end
                if count >= 2 then
                    break
                end
            end
            if count >= 2 then
                return p, Match.cover(p, range)
            end
        end
    end
    return value3, cover or 0
end

function Match.lookAt(bestSpot, unitEntry)
    local flatOrigin = Utils.flat(bestSpot)
    if unitEntry and unitEntry.id and Match.samples and #Match.samples > 0 then
        local rows = Units.rows(unitEntry.id)
        local row = rows and (rows[rows.max] or rows[0])
        local atkName = row and row.atk
        local atk = atkName and (Core.Attacks[atkName] or Units.fillAttack(atkName))
        if type(atk) == "table" and type(atk.aoe) == "table" then
            local aoeKind, coneCos, lineHalf = nil, 0.7, 3.5
            for _, part in pairs(atk.aoe) do
                if type(part) == "table" and type(part.aoe_type) == "table" then
                    local t = part.aoe_type.type
                    if t == "straight" or t == "line" then
                        aoeKind = "line"
                        lineHalf = Units.lineHalf(part.aoe_type.width)
                        break
                    elseif t == "cone" then
                        aoeKind = "cone"
                        coneCos = math.cos(math.rad((tonumber(part.aoe_type.angle) or 45) / 2))
                        break
                    end
                end
            end
            if aoeKind then
                local range = Units.range(unitEntry.u, rows.max or 0) * ((Match.info and tonumber(Match.info.rangeScale)) or 1)
                local rangeSq = range * range
                local inRange = {}
                local sumVx, sumVz, sumW = 0, 0, 0
                local matchedSamples = Match.samplesInRange and Match.samplesInRange(flatOrigin, range) or Match.samples
                for _, s in ipairs(matchedSamples) do
                    local sFlat = s.flat or Utils.flat(s.pos)
                    local vx = sFlat.X - flatOrigin.X
                    local vz = sFlat.Z - flatOrigin.Z
                    local distSq = vx * vx + vz * vz
                    if distSq > 0.01 and distSq <= rangeSq then
                        local w = 1 + (s.prog or 0)
                        sumVx = sumVx + vx * w
                        sumVz = sumVz + vz * w
                        sumW = sumW + w
                        table.insert(inRange, { vx = vx, vz = vz, distSq = distSq, prog = s.prog or 0 })
                    end
                end
                if #inRange > 0 then
                    local candDirs = {}
                    local sumLenSq = sumVx * sumVx + sumVz * sumVz
                    if sumLenSq > 0.001 then
                        local invLen = 1 / math.sqrt(sumLenSq)
                        table.insert(candDirs, Vector3.new(sumVx * invLen, 0, sumVz * invLen))
                    end
                    for _, pt in ipairs(inRange) do
                        local lenSq = pt.distSq
                        if lenSq > 0.001 then
                            local invLen = 1 / math.sqrt(lenSq)
                            table.insert(candDirs, Vector3.new(pt.vx * invLen, 0, pt.vz * invLen))
                        end
                    end
                    local coneCosSq = coneCos * coneCos
                    local bestDir, bestHits = nil, -1
                    for _, candDir in ipairs(candDirs) do
                        local dx, dz = candDir.X, candDir.Z
                        local hits = 0
                        for _, pt in ipairs(inRange) do
                            local dot = pt.vx * dx + pt.vz * dz
                            if dot > 0 and dot <= range then
                                if aoeKind == "cone" then
                                    if dot * dot >= coneCosSq * pt.distSq then
                                        hits = hits + (1 + pt.prog)
                                    end
                                else
                                    local cross = pt.vx * dz - pt.vz * dx
                                    if cross < 0 then cross = -cross end
                                    if cross <= lineHalf then
                                        hits = hits + (1 + pt.prog)
                                    end
                                end
                            end
                        end
                        if hits > bestHits then
                            bestHits, bestDir = hits, candDir
                        end
                    end
                    if bestDir and bestHits > 0 then
                        return bestDir
                    end
                end
            end
        end
    end
    local huge, pos = math.huge, nil
    for _, sample in ipairs(Match.samples) do
        local sFlat = sample.flat or Utils.flat(sample.pos)
        local dx = sFlat.X - flatOrigin.X
        local dz = sFlat.Z - flatOrigin.Z
        local distSq = dx * dx + dz * dz
        if distSq < huge then
            huge, pos = distSq, sample.pos
        end
    end
    local flat = pos and Utils.flat(pos - bestSpot) or Vector3.new(0, 0, - 1)
    return flat.Magnitude > 0.01 and flat.Unit or Vector3.new(0, 0, - 1)
end

-- The yen a placement really costs: some modes raise every unit's price.
function Match.spawnCost(member)
    local ok, mul = pcall(Core.USC.calculate_spawn_cost_multiplier, Core.session())
    return (tonumber(member.data.cost) or 0) * (ok and tonumber(mul) or 1)
end

-- A refusal the game explains with money or a unit limit says nothing about the spot.
function Match.refusalNotSpot(message)
    message = string.lower(tostring(message or ""))
    for _, word in ipairs({"yen", "money", "afford", "limit", "max"}) do
        if message:find(word, 1, true) then
            return true
        end
    end
    return false
end

function Match.place(member, decide)
    local isFarm = Units.isFarm(member.id)
    local bestSpot, bestSpot2, teamOpening = Match.bestSpot(member, isFarm or (Match.random and Units.idol(member.id)), (Match.trainee ~= nil and member.uuid == Match.trainee) or Units.ENTRY [member.id] == true or (Match.studyEntry == true and member.id == Match.trialId))
    if not bestSpot then
        Match.noSpot [member.uuid] = (Match.noSpot [member.uuid] or 0) + 1
        App.status("Placement", "no free spot for " .. Units.name(member.id))
        return false
    end
    local money = Match.money()
    local cost = Match.spawnCost(member)
    local askedAt = Utils.now()
    local ok, res = App.request("place", "spawn_unit", member.uuid, Core.Util.CFramePLV(bestSpot, Match.lookAt(bestSpot, member)))
    if ok and res then
        if teamOpening then decide = tostring(decide) .. " · near allies at the road entrance" end
        Match.spent = Match.spent + cost
        table.insert(Match.actions, string.format("placed %s", Units.name(member.id)))
        App.log(1, "PLACE", string.format("%s at %s (covers %d road samples) — %s", Units.name(member.id), Match.spotKey(bestSpot), bestSpot2, decide))
        Match.placeLog = Match.placeLog or {
        }
        table.insert(Match.placeLog, {
            t = math.floor(Utils.now() - (Match.startT or Utils.now())),
            w = Match.wave(),
            id = member.id,
            x = math.floor(bestSpot.X),
            z = math.floor(bestSpot.Z),
            cover = math.floor((bestSpot2 or 0) + 0.5),
            why = tostring(decide):sub(1,
            90)
        })
        App.status("Placement", string.format("placed %s — %s", Units.name(member.id), decide))
        Match.placedAt = Match.placedAt or {
        }
        Match.placedAt [member.uuid] = (Match.placedAt [member.uuid] or 0) + 1
        return true
    end
    local gameSaid = App.gameSaid(askedAt)
    if money >= cost and Match.random then
        Match.placeFail = Match.placeFail or {
        }
        Match.placeFail [member.uuid] = (Match.placeFail [member.uuid] or 0) + 1
        if Match.placeFail [member.uuid] >= 2 then
            Match.noSpot [member.uuid] = 3
            App.log(1, "PLACE", string.format("the game refused %s twice (%d/%d units counted) — buying something else", Units.name(member.id), Match.fieldCount(), Match.FIELD_MAX))
        end
    end
    if ok and money >= cost and not Match.random and Match.refusalNotSpot(gameSaid) then
        App.log(2, "PLACE", string.format("%s refused (%s): the spot stays allowed", Units.name(member.id), tostring(gameSaid)))
    elseif ok and money >= cost and not Match.random then
        local fc = Match.fieldCount()
        local capNow = Units.cap(member.u)
        local cntNow = Match.count(member.uuid)
        if fc >= (Match.effectiveFieldMax or Match.FIELD_MAX) or cntNow >= capNow then
            return false
        end
        local spotKey = Match.spotKey(bestSpot)
        Match.refused [spotKey] = true
        local mapKey = Match.mapKey()
        Brain.blocked [mapKey] = Brain.blocked [mapKey] or {
        }
        -- Require 2 refusals on the spot in the same run before permanently penalizing Brain.blocked
        Match.spotRefusalCount = Match.spotRefusalCount or {}
        Match.spotRefusalCount[spotKey] = (Match.spotRefusalCount[spotKey] or 0) + 1
        if Match.spotRefusalCount[spotKey] >= 2 and not Match.refusedRun [spotKey] then
            Brain.blocked [mapKey] [spotKey] = (tonumber(Brain.blocked [mapKey] [spotKey]) or 0) + 1
            Brain.blockedAt [mapKey] = Brain.blockedAt [mapKey] or {
            }
            Brain.blockedAt [mapKey] [spotKey] = os.time()
            Match.refusedRun [spotKey] = true
        end
        Match.refusals = (Match.refusals or 0) + 1
        Match.unitRefusals [member.uuid] = (Match.unitRefusals [member.uuid] or 0) + 1
        if Match.unitRefusals [member.uuid] >= 3 and cntNow > 0 then
            local value = math.max(1, cntNow)
            if Brain.caps [member.uuid] ~= value then
                Brain.caps [member.uuid] = value
                App.log(1, "PLACE", string.format("%s: the server allows %d on the field (learned)", Units.name(member.id), value))
            end
        elseif Match.refusals >= 4 and fc >= 12 and cntNow == 0 then
            Match.effectiveFieldMax = math.min(Match.effectiveFieldMax or Match.FIELD_MAX, fc)
            App.log(1, "PLACE", string.format("field cap learned as %d/%d after server refusals", Match.effectiveFieldMax, Match.FIELD_MAX))
        end
        App.log(2, "PLACE", "refused spot " .. spotKey .. " for " .. Units.name(member.id) .. (gameSaid and (" (the game said: " .. gameSaid .. ")") or ""))
        App.saveSoon()
    end
    return false
end

function Match.count(uuid)
    local count = 0
    for _, inst in ipairs({
        workspace._UNITS,
        workspace:FindFirstChild("_DEAD_UNITS")
    }) do
        if inst then
            for _, child in ipairs(inst:GetChildren()) do
                local stats = child:FindFirstChild("_stats")
                if stats and stats:FindFirstChild("uuid") and stats.player.Value == LocalPlayer and stats.uuid.Value == uuid then
                    count = count + 1
                end
            end
        end
    end
    return count
end

function Match.measure()
    local calRun, info = Match.calRun, Match.info
    if not (calRun and info) then
        return
    end
    pcall(Match.sampleHelpers)
    local now = Utils.now()
    local wave = Match.wave()
    local money = Match.money()
    if not calRun.start and money > 0 and # Match.mine == 0 then
        calRun.start = money
    end
    if wave ~= calRun.lastW then
        if Match.trialId and wave > 0 then
            Match.trialTrace = Match.trialTrace or {
            }
            local count, list, count2, count3 = 0, {
            }, 0, 0
            for _, unit in ipairs(Match.mine) do
                local stats = unit._stats
                if stats.id.Value == Match.trialId then
                    count = count + 1
                    table.insert(list, tostring(stats.upgrade.Value))
                elseif not Units.isFarm(stats.id.Value) then
                    count3 = count3 + 1
                end
            end
            pcall(Match.sampleHelpers, true)
            for _, value in pairs(Match.ownDealt) do
                if value.id == Match.trialId then
                    count2 = count2 + value.v
                end
            end
            local count = 0
            for _, value in pairs(Match.helperDealt) do
                if value.owner == Match.trialId then
                    count = count + value.v
                end
            end
            table.insert(Match.trialTrace, string.format("w%d t=%.0f ¥%d copies[%s] others %d dealt %.0f alive %d hp %.0f front %.2f dps %.0f", wave, now - (Match.startT or now), money, table.concat(list, ","), count3, count2 + count, # (Match.enemies or {
            }), Match.hpAliveRaw or 0, Match.waveMax [wave - 1] or 0, Match.teamDps or 0))
        end
        if calRun.lastW and calRun.lastW > 0 and calRun.lastWT then
            table.insert(calRun.waveSec, now - calRun.lastWT)
        end
        if calRun.paidT and wave > 0 and now - calRun.paidT < 15 then
            table.insert(calRun.skip, now - calRun.paidT)
        end
        calRun.paidT = nil
        if wave > 0 then
            calRun.alive [tostring(wave)] = Match.hpAliveRaw or 0
        end
        if wave == Match.total then
            calRun.moveFinalSeen = calRun.lastW == Match.total - 1
        end
        calRun.lastW, calRun.lastWT = wave, now
    end
    local waveTime = workspace:FindFirstChild("_wave_time")
    if waveTime and wave > 0 then
        calRun.timer [tostring(wave)] = math.max(calRun.timer [tostring(wave)] or 0, tonumber(waveTime.Value) or 0)
    end
    local money2 = money - (Match.lastMoneyR or money)
    Match.lastMoneyR = money
    Match.incomeLog = Match.incomeLog or {
    }
    if money2 > 0 then
        table.insert(Match.incomeLog, {
            t = now,
            y = money2
        })
    end
    while Match.incomeLog [1] and now - Match.incomeLog [1].t > 30 do
        table.remove(Match.incomeLog, 1)
    end
    local count = 0
    for _, value in ipairs(Match.incomeLog) do
        count = count + value.y
    end
    local value = math.min(30, now - (Match.startT or now))
    Match.incomeRate = value >= 8 and count / value or nil
    for _, enemy in ipairs(Match.enemies) do
        local m = enemy.m
        local value = Match.track [m]
        if not value then
            local stats = m._stats
            local humanoid = m:FindFirstChildOfClass("Humanoid")
            local value = info.cfgById [stats.id.Value]
            local baseStats = value and Simulator.baseStats(info, value)
            if humanoid and baseStats and wave > 0 then
                local baseStats2 = baseStats * info.hpRaw * Simulator.waveScale(info, wave, info.list [wave])
                if baseStats2 > 0 and humanoid.MaxHealth > 0 then
                    table.insert(calRun.hp, humanoid.MaxHealth / baseStats2)
                end
            end
            Match.track [m] = {
                t = now,
                p = enemy.prog,
                sp = (stats:FindFirstChild("speed") and tonumber(stats.speed.Value)) or 1
            }
            if wave > 0 then
                calRun.spawn [tostring(wave)] = (calRun.spawn [tostring(wave)] or 0) + 1
                calRun.spawnLast [tostring(wave)] = now - (calRun.lastWT or now)
                calRun.moveLastNew = now
                calRun.moveSpawn = calRun.moveSpawn or {}
                local ids = calRun.moveSpawn[tostring(wave)] or {}
                calRun.moveSpawn[tostring(wave)] = ids
                local id = stats.id.Value
                ids[id] = (ids[id] or 0) + 1
            end
        elseif not value.done and now - value.t >= 15 then
            value.done = true
            local ratio = (enemy.prog - value.p) / (now - value.t) / math.max(0.1, value.sp)
            if ratio > 0.001 and enemy.prog < 0.95 then
                table.insert(calRun.walk, ratio)
            end
        end
    end
    local count = 0
    for _, unit in ipairs(Match.mine) do
        local totalDamage = unit._stats:FindFirstChild("total_damage")
        if totalDamage then
            count = count + totalDamage.Value
        end
    end
    calRun.potSum = calRun.potSum or 0
    if calRun.lastDealtT then
        local now2 = now - calRun.lastDealtT
        local count2 = 0
        for _, unit in ipairs(Match.mine) do
            local stats = unit._stats
            local idValue = stats.id.Value
            if not Units.isFarm(idValue) and stats:FindFirstChild("target") and stats.target.Value ~= nil then
                local ok, res = pcall(Match.liveDps, unit, idValue)
                if ok and res then
                    count2 = count2 + res * now2
                    -- Per unit, for learning: what it could deal while it stood and had a target, at the
                    -- stats it had then (without the learned correction, which is what is being learned).
                    calRun.potBy = calRun.potBy or {
                    }
                    local own = res / math.max(0.5, Units.nudge(idValue))
                    local mark = Units.passive(idValue).mark
                    if mark then
                        own = own + mark.dot * stats.damage.Value
                    end
                    calRun.potBy [idValue] = (calRun.potBy [idValue] or 0) + own * now2
                end
            end
        end
        calRun.potWin = (calRun.potWin or 0) + count2
        if now - (calRun.winT or now) >= 5 then
            local count2 = count - (calRun.winDealt or count)
            if calRun.potWin > 0 and count2 >= 0 then
                calRun.dealtSum = (calRun.dealtSum or 0) + count2
                calRun.potSum = calRun.potSum + calRun.potWin
            end
            calRun.winT, calRun.winDealt, calRun.potWin = now, count, 0
        end
    end
    if not calRun.winT then
        calRun.winT, calRun.winDealt = now, count
    end
    calRun.lastDealtT = now
    if wave ~= calRun.dpsW and wave > 0 then
        calRun.dpsAt [tostring(wave)] = Match.teamDps or 0
        calRun.dpsW = wave
    end
    local value = math.min(1, now - (calRun.densT or now))
    calRun.densT = now
    for _, enemy in ipairs(Match.enemies) do
        local bins = math.min(Simulator.BINS, math.floor(enemy.prog * Simulator.BINS) + 1)
        calRun.dens [bins] = (calRun.dens [bins] or 0) + value
    end
    local base = workspace._BASES.player:FindFirstChild("base")
    local fakeUnit = base and base:FindFirstChild("fake_unit")
    local humanoid = fakeUnit and fakeUnit:FindFirstChildOfClass("Humanoid")
    if humanoid then
        calRun.baseHp = math.max(calRun.baseHp or 0, humanoid.MaxHealth)
        local count = 0
        for _, enemy in ipairs(Match.enemies) do
            if enemy.prog >= 0.97 then
                local humanoid = enemy.m:FindFirstChildOfClass("Humanoid")
                count = count + (humanoid and humanoid.MaxHealth or enemy.hp)
            end
        end
        if calRun.lastBase and humanoid.Health < calRun.lastBase and count > 0 and calRun.lastBaseT then
            table.insert(calRun.baseRel, (calRun.lastBase - humanoid.Health) / math.max(0.1, now - calRun.lastBaseT) / count)
        end
        calRun.lastBase, calRun.lastBaseT = humanoid.Health, now
    end
end

function Match.recordMap()
    local mapKey = Match.mapKey()
    local map = Brain.maps [mapKey]
    if map and map.v == 1 and map.laneV and (map.densN or 0) == (map.binsDensN or 0) then
        return
    end
    if map and map.v == 1 and map.laneV and (map.densN or 0) > 5 and (map.binsDensN or 0) >= 5 then
        return
    end
    local info = {
        override_hitbox_radius = 1.75
    }
    local info2 = {
        hill_unit = true,
        override_hitbox_radius = 1.75
    }
    local list, flag = {
    }, false
    for i, cand in ipairs(Match.cands) do
        local valid = Match.valid(cand, info)
        if valid then
            table.insert(list, valid)
        end
        if not flag and Match.valid(cand, info2) then
            flag = true
        end
        if i % 30 == 0 then
            task.wait()
        end
    end
    local list2, list3 = {
    }, {
    }
    local laneList = Simulator.laneList(Match.samples)
    for i = 5, 60, 5 do
        local value, value2
        for _, item in ipairs(list) do
            local cover = Match.cover(item, i, true)
            if not value2 or cover > value2 then
                value, value2 = item, cover
            end
        end
        if value then
            local list, list4 = {
            }, {
            }
            for i = 1, Simulator.BINS do
                list [i] = "0"
            end
            for _, value in ipairs(laneList or {
            }) do
                list4 [value] = {
                }
                for i = 1, Simulator.BINS do
                    list4 [value] [i] = "0"
                end
            end
            local flat = Utils.flat(value)
            for _, sample in ipairs(Match.samples) do
                if ((sample.flat or Utils.flat(sample.pos)) - flat).Magnitude <= i then
                    local bins = math.min(Simulator.BINS, math.floor(sample.prog * Simulator.BINS) + 1)
                    list [bins] = "1"
                    if list4 [tostring(sample.lane)] then
                        list4 [tostring(sample.lane)] [bins] = "1"
                    end
                end
            end
            list2 [tostring(i)] = table.concat(list)
            if laneList then
                list3 [tostring(i)] = {
                }
                for itemKey, item in pairs(list4) do
                    list3 [tostring(i)] [itemKey] = table.concat(item)
                end
            end
        end
        task.wait()
    end
    local map = Brain.maps [mapKey] or {
    }
    Brain.maps [mapKey] = {
        v = 1,
        laneV = 1,
        bins = list2,
        binsL = laneList and list3 or nil,
        lanes = laneList,
        hill = flag,
        spots = # list,
        dens = map.dens,
        densN = map.densN,
        binsDensN = map.densN or 0,
        lay = map.lay,
        walk = map.walk,
        walkN = map.walkN
    }
    Simulator._masks = {
    }
    App.log(1, "SIM", string.format("mapped %s: %d free spots%s", mapKey, # list, flag and ", hill spots too" or ", no hill spots"))
    App.saveSoon()
end
Match.helperDealt, Match.helperAt, Match.ownDealt = {
}, 0, {
}

function Match.sampleHelpers(arg1)
    if not arg1 and Utils.now() - Match.helperAt < 3 then
        return
    end
    Match.helperAt = Utils.now()
    local units = workspace:FindFirstChild("_UNITS")
    local list = {
    }
    for _, unit in ipairs(Match.mine or {
    }) do
        list [unit] = true
        local stats = unit:FindFirstChild("_stats")
        local totalDamage = stats and stats:FindFirstChild("total_damage")
        if totalDamage and stats:FindFirstChild("id") then
            local value = Match.ownDealt [unit] or {
                id = stats.id.Value,
                v = 0,
                lvl = 0,
                since = Utils.now()
            }
            value.v = math.max(value.v, totalDamage.Value)
            value.lvl = math.max(value.lvl, stats:FindFirstChild("upgrade") and tonumber(stats.upgrade.Value) or 0)
            Match.ownDealt [unit] = value
        end
    end
    for _, child in ipairs(units and units:GetChildren() or {
    }) do
        local stats = child:FindFirstChild("_stats")
        local parentUnit = stats and stats:FindFirstChild("parent_unit")
        local totalDamage = stats and stats:FindFirstChild("total_damage")
        if parentUnit and totalDamage and parentUnit.Value ~= nil and list [parentUnit.Value] then
            local stats2 = parentUnit.Value:FindFirstChild("_stats")
            local value = Match.helperDealt [child] or {
                id = stats.id.Value,
                owner = stats2 and stats2:FindFirstChild("id") and stats2.id.Value or nil,
                parent = parentUnit.Value,
                v = 0
            }
            value.v = math.max(value.v, totalDamage.Value)
            Match.helperDealt [child] = value
        end
    end
end

function Match.watchHelpers()
    local units = workspace:FindFirstChild("_UNITS")
    if not units then
        return
    end
    table.insert(App.conns, units.ChildAdded:Connect(function(inst)
        task.spawn(function()
            local stats = inst:WaitForChild("_stats", 3)
            task.wait(0.1)
            local parentUnit = stats and stats:FindFirstChild("parent_unit")
            local totalDamage = stats and stats:FindFirstChild("total_damage")
            if not (totalDamage and parentUnit and parentUnit.Value) then
                return
            end
            local stats2 = parentUnit.Value:FindFirstChild("_stats")
            local idValue = stats2 and stats2:FindFirstChild("id") and stats2.id.Value or nil
            if not idValue then
                return
            end
            local flag = false
            for _, unit in ipairs(Match.mine or {
            }) do
                if unit == parentUnit.Value then
                    flag = true
                    break
                end
            end
            if not flag then
                return
            end
            local function helper()
                local value = Match.helperDealt [inst] or {
                    id = stats.id.Value,
                    owner = idValue,
                    parent = parentUnit.Value,
                    v = 0
                }
                value.v = math.max(value.v, totalDamage.Value)
                Match.helperDealt [inst] = value
            end
            helper()
            table.insert(App.conns, totalDamage.Changed:Connect(helper))
        end)
    end))
end

function Match.damageShares()
    pcall(Match.sampleHelpers, true)
    local list, count = {
    }, 0
    local function helper(arg1, arg2)
        list [arg1] = (list [arg1] or 0) + arg2
        count = count + arg2
    end
    for _, value in pairs(Match.ownDealt) do
        if not Units.isFarm(value.id) then
            helper(value.id, value.v)
        end
    end
    local count2 = 0
    for _, value in pairs(Match.helperDealt) do
        helper(value.owner or "helpers", value.v)
        count2 = count2 + 1
    end
    if count <= 0 then
        return nil
    end
    for itemKey, item in pairs(list) do
        list [itemKey] = item / count
    end
    return list, count, count2
end

function Match.summonSplit()
    local list, list2 = {
    }, {
    }
    for _, value in pairs(Match.ownDealt) do
        list [value.id] = (list [value.id] or 0) + (tonumber(value.v) or 0)
    end
    for _, value in pairs(Match.helperDealt) do
        if value.owner then
            list2 [value.owner] = (list2 [value.owner] or 0) + (tonumber(value.v) or 0)
        end
    end
    local list3 = {
    }
    for itemKey, item in pairs(list2) do
        local item2 = item + (list [itemKey] or 0)
        if item2 > 0 then
            list3 [itemKey] = {
                share = item / item2,
                total = item2
            }
        end
    end
    return list3
end

-- 2.26: the highest level each unit reached on the field this match (and how many copies stood at once).
Match.levelSeen = {}

function Match.noteLevels()
    local count, low = {}, {}
    for _, unit in ipairs(Match.mine or {}) do
        local stats = unit:FindFirstChild("_stats")
        local idValue = stats and stats:FindFirstChild("id")
        local id = idValue and idValue.Value
        if id then
            local upgrade = stats:FindFirstChild("upgrade")
            local level = upgrade and tonumber(upgrade.Value) or 0
            local seen = Match.levelSeen [id] or { top = 0, low = level, n = 0 }
            seen.top = math.max(seen.top, level)
            Match.levelSeen [id] = seen
            count [id] = (count [id] or 0) + 1
            low [id] = math.min(low [id] or level, level)
        end
    end
    for id, n in pairs(count) do
        local seen = Match.levelSeen [id]
        if n >= seen.n then
            seen.n, seen.low = n, low [id]
        end
    end
end

function Match.levelsLine()
    local list = {}
    for id, seen in pairs(Match.levelSeen) do
        local rows = Units.rows(id)
        local text = string.format("%s %d/%s", tostring(Units.name(id) or id), seen.top, rows and tostring(rows.max) or "?")
        if seen.n > 1 then
            text = text .. string.format(" (%d copies, lowest %d)", seen.n, seen.low)
        end
        table.insert(list, { text = text, top = id == Units.FUSION.hero and 1e9 or seen.top })
    end
    if # list == 0 then
        return nil
    end
    table.sort(list, function(a, b) return a.top > b.top end)
    local out = {}
    for _, item in ipairs(list) do
        table.insert(out, item.text)
    end
    return "highest levels on the field: " .. table.concat(out, " · ")
end

function Match.damageLine()
    local damageShares, damageShares2, damageShares3 = Match.damageShares()
    if not damageShares then
        return nil
    end
    local list = {
    }
    for damageShareKey, damageShare in pairs(damageShares) do
        table.insert(list, {
            name = damageShareKey == "helpers" and "helpers" or Units.name(damageShareKey),
            v = damageShare
        })
    end
    table.sort(list, function(arg1, arg2)
        return arg1.v > arg2.v
    end)
    local list2 = {
    }
    for _, item in ipairs(list) do
        table.insert(list2, string.format("%s %d%%", item.name, math.floor(item.v * 100 + 0.5)))
    end
    local ok, res = pcall(Match.summonSplit)
    local list = {
    }
    for key, value in pairs(ok and res or {
    }) do
        if value.share >= 0.05 and value.total >= 0.01 * damageShares2 then
            table.insert(list, string.format("%s %d%%", Units.name(key), math.floor(value.share * 100 + 0.5)))
        end
    end
    table.sort(list)
    return string.format("%s dealt: %s%s%s", Utils.fmt(damageShares2), table.concat(list2, " · "), damageShares3 > 0 and string.format(" (%d helpers)", damageShares3) or "", # list > 0 and (" · from summons: " .. table.concat(list, ", ")) or "")
end

function Match.calMerge(arg1)
    local calRun = Match.calRun
    if not (calRun and Match.key) then
        return
    end
    local cal = Simulator.cal(Simulator.calKey(Match.key, Match.ld, Match.challenge, Match.rotation))
    cal.n = (tonumber(cal.n) or 0) + 1
    -- Each field counts its own observations (2.21): a match can say a lot about enemy speed and nothing
    -- about yen, and a field seen for the first time after many matches should not get a tiny weight.
    -- Fields saved before 2.21 start from the old shared count.
    cal.nf = type(cal.nf) == "table" and cal.nf or {
    }
    -- Per-wave tables (skip votes, timers) keep the shared step.
    local value = math.max(0.2, 1 / cal.n)
    local function helper(arg1)
        if # arg1 == 0 then
            return nil
        end
        table.sort(arg1)
        return arg1 [math.ceil(# arg1 / 2)]
    end
    local function helper2(arg1, arg2)
        if arg2 then
            local seen = (tonumber(cal.nf [arg1]) or (cal [arg1] ~= nil and (cal.n - 1) or 0)) + 1
            cal.nf [arg1] = seen
            local step = math.max(0.2, 1 / seen)
            cal [arg1] = cal [arg1] and (cal [arg1] + (arg2 - cal [arg1]) * step) or arg2
        end
    end
    Match.hpRun = helper(calRun.hp)
    helper2("hpCal", Match.hpRun)
    helper2("walk", helper(calRun.walk))
    do
        local value, mapKey = helper(calRun.walk), Match.mapKey()
        if value then
            local mapWalk = Simulator.mapWalk(mapKey)
            Brain.maps [mapKey] = Brain.maps [mapKey] or {
            }
            local map = Brain.maps [mapKey]
            map.walkN = (tonumber(map.walkN) or 0) + 1
            map.walk = mapWalk and (mapWalk + (value - mapWalk) * math.max(0.2, 1 / (map.walkN + 1))) or value
            Simulator._walk [mapKey] = map.walk
        end
    end
    if (calRun.potSum or 0) > 0 and (calRun.dealtSum or 0) > 0 then
        helper2("eff", Utils.clamp(calRun.dealtSum / calRun.potSum, 0.1, 2))
    end
    local mapKey = Match.mapKey()
    local count = 0
    for _, den in pairs(calRun.dens) do
        count = math.max(count, den)
    end
    if count > 0 then
        Brain.maps [mapKey] = Brain.maps [mapKey] or {
        }
        local dens = type(Brain.maps [mapKey].dens) == "table" and Brain.maps [mapKey].dens or {
        }
        local densN = (tonumber(Brain.maps [mapKey].densN) or 0) + 1
        for i = 1, Simulator.BINS do
            local ratio = (calRun.dens [i] or 0) / count
            local den = tonumber(dens [i])
            dens [i] = den and (den + (ratio - den) * math.max(0.2, 1 / densN)) or ratio
        end
        Brain.maps [mapKey].dens, Brain.maps [mapKey].densN = dens, densN
    end
    if # calRun.pay >= 2 then
        helper2("yenCal", Utils.clamp(helper(calRun.pay), 0.5, 2))
    end
    if not Match.joinedMid then
        helper2("waveSec", helper(calRun.waveSec))
        helper2("baseRel", helper(calRun.baseRel))
        cal.baseDps = nil
        helper2("skipDelay", helper(calRun.skip))
        local list = {
        }
        for i = 2, Match.wave() - 1 do
            local value, value2 = tonumber(calRun.spawn [tostring(i)]), tonumber(calRun.spawnLast [tostring(i)])
            if value and value2 and value >= 3 then
                table.insert(list, value2 / (value - 1))
            end
        end
        if # list >= 3 then
            helper2("spawnGap", Utils.clamp(helper(list), 0.05, 5))
        end
        local voteAt = tonumber(cal.voteAt) or (Match.info and Match.info.voteAt) or Simulator.PRIOR.voteAt
        local list, list2 = {
        }, {
        }
        for _, vote in ipairs(calRun.votes) do
            local n = tonumber(vote.n) or 0
            if n > 0 and Simulator.PRIOR.voteBase + Simulator.PRIOR.votePer * n >= voteAt + 3 then
                table.insert(list, vote.t)
            elseif n > 0 and vote.t < voteAt - 2 then
                table.insert(list2, (vote.t - Simulator.PRIOR.voteBase) / n)
            end
        end
        helper2("voteAt", helper(list))
        helper2("votePer", list2 [1] and Utils.clamp(helper(list2), 0.2, 6) or nil)
        cal.voteWave = type(cal.voteWave) == "table" and cal.voteWave or {
        }
        for _, vote in ipairs(calRun.votes) do
            if vote.w and vote.t then
                local w, value2 = tostring(vote.w), tonumber(cal.voteWave [tostring(vote.w)])
                cal.voteWave [w] = value2 and (value2 + (vote.t - value2) * value) or vote.t
            end
        end
        cal.timerAt = type(cal.timerAt) == "table" and cal.timerAt or {
        }
        for key, value2 in pairs(calRun.timer) do
            if value2 > 5 then
                local value3 = tonumber(cal.timerAt [key])
                cal.timerAt [key] = value3 and (value3 + (value2 + 1 - value3) * value) or (value2 + 1)
            end
        end
        if calRun.start then
            cal.start = calRun.start
        end
        if calRun.baseHp then
            cal.baseHp = calRun.baseHp
        end
        cal.yen = nil
        if Match.info then
            local count, count2 = 0, 0
            for i = 2, Match.wave() - 1 do
                local value = tonumber(calRun.spawn [tostring(i)])
                if value then
                    count = count + value
                    count2 = count2 + # (Simulator.wave(Match.info, i, true))
                end
            end
            if count > 0 and count2 > 0 then
                helper2("countCal", Utils.clamp(count / count2, 0.25, 6))
            end
        end
        local list = {
        }
        for _, member in ipairs(Match.team or {
        }) do
            table.insert(list, member.u)
        end
        local sig = Simulator.sig(list)
        local text = tostring(Match.ld.id or "?") .. (Hunt.is(Match.ld.id) and ("@" .. tostring(Match.ld.map)) or "")
        local teamProfile = Match.teamProfile or Simulator.profileSig(list)
        if cal.teamProfile ~= teamProfile or cal.aliveLvl ~= text then
            cal.alive = {
            }
            cal.teamSig = sig
            cal.teamProfile = teamProfile
            cal.aliveLvl = text
            cal.aliveN = 0
            cal.lastWave = 0
            cal.dpsAt = {
            }
        end
        cal.aliveN = (tonumber(cal.aliveN) or 0) + 1
        local ratio = 1 / cal.aliveN
        cal.alive = type(cal.alive) == "table" and cal.alive or {
        }
        for key, value in pairs(calRun.alive) do
            local value2 = tonumber(cal.alive [key])
            cal.alive [key] = value2 and (value2 + (value - value2) * ratio) or value
        end
        cal.lastWave = math.max(tonumber(cal.lastWave) or 0, Match.wave())
        cal.dpsAt = type(cal.dpsAt) == "table" and cal.dpsAt or {
        }
        for key, value in pairs(calRun.dpsAt) do
            local value2 = tonumber(cal.dpsAt [key])
            cal.dpsAt [key] = value2 and (value2 + (value - value2) * ratio) or value
        end
    end
    cal.ld = Simulator.slim(Match.ld)
    cal.ch = Match.challenge or Match.ld._challenge
    Brain.simRes[Match.key], Brain.simTeam[Match.key] = nil, nil
    Simulator._masks = {
    }
    if Match.pred and Match.infinite then
        App.log(1, "SIM", string.format("predicted the base falls at wave %d%s · real wave %d", Match.pred.wave, Match.pred.won and "+" or "", Match.wave()))
        cal.lastPred = {
            won = Match.pred.won,
            wave = Match.pred.wave,
            realWon = arg1,
            realWave = Match.wave(),
            at = os.time()
        }
    elseif Match.pred then
        App.log(1, "SIM", string.format("predicted %s at wave %d · real %s at wave %d", Match.pred.won and "a win" or "a loss", Match.pred.wave, arg1 and "a win" or "a loss", Match.wave()))
        cal.lastPred = {
            won = Match.pred.won,
            wave = Match.pred.wave,
            realWon = arg1,
            realWave = Match.wave(),
            at = os.time()
        }
    end
end

function Match.holdGain(member, row)
    if Match.random or not row or not Match.info then
        return 0
    end
    local attackInfo = Units.attackInfo(row.atk, row.range)
    if (attackInfo.stun or 0) <= 0 and (attackInfo.slowTime or 0) <= 0 then
        return 0
    end
    local count = 0
    for _, unit in ipairs(Match.mine or {
    }) do
        local stats = unit._stats
        local rows = Units.rows(stats.id.Value)
        local row = rows and rows [math.min(stats.upgrade.Value, rows.max)]
        local attackInfo = row and row.atk and Units.attackInfo(row.atk, row.range)
        if attackInfo and ((attackInfo.stun or 0) > 0 or (attackInfo.slowTime or 0) > 0) then
            count = count + 1
        end
    end
    local mask, count2 = Simulator.mask(Match.info.map, Units.range(member.u, 0) * (Match.info.rangeScale or 1)), 0
    for i = 1, Simulator.BINS do
        if mask [i] then
            count2 = count2 + 1
        end
    end
    local covEnd = Match.depth and Match.depth.units > 0 and Match.depth.covEnd or 1
    local num = (Units.airFrom(member.id) == 0) and 1 or (1 - (1 - Core.FLY_GROUND) * math.min(1, Match.info.flyChance or 0))
    return Economy.holdGain(attackInfo, Match.teamDps or 0, count2 / (math.max(0.1, covEnd) * Simulator.BINS) * num, count)
end

function Match.buffGain(member)
    local allyBuff = Units.allyBuff(member.id)
    if not allyBuff or not Config.actives then
        return 0
    end
    if allyBuff.chain and Units.chainOn() then
        local mates, squadCopies, relayCopies, rotationRunning = Match.squadAndRelays(allyBuff)
        local need = allyBuff.squad or Units.BUFF_COPIES
        if # mates >= need then
            if not rotationRunning or # mates >= Units.BUFF_RELAY_MAX or not (squadCopies and # squadCopies >= need) then
                return 0
            end
            -- The relay spot search walks every candidate spot: reuse its answer for 3 s while the field stays the same.
            local cacheKey = string.format("%s:%d:%d", tostring(allyBuff.attack), # mates, # (Match.mine or {
            }))
            local cached = Match.relayGainCache and Match.relayGainCache [cacheKey]
            local unbuffedDps
            if cached and Utils.now() - cached.at < 3 then
                unbuffedDps = cached.dps
            else
                local _, _, found = Match.bestRelaySpot(member, allyBuff, squadCopies, relayCopies)
                unbuffedDps = found or 0
                Match.relayGainCache = Match.relayGainCache or {
                }
                Match.relayGainCache [cacheKey] = {
                    at = Utils.now(),
                    dps = unbuffedDps
                }
            end
            if not unbuffedDps or unbuffedDps <= 0 then
                return 0
            end
            local rate = 0
            for _, v in pairs(allyBuff.types or {
            }) do
                rate = math.max(rate, tonumber(v) or 0)
            end
            local relayAvg = Units.buffAverage(allyBuff, need, rate, true) * Match.relayUptime(allyBuff)
            return unbuffedDps * relayAvg
        end
    end
    local buffShort = Match.buffShort(allyBuff)
    local value = Brain.stack [allyBuff.attack]
    local cap = value and value.stacks and (value.cap or 1) or nil
    local ok, res = pcall(Units.range, member.u, 0)
    res = (ok and tonumber(res) or 15) * ((Match.info and tonumber(Match.info.rangeScale)) or 1)
    local allowChain = Units.chainOn()
    local cd = cap and Config.community and tonumber(allyBuff.time) and tonumber(allyBuff.cd)
    local function helper(arg1, arg2)
        local ratio = math.floor(arg1 * allyBuff.time / math.max(1, allyBuff.cd) + 0.001)
        return math.min(cap, (1 + arg2) ^ ratio - 1)
    end
    local count = 0
    for _, value in ipairs(buffShort) do
        local count2 = 0
        for _, value2 in ipairs(buffShort) do
            if (value2.pos - value.pos).Magnitude <= res then
                local value = allyBuff.types [value2.base]
                local value3 = value * allyBuff.uptime
                if allyBuff.chain then
                    value3 = Units.buffAverage(allyBuff, value2.n + 1, value, allowChain) - Units.buffAverage(allyBuff, value2.n, value, allowChain)
                elseif cd then
                    local value4, n = helper(value2.n, value), value2.n + 1
                    while n < value2.n + 6 and helper(n, value) <= value4 + 0.001 do
                        n = n + 1
                    end
                    value3 = math.max(0, (helper(n, value) - value4) / (n - value2.n))
                elseif cap then
                    value3 = math.max(0, math.min(cap, (value2.n + 1) * value * allyBuff.uptime) - math.min(cap, value2.n * value * allyBuff.uptime))
                end
                count2 = count2 + value2.dps * value3
            end
        end
        count = math.max(count, count2)
    end
    return count * (cd and 1 or 0.7)
end

-- ===== Relay copies: how much of the time their buff is really up (2.24) =====
-- A relay copy casts only when the squad's buff has reached it and an attacker in its range is unbuffed, so
-- it can be up far less than the guess min(1, uptime × 1.5) its buy counted on. The guess (or what past
-- matches saw, Brain.relayUp) counts as one cooldown of relay time; the casts relays made here, each the
-- buff's length, over their time on the field, outweigh it as they stand longer.
function Match.relayGuess(allyBuff)
    local saved = Brain.relayUp and Brain.relayUp [allyBuff.attack]
    if saved and tonumber(saved.up) then
        return Utils.clamp(tonumber(saved.up), 0, 1)
    end
    return math.min(1, (tonumber(allyBuff.uptime) or 0) * 1.5)
end

function Match.relayDur(allyBuff)
    local learned = Brain.stack and Brain.stack [allyBuff.attack]
    return learned and tonumber(learned.dur) or tonumber(allyBuff.time) or 30
end

function Match.relayUptime(allyBuff)
    local guess = Match.relayGuess(allyBuff)
    local state = Match.buffState and Match.buffState [allyBuff.attack]
    local sec = state and tonumber(state.relaySec) or 0
    if sec <= 0 then
        return guess
    end
    local cd = math.max(1, tonumber(allyBuff.cd) or 60)
    return Utils.clamp(((state.relayDone or 0) * Match.relayDur(allyBuff) + guess * cd) / (sec + cd), 0, 1)
end

function Match.buffWanted(member)
    return Match.buffGain(member) > 0.01 * (Match.teamDps or 0)
end

-- What a buffer's next upgrade adds through its wider circle: the attackers it starts to reach.
function Match.buffWider(member, copy, row, nextRow)
    local allyBuff = Units.allyBuff(member.id)
    if not allyBuff or not Config.actives or not (row and nextRow) or (nextRow.range or 0) <= (row.range or 0) then
        return 0
    end
    local stats = copy._stats
    local reach = stats.range.Value
    local wider = reach * nextRow.range / math.max(1, row.range)
    local origin = Utils.flat(copy:GetPivot().Position)
    local size = 0
    for _, fieldBuffer in ipairs(Match.fieldBuffers()) do
        if fieldBuffer.b.attack == allyBuff.attack then
            size = size + 1
        end
    end
    local gain = 0
    for _, tower in ipairs(Match.mine) do
        local id = tower._stats.id.Value
        if not Units.isFarm(id) and not Units.allyBuff(id) then
            local _, base = Units.types(id)
            local rate = allyBuff.types [base]
            local distance = (Utils.flat(tower:GetPivot().Position) - origin).Magnitude
            if rate and distance > reach and distance <= wider then
                local ok, dps = pcall(Match.liveDps, tower, id)
                gain = gain + (ok and tonumber(dps) or 0) * Units.buffAverage(allyBuff, math.max(1, size), rate, Units.chainOn()) / math.max(1, size)
            end
        end
    end
    return gain
end
Match.summonHist = {
}

function Match.summonRate()
    local now, count = Utils.now(), 0
    for _, value in pairs(Match.helperDealt) do
        count = count + (tonumber(value.v) or 0)
    end
    local summonHist = Match.summonHist
    if not summonHist [# summonHist] or now - summonHist [# summonHist].t >= 1 then
        table.insert(summonHist, {
            t = now,
            v = count
        })
    end
    while # summonHist > 2 and now - summonHist [1].t > 30 do
        table.remove(summonHist, 1)
    end
    local value = summonHist [1]
    return (value and now - value.t >= 5) and math.max(0, count - value.v) / (now - value.t) or 0
end

function Match.blessGain(member)
    if not Units.BLESS.by [member.id] then
        return 0
    end
    local count, count2 = 0, 0
    for _, unit in ipairs(Match.mine or {
    }) do
        local idValue = unit._stats.id.Value
        if Units.BLESS.by [idValue] then
            count = count + 1
        end
        if Units.SUMMONER [idValue] then
            count2 = count2 + Match.liveDps(unit, idValue)
        end
    end
    if count >= Units.BLESS.cap then
        return 0
    end
    local summonRate = math.max(Match.summonRate(), count2 * (1 + Units.BLESS.dmg * count))
    return summonRate / (1 + Units.BLESS.dmg * count) * Units.BLESS.dmg
end

function Match.liveDps(unit, id)
    local stats = unit:FindFirstChild("_stats")
    if not (stats and stats:FindFirstChild("attack_cooldown") and stats:FindFirstChild("damage") and stats:FindFirstChild("range")) then
        return 0
    end
    local value = math.max(0.1, stats.attack_cooldown.Value)
    local primaryAttackValue = stats:FindFirstChild("primary_attack") and stats.primary_attack.Value or nil
    local count = 0
    for _, value in ipairs({
        "physical_crit_chance",
        "magic_crit_chance"
    }) do
        local findFirstChild = stats:FindFirstChild(value)
        if findFirstChild then
            count = math.max(count, tonumber(findFirstChild.Value) or 0)
        end
    end
    local _, types2 = Units.types(id)
    local text = "_dmg_mul_" .. tostring(types2)
    local value2 = 1 + (tonumber(unit:GetAttribute(text)) or tonumber(stats:GetAttribute(text)) or 0)
    local damageValue = stats.damage.Value * Units.galeDps(id, stats:FindFirstChild("upgrade") and tonumber(stats.upgrade.Value) or 0)
    return (stats.damage.Value / value * Units.aoe(primaryAttackValue, stats.range.Value) * (1 + count * 0.5) + damageValue) * Units.elem(id, Match.mod) * Units.nudge(id) * value2
end
Match.upFail, Match.upFailAt = setmetatable({
}, {
    __mode = "k"
}), setmetatable({
}, {
    __mode = "k"
})
Match.TRIAL_DEAR, Match.TRIAL_KEEP_ALIVE = 30000, 20000

function Match.trialSaving()
    local unit = Core.Units [Match.trialId]
    if (tonumber(unit and unit.cost) or 0) < Match.TRIAL_DEAR or (Match.spent or 0) < Match.TRIAL_KEEP_ALIVE then
        return false
    end
    for _, unit in ipairs(Match.mine or {
    }) do
        if unit._stats.id.Value == Match.trialId then
            return false
        end
    end
    return true
end

-- ===== Rollout from the match as it stands (2.22) =====
-- When the economy is about to buy a farm while enemies already get some way down the road, the
-- simulator plays the next ROLL_WAVES waves from this very moment twice (enemies ×ROLL_HP, for a margin):
-- with the farm, and with the best damage buy instead; later buys follow the usual rule in both. Only
-- when the farm branch loses the base, or keeps clearly less of it (ROLL_MARGIN of its health), does the
-- damage buy go first. At most once a wave; any failure keeps the economy's own choice.
Match.ROLL_WAVES, Match.ROLL_HP, Match.ROLL_MARGIN, Match.ROLL_PRESSURE = 5, 1.1, 0.1, 0.3

function Match.rollState()
    local units = {
    }
    for _, member in ipairs(Match.team or {
    }) do
        table.insert(units, member.u)
    end
    local entries = Simulator.teamFrom(units, Match.info.map)
    local byUuid, byId = {
    }, {
    }
    for _, entry in ipairs(entries) do
        if entry.u and entry.u.uuid then
            byUuid [entry.u.uuid] = entry
        end
        byId [entry.id] = byId [entry.id] or entry
    end
    local towers = {
    }
    for _, model in ipairs(Match.mine or {
    }) do
        local stats = model._stats
        local id = stats.id.Value
        local uuid = stats:FindFirstChild("uuid") and stats.uuid.Value
        local entry = (uuid and byUuid [uuid]) or byId [id]
        if entry and entry.id == id then
            table.insert(towers, {
                e = entry,
                lvl = stats:FindFirstChild("upgrade") and tonumber(stats.upgrade.Value) or 0,
                m = model
            })
        end
    end
    local alive = {
    }
    for _, enemy in ipairs(Match.enemies or {
    }) do
        table.insert(alive, {
            hp = enemy.hp,
            p = enemy.prog,
            fly = enemy.fly
        })
    end
    local calRun = Match.calRun
    local baseFrac = calRun and tonumber(calRun.lastBase) and tonumber(calRun.baseHp) and calRun.baseHp > 0 and Utils.clamp(calRun.lastBase / calRun.baseHp, 0, 1) or 1
    return {
        wave = Match.wave(),
        money = Match.money(),
        baseFrac = baseFrac,
        towers = towers,
        alive = alive
    }, entries, byUuid, byId
end

-- The start of one branch: the state with one buy made (nil when the buy cannot be matched to a unit).
function Match.rollBranch(state, byUuid, byId, option)
    local towers = {
    }
    for i, tower in ipairs(state.towers) do
        towers [i] = {
            e = tower.e,
            lvl = tower.lvl,
            m = tower.m
        }
    end
    local money = state.money
    if option then
        local member = option.e
        local entry = member and ((member.uuid and byUuid [member.uuid]) or (member.u and member.u.uuid and byUuid [member.u.uuid]) or byId [member.id])
        if not entry then
            return nil
        end
        money = money - (tonumber(option.cost) or 0)
        if option.place then
            table.insert(towers, {
                e = entry,
                lvl = 0
            })
        else
            local found = false
            for _, tower in ipairs(towers) do
                if option.m and tower.m == option.m then
                    tower.lvl, found = tower.lvl + 1, true
                    break
                end
            end
            if not found then
                return nil
            end
        end
    end
    return {
        wave = state.wave,
        money = money,
        baseFrac = state.baseFrac,
        towers = towers,
        alive = state.alive
    }
end

-- Is a branch's outcome clearly better than another's? Holding beats falling, then more base left.
function Match.rollBetter(b, a)
    if not b then
        return false
    end
    if not a then
        return true
    end
    if b.won and not a.won then
        return true
    end
    if a.won and not b.won then
        return false
    end
    if not a.won then
        return (b.wave or 0) > (a.wave or 0)
    end
    return (b.baseLeft or 0) >= (a.baseLeft or 0) + Match.ROLL_MARGIN
end

function Match.rollCheck(choice, options, ctx)
    if Config.rollout == false or not (choice and choice.farm and Match.info) then
        return choice
    end
    if Match.random or Match.trialId or Match.trainee or Match.joinedMid or ctx.leak or (ctx.attackers or 0) < 1 then
        return choice
    end
    if (ctx.pressure or 0) < Match.ROLL_PRESSURE then
        return choice
    end
    local wave = Match.wave()
    if wave < 1 or Match.rollW == wave then
        return choice
    end
    local alt
    for _, option in ipairs(options) do
        if not option.farm and option.e and (tonumber(option.cost) or math.huge) <= (ctx.money or 0) and (option.gain or 0) > 0 and not Units.allyBuff(option.e.id) then
            if not alt or option.gain / math.max(1, option.cost) > alt.gain / math.max(1, alt.cost) then
                alt = option
            end
        end
    end
    if not alt then
        return choice
    end
    Match.rollW = wave
    local state, entries, byUuid, byId = Match.rollState()
    local horizon = math.min(tonumber(Match.info.total) or (state.wave + Match.ROLL_WAVES), state.wave + Match.ROLL_WAVES)
    local function run(option)
        local start = Match.rollBranch(state, byUuid, byId, option)
        if not start then
            return nil
        end
        local ok, res = pcall(Simulator.run, Match.info, entries, {
            hpMul = Match.ROLL_HP,
            start = start,
            horizon = horizon
        })
        return ok and res or nil
    end
    local farmRun = run(choice)
    if not farmRun then
        return choice
    end
    if farmRun.won and (farmRun.baseLeft or 0) >= state.baseFrac - 0.02 then
        return choice
    end
    local damageRun = run(alt)
    if not Match.rollBetter(damageRun, farmRun) then
        return choice
    end
    if Match.money() < (tonumber(alt.cost) or math.huge) then
        return choice
    end
    local function said(res)
        return res.won and string.format("holds to wave %d with %d%% of the base", res.wave or horizon, math.floor((res.baseLeft or 0) * 100 + 0.5)) or string.format("falls at wave %d", res.wave or 0)
    end
    local why = string.format("the simulator from this moment (next %d waves, enemies ×%.1f): with %s the base %s, with %s it %s", horizon - state.wave, Match.ROLL_HP, choice.what or "the farm", said(farmRun), alt.what or "more damage", said(damageRun))
    Match.rollSwitched = (Match.rollSwitched or 0) + 1
    App.log(1, "ECON", "damage before the farm: " .. why)
    return alt, why
end

-- Real damage against the estimate (2.25), per copy that has stood at least REAL_UP_SEC: Match.realWeigh shares
-- the copies' estimated total by what each really deals (own hits and its summons). Memo for a second.
Match.REAL_UP_SEC, Match.REAL_UP_MIN, Match.REAL_UP_MAX = 20, 0.35, 3
Match.REAL_ZERO_SEC, Match.REAL_ZERO_UP = 40, 0.6

function Match.realFactors()
    local now = Utils.now()
    local memo = Match.realFactorMemo
    if memo and now - memo.at < 1 then
        return memo.map
    end
    local map, list = {
    }, {
    }
    local ok = pcall(function()
        local since = Match.fieldSince or {
        }
        for _, unit in ipairs(Match.mine or {
        }) do
            local stats = unit._stats
            local id = stats and stats.id and stats.id.Value
            if id and not Units.isFarm(id) and not Units.allyBuff(id) and since [unit] and now - since [unit] >= Match.REAL_UP_SEC then
                local okDps, dps = pcall(Match.liveDps, unit, id)
                if okDps and (tonumber(dps) or 0) > 0 then
                    table.insert(list, {
                        model = unit,
                        dps = dps
                    })
                end
            end
        end
        Match.realWeigh(list)
    end)
    if ok then
        local rated = 0
        for _, item in ipairs(list) do
            if item.live and item.live > 0 then
                map [item.model] = Utils.clamp(item.dps / item.live, Match.REAL_UP_MIN, Match.REAL_UP_MAX)
                rated = rated + 1
            end
        end
        -- Measured nothing for REAL_ZERO_SEC while at least 2 others are measured: a careful 0.6, not the floor
        -- (some damage may not be tracked).
        local since = Match.fieldSince or {
        }
        if rated >= 2 then
            for _, item in ipairs(list) do
                if not map [item.model] and since [item.model] and now - since [item.model] >= Match.REAL_ZERO_SEC then
                    map [item.model] = Match.REAL_ZERO_UP
                end
            end
        end
    end
    Match.realFactorMemo = {
        at = now,
        map = map
    }
    return map
end

-- Yen left idle (2.25): after IDLE_SEC of saving, a useful buy that costs at most IDLE_SHARE of the yen in hand.
Match.IDLE_SEC, Match.IDLE_SHARE = 40, 0.35

function Match.idleBuy(options, money)
    local best
    for _, option in ipairs(options) do
        if not option.farm and not option.relayPlace and (tonumber(option.cost) or 0) > 0 and option.cost <= money * Match.IDLE_SHARE and (tonumber(option.gain) or 0) > 0 then
            if not best or option.gain / option.cost > best.gain / best.cost then
                best = option
            end
        end
    end
    return best
end

function Match.econ()
    if Match.endMovePending() then return end
    if Match.noBuy then
        return App.status("Economy", "keeping the last life: back to the lobby")
    end
    if Match.laneWant and not Match.laneCut then
        local ok, res = pcall(Match.portalLanes)
        if ok and not res then
            return App.status("Economy", string.format("this portal opens %d of the map's lanes and the game picks which: waiting for the first enemies", Match.laneWant))
        end
        if not ok then
            Match.laneWant = nil
            App.log(1, "ERROR", "portal lanes: " .. tostring(res))
        end
    end
    if Match.planning and Match.wave() == 0 and #Match.enemies == 0 and Utils.now() - Match.planning < 6 then
        return App.status("Economy", "the simulator is choosing spots on this map…")
    end
    local money = Match.money()
    local wave = Match.wave()
    local wavesLeft = math.max(0, Match.total - wave)
    local pathBudget
    do
        local waveSec = Match.info and tonumber(Match.info.waveSec) or 0
        if waveSec <= 0 then
            waveSec = 20
        end
        local rate = Match.incomeRate or (((Match.coming and Match.coming [1] and Match.coming [1].reward) or 500) / waveSec)
        pathBudget = money + rate * waveSec * wavesLeft
    end
    local team = Match.team
    local upCostMul = 1
    local spawnCostMul = 1
    pcall(function()
        spawnCostMul = Core.USC.calculate_spawn_cost_multiplier(Core.session())
    end)
    local options = {
    }
    local attackers, farmIncome, wantLeft = 0, 0, 0
    local attackersPlaced = 0
    pcall(Match.noteLevels)
    for _, unit in ipairs(Match.mine) do
        if not Units.isFarm(unit._stats.id.Value) then
            attackersPlaced = attackersPlaced + 1
        end
    end
    local placedByUuid = {
    }
    for _, unit in ipairs(Match.mine) do
        local stats = unit._stats
        local uuid = stats:FindFirstChild("uuid") and stats.uuid.Value
        if uuid then
            placedByUuid [uuid] = placedByUuid [uuid] or {
            }
            table.insert(placedByUuid [uuid], unit)
        end
    end
    -- Damage types an equipped buffer raises: attackers of that type go down a little sooner.
    local buffKinds = {
    }
    if Config.actives then
        for _, member in ipairs(team) do
            local buff = Units.allyBuff(member.id)
            for kind in pairs(buff and buff.types or {
            }) do
                buffKinds [kind] = true
            end
        end
    end
    -- Carrot + Vego: what is still to buy before they can fuse, and what Fused Hero adds over the pair
    -- as it stands. Same rule as the simulator, so the forecast and the match buy alike.
    local fusionPath
    do
        local fusion = Units.FUSION
        local heroRows = Units.rows(fusion.hero)
        local parents = {
        }
        for _, member in ipairs(team) do
            if fusion.attacks [member.id] then
                parents [member.id] = member
            end
        end
        local first, second = parents [fusion.parents [1]], parents [fusion.parents [2]]
        if Config.actives and heroRows and first and second and not Match.random and not Match.trialId and not Match.trainee then
            local heroes, lead = 0, {
            }
            for _, tower in ipairs(Match.mine) do
                local id = tower._stats.id.Value
                if id == fusion.hero then
                    heroes = heroes + 1
                elseif parents [id] then
                    local level = tower._stats.upgrade.Value
                    if not lead [id] or level > lead [id].level then
                        lead [id] = {
                            tower = tower,
                            level = level
                        }
                    end
                end
            end
            if heroes < (tonumber(Units.field(fusion.hero, "spawn_cap")) or 3) then
                local remaining, standing, known = 0, 0, true
                for _, member in ipairs({ first, second }) do
                    local rows = Units.rows(member.id)
                    local at = lead [member.id]
                    if rows and rows.max >= fusion.upgrade then
                        if not at then
                            remaining = remaining + (member.data.cost or 0) * spawnCostMul
                        end
                        for level = (at and at.level or 0) + 1, fusion.upgrade do
                            remaining = remaining + (rows [level].cost or 0)
                        end
                        if at then
                            local ok, dps = pcall(Match.liveDps, at.tower, member.id)
                            standing = standing + (ok and tonumber(dps) or 0)
                        end
                    else
                        known = false
                    end
                end
                if known then
                    local step = math.min(1, heroRows.max)
                    local ok, after = pcall(Units.dps, Units.fusedForm(first.u, second.u), step, Match.mod)
                    local total = remaining + (step > 0 and (heroRows [1].cost or 0) or 0)
                    fusionPath = {
                        lead = lead,
                        left = remaining,
                        heroes = heroes,
                        floor = (ok and (tonumber(after) or 0) > standing and total > 0) and (after - standing) / total or nil
                    }
                end
            end
        end
    end
    -- Real damage (2.25): an upgrade's gain is scaled by what the copy really deals against what its stats say.
    local realFactor = Match.realFactors()
    -- Attackers on the field are counted before the options (2.23), the same for every unit of the team.
    for _, member in ipairs(team) do
        if not Units.isFarm(member.id) and # (placedByUuid [member.uuid] or {
        }) > 0 then
            attackers = attackers + 1
        end
    end
    for _, member in ipairs(team) do
        local studyLastWave = Match.trialId and Brain.trial and Brain.trial.study and wave >= (tonumber(Match.total) or math.huge)
        if Match.trialId and not Match.studyTeam and not studyLastWave and member.id ~= Match.trialId and not Units.isFarm(member.id) and (Match.trialSaving() or (not Units.allyBuff(member.id) and (Match.pressure or 0) < 0.6)) then
            continue
        end
        if Match.trialId == member.id and (tonumber(member.data.cost) or 0) >= Match.TRIAL_DEAR and # (placedByUuid [member.uuid] or {
        }) == 0 and money >= (tonumber(member.data.cost) or 0) * spawnCostMul then
            Match.place(member, "on trial")
            return
        end
        if Match.studyTeam and Match.trialId == member.id and (Match.pressure or 0) < 0.6 then
            local spawnCap = tonumber(Units.field(member.id, "spawn_cap")) or tonumber(member.data.spawn_cap) or 1
            if # (placedByUuid [member.uuid] or {
            }) < spawnCap and money >= (tonumber(member.data.cost) or 0) * spawnCostMul then
                Match.place(member, "on study: down first")
                return
            end
        end
        local rows = Units.rows(member.id)
        local isFarm = Units.isFarm(member.id)
        local copies = placedByUuid [member.uuid] or {
        }
        local trainBonus = Match.trainee == member.uuid and Training.BONUS or 1
        for _, copy in ipairs(copies) do
            if copy._stats.id.Value == member.id and not ((Match.upFail [copy] or 0) >= 3 and Utils.now() - (Match.upFailAt [copy] or 0) < 60) then
                local level = copy._stats.upgrade.Value
                if isFarm then
                    farmIncome = farmIncome + (tonumber(copy._stats.farm_amount and copy._stats.farm_amount.Value) or Units.farm(member.u, level))
                end
                local nextRow = rows [level + 1]
                if nextRow and level < rows.max then
                    pcall(function()
                        upCostMul = Core.USC.calculate_upgrade_cost_multiplier(copy, Core.session())
                    end)
                    local cost = nextRow.cost * upCostMul
                    if isFarm then
                        local farmGain = Units.farm(member.u, level + 1) - Units.farm(member.u, level)
                        table.insert(options, {
                            farm = true,
                            cost = cost,
                            gain = farmGain,
                            m = copy,
                            e = member,
                            what = string.format("upgrade %s to level %d",
                            Units.name(member.id),
                            level + 1)
                        })
                    elseif Match.random and Units.idol(member.id) then
                        table.insert(options, {
                            cost = cost,
                            gain = (Match.teamDps or 0) * Match.idolStep(),
                            m = copy,
                            e = member,
                            idol = true,
                            what = string.format("upgrade %s to level %d",
                            Units.name(member.id),
                            level + 1)
                        })
                    elseif Match.mergeHold(copy) then
                    else
                        local shieldHp, shieldCount = Match.shieldNow()
                        local gain = (shieldHp > 0 and Economy.shieldGain(Match.liveDps(copy, member.id), rows [level], Units.dps(member.u, level + 1, Match.mod), nextRow, shieldHp, shieldCount, 1, Match.info and Match.info.eff) or Economy.upgradeGain(Match.liveDps(copy, member.id), rows, level, cost, upCostMul, Units.dps(member.u, level + 1, Match.mod), Match.reachOf(copy), pathBudget)) * trainBonus * Match.mergeBoost(copy) * Match.airBoost(copy) * Match.reach(copy) * Match.focusGain(copy) * (realFactor [copy] or 1)
                        local bleedGain = Match.bleedGain(member.id, level, false)
                        gain = gain + bleedGain
                        gain = gain + Match.buffWider(member, copy, rows [level], nextRow)
                        local fusionStep = fusionPath and fusionPath.lead [member.id] and fusionPath.lead [member.id].tower == copy and level < Units.FUSION.upgrade
                        if fusionStep and fusionPath.floor then
                            gain = math.max(gain, fusionPath.floor * cost)
                        end
                        table.insert(options, {
                            cost = cost,
                            gain = gain,
                            fusionStep = fusionStep or nil,
                            m = copy,
                            e = member,
                            what = string.format("upgrade %s to level %d%s",
                            Units.name(member.id),
                            level + 1,
                            bleedGain > 0 and " (towards its bleed, which stops regen)" or "")
                        })
                        Match.upRate [copy] = gain / math.max(1, cost)
                        for i = level + 1, rows.max do
                            wantLeft = wantLeft + rows [i].cost * upCostMul
                        end
                    end
                end
            end
        end
        local cap = Units.cap(member.u)
        if Match.random then
            cap = member.hand and 1 or 0
        elseif Units.allyBuff(member.id) and trainBonus == 1 and (not Match.buffWanted(member) or not Units.buffAllowed(member.id)) then
            cap = 0
        elseif Units.allyBuff(member.id) then
            cap = math.min(cap, Units.buffCopies(Units.allyBuff(member.id)))
        end
        if # copies < cap and (Match.noSpot [member.uuid] or 0) < 3 then
            local cost = (member.data.cost or 0) * spawnCostMul
            if isFarm then
                table.insert(options, {
                    farm = true,
                    place = true,
                    cost = cost,
                    gain = Units.farm(member.u,
                    0),
                    e = member,
                    what = "place " .. Units.name(member.id)
                })
            else
                local placeWeight = (# copies == 0 and 2.5 or 1) * trainBonus
                if attackers < 3 then
                    placeWeight = placeWeight * 1.3
                end
                if Match.random then
                    placeWeight = placeWeight * (1 + 2 * Match.carry(member.id)) * (1 - Match.resistOf(member.id)) * Match.airNeed(member.id) * (Match.mergeIds [member.id] and 2 or 1)
                elseif Match.flyMode() then
                    placeWeight = placeWeight * Match.airNeed(member.id)
                end
                if Match.random and attackersPlaced < 8 then
                    placeWeight = placeWeight * (1 + (8 - attackersPlaced) * 0.25)
                end
                local isBuffer = Units.allyBuff(member.id) ~= nil
                local allyBuffInfo = isBuffer and Units.allyBuff(member.id) or nil
                local isRelayPlace = isBuffer and allyBuffInfo and allyBuffInfo.chain and # copies >= (allyBuffInfo.squad or Units.BUFF_COPIES) or nil
                if not isBuffer and not Match.random and buffKinds [select(2, Units.types(member.id))] then
                    placeWeight = placeWeight * Simulator.BUFF_MATCH
                end
                local idolGain = Match.random and Units.idol(member.id) and (Match.teamDps or 0) * Match.idolStep() * 2 or 0
                local dpsGain = Match.shieldOf(Match.random and Match.cardDps(member) or Units.dps(member.u, 0, Match.mod), rows [0]) + Match.shieldWork(member.id, rows [0])
                local blessGain = Match.blessGain(member)
                local buffGain = Match.buffGain(member)
                if isBuffer and # copies == 0 and attackers >= 2 and Match.info and Simulator.isShort(Match.info) then
                    -- Short mode: once the opening defense stands, the first buffer copy goes ahead of more damage.
                    buffGain = buffGain * Simulator.BUFF_EARLY
                end
                local placeGain = dpsGain * placeWeight + buffGain + blessGain + idolGain + Match.holdGain(member, rows [0]) + Match.bleedGain(member.id, 0, true)
                local fusionStep = fusionPath and Units.FUSION.attacks [member.id] and not fusionPath.lead [member.id]
                if fusionStep and fusionPath.floor then
                    placeGain = math.max(placeGain, fusionPath.floor * cost)
                end
                table.insert(options, {
                    place = true,
                    support = isBuffer or nil,
                    relayPlace = isRelayPlace,
                    firstCopy = # copies == 0 or nil,
                    fusionStep = fusionStep or nil,
                    cost = cost,
                    gain = placeGain,
                    e = member,
                    what = "place " .. Units.name(member.id) .. (blessGain > 0 and string.format(" (its blessing: +%s summon damage a second)",
                    Utils.fmt(blessGain)) or ""),
                    train = trainBonus ~= 1 and (# copies == 0 and "first" or "more") or nil
                })
                for i = 0, rows.max do
                    wantLeft = wantLeft + rows [i].cost * (i == 0 and spawnCostMul or upCostMul)
                end
            end
        end
    end
    local fusionRows = Units.rows(Units.FUSION.hero)
    for _, tower in ipairs(Match.mine) do
        local stats = tower._stats
        if fusionRows and stats.id.Value == Units.FUSION.hero then
            attackers = attackers + 1
            local level = stats.upgrade.Value
            local current, nextLevel = fusionRows[level], fusionRows[level + 1]
            if current and nextLevel and not ((Match.upFail[tower] or 0) >= 3 and Utils.now() - (Match.upFailAt[tower] or 0) < 60) then
                local ok, scale = pcall(Core.USC.calculate_upgrade_cost_multiplier, tower, Core.session())
                local cost = nextLevel.cost * (ok and tonumber(scale) or 1)
                local liveDps = Match.liveDps(tower, Units.FUSION.hero)
                local estimate = liveDps * (nextLevel.damage / math.max(1, current.damage)) * (current.cd / math.max(0.1, nextLevel.cd))
                table.insert(options, {
                    cost = cost,
                    gain = Economy.upgradeGain(liveDps, fusionRows, level, cost, cost / math.max(1, nextLevel.cost), estimate, Match.reachOf(tower), pathBudget) * Match.reach(tower) * (realFactor [tower] or 1),
                    m = tower,
                    fusedUp = true,
                    what = string.format("upgrade Fused Hero to level %d", level + 1),
                })
                wantLeft = wantLeft + cost
            end
        end
    end
    if Match.random and FarmHub.every("summonCheck", 1) then
        Match.summonWait = false
        for _, ingameSpell in pairs(Core.session().ingame_spells or {
        }) do
            if ingameSpell == "summon" and Match.summonWorth() then
                Match.summonWait = true
            end
        end
    end
    do
        local covEnd = Match.depth and Match.depth.units > 0 and Match.depth.covEnd or 1
        if Match.summonWait and money < 10000 and (Match.pressure or 0) < math.min(Config.dangerReach, covEnd * 0.9) then
            return App.status("Economy", string.format("saving ¥10k for Astral Summon (a unit from your own team): ¥%s", Utils.fmt(money)))
        end
        local spellWant = Match.random and Match.spellWant
        if spellWant and money < spellWant.cost and ((Match.pressure or 0) < math.min(Config.dangerReach, covEnd * 0.9) or (spellWant.rate or 0) > (Match.bestRate or 0)) then
            return App.status("Economy", string.format("saving ¥%s for %s: ¥%s", Utils.fmt(spellWant.cost), spellWant.why, Utils.fmt(money)))
        end
    end
    if Match.fieldCount() >= (Match.effectiveFieldMax or Match.FIELD_MAX) then
        local upgradesOnly = {
        }
        for _, option in ipairs(options) do
            if not option.place then
                table.insert(upgradesOnly, option)
            end
        end
        options = upgradesOnly
        local covEnd2 = Match.depth and Match.depth.units > 0 and Match.depth.covEnd or 1
        if Match.roomPlan and money < Match.roomPlan.need and (Match.pressure or 0) < math.min(Config.dangerReach, covEnd2 * 0.9) then
            return App.status("Economy", string.format("saving ¥%s to swap %s for %s (the field is full)", Utils.fmt(Match.roomPlan.need), Match.roomPlan.out, Match.roomPlan.name))
        end
    end
    if Match.infinite and Match.trainee then
        local hold, holdWhy = Training.hold(Match.pressure or 0, attackers, Match.holding)
        if hold then
            local traineeOnly = {
            }
            for _, option in ipairs(options) do
                if option.farm or (option.e and option.e.uuid == Match.trainee) then
                    table.insert(traineeOnly, option)
                end
            end
            options = traineeOnly
            if # options == 0 then
                return App.status("Economy", holdWhy .. " · everything for the trainee is bought: saving ¥" .. Utils.fmt(money))
            end
        end
        if hold ~= (Match.holding or false) then
            Match.holding = hold
            if FarmHub.every("holdLog", 60) then
                App.log(1, "TRAIN", hold and holdWhy or "enemies get further now: your other units are bought for again")
            end
        end
    end
    -- With Auto Place or Auto Upgrade off, choose only among what may be bought.
    -- Before, a placement chosen while Auto Place was off blocked every upgrade (and the other way round).
    if not Config.place or not Config.upgrade then
        local allowed = {}
        for _, option in ipairs(options) do
            if (option.place and Config.place) or (not option.place and Config.upgrade) then
                table.insert(allowed, option)
            end
        end
        options = allowed
        if # options == 0 then
            return App.status("Economy", Config.place and "nothing left to place (Auto Upgrade is off)" or Config.upgrade and "nothing left to upgrade (Auto Place is off)" or "Auto Place and Auto Upgrade are off")
        end
    end
    Match.bestRate = 0
    for _, option in ipairs(options) do
        if not option.farm and not option.place and option.cost > 0 then
            Match.bestRate = math.max(Match.bestRate, option.gain / option.cost)
        end
    end
    if Match.bestRate > 0 then
        local filtered = {
        }
        for _, option in ipairs(options) do
            if option.relayPlace and (option.gain / math.max(1, option.cost)) <= Match.bestRate then
            else
                table.insert(filtered, option)
            end
        end
        options = filtered
    end
    if # options == 0 then
        return App.status("Economy", "everything is placed and fully upgraded ✓")
    end
    if Match.trainee then
        Training.boost(options, attackers, Match.pressure or 0, Match.depth and Match.depth.units > 0 and Match.depth.covEnd or nil)
    end
    local futureYen = money + farmIncome * wavesLeft
    for i = wave + 1, Match.total do
        futureYen = futureYen + Match.waveReward(i)
    end
    Match.farmNow, Match.future, Match.wantLeft = farmIncome, futureYen, wantLeft
    if Match.info and Match.comingW ~= wave then
        local coming = {
        }
        local reduction = math.min(0.9, Match.info.red or 0)
        for i = 1, 5 do
            local nextWave = wave + i
            if nextWave > Match.total then
                break
            end
            local ok, enemies, reward = pcall(Simulator.wave, Match.info, nextWave)
            local hp, airHp = 0, 0
            for _, enemy in ipairs(ok and enemies or {
            }) do
                hp = hp + enemy.hp + (enemy.bar or 0)
                if enemy.fly then
                    airHp = airHp + enemy.hp + (enemy.bar or 0)
                end
            end
            table.insert(coming, {
                hp = hp / (1 - reduction),
                airHp = airHp / (1 - reduction),
                reward = (ok and tonumber(reward)) or Match.waveReward(nextWave)
            })
        end
        Match.comingW, Match.coming = wave, coming
        Match.comingAir = false
        for _, item in ipairs(coming) do
            Match.comingAir = Match.comingAir or (item.airHp or 0) > 0
        end
    end
    local eff = Match.info and Match.info.eff or Simulator.PRIOR.eff
    local teamShield = Match.teamShield()
    if Match.focus and (Match.focusInRange or 0) > 0 then
        local upgradesOnly = {
        }
        for _, option in ipairs(options) do
            if not option.place then
                table.insert(upgradesOnly, option)
            end
        end
        if # upgradesOnly > 0 then
            options = upgradesOnly
        end
    end
    local ctx = {
        money = money,
        left = wavesLeft,
        attackers = attackers,
        pressure = Match.pressure or 0,
        piling = Match.piling,
        clearSec = (Match.clearSec or 0) / teamShield,
        enemies = # Match.enemies,
        future = futureYen,
        wantLeft = wantLeft,
        coming = Match.coming,
        airShare = Match.comingAir and not Match.airCalm() and Match.airShare() or nil,
        waveSec = Match.info and Match.info.waveSec,
        eff = eff,
        teamDps = (Match.teamDps or 0) * eff,
        shieldK = teamShield,
        farmNow = farmIncome,
        hpAlive = Match.hpAlive or 0,
        roadSec = 1 / math.max(0.001,
        ((Match.info and Match.info.walk) or Simulator.PRIOR.walk) * ((Match.info and Match.info.speedScale) or 1)),
        leak = Match.depth and Match.depth.leak,
        airLeak = Match.depth and Match.depth.airLeak,
        cover = Match.depth and Match.depth.units > 0 and Match.depth.covEnd or nil,
        incomeRate = Match.incomeRate or (((Match.coming and Match.coming [1] and Match.coming [1].reward) or 500) + farmIncome) / ((Match.info and Match.info.waveSec) or 20),
        farmLeft = Match.infinite and Match.infLeft(Brain.infRuns and Brain.infRuns [Match.key], wave) or nil
    }
    -- The planner chose "save for Fusion" for this lineup: while the defense holds, yen goes only to
    -- one Carrot and one Vego (and farms) until the first Fused Hero stands.
    local savingNote
    local planned = Brain.simTeam [Match.key]
    if fusionPath and fusionPath.heroes == 0 and type(planned) == "table" and type(planned.strategy) == "table" and planned.strategy.fusionSave then
        local focus, focusWhy = Economy.fusionFocus(options, ctx, function(option)
            return option.fusionStep == true
        end, fusionPath.left)
        if focus then
            options = focus
            savingNote = string.format("saving for Fused Hero (¥%s to go, %s)", Utils.fmt(fusionPath.left), focusWhy)
        elseif Match.fusionPause ~= focusWhy then
            App.log(2, "ECON", "Fusion saving paused: " .. tostring(focusWhy))
        end
        Match.fusionPause = not focus and focusWhy or nil
    end
    do
        local nowBorn = Utils.now()
        if AI and AI._unitBornAt then
            for _, unitM in ipairs(Match.mine) do
                if AI._unitBornAt[unitM] == nil then
                    AI._unitBornAt[unitM] = nowBorn
                end
            end
        end
    end
    local choice, why, waitText
    local aiEconUsed = false
    if Config.aiEconomy ~= false and Config.upgradeOrder == "Smart" and not savingNote and not Match.random and not Match.trialId and not Match.trainee and not Match.focus and not Match.endMove and not Match.spellBusy then
        if Config.place and Config.upgrade and AI and AI.maybeSellStarter then
            local okSell, didSell = pcall(AI.maybeSellStarter, ctx, options)
            if okSell and didSell == true then
                return
            end
        end
        if AI and AI.chooseEconOption then
            local okAi, aiChoice, aiScore, aiWhy, aiWait = pcall(AI.chooseEconOption, options, ctx)
            if okAi then
                if aiChoice and (tonumber(aiChoice.cost) or math.huge) <= money then
                    choice = aiChoice
                    why = aiWhy or "EconomyNN"
                    waitText = nil
                    aiEconUsed = true
                    App.log(2, "AI_ECON", string.format("%s (cost=¥%s, score=%.3f) — %s", tostring(aiChoice.what or "?"), Utils.fmt(aiChoice.cost or 0), tonumber(aiScore) or 0, tostring(why)))
                elseif aiChoice == nil and type(aiWait) == "string" and aiWait ~= "" then
                    choice = nil
                    why = nil
                    waitText = aiWait
                    aiEconUsed = true
                    App.log(2, "AI_ECON", string.format("SAVE (score=%.3f) — %s", tonumber(aiScore) or 0, aiWait))
                end
            end
        end
    end
    if not aiEconUsed then
        choice, why, waitText = Economy.ordered(options, ctx)
    end
    if waitText and not savingNote and Config.idleSpend then
        Match.saveSince = Match.saveSince or Utils.now()
        if Utils.now() - Match.saveSince >= Match.IDLE_SEC then
            local idle = Match.idleBuy(options, money)
            if idle then
                choice, why, waitText = idle, string.format("the yen sat %ds while %s", math.floor(Utils.now() - Match.saveSince), waitText), nil
                Match.saveSince = nil
            end
        end
    elseif not waitText then
        Match.saveSince = nil
    end
    if choice and choice.farm and not waitText then
        local ok, rolled, rolledWhy = pcall(Match.rollCheck, choice, options, ctx)
        if ok and rolled and rolled ~= choice then
            choice, why = rolled, rolledWhy
        elseif not ok then
            App.log(2, "ERROR", "rollout: " .. tostring(rolled))
        end
    end
    if savingNote then
        why = why and (savingNote .. " · " .. why) or nil
        waitText = waitText and (savingNote .. " · " .. waitText) or nil
    end
    if waitText then
        return App.status("Economy", waitText)
    end
    if not choice then
        return
    end
    if not Config.upgrade and not choice.place then
        return
    end
    if not Config.place and choice.place then
        return
    end
    App.status("Economy", string.format("%s — %s", choice.what, why))
    if Match.namekTest and choice.place and not choice.farm then
        local support = Units.allyBuff(choice.e.id)
        local rival = 0
        for _, alternative in ipairs(options) do
            if alternative.place and alternative.e and alternative.cost <= money and (Units.allyBuff(alternative.e.id) ~= nil) ~= (support ~= nil) and not alternative.farm then
                rival = math.max(rival, (alternative.gain or 0) / math.max(1, alternative.cost) * 1000)
            end
        end
        if rival > 0 then
            Match.namekTest.comparisons += 1
            if support then Match.namekTest.supportChoices += 1 end
            Match.namekTest.lastChoice = string.format("%s (%.0f vs %.0f gain / ¥1k)", choice.what, choice.gain / math.max(1, choice.cost) * 1000, rival)
        end
    end
    -- 2.33: the match may have ended while an earlier request waited for its answer
    local overOk, over = pcall(function()
        return workspace._DATA.GameFinished.Value
    end)
    if Match.finished or (overOk and over) then
        return
    end
    if choice.place then
        Match.place(choice.e, why)
    else
        local moneyBefore = money
        local ok, res = App.request("upg", "upgrade_unit_ingame", choice.m)
        if ok and res then
            Match.spent = Match.spent + choice.cost
            table.insert(Match.actions, choice.what)
            if choice.idol then
                pcall(Match.idolMeasure)
            end
            App.log(2, "UPGRADE", choice.what .. " for ¥" .. Utils.fmt(choice.cost) .. " — " .. why)
            App.status("Upgrade", choice.what)
        elseif ok then
            App.backoff("upg", 1.5)
            if moneyBefore >= choice.cost then
                App.log(2, "UPGRADE", "refused: " .. choice.what)
                Match.upFail [choice.m] = (Match.upFail [choice.m] or 0) + 1
                Match.upFailAt [choice.m] = Utils.now()
                if Match.upFail [choice.m] == 3 then
                    App.log(1, "UPGRADE", "the game refused " .. choice.what .. " 3 times — buying something else for a minute")
                end
            end
        end
    end
end
Match.readySince, Match.buffedTill = setmetatable({
}, {
    __mode = "k"
}), {
}
Match.buffSeen = {
}

function Match.buffOn(stats, types)
    if (tonumber(stats:GetAttribute("_dmg_buff_" .. tostring(types))) or 0) > 0 then
        return true
    end
    local buffDamageMultiplier = stats:FindFirstChild("buff_damage_multiplier")
    return buffDamageMultiplier ~= nil and (tonumber(buffDamageMultiplier.Value) or 0) > 0
end

function Match.buffRotation(unit, stats, activeAttackValue, attackInfo, time, now)
    if # Match.enemies == 0 then
        return false
    end
    local count = 0
    for _, value in pairs(attackInfo.ally.types or {
    }) do
        count = math.max(count, tonumber(value) or 0)
    end
    if count <= 0 then
        return false
    end
    local cap = tonumber(Brain.stack [activeAttackValue].cap) or ((1 + count) ^ 2 - 1)
    local num = 1
    while num < 6 and (1 + count) ^ num - 1 < cap - 0.02 do
        num = num + 1
    end
    local count2 = 0
    for _, unit in ipairs(Match.mine) do
        local activeAttack = unit._stats:FindFirstChild("active_attack")
        if activeAttack and tostring(activeAttack.Value) == activeAttackValue then
            count2 = count2 + 1
        end
    end
    local allyBuff = Units.allyBuff(stats.id.Value)
    local cd = (allyBuff and tonumber(allyBuff.cd)) or 60
    local value = math.max(1, math.min(num, math.floor(count2 * time / math.max(1, cd) + 0.001)))
    local cap2 = math.min(cap, (1 + count) ^ value - 1)
    local ratio = time / value
    local position = unit:GetPivot().Position
    local count, count3 = 0, 0
    for _, unit2 in ipairs(Match.mine) do
        local stats2 = unit2._stats
        local idValue = stats2.id.Value
        if unit2 ~= unit and not Units.isFarm(idValue) and not Units.allyBuff(idValue) and (Utils.flat(unit2:GetPivot().Position) - Utils.flat(position)).Magnitude <= stats.range.Value then
            local _, types2 = Units.types(idValue)
            if attackInfo.ally.types [types2] then
                count = count + 1
                if (tonumber(stats2:GetAttribute("_dmg_buff_" .. tostring(types2))) or 0) < cap2 - 0.02 then
                    count3 = count3 + 1
                end
            end
        end
    end
    if count == 0 or count3 == 0 then
        return false
    end
    Match.buffNext = Match.buffNext or {
    }
    if now < (Match.buffNext [activeAttackValue] or 0) then
        return false
    end
    return true, string.format("rotation: %d of the %d units it reaches are under +%d%% (%d buffs at once from %d copies, one every %.0f s)", count3, count, math.floor(cap2 * 100 + 0.5), value, count2, ratio), ratio
end

function Match.buffLevel(types)
    local count = 0
    for _, unit in ipairs(Match.mine) do
        local stats = unit._stats
        local idValue = stats.id.Value
        if not Units.isFarm(idValue) and not Units.allyBuff(idValue) then
            local _, types2 = Units.types(idValue)
            local buffDamageMultiplier = stats:FindFirstChild("buff_damage_multiplier")
            if buffDamageMultiplier and not types then
                count = math.max(count, tonumber(buffDamageMultiplier.Value) or 0)
            end
            if not types or types [types2] then
                count = math.max(count, tonumber(stats:GetAttribute("_dmg_buff_" .. tostring(types2))) or 0)
            end
        end
    end
    return count
end
Match.galeIdle = setmetatable({
}, {
    __mode = "k"
})

function Match.isGale(stats, activeAttackValue)
    return stats:FindFirstChild("unit_bar") ~= nil and (activeAttackValue:match(":active$") or activeAttackValue:match(":off$")) ~= nil
end
Match.barSeen = setmetatable({
}, {
    __mode = "k"
})

function Match.learnToggle(arg1, inst, arg3, arg4)
    local idValue = inst.id.Value
    local toggle = Brain.toggles [idValue]
    local upgradeValue = tonumber(inst:FindFirstChild("upgrade") and inst.upgrade.Value) or 0
    local flag = toggle == nil
    if not toggle then
        toggle = {
            from = upgradeValue,
            fill = 0,
            drain = 0,
            nf = 0,
            nd = 0,
            at = os.time()
        }
        Brain.toggles [idValue] = toggle
        Simulator._holds [idValue] = nil
    end
    if upgradeValue < (tonumber(toggle.from) or upgradeValue) then
        toggle.from = upgradeValue
    end
    Match.togglesSeen = Match.togglesSeen or {
    }
    Match.togglesSeen [idValue] = true
    local unitBarValue, flag2 = tonumber(inst.unit_bar.Value) or 0, arg3:match(":off$") ~= nil
    local value = Match.barSeen [arg1]
    if value and value.on == flag2 and arg4 - value.t >= 1.5 then
        if unitBarValue > 0.5 and unitBarValue < 99.5 and value.bar > 0.5 and value.bar < 99.5 then
            local ratio = (unitBarValue - value.bar) / (arg4 - value.t)
            if flag2 and ratio < 0 then
                toggle.drain = (toggle.drain * toggle.nd - ratio) / (toggle.nd + 1)
                toggle.nd = math.min(toggle.nd + 1, 50)
            elseif not flag2 and ratio > 0 then
                toggle.fill = (toggle.fill * toggle.nf + ratio) / (toggle.nf + 1)
                toggle.nf = math.min(toggle.nf + 1, 50)
            end
        end
        Match.barSeen [arg1] = {
            bar = unitBarValue,
            t = arg4,
            on = flag2
        }
    elseif not value or value.on ~= flag2 then
        Match.barSeen [arg1] = {
            bar = unitBarValue,
            t = arg4,
            on = flag2
        }
    end
    if flag then
        App.log(1, "UNITS", string.format("%s has a switch ability with a bar (from upgrade %d): learned, so its copies take turns and it stands where your damage is", Units.name(idValue), upgradeValue))
        App.saveSoon()
    end
end

function Match.gale(unit, stats, activeAttackValue, now)
    local match = activeAttackValue:match("^(.+):")
    local function helper(arg1)
        local flat, rangeValue = Utils.flat(arg1:GetPivot().Position), arg1._stats.range.Value
        local count, list = 0, {
        }
        for _, enemy in ipairs(Match.enemies) do
            if (Utils.flat(enemy.pos) - flat).Magnitude <= rangeValue then
                count = count + 1
                if enemy.boss then
                    table.insert(list, enemy)
                end
            end
        end
        return count, list
    end
    local unitBarValue = tonumber(stats.unit_bar.Value) or 0
    local value, value2 = helper(unit)
    local flag = # value2 > 0
    if activeAttackValue:match(":off$") then
        if value > 0 then
            Match.galeIdle [unit] = nil
            return nil
        end
        Match.galeIdle [unit] = Match.galeIdle [unit] or now
        if now - Match.galeIdle [unit] >= 3 and unitBarValue >= 15 then
            return true, string.format("Gale off: nothing in range, keeping its bar (%d)", math.floor(unitBarValue))
        end
        return nil
    end
    Match.galeIdle [unit] = nil
    if value == 0 or unitBarValue < 20 then
        return nil
    end
    local flat = Utils.flat(unit:GetPivot().Position)
    for _, unit2 in ipairs(Match.mine) do
        local stats2 = unit2._stats
        local activeAttack = stats2:FindFirstChild("active_attack")
        local activeAttackValue = activeAttack and tostring(activeAttack.Value) or ""
        if unit2 ~= unit and stats2:FindFirstChild("unit_bar") and activeAttackValue:match("^(.+):") == match then
            local flat2, unitBarValue2 = Utils.flat(unit2:GetPivot().Position), tonumber(stats2.unit_bar.Value) or 0
            local flag2 = (flat2 - flat).Magnitude <= math.max(stats.range.Value, stats2.range.Value)
            local flag3 = false
            for _, value in ipairs(value2) do
                if (Utils.flat(value.pos) - flat2).Magnitude <= stats2.range.Value then
                    flag3 = true
                end
            end
            if activeAttackValue:match(":off$") then
                if unitBarValue2 > 5 and (flag3 or (flag2 and not flag)) then
                    return nil
                end
            elseif flag2 and unitBarValue2 > unitBarValue + 10 and unitBarValue2 >= 20 and helper(unit2) > 0 then
                return nil
            end
        end
    end
    if not Match.galeSaid then
        Match.galeSaid = true
        App.log(1, "ABILITY", string.format("%s: %s in use, copies take turns so enemies stay slowed and freezing", Units.name(stats.id.Value), match == "rukia_bankai" and "Gale of the Moon" or match))
    end
    return true, string.format("Gale on: %d enemies in range%s, bar %d (copies take turns)", value, flag and ", a boss" or "", math.floor(unitBarValue))
end

function Match.fusionReady(source)
    local fusion = Units.FUSION
    if Match.trialId or Match.trainee or Utils.now() < (Match.fusionRetryAt or 0) then return false end
    local sourceStats = source._stats
    if sourceStats.upgrade.Value < fusion.upgrade then return false end
    local sourceId = sourceStats.id.Value
    local sourceUuid = sourceStats:FindFirstChild("uuid") and sourceStats.uuid.Value
    local bestPartner, heroCount = nil, 0
    for _, unit in ipairs(Match.mine) do
        local stats = unit._stats
        local id = stats.id.Value
        if id == fusion.hero then
            heroCount += 1
        elseif id ~= sourceId and fusion.attacks[id] and stats.upgrade.Value >= fusion.upgrade then
            local attack = stats:FindFirstChild("active_attack")
            if attack and attack.Value == fusion.attacks[id] then
                bestPartner = bestPartner or unit
            end
        end
    end
    if not bestPartner or heroCount >= (tonumber(Units.field(fusion.hero, "spawn_cap")) or 3) then
        return false
    end
    -- Ensure we initiate fusion from the stronger origin parent (better traits/relic/level)
    local partnerUuid = bestPartner._stats:FindFirstChild("uuid") and bestPartner._stats.uuid.Value
    local session = Core.session()
    if session and sourceUuid and partnerUuid then
        local uSelf = session.collection:get_unit_by_uuid(sourceUuid)
        local uPartner = session.collection:get_unit_by_uuid(partnerUuid)
        if uSelf and uPartner and Units.rows(fusion.hero) then
            local fSelf = Units.fusedForm(uSelf, uPartner)
            local fPart = Units.fusedForm(uPartner, uSelf)
            local checkLvl = math.min(5, Units.rows(fusion.hero).max or 0)
            local dpsSelf = Units.dps(fSelf, 0, Match.mod) + Units.dps(fSelf, checkLvl, Match.mod)
            local dpsPart = Units.dps(fPart, 0, Match.mod) + Units.dps(fPart, checkLvl, Match.mod)
            if dpsPart > dpsSelf * 1.01 then
                return false
            end
        end
    end
    return true, bestPartner
end

-- Both abilities (2.25): the first press sometimes doesn't count and no Fused Hero appears. 0.7 s after the
-- stronger parent's press, if no hero was added and the partner still stands with its Fusion ready, its
-- ability is pressed too. A fusion that went through takes the partner off the field, so nothing more is sent.
Match.FUSION_FOLLOW = 0.7

function Match.fusionHeroes()
    local count = 0
    for _, unit in ipairs(Match.mine or {
    }) do
        local stats = unit:FindFirstChild("_stats")
        if stats and stats:FindFirstChild("id") and stats.id.Value == Units.FUSION.hero then
            count = count + 1
        end
    end
    return count
end

function Match.fusionFollow(source, partner, heroesBefore)
    Match.fusionRetryAt = math.max(Match.fusionRetryAt or 0, Utils.now() + Match.FUSION_FOLLOW + 3)
    task.delay(Match.FUSION_FOLLOW, function()
        if not App.alive or not partner or not partner.Parent then
            return
        end
        if Match.fusionHeroes() > heroesBefore then
            return
        end
        local stats = partner:FindFirstChild("_stats")
        local attack = stats and stats:FindFirstChild("active_attack")
        local cooldown, last = stats and stats:FindFirstChild("active_attack_cooldown"), stats and stats:FindFirstChild("last_active_cast")
        if not (attack and cooldown and last and stats:FindFirstChild("id")) or Units.FUSION.attacks [stats.id.Value] ~= attack.Value then
            return
        end
        if cooldown.Value - (tick() - last.Value) > 0 or Match.unitBusy [partner] then
            return
        end
        Match.unitBusy [partner] = true
        local okCall, ok = pcall(App.request, "active", "use_active_attack", partner)
        Match.unitBusy [partner] = nil
        ok = okCall and ok
        App.log(1, "ABILITY", string.format("Fusion: no Fused Hero %.1fs after %s's press, so %s's ability was pressed too (%s)", Match.FUSION_FOLLOW, Units.name(source and source:FindFirstChild("_stats") and source._stats:FindFirstChild("id") and source._stats.id.Value or "?"), Units.name(stats.id.Value), ok and "sent" or "not sent"))
    end)
end

-- [Removed in v2.5: Match.relayBuffChoice was obsolete dead code superceded by Auto Buff Match.autoBuffPick]

-- Plain data in, plain data out, so the stand can run it: which copies reach each other and which
-- attackers stand in range. copies: { position, range }; fighters: { position, base, dps }.
function Match.buffReach(copies, fighters, types, squadSet)
    local out = {
        total = 0,
        covered = 0,
        full = 0,
        relay = 0,
        unbuffed = 0,
        inRange = {
        }
    }
    local squadCount = 0
    if squadSet then
        for _, copy in ipairs(copies) do
            if squadSet [copy.model] or squadSet [copy] then
                squadCount = squadCount + 1
            end
        end
    end
    for _, fighter in ipairs(fighters) do
        if types [fighter.base] then
            local reach, sReach, rReach = 0, 0, 0
            for _, copy in ipairs(copies) do
                local x, z = fighter.position.X - copy.position.X, fighter.position.Z - copy.position.Z
                if x * x + z * z <= copy.range * copy.range then
                    reach = reach + 1
                    if squadSet then
                        if squadSet [copy.model] or squadSet [copy] then
                            sReach = sReach + 1
                        else
                            rReach = rReach + 1
                        end
                    end
                end
            end
            out.total = out.total + fighter.dps
            if reach > 0 then
                out.covered = out.covered + fighter.dps
                table.insert(out.inRange, fighter)
            end
            if squadSet and squadCount > 0 then
                if sReach >= squadCount then
                    out.full = out.full + fighter.dps
                elseif rReach > 0 then
                    out.relay = out.relay + fighter.dps
                else
                    out.unbuffed = out.unbuffed + fighter.dps
                end
                fighter.squadReach = sReach
                fighter.relayReach = rReach
            elseif reach == # copies and reach > 0 then
                out.full = out.full + fighter.dps
            end
            fighter.reach = reach
        end
    end
    if not squadSet then
        out.unbuffed = math.max(0, out.total - out.full)
    end
    for _, copy in ipairs(copies) do
        copy.linked = 0
        for _, other in ipairs(copies) do
            if other ~= copy then
                local x, z = other.position.X - copy.position.X, other.position.Z - copy.position.Z
                local reach = math.min(copy.range, other.range)
                if x * x + z * z <= reach * reach then
                    copy.linked = copy.linked + 1
                end
            end
        end
    end
    return out
end

-- The first set of `need` copies that all stand within each other's range (each pair within the shorter of
-- their two ranges). Also returns the most copies that do reach each other, for the status.
function Match.buffSquad(copies, need)
    local function pair(a, b)
        local x, z = a.position.X - b.position.X, a.position.Z - b.position.Z
        local reach = math.min(a.range, b.range)
        return x * x + z * z <= reach * reach
    end
    local chosen, most, found = {
    }, 0, nil
    local function grow(start)
        most = math.max(most, # chosen)
        if # chosen == need then
            found = table.clone(chosen)
            return
        end
        for index = start, # copies do
            local cand = copies [index]
            local fits = true
            for _, member in ipairs(chosen) do
                if not pair(member, cand) then
                    fits = false
                    break
                end
            end
            if fits then
                table.insert(chosen, cand)
                grow(index + 1)
                table.remove(chosen)
                if found then
                    return
                end
            end
        end
    end
    grow(1)
    return found, most
end

function Match.autoBuffGroups(clock)
    local groups, order, fighters = {
    }, {
    }, {
    }
    for _, tower in ipairs(Match.mine) do
        local stats = tower._stats
        local id = stats.id.Value
        local buff = Units.allyBuff(id)
        local position = Utils.flat(tower:GetPivot().Position)
        if buff and buff.chain then
            local active, last, cooldown = stats:FindFirstChild("active_attack"), stats:FindFirstChild("last_active_cast"), stats:FindFirstChild("active_attack_cooldown")
            if active and tostring(active.Value) == buff.attack and last and cooldown then
                local uuidInst = stats:FindFirstChild("uuid")
                local uuid = uuidInst and tostring(uuidInst.Value) or nil
                local group = groups [buff.attack]
                if not group then
                    group = {
                        attack = buff.attack,
                        buff = buff,
                        id = id,
                        uuid = uuid,
                        copies = {
                        },
                        cd = 0
                    }
                    groups [buff.attack] = group
                    table.insert(order, group)
                elseif not group.uuid and uuid then
                    group.uuid = uuid
                end
                local wait = (tonumber(cooldown.Value) or 0) - (clock - (tonumber(last.Value) or 0))
                table.insert(group.copies, {
                    model = tower,
                    stats = stats,
                    uuid = uuid,
                    position = position,
                    range = stats.range.Value,
                    ready = wait <= 0,
                    wait = math.max(0, wait)
                })
                -- The copy's own cooldown as the game shows it: a SPA curse is already in this number.
                group.cd = math.max(group.cd, tonumber(cooldown.Value) or 0)
            end
        elseif not buff and not Units.isFarm(id) then
            local _, base = Units.types(id)
            local ok, dps = pcall(Match.liveDps, tower, id)
            table.insert(fighters, {
                model = tower,
                stats = stats,
                position = position,
                base = base,
                dps = ok and tonumber(dps) or 0,
                id = id
            })
        end
    end
    Match.realWeigh(fighters)
    Match.buffCdSeen = Match.buffCdSeen or {
    }
    for _, group in ipairs(order) do
        group.fighters = fighters
        group.base, group.kind = 0, nil
        for kind, rate in pairs(group.buff.types) do
            if (tonumber(rate) or 0) > group.base then
                group.base, group.kind = tonumber(rate), kind
            end
        end
        group.reach = Match.buffReach(group.copies, fighters, group.buff.types)
        group.seen = 0
        for _, fighter in ipairs(group.reach.inRange) do
            local attr = tonumber(fighter.stats:GetAttribute("_dmg_buff_" .. tostring(fighter.base)))
            fighter.buff = attr
            group.seen = math.max(group.seen, attr or 0)
        end
        for _, copy in ipairs(group.copies) do
            copy.level = tonumber(copy.stats:GetAttribute("_dmg_buff_" .. tostring(group.kind))) or 0
            group.seen = math.max(group.seen, copy.level)
        end
        if group.cd > 0 then
            local cdKey = group.uuid or group.id
            Match.buffCdSeen [cdKey] = {
                uuid = group.uuid,
                id = group.id,
                cd = group.cd,
                attack = group.attack
            }
        end
    end
    return order
end

function Match.recordBuffCooldowns()
    local seen = Match.buffCdSeen
    if type(seen) ~= "table" or not next(seen) then
        return
    end
    Brain.buffCd = Brain.buffCd or {
    }
    local saved = false
    for _, rec in pairs(seen) do
        local realCd = tonumber(rec and rec.cd)
        if realCd and realCd > 0 and rec.id then
            local estCd, estSrc, dur = Units.buffCooldown(rec.id, nil, rec.uuid)
            local fits = realCd <= 2 * (dur or 30) + 0.5
            local msg = string.format("%s: real match cooldown %ds (estimated %ds from %s) · Lenio needs ≤ %ds → %s",
                Units.name(rec.id), math.ceil(realCd - 1e-6), math.ceil((estCd or realCd) - 1e-6), tostring(estSrc or "data"),
                math.floor(2 * (dur or 30)), fits and "fits ✓" or "SPA curse needed")
            App.log(1, "BUFF", msg)
            if rec.uuid then
                Brain.buffCd [tostring(rec.uuid)] = realCd
                saved = true
            end
        end
    end
    if saved then
        App.saveSoon()
    end
end

-- ===== Buff coverage over the match (2.24) =====
-- While the rotation runs: the share of the damage it can raise that stands under all the squad's copies,
-- under relay copies only, or outside, and who stands outside; and the relay copies' time on the field.
function Match.buffCoverTick(group, state, members, relayCopies, need, now)
    local dt = math.min(5, math.max(0, now - (state.tickAt or now)))
    state.tickAt = now
    if dt <= 0 or # members < need then
        return
    end
    state.relaySec = (state.relaySec or 0) + dt * # (relayCopies or {
    })
    local reach = group.reach
    if not (state.squad and reach and (reach.total or 0) > 0) then
        return
    end
    local cov = state.cover or {
        full = 0,
        relay = 0,
        none = 0,
        sec = 0,
        out = {
        }
    }
    state.cover = cov
    cov.sec = cov.sec + dt
    cov.full = cov.full + dt * (reach.full or 0) / reach.total
    cov.relay = cov.relay + dt * (reach.relay or 0) / reach.total
    cov.none = cov.none + dt * (reach.unbuffed or 0) / reach.total
    for _, f in ipairs(group.fighters or {
    }) do
        if f.id and group.buff.types [f.base] and (f.squadReach or 0) < # members and (f.relayReach or 0) == 0 then
            cov.out [f.id] = (cov.out [f.id] or 0) + dt * (tonumber(f.dps) or 0) / reach.total
        end
    end
end

-- At the match's end: one BUFF line per rotation, and what the relay copies really gave (kept for the next buys).
function Match.buffCoverLog()
    local function pct(x)
        return math.floor(x * 100 + 0.5)
    end
    for attack, state in pairs(Match.buffState or {
    }) do
        local allyBuff = state.id and Units.allyBuff(state.id)
        local name = Units.name(state.id or attack)
        local need = allyBuff and allyBuff.squad or Units.BUFF_COPIES
        local cov = state.cover
        if cov and cov.sec >= 10 then
            local outs = {
            }
            for id, v in pairs(cov.out) do
                if v / cov.sec >= 0.05 then
                    table.insert(outs, {
                        id = id,
                        v = v / cov.sec
                    })
                end
            end
            table.sort(outs, function(a, b)
                if a.v ~= b.v then
                    return a.v > b.v
                end
                return tostring(a.id) < tostring(b.id)
            end)
            local parts = {
            }
            for i = 1, math.min(3, # outs) do
                table.insert(parts, string.format("%s %d%%", Units.name(outs [i].id), pct(outs [i].v)))
            end
            App.log(1, "BUFF", string.format("%s: over %d s of the rotation, %d%% of the damage it can raise stood under all %d copies, %d%% under relay copies only, %d%% outside the buff%s", name, math.floor(cov.sec + 0.5), pct(cov.full / cov.sec), need, pct(cov.relay / cov.sec), pct(cov.none / cov.sec), # parts > 0 and (" · outside: " .. table.concat(parts, ", ")) or ""))
        end
        local sec = tonumber(state.relaySec) or 0
        if allyBuff and sec >= 10 then
            local cd = math.max(1, tonumber(allyBuff.cd) or 60)
            local guess = Match.relayGuess(allyBuff)
            local up = Utils.clamp((state.relayDone or 0) * Match.relayDur(allyBuff) / sec, 0, 1)
            local kept = sec >= 2 * cd
            if kept then
                Brain.relayUp = Brain.relayUp or {
                }
                local saved = Brain.relayUp [attack]
                local old = saved and tonumber(saved.up)
                Brain.relayUp [attack] = {
                    up = old and (old + (up - old) * 0.5) or up,
                    n = (saved and tonumber(saved.n) or 0) + 1,
                    at = os.time()
                }
                App.saveSoon()
            end
            App.log(1, "BUFF", string.format("%s: relay copies cast %d times in %d s on the field, so their buff was up about %d%% of their time (their buy counted on %d%%)%s", name, state.relayDone or 0, math.floor(sec + 0.5), pct(up), pct(guess), kept and "; the next buys use what was seen" or ""))
        end
    end
end

function Match.buffDanger()
    if Match.depth and Match.depth.leak then
        return true
    end
    if (Match.pressure or 0) >= math.min(Config.safeReach, 0.35) or Match.piling then
        return true
    end
    if (Match.total or 0) > 0 and Match.wave() >= Match.total then
        return true
    end
    if (Match.clearSec or 0) > math.max(6, Config.clearSec * 0.5) then
        return true
    end
    for _, enemy in ipairs(Match.enemies) do
        if enemy.boss then
            return true
        end
    end
    return false
end

-- Which buffer casts now. Timing comes from our own casts; the buff value the game shows on the units
-- confirms the level and corrects how long a buff really lasts.
-- ===== Infinite buff: start rule, trace and test =====
-- The infinite buff (Lenio's opening) only works on a full squad: Units.BUFF_SQUAD copies that all stand
-- within each other's range, so each cast lands on a copy that is already buffed. No copy casts before the
-- squad is down; once it runs, it never pauses (between waves too), or the chain would break.
function Match.buffTraceFor(group, need)
    Match.buffTrace = Match.buffTrace or {
    }
    local trace = Match.buffTrace [group.attack]
    if not trace then
        trace = {
            attack = group.attack,
            id = group.id,
            need = need,
            casts = {
            },
            events = {
            },
            total = 0,
            at100 = 0,
            any = 0,
            drops = 0,
            peak = 0
        }
        Match.buffTrace [group.attack] = trace
    end
    return trace
end

function Match.buffTraceEvent(trace, text, now)
    table.insert(trace.events, (trace.startedAt and now and string.format("%ds: ", math.floor(now - trace.startedAt)) or "") .. text)
    while # trace.events > 6 do
        table.remove(trace.events, 1)
    end
end

-- Once the rotation runs: how long the buff is up, how long at 100%, how often it falls to nothing.
function Match.buffTraceSample(trace, level, now)
    if not trace.startedAt then
        return
    end
    local dt = math.min(2, now - (trace.sampledAt or now))
    trace.sampledAt = now
    if dt <= 0 then
        return
    end
    trace.total = trace.total + dt
    -- The share at +100% counts from the first time it gets there: the climb to it is part of the opening.
    if level >= 0.99 and not trace.fullAt then
        trace.fullAt = trace.total
    end
    if trace.fullAt then
        trace.fullTime = (trace.fullTime or 0) + dt
        if level >= 0.99 then
            trace.at100 = trace.at100 + dt
        end
    end
    if level > 0.02 then
        trace.any = trace.any + dt
    end
    if (trace.lastLevel or 0) > 0.02 and level <= 0.02 then
        trace.drops = trace.drops + 1
    end
    trace.lastLevel = level
    trace.peak = math.max(trace.peak, level)
end

-- A rotation ended: keep what it did, so a restart doesn't wipe the result.
function Match.buffTraceArchive(trace, now)
    if not trace.startedAt then
        return
    end
    trace.history = trace.history or {
    }
    table.insert(trace.history, string.format("%ds, highest +%d%%, %s: %s", math.floor(trace.total), math.floor(trace.peak * 100 + 0.5),
        trace.fullAt and string.format("+100%% held %ds of %ds", math.floor(trace.at100), math.floor(trace.fullTime or 0)) or "+100% not reached",
        (Match.buffVerdict(trace):gsub("%..*$", ""))))
    while # trace.history > 3 do
        table.remove(trace.history, 1)
    end
    trace.startedAt = nil
    if Config.buffTest then
        Brain.buffTest = {
            at = os.time(),
            text = Match.buffTestText()
        }
        App.saveSoon()
    end
end

function Match.buffVerdict(trace)
    if not trace.startedAt then
        return "NOT STARTED: " .. tostring(trace.why or "waiting for the copies")
    end
    local cd, dur = tonumber(trace.cd) or 0, tonumber(trace.dur) or 30
    local loop = 2 * dur
    local cdNote = cd > loop + 0.5 and string.format(" Each copy's cooldown is %ds, but in Lenio's 4-copy order a copy has to cast again after %ds: an SPA curse (shorter cooldown) fixes that.", math.ceil(cd), math.floor(loop)) or ""
    local needed = math.max(cd, loop) + dur
    if trace.total < needed then
        return string.format("RUNNING: %ds of the %ds a verdict needs.", math.floor(trace.total), math.ceil(needed)) .. cdNote
    end
    local share = trace.at100 / math.max(1, trace.fullTime or 0)
    if not trace.confirmed then
        return "CAN'T CONFIRM: the game shows no buff value on your units here, so only the timings are known." .. cdNote
    end
    if trace.fullAt and share >= 0.9 and trace.drops == 0 then
        return string.format("WORKS: +100%% reached after %ds and held %d%% of the time since; the buff never fell to nothing.", math.floor(trace.fullAt), math.floor(share * 100 + 0.5))
    end
    if trace.peak >= 0.99 then
        return string.format("PARTLY: it reaches +100%% but holds it only %d%% of the time since (%d drop%s to nothing).", math.floor(share * 100 + 0.5), trace.drops, trace.drops == 1 and "" or "s")
            .. (cdNote ~= "" and cdNote or " Look at the casts below for failed or late ones.")
    end
    return string.format("NOT WORKING: the highest buff seen was +%d%%.", math.floor(trace.peak * 100 + 0.5))
        .. (cdNote ~= "" and cdNote or " The copies don't buff each other: all 4 must stand within each other's range, and each cast must land on a copy that is already buffed.")
end

function Match.buffTestText()
    if App.where ~= "match" then
        local lobbyCheck = Units.lobbyBuffCheck and Units.lobbyBuffCheck()
        return (lobbyCheck and (lobbyCheck .. "\n\n") or "") .. "Not in a match. Turn the test on and start a match; the last result stays on the right."
    end
    if not Units.chainOn() then
        return "Auto Buff or Use abilities is off: turn both on in Battle → Controls."
    end
    local blocks = {
    }
    for _, trace in pairs(Match.buffTrace or {
    }) do
        local casts = {
        }
        for index = math.max(1, # trace.casts - 7), # trace.casts do
            local cast = trace.casts [index]
            local label = cast.relay and ("R#" .. tostring(cast.copy)) or ("#" .. tostring(cast.copy))
            local outcome = cast.failed and ("FAILED" .. (cast.why and (" (" .. tostring(cast.why) .. ")") or "")) or (string.format("+%d%%", math.floor(cast.expect * 100 + 0.5)) .. (cast.seen and string.format(" (game: +%d%%)", math.floor(cast.seen * 100 + 0.5)) or ""))
            table.insert(casts, string.format("%s at %ds %s", label, math.floor(cast.t), outcome))
        end
        local lines = {
            string.format("%s · %s", Units.name(trace.id), tostring(trace.squadText or "")),
            Match.buffVerdict(trace)
        }
        if trace.cd then
            local dur = trace.dur or 30
            local lenio = trace.cd <= 2 * dur + 0.5
            local checkStr = string.format("%s: cooldown %ds, Lenio needs ≤ %ds → %s", Units.name(trace.id), math.ceil(trace.cd - 1e-6), math.floor(2 * dur), lenio and "fits ✓" or "SPA curse needed")
            table.insert(lines, checkStr)
            table.insert(lines, string.format("Cooldown %ds · buff %ds · %s", math.ceil(trace.cd), math.floor(dur),
                lenio and string.format("Lenio's order fits (cooldown ≤ %ds) ✓", math.floor(2 * dur))
                or trace.cd <= 4 * (dur - math.min(Units.BUFF_LEAD, dur / 2))
                and string.format("too long for Lenio's order (needs ≤ %ds): copies chain one at a time, each %ds before the last buff ends", math.floor(2 * dur), Units.BUFF_LEAD)
                or string.format("too long for any loop of 4 ✗ (needs ≤ %ds): an SPA curse fixes that", math.floor(2 * dur))))
        elseif Units.buffCheckText then
            local chk = Units.buffCheckText(trace.id, nil, trace.uuid)
            if chk then
                table.insert(lines, chk)
            end
        end
        if trace.templateText then
            table.insert(lines, trace.templateText)
        end
        if trace.relayText then
            table.insert(lines, trace.relayText)
        end
        if trace.coverText then
            table.insert(lines, trace.coverText)
        end
        if trace.startedAt then
            table.insert(lines, string.format("%ds since start · %s · some buff %ds · fell to nothing %d time%s · highest +%d%%", math.floor(trace.total),
                trace.fullAt and string.format("+100%% first at %ds, then held %ds of %ds", math.floor(trace.fullAt), math.floor(trace.at100), math.floor(trace.fullTime or 0)) or "+100% not reached yet",
                math.floor(trace.any), trace.drops, trace.drops == 1 and "" or "s", math.floor(trace.peak * 100 + 0.5)))
        end
        table.insert(lines, # casts > 0 and ("Casts: " .. table.concat(casts, " · ")) or "Casts: none yet")
        if not trace.startedAt or trace.why then
            table.insert(lines, "Now: " .. tostring(trace.why or "-"))
        end
        if trace.history and # trace.history > 0 then
            table.insert(lines, "Earlier runs: " .. table.concat(trace.history, " | "))
        end
        if # trace.events > 0 then
            table.insert(lines, "Events: " .. table.concat(trace.events, " · "))
        end
        table.insert(blocks, table.concat(lines, "\n"))
    end
    if # blocks == 0 then
        return "No Commander, Windsong or Leafy on the field yet. Place 4 copies of one of them next to each other (or let the farm place them)."
    end
    return table.concat(blocks, "\n\n")
end

-- Decides whether an extra (5th/6th) relay copy can cast now without interfering with the 4-copy squad.
function Match.relayDecide(group, state, squad, relayCopies, top, now, nextSquadWait)
    if not (squad and # squad > 0 and relayCopies and # relayCopies > 0) then
        return nil
    end
    if nextSquadWait ~= nil and nextSquadWait < Units.BUFF_RELAY_GUARD then
        return nil
    end
    local fighters = group.fighters or (group.reach and group.reach.fighters) or {
    }
    local till = state.relayTill or {
    }
    for rIdx, rc in ipairs(relayCopies) do
        if rc.ready then
            local inSquadRange = false
            for _, sc in ipairs(squad) do
                if buffDistSq(rc.position, sc.position) <= sc.range * sc.range then
                    inSquadRange = true
                    break
                end
            end
            if inSquadRange then
                local carried = (state.confirmed and (tonumber(rc.level) or 0) > 0) and rc.level or top
                if carried >= Units.BUFF_RELAY_MIN then
                    local unbuffedFighters = {
                    }
                    for _, f in ipairs(fighters) do
                        if group.buff.types [f.base] and (f.squadReach or 0) < # squad then
                            if buffDistSq(f.position, rc.position) <= rc.range * rc.range then
                                local hasAttr = f.stats and f.stats.GetAttribute and tonumber(f.stats:GetAttribute("_dmg_buff_" .. tostring(f.base)))
                                local isBuffed
                                if hasAttr ~= nil then
                                    isBuffed = hasAttr > 0.02
                                elseif state.confirmed and f.buff ~= nil then
                                    isBuffed = tonumber(f.buff) > 0.02
                                else
                                    isBuffed = now < (till [f.model or f.stats or f] or 0)
                                end
                                if not isBuffed then
                                    table.insert(unbuffedFighters, f)
                                end
                            end
                        end
                    end
                    if # unbuffedFighters > 0 then
                        return rc, rIdx, carried, unbuffedFighters
                    end
                end
            end
        end
    end
    return nil
end

-- ===== Game Auto for abilities (2.25) =====
Match.GameAuto = {
    on = setmetatable({
    }, {
        __mode = "k"
    }),
    LOW_SEC = 12,
    LOW_SHARE = 0.6,
    BAN_SEC = 600
}

-- Watch the game's own calls: the first one with "auto" in its name and a unit of ours among its arguments is the
-- Auto switch. Our own requests are skipped.
function Match.GameAuto.learnHook()
    if Match.GameAuto.hooked or type(Core.EP) ~= "table" or Utils.now() < (Match.GameAuto.hookRetry or 0) then
        return
    end
    Match.GameAuto.hookRetry = Utils.now() + 30
    local wrapped = 0
    -- 2.34: the game's module outlives this copy of the script (App.restart keeps the same client). Keep the game's
    -- own functions on the module and always wrap those: wrapping an older copy's wrapper chained every restarted copy
    -- in memory and made every server call pass through all of them.
    local origs = rawget(Core.EP, "__aaOrig")
    if type(origs) ~= "table" then
        origs = {
        }
        pcall(rawset, Core.EP, "__aaOrig", origs)
    end
    for key, fn in pairs(Core.EP) do
        if type(fn) == "function" and tostring(key):lower():find("server", 1, true) then
            local original = origs [key] or fn
            origs [key] = original
            local ok = pcall(function()
                Core.EP [key] = function(...)
                    if (Match.GameAuto.sending or 0) == 0 and App.alive then
                        pcall(Match.GameAuto.heard, key, ...)
                    end
                    return original(...)
                end
            end)
            if ok then
                wrapped = wrapped + 1
            end
        end
    end
    Match.GameAuto.hooked = wrapped > 0
    App.log(2, "AUTO", string.format("listening for the game's Auto command (%d endpoint call%s)", wrapped, wrapped == 1 and "" or "s"))
end

function Match.GameAuto.heard(via, ...)
    local args = table.pack(...)
    local first = 1
    if args [1] == Core.EP then
        first = 2
    end
    local name = args [first]
    if type(name) ~= "string" or not name:lower():find("auto", 1, true) then
        return
    end
    local shape, unitAt, boolAt, boolVal = {
    }, nil, nil, nil
    for i = first + 1, args.n do
        local v = args [i]
        if typeof(v) == "Instance" then
            if v:FindFirstChild("_stats") and not unitAt and table.find(Match.mine or {
            }, v) then
                unitAt = i - first
                table.insert(shape, "<unit>")
            else
                return
            end
        elseif type(v) == "boolean" and not boolAt then
            boolAt, boolVal = i - first, v
            table.insert(shape, "<on>")
        elseif type(v) == "string" or type(v) == "number" then
            table.insert(shape, v)
        else
            return
        end
    end
    if not unitAt then
        return
    end
    local known = Brain.autoCall
    Brain.autoCall = {
        via = tostring(via),
        name = name,
        shape = shape,
        unitAt = unitAt,
        boolAt = boolAt,
        useSelf = first == 2 or nil,
        at = os.time()
    }
    App.saveSoon()
    if not known or known.name ~= name then
        App.log(1, "AUTO", string.format("learned the game's Auto command: %s (%s)%s", name, boolAt and ("on/off, this press: " .. tostring(boolVal)) or "a toggle", boolAt and "" or " · the farm uses a toggle only where it can read the unit's Auto state"))
    end
end

-- Names with "auto" the game offers, for the log only (never called blindly). Once per session.
function Match.GameAuto.scan()
    if Match.GameAuto.scanned then
        return
    end
    Match.GameAuto.scanned = true
    local names = {
    }
    pcall(function()
        for _, remote in ipairs(ReplicatedStorage.endpoints.client_to_server:GetChildren()) do
            if remote.Name:lower():find("auto", 1, true) then
                table.insert(names, remote.Name)
            end
        end
    end)
    App.log(2, "AUTO", # names > 0 and ("game commands with 'auto' in the name: " .. table.concat(names, ", ")) or "no game command has 'auto' in its name")
end

-- The unit's Auto state if the game shows it (a BoolValue or a boolean attribute with "auto" in its name), else nil.
function Match.GameAuto.state(unit)
    local ok, res = pcall(function()
        local holders = {
        }
        local stats = unit:FindFirstChild("_stats")
        if stats then
            table.insert(holders, stats)
        end
        table.insert(holders, unit)
        for _, inst in ipairs(holders) do
            if inst then
                for _, child in ipairs(inst:GetChildren()) do
                    if child:IsA("BoolValue") and child.Name:lower():find("auto", 1, true) then
                        return child.Value
                    end
                end
                for key, value in pairs(inst:GetAttributes()) do
                    if type(value) == "boolean" and key:lower():find("auto", 1, true) then
                        return value
                    end
                end
            end
        end
        return nil
    end)
    if ok then
        return res
    end
    return nil
end

function Match.GameAuto.usable()
    local call = Brain.autoCall
    return type(call) == "table" and type(call.name) == "string" and type(call.shape) == "table" and call.unitAt ~= nil
end

-- Switch the game's Auto on or off for one unit. Returns ok, why.
function Match.GameAuto.set(unit, on)
    if not Match.GameAuto.usable() then
        return false, "the game's Auto command isn't learned yet"
    end
    local call = Brain.autoCall
    local before = Match.GameAuto.state(unit)
    if not call.boolAt then
        if before == nil then
            return false, "Auto is a toggle here and the unit's Auto state can't be read"
        end
        if before == on then
            Match.GameAuto.on [unit] = on or nil
            return true, "already"
        end
    end
    local args = {
    }
    for i, v in ipairs(call.shape) do
        if i == call.unitAt then
            args [i] = unit
        elseif i == call.boolAt then
            args [i] = on
        else
            args [i] = v
        end
    end
    local fn = Core.EP and Core.EP [call.via]
    if type(fn) ~= "function" then
        return false, "the game's endpoint " .. tostring(call.via) .. " is gone"
    end
    Match.GameAuto.sending = (Match.GameAuto.sending or 0) + 1
    local done, ok, res = false, nil, nil
    task.spawn(function()
        if call.useSelf then
            ok, res = pcall(fn, Core.EP, call.name, table.unpack(args, 1, # call.shape))
        else
            ok, res = pcall(fn, call.name, table.unpack(args, 1, # call.shape))
        end
        done = true
    end)
    local started = Utils.now()
    while not done and Utils.now() - started < 5 do
        task.wait(0.1)
    end
    Match.GameAuto.sending = math.max(0, (Match.GameAuto.sending or 1) - 1)
    if not done then
        return false, "no answer from the game in 5s"
    end
    if not ok then
        return false, tostring(res)
    end
    if res == false then
        return false, "the game refused it"
    end
    task.wait(0.5)
    local after = Match.GameAuto.state(unit)
    if after ~= nil and after ~= on then
        return false, "the unit's Auto state didn't change"
    end
    Match.GameAuto.on [unit] = on or nil
    return true, after == nil and "sent (the game shows no Auto state to check)" or "confirmed"
end

-- Called by the rotation each tick. Returns a status text while the game's Auto runs the squad, else nil.
function Match.GameAuto.squadStep(group, state, squad, need, cap, now)
    if not Config.gameAuto then
        if state.gameAuto then
            Match.GameAuto.release(group, state, "Use Game Auto was switched off", now, 0)
        end
        return nil
    end
    if state.gameAuto then
        if not squad then
            Match.GameAuto.release(group, state, "a squad copy left the field", now, 0)
            return nil
        end
        local low = # (Match.enemies or {
        }) > 0 and (group.seen or 0) < cap * Match.GameAuto.LOW_SHARE
        if low then
            state.autoLowSince = state.autoLowSince or now
            if now - state.autoLowSince >= Match.GameAuto.LOW_SEC then
                Match.GameAuto.release(group, state, string.format("the buff stayed under +%d%% for %ds", math.floor(cap * Match.GameAuto.LOW_SHARE * 100 + 0.5), Match.GameAuto.LOW_SEC), now, Match.GameAuto.BAN_SEC)
                return nil
            end
        else
            state.autoLowSince = nil
        end
        return string.format("the game's Auto casts the squad (+%d%% now)", math.floor((group.seen or 0) * 100 + 0.5))
    end
    if state.autoBusy then
        return "switching the squad's Auto"
    end
    if not squad or now < (state.autoBan or 0) or not state.confirmed or (state.done or 0) < need * 2 or (group.seen or 0) < cap - 0.05 then
        return nil
    end
    if not Match.GameAuto.usable() then
        if not state.autoHint then
            state.autoHint = true
            App.log(1, "AUTO", string.format("%s: the rotation is steady at +%d%%. To hand it to the game's Auto, press Auto on any unit's ability once: the farm learns the command and switches the squad over (Use Game Auto)", Units.name(group.id), math.floor(cap * 100 + 0.5)))
        end
        return nil
    end
    state.autoBusy = true
    task.spawn(function()
        local done, why = {
        }, nil
        for _, copy in ipairs(squad) do
            if not App.alive or not copy.model.Parent or not Config.gameAuto then
                why = "the squad changed while switching"
                break
            end
            local ok, res = Match.GameAuto.set(copy.model, true)
            if not ok then
                why = res
                break
            end
            table.insert(done, copy.model)
        end
        if not why and not (Config.gameAuto and Config.actives and App.alive) then
            why = "Use Game Auto or Auto Abilities was switched off meanwhile"
        end
        if why then
            for _, model in ipairs(done) do
                Match.GameAuto.set(model, false)
            end
            state.autoBan = Utils.now() + Match.GameAuto.BAN_SEC
            App.log(1, "AUTO", string.format("%s: the game's Auto wasn't switched on (%s), the farm keeps casting the rotation", Units.name(group.id), tostring(why)))
        else
            state.gameAuto, state.autoLowSince = true, nil
            App.log(1, "AUTO", string.format("%s: the rotation is steady at +%d%%, the game's Auto casts the %d squad copies now (the farm takes over again if the buff drops)", Units.name(group.id), math.floor((group.seen or 0) * 100 + 0.5), # done))
        end
        state.autoBusy = nil
    end)
    return "switching the squad to the game's Auto"
end

function Match.GameAuto.copiesOf(attack)
    local list = {
    }
    for _, unit in ipairs(Match.mine or {
    }) do
        local stats = unit:FindFirstChild("_stats")
        local active = stats and stats:FindFirstChild("active_attack")
        if active and tostring(active.Value) == tostring(attack) then
            table.insert(list, {
                model = unit
            })
        end
    end
    return list
end

function Match.GameAuto.release(group, state, why, now, ban)
    state.gameAuto, state.autoLowSince = nil, nil
    state.autoBan = now + (ban or 0)
    state.casts, state.last = {
    }, - 99
    local models = {
    }
    for _, copy in ipairs(group.copies or {
    }) do
        if Match.GameAuto.on [copy.model] then
            table.insert(models, copy.model)
        end
    end
    state.autoBusy = true
    task.spawn(function()
        for _, model in ipairs(models) do
            if App.alive and model.Parent then
                Match.GameAuto.set(model, false)
            end
            Match.GameAuto.on [model] = nil
        end
        state.autoBusy = nil
    end)
    App.log(1, "AUTO", string.format("%s: back to the farm's own rotation (%s)", Units.name(group.id), why))
end

function Match.autoBuffPick(now, clock)
    if not Units.chainOn() then
        Match.buffText = nil
        return nil
    end
    Match.buffState = Match.buffState or {
    }
    local test = Config.buffTest == true
    local pick
    local lines = {
    }
    for _, group in ipairs(Match.autoBuffGroups(clock)) do
        local state = Match.buffState [group.attack]
        if not state then
            state = {
                casts = {
                },
                last = - 99,
                done = 0
            }
            Match.buffState [group.attack] = state
        end
        local need = group.buff.squad or Units.BUFF_COPIES
        local trace = Match.buffTraceFor(group, need)
        local learned = Brain.stack [group.attack]
        local dataDur = tonumber(group.buff.time) or 30
        local dur = learned and tonumber(learned.dur) or dataDur
        local cap = learned and tonumber(learned.cap) or 1
        if group.seen > 0.02 then
            state.confirmed = true
            trace.confirmed = true
        end
        -- A drop the game shows: the cast that gave that level has ended. Its real length replaces the estimate.
        if state.confirmed and state.seen and group.seen < state.seen - 0.02 then
            local ended
            for _, cast in ipairs(state.casts) do
                if math.abs((cast.level or 0) - state.seen) <= 0.06 and (not ended or cast.at < ended.at) then
                    ended = cast
                end
            end
            if ended and now - ended.at > 3 then
                local real = now - ended.at
                if real >= dataDur * 0.4 and real <= dataDur * 2 then
                    local entry = Brain.stack [group.attack] or {
                    }
                    entry.dur = entry.dur and (entry.dur + (real - entry.dur) * 0.5) or real
                    entry.durAt = os.time()
                    Brain.stack [group.attack] = entry
                    dur = entry.dur
                    App.saveSoon()
                end
                ended.at = now - dur
            end
        end
        state.seen = group.seen
        local live, top = {
        }, 0
        for index = # state.casts, 1, - 1 do
            local cast = state.casts [index]
            if now - cast.at >= dur then
                table.remove(state.casts, index)
            else
                table.insert(live, {
                    left = dur - (now - cast.at),
                    level = cast.level
                })
                top = math.max(top, cast.level or 0)
            end
        end
        -- The squad: the copies the rotation runs on. A member that leaves the field ends the rotation.
        local present = {
        }
        for _, copy in ipairs(group.copies) do
            present [copy.model] = copy
        end
        local squad
        if state.squad then
            squad = {
            }
            for _, model in ipairs(state.squad) do
                if present [model] then
                    table.insert(squad, present [model])
                end
            end
            if # squad < need then
                App.log(1, "BUFF", string.format("%s: a copy of the rotation left the field, so it waits for %d copies within each other's range again", Units.name(group.id), need))
                Match.buffTraceEvent(trace, "a rotation copy left the field: waiting for a full squad again", now)
                Match.buffTraceArchive(trace, now)
                state.squad, squad = nil, nil
                state.casts, live, top = {
                }, {
                }, 0
            end
        end
        local found, most = nil, 0
        if not squad then
            found, most = Match.buffSquad(group.copies, need)
        end
        local members = squad or found or {
        }
        local squadSet = {
        }
        for _, m in ipairs(members) do
            squadSet [m.model or m] = true
        end
        local relayCopies = {
        }
        if # members >= need then
            for _, copy in ipairs(group.copies) do
                if not squadSet [copy.model or copy] then
                    table.insert(relayCopies, copy)
                end
            end
            if group.fighters then
                group.reach = Match.buffReach(group.copies, group.fighters, group.buff.types, squadSet)
            end
        end
        state.id = group.id
        Match.buffCoverTick(group, state, members, relayCopies, need, now)
        local cd = group.cd > 0 and group.cd or group.buff.cd
        trace.cd, trace.dur, trace.uuid = cd, dur, group.uuid or trace.uuid
        local plan = Units.buffPlan(need, cd, dur, group.base, cap, group.buff.follow)
        local ready, best, soon = 0, nil, nil
        for _, copy in ipairs(members) do
            -- Without a readable buff value the level a copy carries is the one our timing says is up.
            copy.carried = state.confirmed and copy.level or top
            if copy.ready then
                ready = ready + 1
                if not best or copy.carried > best.carried + 0.01 then
                    best = copy
                end
            else
                soon = math.min(soon or copy.wait, copy.wait)
            end
        end
        local go, why, wait = false, nil, nil
        if not squad then
            if not found then
                if # group.copies < need then
                    why = string.format("%d of %d copies placed: the infinite buff starts once %d stand within each other's range", # group.copies, need, need)
                else
                    why = string.format("only %d of the %d copies reach each other: all %d must stand within each other's range", most, # group.copies, need)
                end
            elseif ready < need then
                why, wait = string.format("%d of %d squad copies ready: the rotation starts with all of them off cooldown", ready, need), soon
            elseif Match.stopping then
                why = "the run is ending: no new rotation"
            elseif not test and group.reach.covered <= 0 then
                why = "no " .. tostring(group.kind) .. " attacker stands in range of the copies yet"
            elseif not test and # Match.enemies == 0 then
                why = "no enemies on the field: the rotation starts with the next wave"
            else
                state.squad = {
                }
                for _, copy in ipairs(found) do
                    table.insert(state.squad, copy.model)
                end
                state.casts, state.last, live, top = {
                }, - 99, {
                }, 0
                squad = found
                trace.startedAt, trace.sampledAt = now, now
                trace.total, trace.at100, trace.any, trace.drops, trace.peak, trace.lastLevel = 0, 0, 0, 0, 0, 0
                trace.fullAt, trace.fullTime = nil, 0
                trace.casts = {
                }
                Match.buffTraceEvent(trace, string.format("%d copies within each other's range: the rotation starts", need), now)
                App.log(1, "BUFF", string.format("%s: %d copies stand within each other's range, the infinite buff starts%s", Units.name(group.id), need, test and " (test: no enemies or attackers needed)" or ""))
                go, why = true, "starts the infinite buff with copy #1"
            end
        else
            if not best then
                why, wait = "every copy is on cooldown", soon
            else
                -- Once it runs it never waits for enemies or a boss: a pause would break the chain.
                go, why, wait = Units.buffDecide(plan, live, now - state.last, true)
            end
        end
        local autoText = Match.GameAuto.squadStep(group, state, squad, need, cap, now)
        if autoText then
            go, why, wait = false, autoText, nil
        end
        local relayPick
        if go and not pick and best then
            pick = best.model
            local index = 1
            for position, model in ipairs(state.squad or {
            }) do
                if model == best.model then
                    index = position
                end
            end
            Match.buffPending = {
                attack = group.attack,
                level = math.min(cap, (1 + group.base) * (1 + math.max(0, best.carried)) - 1),
                why = why,
                copy = index
            }
        elseif squad and not go and not pick and # relayCopies > 0 then
            local nextSquadWait
            if best then
                nextSquadWait = wait or 0
            else
                local _, _, decideWait = Units.buffDecide(plan, live, now - state.last, true)
                nextSquadWait = math.max(soon or 0, decideWait or 0)
            end
            local rc, rIdx, rcCarried, rcFighters = Match.relayDecide(group, state, squad, relayCopies, top, now, nextSquadWait)
            if rc then
                pick, relayPick = rc.model, rIdx
                Match.buffPending = {
                    attack = group.attack,
                    level = math.min(cap, (1 + group.base) * (1 + math.max(0, rcCarried)) - 1),
                    why = string.format("relay #%d buffs distant attackers", rIdx),
                    copy = rIdx,
                    relay = true,
                    fighters = rcFighters,
                    dur = dur
                }
            end
        end
        local tpl = Match.buffTemplates and Match.buffTemplates [group.attack]
        if tpl and type(tpl.spots) == "table" and # tpl.spots > 0 then
            local pts = {
            }
            for _, sp in ipairs(tpl.spots) do
                table.insert(pts, Match.spotKey(sp))
            end
            trace.templateText = string.format("Squad template (%d spots): %s", # tpl.spots, table.concat(pts, " · "))
        elseif # members >= need then
            local pts = {
            }
            for _, m in ipairs(members) do
                table.insert(pts, Match.spotKey(m.position))
            end
            trace.templateText = string.format("Squad spots (%d): %s", # members, table.concat(pts, " · "))
        else
            trace.templateText = "Squad template: pending placement"
        end
        local maxRelay = math.max(0, Units.BUFF_RELAY_MAX - need)
        local rReady = 0
        for _, rc in ipairs(relayCopies) do
            if rc.ready then
                rReady = rReady + 1
            end
        end
        trace.relayText = string.format("Relay copies: %d/%d placed (%d ready) · %d casts", # relayCopies, maxRelay, rReady, state.relayDone or 0)
        if group.reach.total > 0 then
            local pFull = math.floor((group.reach.full or 0) / group.reach.total * 100 + 0.5)
            local pRelay = math.floor((group.reach.relay or 0) / group.reach.total * 100 + 0.5)
            local pNone = math.max(0, 100 - pFull - pRelay)
            trace.coverText = string.format("Damage coverage (%s): full squad %d%% · relay copies %d%% · unbuffed %d%%", tostring(group.kind), pFull, pRelay, pNone)
        else
            trace.coverText = string.format("Damage coverage (%s): no %s attackers placed yet", tostring(group.kind), tostring(group.kind))
        end
        local level = state.confirmed and group.seen or top
        Match.buffTraceSample(trace, level, now)
        trace.why = not go and (relayPick and ("casting relay #" .. tostring(relayPick)) or (why .. (wait and string.format(" (%ds)", math.ceil(wait)) or ""))) or nil
        trace.squadText = squad and string.format("%d copies within each other's range ✓ (rotation running)", need)
            or found and string.format("%d copies within each other's range ✓", need)
            or string.format("%d placed, %d reach each other, %d needed ✗", # group.copies, most, need)
        local effect
        if state.confirmed then
            effect = string.format("effect now +%d%% (seen in the match)", math.floor(group.seen * 100 + 0.5))
        elseif state.done > 0 then
            effect = string.format("effect about +%d%% (estimate from timings: the game shows no buff value here)", math.floor(top * 100 + 0.5))
        else
            effect = "no buff cast yet"
        end
        local cover = group.reach.total > 0 and string.format("%d%% of %s damage in range", math.floor(group.reach.covered / group.reach.total * 100 + 0.5), tostring(group.kind)) or ("no " .. tostring(group.kind) .. " attacker placed")
        local actionTxt = go and ("casting: " .. tostring(why)) or (relayPick and ("casting: relay #" .. tostring(relayPick)) or ("waiting: " .. tostring(why)))
        table.insert(lines, string.format("%s ×%d%s · %s · %d ready · %s · %s · %s%s", Units.name(group.id), # group.copies, # relayCopies > 0 and (" (+" .. # relayCopies .. " relay)") or "", trace.squadText, ready, effect, cover,
            actionTxt, (not go and not relayPick and wait) and string.format(" (%ds)", math.ceil(wait)) or ""))
    end
    Match.buffText = # lines > 0 and table.concat(lines, "\n") or "no Commander, Windsong or Leafy on the field"
    if test and Utils.now() - (Match.buffTestSavedAt or 0) >= 10 and Match.buffTrace and next(Match.buffTrace) then
        Match.buffTestSavedAt = Utils.now()
        Brain.buffTest = {
            at = os.time(),
            text = Match.buffTestText()
        }
        App.saveSoon()
    end
    return pick
end

-- A cast went out: remember it, then check two seconds later that the game really took it.
function Match.autoBuffCast(unit, stats, attack, types, askedAt)
    askedAt = askedAt or Utils.now()
    local said0 = App.gameSaid and App.gameSaid(askedAt) or nil
    local pending = Match.buffPending
    local state = Match.buffState and Match.buffState [attack]
    if not state then
        return
    end
    local isRelayCopy = pending and pending.attack == attack and pending.relay == true
    local copyNum = pending and pending.attack == attack and pending.copy or 0
    local copyLabel = isRelayCopy and string.format("relay #%d", copyNum) or (copyNum > 0 and string.format("copy #%d", copyNum) or "copy")
    local cast = {
        at = askedAt,
        level = (pending and pending.attack == attack and pending.level) or 0,
        by = unit
    }
    local markedFighters = {
    }
    if isRelayCopy then
        state.relayDone = (state.relayDone or 0) + 1
        state.relayTill = state.relayTill or {
        }
        local dur = pending and tonumber(pending.dur) or 30
        for _, f in ipairs(pending and pending.fighters or {
        }) do
            local fKey = f.model or f.stats or f
            table.insert(markedFighters, {
                k = fKey,
                prev = state.relayTill [fKey]
            })
            state.relayTill [fKey] = cast.at + dur
        end
    else
        table.insert(state.casts, cast)
        state.last, state.done = cast.at, state.done + 1
    end
    local trace = Match.buffTrace and Match.buffTrace [attack]
    local entry
    if trace and trace.startedAt then
        entry = {
            t = cast.at - trace.startedAt,
            copy = copyNum,
            relay = isRelayCopy or nil,
            expect = cast.level
        }
        table.insert(trace.casts, entry)
        while # trace.casts > 40 do
            table.remove(trace.casts, 1)
        end
    end
    task.delay(2, function()
        if not App.alive then
            return
        end
        local last = stats and stats.FindFirstChild and stats:FindFirstChild("last_active_cast") or nil
        if last and tick() - (tonumber(last.Value) or 0) > 8 then
            -- The game did not start its cooldown: the cast failed, so the order is worked out again.
            local said = (App.gameSaid and App.gameSaid(askedAt)) or said0
            local reason = said and ("the game said: " .. tostring(said)) or "no message from the game"
            if isRelayCopy then
                state.relayDone = math.max(0, (state.relayDone or 1) - 1)
                if state.relayTill then
                    for _, mf in ipairs(markedFighters) do
                        state.relayTill [mf.k] = mf.prev
                    end
                end
            else
                local index = table.find(state.casts, cast)
                if index then
                    table.remove(state.casts, index)
                end
                state.last = - 99
            end
            if entry then
                entry.failed = true
                entry.why = said
            end
            if trace then
                Match.buffTraceEvent(trace, string.format("%s: a cast didn't go through (%s)", copyLabel, reason), Utils.now())
            end
            local unitName = (stats and stats.FindFirstChild and stats:FindFirstChild("id") and Units.name(stats.id.Value)) or (trace and Units.name(trace.id)) or "Buffer"
            App.log(2, "BUFF", string.format("%s (%s): the cast did not go through (%s), the rotation is recalculated", unitName, copyLabel, reason))
            return
        end
        local seen = Match.buffLevel(types)
        if seen > 0.02 then
            state.confirmed = true
            cast.level = seen
            if entry then
                entry.seen = seen
            end
        end
    end)
end

function Match.actives()
    if not Config.actives then
        -- Auto Abilities off: squads the game's Auto was casting are switched back.
        for attack, state in pairs(Match.buffState or {
        }) do
            if state.gameAuto and not state.autoBusy then
                Match.GameAuto.release({
                    id = state.id,
                    copies = Match.GameAuto.copiesOf(attack)
                }, state, "Auto Abilities was switched off", Utils.now(), 0)
            end
        end
        return
    end
    if Config.gameAuto then
        Match.GameAuto.learnHook()
        Match.GameAuto.scan()
    end
    Match.unitBusy = Match.unitBusy or {}
    local now = tick()
    local now2 = Utils.now()
    local relayCaster = Match.autoBuffPick(now2, now)
    for _, unit in ipairs(Match.mine) do
        local stats = unit._stats
        local activeAttack, activeAttackCooldown, lastActiveCast = stats:FindFirstChild("active_attack"), stats:FindFirstChild("active_attack_cooldown"), stats:FindFirstChild("last_active_cast")
        if activeAttack and activeAttackCooldown and lastActiveCast and activeAttack.Value ~= "nil" and activeAttack.Value ~= "" then
            if Match.isGale(stats, tostring(activeAttack.Value)) then
                pcall(Match.learnToggle, unit, stats, tostring(activeAttack.Value), now2)
            end
            if activeAttackCooldown.Value - (now - lastActiveCast.Value) > 0 then
                Match.readySince [unit] = nil
            else
                Match.readySince [unit] = Match.readySince [unit] or now2
                local attackInfo = Units.attackInfo(activeAttack.Value)
                local position = unit:GetPivot().Position
                local rangeValue = stats.range.Value
                local fusionReady, str, value, rotInterval, isRelay, fusePartner
                local flag = Match.trialId == stats.id.Value and Brain.trial and Brain.trial.study and # Match.enemies > 0 and not Match.isGale(stats, tostring(activeAttack.Value))
                if Units.FUSION.attacks[stats.id.Value] == activeAttack.Value then
                    fusionReady, fusePartner = Match.fusionReady(unit)
                    str = "Fusion: both partners reached upgrade 7"
                elseif flag then
                    fusionReady, str = true, "on study: what it does"
                elseif Match.isGale(stats, tostring(activeAttack.Value)) then
                    fusionReady, str = Match.gale(unit, stats, tostring(activeAttack.Value), now2)
                elseif attackInfo.ally and Units.chainOn(stats.id.Value) then
                    fusionReady, str = relayCaster == unit, "Auto Buff: " .. tostring(Match.buffPending and Match.buffPending.why or "rotation")
                    isRelay = fusionReady
                elseif attackInfo.ally and Brain.stack [activeAttack.Value] and Brain.stack [activeAttack.Value].stacks and Config.community then
                    fusionReady, str, rotInterval = Match.buffRotation(unit, stats, tostring(activeAttack.Value), attackInfo, tonumber(attackInfo.ally.time) or 30, now2)
                elseif attackInfo.ally or attackInfo.allyCd or attackInfo.allyRange then
                    local time = (attackInfo.ally and attackInfo.ally.time) or (attackInfo.allyCd and attackInfo.allyCd.time) or (attackInfo.allyRange and attackInfo.allyRange.time) or 30
                    local value2 = Match.buffedTill [activeAttack.Value]
                    if not value2 then
                        value2 = setmetatable({
                        }, {
                            __mode = "k"
                        })
                        Match.buffedTill [activeAttack.Value] = value2
                    end
                    local list, count, count2, count3 = {
                    }, 0, 0, 0
                    for _, unit2 in ipairs(Match.mine) do
                        local stats = unit2._stats
                        local idValue = stats.id.Value
                        if unit2 ~= unit and not Units.isFarm(idValue) and not Units.allyBuff(idValue) and (Utils.flat(unit2:GetPivot().Position) - Utils.flat(position)).Magnitude <= rangeValue then
                            local _, types2 = Units.types(idValue)
                            if not attackInfo.ally or attackInfo.ally.types [types2] then
                                table.insert(list, unit2)
                                if stats:FindFirstChild("target") and stats.target.Value ~= nil then
                                    local flag = (value2 [unit2] or 0) >= now2
                                    if attackInfo.ally then
                                        flag = Match.buffOn(stats, types2) or (value2 [unit2] or 0) - time + 2 >= now2
                                    end
                                    if flag then
                                        count2 = count2 + 1
                                        count3 = math.max(count3, value2 [unit2] or 0)
                                    else
                                        count = count + 1
                                    end
                                end
                            end
                        end
                    end
                    local value3 = Brain.stack [activeAttack.Value]
                    if value3 and not value3.stacks and os.time() - (value3.at or 0) > 3 * 86400 then
                        value3 = nil
                    end
                    local buffLevel = attackInfo.ally and count2 > 0 and Match.buffLevel(attackInfo.ally.types) or 0
                    local value4 = not Match.buffTestBusy and count2 > 0 and attackInfo.ally and Config.community and buffLevel > 0 and ((value3 == nil and count3 - now2 > 5) or (value3 and value3.stacks and buffLevel < (value3.cap or 1) - 0.02))
                    if count > count2 or value4 then
                        fusionReady, str = true, string.format("buffs %d of your units that are fighting", count + count2)
                        if value4 and value3 == nil then
                            value = {
                                key = activeAttack.Value,
                                types = attackInfo.ally.types,
                                before = buffLevel
                            }
                            str = str .. string.format(" (testing whether a 2nd buff adds up: now +%d%%)", math.floor(buffLevel * 100 + 0.5))
                        elseif value4 then
                            str = str .. string.format(" (chaining: now +%d%%)", math.floor(buffLevel * 100 + 0.5))
                        end
                        for _, item in ipairs(list) do
                            value2 [item] = now2 + time
                        end
                    end
                elseif attackInfo.baseSafe then
                    for _, enemy in ipairs(Match.enemies) do
                        if enemy.prog >= 0.98 then
                            fusionReady, str = true, "an enemy is at the base"
                            break
                        end
                    end
                else
                    local count, flag, nearBase, inRangeHp = 0, false, false, 0
                    local maxInRangeProg, bossHpFrac, bossProg = 0, 0, 0
                    local flatPos = Utils.flat(position)
                    local rSq = rangeValue * rangeValue
                    local isWholeMap = (attackInfo.wholeMap == true)
                    for _, enemy in ipairs(Match.enemies) do
                        local enemyFlat = Utils.flat(enemy.pos)
                        local dx = enemyFlat.X - flatPos.X
                        local dz = enemyFlat.Z - flatPos.Z
                        local distSq = dx * dx + dz * dz
                        local dist = math.sqrt(distSq)
                        local speed = enemy.speed or (enemy.v and enemy.v * (Match.roadLength or 500)) or 8
                        local castLead = (attackInfo.castDelay or 0.25) + dist / math.max(10, attackInfo.projSpeed or 100)
                        local futPos = enemy.pos + (enemy.dir or Vector3.new(0, 0, 0)) * (speed * castLead)
                        local futFlat = Utils.flat(futPos)
                        local fdx = futFlat.X - flatPos.X
                        local fdz = futFlat.Z - flatPos.Z
                        local futDistSq = fdx * fdx + fdz * fdz
                        local inHitRange = isWholeMap or (distSq <= rSq) or (futDistSq <= rSq)
                        if inHitRange then
                            count = count + 1
                            inRangeHp = inRangeHp + (enemy.hp or 0)
                            local eProg = tonumber(enemy.prog) or 0
                            if eProg > maxInRangeProg then
                                maxInRangeProg = eProg
                            end
                            if eProg >= 0.82 then
                                nearBase = true
                            end
                            if enemy.boss then
                                flag = true
                                if eProg > bossProg then
                                    bossProg = eProg
                                end
                                local eHp = tonumber(enemy.hp) or 0
                                local eMaxHp = math.max(1, eHp)
                                if enemy.m then
                                    local okH, bHum = pcall(function()
                                        return enemy.m:FindFirstChildOfClass("Humanoid")
                                    end)
                                    if okH and bHum and bHum.MaxHealth and bHum.MaxHealth > 0 then
                                        eMaxHp = bHum.MaxHealth
                                    end
                                end
                                local bFrac = math.max(0, math.min(1, eHp / eMaxHp))
                                if bFrac > bossHpFrac then
                                    bossHpFrac = bFrac
                                end
                            end
                        end
                    end
                    local now22 = now2 - Match.readySince [unit]
                    if Match.trialId == stats.id.Value and (tonumber((Core.Units [Match.trialId] or {
                    }).damage) or 0) <= 0 and # Match.enemies > 0 then
                        fusionReady, str = true, "on trial"
                    else
                        local aiActiveDone = false
                        if Config.aiTactics ~= false and not Match.trialId and AI and AI.shouldUseActive then
                            local wtObj = workspace and workspace:FindFirstChild("_wave_time")
                            local waveTimeLeft = (wtObj and tonumber(wtObj.Value)) or 15.0
                            local isFullAoe = (attackInfo.full == true) or (type(attackInfo.shape) == "table" and attackInfo.shape.type == "full_aoe")
                            local isStun = (tonumber(attackInfo.stun) or 0) > 0
                            local isSlow = (tonumber(attackInfo.slow) or 0) > 0
                            local isDebuff = ((tonumber(attackInfo.amp) or 0) > 0) or (attackInfo.bleed == true) or ((tonumber(attackInfo.dot) or 0) > 0)
                            local aCtx = {
                                count = count,
                                crowd = # Match.enemies,
                                inRangeHp = inRangeHp,
                                hpAlive = Match.hpAlive or 0,
                                teamDps = Match.teamDps or 0,
                                bossInRange = flag,
                                bossHpFrac = bossHpFrac,
                                bossProg = bossProg,
                                maxInRangeProg = maxInRangeProg,
                                nearBase = nearBase,
                                pressure = Match.pressure or maxInRangeProg,
                                baseHpFrac = AI.getBaseHpFrac(),
                                isStun = isStun,
                                isSlow = isSlow,
                                isDebuff = isDebuff,
                                isFullAoe = isFullAoe,
                                isWholeMap = isWholeMap,
                                cd = activeAttackCooldown.Value,
                                held = now22,
                                waveTimeLeft = waveTimeLeft,
                                wave = Match.wave(),
                                totalWaves = Match.total or 15,
                                isInfinite = (Match.infinite == true)
                            }
                            local okAct, aiCast, aiActScore, aiActWhy = pcall(AI.shouldUseActive, aCtx)
                            if okAct and type(aiCast) == "boolean" then
                                fusionReady = aiCast
                                str = aiActWhy or "ActiveNN"
                                aiActiveDone = true
                                if aiCast then
                                    local scoreTxt = "guardrail"
                                    if type(aiActScore) == "number" then
                                        scoreTxt = string.format("%.3f", aiActScore)
                                    end
                                    App.log(2, "AI_ACTIVE", string.format("%s (%s): CAST (score=%s, count=%d, boss=%s, reason=%s)", Units.name(stats.id.Value), tostring(activeAttack.Value), scoreTxt, count, tostring(flag), tostring(str)))
                                end
                            end
                        end
                        if not aiActiveDone then
                            fusionReady, str = Units.castDecision({
                                count = count,
                                boss = flag,
                                nearBase = nearBase,
                                crowd = # Match.enemies,
                                held = now22,
                                cd = activeAttackCooldown.Value,
                                inRangeHp = inRangeHp,
                                teamDps = Match.teamDps or 0
                            })
                        end
                    end
                end
                if fusionReady and isRelay and Match.buffBusy then
                    -- One rotation cast at a time: the next copy is picked once this one is recorded.
                    fusionReady = false
                end
                if fusionReady and not Match.unitBusy[unit] then
                    Match.unitBusy[unit] = true
                    local relayPending = isRelay and Match.buffPending or nil
                    if isRelay then
                        Match.buffBusy = true
                    end
                    if Units.FUSION.attacks[stats.id.Value] == activeAttack.Value then
                        Match.fusionRetryAt = Utils.now() + 5
                    end
                    Match.readySince [unit] = nil
                    local heroesBefore = fusePartner and Match.fusionHeroes() or 0
                    task.spawn(function()
                        local askedAt = Utils.now()
                        local ok = App.request("active", "use_active_attack", unit)
                        Match.unitBusy[unit] = nil
                        if fusePartner then
                            Match.fusionFollow(unit, fusePartner, heroesBefore)
                        end
                        if isRelay then
                            Match.buffBusy = nil
                            Match.buffPending = relayPending
                        end
                        if ok then
                            if rotInterval then
                                Match.buffNext = Match.buffNext or {}
                                Match.buffNext[tostring(activeAttack.Value)] = Utils.now() + rotInterval
                            end
                            if isRelay then
                                Match.autoBuffCast(unit, stats, tostring(activeAttack.Value), attackInfo.ally.types, askedAt)
                            end
                            Match.casts = Match.casts or {
                            }
                            Match.casts [stats.id.Value] = (Match.casts [stats.id.Value] or 0) + 1
                            App.status("Abilities", string.format("%s used its ability — %s", Units.name(stats.id.Value), str))
                            App.log(2, "ABILITY", Units.name(stats.id.Value) .. ": " .. str)
                            if attackInfo.ally then
                                task.delay(2, function()
                                    if not App.alive then
                                        return
                                    end
                                    local value = Match.buffSeen [stats.id.Value] or {
                                        casts = 0,
                                        levels = {
                                        }
                                    }
                                    Match.buffSeen [stats.id.Value] = value
                                    value.casts = value.casts + 1
                                    if # value.levels < 12 then
                                        table.insert(value.levels, math.floor(Match.buffLevel(attackInfo.ally.types) * 100 + 0.5))
                                    end
                                end)
                            end
                            if value then
                                Match.buffTestBusy = true
                                task.delay(2, function()
                                    Match.buffTestBusy = false
                                    if not App.alive then return end
                                    local buffLevel = Match.buffLevel(value.types)
                                    local flag = buffLevel > value.before + 0.05
                                    Brain.stack [value.key] = {
                                        stacks = flag,
                                        cap = flag and 1 or nil,
                                        before = value.before,
                                        after = buffLevel,
                                        at = os.time()
                                    }
                                    App.log(1, "ABILITY", string.format("%s's buff %s: +%d%% → +%d%% with a second copy", Units.name(stats.id.Value), flag and "adds up (chaining it from now on)" or "doesn't add up (copies take turns)", math.floor(value.before * 100 + 0.5), math.floor(buffLevel * 100 + 0.5)))
                                    App.saveSoon()
                                end)
                            end
                        end
                    end)
                    return
                end
            end
        end
    end
end
Match.prioAt = setmetatable({
}, {
    __mode = "k"
})

function Match.targeting()
    local changes = 0
    local now = Utils.now()
    for _, unit in ipairs(Match.trainee and Match.mine or {
    }) do
        local stats = unit._stats
        local priority = stats:FindFirstChild("priority")
        if priority and stats:FindFirstChild("uuid") and stats.uuid.Value == Match.trainee and priority.Value ~= "last" and now - (Match.prioAt [unit] or 0) > 6 then
            Match.prioAt [unit] = now
            if App.request("prio", "change_priority", unit, "last") then
                App.log(2, "TARGET", Units.name(stats.id.Value) .. " → last (takedown training)")
            end
            changes = changes + 1
            if changes >= 5 then return end
        end
    end
    local function aiHasPrio(tbl, name)
        if type(tbl) ~= "table" or not name then
            return false
        end
        if tbl[name] then
            return true
        end
        for idxP = 1, #tbl do
            if tbl[idxP] == name then
                return true
            end
        end
        return false
    end
    local flag, hasBoss, nearBase = false, false, false
    for _, enemy in ipairs(Match.enemies or {
    }) do
        if enemy.fly then flag = true end
        if enemy.boss then hasBoss = true end
        if (enemy.prog or 0) >= 0.84 then nearBase = true end
    end
    nearBase = nearBase or (Match.pressure or 0) >= Config.dangerReach
    for _, unit in ipairs(Config.community and Match.mine or {
    }) do
        local stats = unit._stats
        local tip = Core.TIPS [stats.id.Value]
        local priority = stats:FindFirstChild("priority")
        if tip and tip.target and priority and now - (Match.prioAt [unit] or 0) > 6 then
            local flyerOverrides = flag and Match.canAir(unit) and not tip.keepOnAir
            if not flyerOverrides then
                local wantPrio = tip.target
                local whyText = tip.why
                if nearBase and not hasBoss and wantPrio == "strongest" then
                    wantPrio = "first"
                    whyText = "defending base (yielded from tip)"
                end
                if priority.Value ~= wantPrio then
                    local okP, validP = pcall(Core.USC.get_valid_priorities, unit)
                    if okP and type(validP) == "table" and aiHasPrio(validP, wantPrio) then
                        Match.prioAt [unit] = now
                        if App.request("prio", "change_priority", unit, wantPrio) then
                            App.log(2, "TARGET", Units.name(stats.id.Value) .. " → " .. wantPrio .. " (" .. tostring(whyText) .. ")")
                        end
                        changes = changes + 1
                        if changes >= 5 then return end
                    end
                end
            end
        end
    end
    for _, unit in ipairs(flag and Match.mine or {
    }) do
        local stats = unit._stats
        local priority = stats:FindFirstChild("priority")
        local tipObj = Config.community and Core.TIPS [stats.id.Value] or nil
        local keepTipOnAir = tipObj and tipObj.target and tipObj.keepOnAir
        if priority and priority.Value ~= "flying" and not keepTipOnAir and Match.canAir(unit) and not Units.isFarm(stats.id.Value) and not Units.allyBuff(stats.id.Value) and now - (Match.prioAt [unit] or 0) > 4 then
            local ok, res = pcall(Core.USC.get_valid_priorities, unit)
            if ok and type(res) == "table" and aiHasPrio(res, "flying") then
                Match.prioAt [unit] = now
                if App.request("prio", "change_priority", unit, "flying") then
                    App.log(2, "TARGET", Units.name(stats.id.Value) .. " → flying (a flyer is on the road)")
                end
                changes = changes + 1
                if changes >= 5 then return end
            end
        end
    end
    if not Config.smartTarget then
        return
    end
    local aiPrevById = {}
    for _, unit in ipairs(Match.mine) do
        local stats = unit._stats
        local idValue = stats.id.Value
        local priority = stats:FindFirstChild("priority")
        local value = Match.trainee and stats:FindFirstChild("uuid") and stats.uuid.Value == Match.trainee
        local target = Config.community and Core.TIPS [idValue] and Core.TIPS [idValue].target
        local canAir = flag and Match.canAir(unit)
        if priority and not value and not target and not canAir and not Units.isFarm(idValue) and not Units.allyBuff(idValue) then
            local aiHandled = false
            if Config.aiTargeting ~= false and not nearBase then
                local prevList = aiPrevById[idValue]
                if not prevList then
                    prevList = {}
                    aiPrevById[idValue] = prevList
                end
                local okAi, aiStr, aiIdx, aiLogits = pcall(AI.pickTarget, unit, prevList)
                if okAi and type(aiStr) == "string" then
                    aiHandled = true
                    local chosenStr = aiStr
                    local chosenIdx = aiIdx or 0
                    if (priority.Value ~= chosenStr or chosenStr == "closest") and now - (Match.prioAt [unit] or 0) > 6 then
                        local okP, resP = pcall(Core.USC.get_valid_priorities, unit)
                        if okP and type(resP) == "table" then
                            if not aiHasPrio(resP, chosenStr) then
                                local bestAltStr, bestAltIdx, bestAltScore = "first", 0, -math.huge
                                if type(aiLogits) == "table" then
                                    for k = 1, 4 do
                                        local candStr = AI.TARGET_NAMES[k]
                                        local sc = tonumber(aiLogits[k])
                                        if candStr and sc and sc > bestAltScore and aiHasPrio(resP, candStr) then
                                            bestAltScore = sc
                                            bestAltStr = candStr
                                            bestAltIdx = k - 1
                                        end
                                    end
                                end
                                chosenStr = bestAltStr
                                chosenIdx = bestAltIdx
                            end
                            if priority.Value ~= chosenStr and aiHasPrio(resP, chosenStr) then
                                Match.prioAt [unit] = now
                                local okReq = App.request("prio", "change_priority", unit, chosenStr)
                                if okReq then
                                    App.status("Targeting", string.format("%s → %s (Neural AI)", Units.name(idValue), chosenStr))
                                    App.log(2, "TARGET", Units.name(idValue) .. " → " .. chosenStr .. " (Neural AI)")
                                    table.insert(prevList, chosenIdx)
                                else
                                    table.insert(prevList, AI.TARGET_TO_IDX[priority.Value] or 0)
                                end
                                changes = changes + 1
                                if changes >= 5 then return end
                            else
                                table.insert(prevList, AI.TARGET_TO_IDX[priority.Value] or chosenIdx)
                            end
                        else
                            table.insert(prevList, AI.TARGET_TO_IDX[priority.Value] or chosenIdx)
                        end
                    else
                        table.insert(prevList, AI.TARGET_TO_IDX[priority.Value] or chosenIdx)
                    end
                end
            end
            if not aiHandled then
                local primaryAttackValue = stats:FindFirstChild("primary_attack") and stats.primary_attack.Value or nil
                local attackInfo = Units.attackInfo(primaryAttackValue, stats.range.Value)
                local value = attackInfo.n <= 1.4 and attackInfo.slow == 0 and attackInfo.stun == 0
                local str = (value and hasBoss and not nearBase) and "strongest" or "first"
                if priority.Value ~= str and now - (Match.prioAt [unit] or 0) > 6 then
                    local ok, res = pcall(Core.USC.get_valid_priorities, unit)
                    if ok and type(res) == "table" and aiHasPrio(res, str) then
                        Match.prioAt [unit] = now
                        local ok = App.request("prio", "change_priority", unit, str)
                        if ok then
                            App.status("Targeting", string.format("%s → %s (%s)", Units.name(idValue), str, str == "strongest" and "boss on the road" or (nearBase and "defending base" or (value and "no boss now" or "holds the front"))))
                            App.log(2, "TARGET", Units.name(idValue) .. " → " .. str)
                        end
                        changes = changes + 1
                        if changes >= 5 then return end
                    end
                end
            end
        end
    end
end
Hunt.CARD_PICKS = {
    "Secret Luck",
    "Gems",
    "Easiest Win",
    "Smart"
}

function Hunt.cardLuck(value)
    local count = 0
    for _, effect in pairs(type(value) == "table" and type(value.effects) == "table" and value.effects or {
    }) do
        if type(effect) == "table" and effect.type == "secret_drop" then
            count = count + (tonumber(effect.amount) or 0)
        end
    end
    return count
end

-- Match titles, never the transient 1/2/3 option slots. Explicit id:/type:
-- tokens also work when a server supplies those stable fields.
function Hunt.cardToken(text)
    return (tostring(text or ""):gsub("^%s+", ""):gsub("%s+$", ""):gsub("%s+", " "):lower())
end

function Hunt.cardList(text)
    local ranks, count = {}, 0
    for token in tostring(text or ""):gmatch("[^,;\r\n]+") do
        token = Hunt.cardToken(token):gsub("^(%a+):%s+", "%1:")
        if token ~= "" and token ~= "id:" and token ~= "type:" and not ranks[token] then
            count = count + 1
            ranks[token] = count
        end
    end
    return ranks
end

-- "+ attack ii" -> "attack ii" (no sign) and "attack" (no tier).
function Hunt.cardNames(title)
    local full = Hunt.cardToken(title)
    local bare = full:gsub("^[%+%-%s]+", "")
    local base = bare:gsub("%s+[ivx]+$", "")
    return full, bare, base
end

function Hunt.cardRank(card, ranks)
    if type(card) ~= "table" then return nil end
    local full, bare, base = Hunt.cardNames(card.title)
    local rank = ranks[full] or ranks[bare] or ranks[base]
    for _, field in ipairs({ "id", "option_type" }) do
        local value = card[field]
        if type(value) == "string" or type(value) == "number" then
            local token = (field == "id" and "id:" or "type:") .. Hunt.cardToken(value)
            local found = ranks[token]
            if found and (not rank or found < rank) then rank = found end
        end
    end
    return rank
end

function Match.huntChoose(arg1, wave)
    if type(arg1) ~= "table" then
        arg1 = {
        }
    end
    Match.fhP = Match.fhP or 1
    local floor = Hunt.floor()
    local leak = (Match.pressure or 0) >= Config.safeReach or (Match.depth and Match.depth.leak)
    local weatherStrength = Hunt.weatherStrength(Hunt.weatherNow())
    local huntCards = table.find(Hunt.CARD_PICKS, Config.huntCards) and Config.huntCards or "Smart"
    local value, value2, value3, value4
    local allowed, allowedScore, allowedStrength, allowedGems, allowedRank
    local bannedCount, unsafeCount = 0, 0
    local notBanned, notBannedScore, notBannedStrength, notBannedGems
    local first = Hunt.cardList(Config.huntCardsFirst)
    local never = Hunt.cardList(Config.huntCardsNever)
    local list = {
    }
    local cardMeta = {
    }
    for key, value5 in pairs(arg1) do
        local num, list2 = 1, {
        }
        for _, effect in pairs(type(value5) == "table" and value5.effects or {
        }) do
            if type(effect) == "table" then
                local rogueEffect = Match.rogueEffect(effect)
                num = num * rogueEffect
                table.insert(list2, Match.effectText(effect))
            end
        end
        if type(value5) == "table" and value5.weather then
            num = num * Hunt.weatherStrength(value5.weather) / math.max(0.05, weatherStrength)
        end
        local cardGems = type(value5) == "table" and Hunt.cardGems(value5, wave) or 0
        local flag = num >= 1 or (Match.fhP * num >= floor and not leak)
        local log = math.log(math.max(0.05, num))
        local log2 = log * Hunt.STRENGTH_GEMS + (flag and cardGems or - 1000)
        local cardLuck = Hunt.cardLuck(value5)
        if huntCards == "Secret Luck" and flag and cardLuck > 0 then
            log2 = 2e6 + cardLuck * 1e4 + cardGems
        elseif huntCards == "Gems" and flag then
            log2 = 1e6 + cardGems + log
        elseif huntCards == "Easiest Win" then
            log2 = log * 1e6 + cardGems
        end
        if not value2 or log2 > value2 then
            value, value2, value3, value4 = key, log2, num, cardGems
        end
        local banned = Hunt.cardRank(value5, never) ~= nil
        local rank = Hunt.cardRank(value5, first)
        if not banned and (notBannedScore == nil or log2 > notBannedScore) then
            notBanned, notBannedScore, notBannedStrength, notBannedGems = key, log2, num, cardGems
        end
        if banned then
            bannedCount = bannedCount + 1
        elseif not flag then
            unsafeCount = unsafeCount + 1
        elseif allowed == nil or (rank and (not allowedRank or rank < allowedRank))
            or (rank == allowedRank and log2 > allowedScore) then
            allowed, allowedScore, allowedStrength, allowedGems, allowedRank = key, log2, num, cardGems, rank
        end
        cardMeta[key] = {
            strength = num,
            gems = cardGems,
            luck = cardLuck,
            safe = flag,
            banned = banned,
            rank = rank
        }
        local rule = banned and " / banned" or (not flag and " / unsafe" or (rank and (" / priority " .. rank) or ""))
        table.insert(list, string.format("%s) %s%s [%s] ×%.2f, %d gems: %s", tostring(key), tostring(type(value5) == "table" and value5.title or "?") .. rule, (type(value5) == "table" and value5.weather) and (" (" .. tostring(value5.weather) .. ")") or "", tostring(type(value5) == "table" and value5.option_type or "?"), num, math.floor(cardGems + 0.5), table.concat(list2, " + ")))
    end
    if allowed ~= nil then
        value, value3, value4 = allowed, allowedStrength, allowedGems
        if allowedRank then huntCards = "priority " .. allowedRank .. " / " .. huntCards end
    elseif notBanned ~= nil then
        value, value3, value4 = notBanned, notBannedStrength, notBannedGems
        if bannedCount > 0 then
            App.log(1, "ROGUE", string.format("No safe card outside Never Take (%d banned, %d unsafe): the best card you didn't ban", bannedCount, unsafeCount))
        else
            App.log(1, "ROGUE", string.format("All %d offered cards would take the team under its floor: the least harmful one", unsafeCount))
        end
        huntCards = huntCards .. " fallback"
    elseif value ~= nil then
        App.log(1, "ROGUE", string.format("Every offered card is on Never Take (%d): using %s to keep the run moving", bannedCount, huntCards))
        huntCards = huntCards .. " fallback"
    end
    if Config.aiCards ~= false and AI and AI.chooseRogueCard and next(arg1) ~= nil then
        local okCard, aiKey, aiScore, aiWhy = pcall(AI.chooseRogueCard, arg1, {
            mode = "event_50",
            isEvent = true,
            wave = wave,
            totalWaves = Match.total or 50,
            floor = floor,
            safetyFloor = floor,
            leak = leak,
            fhP = Match.fhP or 1,
            weather = Hunt.weatherNow(),
            huntCards = huntCards,
            meta = cardMeta
        })
        if okCard and aiKey ~= nil and arg1[aiKey] ~= nil and cardMeta[aiKey] ~= nil then
            local m = cardMeta[aiKey]
            local aiTitle = type(arg1[aiKey]) == "table" and tostring(arg1[aiKey].title or aiKey) or tostring(aiKey)
            value, value3, value4 = aiKey, m.strength, m.gems
            huntCards = "CardNN/" .. tostring(huntCards)
            App.log(1, "AI_CARD", string.format("w%d hunt pick=%s (%s) score=%.3f why=%s str=x%.2f gems=%d", tonumber(wave) or 0, tostring(aiKey), aiTitle, tonumber(aiScore) or 0, tostring(aiWhy or "nn"), tonumber(m.strength) or 1, math.floor((tonumber(m.gems) or 0) + 0.5)))
            if AI.recordCardPick then
                pcall(AI.recordCardPick, wave, aiTitle)
            end
        elseif not okCard then
            App.log(2, "AI_CARD", "Fallback to v2.34 hunt card picker (" .. tostring(aiKey) .. ")")
        end
    end
    return value, value3, value4, list, floor, leak, huntCards
end

function Match.huntPick(rogueOptions)
    local wave = Match.wave()
    local huntChoose, huntChoose2, huntChoose3, huntChoose4, huntChoose5, huntChoose6, huntChoose7 = Match.huntChoose(rogueOptions, wave)
    if huntChoose == nil then
        Match.rogueOptions = nil
        App.log(1, "ROGUE", "No cards were offered; waiting for the next offer")
        return false
    end
    Match.fhP = Match.fhP * (huntChoose2 or 1)
    Match.rogueOptions = nil
    local ok, res = pcall(HttpService.JSONEncode, HttpService, Hunt.plain(rogueOptions))
    if ok then
        Hunt.write("hunt_cards.txt", string.format("%s wave %d map %s weather %s: %s", os.date("%m-%d %H:%M"), wave, tostring(Match.ld.map), tostring(Hunt.weatherNow()), res))
    end
    local ok = App.request("rogue", "select_roguelike_option", huntChoose)
    local cardLuck = huntChoose and Hunt.cardLuck(rogueOptions [huntChoose]) or 0
    App.log(1, "ROGUE", string.format("wave %d · picked %s by %s (worth %d gems%s, strength now ×%.2f, floor ×%.2f%s) of: %s", wave, tostring(huntChoose), tostring(huntChoose7), math.floor((huntChoose3 or 0) + 0.5), cardLuck > 0 and string.format(", secret luck +%g", cardLuck) or "", Match.fhP, huntChoose5, huntChoose6 and ", under pressure" or "", table.concat(huntChoose4, " | ")))
    return ok
end

function Match.huntRecord(arg1, arg2, arg3, arg4)
    local ok, res = pcall(Hunt.starfallRecord)
    Match.starSummary = ok and res or nil
    local floor = Hunt.floor()
    Brain.hunt.pmin = Utils.clamp(floor + (arg3 and - 0.1 or 0.1), 0.4, 2)
    Brain.hunt.runs = Brain.hunt.runs or {
    }
    table.insert(Brain.hunt.runs, 1, {
        at = os.time(),
        wave = Match.wave(),
        won = arg3 or nil,
        pearls = arg2,
        mult = Match.fhMult or 1,
        strength = Match.fhP or 1,
        floor = floor,
        map = Match.ld.map,
        weather = Hunt.weatherNow(),
        sec = arg4,
        picks = Match.fhPicks
    })
    while # Brain.hunt.runs > 20 do
        table.remove(Brain.hunt.runs)
    end
    local board = Hunt.board()
    App.log(1, "HUNT", string.format("%s at wave %d in %.0f min: +%d Summer Pearls at ×%.2f · map %s, weather %s%s", arg3 and "won" or "lost", Match.wave(), (tonumber(arg4) or 0) / 60, arg2, Match.fhMult or 1, tostring(Match.ld.map), tostring(Hunt.weatherNow()), board and string.format(" · bingo %d of %d squares", board.squares, # board.board) or ""))
    local list = {
    }
    for _, value in ipairs({
        "victory",
        "resource_reward",
        "gem_reward",
        "new_items",
        "new_units",
        "waves_completed",
        "first_completion_gems",
        "party_bonus"
    }) do
        if type(arg1) == "table" then
            list [value] = arg1 [value]
        end
    end
    local list2 = {
    }
    for key in pairs(type(arg1) == "table" and arg1 or {
    }) do
        table.insert(list2, tostring(key))
    end
    table.sort(list2)
    local ok, res = pcall(HttpService.JSONEncode, HttpService, Hunt.plain(list))
    if ok then
        Hunt.write("hunt_results.txt", os.date("%m-%d %H:%M ") .. res .. " · fields: " .. table.concat(list2, ", "))
    end
end

function Match.pickRogue()
    local rogueOptions = Match.rogueOptions
    if rogueOptions and Match.hunt then
        return Match.huntPick(rogueOptions)
    end
    if not rogueOptions then
        local ok = App.request("rogue", "select_roguelike_option", 1)
        return ok
    end
    Match.fhP = Match.fhP or 1
    local pmin = tonumber(Brain.fh.pmin) or 1
    local leak = (Match.pressure or 0) >= Config.safeReach or (Match.depth and Match.depth.leak)
    local value, value2, value3
    local cardMeta = {
    }
    for rogueOptionKey, rogueOption in pairs(rogueOptions) do
        local num, count = 1, 0
        for _, effect in pairs(type(rogueOption) == "table" and rogueOption.effects or {
        }) do
            if type(effect) == "table" then
                local rogueEffect, rogueEffect2 = Match.rogueEffect(effect)
                num = num * rogueEffect
                count = count + rogueEffect2
            end
        end
        local log = math.log(math.max(0.05, num)) * 10
        if count > 0 and Match.fhP * num >= pmin and not leak then
            log = log + 100 * count
        elseif count > 0 then
            log = log - 50 + count
        end
        cardMeta[rogueOptionKey] = {
            strength = num,
            gems = count * 100,
            luck = 0,
            safe = (num >= 1 or (Match.fhP * num >= pmin and not leak)),
            banned = false,
            rank = 0
        }
        if not value2 or log > value2 then
            value, value2, value3 = rogueOptionKey, log, num
        end
    end
    if Config.aiCards ~= false and AI and AI.chooseRogueCard and next(rogueOptions) ~= nil then
        local curW = Match.wave()
        local isDng = (Match.kind == "dungeon")
        local okCard, aiKey, aiScore, aiWhy = pcall(AI.chooseRogueCard, rogueOptions, {
            mode = isDng and "dungeon_15" or "event_50",
            isEvent = not isDng,
            wave = curW,
            totalWaves = Match.total or (isDng and 15 or 50),
            floor = pmin,
            safetyFloor = pmin,
            leak = leak,
            fhP = Match.fhP or 1,
            meta = cardMeta
        })
        if okCard and aiKey ~= nil and rogueOptions[aiKey] ~= nil and cardMeta[aiKey] ~= nil then
            value = aiKey
            value2 = tonumber(aiScore) or value2
            value3 = cardMeta[aiKey].strength
            local aiTitle = type(rogueOptions[aiKey]) == "table" and tostring(rogueOptions[aiKey].title or aiKey) or tostring(aiKey)
            App.log(1, "AI_CARD", string.format("w%d rogue pick=%s (%s) score=%.3f why=%s str=x%.2f", curW, tostring(aiKey), aiTitle, tonumber(aiScore) or 0, tostring(aiWhy or "nn"), tonumber(value3) or 1))
            if AI.recordCardPick then
                pcall(AI.recordCardPick, curW, aiTitle)
            end
        elseif not okCard then
            App.log(2, "AI_CARD", "Fallback to v2.34 rogue card picker (" .. tostring(aiKey) .. ")")
        end
    end
    Match.fhP = Match.fhP * (value3 or 1)
    local list = {
    }
    for rogueOptionKey, rogueOption in pairs(rogueOptions) do
        local list2 = {
        }
        for _, effect in pairs(type(rogueOption) == "table" and rogueOption.effects or {
        }) do
            if type(effect) == "table" then
                table.insert(list2, Match.effectText(effect))
            end
        end
        table.insert(list, tostring(rogueOptionKey) .. ") " .. table.concat(list2, " + "))
    end
    Match.rogueOptions = nil
    local ok = App.request("rogue", "select_roguelike_option", value)
    App.log(1, "ROGUE", string.format("wave %d · picked %s (score %.1f, strength now ×%.2f, floor ×%.2f) of: %s", Match.wave(), tostring(value), value2 or 0, Match.fhP, pmin, table.concat(list, " | ")))
    return ok
end

function Match.rogueShare(damageType)
    if not damageType then
        return 0.5
    end
    local replaced = tostring(damageType):gsub("_damage$", "")
    local count, count2 = 0, 0
    for _, unit in ipairs(Match.mine or {
    }) do
        local idValue = unit._stats.id.Value
        if not Units.isFarm(idValue) then
            local ok, res = pcall(Match.liveDps, unit, idValue)
            res = ok and res or 0
            local types = Units.types(idValue)
            count = count + res
            if types [replaced] or types [replaced .. "_damage"] then
                count2 = count2 + res
            end
        end
    end
    local count3 = 0
    for _, unit in ipairs(Match.mine or {
    }) do
        if not Units.isFarm(unit._stats.id.Value) then
            count3 = count3 + 1
        end
    end
    local ratio = count3 / (count3 + 4)
    return ratio * (count > 0 and count2 / count or 0.5) + (1 - ratio) * 0.5
end

function Match.resistOf(id)
    local types = Units.types(id)
    local count = 0
    for key, value in pairs(Match.fhResist or {
    }) do
        local replaced = tostring(key):gsub("_damage$", "")
        if types [replaced] or types [replaced .. "_damage"] then
            count = math.max(count, value / 100)
        end
    end
    return math.min(0.95, count)
end

function Match.rogueEffect(effect)
    local value, amount, stat = effect.type, tonumber(effect.amount) or 0, tostring(effect.stat or "")
    if value == "candy_multiplier" then
        return 1, math.abs(amount)
    end
    if value == "stat_mul" or value == "stat_add" or value == "stat_attr_add" then
        if stat == "damage" then
            return math.max(0.3, 1 + amount), 0
        end
        if stat == "range" then
            return math.max(0.5, 1 + amount / 2), 0
        end
        if stat:find("cooldown") then
            return 1 / math.max(0.3, 1 + amount), 0
        end
        return 1, 0
    end
    if value == "stat_mul_real" then
        if stat == "damage" then
            return math.max(0.3, amount), 0
        end
        if stat == "range" then
            return math.max(0.5, 1 + (amount - 1) / 2), 0
        end
        if stat:find("cooldown") then
            return 1 / math.max(0.3, amount), 0
        end
        return 1, 0
    end
    if value == "boss_damage" then
        return 1 + amount / 3, 0
    end
    if value == "enemy_stat_mul" then
        return 1 / math.max(0.3, 1 + amount), 0
    end
    if value == "enemy_resistance_specific" then
        return math.max(0.2, 1 - Match.rogueShare(effect.damage_type) * (1 - 100 / (100 + amount))), 0
    end
    if value == "enemy_amp_specific" then
        return 1 + Match.rogueShare(effect.damage_type) * amount, 0
    end
    if value == "weather_flying_chance" then
        return math.max(0.5, 1 - amount * 0.5), 0
    end
    if value == "weather_soaring_share" then
        return math.max(0.5, 1 - amount * 0.2), 0
    end
    if value == "flying_damage" then
        return 1 + amount * 0.1, 0
    end
    if value == "burst_speed" then
        return 1 / math.max(0.3, 1 + amount * 0.5), 0
    end
    if value == "lightning_strikes" then
        return math.max(0.5, 1 - amount * 0.1), 0
    end
    if value == "enemy_speedup" then
        return 1 / math.max(0.3, 1 + amount), 0
    end
    if value == "enemy_regen" then
        return math.max(0.3, 1 - amount * 20), 0
    end
    if value == "enemy_shield" then
        return math.max(0.5, 1 - amount * 0.03), 0
    end
    if value == "enemy_bomb" then
        return 0.95, 0
    end
    if value == "enemy_passive_chance" then
        return math.max(0.5, 1 - amount), 0
    end
    if value == "resource_gain" then
        return 1 + math.min(0.3, amount / 40000), 0
    end
    if value == "unit_cost" then
        return 1 / math.max(0.3, 1 + amount / 2), 0
    end
    if value == "new_path" then
        return 0.8, 0
    end
    if value == "random_effects" then
        local value = math.max(1, math.abs(amount)) * math.max(1, math.abs(tonumber(effect.tier) or 1))
        return effect._type == "Good" and 1.1 ^ value or 0.8 ^ value, 0
    end
    return 1, 0
end

function Match.effectText(effect)
    return string.format("%s%s %s", tostring(effect.type), effect.stat and ("." .. tostring(effect.stat)) or "", tostring(effect.amount))
end

-- A unit's share of the real damage is compared with its share of the damage it could deal. Since
-- 2.21 "could deal" is summed second by second over the match while the unit stood and had a target
-- (Match.measure, calRun.potBy): a unit placed or upgraded late is no longer judged as if it had
-- fought the whole match at its final level. Without that record, the old end-of-match snapshot.
function Match.learn()
    local list, list2 = {
    }, {
    }
    local count, count2 = 0, 0
    local potBy = Match.calRun and Match.calRun.potBy
    local timed = false
    for _, value in pairs(potBy or {
    }) do
        timed = timed or value > 0
    end
    for _, unit in ipairs(Match.mine) do
        local stats = unit._stats
        local idValue = stats.id.Value
        local totalDamageValue = stats:FindFirstChild("total_damage") and stats.total_damage.Value or 0
        if not Units.isFarm(idValue) then
            list [idValue] = (list [idValue] or 0) + totalDamageValue
            if timed then
                list2 [idValue] = potBy [idValue] or 0
            else
                list2 [idValue] = (list2 [idValue] or 0) + Match.liveDps(unit, idValue) / math.max(0.5, Units.nudge(idValue))
                local mark = Units.passive(idValue).mark
                if mark then
                    list2 [idValue] = list2 [idValue] + mark.dot * stats.damage.Value
                end
            end
            count = count + totalDamageValue
        end
    end
    for _, item in pairs(list2) do
        count2 = count2 + item
    end
    if count <= 0 or count2 <= 0 then
        return
    end
    Match.lastEff = {
    }
    for itemKey, item in pairs(list) do
        local ratio, ratio2 = item / count, list2 [itemKey] / count2
        if ratio2 > 0.02 then
            local value = Brain.learn [itemKey] or {
                eff = 1,
                n = 0
            }
            local value2 = math.max(0.02, 0.25 * math.sqrt(30 / (30 + value.n)))
            local clamp = Utils.clamp(ratio / ratio2, 0.3, 3)
            Match.lastEff [itemKey] = math.floor(clamp * 1000 + 0.5) / 1000
            value.eff = value.eff + (clamp - value.eff) * value2
            value.n = value.n + 1
            Brain.learn [itemKey] = value
        end
    end
end

function Match.randomTeam()
    local session = Core.session()
    local temporaryUnits = session and session.collection.temporary_units or {
    }
    local list, list2 = {
    }, {
    }
    local function helper(arg1, arg2, arg3)
        local temporaryUnit = arg1 and temporaryUnits [arg1]
        if temporaryUnit and Core.Units [temporaryUnit.unit_id] and not list2 [arg1] then
            list2 [arg1] = true
            table.insert(list, {
                slot = arg3 or 99,
                uuid = arg1,
                u = temporaryUnit,
                id = temporaryUnit.unit_id,
                data = Core.Units [temporaryUnit.unit_id],
                hand = arg2
            })
        end
    end
    for overrideEquippedUnitKey, overrideEquippedUnit in pairs(session and session.override_equipped_units or {
    }) do
        helper(overrideEquippedUnit, true, tonumber(overrideEquippedUnitKey))
    end
    for _, unit in ipairs(Match.mine or {
    }) do
        local stats = unit._stats
        helper(stats:FindFirstChild("uuid") and stats.uuid.Value, false)
    end
    table.sort(list, function(arg1, arg2)
        return arg1.slot < arg2.slot
    end)
    return list
end

function Match.fhSnap()
    local health, maxHealth = nil, nil
    pcall(function()
        for _, desc in ipairs(workspace._BASES:GetDescendants()) do
            if desc:IsA("Humanoid") then
                health, maxHealth = desc.Health, desc.MaxHealth
                break
            end
        end
    end)
    local ratio = health and maxHealth and maxHealth > 0 and math.floor(health / maxHealth * 100) or - 1
    local count, list, list2 = 0, {
    }, {
    }
    for _, enemy in ipairs(Match.enemies or {
    }) do
        if (enemy.prog or 0) > 0.8 then
            count = count + 1
            list [tostring(enemy.m)] = (list [tostring(enemy.m)] or 0) + 1
        end
        list2 [tostring(enemy.m)] = (list2 [tostring(enemy.m)] or 0) + 1
    end
    if not next(list) then
        list = list2
    end
    local count2 = 0
    for _, unit in ipairs(Match.mine or {
    }) do
        local ok, res = pcall(Match.liveDps, unit, unit._stats.id.Value)
        if ok and res then
            count2 = count2 + res
        end
    end
    Match.fhWaves = Match.fhWaves or {
    }
    local count3 = 0
    for _, enemy in ipairs(Match.enemies or {
    }) do
        if enemy.fly then
            count3 = count3 + 1
        end
    end
    table.insert(Match.fhWaves, string.format("%d:%d:%d:%d:%s:%d:%.2f:%s:air%d%%:fly%d", Match.wave(), ratio, # (Match.enemies or {
    }), count, Utils.fmt(count2), Match.fieldCount(), Match.fhMult or 1, Utils.fmt(Match.money()), math.floor(Match.airShare() * 100 + 0.5), count3))
    if ratio >= 0 and Match.fhLastPct and ratio < Match.fhLastPct and not Match.fhLeak then
        local list2 = {
        }
        for itemKey, item in pairs(list) do
            table.insert(list2, Units.name(itemKey) .. "×" .. item)
        end
        Match.fhLeak = string.format("wave %d: base %d%% → %d%%, near it: %s", Match.wave(), Match.fhLastPct, ratio, # list2 > 0 and table.concat(list2, ", ") or "nothing seen")
        App.log(1, "MATCH", "first damage to the base — " .. Match.fhLeak)
    end
    Match.fhLastPct = ratio
end

function Match.fhRecord(arg1, arg2)
    local list, count = {
    }, 0
    for _, unit in ipairs(Match.mine or {
    }) do
        local stats = unit._stats
        local totalDamageValue = stats:FindFirstChild("total_damage") and tonumber(stats.total_damage.Value) or 0
        local idValue = stats.id.Value
        if totalDamageValue > 0 then
            list [idValue] = (list [idValue] or 0) + totalDamageValue
            count = count + totalDamageValue
        end
    end
    local list2 = {
    }
    for itemKey, item in pairs(list) do
        local ratio = count > 0 and item / count or 0
        local unit = Brain.fh.units [itemKey] or {
            n = 0,
            share = 0
        }
        unit.share = (unit.share * unit.n + ratio) / (unit.n + 1)
        unit.n = unit.n + 1
        Brain.fh.units [itemKey] = unit
        table.insert(list2, {
            id = itemKey,
            share = ratio
        })
    end
    table.sort(list2, function(arg1, arg2)
        return arg1.share > arg2.share
    end)
    local list = {
    }
    for i = 1, math.min(4, # list2) do
        table.insert(list, string.format("%s %d%%", Units.name(list2 [i].id), math.floor(list2 [i].share * 100 + 0.5)))
    end
    pcall(Match.fhSnap)
    local pmin = tonumber(Brain.fh.pmin) or 1
    Brain.fh.pmin = Utils.clamp(pmin * (arg2 and 0.9 or 1.1), 0.5, 2.5)
    table.insert(Brain.fh.runs, 1, {
        at = os.time(),
        wave = Match.wave(),
        won = arg2 or nil,
        coins = arg1,
        top = list,
        mult = Match.fhMult or 1,
        discards = Match.discards,
        strength = Match.fhP,
        floor = pmin,
        effects = Match.fhEffects,
        picks = Match.fhPicks,
        leak = Match.fhLeak,
        waves = Match.fhWaves
    })
    while # Brain.fh.runs > 20 do
        table.remove(Brain.fh.runs)
    end
    App.log(1, "RESULT", string.format("dealt team reached wave %d; most damage: %s", Match.wave(), table.concat(list, ", ")))
end

function Match.carry(id)
    local unit = Brain.fh.units [id]
    return unit and unit.n > 0 and unit.share or 0
end

function Match.fhText()
    local runs = Brain.fh.runs
    if # runs == 0 then
        return "No Fool's Hunt run recorded yet."
    end
    local count, count2 = 0, 0
    for _, run in ipairs(runs) do
        count = count + (run.wave or 0)
        count2 = count2 + (run.coins or 0)
    end
    local list = {
    }
    for unitKey, unit in pairs(Brain.fh.units) do
        if unit.n >= 2 then
            table.insert(list, {
                id = unitKey,
                share = unit.share,
                n = unit.n
            })
        end
    end
    table.sort(list, function(arg1, arg2)
        return arg1.share > arg2.share
    end)
    local list2 = {
    }
    for i = 1, math.min(6, # list) do
        table.insert(list2, string.format("%s %d%% (%d runs)", Units.name(list [i].id), math.floor(list [i].share * 100 + 0.5), list [i].n))
    end
    local count3 = 0
    for _ in pairs(Brain.unitData) do
        count3 = count3 + 1
    end
    local count4 = 0
    for _, run in ipairs(runs) do
        if run.won then
            count4 = count4 + 1
        end
    end
    local run = runs [1]
    local merge, idol = Brain.fh.merge, Brain.fh.idol
    local str = ""
    if merge and merge.n > 0 then
        str = str .. string.format("\nMerges cast: %d, each gave %.0f%% of what the game's description promises.", merge.n, merge.ratio / merge.n * 100)
    end
    if idol and idol.n > 0 then
        str = str .. string.format("\nIdol: each upgrade adds %.1f%% damage and makes upgrades %.1f%% cheaper (measured %d times).", idol.dmg / idol.n * 100, idol.cost / idol.n * 100, idol.n)
    end
    local clone, ritual = Brain.fh.clone, Brain.fh.ritual
    if clone and clone.n > 0 then
        str = str .. string.format("\nClones: %d made, each with %.0f%% of the original's damage and %.0f%% of the yen in it.", clone.n, clone.ratio / clone.n * 100, clone.spent / clone.n * 100)
    end
    if ritual and ritual.n > 0 then
        str = str .. string.format("\nRitual: %d cast, the Divine General came out at %.1f× the sacrificed unit's damage.", ritual.n, ritual.ratio / ritual.n)
    end
    local farmMerge = Brain.fh.farmMerge
    if farmMerge and farmMerge.n > 0 then
        str = str .. string.format("\nFarm merges: %d tested, each kept %.0f%% of 1.5× the income it took in.", farmMerge.n, farmMerge.ratio / farmMerge.n * 100)
    end
    return string.format("Fool's Hunt: %d runs recorded (%d won), wave %.0f and %d AprilCoins a run on average. Last run: wave %s, coin multiplier ×%.2f, team strength ×%.2f%s; most damage: %s.\n" .. "Coin-multiplier picks need team strength ×%.2f or more (it goes up after a lost run, down after a won one, until it wins with the highest multiplier).\n" .. "Dealt units that carry (average share of the damage): %s.\nHidden unit stats learned so far: %d units.%s", # runs, count4, count / # runs, math.floor(count2 / # runs + 0.5), tostring(run.wave), tonumber(run.mult) or 1, tonumber(run.strength) or 1, run.leak and (" · first base hit: " .. run.leak) or "", table.concat(run.top or {
    }, ", "), tonumber(Brain.fh.pmin) or 1, # list2 > 0 and table.concat(list2, " · ") or "needs 2 runs with a unit", count3, str)
end

function Match.cardDps(member)
    local ok, res = pcall(Units.dps, member.u, 0, Match.mod)
    res = ok and tonumber(res) or 0
    if res > 0 or Units.isFarm(member.id) or Units.idol(member.id) or Units.allyBuff(member.id) then
        return res
    end
    local cardVals = table.clone(Match.cardVals or {
    })
    if # cardVals == 0 then
        return 1000
    end
    table.sort(cardVals)
    return cardVals [math.max(1, math.ceil(# cardVals * 0.6))]
end

function Match.cardValue(member)
    if Units.isFarm(member.id) then
        return 0
    end
    if Units.idol(member.id) then
        return (Match.teamDps or 0) * Match.idolStep() * 3
    end
    local buffGain = Units.allyBuff(member.id) and Match.buffGain(member) or Match.cardDps(member)
    return buffGain * (1 + 2 * Match.carry(member.id)) * (1 - Match.resistOf(member.id)) * Match.airNeed(member.id) * (Match.mergeIds [member.id] and 2 or 1)
end

function Match.flyMode()
    if Match.random or Match.flyerSeen then
        return true
    end
    if Match.kind == "dungeon" then
        if Match._curseFly == nil then
            local ok, res = pcall(Dungeon.items, Dungeon.data())
            Match._curseFly = ok and (res._curse_fly or 0) > 0 or false
        end
        return Match._curseFly
    end
    return false
end

function Match.shieldNow()
    local wave = Match.wave()
    if Match._shieldW ~= wave then
        Match._shieldW, Match._shieldS, Match._shieldH = wave, 0, 1
        local ok, res = pcall(Simulator.wave, Match.info, math.max(1, wave), true)
        if Match.info and ok and # res > 0 then
            local count, count2 = 0, 0
            for _, value in ipairs(res) do
                count, count2 = count + (value.sh or 0), count2 + value.hp
            end
            Match._shieldS, Match._shieldH = count / # res, count2 / # res
        end
    end
    return Match._shieldS, Match._shieldH
end

function Match.shieldOf(cardDps, row)
    local shieldNow, shieldNow2 = Match.shieldNow()
    if shieldNow <= 0 or not row then
        return cardDps
    end
    local attackInfo = Units.attackInfo(row.atk, row.range)
    return Economy.shieldDps(cardDps, tonumber(row.cd) or 2, attackInfo.n, shieldNow, shieldNow2, Match.info and Match.info.eff, attackInfo.hits)
end

function Match.shieldWork(id, row)
    local shieldNow, shieldNow2 = Match.shieldNow()
    if shieldNow <= 0 or not row or not Match.info then
        return 0
    end
    local count, count2 = 0, 0
    for _, member in ipairs(Match.team or {
    }) do
        local rows = Units.rows(member.id)
        rows = rows and rows [0]
        if rows and not Units.isFarm(member.id) then
            count = math.max(count, Units.dps(member.u, 0, Match.mod) * (tonumber(rows.cd) or 2) / math.max(1, Units.attackInfo(rows.atk, rows.range).n))
        end
    end
    for _, unit in ipairs(Match.mine or {
    }) do
        local idValue = unit._stats.id.Value
        local rows = Units.rows(idValue)
        local row = rows and rows [unit._stats.upgrade and unit._stats.upgrade.Value or 0]
        if row and not Units.isFarm(idValue) and not Units.allyBuff(idValue) then
            local attackInfo = Units.attackInfo(row.atk, row.range)
            count2 = count2 + attackInfo.n * attackInfo.hits / math.max(0.3, tonumber(row.cd) or 2)
        end
    end
    local ok, res = pcall(Simulator.wave, Match.info, math.max(1, Match.wave()), true)
    local attackInfo = Units.attackInfo(row.atk, row.range)
    return Economy.shieldWork(attackInfo.n, tonumber(row.cd) or 2, count2, shieldNow, ok and # res or 1, Match.info.waveSec, count * (Match.info.eff or 1), shieldNow2, attackInfo.hits)
end

function Match.teamShield()
    if Match._shieldAt and Utils.now() - Match._shieldAt < 2 then
        return Match._shieldTeam
    end
    local count, count2 = 0, 0
    for _, unit in ipairs(Match.mine or {
    }) do
        local idValue = unit._stats.id.Value
        if not Units.isFarm(idValue) and unit._stats:FindFirstChild("upgrade") then
            local rows = Units.rows(idValue)
            local ok, res = pcall(Match.liveDps, unit, idValue)
            if ok and rows then
                count = count + res
                count2 = count2 + Match.shieldOf(res, rows [unit._stats.upgrade.Value])
            end
        end
    end
    Match._shieldTeam, Match._shieldAt = count > 0 and math.max(0.05, count2 / count) or 1, Utils.now()
    return Match._shieldTeam
end

function Match.airLow()
    if not Match.flyMode() then
        return false
    end
    if FarmHub.every("airShare", 1) or not Match.airShareNow then
        Match.airShareNow = Match.airShare()
    end
    return Match.airShareNow < 0.5
end

function Match.airWeight(arg1)
    if not (arg1 and Match.flyMode()) then
        return 1
    end
    return Match.airLow() and 2.5 or 1.5
end

-- Road a placed unit would reach with a given range, for judging range upgrades (cached 5 s).
Match.reachOfCache = setmetatable({
}, {
    __mode = "k"
})

function Match.reachOf(m)
    local ok, pos = pcall(function()
        return m:GetPivot().Position
    end)
    if not ok or not pos or not Match.samples or # Match.samples == 0 then
        return nil
    end
    local scale = (Match.info and tonumber(Match.info.rangeScale)) or 1
    return function(range)
        local key = math.floor(range * scale * 2 + 0.5)
        local byUnit = Match.reachOfCache [m]
        if not byUnit or Utils.now() - byUnit.t > 5 then
            byUnit = {
                t = Utils.now()
            }
            Match.reachOfCache [m] = byUnit
        end
        if byUnit [key] == nil then
            byUnit [key] = Match.cover(pos, range * scale)
        end
        return byUnit [key]
    end
end

function Match.reach(m)
    if not Match.reachAt or Utils.now() - Match.reachAt > 5 then
        local count, count2 = 0, 0
        for _, unit in ipairs(Match.mine or {
        }) do
            local stats = unit._stats
            if not Units.isFarm(stats.id.Value) and stats:FindFirstChild("range") then
                count, count2 = count + Match.cover(unit:GetPivot().Position, stats.range.Value), count2 + 1
            end
        end
        Match.reachAvg, Match.reachAt = count2 > 0 and count / count2 or 0, Utils.now()
    end
    local stats = m._stats
    if (Match.reachAvg or 0) <= 0 or not stats:FindFirstChild("range") then
        return 1
    end
    local value = Match.reachCache [m]
    if value and Utils.now() - value.t < 5 then
        return value.v
    end
    local clamp = Utils.clamp(Match.cover(m:GetPivot().Position, stats.range.Value) / Match.reachAvg, 0.4, 1.6)
    Match.reachCache [m] = {
        v = clamp,
        t = Utils.now()
    }
    return clamp
end
Match.reachCache = setmetatable({
}, {
    __mode = "k"
})

function Match.airNeed(id)
    local airFrom = Units.airFrom(id)
    if airFrom == 0 then
        return Match.airWeight(true)
    end
    if airFrom then
        return 1 + (Match.airWeight(true) - 1) * 0.4
    end
    return 1
end

function Match.airBoost(m)
    if Match.canAir(m) then
        return Match.airWeight(true)
    end
    local airFrom = Units.airFrom(m._stats.id.Value)
    if not airFrom then
        return 1
    end
    return 1 + (Match.airWeight(true) - 1) * math.min(1, (m._stats.upgrade.Value + 1) / math.max(1, airFrom))
end
Match.cardSeen, Match.cardVals = {
}, {
}

function Match.fish()
    if not Match.random then
        return
    end
    local list = {
    }
    for _, member in ipairs(Match.team) do
        if member.hand then
            table.insert(list, member)
            if not Match.cardSeen [member.uuid] then
                Match.cardSeen [member.uuid] = Utils.now()
                if not Units.isFarm(member.id) and not Units.idol(member.id) then
                    table.insert(Match.cardVals, Match.cardValue(member))
                end
            end
        end
    end
    if # Match.cardVals < 8 or not FarmHub.every("fish", 5) then
        return
    end
    local cardVals = table.clone(Match.cardVals)
    table.sort(cardVals)
    local cardVal = cardVals [math.max(1, math.ceil(# cardVals * 0.6))]
    local count = 0
    for _, unit in ipairs(Match.mine or {
    }) do
        if Units.isFarm(unit._stats.id.Value) then
            count = count + 1
        end
    end
    local flag = Match.fieldCount() < 16
    local flag2 = false
    for _, item in ipairs(list) do
        local flag3 = Units.isFarm(item.id) and Match.wave() < 12 and count < 3 and not flag2
        if flag3 then
            flag2 = true
        end
        local value = Match.roomPlan and Match.roomPlan.name == Units.name(item.id)
        local flag2 = (Match.noSpot [item.uuid] or 0) >= 3
        local idol = not flag2 and (flag3 or value or Units.idol(item.id) or Match.mergeIds [item.id])
        local flag3 = Utils.now() - (tonumber(Match.cardSeen [item.uuid]) or Utils.now()) > 60
        if flag2 or (not idol and Match.cardValue(item) < cardVal * ((flag and not flag3) and 0.25 or 1)) then
            if Match.discardCard(item) then
                App.log(2, "PLACE", string.format("discarded %s (%s) for a new card", Units.name(item.id), flag2 and "no spot it fits" or ("worth " .. Utils.fmt(Match.cardValue(item)) .. ", the bar is " .. Utils.fmt(cardVal))))
                Match.discards = (Match.discards or 0) + 1
            end
            return
        end
    end
end

function Match.discardCard(item)
    local slot = tostring(item.slot)
    local overrideEquippedUnits = Core.session().override_equipped_units or {
    }
    if overrideEquippedUnits [slot] ~= item.uuid then
        return false
    end
    if not App.request("discard", "delete_ingame_temporary_unit", slot) then
        return false
    end
    task.wait(0.3)
    local flag = (Core.session().override_equipped_units or {
    }) [slot] ~= item.uuid
    if not flag and FarmHub.every("discardFail", 30) then
        App.log(1, "PLACE", "the game didn't take the discard of " .. Units.name(item.id))
    end
    return flag
end

function Match.watchLine()
    local session = Core.session()
    local list, list2 = {
    }, {
    }
    for _, member in ipairs(Match.team or {
    }) do
        if member.hand then
            table.insert(list, Units.name(member.id) .. " " .. Utils.fmt(Match.cardValue(member)))
            table.insert(list2, member.uuid)
        end
    end
    local list3 = {
    }
    for _, ingameSpell in pairs((session and session.ingame_spells) or {
    }) do
        table.insert(list3, Match.SPELL_NAMES [ingameSpell] or tostring(ingameSpell))
    end
    local joined = table.concat(list2, ",")
    if joined ~= Match.handKey then
        Match.handKey, Match.handSince = joined, Utils.now()
    end
    local value = # list2 > 0 and Utils.now() - Match.handSince >= 90
    App.log(1, "WATCH", string.format("wave %d · %d/%d units · ¥%s · hand: %s%s · merge: %s%s · economy: %s%s", Match.wave(), Match.fieldCount(), Match.FIELD_MAX, Utils.fmt(Match.money()), # list > 0 and table.concat(list, ", ") or "no unit cards", # list3 > 0 and (" + " .. table.concat(list3, ", ")) or "", tostring(Status.Merge or "-"), Match.cloneNote and (" · clone: " .. Match.cloneNote) or "", tostring(Status.Economy or "-"), value and " · HAND STUCK 90s+" or ""))
end
