            App.log(1, role and "STUDY" or "TRIAL", string.format("%s %d of %d: %s%s", role and "study run" or "trial", tonumber(trial.i) or 1, # trial.list, Units.name(item), Match.studyTeam and " plays with the whole team fighting" or " gets the yen, the rest of the team stands by") .. (Match.studyEntry and ", at the road's entrance" or ""))
        end
    end
    Match.xp0 = {
    }
    for _, member in ipairs(Match.team) do
