            Match.xp0 [member.uuid] = tonumber(member.u.xp) or 0
        end
    end
    pcall(Units.capture)
    task.delay(15, function()
        local ok, res = pcall(Units.capture)
        if not ok then
            App.log(1, "ERROR", "unit stats: " .. tostring(res))
        end
    end)
    Match.trainee, Match.trainTk = nil, 0
    for _, member in ipairs(Match.team) do
        if Brain.train.on and member.uuid == Brain.train.on.uuid then
            Match.trainee = member.uuid
        end
    end
    local challenge = Match.ld._challenge or (Match.key == "dc" and Match.rotation and Brain.live.daily and Brain.live.daily.challenge) or nil
    Match.challenge = challenge
    Match.teamProfile, Match.teamUuids = Modes.equippedProfile(), Training.team()
    Match.calRun = {
        waveSec = {
        },
        walk = {
        },
        hp = {
        },
        baseRel = {
        },
        alive = {
        },
        spawn = {
        },
        spawnLast = {
        },
        dpsAt = {
        },
        dens = {
        },
        pay = {
        },
        skip = {
        },
        timer = {
        },
        votes = {
        }
    }
    Match.track = setmetatable({
    }, {
        __mode = "k"
    })
    local ok, res = pcall(Simulator.info, Simulator.slim(Match.ld), Match.key, challenge, Match.mod, Match.rotation)
    Match.info = ok and res or nil
    if not ok then
        App.log(1, "ERROR", "sim info: " .. tostring(res))
    end
    if Match.info and Match.info.mapMods then
        local ok, res = pcall(Match.watchMods)
        if not ok then
            App.log(1, "ERROR", "enemy types: " .. tostring(res))
        end
    end
    if Match.info and Match.kind == "dungeon" then
        local ok, res = pcall(Dungeon.fx, Dungeon.data())
        if ok then
            Simulator.applyFx(Match.info, res)
            local list = {
            }
            for key, value in pairs(Match.mod and Match.mod.weak or {
            }) do
                table.insert(list, string.format("%s ×%.2f", tostring(key):gsub("_damage", ""), value))
            end
