        end
    end
    if Match.info and Match.trialId then
        task.spawn(function()
            local list = {
            }
            for _, member in ipairs(Match.team) do
                if member.id == Match.trialId or Units.isFarm(member.id) or Units.allyBuff(member.id) then
                    table.insert(list, member.u)
