}

function Reports.settingsOf()
    local list, count = {
    }, 0
    for defaultKey, default in pairs(Core.DEFAULTS) do
        local value = Config [defaultKey]
        local kind = type(value)
        local flag = kind == "boolean" or kind == "number" or (kind == "string" and # value <= 24 and not value:find("[{}%-]") and not tostring(defaultKey):lower():find("unit"))
        if value ~= default and flag and not Reports.SETTINGS_SKIP [defaultKey] and not tostring(defaultKey):find("At$") and not tostring(defaultKey):find("Sig$") then
            list [defaultKey] = kind == "number" and math.floor(value * 100 + 0.5) / 100 or value
            count = count + 1
        end
    end
    return count > 0 and list or nil
end

function Reports.searchOf(arg1)
    local simResult = Brain.simTeam [arg1]
    if type(simResult) ~= "table" or type(simResult.ids) ~= "table" or os.time() - (tonumber(simResult.at) or 0) > 7200 then
        return nil
    end
    local list = {
    }
    for _, member in ipairs(Match.team or {
    }) do
        list [member.id] = true
    end
    local flag = # simResult.ids > 0
    for _, value in ipairs(simResult.ids) do
        if not list [value] then
            flag = false
        end
    end
    return {
        ids = simResult.ids,
        won = simResult.won and true or false,
        wave = simResult.wave,
        cur = simResult.cur,
        better = simResult.better and true or nil,
        played = flag,
        ago = os.time() - (tonumber(simResult.at) or 0)
    }
end

function Reports.modsOf()
    local function helper(arg1)
        local value
        for key, value2 in pairs(type(arg1) == "table" and arg1 or {
        }) do
            value = value or {
            }
            value [key] = type(value2) == "number" and math.floor(value2 * 1000 + 0.5) / 1000 or value2
        end
        return value
    end
    local list = {
    }
    if Match.mod then
        list.weak, list.res, list.strong = helper(Match.mod.weak), helper(Match.mod.res), helper(Match.mod.strong)
    end
    list.seed = Match.ld._is_daily_challenge and tonumber(Match.ld._challenge_uuid) or nil
    local list2 = {
    }
    for _, config in pairs(Match.info and Match.info.configs or {
    }) do
        local unit = type(config) == "table" and Core.Units [config.unit_id]
        if type(unit) == "table" then
            local enemyModifiers = type(unit.enemy_modifiers) == "table" and unit.enemy_modifiers or {
            }
            for enemyModifierKey, enemyModifier in pairs(enemyModifiers) do
                if enemyModifier then
                    list2 [enemyModifierKey] = (list2 [enemyModifierKey] or 0) + 1
                end
            end
            if not enemyModifiers.Flying and Simulator.flies(unit) then
                list2.Flying = (list2.Flying or 0) + 1
            end
        end
    end
    if next(list2) then
        list.enemy = list2
    end
    for _, value in ipairs({
        "Armor",
        "Ice",
        "Ice@snow"
    }) do
        local enemyMod = Brain.enemyMods [value]
        local modRead = Simulator.modRead(enemyMod)
        if modRead then
            list.measured = list.measured or {
            }
            list.measured [value] = {
                f = math.floor(modRead * 1000 + 0.5) / 1000,
                n = # enemyMod.r
            }
        end
    end
    return next(list) and list or nil
end

