function Reports.match(arg1)
    local playerCount, count = # game:GetService("Players"):GetPlayers() - 1, 0
    for _, child in ipairs(workspace._UNITS:GetChildren()) do
        local stats = child:FindFirstChild("_stats")
        local player = stats and stats:FindFirstChild("player")
        local parentUnit = stats and stats:FindFirstChild("parent_unit")
        if player and player.Value ~= nil and player.Value ~= LocalPlayer and not (parentUnit and parentUnit.Value) then
            count = count + 1
        end
    end
    local list = {
    }
    local function helper(arg1)
        list [arg1] = list [arg1] or {
            dealt = 0,
            copies = 0,
            top = 0
        }
        return list [arg1]
    end
    for _, value in pairs(Match.ownDealt or {
    }) do
        local value2 = helper(value.id)
        value2.dealt = value2.dealt + (value.v or 0)
        value2.copies = value2.copies + 1
        value2.top = math.max(value2.top, value.lvl or 0)
    end
    for _, value in pairs(Match.helperDealt or {
    }) do
        if value.owner then
            local value2 = helper(value.owner)
            value2.helpers = (value2.helpers or 0) + (value.v or 0)
