    end
    for _, unit in ipairs(Match.mine or {
    }) do
        local stats = unit:FindFirstChild("_stats")
        local takedownCount = stats and stats:FindFirstChild("takedown_count")
        if stats and stats:FindFirstChild("id") and takedownCount then
            local value = helper(stats.id.Value)
            value.tk = (value.tk or 0) + (tonumber(takedownCount.Value) or 0)
        end
    end
    local list2 = {
    }
    for _, member in ipairs(Match.team or {
    }) do
        local item = list [member.id] or {
        }
        table.insert(list2, {
            id = member.id,
            lvl = Strategy.level(member.u),
            trait = (Units.trait(member.u)),
            relic = Units.relicName(member.u),
            skin = member.u.skin and member.u.skin._skin_id or nil,
            copies = item.copies or 0,
            top = item.top or 0,
            dealt = math.floor(item.dealt or 0),
            helpers = item.helpers and math.floor(item.helpers) or nil,
            tk = item.tk,
            eff = Match.lastEff and Match.lastEff [member.id] or nil
        })
    end
    local list = {
    }
    local calRun, pred = Match.calRun or {
    }, Match.pred or {
    }
    local function helper(arg1, arg2)
        return math.floor(tonumber(arg1 and (arg1 [arg2] or arg1 [tostring(arg2)])) or 0)
    end
    for i = 1, Match.wave() do
        table.insert(list, {
            i,
            helper(calRun.alive,
            i),
            helper(calRun.dpsAt,
            i),
            helper(pred.aliveAt,
            i),
            helper(pred.dpsAt,
