    local list3 = {
    }
    for key, value in pairs(Match.layout or {
    }) do
        if value [1] then
            list3 [key] = {
                math.floor(value [1].X),
                math.floor(value [1].Z)
            }
        end
    end
    local simRe = Brain.simRes [arg1.key] or {
    }
    local info = {
        v = VERSION,
        at = os.time(),
        mode = arg1.key,
        kind = Match.kind,
        level = Match.ld.id,
        map = Match.ld.map,
        diff = Match.ld._difficulty,
        challenge = Match.ld._challenge or (Match.key == "dc" and Brain.live.daily and Brain.live.daily.challenge) or nil,
        portal = Match.kind == "portal" and Brain.portalMods or nil,
        weather = Hunt.is(Match.ld.id) and Hunt.weatherNow() or nil,
        players = playerCount,
        otherUnits = count,
        joinedMid = Match.joinedMid or nil,
        lanes = Match.laneCount and Match.laneCount.n or 1,
        result = {
            won = arg1.won and true or false,
            wave = Match.wave(),
            total = Match.total,
            sec = math.floor(tonumber(arg1.sec) or 0),
            gems = arg1.gems,
            coins = arg1.coins,
            spent = math.floor(Match.spent or 0),
            refused = Match.refusals or 0,
            items = (type(arg1.items) == "table" and next(arg1.items)) and arg1.items or nil
        },
        sim = {
            pred = Match.pred and {
                won = Match.pred.won,
                wave = Match.pred.wave,
                min = math.floor((Match.pred.t or 0) / 6) / 10
            } or nil,
            p = simRe.p,
            margin = simRe.playing or simRe.margin,
            trust = simRe.trust and simRe.trust.ratio or nil,
            style = Match.style,
            why = Match.styleWhy,
            hpCal = Match.info and Match.info.cal and Match.info.cal.hpCal or nil,
            hpRun = Match.hpRun
        },
        team = list2,
        placed = Match.placeLog,
        plan = list3,
        waves = list,
        trainee = Match.trainee and Brain.train.on and Brain.train.on.id or nil,
        trial = Match.trialId,
        hunt = Match.hunt and {
