function Reports.postEmbed(arg1, arg2)
    local httpRequest = (syn and syn.request) or (http and http.request) or http_request or request
    if not httpRequest or Core.WEBHOOK_URL == "" then
        return false
    end
    local ok, res = pcall(httpRequest, {
        Url = Core.WEBHOOK_URL,
        Method = "POST",
        Headers = {
            ["Content-Type"] = "application/json"
        },
        Body = Utils.json({
            username = "awaqwaa",
            allowed_mentions = {
                parse = {
                }
            },
            embeds = {
                {
                    title = arg1,
                    description = arg2,
                    color = 15418782
                }
            }
        })
    })
    local statusCode = ok and type(res) == "table" and tonumber(res.StatusCode or res.Status) or nil
    return ok and (not statusCode or statusCode < 300)
end

function Reports.sendHive()
    if not (Config.shareStats and Core.WEBHOOK_URL ~= "") or # Brain.aaHiveQ == 0 or Reports.sending then
        return
    end
    Reports.sending = true
    local ok, res = pcall(Reports.postEmbed, string.format("🎌 AA · match · %s · v%s", tostring(Brain.anonId), VERSION), "```json\n" .. Brain.aaHiveQ [1] .. "\n```")
    Reports.sending = nil
    if ok and res then
        table.remove(Brain.aaHiveQ, 1)
        Brain.hiveSent = (tonumber(Brain.hiveSent) or 0) + 1
        pcall(App.saveNow)
    end
end

function Reports.sendAll()
    if not (Config.shareStats and Core.WEBHOOK_URL ~= "") then
        return 0, # Brain.aaHiveQ
    end
    local count = 0
    for i = 1, 10 do
        local aaHiveQCount = # Brain.aaHiveQ
        if aaHiveQCount == 0 then
            break
        end
        Reports.sendHive()
        if # Brain.aaHiveQ >= aaHiveQCount then
            break
        end
        count = count + 1
        task.wait(1.5)
    end
    return count, # Brain.aaHiveQ
end

function Reports.post(arg1)
    if Core.WEBHOOK_URL == "" then return false, "not connected" end
    local httpRequest = (syn and syn.request) or (http and http.request) or http_request or request
    if not httpRequest then
        return false, "no http"
    end
    local ok, res = pcall(httpRequest, {
        Url = Core.WEBHOOK_URL,
        Method = "POST",
        Headers = {
            ["Content-Type"] = "application/json"
        },
        Body = Utils.json({
            content = arg1,
            allowed_mentions = {
                parse = {
                }
            }
        })
    })
    return ok and res and (res.StatusCode == 200 or res.StatusCode == 204), res
end

function Reports.flush()
    if Core.WEBHOOK_URL == "" or not Config.shareStats or # Brain.hiveQueue == 0 then
        return false, "not connected"
    end
    local post = Reports.post("📊 AA " .. Utils.json({
        id = Brain.anonId,
        v = VERSION,
        runs = Brain.hiveQueue
    }))
    if post then
        table.clear(Brain.hiveQueue)
        App.saveSoon()
    end
    return post
end
Reports.HIVE_FILE = Core.FOLDER .. "/hive_shared.json"

function Reports.hive()
    if not Config.useHive then
        return nil
    end
    if Reports.shared == nil then
        local readJson = Utils.readJson(Reports.HIVE_FILE)
        Reports.shared = type(readJson) == "table" and type(readJson.units) == "table" and readJson or false
    end
    return Reports.shared or nil
end

function Reports.hiveUnit(unitKey)
    local hive = Reports.hive()
    local unit = hive and hive.units [unitKey]
    if type(unit) == "table" and (tonumber(unit.eff) or 0) > 0 and ((tonumber(unit.matches) or 0) >= 5 or (tonumber(unit.players) or 0) >= 2) then
        return unit
    end
end

function Reports.hiveTrain(arg1, arg2)
    local hive = Reports.hive()
    local value = hive and type(hive.train) == "table" and hive.train [arg1]
    if type(value) ~= "table" then
        return nil
    end
    local unit = arg2 and type(value.units) == "table" and value.units [arg2]
    if type(unit) == "table" and (tonumber(unit.runs) or 0) >= 3 then
        return tonumber(unit.perRun)
    end
    if (tonumber(value.runs) or 0) >= 3 then
        return tonumber(value.perRun)
    end
end

function Reports.hiveToggle(arg1)
    local hive = Reports.hive()
    local toggle = hive and type(hive.toggles) == "table" and hive.toggles [arg1]
    return type(toggle) == "table" and toggle or nil
end

function Reports.hiveStat(arg1)
    local hive = Reports.hive()
    local stat = hive and type(hive.stats) == "table" and hive.stats [arg1]
    return type(stat) == "table" and stat or nil
end

function Reports.hiveHp(mapKey)
    local hive = Reports.hive()
    local map = hive and type(hive.maps) == "table" and hive.maps [mapKey]
    return type(map) == "table" and (tonumber(map.runs) or 0) >= 3 and tonumber(map.hpCal) or nil
end

function Reports.hiveDrops(dropKey)
    local hive = Reports.hive()
    local drop = dropKey and hive and type(hive.drops) == "table" and hive.drops [dropKey]
    if type(drop) ~= "table" or (tonumber(drop.runs) or 0) < 3 or type(drop.items) ~= "table" then
        return nil
    end
    return drop.items
end

function Reports.sendUnit()
    if not (Config.shareStats and Core.WEBHOOK_URL ~= "") or Reports.sending then
        return
    end
    local hive = Reports.hive()
    local stats = hive and type(hive.stats) == "table" and hive.stats or {
    }
    for key, value in pairs(Brain.unitData) do
        if not Brain.unitSent [key] and not stats [key] and type(value) == "table" and value.upgrade then
            local list = {
            }
            for key, value in pairs(value) do
                if key ~= "passives" then
                    list [key] = value
                end
            end
            local ok, res = pcall(Utils.json, {
                id = key,
                data = list
            })
            if ok and # res <= 3900 then
                Reports.sending = true
                local ok, res2 = pcall(Reports.postEmbed, string.format("🎌 AA · unit · %s · v%s", tostring(Brain.anonId), VERSION), "```json\n" .. res .. "\n```")
                Reports.sending = nil
                if ok and res2 then
                    Brain.unitSent [key] = os.time()
                    App.saveSoon()
                end
            else
                Brain.unitSent [key] = - 1
                App.saveSoon()
            end
            return
        end
    end
end

function Reports.hiveTrainRate(key)
    local hive = Reports.hive()
    local value = hive and type(hive.train) == "table" and hive.train [key]
    return type(value) == "table" and (tonumber(value.runs) or 0) >= 3 and tonumber(value.perMin) or nil
end

function Reports.hiveFetch()
    if Core.HIVE_URL == "" or not Config.useHive then
        return
    end
    local ok, res = pcall(game.HttpGet, game, Core.HIVE_URL .. "?t=" .. os.time())
    if not ok or type(res) ~= "string" or res:sub(1, 1) ~= "{" then
        return
    end
    local ok, res2 = pcall(HttpService.JSONDecode, HttpService, res)
    if not (ok and type(res2) == "table" and tonumber(res2.v) == 1 and type(res2.units) == "table") then
        return
    end
    local hive = Reports.hive()
    if hive and hive.updated == res2.updated then
        return
    end
    pcall(Utils.writeJson, Reports.HIVE_FILE, res2)
    Reports.shared = res2
    table.clear(Units._rows)
    table.clear(Simulator._holds)
    Adventure._src = nil
    local count, count2 = 0, 0
    for _ in pairs(res2.units) do
        count = count + 1
    end
    for _ in pairs(type(res2.train) == "table" and res2.train or {
    }) do
        count2 = count2 + 1
    end
    App.log(1, "HIVE", string.format("learned from %d players' %d matches: readings for %d units, takedown rates on %d maps", tonumber(res2.players) or 0, tonumber(res2.matchRecords) or 0, count, count2))
    local list = {
    }
    for _, unitId in ipairs(type(res2.under) == "table" and res2.under or {
    }) do
        if Units.owns(unitId) and not (Brain.learn [unitId] and (Brain.learn [unitId].n or 0) >= 3) then
            table.insert(list, string.format("%s (×%.1f)", Units.name(unitId), tonumber(res2.units [unitId] and res2.units [unitId].eff) or 0))
        end
    end
    if # list > 0 then
        App.log(1, "HIVE", "other players' runs say the simulator reads these of yours far too low: " .. table.concat(list, ", ") .. ". A trial run would check them")
        if App.notify then
            App.notify("Local learning", "Units the simulator underrates: " .. table.concat(list, ", "), "info")
        end
    end
end

function Reports.hiveText()
    if not Config.useHive then
        return "Off: the farm learns only from your own runs."
    end
    local hive = Reports.hive()
    if not hive then
        return "Nothing shared yet. Once other players' farms send their matches, the farm reads what they learned here every 6 hours."
    end
    local count, count2, count3, count4, count5, count6 = 0, 0, 0, 0, 0, 0
    for unitKey in pairs(hive.units) do
        if Reports.hiveUnit(unitKey) and not (Brain.learn [unitKey] and (Brain.learn [unitKey].n or 0) >= 3) then
            count = count + 1
        end
    end
    for _ in pairs(type(hive.train) == "table" and hive.train or {
    }) do
        count2 = count2 + 1
    end
    for statKey in pairs(type(hive.stats) == "table" and hive.stats or {
    }) do
        if not Brain.unitData [statKey] then
            count3 = count3 + 1
        end
    end
    for mapKey in pairs(type(hive.maps) == "table" and hive.maps or {
    }) do
        if Reports.hiveHp(mapKey) and not (Brain.simCal [mapKey] and Brain.simCal [mapKey].hpCal) then
            count4 = count4 + 1
        end
    end
    for dropKey in pairs(type(hive.drops) == "table" and hive.drops or {
    }) do
        if Reports.hiveDrops(dropKey) then
            count5 = count5 + 1
        end
    end
    for toggleKey in pairs(type(hive.toggles) == "table" and hive.toggles or {
    }) do
        if not Brain.toggles [toggleKey] then
            count6 = count6 + 1
        end
    end
    local list = {
        string.format("From %d players' %d matches, updated %s.",
        tonumber(hive.players) or 0,
        tonumber(hive.matchRecords) or 0,
        os.date("%b %d %H:%M",
        tonumber(hive.updated) or 0)),
        string.format("What it fills in that your own runs haven't: %d units' readings, %d hidden units' real stats, %d switch abilities, how tough %d maps really are, what %d levels really drop, and takedown rates on %d maps.",
        count,
        count3,
        count6,
        count4,
        count5,
        count2)
    }
    local list2 = {
    }
    for _, unitId in ipairs(type(hive.under) == "table" and hive.under or {
    }) do
        table.insert(list2, Units.name(unitId) .. (Units.owns(unitId) and " (yours)" or ""))
    end
    if # list2 > 0 then
        table.insert(list, "The simulator reads these far too low: " .. table.concat(list2, ", ") .. ".")
    end
    return table.concat(list, "\n")
end

function Reports.suggest(arg1)
    arg1 = tostring(arg1 or ""):sub(1, 500):gsub("https?://%S+", "[link]"):gsub("@", "(at)")
    if arg1:gsub("%s", "") == "" then
        return false, "empty"
    end
    if Core.WEBHOOK_URL == "" then
        return false, "suggestions aren't connected yet"
    end
    if os.time() - (Brain.lastSuggest or 0) < 600 then
        return false, "one suggestion per 10 minutes"
    end
    local postEmbed = Reports.postEmbed(string.format("🎌 AA · suggestion · %s · v%s", tostring(Brain.anonId), VERSION), arg1)
    if postEmbed then
        Brain.lastSuggest = os.time()
    end
    return postEmbed, postEmbed and nil or "send failed"
end

