-- ============================================================================
-- Helper: Safe Config Base Read / Write (respects Farming Queue overlay)
-- ============================================================================
local function uiGetBase(key)
    if Farming and type(Farming.baseValue) == "function" then
        local ok, val = pcall(Farming.baseValue, key)
        if ok then
            return val
        end
    end
    return Config[key]
end

local function uiSetBase(key, val, skipSave)
    if Farming and type(Farming.setBase) == "function" then
        pcall(Farming.setBase, key, val)
    else
        Config[key] = val
    end
    if not skipSave and App and type(App.saveSoon) == "function" then
        pcall(App.saveSoon)
    end
end

function GUI.escape(value)
    local s = tostring(value or "")
    s = s:gsub("&", "&amp;")
    s = s:gsub("<", "&lt;")
    s = s:gsub(">", "&gt;")
    return s
end

function GUI.shortLine(text, limit)
    local s = tostring(text or ""):gsub("[\r\n]+", " ")
    local maxLen = tonumber(limit) or 120
    if #s > maxLen then
        s = s:sub(1, maxLen - 3) .. "..."
    end
    return s
end

function GUI.sigOf(res)
    local list = {}
    for _, item in ipairs(res or {}) do
        if type(item) == "table" then
            table.insert(list, tostring(item.value or "") .. "=" .. tostring(item.text or ""))
        else
            table.insert(list, tostring(item))
        end
    end
    return table.concat(list, "\n")
end

function GUI.listBuilt(name, res)
    GUI.listSig[name] = GUI.sigOf(res)
    GUI.listEmpty[name] = (#(res or {}) <= 1)
end

-- ============================================================================
-- Preserved Pure Lua 5.1 QoL Helpers (Match ETA & Rates)
-- ============================================================================
local function qolFinite(x)
    return type(x) == "number" and x == x and x ~= math.huge and x ~= -math.huge
end

local function qolQuantile(sorted, q)
    local n = #sorted
    if n == 1 then
        return sorted[1]
    end
    local idx = 1 + (n - 1) * q
    local loIdx = math.floor(idx)
    local hiIdx = math.ceil(idx)
    local frac = idx - loIdx
    return sorted[loIdx] * (1 - frac) + sorted[hiIdx] * frac
end

local function qolCommas(n)
    local s = string.format("%.0f", math.floor(n + 0.5))
    while true do
        local updated, count = string.gsub(s, "^(-?%d+)(%d%d%d)", "%1,%2")
        s = updated
        if count == 0 then
            break
        end
    end
    return s
end

function Utils.qol_fmtDur(sec)
    if not qolFinite(sec) or sec < 0 then
        return "?"
    end
    local s = math.floor(sec + 0.5)
    if s >= 3600 then
        local h = math.floor(s / 3600)
        local m = math.floor((s % 3600) / 60)
        return string.format("%dh %02dm", h, m)
    elseif s >= 60 then
        local m = math.floor(s / 60)
        local rem = s % 60
        return string.format("%dm %02ds", m, rem)
    else
        return string.format("%ds", s)
    end
end

function Utils.qol_eta(p)
    local params = {}
    if type(p) == "table" then
        params = p
    end

    local wave = 0
    if qolFinite(params.wave) and params.wave >= 0 then
        wave = math.floor(params.wave)
    end

    local validStarts = {}
    if type(params.waveStarts) == "table" then
        for _, t in ipairs(params.waveStarts) do
            if qolFinite(t) then
                table.insert(validStarts, t)
            end
        end
    end

    local allIntervals = {}
    for i = 1, #validStarts - 1 do
        local dt = validStarts[i + 1] - validStarts[i]
        if qolFinite(dt) and dt > 0 then
            table.insert(allIntervals, dt)
        end
    end

    local intervals = {}
    local startIdx = math.max(1, #allIntervals - 7)
    for i = startIdx, #allIntervals do
        table.insert(intervals, allIntervals[i])
    end

    local n = #intervals
    local hasPrior = qolFinite(params.prior) and params.prior > 0
    local priorVal = 0
    if hasPrior then
        priorVal = params.prior
    end

    local waveDur = nil
    local waveLo = 0
    local waveHi = 0
    local basis = "none"

    local sorted = {}
    for i = 1, n do
        sorted[i] = intervals[i]
    end
    table.sort(sorted)

    if n >= 2 then
        waveDur = qolQuantile(sorted, 0.5)
        basis = "measured"
    elseif n == 1 then
        local med = sorted[1]
        if hasPrior then
            local w = n / 2
            waveDur = med * w + priorVal * (1 - w)
            basis = "measured"
        else
            waveDur = med
            basis = "measured"
        end
    elseif hasPrior then
        waveDur = priorVal
        basis = "sim"
    end

    local isInfinite = (params.total == nil) or (params.total == 0) or (not qolFinite(params.total)) or (params.total < 0)

    if waveDur == nil or not qolFinite(waveDur) then
        local goal = params.total
        if isInfinite then
            goal = params.target
        end
        local leftVal = nil
        if qolFinite(goal) and goal > 0 then
            leftVal = math.max(0, math.floor(goal) - wave)
        end
        return {
            sec = nil,
            lo = nil,
            hi = nil,
            left = leftVal,
            basis = "none",
            text = "?"
        }
    end

    local dur = math.max(0, waveDur)
    if n >= 4 then
        waveLo = math.max(0, qolQuantile(sorted, 0.25))
        waveHi = math.max(0, qolQuantile(sorted, 0.75))
    else
        waveLo = dur * 0.8
        waveHi = dur * 1.2
    end

    local hasTarget = qolFinite(params.target) and params.target > 0
    if isInfinite and not hasTarget then
        return {
            sec = nil,
            lo = nil,
            hi = nil,
            left = nil,
            basis = basis,
            text = "Infinite · ~" .. Utils.qol_fmtDur(dur) .. "/wave"
        }
    end

    local rawGoal = params.total
    if isInfinite then
        rawGoal = params.target
    end
    local goal = math.floor(rawGoal)
    local left = math.max(0, goal - wave)

    local elapsed = 0
    if #validStarts > 0 and qolFinite(params.now) then
        elapsed = math.max(0, params.now - validStarts[#validStarts])
    end

    local sec = 0
    local lo = 0
    local hi = 0
    if left > 0 then
        sec = math.max(0, left * dur - elapsed)
        lo = math.max(0, left * waveLo - elapsed)
        hi = math.max(0, left * waveHi - elapsed)
    end

    local unit = "waves"
    if left == 1 then
        unit = "wave"
    end
    local text = string.format(
        "%d %s left · ~%s (%s-%s)",
        left,
        unit,
        Utils.qol_fmtDur(sec),
        Utils.qol_fmtDur(lo),
        Utils.qol_fmtDur(hi)
    )

    return {
        sec = sec,
        lo = lo,
        hi = hi,
        left = left,
        basis = basis,
        text = text
    }
end

function Utils.qol_perHour(amount, sinceSec)
    if not qolFinite(sinceSec) or sinceSec < 60 then
        return "..."
    end
    if not qolFinite(amount) then
        return "..."
    end
    local safeAmount = math.max(0, amount)
    local rate = math.floor((safeAmount / sinceSec) * 3600 + 0.5)
    return "~" .. qolCommas(rate) .. "/h"
end

function Match.etaText()
    local wave = Match.wave()
    local total = tonumber(Match.total) or 0
    local passTotal = total
    if Match.infinite or total <= 0 then
        passTotal = 0
    end
    local ok, res = pcall(Utils.qol_eta, {
        wave = math.max(0, wave - 1),
        total = passTotal,
        waveStarts = Match.waveStarts,
        prior = Match.info and tonumber(Match.info.waveSec) or nil,
        now = Utils.now()
    })
    if ok and type(res) == "table" and res.text and res.text ~= "?" then
        return res.text .. " · "
    end
    return ""
end

