function GUI.bannerOptions()
    local list = {
        { text = "Pick a banner", value = "" }
    }
    local list2 = {}
    for bannerKey, banner in pairs(Core.Banners or {}) do
        if type(banner) == "table" and banner.active then
            table.insert(list2, bannerKey)
        end
    end
    table.sort(list2)
    for _, item in ipairs(list2) do
        local bannerCost = FarmHub.bannerCost(item)
        table.insert(list, {
            text = string.format("%s (%s)", FarmHub.BANNER_NAME[item] or item, bannerCost and bannerCost.name or "?"),
            value = item
        })
    end
    return list
end

function GUI.snipeOptions()
    local list = {
        { text = "Pick a unit", value = "" }
    }
    local snipe = Brain.snipe or {}
    if not GUI.evolvedIds then
        GUI.evolvedIds = {}
        for _, unit in pairs(Core.Units or {}) do
            if type(unit) == "table" and type(unit.evolve) == "table" and unit.evolve.evolve_unit then
                GUI.evolvedIds[unit.evolve.evolve_unit] = true
            end
        end
    end
    local list2, list3 = {}, {}
    local function helper(unitId, arg2, arg3)
        if list3[unitId] or not (Core.Units and Core.Units[unitId]) then
            return
        end
        list3[unitId] = true
        local snipeHas = FarmHub.snipeHas(unitId)
        table.insert(list2, {
            id = unitId,
            text = Units.name(unitId) .. arg2 .. (snipeHas and " · owned" or ""),
            key = arg3 * 10 + (snipeHas and 0 or 5),
            name = Units.name(unitId)
        })
    end
    if Config.snipeUnit ~= "" then
        helper(Config.snipeUnit, "", 9)
    end
    for key, val in pairs(snipe.feat or {}) do
        for _, uId in ipairs(val) do
            helper(uId, " · featured on " .. (FarmHub.BANNER_NAME[key] or key), 3)
        end
    end
    for key, val in pairs(snipe.seen or {}) do
        if type(val) == "table" then
            helper(key, string.format(" · seen on %s %s", FarmHub.BANNER_NAME[val.banner] or tostring(val.banner), os.date("%b %d", tonumber(val.at) or os.time())), 2)
        end
    end
    for unitKey, unit in pairs(Core.Units or {}) do
        if type(unitKey) == "string" and type(unit) == "table" and unit.rarity == "Mythic" and not unit.hide_from_banner and not unit.limited and not GUI.evolvedIds[unitKey] and not unitKey:find(":") then
            helper(unitKey, "", 1)
        end
    end
    table.sort(list2, function(a, b)
        if a.key ~= b.key then
            return a.key > b.key
        end
        return a.name < b.name
    end)
    for _, item in ipairs(list2) do
        table.insert(list, { text = item.text, value = item.id })
    end
    return list
end

function GUI.unitOptions(fuseXpUnit, filterFn)
    local list = {
        { text = "Pick a unit", value = "" }
    }
    local session = Core.session()
    if not session then
        return list
    end
    local eqMap = {}
    for _, item in ipairs(Units.equipped()) do
        eqMap[item.uuid] = true
    end
    local list3 = {}
    for ownedUnitKey, ownedUnit in pairs(session.profile_data.collection.owned_units or {}) do
        local unit = Core.Units[ownedUnit.unit_id]
        if unit and (eqMap[ownedUnitKey] or ownedUnit._locked or unit.rarity == "Secret" or unit.rarity == "Mythic" or ownedUnitKey == fuseXpUnit) then
            local ok, res = pcall(Core.USC.calculate_level, ownedUnit.unit_id, ownedUnit.xp)
            res = ok and tonumber(res) or 0
            table.insert(list3, {
                uuid = ownedUnitKey,
                u = ownedUnit,
                lvl = res,
                team = eqMap[ownedUnitKey],
                key = (eqMap[ownedUnitKey] and 4000 or 0) + (ownedUnit._locked and 2000 or 0) + (unit.rarity == "Secret" and 1000 or 0) + res
            })
        end
    end
    table.sort(list3, function(a, b)
        if a.key ~= b.key then
            return a.key > b.key
        end
        return a.uuid < b.uuid
    end)
    for _, item in ipairs(list3) do
        local flag, str = true, ""
        if filterFn then
            flag, str = pcall(filterFn, item.u)
        end
        if flag and (str ~= false or item.uuid == fuseXpUnit) and (#list <= 60 or item.uuid == fuseXpUnit) then
            table.insert(list, {
                text = string.format("%s · Lv %d%s%s", Units.name(item.u.unit_id), item.lvl, item.team and " · team" or "", type(str) == "string" and str or ""),
                value = item.uuid
            })
        end
    end
    return list
end

function GUI.focusNow()
    if Config.autoEvolve and Config.evolveUnit ~= "" then
        return Config.evolveUnit
    end
    return ""
end

function GUI.evolveOptions(focusNow)
    local list = {
        { text = "Pick a unit", value = "" }
    }
    local session = Core.session()
    if not session then
        return list
    end
    local eqMap = {}
    for _, item in ipairs(Units.equipped()) do
        eqMap[item.uuid] = true
    end
    local bestById = {}
    for ownedUnitKey, ownedUnit in pairs(session.profile_data.collection.owned_units or {}) do
        local unit = Core.Units[ownedUnit.unit_id]
        if unit and unit.evolve and unit.evolve.evolve_unit and not unit.evolve.hide_from_ui and Core.Units[unit.evolve.evolve_unit] then
            local num = (ownedUnitKey == focusNow and 1e9 or 0) + (eqMap[ownedUnitKey] and 1e6 or 0) + (tonumber(ownedUnit.xp) or 0)
            if not bestById[ownedUnit.unit_id] or num > bestById[ownedUnit.unit_id].key then
                bestById[ownedUnit.unit_id] = {
                    uuid = ownedUnitKey,
                    id = ownedUnit.unit_id,
                    to = unit.evolve.evolve_unit,
                    key = num
                }
            end
        end
    end
    local list4 = {}
    for _, item in pairs(bestById) do
        table.insert(list4, item)
    end
    table.sort(list4, function(a, b)
        if a.key ~= b.key then
            return a.key > b.key
        end
        return a.uuid < b.uuid
    end)
    for _, item in ipairs(list4) do
        local unitObj = session.collection:get_unit_by_uuid(item.uuid)
        local ok, res = pcall(Core.USC.calculate_level, item.id, unitObj and unitObj.xp or 0)
        table.insert(list, {
            text = string.format("%s -> %s · Lv %d%s", Units.name(item.id), Units.name(item.to), ok and tonumber(res) or 0, eqMap[item.uuid] and " · team" or ""),
            value = item.uuid
        })
    end
    return list
end

function GUI.focusOptions()
    local list = {
        { text = "Smart Play (auto chooses)", value = "" }
    }
    local seenFrom = {}
    local session = Core.session()
    for _, item in ipairs(Brain.goalsTop or {}) do
        seenFrom[item.from] = true
        local unitObj = session and session.collection:get_unit_by_uuid(item.uuid)
        local ok, res = pcall(Core.USC.calculate_level, item.from, unitObj and unitObj.xp or 0)
        table.insert(list, {
            text = string.format("%s -> %s · Lv %d%s", Units.name(item.from), Units.name(item.to), ok and tonumber(res) or 0, item.ready and " · ready" or ""),
            value = item.uuid
        })
    end
    if session then
        for _, evolveOption in ipairs(GUI.evolveOptions(GUI.focusNow())) do
            local unitObj = evolveOption.value ~= "" and session.collection:get_unit_by_uuid(evolveOption.value)
            if unitObj and not seenFrom[unitObj.unit_id] then
                table.insert(list, evolveOption)
            end
        end
    end
    return list
end

function FarmHub.setFocus(uuid)
    Config.evolveUnit = uuid or ""
    Config.autoEvolve = Config.evolveUnit ~= ""
    Config.focusNext = ""
    if FarmHub.pickNote then
        FarmHub.pickNote.autoEvolve = nil
    end
    if FarmHub.last then
        FarmHub.last.goals = nil
        FarmHub.last.trainScan = nil
    end
    if Training then
        Training._at = nil
    end
    if Modes then
        Modes.lastScored = nil
    end
    local okAdv, resAdv = pcall(Adventure.refresh)
    if not okAdv then
        App.log(1, "ERROR", "focus goals: " .. tostring(resAdv))
    end
    local okCore, resCore = pcall(Strategy.core, true)
    if not okCore then
        App.log(1, "ERROR", "focus core: " .. tostring(resCore))
    end
    App.saveSoon()
end

function FarmHub.focusText()
    if GUI.focusNow() ~= "" then
        local tail = ""
        if Config.focusNext ~= "" then
            tail = "\nNext up: " .. Units.name(Config.focusNext) .. ", once this one has evolved."
        end
        return "Your focus. " .. FarmHub.evolveText() .. tail
    end
    local on = Brain.train and Brain.train.on
    local on2 = on or (Training and Training.target and Training.target())
    if on2 then
        return string.format(
            "Smart Play is working on %s -> %s (%s %s/%s)",
            Units.name(on2.id),
            Units.name(on2.to),
            tostring(on2.what),
            Utils.fmt((tonumber(on2.have) or 0) + (tonumber(on2.got) or 0)),
            Utils.fmt(tonumber(on2.need) or 0)
        )
    end
    local goal = (Brain.goals or {})[1]
    if goal then
        return "Smart Play is working on " .. Units.name(goal.from) .. " -> " .. Units.name(goal.to)
    end
    return "Smart Play: goals are worked out in the lobby"
end

function GUI.modeOptions(kind)
    local list = {}
    local pickKey = ({
        raid = "pickRaid",
        story = "pickStory",
        legend = "pickLegend",
        infinite = "pickInfinite",
        portal = "pickPortal"
    })[kind]

    local function walkWorlds(worldOrder, fn)
        for _, worldId in ipairs(Utils.list(worldOrder)) do
            local world = Core.Worlds and Core.Worlds[worldId]
            for _, lvl in ipairs(Utils.list(world and world.levels)) do
                if Modes.open(lvl.id) then
                    fn(lvl.id, world)
                end
            end
        end
    end

    if kind == "story" then
        list = {
            { text = "Smart: first clears, then farm runs", value = "" },
            { text = "Progress: next unbeaten act", value = "progress" }
        }
        walkWorlds(Core.WLO and Core.WLO.WORLD_ORDER, function(lvlId, world)
            if not world.legend_stage and not world.raid_world then
                for _, diff in ipairs({ "Normal", "Hard" }) do
                    if Modes.diffOpen(lvlId, diff) then
                        table.insert(list, {
                            text = Modes.levelName(lvlId) .. " (" .. diff .. ")",
                            value = "st:" .. lvlId .. ":" .. diff
                        })
                    end
                end
            end
        end)
    elseif kind == "legend" then
        list = {
            { text = "Smart: when drops match goals", value = "" },
            { text = "Progress: next unbeaten legend stage", value = "progress" }
        }
        walkWorlds(Core.WLO and Core.WLO.LEGEND_WORLD_ORDER, function(lvlId)
            table.insert(list, {
                text = Modes.levelName(lvlId),
                value = "st:" .. lvlId .. ":Hard"
            })
        end)
    elseif kind == "raid" then
        list = {
            { text = "Smart: highest-value raid", value = "" }
        }
        walkWorlds(Core.WLO and Core.WLO.RAID_WORLD_ORDER, function(lvlId)
            table.insert(list, {
                text = Modes.levelName(lvlId),
                value = "rd:" .. lvlId
            })
        end)
    elseif kind == "infinite" then
        list = {
            { text = "Smart: daily gems & takedowns", value = "" }
        }
        for _, infId in ipairs(Modes.infIds()) do
            if Modes.open(infId) then
                table.insert(list, {
                    text = Modes.levelName(infId),
                    value = "inf:" .. infId
                })
            end
        end
    elseif kind == "portal" then
        list = {
            { text = "Smart: portals matching evolution goals", value = "smart" }
        }
        local unheld = {}
        for _, portalKind in ipairs(Modes.portalKinds()) do
            local heldCount = #Modes.portalsHeld(portalKind.pid)
            local suffix = ""
            if heldCount > 0 then
                suffix = " · held " .. tostring(heldCount)
            end
            local info = {
                text = string.format("%s (%s)%s", portalKind.name, tostring(portalKind.rarity or "?"), suffix),
                value = portalKind.pid
            }
            if heldCount > 0 then
                table.insert(list, info)
            else
                table.insert(unheld, info)
            end
        end
        for _, item in ipairs(unheld) do
            table.insert(list, item)
        end
    end

    local savedVal = ""
    if pickKey and Config[pickKey] ~= nil then
        savedVal = Config[pickKey]
    end
    local found = false
    for _, item in ipairs(list) do
        if item.value == savedVal then
            found = true
            break
        end
    end
    if not found then
        table.insert(list, {
            text = "Saved pick (not open right now)",
            value = savedVal
        })
    end
    return list
end

function GUI.lbTargetOptions()
    local list = {
        { text = "Pick a unit", value = "" }
    }
    local session = Core.session()
    if not session then
        return list
    end
    local eqMap = {}
    for _, item in ipairs(Units.equipped()) do
        eqMap[item.uuid] = true
    end
    local list3 = {}
    for ownedUnitKey, ownedUnit in pairs(session.profile_data.collection.owned_units or {}) do
        local unitObj = session.collection:get_unit_by_uuid(ownedUnitKey) or ownedUnit
        local unit = Core.Units[unitObj.unit_id]
        if unit and (unit.rarity == "Mythic" or unit.rarity == "Secret" or eqMap[ownedUnitKey] or ownedUnitKey == Config.fuseUnit) then
            local ok, res = pcall(Core.USC.get_max_limit_break, unitObj)
            local curLb = unitObj.further_modifiers and unitObj.further_modifiers.limit_break and tonumber(unitObj.further_modifiers.limit_break.current_limit_break) or 0
            if (ok and (tonumber(res) or 0) > curLb) or ownedUnitKey == Config.fuseUnit then
                local okSc, scRes = pcall(Units.score, unitObj)
                local level, cap = Strategy.level(unitObj), Strategy.cap(unitObj)
                table.insert(list3, {
                    uuid = ownedUnitKey,
                    id = unitObj.unit_id,
                    lvl = level,
                    cap = cap,
                    team = eqMap[ownedUnitKey],
                    sc = okSc and scRes or 0,
                    key = (ownedUnitKey == Config.fuseUnit and 4 or 0) + (eqMap[ownedUnitKey] and 2 or 0) + (level >= cap and 1 or 0)
                })
            end
        end
    end
    table.sort(list3, function(a, b)
        if a.key ~= b.key then
            return a.key > b.key
        end
        if a.sc ~= b.sc then
            return a.sc > b.sc
        end
        return a.uuid < b.uuid
    end)
    for i, item in ipairs(list3) do
        if i > 60 then
            break
        end
        table.insert(list, {
            text = string.format("%s · Lv %d/%d%s%s", Units.name(item.id), item.lvl, item.cap, item.team and " · team" or "", item.lvl >= item.cap and " · at cap" or ""),
            value = item.uuid
        })
    end
    return list
end

function GUI.lbStatusNow()
    local col = GUI.COL
    if Config.fuseUnit == "" then
        return {
            title = "Pick a unit to Limit Break",
            text = "Raises a unit's level cap (100 -> 110). Requires a Divine Wish and fodder units.",
            sub = "",
            tag = "IDLE",
            tagColor = col.sub,
            progress = 0,
            color = col.accent
        }
    end
    local session = Core.session()
    local unitObj = session and session.collection:get_unit_by_uuid(Config.fuseUnit)
    if not unitObj then
        return {
            title = "Target unit not found",
            text = "Pick another unit from your inventory.",
            sub = "",
            tag = "MISSING",
            tagColor = col.red,
            progress = 0,
            color = col.red
        }
    end
    if App.where == "lobby" and not (Brain.fuseInfo and Brain.fuseInfo.uuid == unitObj.uuid) and FarmHub.every("lbInfo", 10) then
        task.spawn(function()
            local ok, res = App.request("fuseInfo", "request_fusion_information", unitObj.uuid)
            if ok and type(res) == "table" then
                Brain.fuseInfo = {
                    requirement = res.requirement,
                    divine_wish = res.divine_wish,
                    allowed = res.allowed,
                    uuid = unitObj.uuid
                }
                GUI._lb = nil
            end
        end)
    end
    local hasInfo = Brain.fuseInfo and Brain.fuseInfo.uuid == unitObj.uuid
    local requirement = hasInfo and tonumber(Brain.fuseInfo.requirement) or 12
    local divineWish = hasInfo and tonumber(Brain.fuseInfo.divine_wish) or 1
    local level, cap = Strategy.level(unitObj), Strategy.cap(unitObj)
    local fodderPts = 0
    if #(Config.fuseFodder or {}) > 0 then
        _, fodderPts = FarmHub.fodderPicked(unitObj)
    else
        _, fodderPts = FarmHub.fuseFuel(unitObj, requirement)
    end
    local have = Adventure.have("divine_wish")
    local ready = level >= cap and have >= divineWish and fodderPts >= requirement and not (hasInfo and Brain.fuseInfo.allowed == false)
    local function mark(cond)
        if cond then
            return "OK"
        end
        return "NO"
    end
    local titleTail = ""
    if hasInfo and Brain.fuseInfo.allowed == false then
        titleTail = " · cannot limit break"
    end
    local infoNote = ""
    if not hasInfo then
        infoNote = " (checked in lobby)"
    end
    local subText = FarmHub.pickNote and FarmHub.pickNote.autoFuse
    if not subText then
        if Config.autoFuse then
            subText = "Auto Limit Break ON: fuses automatically once all requirements are met."
        else
            subText = "Auto Limit Break OFF: review fodder below, then enable Auto Limit Break."
        end
    end
    return {
        title = Units.name(unitObj.unit_id) .. titleTail,
        text = string.format("Lv %d/%d [%s] · Divine Wish %d/%d [%s] · Fodder %d/%d pts [%s]%s", level, cap, mark(level >= cap), have, divineWish, mark(have >= divineWish), fodderPts, requirement, mark(fodderPts >= requirement), infoNote),
        sub = subText,
        tag = ready and "READY" or "WAITING",
        tagColor = ready and col.green or col.orange,
        progress = math.min(1, fodderPts / math.max(1, requirement)),
        color = ready and col.green or col.accent
    }
end

function GUI.lbStatus()
    local joined = table.concat({
        tostring(Config.fuseUnit),
        table.concat(Config.fuseFodder or {}, ","),
        tostring(Config.autoFuse),
        tostring(FarmHub.pickNote and FarmHub.pickNote.autoFuse),
        tostring(Brain.fuseInfo and Brain.fuseInfo.uuid),
        tostring(App.where)
    }, "|")
    local lb = GUI._lb
    if lb and lb.key == joined and Utils.now() - lb.at < 15 then
        return lb.v
    end
    local res = GUI.lbStatusNow()
    GUI._lb = { key = joined, at = Utils.now(), v = res }
    return res
end

function GUI.keyName(key)
    if key == "dc" then
        return "Daily Challenge"
    end
    if key == "ch" then
        return "Challenge"
    end
    if key == "dg" then
        return "Dungeon"
    end
    local pref, mapId, diff = tostring(key):match("^(%a+):([^:]+):?(%a*)$")
    if not mapId then
        return tostring(key)
    end
    local tag = ({ st = "Story ", rd = "Raid ", ev = "Event ", inf = "Infinite " })[pref] or ""
    local suffix = ""
    if diff and diff ~= "" then
        suffix = " (" .. diff .. ")"
    end
    return tag .. Modes.levelName(mapId) .. suffix
end

function GUI.plainMode(mode)
    return string.format("%s · %.0f%% win · ~%.0f gems/min", mode.label, (mode.p or 0) * 100, mode.score or 0)
end

function GUI.upNext(mode, arg2)
    if not mode then
        return "Deciding...", ""
    end
    if App.where == "match" and mode.kind == "story" and mode.first and mode.key == Match.key then
        local str = "once this act is won"
        local ok, res = pcall(Core.PSC.get_next_story_level, mode.level)
        if Config.onlyStory and ok and res then
            return Modes.levelName(res) .. " (" .. tostring(mode.diff) .. ")", "Next act " .. str
        end
        if arg2 then
            return GUI.plainMode(arg2), "Next best mode " .. str
        end
    end
    return GUI.plainMode(mode), mode.why or ""
end

function GUI.slotLines(items)
    local out = {}
    for i, item in ipairs(items or {}) do
        local name = type(item) == "table" and tostring(item.name or "?") or tostring(item)
        local role = type(item) == "table" and item.role and (" (" .. tostring(item.role) .. ")") or ""
        table.insert(out, tostring(i) .. ". " .. name .. role)
    end
    return table.concat(out, " · ")
end

function GUI.simView(col)
    col = col or GUI.COL
    if App.where == "match" and Match.ld then
        local pred = Match.pred
        local titleStr
        if not pred then
            if Match.planning or (Match.laneWant and not Match.laneCut) then
                titleStr = "Simulator: choosing spots..."
            else
                titleStr = "Simulator: no prediction for this run"
            end
        elseif Match.infinite then
            titleStr = string.format("Simulator: base falls at wave %d (%.0f min)", pred.wave or 0, (pred.t or 0) / 60)
        else
            titleStr = string.format("Simulator: %s at wave %d (%.0f min)", pred.won and "Win" or "Loss", pred.wave or 0, (pred.t or 0) / 60)
        end
        local parts = {}
        if Match.style then
            table.insert(parts, "Placement: " .. (GUI.STYLE_NAMES[Match.style] or Match.style))
        end
        if Match.laneWant then
            if Match.laneCut then
                table.insert(parts, string.format("Lane %s (%d/%d)", tostring(Match.laneCut), Match.laneWant, Match.laneTotal or 0))
            else
                table.insert(parts, string.format("Waiting for portal lane (%d/%d)", Match.laneWant, Match.laneTotal or 0))
            end
        end
        if Match.trainee and Brain.train and Brain.train.on then
            table.insert(parts, "Training " .. Units.name(Brain.train.on.id))
        end
        local tag, tagCol, subText = "", nil, "No wave measured yet"
        local alive = Match.calRun and Match.calRun.alive or {}
        for i = Match.wave(), 1, -1 do
            local val1 = tonumber(alive[tostring(i)])
            local val2 = pred and pred.aliveAt and tonumber(pred.aliveAt[i])
            if val1 and val2 then
                local thresh = 1000
                if val1 < thresh and val2 < thresh then
                    tag, tagCol, subText = "ON TRACK", col.green, string.format("Wave %d cleared cleanly as expected", i)
                elseif val2 < thresh then
                    tag, tagCol, subText = "BEHIND", col.red, string.format("Wave %d: %s HP left vs 0 expected", i, Utils.fmt(val1))
                elseif val1 < thresh then
                    tag, tagCol, subText = "AHEAD", col.green, string.format("Wave %d cleared ahead of schedule", i)
                else
                    local ratio = val1 / val2
                    if ratio <= 0.8 then
                        tag, tagCol = "AHEAD", col.green
                    elseif ratio <= 1.25 then
                        tag, tagCol = "ON TRACK", col.green
                    elseif ratio <= 2 then
                        tag, tagCol = "BEHIND", col.orange
                    else
                        tag, tagCol = "FAR BEHIND", col.red
                    end
                    subText = string.format("Wave %d: %s HP vs %s expected", i, Utils.fmt(val1), Utils.fmt(val2))
                end
                break
            end
        end
        if FarmHub.every("simCardShares", 5) then
            local ok, res = pcall(Match.damageShares)
            local list = {}
            if ok and type(res) == "table" then
                for k, v in pairs(res) do
                    if v >= 0.01 then
                        table.insert(list, { n = Units.name(k):gsub(" %(.+%)", ""), v = v })
                    end
                end
            end
            table.sort(list, function(a, b) return a.v > b.v end)
            local top = {}
            for i = 1, math.min(4, #list) do
                table.insert(top, string.format("%s %d%%", list[i].n, math.floor(list[i].v * 100 + 0.5)))
            end
            GUI.simShares = #top > 0 and ("Damage: " .. table.concat(top, ", ")) or nil
        end
        return {
            title = titleStr,
            text = table.concat(parts, " · "),
            sub = subText .. (GUI.simShares and (" · " .. GUI.simShares) or ""),
            tag = tag,
            tagColor = tagCol
        }
    end
    local topMode = Modes.lastScored and Modes.lastScored[1]
    local simRe = topMode and Brain.simRes and Brain.simRes[topMode.key]
    local simTm = topMode and Brain.simTeam and Brain.simTeam[topMode.key]
    if not topMode then
        return { title = "Simulator", text = "Waiting for next mode scan", sub = "", tag = "" }
    end
    local pct = math.floor((tonumber(topMode.p) or 0) * 100 + 0.5)
    local tagStr = ""
    local tagCol = nil
    if simRe then
        if simRe.hopeless then
            tagStr = "HOPELESS"
            tagCol = col.red
        else
            tagStr = string.format("%d%%", pct)
            tagCol = (tonumber(topMode.p) or 0) >= 0.7 and col.green or col.orange
        end
    end
    return {
        title = "Simulator: " .. tostring(topMode.label),
        text = simRe and (tostring(simRe.margin) .. (simRe.playing and (" · " .. tostring(simRe.playing)) or "")) or "No reading yet for this mode",
        sub = simTm and type(simTm.names) == "table" and ("Team: " .. table.concat(simTm.names, ", ")) or "",
        tag = tagStr,
        tagColor = tagCol
    }
end

function GUI.planView(col)
    col = col or GUI.COL
    local data = { title = "Active Match Plan" }
    local running = Simulator and Simulator.progress
    local busy = running and running.running and (Utils.now() - (running.at or 0) < 180)
    local function setStep(text, color)
        data["Next step"] = text
        data.stepColor = color
    end
    if busy then
        setStep("Search running...", col.gold)
    elseif not (Config.sim and Config.simTeams) then
        setStep("Enable Battle Simulator and Plan Best 6-Unit Squads to use the planner.", col.red)
    elseif App.where ~= "lobby" then
        setStep("In match. Lobby buttons activate when you return to the lobby.", col.sub)
    end
    if busy then
        data.progress = running.frac or 0
        data.state = string.format("%s · %d%% · %ds · %s", tostring(running.label), math.floor((running.frac or 0) * 100 + 0.5), math.floor(Utils.now() - (running.started or Utils.now())), tostring(running.text))
    elseif running and running.started then
        data.state = string.format("Last search: %s (%ds)", tostring(running.label), math.floor((running.at or running.started) - running.started))
    else
        data.state = "Ready"
    end
    local equipped = {}
    for _, unit in ipairs(Units.equipped()) do
        table.insert(equipped, { name = Units.name(unit.id), role = Units.roleName(unit.id) })
    end
    data["Current team"] = #equipped > 0 and GUI.slotLines(equipped) or "No unit equipped"
    local nextMode = Modes.lastScored and Modes.lastScored[1]
    local plan = FarmHub.manualPlan and FarmHub.manualPlan.team
    if not plan and nextMode and Brain.simTeam then
        plan = Brain.simTeam[nextMode.key]
    end
    if not plan and Brain.simTeam then
        for _, value in pairs(Brain.simTeam) do
            if type(value) == "table" and (not plan or (value.at or 0) > (plan.at or 0)) then
                plan = value
            end
        end
    end
    if type(plan) ~= "table" then
        data["Map & mode"] = nextMode and (tostring(nextMode.label) .. " · not planned yet") or "Waiting for next mode"
        if not data["Next step"] then
            setStep("Press Simulate Now to calculate the strongest team (10-30s).", col.accent)
        end
        return data
    end
    data["Map & mode"] = tostring(plan.label or (nextMode and nextMode.label) or "Planned stage")
    data["Planned team"] = type(plan.names) == "table" and table.concat(plan.names, ", ") or "Same as current"
    if not data["Next step"] then
        if plan.better and Config.autoTeam and Config.play then
            setStep("Auto-Equip is ON: planned team equips automatically before runs.", col.green)
        elseif plan.better then
            setStep("Better team found! Press Equip Best Team or enable Auto-Equip Best Team.", col.accent)
        else
            setStep("Your equipped team is already the strongest found.", col.green)
        end
    end
    return data
end

function GUI.homeRows()
    local function trimLine(arg1)
        local match = tostring(arg1 or ""):match("^[^\n]+") or ""
        if #match > 120 then
            match = match:sub(1, 117) .. "..."
        end
        return match
    end
    local function safeCall(fn)
        local ok, res = pcall(fn)
        if ok then
            return trimLine(res)
        end
        return "..."
    end
    local list = {}
    if Modes and Modes.onlyOn and Modes.onlyOn() then
        list.Playing = "Only " .. Modes.onlyText()
    else
        list.Playing = "Smart: best gems/min among active modes"
    end
    list.Focus = safeCall(FarmHub.focusText)
    list.Training = Config.trainTakedowns and safeCall(Training.text) or "Off"
    list.Snipe = (Config.snipeOn and Config.snipeUnit ~= "") and safeCall(FarmHub.snipeText) or "Off"
    if Config.fuseUnit ~= "" then
        local ok, res = pcall(GUI.lbStatus)
        list["Limit Break"] = ok and trimLine(res.title .. " · " .. tostring(res.tag):lower()) or "..."
    else
        list["Limit Break"] = "No unit selected"
    end
    list.Team = Config.team and safeCall(Strategy.text) or "Off"
    return list
end

function GUI.pickBestTeam(notifyFn)
    local function tell(title, text, tone)
        if type(notifyFn) == "function" then
            pcall(notifyFn, title, text, tone)
        elseif App and type(App.notify) == "function" then
            pcall(App.notify, title, text, tone)
        end
    end
    if App.where ~= "lobby" then
        return tell("Team", "Works in the lobby", "warning")
    end
    FarmHub.recalculatePlan(tell)
    local manual = FarmHub.manualPlan
    local team = manual and manual.team
    if not (team and team.better) then
        return
    end
    if team.targetProfile ~= Modes.ownedProfile(team.uuids) then
        return tell("Team", "Your units changed during the search. Press Pick Best Team again.", "warning")
    end
    if FarmHub.equipTeam(team.uuids, "best team for " .. tostring(team.label) .. " (Pick Best Team)") then
        FarmHub.manualPlan = nil
        tell("Team", "Equipped: " .. table.concat(team.names or {}, ", "), "success")
    else
        tell("Team", "Game did not equip full team. Check Activity Log.", "warning")
    end
end

-- ============================================================================
-- Section B: Obsidian Precision Native Roblox UI Engine & Primitives
-- ============================================================================
local UI_PREFS_PATH = "AA_SmartFarm/ui_v240_prefs.json"
local UI_PROFILES_DIR = "AA_SmartFarm/profiles"

local function uiSafeService(name)
    local ok, svc = pcall(function()
        return game:GetService(name)
    end)
    if ok then
        return svc
    end
    return nil
end

local function uiGetParent()
    local okHui, hui = pcall(function()
        if type(gethui) == "function" then
            return gethui()
        end
        return nil
    end)
    if okHui and hui ~= nil then
        return hui
    end
    local coreGui = uiSafeService("CoreGui")
    if coreGui ~= nil then
        return coreGui
    end
    local okPg, pg = pcall(function()
        local pl = Players and Players.LocalPlayer
        if pl then
            return pl:FindFirstChild("PlayerGui") or pl:WaitForChild("PlayerGui", 3)
        end
        return nil
    end)
    if okPg and pg ~= nil then
        return pg
    end
    return nil
end

local function uiLoadPrefs()
    local defs = {
        toggleKey = "RightShift",
        uiScale = 1.0,
        uiOpacity = 0.96,
        accentId = "obsidian_blue",
        miniHudEnabled = true
    }
    pcall(function()
        if type(isfile) == "function" and type(readfile) == "function" and isfile(UI_PREFS_PATH) then
            local raw = readfile(UI_PREFS_PATH)
            local hs = uiSafeService("HttpService")
            if hs and type(raw) == "string" and #raw > 2 then
                local ok, dec = pcall(function() return hs:JSONDecode(raw) end)
                if ok and type(dec) == "table" then
                    if type(dec.toggleKey) == "string" and dec.toggleKey ~= "" then defs.toggleKey = dec.toggleKey end
                    if type(dec.uiScale) == "number" then defs.uiScale = math.max(0.75, math.min(1.25, dec.uiScale)) end
                    if type(dec.uiOpacity) == "number" then defs.uiOpacity = math.max(0.70, math.min(1.0, dec.uiOpacity)) end
                    if type(dec.accentId) == "string" and dec.accentId ~= "" then defs.accentId = dec.accentId end
                    if type(dec.miniHudEnabled) == "boolean" then defs.miniHudEnabled = dec.miniHudEnabled end
                end
            end
        end
    end)
    return defs
end

local function uiSavePrefs(prefs)
    pcall(function()
        if type(writefile) ~= "function" then
            return
        end
        if type(isfolder) == "function" and type(makefolder) == "function" and not isfolder("AA_SmartFarm") then
            makefolder("AA_SmartFarm")
        end
        local hs = uiSafeService("HttpService")
        if hs then
            writefile(UI_PREFS_PATH, hs:JSONEncode(prefs))
        end
    end)
end

local function uiClamp(v, lo, hi)
    if v < lo then return lo end
    if v > hi then return hi end
    return v
end

local function uiRoundStep(val, minV, maxV, step)
    local s = tonumber(step) or 1
    if s <= 0 then s = 1 end
    local snapped = minV + math.floor(((val - minV) / s) + 0.5) * s
    snapped = uiClamp(snapped, minV, maxV)
    if s < 1 then
        snapped = math.floor(snapped * 10000 + 0.5) / 10000
    end
    return snapped
end

local function uiFormatSlider(val, spec)
    local n = tonumber(val) or 0
    if spec and type(spec.formatFn) == "function" then
        local ok, s = pcall(spec.formatFn, n)
        if ok and type(s) == "string" then
            return s
        end
    end
    if spec and spec.kind == "pct" then
        return string.format("%d%%", math.floor(n * 100 + 0.5))
    end
    if spec and spec.kind == "sec" then
        return string.format("%ds", math.floor(n + 0.5))
    end
    if spec and spec.kind == "hrs" then
        if n <= 0 then return "Off" end
        return string.format("%dh", math.floor(n + 0.5))
    end
    if spec and spec.kind == "fmt" then
        if Utils and type(Utils.fmt) == "function" then
            return Utils.fmt(n)
        end
        return tostring(math.floor(n + 0.5))
    end
    if spec and spec.step and spec.step < 1 then
        return string.format("%.2f", n)
    end
    return tostring(math.floor(n + 0.5))
end

local function uiIsRunning()
    return Config.master == true and Config.play == true and (not Brain.holdLobby)
end

local function uiCountActiveAI()
    local n = 0
    if Config.aiPlacement ~= false then n = n + 1 end
    if Config.aiTargeting ~= false then n = n + 1 end
    if Config.aiEconomy ~= false then n = n + 1 end
    if Config.aiTactics ~= false then n = n + 2 end
    if Config.aiTeam ~= false then n = n + 1 end
    if Config.aiCards ~= false then n = n + 1 end
    return n
end

-- Create the UI engine builder context (instantiated cleanly inside GUI.build())
local function createUiEngine()
    local P = GUI.PALETTE
    local TweenService = uiSafeService("TweenService")
    local UIS = uiSafeService("UserInputService")
    local prefs = uiLoadPrefs()

    local E = {
        prefs = prefs,
        destroyed = false,
        conns = {},
        accentBindings = {},
        softAccentBindings = {},
        searchItems = {},
        tabs = {},
        tabButtons = {},
        subPillMap = {},
        activeTab = "start",
        activeSubPill = {},
        searchQuery = "",
        minimized = false,
        hidden = false,
        advancedOpen = false,
        listeningKeybind = false,
        openDropdown = nil,
        toasts = {},
        toastSeq = 0,
        controlHandles = {},
        configHandles = {},
        modePillHandles = {},
        jobPillHandles = {},
        screenGui = nil,
        mainFrame = nil,
        uiScaleObj = nil,
        miniHud = nil,
        searchBox = nil,
        searchResultsFrame = nil,
        searchEmptyLabel = nil,
        searchCountLabel = nil,
        contentHost = nil,
        toastContainer = nil,
        accentColor = P.accent,
        accentSoft = P.accentSoft
    }

    local function applyAccentColorsFromId(accentId)
        for _, preset in ipairs(GUI.ACCENT_PRESETS) do
            if preset.id == accentId then
                E.accentColor = preset.color
                E.accentSoft = preset.soft
                GUI.PALETTE.accent = preset.color
                GUI.PALETTE.accentSoft = preset.soft
                GUI.COL.accent = preset.color
                return
            end
        end
    end
    applyAccentColorsFromId(prefs.accentId)

    local function trackConn(signal, fn)
        if E.destroyed or not signal then
            return nil
        end
        local ok, conn = pcall(function()
            return signal:Connect(function(...)
                if E.destroyed then
                    return
                end
                fn(...)
            end)
        end)
        if ok and conn then
            table.insert(E.conns, conn)
            return conn
        end
        return nil
    end
    E.trackConn = trackConn

    local function disconnectAll()
        for i = 1, #E.conns do
            local c = E.conns[i]
            if c then
                pcall(function() c:Disconnect() end)
            end
        end
        E.conns = {}
    end
    E.disconnectAll = disconnectAll

    local function safeTween(inst, props, dur)
        if E.destroyed or not inst then
            return
        end
        local d = dur or 0.15
        if d > 0 and TweenService then
            local ok = pcall(function()
                local info = TweenInfo.new(d, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
                local tw = TweenService:Create(inst, info, props)
                tw:Play()
            end)
            if ok then
                return
            end
        end
        for k, v in pairs(props) do
            pcall(function() inst[k] = v end)
        end
    end
    E.safeTween = safeTween

    local function make(className, props, parent)
        local inst = Instance.new(className)
        if className == "Frame" or className == "TextLabel" or className == "TextButton" or className == "TextBox" or className == "ScrollingFrame" then
            pcall(function() inst.BorderSizePixel = 0 end)
        end
        if className == "TextButton" then
            pcall(function() inst.AutoButtonColor = false end)
        end
        if props then
            for k, v in pairs(props) do
                pcall(function() inst[k] = v end)
            end
        end
        if parent then
            pcall(function() inst.Parent = parent end)
        end
        return inst
    end
    E.make = make

    local function addCorner(parent, radius)
        return make("UICorner", { CornerRadius = UDim.new(0, radius or 8) }, parent)
    end
    E.addCorner = addCorner

    local function addStroke(parent, color, thickness, transparency)
        return make("UIStroke", {
            Color = color or P.stroke,
            Thickness = thickness or 1,
            Transparency = transparency or 0
        }, parent)
    end
    E.addStroke = addStroke

    local function addPad(parent, top, right, bottom, left)
        return make("UIPadding", {
            PaddingTop = UDim.new(0, top or 0),
            PaddingRight = UDim.new(0, right or top or 0),
            PaddingBottom = UDim.new(0, bottom or top or 0),
            PaddingLeft = UDim.new(0, left or right or top or 0)
        }, parent)
    end
    E.addPad = addPad

    local function addList(parent, padding, dir, hAlign)
        return make("UIListLayout", {
            Padding = UDim.new(0, padding or 6),
            FillDirection = dir or Enum.FillDirection.Vertical,
            HorizontalAlignment = hAlign or Enum.HorizontalAlignment.Left,
            SortOrder = Enum.SortOrder.LayoutOrder
        }, parent)
    end
    E.addList = addList

    local function bindAccent(inst, prop, isSoft)
        local entry = { inst = inst, prop = prop }
        if isSoft then
            table.insert(E.softAccentBindings, entry)
            pcall(function() inst[prop] = E.accentSoft end)
        else
            table.insert(E.accentBindings, entry)
            pcall(function() inst[prop] = E.accentColor end)
        end
    end
    E.bindAccent = bindAccent

    function E.refreshAccentBindings()
        for _, b in ipairs(E.accentBindings) do
            pcall(function() b.inst[b.prop] = E.accentColor end)
        end
        for _, b in ipairs(E.softAccentBindings) do
            pcall(function() b.inst[b.prop] = E.accentSoft end)
        end
        if E.onThemeChanged then
            pcall(E.onThemeChanged)
        end
    end

    local function makeDraggable(handle, target)
        local dragging = false
        local dragStart = nil
        local startPos = nil
        trackConn(handle.InputBegan, function(input)
            local ok, isDrag = pcall(function()
                return input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch
            end)
            if ok and isDrag then
                dragging = true
                pcall(function()
                    dragStart = input.Position
                    startPos = target.Position
                end)
            end
        end)
        if UIS then
            trackConn(UIS.InputChanged, function(input)
                if not dragging or not dragStart or not startPos then
                    return
                end
                local ok, isMove = pcall(function()
                    return input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch
                end)
                if ok and isMove then
                    pcall(function()
                        local delta = input.Position - dragStart
                        local sc = (E.uiScaleObj and E.uiScaleObj.Scale) or 1
                        if sc <= 0.05 then sc = 1 end
                        target.Position = UDim2.new(
                            startPos.X.Scale,
                            startPos.X.Offset + (delta.X / sc),
                            startPos.Y.Scale,
                            startPos.Y.Offset + (delta.Y / sc)
                        )
                    end)
                end
            end)
            trackConn(UIS.InputEnded, function(input)
                if not dragging then
                    return
                end
                local ok, isEnd = pcall(function()
                    return input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch
                end)
                if ok and isEnd then
                    dragging = false
                end
            end)
        end
    end
    E.makeDraggable = makeDraggable

    function E.updateScale()
        if E.destroyed or not E.uiScaleObj then
            return
        end
        local baseScale = 1.0
        pcall(function()
            local cam = workspace and workspace.CurrentCamera
            if cam and cam.ViewportSize then
                local vx = cam.ViewportSize.X
                local vy = cam.ViewportSize.Y
                if vx > 100 and vy > 100 then
                    baseScale = uiClamp(math.min(vx / 960, vy / 640), 0.65, 1.25)
                end
            end
        end)
        local finalScale = uiClamp(baseScale * (E.prefs.uiScale or 1.0), 0.65, 1.35)
        pcall(function() E.uiScaleObj.Scale = finalScale end)
    end

    function E.updateOpacity()
        if E.destroyed or not E.mainFrame then
            return
        end
        local op = uiClamp(E.prefs.uiOpacity or 0.96, 0.70, 1.0)
        pcall(function()
            E.mainFrame.BackgroundTransparency = 1 - op
        end)
    end

    -- Toast Notifications (wired to App.notify)
    function E.notify(title, text, tone)
        if E.destroyed or not E.toastContainer then
            return
        end
        E.toastSeq = E.toastSeq + 1
        local tColor = E.accentColor
        if tone == "success" then
            tColor = P.success
        elseif tone == "warning" then
            tColor = P.warning
        elseif tone == "error" then
            tColor = P.danger
        elseif tone == "info" then
            tColor = E.accentColor
        end

        while #E.toasts >= 4 do
            local oldest = table.remove(E.toasts, 1)
            if oldest and oldest.frame then
                pcall(function() oldest.frame:Destroy() end)
            end
        end

        local card = make("Frame", {
            Name = "Toast_" .. tostring(E.toastSeq),
            Size = UDim2.new(1, 0, 0, 56),
            BackgroundColor3 = P.bgSurface,
            BackgroundTransparency = 0.04,
            LayoutOrder = E.toastSeq
        }, E.toastContainer)
        addCorner(card, 10)
        addStroke(card, tColor, 1, 0.35)

        local bar = make("Frame", {
            Size = UDim2.new(0, 4, 1, -12),
            Position = UDim2.new(0, 6, 0, 6),
            BackgroundColor3 = tColor
        }, card)
        addCorner(bar, 2)

        make("TextLabel", {
            Size = UDim2.new(1, -24, 0, 18),
            Position = UDim2.new(0, 18, 0, 8),
            BackgroundTransparency = 1,
            Font = Enum.Font.GothamBold,
            Text = tostring(title or "Airflow"),
            TextColor3 = P.textPrimary,
            TextSize = 12,
            TextXAlignment = Enum.TextXAlignment.Left,
            TextTruncate = Enum.TextTruncate.AtEnd
        }, card)

        make("TextLabel", {
            Size = UDim2.new(1, -24, 0, 24),
            Position = UDim2.new(0, 18, 0, 26),
            BackgroundTransparency = 1,
            Font = Enum.Font.Gotham,
            Text = GUI.shortLine(tostring(text or ""), 95),
            TextColor3 = P.textSecondary,
            TextSize = 11,
            TextXAlignment = Enum.TextXAlignment.Left,
            TextWrapped = true
        }, card)

        local entry = { frame = card, seq = E.toastSeq }
        table.insert(E.toasts, entry)

        task.spawn(function()
            task.wait(4)
            if E.destroyed then
                return
            end
            for idx, item in ipairs(E.toasts) do
                if item == entry then
                    table.remove(E.toasts, idx)
                    break
                end
            end
            pcall(function() card:Destroy() end)
        end)
    end

    -- Helper: Make dual dot/colon callable handle
    local function registerHandle(uiKey, configKey, handle)
        if uiKey and uiKey ~= "" then
            GUI.UI[uiKey] = handle
            E.controlHandles[uiKey] = handle
        end
        if configKey and configKey ~= "" then
            if not GUI.UI[configKey] then
                GUI.UI[configKey] = handle
            end
            if not E.configHandles[configKey] then
                E.configHandles[configKey] = {}
            end
            table.insert(E.configHandles[configKey], handle)
        end
    end
    E.registerHandle = registerHandle

    -- Global Search Registration
    local function registerSearchItem(meta)
        local parts = {
            tostring(meta.label or ""),
            tostring(meta.tooltip or ""),
            tostring(meta.breadcrumb or ""),
            tostring(meta.configKey or ""),
            tostring(meta.id or ""),
            tostring(meta.keywords or "")
        }
        meta.haystack = string.lower(table.concat(parts, " "))
        table.insert(E.searchItems, meta)
    end
    E.registerSearchItem = registerSearchItem

    function E.applySearch(query)
        local q = tostring(query or "")
        q = q:gsub("^%s+", ""):gsub("%s+$", "")
        E.searchQuery = q
        local lowerQ = string.lower(q)

        if lowerQ == "" then
            -- Restore all moved rows back to original parents
            for _, item in ipairs(E.searchItems) do
                if item.frame and item.origParent then
                    pcall(function()
                        if item.frame.Parent ~= item.origParent then
                            item.frame.Parent = item.origParent
                        end
                        item.frame.LayoutOrder = item.origOrder
                        item.frame.Visible = true
                    end)
                end
                if item.badge then
                    pcall(function() item.badge.Visible = false end)
                end
            end
            if E.searchResultsFrame then
                E.searchResultsFrame.Visible = false
            end
            if E.contentHost then
                E.contentHost.Visible = true
            end
            return 0
        end

        -- Show search results panel, hide standard tab pages
        if E.contentHost then
            E.contentHost.Visible = false
        end
        if E.searchResultsFrame then
            E.searchResultsFrame.Visible = true
        end

        local matches = 0
        local tokens = {}
        for tok in string.gmatch(lowerQ, "%S+") do
            table.insert(tokens, tok)
        end

        for _, item in ipairs(E.searchItems) do
            local hit = true
            for _, tok in ipairs(tokens) do
                if not string.find(item.haystack, tok, 1, true) then
                    hit = false
                    break
                end
            end
            if hit and item.frame and E.searchResultsList then
                matches = matches + 1
                pcall(function()
                    item.frame.Parent = E.searchResultsList
                    item.frame.LayoutOrder = matches
                    item.frame.Visible = true
                end)
                if item.badge then
                    pcall(function() item.badge.Visible = true end)
                end
            elseif item.frame and item.origParent then
                pcall(function()
                    if item.frame.Parent ~= item.origParent then
                        item.frame.Parent = item.origParent
                    end
                    item.frame.LayoutOrder = item.origOrder
                end)
                if item.badge then
                    pcall(function() item.badge.Visible = false end)
                end
            end
        end

        if E.searchCountLabel then
            E.searchCountLabel.Text = string.format("Search results for \"%s\" (%d matches)", q, matches)
        end
        if E.searchEmptyLabel then
            E.searchEmptyLabel.Visible = (matches == 0)
        end
        return matches
    end

    -- ========================================================================
    -- Declarative Card & Control Builders
    -- ========================================================================
    function E.createCard(parent, title, subtitle, order)
        local card = make("Frame", {
            Name = "Card_" .. tostring(title or "Section"),
            Size = UDim2.new(1, 0, 0, 0),
            AutomaticSize = Enum.AutomaticSize.Y,
            BackgroundColor3 = P.bgSurface,
            LayoutOrder = order or 1
        }, parent)
        addCorner(card, 10)
        addStroke(card, P.stroke, 1, 0)
        addPad(card, 12, 14, 12, 14)
        addList(card, 6)

        if title and title ~= "" then
            local hdr = make("Frame", {
                Name = "CardHeader",
                Size = UDim2.new(1, 0, 0, subtitle and subtitle ~= "" and 34 or 20),
                BackgroundTransparency = 1,
                LayoutOrder = 0
            }, card)
            make("TextLabel", {
                Size = UDim2.new(1, 0, 0, 18),
                BackgroundTransparency = 1,
                Font = Enum.Font.GothamBold,
                Text = title,
                TextColor3 = P.textPrimary,
                TextSize = 13,
                TextXAlignment = Enum.TextXAlignment.Left
            }, hdr)
            if subtitle and subtitle ~= "" then
                make("TextLabel", {
                    Size = UDim2.new(1, 0, 0, 14),
                    Position = UDim2.new(0, 0, 0, 19),
                    BackgroundTransparency = 1,
                    Font = Enum.Font.Gotham,
                    Text = subtitle,
                    TextColor3 = P.textSecondary,
                    TextSize = 11,
                    TextXAlignment = Enum.TextXAlignment.Left,
                    TextTruncate = Enum.TextTruncate.AtEnd
                }, hdr)
            end
        end

        local body = make("Frame", {
            Name = "CardBody",
            Size = UDim2.new(1, 0, 0, 0),
            AutomaticSize = Enum.AutomaticSize.Y,
            BackgroundTransparency = 1,
            LayoutOrder = 1
        }, card)
        addList(body, 6)

        return card, body
    end

    local function makeRowBase(parent, opts)
        local order = opts.order or (#parent:GetChildren() + 1)
        local h = opts.height or 44
        local row = make("Frame", {
            Name = "Row_" .. tostring(opts.id or opts.label or order),
            Size = UDim2.new(1, 0, 0, h),
            BackgroundColor3 = P.bgElevated,
            BackgroundTransparency = 0.45,
            LayoutOrder = order
        }, parent)
        addCorner(row, 8)
        addStroke(row, P.stroke, 1, 0.35)

        local leftWidth = opts.leftWidth or -110
        local titleLbl = make("TextLabel", {
            Name = "Title",
            Size = UDim2.new(1, leftWidth, 0, 17),
            Position = UDim2.new(0, 12, 0, opts.tooltip and opts.tooltip ~= "" and 6 or 13),
            BackgroundTransparency = 1,
            Font = Enum.Font.GothamMedium,
            Text = tostring(opts.label or ""),
            TextColor3 = P.textPrimary,
            TextSize = 12,
            TextXAlignment = Enum.TextXAlignment.Left,
            TextTruncate = Enum.TextTruncate.AtEnd
        }, row)

        local subLbl = nil
        if opts.tooltip and opts.tooltip ~= "" then
            subLbl = make("TextLabel", {
                Name = "Helper",
                Size = UDim2.new(1, leftWidth, 0, 14),
                Position = UDim2.new(0, 12, 0, 24),
                BackgroundTransparency = 1,
                Font = Enum.Font.Gotham,
                Text = tostring(opts.tooltip),
                TextColor3 = P.textSecondary,
                TextSize = 11,
                TextXAlignment = Enum.TextXAlignment.Left,
                TextTruncate = Enum.TextTruncate.AtEnd
            }, row)
        end

        local badge = make("TextLabel", {
            Name = "SearchBadge",
            Visible = false,
            Size = UDim2.new(0, 150, 0, 16),
            Position = UDim2.new(1, -260, 0, 4),
            BackgroundColor3 = E.accentSoft,
            Font = Enum.Font.GothamBold,
            Text = tostring(opts.breadcrumb or ""),
            TextColor3 = E.accentColor,
            TextSize = 10,
            TextXAlignment = Enum.TextXAlignment.Center,
            TextTruncate = Enum.TextTruncate.AtEnd
        }, row)
        addCorner(badge, 4)

        registerSearchItem({
            id = opts.id,
            label = opts.label,
            tooltip = opts.tooltip,
            breadcrumb = opts.breadcrumb,
            configKey = opts.configKey,
            keywords = opts.keywords,
            isAdvanced = opts.isAdvanced == true,
            frame = row,
            origParent = parent,
            origOrder = order,
            badge = badge
        })

        return row, titleLbl, subLbl, badge
    end

    -- 1. Toggle Control
    function E.addToggle(parent, opts)
        local row = makeRowBase(parent, {
            id = opts.id,
            label = opts.label,
            tooltip = opts.tooltip,
            breadcrumb = opts.breadcrumb,
            configKey = opts.configKey,
            keywords = opts.keywords,
            isAdvanced = opts.isAdvanced,
            leftWidth = -72,
            height = 44
        })

        local curVal = false
        if opts.default ~= nil then
            curVal = opts.default == true
        elseif opts.configKey then
            local bv = uiGetBase(opts.configKey)
            if opts.invert then
                curVal = not (bv == true)
            else
                curVal = (bv == true)
            end
        end

        local track = make("TextButton", {
            Name = "ToggleTrack",
            Size = UDim2.new(0, 42, 0, 22),
            Position = UDim2.new(1, -54, 0.5, -11),
            BackgroundColor3 = curVal and P.success or P.strokeStrong,
            Text = ""
        }, row)
        addCorner(track, 999)

        local knob = make("Frame", {
            Name = "Knob",
            Size = UDim2.new(0, 16, 0, 16),
            Position = curVal and UDim2.new(1, -19, 0.5, -8) or UDim2.new(0, 3, 0.5, -8),
            BackgroundColor3 = P.textPrimary
        }, track)
        addCorner(knob, 999)

        local handle = { _kind = "Toggle", _value = curVal, _frame = row, _track = track }

        local function render(v, animate)
            local d = animate and 0.14 or 0
            safeTween(track, { BackgroundColor3 = v and P.success or P.strokeStrong }, d)
            safeTween(knob, { Position = v and UDim2.new(1, -19, 0.5, -8) or UDim2.new(0, 3, 0.5, -8) }, d)
        end

        function handle.Get(a)
            return handle._value
        end

        function handle.Set(a, b, c)
            local val, silent
            if a == handle then
                val, silent = b, c
            else
                val, silent = a, b
            end
            local nextVal = (val == true)
            handle._value = nextVal
            render(nextVal, not silent)
            if not silent then
                if opts.configKey and not opts.customWrite then
                    local storeVal = nextVal
                    if opts.invert then
                        storeVal = not nextVal
                    end
                    uiSetBase(opts.configKey, storeVal)
                end
                if type(opts.onChange) == "function" then
                    pcall(opts.onChange, nextVal)
                end
            end
        end

        trackConn(track.MouseButton1Click, function()
            handle.Set(not handle._value, false)
        end)

        registerHandle(opts.uiKey, opts.invert and nil or opts.configKey, handle)
        return handle
    end

    -- 2. Slider Control (with direct drag + quick -/+ nudge buttons for Lune & mobile precision!)
    function E.addSlider(parent, opts)
        local row = makeRowBase(parent, {
            id = opts.id,
            label = opts.label,
            tooltip = opts.tooltip,
            breadcrumb = opts.breadcrumb,
            configKey = opts.configKey,
            keywords = opts.keywords,
            isAdvanced = opts.isAdvanced,
            leftWidth = -140,
            height = 60
        })

        local minV = tonumber(opts.min) or 0
        local maxV = tonumber(opts.max) or 100
        local step = tonumber(opts.step) or 1
        local curVal = opts.default
        if curVal == nil and opts.configKey then
            curVal = tonumber(uiGetBase(opts.configKey))
        end
        if curVal == nil then
            curVal = minV
        end
        curVal = uiRoundStep(curVal, minV, maxV, step)

        local valLbl = make("TextLabel", {
            Name = "ValueLabel",
            Size = UDim2.new(0, 82, 0, 18),
            Position = UDim2.new(1, -126, 0, 7),
            BackgroundTransparency = 1,
            Font = Enum.Font.Code,
            Text = uiFormatSlider(curVal, opts),
            TextColor3 = E.accentColor,
            TextSize = 12,
            TextXAlignment = Enum.TextXAlignment.Right
        }, row)
        bindAccent(valLbl, "TextColor3", false)

        local minusBtn = make("TextButton", {
            Name = "MinusBtn",
            Size = UDim2.new(0, 18, 0, 18),
            Position = UDim2.new(1, -40, 0, 7),
            BackgroundColor3 = P.bgSurface,
            Font = Enum.Font.GothamBold,
            Text = "-",
            TextColor3 = P.textPrimary,
            TextSize = 12
        }, row)
        addCorner(minusBtn, 4)
        addStroke(minusBtn, P.stroke, 1, 0)

        local plusBtn = make("TextButton", {
            Name = "PlusBtn",
            Size = UDim2.new(0, 18, 0, 18),
            Position = UDim2.new(1, -20, 0, 7),
            BackgroundColor3 = P.bgSurface,
            Font = Enum.Font.GothamBold,
            Text = "+",
            TextColor3 = P.textPrimary,
            TextSize = 12
        }, row)
        addCorner(plusBtn, 4)
        addStroke(plusBtn, P.stroke, 1, 0)

        local barBg = make("TextButton", {
            Name = "SliderTrack",
            Size = UDim2.new(1, -24, 0, 8),
            Position = UDim2.new(0, 12, 0, 44),
            BackgroundColor3 = P.bgSurface,
            Text = ""
        }, row)
        addCorner(barBg, 999)

        local pct0 = 0
        if maxV > minV then
            pct0 = uiClamp((curVal - minV) / (maxV - minV), 0, 1)
        end
        local fill = make("Frame", {
            Name = "Fill",
            Size = UDim2.new(pct0, 0, 1, 0),
            BackgroundColor3 = E.accentColor
        }, barBg)
        addCorner(fill, 999)
        bindAccent(fill, "BackgroundColor3", false)

        local handle = { _kind = "Slider", _value = curVal, _frame = row }

        local function render(v)
            local p = 0
            if maxV > minV then
                p = uiClamp((v - minV) / (maxV - minV), 0, 1)
            end
            fill.Size = UDim2.new(p, 0, 1, 0)
            valLbl.Text = uiFormatSlider(v, opts)
        end

        function handle.Get(a)
            return handle._value
        end

        function handle.Set(a, b, c)
            local val, silent
            if a == handle then
                val, silent = b, c
            else
                val, silent = a, b
            end
            local snapped = uiRoundStep(tonumber(val) or minV, minV, maxV, step)
            handle._value = snapped
            render(snapped)
            if not silent then
                if opts.configKey and not opts.customWrite then
                    uiSetBase(opts.configKey, snapped)
                end
                if type(opts.onChange) == "function" then
                    pcall(opts.onChange, snapped)
                end
            end
        end

        local sliding = false
        local function setFromX(absX)
            local ok, ratio = pcall(function()
                local bx = barBg.AbsolutePosition.X
                local bw = barBg.AbsoluteSize.X
                if bw <= 1 then return 0 end
                return uiClamp((absX - bx) / bw, 0, 1)
            end)
            if ok then
                handle.Set(minV + ratio * (maxV - minV), false)
            end
        end

        trackConn(barBg.InputBegan, function(input)
            local ok, isClick = pcall(function()
                return input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch
            end)
            if ok and isClick then
                sliding = true
                pcall(function() setFromX(input.Position.X) end)
            end
        end)
        if UIS then
            trackConn(UIS.InputChanged, function(input)
                if not sliding then return end
                local ok, isMove = pcall(function()
                    return input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch
                end)
                if ok and isMove then
                    pcall(function() setFromX(input.Position.X) end)
                end
            end)
            trackConn(UIS.InputEnded, function(input)
                if not sliding then return end
                local ok, isEnd = pcall(function()
                    return input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch
                end)
                if ok and isEnd then
                    sliding = false
                end
            end)
        end

        trackConn(minusBtn.MouseButton1Click, function()
            handle.Set(handle._value - step, false)
        end)
        trackConn(plusBtn.MouseButton1Click, function()
            handle.Set(handle._value + step, false)
        end)

        registerHandle(opts.uiKey, opts.configKey, handle)
        return handle
    end

    -- 3. Dropdown Control (Inline expandable list so it never clips or fails in Lune)
    function E.addDropdown(parent, opts)
        local order = opts.order or (#parent:GetChildren() + 1)
        local wrap = make("Frame", {
            Name = "Drop_" .. tostring(opts.id or opts.label or order),
            Size = UDim2.new(1, 0, 0, 44),
            AutomaticSize = Enum.AutomaticSize.Y,
            BackgroundColor3 = P.bgElevated,
            BackgroundTransparency = 0.45,
            LayoutOrder = order
        }, parent)
        addCorner(wrap, 8)
        addStroke(wrap, P.stroke, 1, 0.35)
        addList(wrap, 0)

        local top = make("Frame", {
            Name = "Header",
            Size = UDim2.new(1, 0, 0, 44),
            BackgroundTransparency = 1,
            LayoutOrder = 1
        }, wrap)

        make("TextLabel", {
            Size = UDim2.new(0.46, -12, 0, 17),
            Position = UDim2.new(0, 12, 0, opts.tooltip and opts.tooltip ~= "" and 6 or 13),
            BackgroundTransparency = 1,
            Font = Enum.Font.GothamMedium,
            Text = tostring(opts.label or ""),
            TextColor3 = P.textPrimary,
            TextSize = 12,
            TextXAlignment = Enum.TextXAlignment.Left,
            TextTruncate = Enum.TextTruncate.AtEnd
        }, top)

        if opts.tooltip and opts.tooltip ~= "" then
            make("TextLabel", {
                Size = UDim2.new(0.46, -12, 0, 14),
                Position = UDim2.new(0, 12, 0, 24),
                BackgroundTransparency = 1,
                Font = Enum.Font.Gotham,
                Text = tostring(opts.tooltip),
                TextColor3 = P.textSecondary,
                TextSize = 11,
                TextXAlignment = Enum.TextXAlignment.Left,
                TextTruncate = Enum.TextTruncate.AtEnd
            }, top)
        end

        local badge = make("TextLabel", {
            Name = "SearchBadge",
            Visible = false,
            Size = UDim2.new(0, 120, 0, 15),
            Position = UDim2.new(0.46, 0, 0, 2),
            BackgroundColor3 = E.accentSoft,
            Font = Enum.Font.GothamBold,
            Text = tostring(opts.breadcrumb or ""),
            TextColor3 = E.accentColor,
            TextSize = 9,
            TextTruncate = Enum.TextTruncate.AtEnd
        }, top)
        addCorner(badge, 4)

        local selBtn = make("TextButton", {
            Name = "SelectButton",
            Size = UDim2.new(0.52, -16, 0, 28),
            Position = UDim2.new(0.48, 4, 0.5, -14),
            BackgroundColor3 = P.bgSurface,
            Font = Enum.Font.Gotham,
            Text = "Select...",
            TextColor3 = P.textPrimary,
            TextSize = 11,
            TextXAlignment = Enum.TextXAlignment.Left,
            TextTruncate = Enum.TextTruncate.AtEnd
        }, top)
        addCorner(selBtn, 6)
        addStroke(selBtn, P.strokeStrong, 1, 0.25)
        addPad(selBtn, 0, 22, 0, 10)

        local chev = make("TextLabel", {
            Size = UDim2.new(0, 18, 1, 0),
            Position = UDim2.new(1, -20, 0, 0),
            BackgroundTransparency = 1,
            Font = Enum.Font.GothamBold,
            Text = "v",
            TextColor3 = P.textSecondary,
            TextSize = 10
        }, selBtn)

        local menu = make("ScrollingFrame", {
            Name = "DropMenu",
            Visible = false,
            Size = UDim2.new(1, 0, 0, 0),
            CanvasSize = UDim2.new(0, 0, 0, 0),
            AutomaticCanvasSize = Enum.AutomaticSize.Y,
            ScrollBarThickness = 4,
            ScrollBarImageColor3 = P.strokeStrong,
            BackgroundColor3 = P.bgSubtle,
            LayoutOrder = 2
        }, wrap)
        addCorner(menu, 6)
        addPad(menu, 6, 8, 6, 8)
        addList(menu, 3)

        registerSearchItem({
            id = opts.id,
            label = opts.label,
            tooltip = opts.tooltip,
            breadcrumb = opts.breadcrumb,
            configKey = opts.configKey,
            keywords = opts.keywords,
            isAdvanced = opts.isAdvanced == true,
            frame = wrap,
            origParent = parent,
            origOrder = order,
            badge = badge
        })

        local handle = {
            _kind = "Dropdown",
            _options = {},
            _value = nil,
            _text = "",
            _open = false,
            _frame = wrap
        }

        local function normOpts(rawList)
            local out = {}
            for _, item in ipairs(rawList or {}) do
                if type(item) == "table" then
                    table.insert(out, { text = tostring(item.text or item.value or ""), value = item.value })
                else
                    table.insert(out, { text = tostring(item), value = item })
                end
            end
            return out
        end

        local function closeMenu()
            handle._open = false
            menu.Visible = false
            menu.Size = UDim2.new(1, 0, 0, 0)
            chev.Text = "v"
            if E.openDropdown == handle then
                E.openDropdown = nil
            end
        end
        handle.Close = closeMenu

        local function findLabelFor(val)
            for _, opt in ipairs(handle._options) do
                if opt.value == val or opt.text == val then
                    return opt.text, opt.value
                end
            end
            if handle._options[1] then
                return handle._options[1].text, handle._options[1].value
            end
            return tostring(val or ""), val
        end

        local function rebuildMenu()
            for _, ch in ipairs(menu:GetChildren()) do
                if ch:IsA("TextButton") then
                    pcall(function() ch:Destroy() end)
                end
            end
            for i, opt in ipairs(handle._options) do
                local isSel = (opt.value == handle._value)
                local btn = make("TextButton", {
                    Name = "Opt_" .. tostring(i),
                    Size = UDim2.new(1, 0, 0, 26),
                    BackgroundColor3 = isSel and E.accentSoft or P.bgSurface,
                    Font = isSel and Enum.Font.GothamBold or Enum.Font.Gotham,
                    Text = opt.text,
                    TextColor3 = isSel and E.accentColor or P.textPrimary,
                    TextSize = 11,
                    TextXAlignment = Enum.TextXAlignment.Left,
                    TextTruncate = Enum.TextTruncate.AtEnd,
                    LayoutOrder = i
                }, menu)
                addCorner(btn, 5)
                addPad(btn, 0, 8, 0, 8)
                trackConn(btn.MouseButton1Click, function()
                    handle.Set(opt.value, false)
                    closeMenu()
                end)
            end
        end

        function handle.Get(a)
            return handle._value
        end

        function handle.Set(a, b, c)
            local val, silent
            if a == handle then
                val, silent = b, c
            else
                val, silent = a, b
            end
            local txt, realVal = findLabelFor(val)
            handle._value = realVal
            handle._text = txt
            selBtn.Text = txt
            if handle._open then
                rebuildMenu()
            end
            if not silent then
                if opts.configKey and not opts.customWrite then
                    uiSetBase(opts.configKey, realVal)
                end
                if type(opts.onChange) == "function" then
                    pcall(opts.onChange, txt, realVal)
                end
            end
        end

        function handle.Refresh(a, b, c)
            local rawList, selectedVal
            if a == handle then
                rawList, selectedVal = b, c
            else
                rawList, selectedVal = a, b
            end
            handle._options = normOpts(rawList)
            if selectedVal ~= nil then
                local txt, realVal = findLabelFor(selectedVal)
                handle._value = realVal
                handle._text = txt
                selBtn.Text = txt
            else
                local txt, realVal = findLabelFor(handle._value)
                handle._value = realVal
                handle._text = txt
                selBtn.Text = txt
            end
            if handle._open then
                rebuildMenu()
            end
        end

        trackConn(selBtn.MouseButton1Click, function()
            if handle._open then
                closeMenu()
            else
                if E.openDropdown and E.openDropdown ~= handle then
                    pcall(E.openDropdown.Close)
                end
                E.openDropdown = handle
                handle._open = true
                rebuildMenu()
                local count = math.max(1, math.min(6, #handle._options))
                menu.Size = UDim2.new(1, 0, 0, count * 29 + 12)
                menu.Visible = true
                chev.Text = "^"
            end
        end)

        local initOpts = opts.options or {}
        local initVal = opts.default
        if initVal == nil and opts.configKey then
            initVal = uiGetBase(opts.configKey)
        end
        handle.Refresh(initOpts, initVal)
        registerHandle(opts.uiKey, opts.configKey, handle)
        return handle
    end

    -- 4. MultiSelect Pill Chips Control
    function E.addMultiSelect(parent, opts)
        local order = opts.order or (#parent:GetChildren() + 1)
        local wrap = make("Frame", {
            Name = "Multi_" .. tostring(opts.id or opts.label or order),
            Size = UDim2.new(1, 0, 0, 0),
            AutomaticSize = Enum.AutomaticSize.Y,
            BackgroundColor3 = P.bgElevated,
            BackgroundTransparency = 0.45,
            LayoutOrder = order
        }, parent)
        addCorner(wrap, 8)
        addStroke(wrap, P.stroke, 1, 0.35)
        addPad(wrap, 10, 12, 10, 12)
        addList(wrap, 6)

        local hdr = make("Frame", {
            Size = UDim2.new(1, 0, 0, opts.tooltip and opts.tooltip ~= "" and 32 or 18),
            BackgroundTransparency = 1,
            LayoutOrder = 1
        }, wrap)

        make("TextLabel", {
            Size = UDim2.new(1, -130, 0, 17),
            BackgroundTransparency = 1,
            Font = Enum.Font.GothamMedium,
            Text = tostring(opts.label or ""),
            TextColor3 = P.textPrimary,
            TextSize = 12,
            TextXAlignment = Enum.TextXAlignment.Left
        }, hdr)

        if opts.tooltip and opts.tooltip ~= "" then
            make("TextLabel", {
                Size = UDim2.new(1, 0, 0, 14),
                Position = UDim2.new(0, 0, 0, 18),
                BackgroundTransparency = 1,
                Font = Enum.Font.Gotham,
                Text = tostring(opts.tooltip),
                TextColor3 = P.textSecondary,
                TextSize = 11,
                TextXAlignment = Enum.TextXAlignment.Left,
                TextTruncate = Enum.TextTruncate.AtEnd
            }, hdr)
        end

        local badge = make("TextLabel", {
            Name = "SearchBadge",
            Visible = false,
            Size = UDim2.new(0, 125, 0, 15),
            Position = UDim2.new(1, -125, 0, 1),
            BackgroundColor3 = E.accentSoft,
            Font = Enum.Font.GothamBold,
            Text = tostring(opts.breadcrumb or ""),
            TextColor3 = E.accentColor,
            TextSize = 9,
            TextTruncate = Enum.TextTruncate.AtEnd
        }, hdr)
        addCorner(badge, 4)

        local grid = make("Frame", {
            Name = "ChipGrid",
            Size = UDim2.new(1, 0, 0, 0),
            AutomaticSize = Enum.AutomaticSize.Y,
            BackgroundTransparency = 1,
            LayoutOrder = 2
        }, wrap)
        make("UIGridLayout", {
            CellSize = UDim2.new(0, 148, 0, 28),
            CellPadding = UDim2.new(0, 6, 0, 6),
            SortOrder = Enum.SortOrder.LayoutOrder
        }, grid)

        registerSearchItem({
            id = opts.id,
            label = opts.label,
            tooltip = opts.tooltip,
            breadcrumb = opts.breadcrumb,
            configKey = opts.configKey,
            keywords = opts.keywords,
            isAdvanced = opts.isAdvanced == true,
            frame = wrap,
            origParent = parent,
            origOrder = order,
            badge = badge
        })

        local handle = { _kind = "MultiSelect", _selected = {}, _chips = {}, _frame = wrap }

        local function paintChip(val)
            local chip = handle._chips[val]
            if not chip then return end
            local on = handle._selected[val] == true
            chip.btn.BackgroundColor3 = on and E.accentSoft or P.bgSurface
            chip.btn.TextColor3 = on and E.accentColor or P.textSecondary
            chip.stroke.Color = on and E.accentColor or P.stroke
        end

        function handle.Get(a)
            local out = {}
            for _, item in ipairs(opts.options or {}) do
                local val = type(item) == "table" and item.value or item
                if handle._selected[val] then
                    table.insert(out, val)
                end
            end
            return out
        end

        function handle.Set(a, b, c)
            local vals, silent
            if a == handle then
                vals, silent = b, c
            else
                vals, silent = a, b
            end
            handle._selected = {}
            if type(vals) == "table" then
                for _, v in ipairs(vals) do
                    handle._selected[v] = true
                end
            end
            for val, _ in pairs(handle._chips) do
                paintChip(val)
            end
            if not silent and type(opts.onChange) == "function" then
                pcall(opts.onChange, handle.Get())
            end
        end

        for i, item in ipairs(opts.options or {}) do
            local labelTxt = type(item) == "table" and tostring(item.text or item.value) or tostring(item)
            local val = type(item) == "table" and item.value or item
            local btn = make("TextButton", {
                Name = "Chip_" .. tostring(i),
                BackgroundColor3 = P.bgSurface,
                Font = Enum.Font.GothamMedium,
                Text = labelTxt,
                TextColor3 = P.textSecondary,
                TextSize = 11,
                TextTruncate = Enum.TextTruncate.AtEnd,
                LayoutOrder = i
            }, grid)
            addCorner(btn, 6)
            local st = addStroke(btn, P.stroke, 1, 0)
            handle._chips[val] = { btn = btn, stroke = st }
            trackConn(btn.MouseButton1Click, function()
                handle._selected[val] = not (handle._selected[val] == true)
                paintChip(val)
                if type(opts.onChange) == "function" then
                    pcall(opts.onChange, handle.Get())
                end
            end)
        end

        handle.Set(opts.default or {}, true)
        registerHandle(opts.uiKey, opts.configKey, handle)
        return handle
    end

    -- 5. Text Input Control
    function E.addInput(parent, opts)
        local row = makeRowBase(parent, {
            id = opts.id,
            label = opts.label,
            tooltip = opts.tooltip,
            breadcrumb = opts.breadcrumb,
            configKey = opts.configKey,
            keywords = opts.keywords,
            isAdvanced = opts.isAdvanced,
            leftWidth = -210,
            height = 48
        })

        local initVal = opts.default
        if initVal == nil and opts.configKey then
            initVal = tostring(uiGetBase(opts.configKey) or "")
        end
        initVal = tostring(initVal or "")

        local box = make("TextBox", {
            Name = "InputBox",
            Size = UDim2.new(0, 194, 0, 28),
            Position = UDim2.new(1, -206, 0.5, -14),
            BackgroundColor3 = P.bgSurface,
            Font = Enum.Font.Gotham,
            PlaceholderText = tostring(opts.placeholder or "Enter value..."),
            PlaceholderColor3 = P.textMuted,
            Text = initVal,
            TextColor3 = P.textPrimary,
            TextSize = 11,
            TextXAlignment = Enum.TextXAlignment.Left,
            ClearTextOnFocus = false
        }, row)
        addCorner(box, 6)
        addStroke(box, P.strokeStrong, 1, 0.25)
        addPad(box, 0, 8, 0, 8)

        local handle = { _kind = "Input", _value = initVal, _frame = row, _box = box }

        function handle.Get(a)
            return handle._value
        end

        function handle.Set(a, b, c)
            local val, silent
            if a == handle then
                val, silent = b, c
            else
                val, silent = a, b
            end
            local s = tostring(val or "")
            handle._value = s
            pcall(function() box.Text = s end)
            if not silent then
                if opts.configKey and not opts.customWrite then
                    uiSetBase(opts.configKey, s)
                end
                if type(opts.onChange) == "function" then
                    pcall(opts.onChange, s)
                end
            end
        end

        trackConn(box.FocusLost, function()
            handle.Set(box.Text, false)
        end)

        registerHandle(opts.uiKey, opts.configKey, handle)
        return handle
    end

    -- 6. Action Button Control
    function E.addButton(parent, opts)
        local row = makeRowBase(parent, {
            id = opts.id,
            label = opts.label,
            tooltip = opts.tooltip,
            breadcrumb = opts.breadcrumb,
            configKey = opts.configKey,
            keywords = opts.keywords,
            isAdvanced = opts.isAdvanced,
            leftWidth = -132,
            height = 44
        })

        local bg = E.accentColor
        if opts.tone == "danger" then
            bg = P.danger
        elseif opts.tone == "success" then
            bg = P.success
        elseif opts.tone == "warning" then
            bg = P.warning
        elseif opts.tone == "neutral" then
            bg = P.bgSurface
        end

        local btn = make("TextButton", {
            Name = "ActionBtn",
            Size = UDim2.new(0, 114, 0, 28),
            Position = UDim2.new(1, -124, 0.5, -14),
            BackgroundColor3 = bg,
            Font = Enum.Font.GothamBold,
            Text = tostring(opts.buttonText or "Run"),
            TextColor3 = P.textPrimary,
            TextSize = 11
        }, row)
        addCorner(btn, 6)
        if opts.tone == "neutral" then
            addStroke(btn, P.strokeStrong, 1, 0)
        elseif not opts.tone or opts.tone == "accent" then
            bindAccent(btn, "BackgroundColor3", false)
        end

        local handle = { _kind = "Button", _frame = row, _btn = btn }
        function handle.Trigger()
            if type(opts.onClick) == "function" then
                pcall(opts.onClick)
            end
        end
        trackConn(btn.MouseButton1Click, handle.Trigger)
        if opts.uiKey then
            registerHandle(opts.uiKey, nil, handle)
        end
        return handle
    end

    -- 7. Live Text Paragraph Control
    function E.addLiveText(parent, opts)
        local order = opts.order or (#parent:GetChildren() + 1)
        local box = make("Frame", {
            Name = "Live_" .. tostring(opts.id or order),
            Size = UDim2.new(1, 0, 0, 0),
            AutomaticSize = Enum.AutomaticSize.Y,
            BackgroundColor3 = P.bgSubtle,
            LayoutOrder = order
        }, parent)
        addCorner(box, 8)
        addStroke(box, P.stroke, 1, 0.3)
        addPad(box, 8, 12, 8, 12)
        addList(box, 3)

        if opts.label and opts.label ~= "" then
            make("TextLabel", {
                Size = UDim2.new(1, 0, 0, 15),
                BackgroundTransparency = 1,
                Font = Enum.Font.GothamBold,
                Text = tostring(opts.label),
                TextColor3 = P.textSecondary,
                TextSize = 11,
                TextXAlignment = Enum.TextXAlignment.Left,
                LayoutOrder = 1
            }, box)
        end

        local lbl = make("TextLabel", {
            Name = "Body",
            Size = UDim2.new(1, 0, 0, 0),
            AutomaticSize = Enum.AutomaticSize.Y,
            BackgroundTransparency = 1,
            Font = Enum.Font.Gotham,
            Text = tostring(opts.initial or "..."),
            TextColor3 = P.textPrimary,
            TextSize = 11,
            TextXAlignment = Enum.TextXAlignment.Left,
            TextWrapped = true,
            LayoutOrder = 2
        }, box)

        local handle = { _kind = "LiveText", _text = lbl.Text, _frame = box, _lbl = lbl }
        function handle.Set(a, b)
            local txt = (a == handle) and b or a
            local s = tostring(txt or "")
            if s ~= handle._text then
                handle._text = s
                lbl.Text = s
            end
        end
        function handle.Get()
            return handle._text
        end
        if opts.liveKey then
            GUI.LIVE[opts.liveKey] = handle
        end
        return handle
    end

    -- 8. Key-Value Table Widget (Pooled & Dirty-Checked)
    function E.addKeyValue(parent, opts)
        local order = opts.order or (#parent:GetChildren() + 1)
        local box = make("Frame", {
            Name = "KV_" .. tostring(opts.id or order),
            Size = UDim2.new(1, 0, 0, 0),
            AutomaticSize = Enum.AutomaticSize.Y,
            BackgroundColor3 = P.bgSubtle,
            LayoutOrder = order
        }, parent)
        addCorner(box, 8)
        addStroke(box, P.stroke, 1, 0.3)
        addPad(box, 8, 12, 8, 12)
        addList(box, 4)

        if opts.label and opts.label ~= "" then
            make("TextLabel", {
                Size = UDim2.new(1, 0, 0, 16),
                BackgroundTransparency = 1,
                Font = Enum.Font.GothamBold,
                Text = tostring(opts.label),
                TextColor3 = P.textSecondary,
                TextSize = 11,
                TextXAlignment = Enum.TextXAlignment.Left,
                LayoutOrder = 0
            }, box)
        end

        local rowsBody = make("Frame", {
            Size = UDim2.new(1, 0, 0, 0),
            AutomaticSize = Enum.AutomaticSize.Y,
            BackgroundTransparency = 1,
            LayoutOrder = 1
        }, box)
        addList(rowsBody, 3)

        local emptyRow = make("Frame", {
            Size = UDim2.new(1, 0, 0, 18),
            BackgroundTransparency = 1,
            Visible = false,
            LayoutOrder = 1
        }, rowsBody)
        local emptyTextStr = tostring(opts.emptyText or "No data yet")
        make("TextLabel", {
            Size = UDim2.new(1, 0, 1, 0),
            BackgroundTransparency = 1,
            Font = Enum.Font.Gotham,
            Text = emptyTextStr,
            TextColor3 = P.textMuted,
            TextSize = 11,
            TextXAlignment = Enum.TextXAlignment.Left
        }, emptyRow)

        local rowPool = {}
        local activeCount = -1
        local emptyVisible = false
        local handle = { _kind = "KeyValue", _rows = {}, _frame = box }

        function handle.SetRows(a, b)
            local items = (a == handle) and b or a
            if type(items) ~= "table" then return end
            local n = #items
            if n == 0 then
                if not emptyVisible then
                    emptyRow.Visible = true
                    emptyVisible = true
                end
                if activeCount ~= 0 then
                    for i = 1, #rowPool do
                        local slot = rowPool[i]
                        if slot.vis then
                            slot.frame.Visible = false
                            slot.vis = false
                        end
                    end
                    activeCount = 0
                end
                return
            end

            if emptyVisible then
                emptyRow.Visible = false
                emptyVisible = false
            end

            for idx = 1, n do
                local entry = items[idx]
                local k = tostring(entry.key or entry[1] or "")
                local v = tostring(entry.value or entry[2] or "")
                local col = entry.color or P.textPrimary
                local slot = rowPool[idx]
                if not slot then
                    local r = make("Frame", {
                        Size = UDim2.new(1, 0, 0, 18),
                        BackgroundTransparency = 1,
                        LayoutOrder = idx
                    }, rowsBody)
                    local kLbl = make("TextLabel", {
                        Size = UDim2.new(0.32, 0, 1, 0),
                        BackgroundTransparency = 1,
                        Font = Enum.Font.GothamMedium,
                        Text = k,
                        TextColor3 = P.textSecondary,
                        TextSize = 11,
                        TextXAlignment = Enum.TextXAlignment.Left,
                        TextTruncate = Enum.TextTruncate.AtEnd
                    }, r)
                    local vLbl = make("TextLabel", {
                        Size = UDim2.new(0.68, -6, 1, 0),
                        Position = UDim2.new(0.32, 6, 0, 0),
                        BackgroundTransparency = 1,
                        Font = Enum.Font.Gotham,
                        Text = v,
                        TextColor3 = col,
                        TextSize = 11,
                        TextXAlignment = Enum.TextXAlignment.Right,
                        TextTruncate = Enum.TextTruncate.AtEnd
                    }, r)
                    slot = {
                        frame = r,
                        kLbl = kLbl,
                        vLbl = vLbl,
                        k = k,
                        v = v,
                        col = col,
                        vis = true
                    }
                    rowPool[idx] = slot
                else
                    if not slot.vis then
                        slot.frame.Visible = true
                        slot.vis = true
                    end
                    if slot.k ~= k then
                        slot.k = k
                        slot.kLbl.Text = k
                    end
                    if slot.v ~= v then
                        slot.v = v
                        slot.vLbl.Text = v
                    end
                    if slot.col ~= col then
                        slot.col = col
                        slot.vLbl.TextColor3 = col
                    end
                end
            end

            if activeCount > n then
                for idx = n + 1, activeCount do
                    local slot = rowPool[idx]
                    if slot and slot.vis then
                        slot.frame.Visible = false
                        slot.vis = false
                    end
                end
            end
            activeCount = n
        end

        handle.SetRows(opts.initialRows or {})
        return handle
    end

    -- 9. Status Card Widget (title, text, sub, badge tag, progress bar — Dirty-Checked)
    function E.addStatusCard(parent, opts)
        local order = opts.order or (#parent:GetChildren() + 1)
        local card = make("Frame", {
            Name = "StatusCard_" .. tostring(opts.id or order),
            Size = UDim2.new(1, 0, 0, 0),
            AutomaticSize = Enum.AutomaticSize.Y,
            BackgroundColor3 = P.bgSubtle,
            LayoutOrder = order
        }, parent)
        addCorner(card, 8)
        addStroke(card, P.stroke, 1, 0.2)
        addPad(card, 10, 12, 10, 12)
        addList(card, 4)

        local initTitle = tostring(opts.title or "Status")
        local initText = tostring(opts.initial or "...")

        local top = make("Frame", { Size = UDim2.new(1, 0, 0, 18), BackgroundTransparency = 1, LayoutOrder = 1 }, card)
        local titleLbl = make("TextLabel", {
            Size = UDim2.new(1, -90, 1, 0),
            BackgroundTransparency = 1,
            Font = Enum.Font.GothamBold,
            Text = initTitle,
            TextColor3 = P.textPrimary,
            TextSize = 12,
            TextXAlignment = Enum.TextXAlignment.Left,
            TextTruncate = Enum.TextTruncate.AtEnd
        }, top)
        local tagLbl = make("TextLabel", {
            Size = UDim2.new(0, 82, 0, 16),
            Position = UDim2.new(1, -82, 0, 1),
            BackgroundColor3 = P.bgElevated,
            Font = Enum.Font.GothamBold,
            Text = "",
            TextColor3 = P.textSecondary,
            TextSize = 10,
            Visible = false
        }, top)
        addCorner(tagLbl, 4)

        local textLbl = make("TextLabel", {
            Size = UDim2.new(1, 0, 0, 0),
            AutomaticSize = Enum.AutomaticSize.Y,
            BackgroundTransparency = 1,
            Font = Enum.Font.Gotham,
            Text = initText,
            TextColor3 = P.textPrimary,
            TextSize = 11,
            TextXAlignment = Enum.TextXAlignment.Left,
            TextWrapped = true,
            LayoutOrder = 2
        }, card)

        local subLbl = make("TextLabel", {
            Size = UDim2.new(1, 0, 0, 0),
            AutomaticSize = Enum.AutomaticSize.Y,
            BackgroundTransparency = 1,
            Font = Enum.Font.Gotham,
            Text = "",
            TextColor3 = P.textSecondary,
            TextSize = 11,
            TextXAlignment = Enum.TextXAlignment.Left,
            TextWrapped = true,
            Visible = false,
            LayoutOrder = 3
        }, card)

        local barBg = make("Frame", {
            Size = UDim2.new(1, 0, 0, 5),
            BackgroundColor3 = P.bgElevated,
            Visible = false,
            LayoutOrder = 4
        }, card)
        addCorner(barBg, 999)
        local barFill = make("Frame", {
            Size = UDim2.new(0, 0, 1, 0),
            BackgroundColor3 = E.accentColor
        }, barBg)
        addCorner(barFill, 999)

        local lastTitle = initTitle
        local lastText = initText
        local lastSub = ""
        local lastSubVis = false
        local lastTag = ""
        local lastTagCol = P.textSecondary
        local lastTagVis = false
        local lastBarVis = false
        local lastProg = -1
        local lastBarCol = E.accentColor

        local handle = { _kind = "StatusCard", _frame = card }
        function handle.Set(a, b)
            local data = (a == handle) and b or a
            if type(data) ~= "table" then return end
            if data.title ~= nil then
                local t = tostring(data.title)
                if t ~= lastTitle then
                    lastTitle = t
                    titleLbl.Text = t
                end
            end
            if data.text ~= nil then
                local tx = tostring(data.text)
                if tx ~= lastText then
                    lastText = tx
                    textLbl.Text = tx
                end
            end
            if data.sub and data.sub ~= "" then
                local sb = tostring(data.sub)
                if sb ~= lastSub then
                    lastSub = sb
                    subLbl.Text = sb
                end
                if not lastSubVis then
                    lastSubVis = true
                    subLbl.Visible = true
                end
            else
                if lastSubVis then
                    lastSubVis = false
                    subLbl.Visible = false
                end
            end
            if data.tag and data.tag ~= "" then
                local tg = tostring(data.tag)
                if tg ~= lastTag then
                    lastTag = tg
                    tagLbl.Text = tg
                end
                local tCol = data.tagColor or E.accentColor
                if tCol ~= lastTagCol then
                    lastTagCol = tCol
                    tagLbl.TextColor3 = tCol
                end
                if not lastTagVis then
                    lastTagVis = true
                    tagLbl.Visible = true
                end
            else
                if lastTagVis then
                    lastTagVis = false
                    tagLbl.Visible = false
                end
            end
            if type(data.progress) == "number" then
                if not lastBarVis then
                    lastBarVis = true
                    barBg.Visible = true
                end
                local p = uiClamp(data.progress, 0, 1)
                if math.abs(p - lastProg) > 0.0005 then
                    lastProg = p
                    barFill.Size = UDim2.new(p, 0, 1, 0)
                end
                local bCol = data.color or E.accentColor
                if bCol ~= lastBarCol then
                    lastBarCol = bCol
                    barFill.BackgroundColor3 = bCol
                end
            else
                if lastBarVis then
                    lastBarVis = false
                    barBg.Visible = false
                end
            end
        end
        return handle
    end

    -- 10. Keybind Picker
    function E.addKeybind(parent, opts)
        local row = makeRowBase(parent, {
            id = opts.id,
            label = opts.label,
            tooltip = opts.tooltip,
            breadcrumb = opts.breadcrumb,
            keywords = opts.keywords,
            leftWidth = -132,
            height = 44
        })

        local btn = make("TextButton", {
            Name = "KeybindBtn",
            Size = UDim2.new(0, 114, 0, 28),
            Position = UDim2.new(1, -124, 0.5, -14),
            BackgroundColor3 = P.bgSurface,
            Font = Enum.Font.Code,
            Text = tostring(E.prefs.toggleKey or "RightShift"),
            TextColor3 = E.accentColor,
            TextSize = 11
        }, row)
        addCorner(btn, 6)
        addStroke(btn, P.strokeStrong, 1, 0)
        bindAccent(btn, "TextColor3", false)

        local handle = { _kind = "Keybind", _frame = row, _btn = btn }
        function handle.Set(a, b)
            local k = (a == handle) and b or a
            local name = tostring(k or "RightShift")
            E.prefs.toggleKey = name
            btn.Text = name
            if E.headerKeyBadge then
                E.headerKeyBadge.Text = name
            end
            uiSavePrefs(E.prefs)
        end
        function handle.Get()
            return E.prefs.toggleKey
        end

        trackConn(btn.MouseButton1Click, function()
            E.listeningKeybind = true
            btn.Text = "Press key..."
        end)
        E.keybindHandle = handle
        return handle
    end

    -- 11. Accent Color Swatch Picker
    function E.addAccentPicker(parent, opts)
        local row = makeRowBase(parent, {
            id = opts.id,
            label = opts.label,
            tooltip = opts.tooltip,
            breadcrumb = opts.breadcrumb,
            keywords = opts.keywords,
            leftWidth = -170,
            height = 44
        })

        local swatchHolder = make("Frame", {
            Size = UDim2.new(0, 152, 0, 28),
            Position = UDim2.new(1, -162, 0.5, -14),
            BackgroundTransparency = 1
        }, row)
        addList(swatchHolder, 8, Enum.FillDirection.Horizontal)

        local swatches = {}
        local function paintSwatches()
            for _, s in ipairs(swatches) do
                local active = (E.prefs.accentId == s.id)
                s.stroke.Thickness = active and 2 or 1
                s.stroke.Color = active and P.textPrimary or P.stroke
            end
        end

        for i, preset in ipairs(GUI.ACCENT_PRESETS) do
            local sw = make("TextButton", {
                Name = "Swatch_" .. preset.id,
                Size = UDim2.new(0, 30, 0, 26),
                BackgroundColor3 = preset.color,
                Text = "",
                LayoutOrder = i
            }, swatchHolder)
            addCorner(sw, 6)
            local st = addStroke(sw, P.stroke, 1, 0)
            table.insert(swatches, { id = preset.id, btn = sw, stroke = st })
            trackConn(sw.MouseButton1Click, function()
                GUI.setAccent(preset.id)
                paintSwatches()
            end)
        end
        paintSwatches()
        E.paintSwatches = paintSwatches
    end

    return E
end

