function GUI.saveQuickTask(taskObj, sender)
    if GUI.syncingQuickTask then return end
    GUI.syncingQuickTask = true
    Config.qsTask = Farming.copy(taskObj)
    App.saveSoon()
    for _, form in ipairs(GUI.quickForms or {}) do
        if form ~= sender then
            pcall(form.load, Config.qsTask)
        end
    end
    GUI.syncingQuickTask = false
end

local function buildFarmTaskForm(E, parent, breadcrumb, onChange)
    local form = { task = Farming.newTask(), adv = {}, mapSig = nil }

    local function rowIndex(rows, value)
        for idx, row in ipairs(rows) do
            if row.value == value then
                return idx
            end
        end
        return nil
    end

    local function modeRows()
        local rows = {}
        for _, mode in ipairs(Farming.MODES or {}) do
            local txt = mode.name
            if mode.needsEvent and not (Modes and Modes.eventNow and Modes.eventNow()) then
                txt = txt .. " (none running)"
            end
            table.insert(rows, { text = txt, value = mode.id })
        end
        return rows
    end

    local function diffRows()
        local rows = Farming.diffOptions(form.task)
        if #rows == 0 then
            local msg = "Not needed for this mode"
            if form.task.mode == "story" then
                if form.task.map == "" or form.task.map == "progress" then
                    msg = "Set by Smart / Progress"
                else
                    msg = "Pick an act first"
                end
            end
            return { { text = msg, value = "" } }
        end
        return rows
    end

    local function changed()
        if onChange then
            pcall(onChange, form.task)
        end
    end

    function form.refreshDiff()
        local real = Farming.diffOptions(form.task)
        if #real > 0 and not rowIndex(real, form.task.diff) then
            form.task.diff = real[1].value
        elseif #real == 0 then
            form.task.diff = ""
        end
        if form.diff then
            form.diff.Refresh(diffRows(), form.task.diff)
        end
    end

    function form.refreshMaps(reset)
        local rows = Farming.mapOptions(form.task.mode)
        if reset and not rowIndex(rows, form.task.map) then
            form.task.map = rows[1] and rows[1].value or ""
        end
        local parts = { tostring(form.task.mode), tostring(form.task.map) }
        for _, row in ipairs(rows) do
            table.insert(parts, tostring(row.value))
        end
        local sig = table.concat(parts, "|")
        if form.map and (reset or sig ~= form.mapSig) then
            form.map.Refresh(rows, form.task.map)
            form.mapSig = sig
            form.refreshDiff()
        end
    end

    form.mode = E.addDropdown(parent, {
        id = "queue_task_mode",
        label = "Task Mode",
        tooltip = "Mode to run for this queued task.",
        breadcrumb = breadcrumb,
        keywords = "queue routine task mode",
        options = modeRows(),
        default = form.task.mode,
        onChange = function(_, value)
            form.task.mode = value
            form.refreshMaps(true)
            form.refreshDiff()
            changed()
        end
    })

    form.map = E.addDropdown(parent, {
        id = "queue_task_map",
        label = "Task Map",
        tooltip = "Open maps available for the selected mode.",
        breadcrumb = breadcrumb,
        keywords = "queue routine task map",
        options = Farming.mapOptions(form.task.mode),
        default = form.task.map,
        onChange = function(_, value)
            form.task.map = value
            form.refreshDiff()
            changed()
        end
    })

    form.diff = E.addDropdown(parent, {
        id = "queue_task_diff",
        label = "Task Difficulty",
        tooltip = "Normal or Hard for Story acts.",
        breadcrumb = breadcrumb,
        keywords = "queue routine difficulty",
        options = diffRows(),
        default = form.task.diff,
        onChange = function(_, value)
            if value ~= "" then
                form.task.diff = value
            end
            changed()
        end
    })

    form.runs = E.addInput(parent, {
        id = "queue_task_runs",
        label = "Runs Count",
        tooltip = "Number of completed runs before moving to the next task (0 = unlimited).",
        breadcrumb = breadcrumb,
        keywords = "queue routine runs count",
        placeholder = "e.g. 25",
        default = tostring(form.task.runs),
        onChange = function(text)
            local cleaned = tostring(text or ""):gsub("%s", "")
            form.task.runs = tonumber(cleaned) or 0
            changed()
        end
    })

    for _, spec in ipairs(GUI.FARM_ADV) do
        form.adv[spec.key] = E.addDropdown(parent, {
            id = "queue_adv_" .. spec.key,
            label = spec.title,
            tooltip = "Per-task override (Same as Auto Farm uses your global setting).",
            breadcrumb = breadcrumb,
            keywords = "queue override " .. spec.key,
            options = spec.rows,
            default = "same",
            onChange = function(_, value)
                form.task.adv[spec.key] = value
                changed()
            end
        })
    end

    function form.load(taskObj)
        local t = taskObj
        if type(t) ~= "table" or not Farming.mode(t.mode) then
            t = Farming.newTask(form.task and form.task.mode)
        end
        form.task = Farming.copy(t)
        if type(form.task.adv) ~= "table" then
            form.task.adv = {}
        end
        for k, v in pairs(Farming.SAME or {}) do
            if form.task.adv[k] == nil then
                form.task.adv[k] = v
            end
        end
        form.task.map = type(form.task.map) == "string" and form.task.map or ""
        form.task.diff = type(form.task.diff) == "string" and form.task.diff or ""
        if form.mode then form.mode.Refresh(modeRows(), form.task.mode) end
        form.mapSig = nil
        form.refreshMaps(false)
        form.refreshDiff()
        if form.runs then pcall(form.runs.Set, tostring(form.task.runs), true) end
        for k, h in pairs(form.adv) do
            pcall(h.Set, form.task.adv[k], true)
        end
        changed()
    end

    function form.get()
        return Farming.copy(form.task)
    end

    table.insert(GUI.farmForms, form)
    return form
end

-- Build all 5 Tabs inside GUI.build()
function GUI.build()
    -- Teardown any existing window cleanly before rebuilding
    if GUI.Win and type(GUI.Win.Destroy) == "function" then
        pcall(function() GUI.Win:Destroy() end)
    end

    GUI.UI = {}
    GUI.LIVE = {}
    GUI.farmModeSpecs = {}
    GUI.farmForms = {}
    GUI.quickForms = {}

    local E = createUiEngine()
    GUI._engine = E
    local P = GUI.PALETTE
    local make, addCorner, addStroke, addPad, addList = E.make, E.addCorner, E.addStroke, E.addPad, E.addList
    local trackConn, bindAccent = E.trackConn, E.bindAccent

    local guiParent = uiGetParent()
    local screenGui = make("ScreenGui", {
        Name = "AirflowV241UI",
        ResetOnSpawn = false,
        ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
