    -- Helper: Create a Top-Level Tab (optionally with contextual Sub-Pills)
    local function createTabPage(tabId, label, order, subPillDefs)
        local navBtn = make("TextButton", {
            Name = "Nav_" .. tabId,
            Size = UDim2.new(1, 0, 0, 36),
            BackgroundColor3 = P.bgSubtle,
            Font = Enum.Font.GothamMedium,
            Text = label,
            TextColor3 = P.textSecondary,
            TextSize = 12,
            TextXAlignment = Enum.TextXAlignment.Left,
            LayoutOrder = order
        }, navList)
        addCorner(navBtn, 8)
        addPad(navBtn, 0, 10, 0, 12)
        local navStroke = addStroke(navBtn, P.stroke, 1, 1)

        local container = make("Frame", {
            Name = "Tab_" .. tabId,
            Visible = (tabId == "start"),
            Size = UDim2.new(1, 0, 1, 0),
            BackgroundTransparency = 1
        }, contentHost)

        local subPages = {}
        local subButtons = {}
        local defaultScroll = nil

        if subPillDefs and #subPillDefs > 0 then
            local pillBar = make("Frame", {
                Name = "SubPillBar",
                Size = UDim2.new(1, 0, 0, 44),
                BackgroundColor3 = P.bgSubtle,
                BackgroundTransparency = 0.25
            }, container)
            addPad(pillBar, 8, 12, 8, 12)
            addList(pillBar, 6, Enum.FillDirection.Horizontal)

            for idx, sp in ipairs(subPillDefs) do
                local pillBtn = make("TextButton", {
                    Name = "SubPill_" .. sp.id,
                    Size = UDim2.new(0, sp.width or 122, 0, 28),
                    BackgroundColor3 = idx == 1 and E.accentSoft or P.bgSurface,
                    Font = idx == 1 and Enum.Font.GothamBold or Enum.Font.GothamMedium,
                    Text = sp.label,
                    TextColor3 = idx == 1 and E.accentColor or P.textSecondary,
                    TextSize = 11,
                    LayoutOrder = idx
                }, pillBar)
                addCorner(pillBtn, 999)
                local spStroke = addStroke(pillBtn, idx == 1 and E.accentColor or P.stroke, 1, 0)

                local sc = make("ScrollingFrame", {
                    Name = "SubPage_" .. sp.id,
                    Visible = (idx == 1),
                    Size = UDim2.new(1, 0, 1, -44),
                    Position = UDim2.new(0, 0, 0, 44),
                    CanvasSize = UDim2.new(0, 0, 0, 0),
                    AutomaticCanvasSize = Enum.AutomaticSize.Y,
                    ScrollBarThickness = 5,
                    ScrollBarImageColor3 = P.strokeStrong,
                    BackgroundTransparency = 1
                }, container)
                addPad(sc, 12, 14, 16, 14)
                addList(sc, 10)

                subPages[sp.id] = sc
                subButtons[sp.id] = { btn = pillBtn, stroke = spStroke }
                trackConn(pillBtn.MouseButton1Click, function()
                    GUI.selectSubPill(tabId, sp.id)
                end)
            end
            E.activeSubPill[tabId] = subPillDefs[1].id
            E.subPillMap[tabId] = { pages = subPages, buttons = subButtons }
        else
            defaultScroll = make("ScrollingFrame", {
                Name = "Page_" .. tabId,
                Size = UDim2.new(1, 0, 1, 0),
                CanvasSize = UDim2.new(0, 0, 0, 0),
                AutomaticCanvasSize = Enum.AutomaticSize.Y,
                ScrollBarThickness = 5,
                ScrollBarImageColor3 = P.strokeStrong,
                BackgroundTransparency = 1
            }, container)
            addPad(defaultScroll, 12, 14, 16, 14)
            addList(defaultScroll, 10)
        end

        E.tabs[tabId] = container
        E.tabButtons[tabId] = { btn = navBtn, stroke = navStroke }

        trackConn(navBtn.MouseButton1Click, function()
            GUI.selectTab(tabId)
        end)

        return defaultScroll, subPages
    end

