    -- ========================================================================
    -- Shared Start/Stop Action (used by Hero Button & Mini-HUD Pause/Resume)
    -- ========================================================================
    local function toggleStartStop()
        if uiIsRunning() then
            uiSetBase("master", false)
            if Farming and Farming.active and Farming.active() then
                pcall(Farming.stop, "you pressed Stop Auto Farm")
            end
            App.notify("Auto Farm", "Paused auto farming.", "warning")
        else
            Brain.holdLobby = nil
            uiSetBase("play", true, true)
            uiSetBase("master", true)
            App.notify("Auto Farm", "Auto farming started!", "success")
        end
        pcall(GUI.farmSync)
    end
    E.toggleStartStop = toggleStartStop
    trackConn(miniPauseBtn.MouseButton1Click, toggleStartStop)

    -- ========================================================================
    -- TAB 1: START (Quick Start Hub)
    -- ========================================================================
    do
        local _, heroBody = E.createCard(startPage, "Quick Start Hub", "Start farming in 1 click, monitor live match telemetry, and pick your favorite playstyle.", 1)

        -- Giant Hero Toggle Button
        local heroBtn = make("TextButton", {
            Name = "HeroStartStopBtn",
            Size = UDim2.new(1, 0, 0, 44),
            BackgroundColor3 = P.success,
            Font = Enum.Font.GothamBold,
            Text = "START AUTO FARM",
            TextColor3 = P.textPrimary,
            TextSize = 15,
            LayoutOrder = 1
        }, heroBody)
        addCorner(heroBtn, 9)
        E.heroBtn = heroBtn
        trackConn(heroBtn.MouseButton1Click, toggleStartStop)

        -- Expose master handle on GUI.UI so external callers / GUI.farmSync work seamlessly
        local masterHandle = { _kind = "HeroToggle", _value = uiGetBase("master") == true, _frame = heroBtn }
        function masterHandle.Get()
            return masterHandle._value
        end
        function masterHandle.Set(a, b, c)
            local val, silent
            if a == masterHandle then val, silent = b, c else val, silent = a, b end
            masterHandle._value = (val == true)
            if not silent then
                uiSetBase("master", masterHandle._value)
            end
            if E.syncHeroVisuals then E.syncHeroVisuals() end
        end
        E.registerHandle("master", "master", masterHandle)

        -- Quick Action Row: Pick Best Team | Return To Lobby | Resume Farming
        local qRow = make("Frame", {
            Size = UDim2.new(1, 0, 0, 32),
            BackgroundTransparency = 1,
            LayoutOrder = 2
        }, heroBody)
        addList(qRow, 8, Enum.FillDirection.Horizontal)

        local function quickAction(label, tone, fn, width)
            local b = make("TextButton", {
                Size = UDim2.new(0, width or 150, 1, 0),
                BackgroundColor3 = tone == "accent" and E.accentSoft or P.bgElevated,
                Font = Enum.Font.GothamBold,
                Text = label,
                TextColor3 = tone == "accent" and E.accentColor or P.textPrimary,
                TextSize = 11
            }, qRow)
            addCorner(b, 7)
            addStroke(b, tone == "accent" and E.accentColor or P.stroke, 1, 0.25)
            trackConn(b.MouseButton1Click, function() pcall(fn) end)
            return b
        end
        quickAction("Pick Best Team", "accent", function()
            task.spawn(function() GUI.pickBestTeam(App.notify) end)
        end, 160)
        quickAction("Return To Lobby", "neutral", function()
            Brain.holdLobby = { why = "you pressed Return To Lobby", at = os.time() }
            App.saveNow()
            if App.where == "match" and Match and Match.toLobby then
                task.spawn(function() pcall(Match.toLobby, "Return To Lobby") end)
            end
            App.notify("Lobby", "Returning to lobby and holding there.", "warning")
            pcall(GUI.farmSync)
        end, 160)
        quickAction("Resume Farming", "neutral", function()
            Brain.holdLobby = nil
            App.saveNow()
            App.notify("Auto Farm", "Cleared lobby hold. Resuming...", "success")
            pcall(GUI.farmSync)
        end, 160)

        -- 5-Tile Live Status Strip
        local strip = make("Frame", {
            Name = "LiveStatusStrip",
            Size = UDim2.new(1, 0, 0, 56),
            BackgroundTransparency = 1,
            LayoutOrder = 3
        }, heroBody)
        make("UIGridLayout", {
            CellSize = UDim2.new(0.2, -6, 1, 0),
            CellPadding = UDim2.new(0, 7, 0, 0),
            SortOrder = Enum.SortOrder.LayoutOrder
        }, strip)

        E.statusTiles = {}
        local tileDefs = {
            { id = "state", label = "STATE", value = "Paused" },
            { id = "wave", label = "MAP & WAVE", value = "Lobby" },
            { id = "record", label = "WINS / LOSSES", value = "0W / 0L" },
            { id = "session", label = "GEMS / HR", value = "..." },
            { id = "ai", label = "NEURAL AI", value = "7/7 Active" }
        }
        for idx, td in ipairs(tileDefs) do
            local tile = make("Frame", {
                Name = "Tile_" .. td.id,
                BackgroundColor3 = P.bgSubtle,
                LayoutOrder = idx
            }, strip)
            addCorner(tile, 8)
            addStroke(tile, P.stroke, 1, 0.2)
            make("TextLabel", {
                Size = UDim2.new(1, -12, 0, 14),
                Position = UDim2.new(0, 8, 0, 7),
                BackgroundTransparency = 1,
                Font = Enum.Font.GothamBold,
                Text = td.label,
                TextColor3 = P.textMuted,
                TextSize = 9,
                TextXAlignment = Enum.TextXAlignment.Left
            }, tile)
            local vLbl = make("TextLabel", {
                Size = UDim2.new(1, -12, 0, 22),
                Position = UDim2.new(0, 8, 0, 24),
                BackgroundTransparency = 1,
                Font = Enum.Font.GothamBold,
                Text = td.value,
                TextColor3 = P.textPrimary,
                TextSize = 13,
                TextXAlignment = Enum.TextXAlignment.Left,
                TextTruncate = Enum.TextTruncate.AtEnd
            }, tile)
            E.statusTiles[td.id] = vLbl
        end

        E.addLiveText(heroBody, { id = "live_home_status", liveKey = "homeStatus", label = "Current Action", initial = "Ready in the lobby" })
        GUI.nowCard = E.addStatusCard(heroBody, { id = "card_now", title = "Match / Lobby", initial = "Waiting..." })
        GUI.simCard = E.addStatusCard(heroBody, { id = "card_sim", title = "Simulator Forecast", initial = "Waiting for next pick..." })
        GUI.nextCard = E.addStatusCard(heroBody, { id = "card_next", title = "Up Next & Last Run", initial = "Deciding..." })
        GUI.goals = E.addKeyValue(heroBody, { id = "kv_goals", label = "At A Glance (Currencies & Progress)" })
        GUI.homeKv = E.addKeyValue(heroBody, { id = "kv_home_parts", label = "Active Subsystems Summary" })

        -- Card 2: Mode Selector Pills & Jobs Between Runs
        local _, modeBody = E.createCard(startPage, "What To Farm", "Click any mode pill to include or exclude it from Smart Auto Farm.", 2)
        E.addLiveText(modeBody, { id = "live_farm_pick", liveKey = "farmPickStatus", label = "Active Selection", initial = "Smart Auto Farm" })

        local pillGrid = make("Frame", {
            Name = "ModePillsGrid",
            Size = UDim2.new(1, 0, 0, 68),
            BackgroundTransparency = 1,
            LayoutOrder = 2
        }, modeBody)
        make("UIGridLayout", {
            CellSize = UDim2.new(0, 122, 0, 30),
            CellPadding = UDim2.new(0, 6, 0, 6),
            SortOrder = Enum.SortOrder.LayoutOrder
        }, pillGrid)

        local modePillSpecs = {
            { id = "story", label = "Story", only = "onlyStory", enable = { "firstClears", "farm" } },
            { id = "raid", label = "Raid", only = "onlyRaids", enable = { "raids" } },
            { id = "dungeon", label = "Dungeon", only = "onlyDungeons", enable = { "dungeon" } },
            { id = "event", label = "Event", only = "onlyCoins", enable = { "event" } },
            { id = "infinite", label = "Infinite", only = "onlyInfinite", enable = { "infinite" } },
            { id = "portal", label = "Portal", only = "onlyPortals", enable = { "portals" } },
            { id = "challenge", label = "Challenge", only = "onlyChallenges", enable = { "dailyChallenge", "challenge" } },
            { id = "artifact", label = "Artifact", only = "onlyArtifact", enable = { "artifact" } }
        }

        for idx, spec in ipairs(modePillSpecs) do
            table.insert(GUI.farmModeSpecs, { only = spec.only, enable = spec.enable, toggle = true })
            local pillBtn = make("TextButton", {
                Name = "ModePill_" .. spec.id,
                BackgroundColor3 = P.bgElevated,
                Font = Enum.Font.GothamBold,
                Text = spec.label,
                TextColor3 = P.textSecondary,
                TextSize = 11,
                LayoutOrder = idx
            }, pillGrid)
            addCorner(pillBtn, 999)
            local st = addStroke(pillBtn, P.stroke, 1, 0)

            local h = { _kind = "ModePill", _value = false, _btn = pillBtn, _stroke = st, _spec = spec }
            local function paint(v)
                pillBtn.BackgroundColor3 = v and E.accentSoft or P.bgElevated
                pillBtn.TextColor3 = v and E.accentColor or P.textSecondary
                st.Color = v and E.accentColor or P.stroke
            end
            function h.Get() return h._value end
            function h.Set(a, b, c)
                local val, silent
                if a == h then val, silent = b, c else val, silent = a, b end
                h._value = (val == true)
                paint(h._value)
                if not silent then
                    for _, k in ipairs(spec.enable) do
                        uiSetBase(k, h._value, true)
                    end
                    if not h._value then
                        uiSetBase(spec.only, false, true)
                    end
                    App.saveSoon()
                    if Modes then Modes.lastScored = nil end
                    pcall(GUI.farmSync)
                end
            end
            trackConn(pillBtn.MouseButton1Click, function()
                h.Set(not h._value, false)
            end)
            E.registerHandle(spec.only .. "Mode", nil, h)
            E.modePillHandles[spec.only] = h
        end

        -- 9th Pill: Legend Stage quick jump
        local legBtn = make("TextButton", {
            Name = "ModePill_legend",
