        end)

        -- Jobs Between Runs Multi-Pill Group
        local jobDefs = {
            { text = "Team Upgrades", value = "team" },
            { text = "Smart Evolve", value = "smartEvolve" },
            { text = "Evo Goals", value = "goals" },
            { text = "Takedowns", value = "trainTakedowns" },
            { text = "Core Fuse", value = "teamFuse" },
            { text = "Auto Summon", value = "autoSummon" },
            { text = "Banner Snipe", value = "snipeOn" },
            { text = "Rewards", value = "rewards" },
            { text = "Promo Codes", value = "codes" },
            { text = "Gold Shop", value = "goldShop" }
        }
        local initJobs = {}
        for _, jd in ipairs(jobDefs) do
            if uiGetBase(jd.value) == true then
                table.insert(initJobs, jd.value)
            end
        end
        E.jobsMultiHandle = E.addMultiSelect(modeBody, {
            id = "jobs_between_runs",
            label = "Jobs Between Runs",
            tooltip = "Lobby tasks performed automatically between matches.",
            breadcrumb = "Start",
            keywords = "jobs lobby evolve summon rewards codes gold fuse snipe team",
            options = jobDefs,
            default = initJobs,
            onChange = function(selectedKeys)
                local lookup = {}
                for _, k in ipairs(selectedKeys) do lookup[k] = true end
                for _, jd in ipairs(jobDefs) do
                    uiSetBase(jd.value, lookup[jd.value] == true, true)
                end
                App.saveSoon()
                pcall(GUI.farmSync)
            end
        })

        E.addToggle(modeBody, { id = "toggle_play", label = "Auto Join Matches", tooltip = "Automatically enters the best selected mode from the lobby.", breadcrumb = "Start", configKey = "play", uiKey = "play", keywords = "play join match start" })
