        E.addToggle(cEv, { id = "toggle_smart_charm", label = "Smart Charm Equip", tooltip = "Equips reward or damage Summer Charm depending on clear margin.", breadcrumb = "Modes › Event & Summer", configKey = "smartCharm", uiKey = "smartCharm", keywords = "charm summer equip" })
        E.addSlider(cEv, { id = "slider_pearl_floor", label = "Summer Pearls To Keep", tooltip = "Reserve this many Summer Pearls before spending.", breadcrumb = "Modes › Event & Summer", configKey = "pearlFloor", uiKey = "pearlFloor", min = 0, max = 300000, step = 5000, kind = "fmt", keywords = "pearl floor summer reserve" })

