        E.addToggle(cSkin, { id = "toggle_star_open", label = "Auto Open Sunny Stars", tooltip = "Automatically opens collected Sunny Stars in the lobby.", breadcrumb = "Modes › Event & Summer", configKey = "starOpen", uiKey = "starOpen", keywords = "sunny star open" })
