        E.addToggle(cDg, { id = "toggle_only_dungeons", label = "Only Play Dungeon", tooltip = "Restrict Auto Farm strictly to Dungeon runs.", breadcrumb = "Modes › Dungeon", configKey = "onlyDungeons", uiKey = "onlyDungeons", keywords = "only dungeon lock" })
