        E.addToggle(cInf, { id = "toggle_infinite", label = "Play Infinite", tooltip = "Allows entering Infinite stages.", breadcrumb = "Modes › Infinite & Portals", configKey = "infinite", uiKey = "infinite", keywords = "infinite waves" })
        E.addToggle(cInf, { id = "toggle_only_infinite", label = "Only Play Infinite", tooltip = "Restrict Auto Farm strictly to Infinite mode.", breadcrumb = "Modes › Infinite & Portals", configKey = "onlyInfinite", uiKey = "onlyInfinite", keywords = "only infinite lock" })
        E.addDropdown(cInf, { id = "dropdown_pick_infinite", label = "Infinite Map Target", tooltip = "Pick a specific Infinite map or Smart.", breadcrumb = "Modes › Infinite & Portals", configKey = "pickInfinite", uiKey = "pickInfinitePick", options = GUI.modeOptions("infinite"), keywords = "infinite map target" })
