    end

    -- Sub-pill 2.5: Lobby & Queue (Task Queue, Matchmaking, Custom Team Per Mode, Mode Rankings)
    do
        local p = modesSub.lobby_retry

        -- Task Queue Builder
        local _, cQ = E.createCard(p, "Task Queue Builder", "Chain ordered farming tasks (mode, map, runs) that run top to bottom.", 1)
        local QUEUE_NAME = "Queue"
        local routineObj = Farming.routine(QUEUE_NAME) or { name = QUEUE_NAME, tasks = {} }
        local tasks = routineObj.tasks
        local selectedIdx = 1
        local queueText = E.addLiveText(cQ, { id = "live_queue_text", liveKey = "queueText", label = "Queued Tasks", initial = "No tasks queued." })
        E.addLiveText(cQ, { id = "live_queue_progress", liveKey = "farmRoutine", label = "Queue Progress", initial = Farming.progressText() })

        local qForm = buildFarmTaskForm(E, cQ, "Modes › Lobby & Queue", nil)
        local function saveQueue()
            Farming.saveRoutine(QUEUE_NAME, tasks)
            App.saveSoon()
        end
        local function refreshQueue()
            if #tasks == 0 then
                selectedIdx = 1
                queueText.Set("No tasks in queue. Configure a task above and press Add Task.")
            else
                selectedIdx = uiClamp(selectedIdx, 1, #tasks)
                local lines = {}
                for i, t in ipairs(tasks) do
                    local mark = (i == selectedIdx) and "> " or "  "
                    table.insert(lines, string.format("%s%d. %s", mark, i, Farming.label(t)))
                end
                queueText.Set(table.concat(lines, "\n"))
            end
            GUI.farmProgress()
        end
        refreshQueue()

        local qBtnRow1 = make("Frame", { Size = UDim2.new(1, 0, 0, 30), BackgroundTransparency = 1, LayoutOrder = 20 }, cQ)
        addList(qBtnRow1, 6, Enum.FillDirection.Horizontal)
        local qBtnRow2 = make("Frame", { Size = UDim2.new(1, 0, 0, 30), BackgroundTransparency = 1, LayoutOrder = 21 }, cQ)
        addList(qBtnRow2, 6, Enum.FillDirection.Horizontal)

        local function qBtn(rowParent, txt, tone, w, fn)
            local bg = P.bgElevated
            if tone == "accent" then bg = E.accentColor
            elseif tone == "success" then bg = P.success
            elseif tone == "danger" then bg = P.danger end
            local b = make("TextButton", {
                Size = UDim2.new(0, w, 1, 0),
                BackgroundColor3 = bg,
                Font = Enum.Font.GothamBold,
                Text = txt,
                TextColor3 = P.textPrimary,
                TextSize = 11
            }, rowParent)
            addCorner(b, 6)
            trackConn(b.MouseButton1Click, function() pcall(fn) end)
            return b
        end

        qBtn(qBtnRow1, "Add Task", "accent", 96, function()
            table.insert(tasks, qForm.get())
            selectedIdx = #tasks
            saveQueue()
            refreshQueue()
            App.notify("Queue", "Added task #" .. tostring(selectedIdx), "success")
        end)
        qBtn(qBtnRow1, "Replace", "neutral", 84, function()
            if not tasks[selectedIdx] then return App.notify("Queue", "No task selected.", "warning") end
            tasks[selectedIdx] = qForm.get()
            saveQueue()
            refreshQueue()
            App.notify("Queue", "Updated task #" .. tostring(selectedIdx), "info")
        end)
        qBtn(qBtnRow1, "Prev", "neutral", 62, function()
            if #tasks > 0 then selectedIdx = math.max(1, selectedIdx - 1); qForm.load(tasks[selectedIdx]); refreshQueue() end
        end)
        qBtn(qBtnRow1, "Next", "neutral", 62, function()
            if #tasks > 0 then selectedIdx = math.min(#tasks, selectedIdx + 1); qForm.load(tasks[selectedIdx]); refreshQueue() end
        end)
        qBtn(qBtnRow1, "Remove", "danger", 82, function()
            if not tasks[selectedIdx] then return App.notify("Queue", "No task to remove.", "warning") end
            local rem = table.remove(tasks, selectedIdx)
            saveQueue()
            refreshQueue()
            App.notify("Queue", "Removed: " .. Farming.label(rem), "default")
        end)

        qBtn(qBtnRow2, "Move Up", "neutral", 84, function()
            if selectedIdx > 1 and tasks[selectedIdx] then
                tasks[selectedIdx], tasks[selectedIdx - 1] = tasks[selectedIdx - 1], tasks[selectedIdx]
                selectedIdx = selectedIdx - 1
                saveQueue()
                refreshQueue()
            end
        end)
        qBtn(qBtnRow2, "Move Down", "neutral", 94, function()
            if selectedIdx < #tasks and tasks[selectedIdx] then
                tasks[selectedIdx], tasks[selectedIdx + 1] = tasks[selectedIdx + 1], tasks[selectedIdx]
                selectedIdx = selectedIdx + 1
                saveQueue()
                refreshQueue()
            end
        end)
        qBtn(qBtnRow2, "Start Queue", "success", 104, function()
            local ok, msg = Farming.start("routine", QUEUE_NAME, tasks)
            App.notify("Queue", tostring(msg), ok and "success" or "warning")
            refreshQueue()
        end)
        qBtn(qBtnRow2, "Stop Queue", "danger", 100, function()
            local _, msg = Farming.stop("you pressed Stop Queue")
            App.notify("Queue", tostring(msg), "default")
            refreshQueue()
        end)

        -- Matchmaking
        local _, cMm = E.createCard(p, "Matchmaking", "Find other players before falling back to solo play.", 2)
        E.addToggle(cMm, { id = "toggle_daily_match", label = "Matchmake Daily Challenge", tooltip = "Queues with other players for Daily Challenge.", breadcrumb = "Modes › Lobby & Queue", configKey = "dailyMatch", uiKey = "dailyMatch", keywords = "matchmake daily coop" })
        E.addToggle(cMm, { id = "toggle_mm_raid", label = "Matchmake Raids", tooltip = "Queues with up to 6 players for Raids.", breadcrumb = "Modes › Lobby & Queue", configKey = "mmRaid", uiKey = "mmRaid", keywords = "matchmake raid coop" })
        E.addToggle(cMm, { id = "toggle_mm_infinite", label = "Matchmake Infinite", tooltip = "Queues with up to 4 players for Infinite.", breadcrumb = "Modes › Lobby & Queue", configKey = "mmInfinite", uiKey = "mmInfinite", keywords = "matchmake infinite coop" })
        E.addToggle(cMm, { id = "toggle_mm_legend", label = "Matchmake Legend Stages", tooltip = "Queues with up to 4 players for Legend Stages.", breadcrumb = "Modes › Lobby & Queue", configKey = "mmLegend", uiKey = "mmLegend", keywords = "matchmake legend coop" })
        E.addToggle(cMm, { id = "toggle_mm_event", label = "Matchmake Event", tooltip = "Queues with up to 6 players for Event runs.", breadcrumb = "Modes › Lobby & Queue", configKey = "mmEvent", uiKey = "mmEvent", keywords = "matchmake event summer coop" })
        E.addSlider(cMm, { id = "slider_mm_wait", label = "Matchmaking Wait Limit", tooltip = "Seconds to wait for teammates before starting solo.", breadcrumb = "Modes › Lobby & Queue", configKey = "dailyMatchWait", uiKey = "dailyMatchWait", min = 30, max = 600, step = 30, kind = "sec", keywords = "matchmake wait timeout seconds" })

        -- Custom Team Per Mode
        local _, cOwn = E.createCard(p, "Custom Team Per Mode", "Save your currently equipped team as the pinned loadout for a specific mode.", 3)
        local ownKeys = { "story", "legend", "raid", "infinite", "portal", "daily", "challenge", "artifact", "event", "dungeon" }
        local ownSel = ownKeys[1]
        local ownStatus = E.addLiveText(cOwn, { id = "live_own_team", liveKey = "ownTeamStatus", label = "Saved Mode Team", initial = "..." })
        local ownShown, ownShownAt = nil, 0
        local function refreshOwnTeam(force)
            if not force and Utils.now() - ownShownAt < 4 then return end
            ownShownAt = Utils.now()
            local ok, txt = pcall(Modes.ownTeamText, ownSel)
            if ok and txt ~= ownShown then
                ownShown = txt
