        local function activeBannerFloorKey()
            local bc = FarmHub and FarmHub.bannerCost and FarmHub.bannerCost(Config.summonBanner)
            return (bc and bc.floor) or "gemFloor"
        end
        local bannerOpts = GUI.bannerOptions()
        GUI.listBuilt("summonBanner", bannerOpts)
        E.addDropdown(cSum, {
            id = "dropdown_summon_banner",
            label = "Banner To Summon",
            tooltip = "Select which active banner to pull on.",
            breadcrumb = "Account & Rewards › Summons & Snipe",
            configKey = "summonBanner",
            uiKey = "summonBannerPick",
            options = bannerOpts,
            keywords = "summon banner select",
            onChange = function(_, val)
                local bc = FarmHub and FarmHub.bannerCost and FarmHub.bannerCost(val)
                if bc and GUI.UI.summonKeep then
                    pcall(GUI.UI.summonKeep.Set, Config[bc.floor], true)
                end
            end
        })
        E.addToggle(cSum, {
            id = "toggle_auto_summon",
            label = "Enable Auto Summon",
            tooltip = "Summons 10x in the lobby until reaching the reserve below.",
            breadcrumb = "Account & Rewards › Summons & Snipe",
            configKey = "autoSummon",
