        local logRing = {}
        local logSeq = 0
        local actLog = {}
        function actLog.Push(a, b, c)
            if E.destroyed then return end
            local txt, kind
            if a == actLog then txt, kind = b, c else txt, kind = a, b end
            logSeq = logSeq + 1
            local entry = { seq = logSeq, text = tostring(txt or ""), kind = kind }
            table.insert(logRing, entry)
            while #logRing > 250 do
                local old = table.remove(logRing, 1)
                if old and old.lbl then
                    pcall(function() old.lbl:Destroy() end)
                end
            end
            local lbl = make("TextLabel", {
                Size = UDim2.new(1, 0, 0, 15),
                BackgroundTransparency = 1,
                Font = Enum.Font.Code,
                Text = GUI.shortLine(entry.text, 140),
                TextColor3 = (kind == "Error") and P.danger or P.textSecondary,
                TextSize = 10,
                TextXAlignment = Enum.TextXAlignment.Left,
                TextTruncate = Enum.TextTruncate.AtEnd,
                LayoutOrder = logSeq
            }, logScroll)
            entry.lbl = lbl
        end
        GUI.activityLog = actLog

        -- Replay any buffered startup logs
        if LogBuffer and type(LogBuffer.lines) == "table" then
            local startI = math.max(1, #LogBuffer.lines - 40)
            for i = startI, #LogBuffer.lines do
                local line = LogBuffer.lines[i]
                if type(line) == "string" then
                    pcall(actLog.Push, actLog, line, nil)
                end
            end
