    -- ========================================================================
    -- Visual Sync Helpers, Keybind Input Listener & Window Lifecycle
    -- ========================================================================
    local lastPaintSig = nil
    local function paintTabs()
        local activeTab = E.activeTab
        local activeSp = E.activeSubPill[activeTab] or ""
        local accId = E.prefs and E.prefs.accentId or ""
        local sig = tostring(activeTab) .. "|" .. tostring(activeSp) .. "|" .. tostring(accId)
        if sig == lastPaintSig then
            return
        end
        lastPaintSig = sig
        for tId, tb in pairs(E.tabButtons) do
            local active = (tId == activeTab)
            tb.btn.BackgroundColor3 = active and E.accentSoft or P.bgSubtle
            tb.btn.TextColor3 = active and E.accentColor or P.textSecondary
            tb.btn.Font = active and Enum.Font.GothamBold or Enum.Font.GothamMedium
            tb.stroke.Color = active and E.accentColor or P.stroke
            tb.stroke.Transparency = active and 0.25 or 1
        end
        for tId, spInfo in pairs(E.subPillMap) do
            local curSp = E.activeSubPill[tId]
            for spId, sb in pairs(spInfo.buttons) do
                local active = (spId == curSp)
                sb.btn.BackgroundColor3 = active and E.accentSoft or P.bgSurface
                sb.btn.TextColor3 = active and E.accentColor or P.textSecondary
                sb.btn.Font = active and Enum.Font.GothamBold or Enum.Font.GothamMedium
                sb.stroke.Color = active and E.accentColor or P.stroke
            end
        end
    end
    E.paintTabs = paintTabs
    E.onThemeChanged = function()
        lastPaintSig = nil
        paintTabs()
    end

    local lastHeroRunning = nil
    local lastHeroHold = nil
    local lastHeroAiCnt = nil
    local lastHeroAccent = nil

    local function syncHeroVisuals()
        if E.destroyed then return end
        local running = uiIsRunning()
        local hold = (Brain.holdLobby ~= nil)
        local aiCnt = uiCountActiveAI()
        local acc = E.accentColor
        if running == lastHeroRunning and hold == lastHeroHold and aiCnt == lastHeroAiCnt and acc == lastHeroAccent then
            return
        end
        lastHeroRunning = running
        lastHeroHold = hold
        lastHeroAiCnt = aiCnt
        lastHeroAccent = acc

        local dotCol = running and P.success or P.warning

        if E.hdrDot then E.hdrDot.BackgroundColor3 = dotCol end
        if E.miniDot then E.miniDot.BackgroundColor3 = dotCol end
        if E.heroBtn then
            E.heroBtn.Text = running and "STOP AUTO FARM" or "START AUTO FARM"
            E.heroBtn.BackgroundColor3 = running and P.danger or P.success
        end
        if E.miniPauseBtn then
            E.miniPauseBtn.Text = running and "Pause" or "Resume"
            E.miniPauseBtn.TextColor3 = running and P.warning or P.success
        end
        if E.navStateLbl then
            E.navStateLbl.Text = running and "RUNNING" or (hold and "HOLDING" or "PAUSED")
            E.navStateLbl.TextColor3 = dotCol
        end
        if E.navAiLbl then
            E.navAiLbl.Text = string.format("%d/7 Neural AI", aiCnt)
        end
        if E.statusTiles then
            if E.statusTiles.state then
                E.statusTiles.state.Text = running and "Running" or (hold and "Hold Lobby" or "Paused")
                E.statusTiles.state.TextColor3 = dotCol
            end
            if E.statusTiles.ai then
                E.statusTiles.ai.Text = string.format("%d/7 Active", aiCnt)
                E.statusTiles.ai.TextColor3 = (aiCnt == 7) and P.success or acc
            end
        end
        if E.aiHeaderLbl then
            E.aiHeaderLbl.Set(string.format("%d/7 Neural Models Active (PlacementNN, TargetNN, EconomyNN, ActiveNN, SkipNN, TeamNN, CardNN)", aiCnt))
        end
    end
    E.syncHeroVisuals = syncHeroVisuals

    -- Global Keybind Handler (show/hide UI + capture new keybind)
    local UIS = uiSafeService("UserInputService")
    if UIS then
        trackConn(UIS.InputBegan, function(input, gameProcessed)
            if E.destroyed then return end
            local ok, keyName = pcall(function()
                if input.UserInputType == Enum.UserInputType.Keyboard and input.KeyCode then
                    return input.KeyCode.Name
                end
                return nil
            end)
            if not ok or not keyName or keyName == "Unknown" then
                return
            end
            if E.listeningKeybind then
                E.listeningKeybind = false
                if keyName ~= "Escape" then
                    GUI.setToggleKey(keyName)
                elseif E.keybindHandle then
                    E.keybindHandle.Set(E.prefs.toggleKey)
                end
                return
            end
            if gameProcessed then
                return
            end
            if keyName == tostring(E.prefs.toggleKey or "RightShift") then
                if GUI.Win and GUI.Win.Toggle then
                    GUI.Win:Toggle()
                end
            end
        end)
    end

    -- Window Lifecycle Controller (GUI.Win:Destroy() called by App.cleanup())
    local win = {}
    function win:IsVisible()
        return (not E.destroyed) and (not E.hidden)
    end
    function win:SetVisible(visible)
        if E.destroyed then return end
        local wasHidden = E.hidden
        E.hidden = (visible ~= true)
        if E.hidden then
            if E.mainFrame then E.mainFrame.Visible = false end
            if E.miniHud then E.miniHud.Visible = false end
        else
            if E.minimized then
                if E.mainFrame then E.mainFrame.Visible = false end
                if E.miniHud then E.miniHud.Visible = (E.prefs.miniHudEnabled ~= false) end
            else
                if E.mainFrame then E.mainFrame.Visible = true end
                if E.miniHud then E.miniHud.Visible = false end
            end
            if wasHidden then
                pcall(GUI.update, true)
            end
        end
    end
    function win:Toggle()
        win:SetVisible(E.hidden)
    end
    function win:Destroy()
        if E.destroyed then
            return
        end
        E.destroyed = true
        E.disconnectAll()
        E.toasts = {}
        E.openDropdown = nil
        if E.screenGui then
            local sg = E.screenGui
            E.screenGui = nil
            pcall(function() sg:Destroy() end)
        end
    end
    GUI.Win = win

    -- Initial paint & state sync
    GUI._forceFullUpdate = true
    paintTabs()
    syncHeroVisuals()
    pcall(GUI.farmSync)

    -- Show welcome / update toast on first run of v2.41
    if Config.seenVersion ~= VERSION then
        Config.seenVersion = VERSION
        App.saveSoon()
        pcall(App.notify, "Airflow v" .. VERSION .. " AI", "Obsidian Precision native UI ready — 5 tabs, Global Search, 4 Presets, Mini-HUD, 7 Neural AIs & Match Calibration Logger.", "success")
    end

    return win
end

-- ============================================================================
-- Section D: Programmatic UI Controls & External Hooks (Live + Lune Test API)
-- ============================================================================
function GUI.selectTab(tabId)
    local E = GUI._engine
    if not E or E.destroyed or not E.tabs[tabId] then
        return false
    end
    local prevTab = E.activeTab
    E.activeTab = tabId
    if E.searchQuery ~= "" then
        GUI.setSearch("")
    end
    for id, frame in pairs(E.tabs) do
        local vis = (id == tabId)
        if frame.Visible ~= vis then
            frame.Visible = vis
        end
    end
    if E.paintTabs then E.paintTabs() end
    if prevTab ~= tabId then
        pcall(GUI.update, true)
    end
    return true
end

function GUI.selectSubPill(tabId, subPillId)
    local E = GUI._engine
    if not E or E.destroyed then
        return false
    end
    if tabId and E.tabs[tabId] and E.activeTab ~= tabId then
        E.activeTab = tabId
        if E.searchQuery ~= "" then
            GUI.setSearch("")
        end
        for id, frame in pairs(E.tabs) do
            local vis = (id == tabId)
            if frame.Visible ~= vis then
                frame.Visible = vis
            end
        end
    end
    local info = E.subPillMap[E.activeTab]
    if not info or not info.pages[subPillId] then
        return false
    end
    E.activeSubPill[E.activeTab] = subPillId
    for spId, sc in pairs(info.pages) do
        local vis = (spId == subPillId)
        if sc.Visible ~= vis then
            sc.Visible = vis
        end
    end
    if E.paintTabs then E.paintTabs() end
    pcall(GUI.update, true)
    return true
end

function GUI.setSearch(query)
    local E = GUI._engine
    if not E or E.destroyed then
        return 0
    end
    local q = tostring(query or "")
    if E.searchBox and E.searchBox.Text ~= q then
        pcall(function() E.searchBox.Text = q end)
    end
    return E.applySearch(q)
end

function GUI.setMinimized(isMinimized)
    local E = GUI._engine
    if not E or E.destroyed then
        return false
    end
    local wasMin = E.minimized
    E.minimized = (isMinimized == true)
    if not E.hidden then
        if E.minimized then
            if E.mainFrame then E.mainFrame.Visible = false end
            if E.miniHud then E.miniHud.Visible = (E.prefs.miniHudEnabled ~= false) end
        else
            if E.mainFrame then E.mainFrame.Visible = true end
            if E.miniHud then E.miniHud.Visible = false end
            if wasMin then
                pcall(GUI.update, true)
            end
        end
    end
    return E.minimized
end

function GUI.setAdvancedOpen(isOpen)
    local E = GUI._engine
    if not E or E.destroyed then
        return false
    end
    local wasOpen = E.advancedOpen
    E.advancedOpen = (isOpen == true)
    if E.advBody then
        E.advBody.Visible = E.advancedOpen
    end
    if E.advToggleBtn then
        local prefix = E.advancedOpen and "-  " or "+  "
        E.advToggleBtn.Text = prefix .. "Advanced / Debug (Power-User Weights, Unit Study, Live Logs & Changelog)"
    end
    if E.advancedOpen and not wasOpen then
        pcall(GUI.update, true)
    end
    return E.advancedOpen
end

function GUI.setAccent(accentId)
    local E = GUI._engine
    if not E or E.destroyed then return false end
    for _, preset in ipairs(GUI.ACCENT_PRESETS) do
        if preset.id == accentId then
            E.prefs.accentId = preset.id
            E.accentColor = preset.color
            E.accentSoft = preset.soft
            GUI.PALETTE.accent = preset.color
            GUI.PALETTE.accentSoft = preset.soft
            GUI.COL.accent = preset.color
            uiSavePrefs(E.prefs)
            E.refreshAccentBindings()
            if E.paintSwatches then E.paintSwatches() end
            return true
        end
    end
    return false
end

function GUI.setScale(scaleVal)
    local E = GUI._engine
    if not E or E.destroyed then return 1.0 end
    E.prefs.uiScale = uiClamp(tonumber(scaleVal) or 1.0, 0.75, 1.25)
    uiSavePrefs(E.prefs)
    E.updateScale()
    return E.prefs.uiScale
end

function GUI.setOpacity(opacityVal)
    local E = GUI._engine
    if not E or E.destroyed then return 0.96 end
    E.prefs.uiOpacity = uiClamp(tonumber(opacityVal) or 0.96, 0.70, 1.0)
    uiSavePrefs(E.prefs)
    E.updateOpacity()
    return E.prefs.uiOpacity
end

function GUI.setToggleKey(keyName)
    local E = GUI._engine
    if not E or E.destroyed then return "RightShift" end
    local k = tostring(keyName or "RightShift")
    if E.keybindHandle then
        E.keybindHandle.Set(k)
    else
        E.prefs.toggleKey = k
        if E.headerKeyBadge then E.headerKeyBadge.Text = k end
        uiSavePrefs(E.prefs)
    end
    return k
end

function GUI.applyPreset(presetId)
    local target = nil
    for _, pr in ipairs(GUI.PRESETS) do
        if pr.id == presetId then
            target = pr
            break
        end
    end
    if not target then
        return false
    end
    if target.clearOnlyFlags then
        for _, fk in ipairs(GUI.ONLY_FLAGS) do
            uiSetBase(fk, false, true)
        end
    end
    for k, v in pairs(target.settings) do
        uiSetBase(k, v, true)
    end
    if App and App.saveSoon then pcall(App.saveSoon) end
    if Modes then Modes.lastScored = nil end
    if FarmHub and FarmHub.quietFx then pcall(FarmHub.quietFx) end
    if GUI.gfxApply then pcall(GUI.gfxApply, true) end
    GUI.lowCpuAt = nil
    pcall(GUI.farmSync)
    if App and App.notify then
        pcall(App.notify, "Preset Applied: " .. target.name, target.desc, target.tone or "success")
    end
    return true
end

function GUI.getState()
    local E = GUI._engine
    if not E then
        return { built = false }
    end
    return {
        built = true,
        destroyed = E.destroyed == true,
        screenGuiAlive = (E.screenGui ~= nil) and (not E.destroyed),
        activeTab = E.activeTab,
        activeSubPill = E.activeSubPill[E.activeTab],
        searchQuery = E.searchQuery,
        minimized = E.minimized,
        hidden = E.hidden,
        advancedOpen = E.advancedOpen,
        activeAiCount = uiCountActiveAI(),
        running = uiIsRunning(),
        controlCount = #E.searchItems,
        connectionCount = #E.conns,
        accentId = E.prefs.accentId,
        uiScale = E.prefs.uiScale,
        uiOpacity = E.prefs.uiOpacity,
        toggleKey = E.prefs.toggleKey
    }
end

-- ============================================================================
-- Section E: External Farm Sync, Progress & 1s/3s Live Telemetry Loop
-- ============================================================================
function GUI.farmProgress()
    local live = GUI.LIVE
    if not live then return end
    local ok, text = pcall(Farming.progressText)
    if not ok then return end
    if live.farmQuick then pcall(live.farmQuick.Set, text) end
    if live.farmRoutine then pcall(live.farmRoutine.Set, text) end
end

function GUI.farmSync()
    local E = GUI._engine
    local ui = GUI.UI or {}
    if not E or E.destroyed then
        return
    end

    -- 1. Sync Start Mode Selector Pills
    for _, spec in ipairs(GUI.farmModeSpecs or {}) do
        local handle = ui[spec.only .. "Mode"]
        if handle then
            local on = (uiGetBase(spec.only) == true)
            for _, key in ipairs(spec.enable or {}) do
                if uiGetBase(key) == true then
                    on = true
                end
            end
            pcall(handle.Set, on, true)
        end
    end

    -- 2. Sync all Config-bound controls silently from Farming.baseValue(key)
    for cfgKey, handles in pairs(E.configHandles or {}) do
        local bv = uiGetBase(cfgKey)
        if bv ~= nil then
            for _, h in ipairs(handles) do
                pcall(h.Set, bv, true)
            end
        end
    end

    -- 3. Sync inverted unitsPaused handle
    if ui.unitsPlay then
        pcall(ui.unitsPlay.Set, not (uiGetBase("unitsPaused") == true), true)
    end

    -- 4. Sync Jobs Between Runs multi-pill group
    if E.jobsMultiHandle then
        local activeJobs = {}
        local jobKeys = { "team", "smartEvolve", "goals", "trainTakedowns", "teamFuse", "autoSummon", "snipeOn", "rewards", "codes", "goldShop" }
        for _, jk in ipairs(jobKeys) do
            if uiGetBase(jk) == true then
                table.insert(activeJobs, jk)
            end
        end
        pcall(E.jobsMultiHandle.Set, activeJobs, true)
    end

    -- 5. Sync Hero Start/Stop visuals, Mini-HUD, and Queue progress
    if E.syncHeroVisuals then
        pcall(E.syncHeroVisuals)
    end
    GUI.farmProgress()
end

function GUI.update(forceAll)
    local E = GUI._engine
    if not E or E.destroyed then
        return
    end
    local full = (forceAll == true) or (GUI._forceFullUpdate == true) or (E.searchQuery ~= "")
    if not full and E.hidden then
        return
    end

    local now = Utils.now()
    if not full and (Config.gfxLowCpu or Config.gfxLow) and GUI.lowCpuAt and (now - GUI.lowCpuAt < 3) then
        return
    end
    GUI.lowCpuAt = now
    GUI._forceFullUpdate = false

    local col = GUI.COL
    local live = GUI.LIVE
    local running = uiIsRunning()
    local aiCnt = uiCountActiveAI()

    if E.syncHeroVisuals then E.syncHeroVisuals() end

    -- 1. Always update Top Status Strip & Mini-HUD (with property dirty-checking)
    local waveSummary = "Lobby"
    if App.where == "match" and Match and Match.ld then
        local mapName = Modes.levelName(Match.ld.id or "?")
        local w = Match.wave()
        local tot = tonumber(Match.total) or 0
        if tot > 0 then
            waveSummary = string.format("%s · W%d/%d", mapName, w, tot)
        else
            waveSummary = string.format("%s · W%d", mapName, w)
        end
    end
    local wins = (Brain.totals and Brain.totals.wins) or 0
    local losses = (Brain.totals and Brain.totals.losses) or 0
    local sesDur = Brain.sessionStart and (os.time() - Brain.sessionStart) or 0
    local gemsPerHr = Utils.qol_perHour(Brain.sessionGems or (Brain.totals and Brain.totals.gems) or 0, sesDur)

    if E.statusTiles then
        if E.statusTiles.wave and E._lastTileWave ~= waveSummary then
            E._lastTileWave = waveSummary
            E.statusTiles.wave.Text = waveSummary
        end
        local recStr = string.format("%dW / %dL", wins, losses)
        if E.statusTiles.record and E._lastTileRecord ~= recStr then
            E._lastTileRecord = recStr
            E.statusTiles.record.Text = recStr
        end
        if E.statusTiles.session and E._lastTileSession ~= gemsPerHr then
            E._lastTileSession = gemsPerHr
            E.statusTiles.session.Text = gemsPerHr
        end
    end
    if E.miniStatusLbl then
        local miniStr = string.format("%s | %dW/%dL | %d/7 AI", waveSummary, wins, losses, aiCnt)
        if E._lastMiniStatus ~= miniStr then
            E._lastMiniStatus = miniStr
            E.miniStatusLbl.Text = miniStr
        end
    end

    -- Fast-exit if minimized to Mini-HUD (main window is not visible)
    if not full and E.minimized then
        return
    end

    local tab = E.activeTab
    local subPill = E.activeSubPill[tab]

    -- ========================================================================
    -- TAB 1: START
    -- ========================================================================
    if full or tab == "start" then
        local prof = Core.prof and Core.prof() or {}
        local statusLine
        if not Config.master then
            statusLine = "Paused: Auto Farm is off"
        elseif Brain.holdLobby then
            if App.where == "match" then
                statusLine = "Finishing this match, then holding in lobby"
            else
                statusLine = "Stopped: " .. tostring(Brain.holdLobby.why or "holding in lobby")
            end
        elseif App.where == "match" then
            statusLine = Status.Economy or Status.Match or "Playing current match"
        else
            statusLine = Status.Mode or "Planning next run in lobby"
        end
        if live.homeStatus then live.homeStatus.Set(GUI.shortLine(statusLine, 120)) end
        if live.farmPickStatus and Farming and Farming.pickText then
            local okP, pTxt = pcall(Farming.pickText)
            if okP then live.farmPickStatus.Set(pTxt) end
        end

        -- 2. Now Card (Match / Lobby)
        if GUI.nowCard then
            if not Config.master then
                GUI.nowCard.Set({ title = "Paused", text = "Press START AUTO FARM to resume.", sub = "", tag = "PAUSED", tagColor = col.orange, progress = false })
            elseif App.where == "match" and Match.ld then
                local lvlTitle = Modes.levelName(Match.ld.id or "?") .. (Match.ld._difficulty and (" (" .. Match.ld._difficulty .. ")") or "")
                local pressure = Match.pressure or 0
                local depth = Match.depth or {}
                local covClamp = (depth.units or 0) > 0 and Utils.clamp(depth.covEnd or 0.6, 0.1, 1) or 0.6
                local isDanger = depth.leak or pressure >= math.min(Config.dangerReach, covClamp * 0.9)
                local isPress = pressure >= math.min(Config.safeReach, covClamp * 0.75)
                local tagTxt = depth.leak and "LEAK" or (isDanger and "DANGER" or (isPress and "PRESSURE" or "SAFE"))
                local tagC = isDanger and col.red or (isPress and col.orange or col.green)
                local prog = (Match.total or 0) > 0 and (Match.wave() / Match.total) or false
                GUI.nowCard.Set({
                    title = lvlTitle,
                    text = tostring(Status.Economy or "Playing match"),
                    sub = Match.etaText() .. string.format("Wave %d/%d · ¥%s · %d enemies · front %d%% · reach %d%%", Match.wave(), Match.total or 0, Utils.fmt(Match.money()), #(Match.enemies or {}), math.floor(pressure * 100), math.floor(((depth.units or 0) > 0 and depth.covEnd or 0) * 100)),
                    tag = tagTxt,
                    tagColor = tagC,
                    progress = prog,
                    color = col.accent
                })
            else
                GUI.nowCard.Set({
                    title = "In Lobby",
                    text = tostring(Status.Mode or "Evaluating next best stage"),
                    sub = string.format("Location: Lobby · Active AI: %d/7 · Copy %s", aiCnt, tostring(App.loadId or "1")),
                    tag = running and "ACTIVE" or "IDLE",
                    tagColor = running and col.green or col.orange,
                    progress = false
                })
            end
        end

        -- 3. Sim Card & Up Next Card
        if GUI.simCard then
            local okSim, sv = pcall(GUI.simView, col)
            if okSim and type(sv) == "table" then
                GUI.simCard.Set(sv)
            end
        end
        if GUI.nextCard then
            local topM = Modes.lastScored and Modes.lastScored[1]
            local secM = Modes.lastScored and Modes.lastScored[2]
            local nextTitle, nextWhy = GUI.upNext(topM, secM)
            local lr = Brain.lastResult
            local subStr = nextWhy or ""
            if type(lr) == "table" then
                subStr = string.format("Last run: %s (%s) · +%s gems%s", lr.won and "WON" or "LOST", tostring(lr.label or "?"), Utils.fmt(lr.gems or 0), subStr ~= "" and (" · " .. subStr) or "")
            end
            GUI.nextCard.Set({ title = "Up Next: " .. tostring(nextTitle), text = subStr, tag = topM and string.format("%.0f%%", (topM.p or 0) * 100) or "", tagColor = col.accent })
        end

        -- 4. Currencies & At A Glance + Home Subsystems Summary
        if GUI.goals then
            local goldAmt = prof.gold_amount or prof.gold or 0
            local gemAmt = prof.gem_amount or prof.gems or 0
            local pearlAmt = (prof.resources and prof.resources.SummerPearls) or prof.summer_pearls or prof.event_currency or 0
            local gRows = GUI._goalsRowsBuf
            if not gRows then
                gRows = { { "Gold", "" }, { "Gems", "" }, { "Summer Pearls", "" }, { "Record", "" } }
                GUI._goalsRowsBuf = gRows
            end
            gRows[1][2] = Utils.fmt(goldAmt)
            gRows[2][2] = Utils.fmt(gemAmt) .. " (" .. gemsPerHr .. ")"
            gRows[3][2] = Utils.fmt(pearlAmt)
            gRows[4][2] = string.format("%dW / %dL (%d matches)", wins, losses, (Brain.totals and Brain.totals.matches) or 0)
            GUI.goals.SetRows(gRows)
        end
        if GUI.homeKv then
            local okH, hMap = pcall(GUI.homeRows)
            if okH and type(hMap) == "table" then
                local rows = GUI._homeRowsBuf
                if not rows then
                    rows = {}
                    for idx, k in ipairs(GUI.HOME_KEYS) do
                        rows[idx] = { k, "" }
                    end
                    GUI._homeRowsBuf = rows
                end
                for idx, k in ipairs(GUI.HOME_KEYS) do
                    rows[idx][2] = tostring(hMap[k] or "...")
                end
                GUI.homeKv.SetRows(rows)
            end
        end
    end

    -- ========================================================================
    -- TAB 2: MODES
    -- ========================================================================
    if full or tab == "modes" then
        if full or subPill == "story_legend" then
            if live.only then
                local txt = (Modes and Modes.onlyOn and Modes.onlyOn()) and ("Locked to: " .. Modes.onlyText()) or "Smart multi-mode selection active"
                live.only.Set(txt)
            end
        end
        if full or subPill == "event_summer" then
            if live.hunt and Hunt and Hunt.text then pcall(function() live.hunt.Set(Hunt.text()) end) end
            if live.fh and Match and Match.fhText then pcall(function() live.fh.Set(Match.fhText()) end) end
            if live.skins and Hunt and Hunt.skinText then pcall(function() live.skins.Set(Hunt.skinText()) end) end
        end
        if full or subPill == "dungeon" then
            if live.dungeon and Dungeon and Dungeon.text then pcall(function() live.dungeon.Set(Dungeon.text()) end) end
        end
        if full or subPill == "lobby_retry" then
            if GUI.refreshOwnTeam then pcall(GUI.refreshOwnTeam, false) end
            if GUI.rank and Modes and type(Modes.lastScored) == "table" then
                local rRows = {}
                for i = 1, math.min(6, #Modes.lastScored) do
                    local m = Modes.lastScored[i]
                    table.insert(rRows, { tostring(i) .. ". " .. tostring(m.label), string.format("%.0f%% · ~%.0f g/m", (m.p or 0) * 100, m.score or 0) })
                end
                GUI.rank.SetRows(rRows)
            end
            if GUI.records and type(Brain.modes) == "table" then
                local recRows = {}
                for k, v in pairs(Brain.modes) do
                    if type(v) == "table" and ((v.w or 0) + (v.l or 0) > 0) then
                        table.insert(recRows, { GUI.keyName(k), string.format("%dW / %dL", v.w or 0, v.l or 0) })
                        if #recRows >= 8 then break end
                    end
                end
                GUI.records.SetRows(recRows)
            end
        end
    end

    -- ========================================================================
    -- TAB 3: BATTLE & TEAM
    -- ========================================================================
    if full or tab == "battle_team" then
        if full or subPill == "combat_buffs" then
            if GUI.buffInfo then
                local bRows = {}
                if App.where == "match" and Match and Match.buffText then
                    local okB, bTxt = pcall(Match.buffText)
                    table.insert(bRows, { "Match Buffs", okB and tostring(bTxt) or "..." })
                elseif Units and Units.lobbyBuffCheck then
                    local okB, bTxt = pcall(Units.lobbyBuffCheck)
                    table.insert(bRows, { "Lobby Check", okB and tostring(bTxt) or "..." })
                end
                table.insert(bRows, { "Type", tostring(Config.autoBuffKind or "auto") })
                GUI.buffInfo.SetRows(bRows)
            end
        end

        if full or subPill == "economy" then
            if GUI.econCard then
                if App.where == "match" and Match and Match.ld then
                    GUI.econCard.Set({
                        title = "Yen: ¥" .. Utils.fmt(Match.money()),
                        text = tostring(Status.Economy or "Managing upgrades"),
                        sub = string.format("EconomyNN: %s · Priority: %s", Config.aiEconomy ~= false and "ON" or "OFF", tostring(Config.upgradeOrder or "Smart")),
                        tag = Config.aiEconomy ~= false and "AI ON" or "RULES",
                        tagColor = Config.aiEconomy ~= false and col.green or col.accent
                    })
                else
                    GUI.econCard.Set({ title = "Lobby (No Active Match)", text = "Economy AI activates automatically inside matches.", tag = "IDLE", tagColor = col.sub })
                end
            end
        end

        if full or subPill == "team_planner" then
            if GUI.plan then
                local okPl, pv = pcall(GUI.planView, col)
                if okPl and type(pv) == "table" then
                    local pRows = {
                        { "State", tostring(pv.state or "Ready") },
                        { "Next Step", tostring(pv["Next step"] or "..."), color = pv.stepColor },
                        { "Map & Mode", tostring(pv["Map & mode"] or "...") },
                        { "Current Team", tostring(pv["Current team"] or "...") }
                    }
                    if pv["Planned team"] then
                        table.insert(pRows, { "Planned Team", tostring(pv["Planned team"]) })
                    end
                    GUI.plan.SetRows(pRows)
                end
            end
            if GUI.sim then
                local sRows = {
                    { "Simulator", Config.sim and "Enabled" or "Disabled" },
                    { "TeamNN", Config.aiTeam ~= false and "Enabled (6th NN)" or "Disabled" },
                    { "CardNN", Config.aiCards ~= false and "Enabled (7th NN)" or "Disabled" },
                    { "Auto-Equip", Config.autoTeam and "Enabled" or "Disabled" }
                }
                GUI.sim.SetRows(sRows)
            end
            if GUI.team then
                local eq = Units and Units.equipped and Units.equipped() or {}
                local tRows = {}
                for i, u in ipairs(eq) do
                    table.insert(tRows, { "Slot " .. tostring(i), Units.name(u.id or u.unit_id) .. " (" .. tostring(Units.roleName(u.id or u.unit_id)) .. ")" })
                end
                GUI.team.SetRows(tRows)
            end
            if live.teamNext and Strategy and Strategy.text then pcall(function() live.teamNext.Set(Strategy.text()) end) end
            if GUI.core and Strategy and Strategy.rows then
                local okC, cRows = pcall(Strategy.rows)
                if okC and type(cRows) == "table" then
                    local out = {}
                    for _, r in ipairs(cRows) do
                        if type(r) == "table" then
                            table.insert(out, { tostring(r[1] or r.name or ""), tostring(r[2] or r.text or "") })
                        end
                    end
                    GUI.core.SetRows(out)
                end
            end
        end

        if full or subPill == "goals_training" then
            if live.focus then pcall(function() live.focus.Set(FarmHub.focusText()) end) end
            if GUI.readyLabel then
                local readyNames = {}
                for _, g in ipairs(Brain.goals or {}) do
                    if g.ready then table.insert(readyNames, Units.name(g.from)) end
                end
                GUI.readyLabel.Set(#readyNames > 0 and table.concat(readyNames, ", ") or "None ready yet")
            end
            if GUI.path then
                local pRows = {}
                for i = 1, math.min(5, #(Brain.goalsTop or {})) do
                    local g = Brain.goalsTop[i]
                    table.insert(pRows, { tostring(i) .. ". " .. Units.name(g.from), "-> " .. Units.name(g.to) .. (g.ready and " (READY)" or "") })
                end
                GUI.path.SetRows(pRows)
            end
            if live.train and Training and Training.text then pcall(function() live.train.Set(Training.text()) end) end
            if live.lb and Adventure and Adventure.lbText then pcall(function() live.lb.Set(Adventure.lbText()) end) end
        end
    end

    -- ========================================================================
    -- TAB 4: ACCOUNT & REWARDS
    -- ========================================================================
    if full or tab == "account_rewards" then
        if full or subPill == "rewards_shop" then
            if live.community and Adventure and Adventure.communityText then pcall(function() live.community.Set(Adventure.communityText()) end) end
        end
        if full or subPill == "summons_snipe" then
            if live.snipe and FarmHub and FarmHub.snipeText then pcall(function() live.snipe.Set(FarmHub.snipeText()) end) end
            if live.summonPick and FarmHub and FarmHub.summonText then pcall(function() live.summonPick.Set(FarmHub.summonText()) end) end
        end
        if full or subPill == "inventory_fusion" then
            if GUI.lbCard then
                local okLb, lbData = pcall(GUI.lbStatus)
                if okLb and type(lbData) == "table" then
                    GUI.lbCard.Set(lbData)
                end
            end
            if live.fusePick and FarmHub and FarmHub.fuseText then pcall(function() live.fusePick.Set(FarmHub.fuseText()) end) end
            if live.fuseXpPick and FarmHub and FarmHub.fuseXpText then pcall(function() live.fuseXpPick.Set(FarmHub.fuseXpText()) end) end
            if GUI.fodder and Config.fuseUnit ~= "" and FarmHub and FarmHub.fodderRows then
                local session = Core.session and Core.session()
                local unitObj = session and session.collection:get_unit_by_uuid(Config.fuseUnit)
                if unitObj then
                    local sig = tostring(Config.fuseUnit) .. "|" .. tostring(now > (GUI._fodderAt or 0) + 15 and math.floor(now / 15) or math.floor((GUI._fodderAt or 0) / 15))
                    if sig ~= GUI.fodderSig then
                        GUI.fodderSig = sig
                        GUI._fodderAt = now
                        local okFr, rows = pcall(FarmHub.fodderRows, unitObj)
                        if okFr and type(rows) == "table" then
                            GUI.fodder.Refresh(rows)
                        end
                    end
                end
            end
        end
        if full or subPill == "discord_alerts" then
            if live.discord and Discord and Discord.statusText then pcall(function() live.discord.Set(Discord.statusText()) end) end
        end
    end

    -- ========================================================================
    -- TAB 5: SETTINGS (+ Advanced / Debug Drawer)
    -- ========================================================================
    if full or tab == "settings" then
        if live.gfxPerf then
            local gOk, gTxt = pcall(GUI.gfxText)
            local pOk, pTxt = pcall(function() return Perf and Perf.text and Perf.text() or "" end)
            live.gfxPerf.Set((gOk and tostring(gTxt) or "") .. ((pOk and pTxt ~= "") and ("\n" .. tostring(pTxt)) or ""))
        end

        if full or E.advancedOpen then
            if live.study and FarmHub and FarmHub.studyText then pcall(function() live.study.Set(FarmHub.studyText()) end) end
            if GUI.systems then
                local sysRows = GUI._sysRowsBuf
                if not sysRows then
                    sysRows = {}
                    for idx, name in ipairs(GUI.SYSTEMS) do
                        sysRows[idx] = { name, "idle" }
                    end
                    GUI._sysRowsBuf = sysRows
                end
                for idx, name in ipairs(GUI.SYSTEMS) do
                    sysRows[idx][2] = GUI.shortLine(tostring(Status[name] or "idle"), 64)
                end
                GUI.systems.SetRows(sysRows)
            end
            if live.totals then
                local spOk, spTxt = pcall(function() return Spending and Spending.text and Spending.text() or "" end)
                local totalsStr = string.format(
                    "Matches %d · Wins %d · Losses %d · Gems %s · Event Coins %s",
                    (Brain.totals and Brain.totals.matches) or 0,
                    wins,
                    losses,
                    Utils.fmt((Brain.totals and Brain.totals.gems) or 0),
                    Utils.fmt((Brain.totals and Brain.totals.coins) or 0)
                )
                if spOk and type(spTxt) == "string" and spTxt ~= "" then
                    totalsStr = totalsStr .. "\n" .. spTxt
                end
                live.totals.Set(totalsStr)
            end
        end
    end

    -- ========================================================================
    -- Dynamic Dropdown Refresh (Scoped to visible tab/sub-pill or initial build)
    -- ========================================================================
    local initLists = (GUI.focusSig == nil)
    if initLists or FarmHub.every("guiDynLists", 15) then
        if initLists or full or (tab == "battle_team" and subPill == "goals_training") then
            if GUI.UI.focusPick then
                local opts = GUI.focusOptions()
                local sig = GUI.sigOf(opts)
                if sig ~= GUI.focusSig then
                    GUI.focusSig = sig
                    pcall(GUI.UI.focusPick.Refresh, opts, GUI.focusNow())
                end
            end
        end
        if initLists or full or (tab == "account_rewards" and subPill == "summons_snipe") then
            if GUI.UI.snipeUnitPick then
                local opts = GUI.snipeOptions()
                local sig = GUI.sigOf(opts)
                if sig ~= GUI.listSig.snipeUnit then
                    GUI.listBuilt("snipeUnit", opts)
                    pcall(GUI.UI.snipeUnitPick.Refresh, opts, Config.snipeUnit)
                end
            end
            if GUI.UI.summonBannerPick then
                local opts = GUI.bannerOptions()
                local sig = GUI.sigOf(opts)
                if sig ~= GUI.listSig.summonBanner then
                    GUI.listBuilt("summonBanner", opts)
                    pcall(GUI.UI.summonBannerPick.Refresh, opts, Config.summonBanner)
                end
            end
        end
        if initLists or full or (tab == "account_rewards" and subPill == "inventory_fusion") then
            if GUI.UI.fuseUnitPick then
                local opts = GUI.lbTargetOptions()
                local sig = GUI.sigOf(opts)
                if sig ~= GUI.listSig.fuseUnit then
                    GUI.listBuilt("fuseUnit", opts)
                    pcall(GUI.UI.fuseUnitPick.Refresh, opts, Config.fuseUnit)
                end
            end
            if GUI.UI.fuseXpUnitPick then
                local opts = GUI.unitOptions(Config.fuseXpUnit)
                local sig = GUI.sigOf(opts)
                if sig ~= GUI.listSig.fuseXpUnit then
                    GUI.listBuilt("fuseXpUnit", opts)
                    pcall(GUI.UI.fuseXpUnitPick.Refresh, opts, Config.fuseXpUnit)
                end
            end
        end
        if initLists or full or (tab == "settings" and E.advancedOpen) then
            if GUI.UI.studyUnitPick and GUI.lists.studyUnit then
                local okS, opts = pcall(GUI.lists.studyUnit)
                if okS and type(opts) == "table" then
                    local sig = GUI.sigOf(opts)
                    if sig ~= GUI.listSig.studyUnit then
                        GUI.listBuilt("studyUnit", opts)
                        pcall(GUI.UI.studyUnitPick.Refresh, opts, Config.studyUnit)
                    end
                end
            end
        end
        if initLists or full or (tab == "modes" and subPill == "lobby_retry") then
            for _, form in ipairs(GUI.farmForms or {}) do
                pcall(form.refreshMaps, false)
            end
        end
    end
end

function GUI.loop()
    while App.alive do
        pcall(GUI.update)
        task.wait(1)
    end
end
table.insert(App.conns, LocalPlayer.Idled:Connect(function()
