function App.cleanup()
    pcall(GUI.gfxOff)
    for _, conn in ipairs(App.conns) do
        pcall(function()
            conn:Disconnect()
        end)
    end
    pcall(function()
        GUI.Win:Destroy()
    end)
    pcall(function()
        if Match.probe then
            Match.probe:Destroy()
        end
    end)
    pcall(function()
        if Match.bounds then
            Match.bounds:Destroy()
        end
    end)
    pcall(function()
        if Config.matchLogger == true and AI and AI.flushMatchLog then
            AI.flushMatchLog({ won = false, reason = "cleanup" })
        end
    end)
    pcall(function()
        if AI and AI.resetCache then
            AI.resetCache()
        end
    end)
end

function App.unload()
    App.alive = false
    App.saveNow()
    pcall(FarmHub.quietFx, true)
    App.cleanup()
    _G.AA_SF = nil
end

function App.restart()
    local loadstring2, loadstring22 = loadstring(readfile(Core.SELF), "=awaqwaa_script_awaqwaa_airflow")
    assert(loadstring2, loadstring22)
    App.unload()
    loadstring2()
end
